INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H101', 'C04', 'Indicated', 'Primary', 'Cold-damp-relaxed, boggy phlegmatic with passive discharge.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H101', 'C05', 'Aggravates', 'Secondary', 'Drying and depleting to the thin, cold, depleted (Vata-like) type.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H101', 'C03', 'Aggravates', 'Secondary', 'Cold-dry melancholic worsened by further drying astringency.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H101', 'D03', 'Primary', 'Astringent and drying reduces damp, heavy Kapha.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
