INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H101', 'TCM13', 'Secondary', 'Premature astringing in Wind-Cold exterior may trap the pathogen.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quercus alba (U.S.P.), White Oak. https://www.henriettes-herb.com/eclectic/kings/quercus.html", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Quercus; Cook, The Physio-Medical Dispensatory (1869) - Quercus alba; Grieve, A Modern Herbal (1931) - Oak; NCCIH herb safety guidance; WebMD White Oak monograph; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI203', 'H101', 'pregnancy', 'Pregnancy (internal use)', 'moderate', 'High tannin content and lack of established safety data; astringent tannins reduce nutrient absorption.', 'Avoid internal use in pregnancy. Brief external sitz-bath use for hemorrhoids on intact skin only, under practitioner guidance.', 'WebMD White Oak monograph; Healthline, Oak Bark (2023); NCCIH herb safety guidance.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI204', 'H101', 'breastfeeding', 'Breastfeeding (internal use)', 'moderate', 'No species-specific lactation data; astringent tannins may theoretically reduce secretions.', 'Avoid internal use while breastfeeding.', 'WebMD White Oak monograph; Healthline, Oak Bark.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI205', 'H101', 'drug_interaction', 'Oral iron and mineral supplements', 'moderate', 'Tannins chelate iron and divalent minerals, reducing their absorption.', 'Separate oral oak preparations from iron and mineral supplements (and mineral-dependent drugs) by at least 2 hours.', 'Healthline, Oak Bark; Brinker, Herb Contraindications & Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI206', 'H101', 'drug_interaction', 'Alkaloidal and protein/peptide oral drugs', 'moderate', 'Tannins precipitate alkaloids and proteins, lowering oral bioavailability.', 'Separate oral administration by at least 2 hours; do not co-decoct with alkaloidal medicines.', 'Brinker, Herb Contraindications & Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI207', 'H101', 'condition', 'Kidney disease / renal impairment', 'moderate', 'High-dose or prolonged tannin intake associated with nephrotoxicity in animal models (rat kidney damage at ~33 mg/kg extract).', 'Avoid internal use with impaired kidney function; keep any oral use brief (3 to 4 days) and modest (<= ~3 g/day).', 'Healthline, Oak Bark; WebMD White Oak monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI208', 'H101', 'condition', 'Liver disease', 'moderate', 'Prolonged high tannin loads may burden hepatic function.', 'Avoid prolonged internal use with hepatic impairment.', 'WebMD White Oak monograph; Healthline, Oak Bark.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI209', 'H101', 'other', 'Broken/damaged skin, eczema, extensive skin damage', 'moderate', 'Astringent tannins irritate and are absorbed through damaged skin and can worsen eczema; likely unsafe on damaged skin.', 'Apply only to intact skin; limit topical use to 2 to 3 weeks.', 'WebMD White Oak monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI210', 'H101', 'other', 'Chronic or high-dose internal use', 'moderate', 'Chronic tannin intake impairs nutrient absorption and may cause constipation and organ burden.', 'Limit internal use to 3 to 4 days at <= ~3 g dried bark/day; not for long-term use.', 'WebMD White Oak monograph; Healthline, Oak Bark.');
