INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H102', 'C06', 'Indicated', 'Primary', 'Cools and tones hot, robust, full-blooded (Pitta-like) types', '{"title": "Egyptian Herbal Monograph, Vol. 1 - Traditional Wild Medicinal Plants (Egyptian Drug Authority, 2023): Hibiscus sabdariffa (Karkade), the modern regulatory codification of the long-standing Egyptian karkade tradition (adjuvant for hypertens", "locator": "Egyptian Herbal Monograph, Vol. 1 - Traditional Wild Medicinal Plants (Egyptian Drug Authority, 2023): Hibiscus sabdariffa (Karkade), the modern regulatory codification of the long-standing Egyptian karkade tradition (adjuvant for hypertens", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Da-Costa-Rocha I, Bonnlaender B, Sievers H, Pischel I, Heinrich M. Hibiscus sabdariffa L.: a phytochemical and pharmacological review. Food Chemistry 2014;165:424-443. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013). Mills", "locator": "Da-Costa-Rocha I, Bonnlaender B, Sievers H, Pischel I, Heinrich M. Hibiscus sabdariffa L.: a phytochemical and pharmacological review. Food Chemistry 2014;165:424-443. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013). Mills", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
