INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI211', 'H102', 'pregnancy', 'Pregnancy (medicinal or therapeutic doses)', 'moderate', 'Traditional emmenagogue reputation; animal studies report anti-implantation, anti-fertility, and developmental effects. The calyx also lowers blood pressure. Human safety data are lacking.', 'Avoid medicinal-strength teas and extracts during pregnancy. Culinary flavoring amounts and the occasional dilute beverage have a long dietary history, but do not use therapeutically.', 'Egyptian Herbal Monograph (EDA 2023); NCCIH; animal reproductive-toxicity reports');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI212', 'H102', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'No data on excretion of hibiscus components into breast milk or on infant safety; possible allergic cross-reactivity within the Malvaceae.', 'Culinary and dilute-beverage amounts likely compatible; reserve medicinal-strength preparations until data exist.', 'LactMed (NCBI Bookshelf NBK501882); Egyptian Herbal Monograph (EDA 2023)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI213', 'H102', 'drug_interaction', 'Antihypertensive drugs (ACE inhibitors, ARBs, diuretics, etc.)', 'moderate', 'Hibiscus reliably lowers blood pressure (ACE-inhibitory, mild diuretic); additive effect can cause hypotension.', 'Monitor blood pressure; adjust medication under supervision. Hibiscus is an adjuvant, not a replacement, for prescribed therapy.', 'Egyptian Herbal Monograph (EDA 2023); RxList/MedlinePlus; antihypertensive RCTs');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI214', 'H102', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Hibiscus can modestly lower blood glucose and may alter drug effect; additive hypoglycemia is possible.', 'Monitor blood glucose; watch around dose changes and surgery.', 'Egyptian Herbal Monograph (EDA 2023); RxList/MedlinePlus');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI215', 'H102', 'drug_interaction', 'Chloroquine (antimalarial)', 'moderate', 'Hibiscus beverage reduces chloroquine absorption and plasma concentration, lowering efficacy (human-volunteer pharmacokinetic study).', 'Do not co-administer with hibiscus tea; separate dosing well or avoid during antimalarial therapy.', 'Egyptian Herbal Monograph (EDA 2023); human pharmacokinetic study');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI216', 'H102', 'drug_interaction', 'Acetaminophen (paracetamol) and diclofenac', 'low', 'Hibiscus alters analgesic pharmacokinetics: it speeds acetaminophen elimination and lowers its peak, while reducing diclofenac elimination and raising its plasma level (human-volunteer studies).', 'Be aware of altered analgesic response at beverage strength; separate timing if effect matters clinically.', 'Human pharmacokinetic (Zobo-drink) studies; Da-Costa-Rocha et al. 2014');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI217', 'H102', 'drug_interaction', 'Losartan and other CYP2C9/CYP3A4/CYP2D6 substrates', 'moderate', 'Hibiscus is a weak inhibitor of CYP2C9, CYP2D6, and CYP3A4; animal studies show altered losartan pharmacokinetics and pharmacodynamics.', 'Use caution with narrow-therapeutic-index substrates; monitor drug effect and blood pressure with losartan.', 'Animal pharmacokinetic studies; Da-Costa-Rocha et al. 2014; AHPA BSH');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI218', 'H102', 'condition', 'Hypotension and peri-operative period', 'moderate', 'Blood-pressure and blood-glucose lowering can be problematic in already-low BP and around surgery.', 'Avoid therapeutic doses in hypotension; discontinue at least 2 weeks before scheduled surgery.', 'Egyptian Herbal Monograph (EDA 2023); RxList/MedlinePlus');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H102', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Egyptian Herbal Monograph, Vol. 1 - Traditional Wild Medicinal Plants (Egyptian Drug Authority, 2023): Hibiscus sabdariffa (Karkade), the modern regulatory codification of the long-standing Egyptian karkade tradition (adjuvant for hypertens", "locator": "Egyptian Herbal Monograph, Vol. 1 - Traditional Wild Medicinal Plants (Egyptian Drug Authority, 2023): Hibiscus sabdariffa (Karkade), the modern regulatory codification of the long-standing Egyptian karkade tradition (adjuvant for hypertens", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Da-Costa-Rocha I, Bonnlaender B, Sievers H, Pischel I, Heinrich M. Hibiscus sabdariffa L.: a phytochemical and pharmacological review. Food Chemistry 2014;165:424-443. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013). Mills", "locator": "Da-Costa-Rocha I, Bonnlaender B, Sievers H, Pischel I, Heinrich M. Hibiscus sabdariffa L.: a phytochemical and pharmacological review. Food Chemistry 2014;165:424-443. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013). Mills", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
