INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H103', 'C05', 'Indicated', 'Primary', 'Moistens and rebuilds thin, dry, depleted Vata-like types', '{"title": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "locator": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "locator": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
