INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H103', 'TCM03', 'Secondary', 'Avoid in Spleen Qi deficiency with damp-cold / loose stools', '{"title": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "locator": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "locator": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI219', 'H103', 'pregnancy', 'Pregnancy (concentrated or therapeutic doses; first trimester)', 'moderate', 'Demonstrated phytoestrogenic (estrogen-receptor-binding) activity and limited rigorous human data during organogenesis, despite a long traditional record of use as a pregnancy tonic.', 'Avoid concentrated or therapeutic doses in the first trimester; if used in later pregnancy, only under qualified supervision. Food and customary tonic amounts have traditional use.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); NIH LactMed; in-vitro ER-alpha binding study (PMID 30580607)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI220', 'H103', 'condition', 'Estrogen-sensitive conditions (breast, uterine, ovarian cancer; endometriosis; estrogen-driven fibroids)', 'moderate', 'Shatavarins bind estrogen receptors (ER-alpha) in vitro; theoretical potential to stimulate estrogen-sensitive tissue.', 'Avoid, or use only under oncology / specialist supervision, in hormone-sensitive cancers and estrogen-driven conditions.', 'In-vitro / in-silico ER-alpha study (PMID 30580607); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI221', 'H103', 'drug_interaction', 'Diuretics and lithium', 'moderate', 'Mild diuretic action: theoretical additive fluid/electrolyte loss with pharmaceutical diuretics (possible additive potassium depletion) and, like other diuretic herbs, a theoretical reduction of lithium clearance that could raise lithium levels.', 'Monitor lithium levels and serum potassium if combined; avoid unsupervised high-dose use with these drugs.', 'Brinker, Herbal Contraindications and Drug Interactions (diuretic-herb / lithium class principle); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI222', 'H103', 'drug_interaction', 'Antidiabetic drugs and insulin', 'low', 'Glucose-lowering activity demonstrated in animal studies; theoretical additive hypoglycemic effect.', 'Monitor blood glucose when combined with hypoglycemic medication; adjust as advised by the prescriber.', 'AHPA Botanical Safety Handbook, 2nd ed. (glucose-regulation animal pharmacology)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI223', 'H103', 'condition', 'Damp / Kapha excess, high ama, weak or cold digestion, acute congestion', 'moderate', 'The sweet, heavy, moist, cooling, cloying nature can aggravate dampness and mucus, dull weak digestive fire, and worsen congestive states.', 'Avoid or use only with digestive support (warming carminatives) in damp, congested, or low-agni presentations.', 'Frawley & Lad, The Yoga of Herbs; Mills & Bone, Principles and Practice of Phytotherapy (energetic caution)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H103', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "locator": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "locator": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
