INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H103', 'EP08', 'avoid', 1, 2, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "locator": "Charaka Samhita (classical Ayurvedic compendium, c. 2nd century BCE to 2nd century CE): Shatavari as balya (strengthener) and rasayana; The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH): Shatavari (Asparagus race", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "locator": "Frawley & Lad, The Yoga of Herbs (1986): Shatavari; Winston & Maimes, Adaptogens (2007); NIH LactMed / Drugs and Lactation Database: Wild Asparagus; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Sharma K et al., Plant ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H104', 'Rehmannia', 'Rehmannia glutinosa', 'Orobanchaceae (formerly Scrophulariaceae)', 'Root (prepared, Shu Di Huang; the raw form is Sheng Di Huang)', 'Sweet, Slightly bitter', 'Warm (prepared, Shu Di Huang); Cold (raw, Sheng Di Huang)', 'Moist', 'Yin deficiency and blood deficiency; dryness of the depleted, burned-out constitution; atrophy of marrow, bone, and essence (jing); the spent, hollow terrain that needs deep nourishing and moistening.', 'Dampness and cold accumulation; a boggy, phlegm-laden Spleen with loose stool and abdominal fullness, where the rich, cloying, moistening root deepens the damp and obstructs digestion.', 'Reproductive, Endocrine (adrenal/Kidney axis), Musculoskeletal (low back, bone, marrow), Hepatic (Liver blood).', 'Adrenal and constitutional exhaustion, menopausal heat and night sweats, low-back pain of deficiency, long-standing anemia and blood deficiency, functional infertility, and the dry, depleted, yin-deficient picture.', 'Spent and burned-out: the deep yin-deficient, dried-out, depleted phenotype whose reserves are drawn down. A rich restorative for the exhausted, not for the damp, boggy, sluggish-digestion type.', 'Vata, Pitta', 'Kapha', 'The principal yin-and-blood tonic of the Chinese materia medica. Prepared Rehmannia (Shu Di Huang) tonifies Kidney Yin and essence (jing) and nourishes Liver Blood: for Kidney Yin deficiency (night sweats, low-back and knee weakness, menopausal heat), Liver Blood deficiency (pallor, dizziness, scanty menses), and Kidney Jing depletion. It is the chief herb of Liu Wei Di Huang Wan. The raw form (Sheng Di Huang) is cold and clears heat and cools the blood.', 'Spleen Qi and Yang deficiency with dampness, phlegm accumulation, loose stool, and abdominal fullness; and acute external invasion, where a rich, cloying tonic is inappropriate. Classically paired with aromatic, qi-moving herbs (citrus peel, cardamom) to offset its cloying nature.', 'The rich, sweet, moistening root can cause loose stool, abdominal fullness, and poor appetite in Spleen-damp constitutions; it is cloying and should be combined with qi-moving, aromatic herbs. Prefer the prepared form (Shu Di Huang) for tonifying; the raw form is cooling and clears heat. Use cautiously with poor digestion.', 'Damp-cold accumulation, Spleen deficiency with loose stool or poor appetite, and acute infection with fever. Caution with poor digestion; introduce gradually.', 'Insufficient modern safety data; use only under qualified professional supervision. Rehmannia is a common constituent of supervised TCM blood-nourishing formulas but robust human pregnancy data are lacking. Source: Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica; NCCIH (general guidance).', 'Insufficient data; avoid internal medicinal doses while breastfeeding without professional guidance. No controlled lactation studies. Source: Mills and Bone, Principles and Practice of Phytotherapy.', 'Avoid therapeutic doses under 12 except under professional care; no established pediatric dosing, and the rich root readily burdens a young digestion. Source: Bensky et al.; Mills and Bone.', 'Theoretical additive effects with anticoagulants (limited data), diuretics, and, via HPA modulation, corticosteroids; monitor if combined. No well-documented clinical interactions at standard decoction doses. Source: Mills and Bone; Brinker, Herb Contraindications and Drug Interactions.', 'Decoction (classical), wine-prepared (jiu zhi), inclusion in patent formulas (Liu Wei Di Huang Wan), tincture, and powder.', 'Decoction 9-30 g/day; commonly 12-15 g in classical formulas. Prepared form for tonifying yin and blood; raw form for clearing heat and cooling blood.', 'Shennong Ben Cao Jing - Di Huang; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.', 'Liu Wei Di Huang Wan systematic reviews on menopausal symptoms; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH.', 'The principal yin-tonifying herb in classical TCM. The prepared form (Shu Di Huang) is moistening and gently warming; the raw form (Sheng Di Huang) is cooling and clears heat. Chief herb of Liu Wei Di Huang Wan. Iridoid glycosides (catalpol) are a key active constituent class. Rich and cloying, so classically combined with aromatic, digestion-moving herbs.', 'Not in canonical biblical texts; classical TCM use traces to the Han dynasty and the Shennong canon; cultivated principally in Henan province, China.', 'Cultivated root; Henan province is the classical source. Quality varies widely with the preparation method (the nine-times steaming and drying for Shu Di Huang). Not a conservation concern; prefer verified, properly-prepared sources.', 'Sweet, deeply moistening, gently warming when prepared: the archetypal restorative for the burned-out, dried-out, yin-and-blood-depleted constitution.', 'Persistent loose stool with abdominal distension, severe edema, or unexplained anemia that does not respond; refer for evaluation.', 'Rehmannia: reh-MAH-nee-uh. Rehmannia glutinosa: reh-MAH-nee-uh gloo-tih-NOH-suh.', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing - Di Huang; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.", "locator": "Shennong Ben Cao Jing - Di Huang; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Liu Wei Di Huang Wan systematic reviews on menopausal symptoms; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH.", "locator": "Liu Wei Di Huang Wan systematic reviews on menopausal symptoms; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH.", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
