INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H104', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing - Di Huang; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.", "locator": "Shennong Ben Cao Jing - Di Huang; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Liu Wei Di Huang Wan systematic reviews on menopausal symptoms; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH.", "locator": "Liu Wei Di Huang Wan systematic reviews on menopausal symptoms; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH.", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H105', 'Prickly Ash', 'Zanthoxylum americanum', 'Rutaceae', 'Bark and berry (dried stem bark; ripe fruit capsules)', 'Pungent (acrid), Bitter', 'Warm', 'Dry', 'Cold, torpor, laxity, and atony: the boggy, under-toned, cold-stuck terrain of sluggish peripheral circulation, atonic digestion with passive hypersecretion from debility, and a nervous and vascular system fallen into depression and want of vital heat.', 'Excess heat, acute inflammation, and dryness: hot, dry, tense, or over-stimulated constitutions, active bleeding, gastric or intestinal ulceration and irritation, and any parched or inflamed state that a warming acrid stimulant would only aggravate.', 'Cardiovascular and peripheral circulation; Digestive; Lymphatic; Musculoskeletal; Nervous; secondarily Integumentary and Reproductive.', 'Poor peripheral circulation with cold hands and feet; chronic cold rheumatism and joint pain; atonic dyspepsia with flatulent colic and low digestive fire; venous stasis, varicose veins, and hemorrhoids; leg cramps; neuralgia; lymphatic congestion and old scrofulous or alterative states; traditional toothache remedy.', 'Cold-Damp-Relaxed; the boggy, still-water phenotype with sluggish circulation, cold extremities, and atonic, under-fired digestion. Phlegmatic, and the cold-depleted who run short of vital heat.', 'Kapha (primary): warms and mobilizes cold, heavy, damp stagnation. Vata secondarily: warms coldness and kindles peripheral circulation.', 'Pitta (primary): pungent heat aggravates fire and inflammation. Vata secondarily if used long-term or in already-dry constitutions, owing to its drying, dispersing pungency.', 'Interior Cold with Blood Stasis and Qi Stagnation; Cold-Damp obstruction of the channels; Spleen and Kidney Yang deficiency presenting with cold limbs and sluggish, stuck circulation.', 'Heat and Fire patterns, Yin deficiency with heat or dryness, and Wind-Heat; any pattern with active bleeding, marked dryness, or inflamed mucosa.', 'A warming, acrid, dispersing stimulant. Overuse or use in the wrong (hot, dry) terrain provokes thirst, flushing, dry mucous membranes, and gastric burning; reduce or stop the herb if these excess-heat signs appear. May irritate a sensitive or inflamed gut. Its pungent amides can cause oral tingling and numbness, the source of its Toothache Tree name.', 'Active peptic ulcer, gastritis, GERD, or any inflamed or ulcerated condition of the gastrointestinal tract, since the herb increases gastric secretion and can irritate. Acute inflammatory or feverish-hot states. Known bleeding disorders or the perioperative period, on theoretical grounds from its coumarin content.', 'Avoid. Northern prickly ash bark is rated possibly unsafe in pregnancy by modern references (Natural Medicines / WebMD), and classical Eclectic use as an emmenagogue and uterine antispasmodic (functional dysmenorrhoea, uterine cramps in King''s) reinforces avoidance. Do not use during pregnancy. (Source: Natural Medicines/WebMD; Herbal Reality.)', 'Avoid. Reliable human safety data during lactation are lacking, and some sources caution it may reduce milk flow. Best avoided while breastfeeding. (Source: Natural Medicines/WebMD; Herbal Reality.)', 'Not recommended for routine pediatric use. Modern safety data in children are lacking, and the acrid gastrointestinal-stimulant and emmenagogue-type profile argues for caution. Although 19th-century Eclectics used the berries in cholera infantum, contemporary evidence is absent; use in children only under qualified supervision. (Source: Natural Medicines/WebMD.)', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin): theoretical additive bleeding risk from the bark''s coumarin constituents; one clinical monograph states prickly ash is contraindicated with anticoagulants. Avoid combining, and use caution with blood-thinning herbs (garlic, ginkgo). Acid-reducing drugs (antacids, H2-blockers, proton-pump inhibitors): the herb may increase gastric acid and blunt their effect. (Source: Herbal Reality; Natural Medicines/WebMD.)', 'Tincture of bark or berries; decoction of the dried bark; powdered bark in capsule; infusion; berry (essential) oil. Traditionally the bark or a berry was chewed as a masticatory for toothache, and the bark applied topically as a rubefacient liniment or poultice over cold, rheumatic joints. Best given with hot water and a warm foot-bath when a diaphoretic effect is wanted.', 'Tincture (1:5, 45%): 6 to 15 ml per day, or 2 to 20 drops of a concentrated bark tincture (King''s). Fluid extract (1:1, 45%): 3 to 9 ml per day. Decoction: 3 to 9 g dried bark daily. Powdered bark: 10 to 30 grains (about 0.6 to 2 g) three times daily. Berry oil: 2 to 10 drops on sugar or in mucilage. Start low; a warming stimulant is titrated to gentle inner warmth, not to burning.', 'King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.', 'Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.', 'Signature constituents: isoquinoline and benzophenanthridine alkaloids (chelerythrine, nitidine, magnoflorine, laurifoline, candicine, tembetarine); pungent acid-amides (alpha-sanshool, neoherculin/herculin) responsible for the tingling, salivation, and local numbing; coumarins (xanthoxyletin, xanthyletin, alloxanthoxyletin) that underlie the anticoagulant-interaction caution; lignans (asarinin, sesamin); volatile oil; and the classical crystalline xanthoxylin. Tradition: the archetypal Eclectic warming circulatory stimulant, the remedy that reaches the capillaries to drive cold-stuck blood and lymph back into motion, for chronic cold rheumatism, atonic dyspepsia, sluggish circulation with cold extremities, and as an alterative in old scrofulous and syphilitic states. Distinguish from Southern prickly ash (Zanthoxylum clava-herculis), which shares the profile, and from the Asian congener Zanthoxylum bungeanum (Sichuan pepper, Hua Jiao), a classical Chinese warming carminative. A stimulant, not a remedy for hot, dry, or inflamed terrain.', 'Not in canonical biblical texts. Zanthoxylum americanum is native to central and eastern North America, adopted from Native American practice (widely called the Toothache Tree for the numbing acrid bark) into 19th-century Eclectic medicine. Its Asian relative Zanthoxylum bungeanum (Hua Jiao) appears in the classical Chinese materia medica as a warming, cold-dispelling carminative.', 'Globally Least Concern (IUCN) and locally common as a thicket-forming shrub, but state-listed as Endangered in Florida, Maryland, and New Hampshire and of Special Concern in Tennessee; not on the United Plant Savers at-risk list. Bark harvest by girdling can kill the plant, so favor renewable berries, coppice regrowth, or prunings, and prefer cultivated or ethically wildcrafted stock over stripping wild trees.', 'Warm, dry, and acrid: the circulatory bellows that rekindles vital heat and drives cold-stuck blood and lymph back into motion.', 'Refer for chest pain, signs of critical limb ischemia (rest pain, non-healing ulcers, gangrene, sudden cold pale limb), suspected deep vein thrombosis (unilateral leg swelling, pain, warmth), unexplained or uncontrolled bleeding or black stools, severe or rapidly progressive joint disease, or any sign of a serious cardiovascular event. Poor circulation and rheumatic pain that is severe, worsening, or accompanied by systemic signs needs medical evaluation, not self-treatment.', 'Prickly Ash: PRIK-lee ASH. Zanthoxylum americanum: zan-THOKS-ih-lum uh-mair-ih-KAH-num.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "locator": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
