INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS17', 'Primary', 'Interior and peripheral cold; cold extremities, cold rheumatism.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS19', 'Primary', 'Torpor of digestion and circulation; the classic King''s picture of gastric and intestinal torpor.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS09', 'Secondary', 'Laxity and relaxation of mucous tissue with passive hypersecretion from debility.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS08', 'Secondary', 'Disperses cold-type blood and lymph stagnation, capillary engorgement.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS11', 'Secondary', 'Depression and atonicity of the nervous and vascular systems.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS05', 'Primary', 'Excess heat; a warming stimulant adds fuel to fire.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS06', 'Primary', 'Acute inflammation is aggravated by the acrid stimulant.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS03', 'Secondary', 'Drying quality worsens dryness and yin/fluid deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS10', 'Secondary', 'Over-excited or irritable states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H105', 'TS25', 'Secondary', 'Gastric or intestinal ulceration; increases secretion and irritates.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY06', 'Primary', 'Peripheral circulatory stimulant for sluggish flow and cold extremities.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY08', 'Primary', 'Atonic dyspepsia, flatulent colic, torpid secretion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY11', 'Secondary', 'Alterative; moves lymph in scrofulous and glandular stagnation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY04', 'Secondary', 'Chronic cold rheumatism, myalgia, lumbago.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY01', 'Secondary', 'Neuralgia; atonicity of the nervous system.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY10', 'Minor', 'Alterative in chronic skin and eruptive conditions.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H105', 'SY03', 'Minor', 'Functional dysmenorrhoea and uterine cramp (traditional).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A14', 'Primary', 'Classic alterative in scrofula, chronic rheumatism, and old syphilitic states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A18', 'Primary', 'Diaphoretic, especially given with hot water; determines to the surface.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A17', 'Primary', 'Carminative for flatulent colic and atonic dyspepsia.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A21', 'Secondary', 'Lymphagogue; moves congested lymph and glands.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A16', 'Secondary', 'Bitter tonic to a torpid, under-fired digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A23', 'Secondary', 'Stimulant tonic in debility of the stomach and circulation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A10', 'Secondary', 'Antispasmodic (berries) for colic and uterine cramp.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A27', 'Secondary', 'Anodyne in toothache and neuralgia; local numbing amides.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A35', 'Secondary', 'Rubefacient counter-irritant applied over cold, rheumatic joints.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A19', 'Secondary', 'Emmenagogue; relieves functional dysmenorrhoea (also a pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A08', 'Minor', 'Mild diuretic (modern clinical listing).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A32', 'Minor', 'Traditional vermifuge across the Zanthoxylum genus.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A43', 'Minor', 'Hepatic/cholagogue stimulation of sluggish bile.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A49', 'Minor', 'Antipyretic via diaphoresis in fever and ague.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H105', 'A09', 'Minor', 'Antirheumatic effect, largely via circulatory stimulation rather than direct anti-inflammation.');
