INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP14', 'Primary', 'Chronic cold rheumatism and joint pain.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP58', 'Primary', 'Atonic dyspepsia, low digestive fire.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP48', 'Secondary', 'Varicose veins and venous stasis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP37', 'Secondary', 'Leg and muscle cramps.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP22', 'Secondary', 'Neuralgia.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP71', 'Secondary', 'Lymphatic and glandular congestion (scrofula).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP54', 'Secondary', 'Flatulent colic, bloating.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP61', 'Minor', 'Hemorrhoids (venous stasis).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP09', 'Minor', 'Chronic infection; alterative in old syphilitic/scrofulous states.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP76', 'Minor', 'Fever and ague management via diaphoresis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H105', 'CP29', 'Minor', 'Functional dysmenorrhoea (traditional).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H105', 'P01', 'Primary', 'Bark or berry tincture; the common modern form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H105', 'P04', 'Primary', 'Decoction of dried bark.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H105', 'P03', 'Secondary', 'Powdered bark, 10 to 30 grains.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H105', 'P05', 'Secondary', 'Infusion of bark or berry.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H105', 'P13', 'Minor', 'Berry essential oil, 2 to 10 drops.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H105', 'C04', 'Indicated', 'Primary', 'Cold-damp, boggy, atonic Phlegmatic; the ideal candidate.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "locator": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H105', 'C05', 'Indicated', 'Secondary', 'Thin/cold/depleted with poor circulation; warms the cold but monitor its drying tendency.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Xanthoxylum, henriettes-herb.com.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "locator": "Grieve, A Modern Herbal (1931), Prickly Ash (botanical.com/botanical/mgmh/a/ashpr077.html); Herbal Reality, Prickly Ash clinical monograph; Natural Medicines / WebMD, Northern Prickly Ash monograph.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
