INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI227', 'H105', 'pregnancy', 'Pregnancy (all trimesters)', 'moderate', 'Traditional emmenagogue and uterine antispasmodic; modern references rate the bark possibly unsafe in pregnancy; coumarin constituents.', 'Avoid throughout pregnancy.', 'Natural Medicines / WebMD, Northern Prickly Ash; King''s American Dispensatory 1898 (traditional emmenagogue use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI228', 'H105', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable human safety data; some sources caution it may reduce milk flow.', 'Avoid while breastfeeding.', 'Natural Medicines / WebMD, Northern Prickly Ash.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI229', 'H105', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin)', 'moderate', 'Coumarin constituents (xanthoxyletin, xanthyletin, alloxanthoxyletin) may add to anticoagulant effect and increase bleeding risk.', 'Avoid concurrent use; one clinical monograph lists anticoagulants as a contraindication. Caution also with blood-thinning herbs (garlic, ginkgo).', 'Herbal Reality, Prickly Ash; Natural Medicines / WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI230', 'H105', 'drug_interaction', 'Acid-reducing drugs (antacids, H2-blockers, proton-pump inhibitors)', 'moderate', 'Herb may increase gastric acid secretion, reducing the drugs'' efficacy.', 'Avoid or separate use in patients requiring acid suppression.', 'Natural Medicines / WebMD, Northern Prickly Ash.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI231', 'H105', 'condition', 'Peptic ulcer, gastritis, GERD, or GI inflammation/ulceration', 'moderate', 'Acrid stimulant increases gastric secretion and can irritate inflamed or ulcerated mucosa.', 'Avoid in active ulcer, gastritis, or reflux.', 'Herbal Reality; Natural Medicines / WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI232', 'H105', 'condition', 'Bleeding disorders / perioperative period', 'moderate', 'Coumarin content; theoretical increased bleeding risk.', 'Discontinue at least 1 to 2 weeks before scheduled surgery; caution in coagulopathy.', 'Extrapolated from coumarin constituents (Herbal Reality; Natural Medicines / WebMD).');
