INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI233', 'H106', 'pregnancy', 'Pregnancy (all medicinal doses)', 'absolute', 'Long-documented emmenagogue and uterine-stimulant reputation (reputed abortifacient); the volatile oil is a mucous-membrane and renal irritant.', 'Avoid all medicinal preparations (teas, tinctures, capsules, essential oil) throughout pregnancy. Incidental culinary amounts seasoning food are of low concern.', 'German Commission E Monograph (Juniperi fructus, 1998); AHPA Botanical Safety Handbook 2nd ed. (2013), Class 2b; Brinker, Herbal Contraindications and Drug Interactions (4th ed. 2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI234', 'H106', 'condition', 'Acute or chronic kidney inflammation (nephritis) and renal insufficiency', 'absolute', 'Traditional and regulatory caution that a stimulating diuretic may aggravate inflamed or compromised kidneys; large doses can irritate the urinary passages. (Modern studies suggest whole-berry and terpinen-4-ol nephrotoxicity was overstated and partly due to confusion with toxic Savin, but the conservative contraindication is retained.)', 'Do not use with known kidney inflammation, reduced kidney function, or renal insufficiency. Discontinue if flank pain, kidney discomfort, or blood in the urine occurs.', 'German Commission E Monograph (Juniperi fructus, 1998); AHPA Botanical Safety Handbook 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI235', 'H106', 'other', 'Long-term continuous use (over 4-6 weeks)', 'moderate', 'Prolonged or high-dose use raises the risk of urinary-tract irritation and cumulative renal stress.', 'Limit continuous medicinal use to 4-6 weeks; do not exceed roughly 10 g berries or 100 mg essential oil per day. Take breaks and reassess before repeating.', 'German Commission E Monograph (Juniperi fructus, 1998)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI236', 'H106', 'drug_interaction', 'Diuretic drugs (loop, thiazide) and lithium', 'moderate', 'Additive diuresis can deplete fluid and electrolytes (especially potassium); marked diuresis can reduce lithium clearance and raise lithium levels.', 'Use cautiously with prescription diuretics; monitor hydration and electrolytes. If on lithium, avoid or monitor lithium levels closely.', 'German Commission E; Brinker, Herbal Contraindications and Drug Interactions (4th ed. 2010); AHPA Botanical Safety Handbook 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI237', 'H106', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Juniper has shown hypoglycemic activity in animal studies (with a conflicting report of raised glucose); a possible additive or interfering effect on blood glucose.', 'Monitor blood glucose if using medicinal-dose juniper alongside antidiabetic medication; culinary use is unproblematic.', 'Brinker, Herbal Contraindications and Drug Interactions (4th ed. 2010); AHPA Botanical Safety Handbook 2nd ed. (Interaction Class A)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI238', 'H106', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'Insufficient safety data; volatile-oil constituents may pass into breast milk.', 'Avoid therapeutic teas, tinctures, and the essential oil while nursing; culinary amounts are of low concern.', 'AHPA Botanical Safety Handbook 2nd ed. (2013); Mills & Bone, Essential Guide to Herbal Safety');
