INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI239', 'H107', 'drug_interaction', 'CYP3A4-substrate drugs with a narrow therapeutic index (ciclosporin, tacrolimus, carbamazepine, midazolam, nifedipine, many statins)', 'moderate', 'Piperine inhibits intestinal and hepatic CYP3A4 and P-glycoprotein, reducing first-pass elimination and raising plasma drug levels; clinically relevant from roughly 20 mg piperine (concentrated supplements).', 'Do not combine concentrated piperine or high-dose black-pepper supplements with these drugs without physician or pharmacist oversight; culinary pepper is generally acceptable but monitor for enhanced drug effect.', 'Bhardwaj et al., J Pharmacol Exp Ther 2002 (PMID 12130727); Brinker, Herbal Contraindications and Drug Interactions (4th ed); Mills & Bone, Principles and Practice of Phytotherapy');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI240', 'H107', 'drug_interaction', 'CYP2C9-substrate drugs with a narrow therapeutic index (warfarin, phenytoin, diclofenac)', 'moderate', 'Piperine inhibits CYP2C9, which can raise levels of S-warfarin and phenytoin; theoretical increased bleeding (raised INR) and phenytoin toxicity risk at supplement-level piperine.', 'Avoid concentrated piperine with warfarin or phenytoin; if used, add INR or therapeutic drug-level monitoring. Culinary pepper is unlikely to be significant for most patients.', 'Mills & Bone, Principles and Practice of Phytotherapy; Pharmacy Times / Natural Medicines; piperine-warfarin pharmacokinetic studies (rodent and in vitro)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI241', 'H107', 'drug_interaction', 'P-glycoprotein-substrate drugs (digoxin, fexofenadine)', 'low', 'Piperine inhibits the P-glycoprotein efflux transporter, increasing absorption of P-gp substrates; digoxin has a narrow therapeutic index.', 'Use caution and monitor if concentrated piperine is combined with digoxin; culinary use is generally unproblematic.', 'Bhardwaj et al., J Pharmacol Exp Ther 2002 (PMID 12130727)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI242', 'H107', 'pregnancy', 'Pregnancy (concentrated piperine and high therapeutic doses)', 'moderate', 'A rodent study reported possible anti-implantation and antifertility activity at very high piperine doses (75 mg/kg, far above dietary intake); piperine inhibition of maternal drug metabolism is undesirable in pregnancy. Culinary amounts have a long record of safe use.', 'Limit to culinary and food amounts during pregnancy; avoid concentrated piperine extracts and high-dose supplements.', 'Drugs and Lactation Database (LactMed); Restorative Medicine / Natural Medicines; AHPA Botanical Safety Handbook, 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI243', 'H107', 'breastfeeding', 'Breastfeeding (concentrated piperine supplements)', 'low', 'Piperine passes into breastmilk but at food-dose levels far below the infant taste threshold (peak near 8.9 mcg/L); no safety data exist for concentrated piperine products.', 'Culinary amounts are compatible with breastfeeding; avoid concentrated piperine supplements while nursing.', 'Drugs and Lactation Database (LactMed): Black Pepper');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI244', 'H107', 'condition', 'Active peptic ulcer, erosive gastritis, or symptomatic GERD', 'moderate', 'Pungent, heating constituents irritate hot, inflamed, or ulcerated gastrointestinal mucosa and can aggravate reflux.', 'Avoid therapeutic and high doses in active ulcer or erosive/reflux disease; keep to culinary amounts as tolerated.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); Mills & Bone, Principles and Practice of Phytotherapy');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H107', 'EP01', 'avoid', 0, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Piper (Black Pepper, Piper nigrum); Charaka Samhita (classical Ayurvedic compendium): Maricha, a principal pungent of Trikatu", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Piper (Black Pepper, Piper nigrum); Charaka Samhita (classical Ayurvedic compendium): Maricha, a principal pungent of Trikatu", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Mills & Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions (4th ed); Bhardwaj et al., ''Piperine, a Major Constituent of B", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Mills & Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions (4th ed); Bhardwaj et al., ''Piperine, a Major Constituent of B", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, true);
