INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI245', 'H108', 'pregnancy', 'Pregnancy (internal / medicinal use)', 'moderate', 'Myricadiol has mineralocorticoid-like activity (sodium and water retention, potassium loss, raised blood pressure); the high tannin fraction is carcinogenic in rodent studies; the bark is reported spermatocidal and antiandrogenic.', 'Avoid internal use during pregnancy. Do not use the powder, decoction, or tincture; limit any use to brief topical application if clearly indicated.', 'AHPA Botanical Safety Handbook 2nd ed. (2013); Brinker, Herbal Contraindications and Drug Interactions 4th ed.; Mills & Bone, Essential Guide to Herbal Safety (2005)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI246', 'H108', 'breastfeeding', 'Breastfeeding (internal / medicinal use)', 'moderate', 'Insufficient safety data; same mineralocorticoid and tannin-carcinogenicity concerns as in pregnancy.', 'Avoid internal use while breastfeeding.', 'AHPA Botanical Safety Handbook 2nd ed. (2013); Mills & Bone, Essential Guide to Herbal Safety (2005)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI247', 'H108', 'condition', 'Hypertension, edema, congestive heart failure, kidney disease', 'moderate', 'Mineralocorticoid-like myricadiol promotes sodium and water retention and potassium depletion, which can raise blood pressure and worsen fluid overload.', 'Avoid internal use in these conditions. If a practitioner uses it briefly, monitor blood pressure, edema, and serum potassium.', 'Natural Medicines / RxList - Bayberry; Mills & Bone, Essential Guide to Herbal Safety (2005)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI248', 'H108', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Sodium and water retention from mineralocorticoid activity can antagonize blood-pressure-lowering medication.', 'Avoid concurrent internal use; if unavoidable, monitor blood pressure closely.', 'Natural Medicines / RxList - Bayberry; Brinker, Herbal Contraindications and Drug Interactions 4th ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI249', 'H108', 'drug_interaction', 'Potassium-depleting diuretics, corticosteroids, and cardiac glycosides (digoxin)', 'moderate', 'Additive potassium depletion from mineralocorticoid activity increases risk of hypokalemia, which can potentiate digoxin toxicity and compound diuretic/steroid effects.', 'Avoid concurrent internal use; monitor serum potassium and digoxin effect if combined under supervision.', 'Brinker, Herbal Contraindications and Drug Interactions 4th ed.; Mills & Bone, Essential Guide to Herbal Safety (2005)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI250', 'H108', 'drug_interaction', 'Oral iron, alkaloidal drugs, and mineral supplements', 'low', 'Tannins bind iron, alkaloids, and minerals in the gut, reducing their absorption.', 'Separate bayberry from these agents by at least 2 hours. Avoid in iron-deficiency anemia.', 'Mills & Bone, Essential Guide to Herbal Safety (2005); Brinker, Herbal Contraindications and Drug Interactions 4th ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI251', 'H108', 'other', 'Prolonged / high-dose internal use', 'moderate', 'The tannin fraction of the bark is carcinogenic in rodent studies; large doses are emetic, sternutatory, and can cause nausea, vomiting, and liver irritation.', 'Restrict internal use to short courses at conventional doses; do not use long-term. Prefer topical use for chronic needs.', 'Natural Medicines / RxList - Bayberry; Brinker, Herbal Contraindications and Drug Interactions 4th ed.');
