INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H109', 'TCM06', 'Minor', 'Blood Deficiency without stasis; use cautiously', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Myrrha.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Myrrha.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Myrrh; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Mo Yao); Memorial Sloan Kettering Integrative Medicine herb monograph (myrrh); NCCIH; WebMD/RxList myrrh monograph; case report ''Risks ", "locator": "Grieve, A Modern Herbal (1931), Myrrh; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Mo Yao); Memorial Sloan Kettering Integrative Medicine herb monograph (myrrh); NCCIH; WebMD/RxList myrrh monograph; case report ''Risks ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI252', 'H109', 'pregnancy', 'Pregnancy', 'absolute', 'Emmenagogue and uterine stimulant; the blood-invigorating action can provoke uterine contractions, and abortifacient activity is reported.', 'Avoid all internal doses during pregnancy. Do not use to bring on menses if pregnancy is possible.', 'Memorial Sloan Kettering Integrative Medicine herb monograph; WebMD/RxList myrrh monograph; case report ''Risks of Myrrh usage in pregnancy'' (PubMed 28050964).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI253', 'H109', 'breastfeeding', 'Breastfeeding', 'moderate', 'Transfer into breast milk has not been studied; safety data are insufficient.', 'Avoid internal use while breastfeeding; reserve occasional dilute topical or oral-rinse use for practitioner guidance only.', 'WebMD/Drugs.com myrrh monograph (limited lactation data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI254', 'H109', 'drug_interaction', 'Warfarin and other coumarin anticoagulants', 'moderate', 'May antagonize the anticoagulant effect and reduce INR, as in a documented case report with C. molmol.', 'Avoid concurrent use or monitor INR closely; do not start or stop without prescriber oversight.', 'Memorial Sloan Kettering Integrative Medicine herb monograph (warfarin case report).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI255', 'H109', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas)', 'moderate', 'Additive blood-glucose-lowering effect may cause hypoglycemia.', 'Monitor blood glucose and adjust medication under clinician supervision.', 'WebMD/RxList myrrh monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI256', 'H109', 'condition', 'Undiagnosed or abnormal uterine bleeding and bleeding disorders', 'moderate', 'Blood-moving action may aggravate bleeding in the absence of blood stasis.', 'Avoid until the cause of bleeding is evaluated; use cautiously with bleeding disorders and discontinue 1 to 2 weeks before surgery.', 'Bensky, Chinese Herbal Medicine: Materia Medica (Mo Yao cautions); Memorial Sloan Kettering (high-dose effects on heart rate).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI257', 'H109', 'pediatric', 'Children', 'moderate', 'No established pediatric safety or dosing data for internal medicinal use.', 'Avoid internal medicinal doses in children; limit to dilute topical or oral-rinse use under professional guidance.', 'WebMD myrrh monograph (no pediatric data).');
