INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H110', 'TCM09', 'Primary', 'Invigorates blood and dispels stasis; amenorrhea, dysmenorrhea, postpartum stasis, masses.', '{"title": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "locator": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "locator": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H110', 'TCM08', 'Secondary', 'Frees constrained Liver qi; depression, restlessness, a heavy spirit.', '{"title": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "locator": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "locator": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H110', 'TCM06', 'Primary', 'A strong blood-mover depletes deficient blood and worsens bleeding; use only with genuine stasis.', '{"title": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "locator": "Grieve, A Modern Herbal (1931), Saffron (Crocus sativus).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "locator": "Culpeper, The Complete Herbal (Saffron); King''s American Dispensatory (Felter and Lloyd, 1898), Crocus; Dioscorides, De Materia Medica (krokos); Natural Medicines Comprehensive Database (Saffron); NCCIH; AHPA Botanical Safety Handbook (2nd ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI258', 'H110', 'pregnancy', 'Pregnancy', 'absolute', 'Saffron is a uterine stimulant and traditional abortifacient; amounts above culinary can cause uterine contraction and miscarriage. Toxic doses near 5 g cause uterine bleeding and near 10 g have induced abortion.', 'Do not use medicinal or supplemental doses in pregnancy. Culinary food amounts are generally regarded as acceptable.', 'Natural Medicines / NCCIH; AHPA Botanical Safety Handbook (Crocus sativus stigma listed among abortifacient botanicals).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI259', 'H110', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable data on saffron in medicinal amounts during lactation.', 'Avoid amounts larger than those found in food; culinary use is presumed acceptable.', 'Natural Medicines Comprehensive Database; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI260', 'H110', 'condition', 'Bipolar disorder / mania', 'moderate', 'Saffron affects mood and may trigger excitability and impulsive or manic behavior.', 'Avoid in bipolar disorder; do not use saffron to self-treat serious mood disorders.', 'Natural Medicines Comprehensive Database (WebMD monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI261', 'H110', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, rivaroxaban and other DOACs, aspirin, clopidogrel)', 'moderate', 'Saffron has antiplatelet, blood-moving activity; additive bleeding risk. A case report describes epistaxis and gum bleeding with saffron plus rivaroxaban.', 'Avoid combined medicinal use; use caution perioperatively and discontinue about two weeks before surgery.', 'Published saffron-rivaroxaban case report; Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI262', 'H110', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Saffron lowers blood pressure; additive hypotension.', 'Monitor blood pressure; caution when combined with antihypertensives.', 'Natural Medicines Comprehensive Database (WebMD monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI263', 'H110', 'drug_interaction', 'Antidiabetic drugs', 'moderate', 'Saffron lowers blood glucose; additive hypoglycemia.', 'Monitor blood sugar; adjust antidiabetic therapy as needed under supervision.', 'Natural Medicines Comprehensive Database (WebMD monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI264', 'H110', 'drug_interaction', 'Sedatives and CNS depressants', 'low', 'Possible additive sedation and drowsiness at higher doses.', 'Use caution with sedative medications at above-culinary doses.', 'Natural Medicines Comprehensive Database (WebMD monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI265', 'H110', 'other', 'Overdose (dose-dependent)', 'absolute', 'Near 5 g causes poisoning (vomiting, dizziness, uterine bleeding, thrombocytopenia, yellowing of skin and mucous membranes); near 10 g is abortifacient; roughly 12 to 20 g can be fatal.', 'Never exceed about 1.5 g per day; keep to culinary or studied therapeutic doses and practitioner supervision.', 'Natural Medicines / NCCIH; WebMD monograph.');
