INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H111', 'TCM11', 'Primary', 'Clears Heat/Fire: stomach heat, hyperacidity, bladder heat.', '{"title": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "locator": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H111', 'TCM08', 'Secondary', 'Moves qi in food stagnation: bloating, belching.', '{"title": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "locator": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H111', 'TCM10', 'Minor', 'Damp-heat in the lower burner: burning, scanty urination.', '{"title": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "locator": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H111', 'TCM03', 'Minor', 'Spleen qi/yang deficiency with cold: cooling diuretic may burden a cold, deficient digestion.', '{"title": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "locator": "Grieve''s A Modern Herbal (1931), Coriander. Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Coriandrum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Dhanyaka (Coriandrum sativum); Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (coriander fruit, Safety Class 1); Brinker, Herb Contraindications and D", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI266', 'H111', 'other', 'Apiaceae (Umbelliferae) allergy: coriander, celery, caraway, dill, fennel, anise; mugwort/birch pollen cross-reactivity', 'absolute', 'IgE cross-reactivity among Apiaceae and related pollens; reports of urticaria, rhinitis, occupational asthma, contact dermatitis, photosensitivity and rare anaphylaxis.', 'Avoid in known coriander or Apiaceae allergy. Introduce cautiously in atopic patients; discontinue on any allergic sign.', 'AHPA Botanical Safety Handbook 2nd ed.; NIH LactMed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI267', 'H111', 'drug_interaction', 'Antidiabetic / hypoglycemic agents (insulin, sulfonylureas, metformin)', 'moderate', 'Coriander has documented blood-glucose-lowering activity; therapeutic doses may add to the hypoglycemic effect of glucose-lowering drugs.', 'Monitor blood glucose; watch for hypoglycemia; coordinate dose adjustment with the prescriber. Culinary amounts are not a concern.', 'Mills & Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI268', 'H111', 'drug_interaction', 'Antihypertensive and diuretic drugs', 'low', 'Mild hypotensive and diuretic activity may be additive at therapeutic doses (limited human data).', 'Monitor blood pressure with high therapeutic doses; likely insignificant at culinary amounts.', 'Mills & Bone, Principles and Practice of Phytotherapy; pharmacology reviews (theoretical).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI269', 'H111', 'other', 'Coriander essential oil, internal or undiluted use', 'moderate', 'Concentrated volatile oil; potential mucosal irritation and insufficient safety data at therapeutic internal doses.', 'Do not take the essential oil internally undiluted. Reserve internal use for trained supervision; avoid concentrated oil in pregnancy and young children.', 'Brinker, Herb Contraindications and Drug Interactions; AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI270', 'H111', 'pregnancy', 'Pregnancy: concentrated extracts and essential oil', 'moderate', 'Food and moderate seed doses are GRAS/Class 1 with no documented teratogenicity; concentrated extracts and essential oil lack robust human safety data.', 'Culinary and moderate coriander-water/seed-tea use is considered low risk. Avoid concentrated extracts and essential oil internally during pregnancy.', 'AHPA Botanical Safety Handbook 2nd ed. (Safety Class 1); NCCIH.');
