INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H112', 'TCM07', 'Secondary', 'Drying, heating action consumes fluids in Yin deficiency.', '{"title": "Grieve, A Modern Herbal (1931), Nigella (Fennel-Flower / Nutmeg Flower).", "locator": "Grieve, A Modern Herbal (1931), Nigella (Fennel-Flower / Nutmeg Flower).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Memorial Sloan Kettering Cancer Center, Nigella sativa herb monograph; NIH Drugs and Lactation Database (LactMed), Black Seed; Nigella sativa (black seed) safety: an overview (PMC10373399, 2023, PMID 37551386); Brinker, Herb Contraindicatio", "locator": "Memorial Sloan Kettering Cancer Center, Nigella sativa herb monograph; NIH Drugs and Lactation Database (LactMed), Black Seed; Nigella sativa (black seed) safety: an overview (PMC10373399, 2023, PMID 37551386); Brinker, Herb Contraindicatio", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI271', 'H112', 'pregnancy', 'Pregnancy (therapeutic doses of seed extract or black seed oil)', 'moderate', 'Traditional emmenagogue and abortifacient; animal studies show reduced fetal survival and anti-fertility effects at therapeutic-equivalent doses, and thymoquinone affects uterine smooth-muscle contractility.', 'Culinary spice amounts are acceptable; avoid concentrated extracts and black seed oil at therapeutic doses during pregnancy.', 'Nigella sativa (black seed) safety overview, PMID 37551386 (2023); MSKCC; traditional-use literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI272', 'H112', 'breastfeeding', 'Breastfeeding (concentrated oil or high-dose supplements)', 'moderate', 'No data on excretion of black seed constituents into breast milk or on infant safety; the oil can cause allergic contact dermatitis.', 'Culinary use is likely acceptable; avoid concentrated oil or high-dose supplements while nursing.', 'NIH Drugs and Lactation Database (LactMed), Black Seed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI273', 'H112', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Thymoquinone may inhibit platelet function and was shown to inhibit warfarin activity, altering bleeding risk and INR.', 'Use cautiously; monitor INR and for signs of bleeding; discontinue before surgery.', 'Memorial Sloan Kettering Cancer Center; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI274', 'H112', 'drug_interaction', 'Antidiabetic drugs (metformin, sulfonylureas, insulin)', 'moderate', 'Additive blood-glucose lowering, raising the risk of hypoglycemia.', 'Monitor blood glucose; the antidiabetic dose may need adjustment.', 'MSKCC; NCCIH; Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI275', 'H112', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Additive blood-pressure lowering, raising the risk of hypotension.', 'Monitor blood pressure when combined.', 'MSKCC; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI276', 'H112', 'drug_interaction', 'CYP2D6, CYP3A4, and CYP2C9 substrates (e.g., cyclosporine, phenytoin, sildenafil)', 'moderate', 'Nigella sativa inhibits these enzymes in vitro and has been reported to alter plasma levels of their substrates.', 'Use caution with narrow-therapeutic-index drugs cleared by these pathways; monitor drug levels or clinical effect.', 'Memorial Sloan Kettering Cancer Center; Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI277', 'H112', 'other', 'Known hypersensitivity to Nigella, or prior severe skin reaction to the oil', 'moderate', 'Topical black seed oil can cause allergic contact dermatitis, and rare DRESS (drug reaction with eosinophilia and systemic symptoms) has followed topical use.', 'Avoid in those with prior hypersensitivity; patch test topical oil before wider use.', 'NIH LactMed; MSKCC.');
