INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H112', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Nigella (Fennel-Flower / Nutmeg Flower).", "locator": "Grieve, A Modern Herbal (1931), Nigella (Fennel-Flower / Nutmeg Flower).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Memorial Sloan Kettering Cancer Center, Nigella sativa herb monograph; NIH Drugs and Lactation Database (LactMed), Black Seed; Nigella sativa (black seed) safety: an overview (PMC10373399, 2023, PMID 37551386); Brinker, Herb Contraindicatio", "locator": "Memorial Sloan Kettering Cancer Center, Nigella sativa herb monograph; NIH Drugs and Lactation Database (LactMed), Black Seed; Nigella sativa (black seed) safety: an overview (PMC10373399, 2023, PMID 37551386); Brinker, Herb Contraindicatio", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H113', 'Flax / Linseed', 'Linum usitatissimum', 'Linaceae', 'Seed (and fixed oil)', 'Sweet', 'Cool', 'Moist', 'Dryness (dry cough, dry hard stool, dry irritated skin and mucosa); Acute Inflammation of mucous membranes and skin (soothes and cools); Torpor of the bowel (bulk stimulates sluggish peristalsis).', 'Dampness and boggy, phlegmatic tissue; Laxity with excess mucus or loose, leaky bowel.', 'Digestive, Respiratory, Urinary, and Integumentary (skin) systems.', 'Constipation with dry, hard stool; dry or irritating cough and bronchial irritation; urinary tract irritation and cystitis; boils, abscesses, and localized skin inflammation (poultice).', 'Hot-Dry-Tense and Thin-Cold-Dry (Vata-like); the parched, tight, constipated phenotype with dry mucous membranes.', 'Vata, Pitta', 'Kapha', 'Intestinal dryness and Yin or fluid deficiency with dry, hard stool; dry Lung with unproductive cough.', 'Dampness and Phlegm accumulation; Spleen Qi deficiency with loose stools or diarrhea.', 'Always take with abundant fluid (roughly ten times the seed volume) to prevent choking or intestinal impaction. Ground seed oxidizes quickly; use fresh and store cold. Higher doses may cause bloating, flatulence, and loose stool, and may modestly lower blood glucose and blood pressure. Immature (unripe) seed contains cyanogenic glycosides and should not be eaten raw in quantity.', 'Contraindicated in bowel obstruction, ileus, and esophageal or intestinal stricture. Avoid with acute, undiagnosed abdominal pain. Discontinue if swallowing or passage becomes difficult.', 'Culinary amounts of whole or ground seed are generally regarded as acceptable, but medicinal or supplemental doses and flaxseed oil are not established as safe and are best avoided; lignan phytoestrogens have weak estrogenic activity and human data are limited. Source: NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (2013).', 'Culinary amounts are considered compatible with breastfeeding; lignans transfer minimally into milk. Safety of medicinal or supplemental doses is not well established. Source: LactMed (NIH Drugs and Lactation Database); AHPA Botanical Safety Handbook, 2nd ed.', 'Whole or ground seed in food amounts is appropriate; ensure adequate fluid intake with any laxative use to prevent obstruction. Medicinal dosing is not well studied in children. Source: NCCIH; AHPA Botanical Safety Handbook, 2nd ed.', 'Mucilage and fiber can delay or reduce absorption of concurrently taken oral drugs; separate flaxseed from other medications by at least 1 hour before or 2 hours after. Alpha-linolenic acid may add a mild antiplatelet effect, so use caution with anticoagulant or antiplatelet drugs (warfarin, aspirin, DOACs) and monitor for bruising or bleeding. May modestly potentiate antidiabetic and antihypertensive drugs; monitor glucose and blood pressure. Source: NCCIH; AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions, 3rd ed.', 'Cold-soaked whole seed for its mucilage; ground seed stirred into water or food as a bulk laxative and nutritive; simmered seed as a soothing gruel or decoction; crushed-seed hot poultice for boils and chest complaints; linseed (fixed) oil externally in liniments and for dry skin.', 'Ground seed: 1 tablespoon (about 10 g) stirred into 150 mL water, 2 to 3 times daily, each dose followed by a full glass of water. Whole seed: 1 to 2 tablespoons daily with abundant fluid. Poultice: crushed or ground seed mixed with hot water to a paste, applied warm.', 'King''s American Dispensatory (Felter and Lloyd, 1898), heading Linum.', 'Grieve, A Modern Herbal (1931), Flax; NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Practice of Phytotherapy.', 'Seed of the flax plant, rich in mucilage, alpha-linolenic acid (omega-3), soluble and insoluble fiber, and lignans (chiefly secoisolariciresinol diglucoside), which gut bacteria convert to the enterolignans enterodiol and enterolactone. Its virtues are mechanical and demulcent rather than heroic: it lubricates and bulks. Western herbalists read it as cooling and moist; classical Ayurveda instead classes Atasi (Alsi) as ushna (heating) owing to its rich oil, pacifying Vata but potentially aggravating Pitta, a traditional divergence noted for the reviewer. Bounding cautions: adequate hydration and fresh, properly ripened seed.', 'Thoroughly biblical as both crop and fiber: the flax was smitten by hail in Egypt (Exodus 9:31); Rahab hid the spies under stalks of flax on her roof (Joshua 2:6); the virtuous woman worketh willingly with wool and flax (Proverbs 31:13). Linen woven from flax clothes the priests and tabernacle throughout Scripture.', 'Widely cultivated as a fiber and oilseed crop, not wild-harvested; no conservation concern and not listed by United Plant Savers. Prefer organically grown seed to avoid pre-harvest glyphosate desiccation residues.', 'Cool, moist demulcent and emollient; the soothing mucilage that lubricates dry, tight, irritated passages and bulks a sluggish bowel.', 'Refer for constipation with severe abdominal pain, vomiting, or absence of stool and gas (possible obstruction); rectal bleeding; unexplained weight loss; cough lasting more than three weeks or producing blood; or signs of an allergic reaction (rare seed allergy).', 'Flax; Linseed (LIN-seed). Linum usitatissimum (LY-num yoo-zih-tuh-TISS-ih-mum).', 'free', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), heading Linum.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), heading Linum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Flax; NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Pra", "locator": "Grieve, A Modern Herbal (1931), Flax; NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Pra", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
