INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H113', 'TCM03', 'Secondary', 'Worsens Spleen Qi deficiency with loose stool', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), heading Linum.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), heading Linum.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Flax; NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Pra", "locator": "Grieve, A Modern Herbal (1931), Flax; NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Pra", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI278', 'H113', 'condition', 'Bowel obstruction, ileus, esophageal or intestinal stricture', 'absolute', 'Bulk-forming mucilage swells with fluid and can impact a narrowed or obstructed lumen', 'Do not use in known or suspected obstruction, stricture, or ileus; discontinue with acute abdominal pain or difficulty swallowing', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI279', 'H113', 'pregnancy', 'Pregnancy (medicinal/supplemental doses and flaxseed oil)', 'moderate', 'Lignan phytoestrogens (secoisolariciresinol diglucoside converted to enterolignans) have weak estrogenic activity; safety of medicinal amounts is not established', 'Culinary amounts of whole or ground seed generally acceptable; avoid medicinal or supplemental doses and flaxseed oil; consult a provider', 'NCCIH, Flaxseed and Flaxseed Oil; AHPA Botanical Safety Handbook, 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI280', 'H113', 'drug_interaction', 'Oral medications taken concurrently', 'moderate', 'Mucilage and fiber can delay or reduce absorption of concurrently ingested drugs', 'Separate flaxseed from other oral medications by at least 1 hour before or 2 hours after', 'NCCIH; Brinker, Herb Contraindications and Drug Interactions, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI281', 'H113', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, DOACs)', 'moderate', 'Alpha-linolenic acid may exert a mild additive antiplatelet effect, theoretically increasing bleeding risk', 'Monitor for bruising or bleeding; use caution with high-dose flaxseed or flaxseed oil alongside anticoagulants', 'AHPA Botanical Safety Handbook, 2nd ed.; Natural Medicines / NCCIH');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI282', 'H113', 'drug_interaction', 'Antidiabetic and antihypertensive drugs', 'low', 'May modestly lower blood glucose and blood pressure, giving a possible additive effect', 'Monitor glucose and blood pressure when combined; adjust therapy per prescriber', 'NCCIH; Mills and Bone, Principles and Practice of Phytotherapy');
