INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI283', 'H114', 'population', 'Pregnancy', 'moderate', 'Traditional emmenagogue with a reputed abortifacient and uterine-stimulant action; AHPA safety Class 2b.', 'Avoid during pregnancy; use only under the supervision of a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed. (Class 2b); Brinker, Herb Contraindications and Drug Interactions');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI284', 'H114', 'population', 'Lactation', 'moderate', 'No modern clinical safety data during breastfeeding; safety not established.', 'Avoid while breastfeeding pending data.', 'AHPA Botanical Safety Handbook, 2nd ed. (no lactation data)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI285', 'H114', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Additive hypoglycemic effect; horehound extract and marrubiin lower blood glucose.', 'Monitor blood glucose; watch for additive hypoglycemia and adjust therapy as needed.', 'Brinker, Herb Contraindications and Drug Interactions; hypoglycemic pharmacology reviewed in PMC5622392 (2017)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI286', 'H114', 'drug_interaction', 'Antihypertensive and calcium-channel-blocking drugs', 'low', 'Marrubenol is an L-type calcium channel blocker with vasorelaxant and hypotensive activity; additive blood-pressure lowering possible at higher doses.', 'Use cautiously at higher doses with these drugs; monitor blood pressure.', 'El Bardai et al., Br J Pharmacol 2003 (PMID 14597602); Mills & Bone, Principles and Practice of Phytotherapy');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI287', 'H114', 'condition', 'Dry, hot, irritable (non-productive) cough', 'moderate', 'Warming and drying energetics aggravate a dry, heat-pattern respiratory terrain.', 'Choose a moistening demulcent instead for dry, spasmodic, or hot coughs.', 'Traditional Western energetics (Wood, The Earthwise Herbal; Hoffmann, Medical Herbalism)');
