INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI288', 'H115', 'pregnancy', 'Pregnancy', 'absolute', 'Emmenagogue and uterine-stimulant action with a longstanding abortifacient reputation, compounded by the neurotoxic, proconvulsant thujone in the volatile oil.', 'Do not use in any form during pregnancy or when attempting to conceive.', 'AHPA Botanical Safety Handbook (2nd ed., Artemisia absinthium); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI289', 'H115', 'breastfeeding', 'Breastfeeding', 'moderate', 'Thujone is neurotoxic and lipophilic and may pass into breast milk; no reliable human lactation safety data.', 'Avoid during breastfeeding.', 'AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI290', 'H115', 'condition', 'Epilepsy and other seizure disorders', 'absolute', 'Thujone is a GABA-A receptor antagonist that lowers the seizure threshold and can precipitate tonic-clonic convulsions.', 'Do not use in anyone with epilepsy or a history of seizures.', 'Pharmacology reviews of thujone and Artemisia absinthium (Batiha et al., 2020, PMC7345338); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI291', 'H115', 'drug_interaction', 'Anticonvulsant and antiepileptic drugs (phenobarbital, valproate, carbamazepine, phenytoin)', 'moderate', 'Thujone antagonizes GABA-A signaling, which may reduce the efficacy of anticonvulsants and lower the seizure threshold.', 'Avoid concurrent use; do not combine with antiepileptic therapy.', 'Brinker, Herb Contraindications and Drug Interactions; thujone pharmacology reviews (PMC7345338).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI292', 'H115', 'condition', 'Active peptic ulcer, acute gastritis, or acute gastrointestinal inflammation', 'moderate', 'The irritant bitter and aromatic volatile oil can aggravate hot, inflamed, or ulcerated gastric mucosa.', 'Avoid during acute gastritis or active ulceration; use only once inflammation has settled.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI293', 'H115', 'other', 'Hypersensitivity to Asteraceae (ragweed, chamomile, marigold, feverfew)', 'moderate', 'Cross-reactivity within the Asteraceae family can provoke allergic reactions.', 'Avoid with known Asteraceae allergy; discontinue if rash, itching, or swelling appears.', 'AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI294', 'H115', 'other', 'Essential oil taken internally, high doses, or prolonged use', 'absolute', 'Concentrated thujone from the essential oil or from excessive or long-term dosing is neurotoxic, causing the historical absinthism syndrome (restlessness, tremor, insomnia, seizures) and possible renal injury.', 'Never take the pure essential oil internally; keep to low doses in short courses and do not exceed recommended dose or duration.', 'Pharmacology reviews of thujone and Artemisia absinthium (Batiha et al., 2020, PMC7345338); Brinker, Herb Contraindications and Drug Interactions.');
