INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI295', 'H116', 'other', 'Broken, inflamed, ulcerated, or sensitive skin; prolonged or occluded application', 'absolute', 'Allyl isothiocyanate is a strong rubefacient and vesicant; on damaged or thin skin, or with prolonged or occluded contact, it causes blistering, chemical (second-degree) burns, and slow-healing ulceration.', 'Never apply to broken, inflamed, or sensitive skin. Use a cloth barrier, watch the skin, and remove at strong reddening before blistering.', 'National Capital Poison Center (mustard plaster); AHPA Botanical Safety Handbook, 2nd ed.; WebMD/RxList.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI296', 'H116', 'pediatric', 'Infants and young children', 'absolute', 'Children burn far more readily; mustard plasters cause severe irritation, chemical burns, and blistering. Goitrogenic glucosinolates may also affect a child''s thyroid on large internal intake.', 'Do not use mustard plasters on infants or young children. Reserve any use in older children for brief, protected topical application under supervision.', 'National Capital Poison Center; WebMD/RxList.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI297', 'H116', 'pregnancy', 'Pregnancy (large internal or medicinal doses)', 'moderate', 'Rated likely unsafe by mouth in large medicinal amounts; traditional heating emmenagogue reputed to stimulate menstruation. Culinary amounts are considered safe.', 'Avoid medicinal internal doses and prolonged plasters. Culinary use as a condiment is fine.', 'WebMD/RxList (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI298', 'H116', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'Insufficient reliable data on medicinal use during lactation.', 'Avoid medicinal internal doses; keep topical use off the chest and feeding area. Culinary amounts are fine.', 'WebMD/RxList (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI299', 'H116', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, other hypoglycemics)', 'moderate', 'Black mustard may lower blood glucose; large medicinal amounts can add to hypoglycemic drugs and cause blood sugar to fall too low.', 'Monitor blood glucose if combined; discontinue large medicinal amounts at least two weeks before scheduled surgery.', 'WebMD/RxList (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI300', 'H116', 'condition', 'Hypothyroidism / thyroid disease', 'moderate', 'Glucosinolates and their breakdown products are goitrogenic (antithyroid); large, chronic intake may impair thyroid function, especially in those already hypothyroid.', 'Avoid large, chronic medicinal intake in hypothyroidism or on thyroid medication; culinary amounts are not a concern.', 'Peer-reviewed glucosinolate/goitrogen reviews (e.g., ScienceDirect goitrogen overview; mustard glucosinolate pharmacology, PMC9459965).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI301', 'H116', 'other', 'Large internal doses / mucous-membrane and airway exposure', 'moderate', 'Large oral doses act as a violent emetic and gastrointestinal irritant and can injure the throat, esophagus, and airway; the concentrated volatile oil severely irritates eyes and mucous membranes.', 'Do not take large internal doses casually; keep the volatile oil away from eyes and do not inhale it concentrated.', 'WebMD/RxList; Botanical-online (mustard toxicity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI302', 'H116', 'other', 'Mustard or cruciferous (Brassica) allergy', 'absolute', 'Mustard is a recognized food allergen and contact sensitizer capable of causing contact dermatitis and, rarely, anaphylaxis in sensitized individuals.', 'Avoid in anyone with known mustard or cruciferous plant allergy.', 'WebMD/RxList; mustard allergen literature.');
