INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H117', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS18', 'Primary', 'Antispasmodic releases muscular and visceral tension.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS12', 'Primary', 'Relieves cramp, spasm, and colic; opens constriction.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS08', 'Primary', 'Emmenagogue and stimulant that moves suppressed, sluggish menstrual and digestive flow.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS22', 'Secondary', 'Warm, acrid mover of stuck Qi.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS17', 'Secondary', 'Warms cold, stagnant, cramping terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS05', 'Primary', 'Warm, acrid herb aggravates excess heat.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS06', 'Primary', 'Irritant; worsens acute inflammation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS03', 'Secondary', 'Drying nature aggravates dry, depleted tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H117', 'TS10', 'Minor', 'High doses overstimulate and can provoke convulsions.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY03', 'Primary', 'Reproductive: uterine stimulant and emmenagogue for suppressed or painful menses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY01', 'Primary', 'Nervous: antispasmodic and anodyne for neuralgia and nervous cramp.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY04', 'Secondary', 'Musculoskeletal: eases cramp, spasm, and rheumatic pain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY08', 'Secondary', 'Digestive: carminative for flatulent colic; vermifuge for worms.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY06', 'Secondary', 'Cardiovascular: rutin strengthens capillaries; traditional for nervous palpitations.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H117', 'SY10', 'Minor', 'Integumentary: topical rubefacient, but phototoxic on skin contact.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A10', 'Primary', 'Antispasmodic for cramp, colic, and spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A19', 'Primary', 'Emmenagogue; promotes suppressed menstruation (dose-dependent uterine stimulant).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A32', 'Secondary', 'Anthelmintic / vermifuge for intestinal worms.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A27', 'Secondary', 'Anodyne for neuralgic and rheumatic pain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A17', 'Secondary', 'Carminative for flatulent colic and sluggish digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A03', 'Secondary', 'Nervine relaxant for nervous spasm and palpitations.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A41', 'Minor', 'Oxytocic / uterine-stimulant at higher doses (the basis of its abortifacient risk); a caution, not a therapeutic use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A35', 'Minor', 'Rubefacient applied topically to painful joints and muscles.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H117', 'A25', 'Minor', 'Antioxidant / vascular support from rutin and quercetin.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H117', 'CP30', 'Primary', 'Amenorrhea: classic low-dose emmenagogue for suppressed menses (never in pregnancy).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H117', 'CP29', 'Secondary', 'Dysmenorrhea: antispasmodic for painful, cramping periods.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H117', 'CP39', 'Secondary', 'Muscular tension / spasm.');
