INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H117', 'TCM11', 'Primary', 'Heat / Fire: aggravates red, hot, inflamed, restless heat patterns.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Ruta (Rue).", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Ruta (Rue).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper''s Complete Herbal (1653): Rue; Ellingwood, American Materia Medica (1919): Ruta; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): Ruta graveolens; Brinker, Herbal Contraindications and Drug Interactions, 4th ed.;", "locator": "Culpeper''s Complete Herbal (1653): Rue; Ellingwood, American Materia Medica (1919): Ruta; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): Ruta graveolens; Brinker, Herbal Contraindications and Drug Interactions, 4th ed.;", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI303', 'H117', 'pregnancy', 'Pregnancy (all trimesters) and preconception', 'absolute', 'Documented uterine stimulant, emmenagogue, and abortifacient; furanocoumarins and alkaloids drive uterine activity and systemic toxicity, with case reports of multi-organ failure and death from attempted abortifacient use.', 'Do not use in pregnancy or when trying to conceive, in any form or dose. Screen for possible pregnancy before use.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): not for use in pregnancy; Brinker, Herbal Contraindications and Drug Interactions (contraindicated in pregnancy); IPCS INCHEM PIM 475.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI304', 'H117', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation safety data; potentially toxic furanocoumarins and quinoline alkaloids with uncharacterized transfer into milk.', 'Avoid internal use while breastfeeding pending data.', 'AHPA Botanical Safety Handbook, 2nd ed. (insufficient data); NCCIH consumer guidance principle.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI305', 'H117', 'drug_interaction', 'CYP3A4-metabolized drugs and narrow-therapeutic-index drugs', 'moderate', 'Rue furanocoumarins (bergapten, xanthotoxin, psoralen) inhibit intestinal CYP3A4 in a grapefruit-like manner, raising drug levels; a case of serious toxicity occurred with concurrent bisoprolol, diltiazem, and amiloride / hydrochlorothiazide.', 'Avoid combining with CYP3A4 substrates and narrow-therapeutic-index drugs; if unavoidable, monitor closely under practitioner supervision.', 'Brinker, Herbal Contraindications and Drug Interactions; furanocoumarin CYP3A4 inhibition literature; IPCS INCHEM PIM 475.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI306', 'H117', 'drug_interaction', 'Photosensitizing agents and phototherapy (PUVA, some antibiotics, retinoids, amiodarone)', 'moderate', 'Rue furanocoumarins are potent photosensitizers; effects are additive with other photosensitizing drugs and light therapy.', 'Avoid concurrent use; counsel strict sun / UV protection.', 'IPCS INCHEM PIM 475; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI307', 'H117', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (e.g., warfarin)', 'moderate', 'Coumarin content and documented coagulopathy in overdose suggest additive bleeding risk.', 'Avoid or monitor coagulation closely; counsel on bleeding signs.', 'IPCS INCHEM PIM 475 (coagulopathy); Brinker, Herbal Contraindications and Drug Interactions (theoretical additive effect).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI308', 'H117', 'condition', 'Hepatic or renal impairment', 'moderate', 'Overdose and the essential oil cause hepatic degeneration and renal damage; impaired organs raise the risk.', 'Avoid in liver or kidney disease; never use the essential oil internally.', 'IPCS INCHEM PIM 475; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI309', 'H117', 'condition', 'Skin contact with the fresh plant plus sun exposure', 'moderate', 'Furanocoumarins on the leaf surface cause phytophotodermatitis: erythema, blistering, and lasting hyperpigmentation on UV exposure.', 'Wear gloves when handling the fresh plant and avoid sun exposure to contacted skin.', 'IPCS INCHEM PIM 475; published phototoxic contact dermatitis case reports (PubMed 10427513).');
