INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI310', 'H118', 'drug_interaction', 'Lithium', 'moderate', 'The seed''s mild diuretic effect can reduce renal lithium clearance, allowing serum lithium to rise toward toxic levels', 'Use only under medical supervision with lithium; monitor serum lithium and adjust dose as directed by the prescriber', 'Natural Medicines Comprehensive Database (Pumpkin); MedlinePlus Herbs and Supplements (Pumpkin)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI311', 'H118', 'drug_interaction', 'Diuretic medications', 'moderate', 'Mild additive diuresis may increase fluid and electrolyte loss', 'Use cautiously with prescription diuretics; watch for dehydration or electrolyte imbalance', 'Natural Medicines Comprehensive Database (Pumpkin); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI312', 'H118', 'other', 'Pumpkin-seed allergy', 'moderate', 'Rare IgE-mediated hypersensitivity to pumpkin seed protein', 'Avoid in anyone with known pumpkin-seed or cucurbit-seed allergy', 'Natural Medicines Comprehensive Database (Pumpkin); NCCIH');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI313', 'H118', 'pregnancy', 'Pregnancy (high medicinal/anthelmintic doses)', 'moderate', 'Food and standard supplemental amounts are considered safe, but large anthelmintic doses have not been formally studied in pregnancy', 'Culinary and standard supplemental amounts acceptable; reserve high anthelmintic doses for professional supervision', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); NCCIH');
