INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS18', 'Primary', 'Tension: relaxes nervous and muscular tension and the tight, spasmodic, irritable cough.');
