INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS05', 'Secondary', 'Excess Heat: cooling to hot, irritable, over-sensitive tissue and nervous heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS06', 'Minor', 'Acute Inflammation: mild anti-inflammatory and analgesic for inflamed, painful tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS17', 'Primary', 'Cold: the cooling latex aggravates cold, under-functioning terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS11', 'Secondary', 'Depression: a sedating depressant deepens depressed, under-functioning states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS01', 'Secondary', 'Deficiency: sedation and cooling further deplete the deficient.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS04', 'Secondary', 'Exhaustion: lowers vitality in the already exhausted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS03', 'Minor', 'Dryness: the drying, anticholinergic tendency worsens dry tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H119', 'TS19', 'Minor', 'Torpor: dulls the already torpid and sluggish.');
