INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H119', 'SY07', 'Primary', 'Respiratory: antitussive for irritable, tickling, spasmodic cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H119', 'SY04', 'Secondary', 'Musculoskeletal: antispasmodic and anodyne for cramp, spasm, and pain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H119', 'SY03', 'Minor', 'Reproductive: eases painful cramping periods; traditional anaphrodisiac.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H119', 'SY08', 'Minor', 'Digestive: bitter; eases colic and griping.');
