INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H119', 'A10', 'Secondary', 'Antispasmodic: for cramp, colic, and spasmodic cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H119', 'A33', 'Secondary', 'Antitussive: quiets the dry, irritable, tickling cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H119', 'A26', 'Secondary', 'Anxiolytic: eases restlessness and nervous agitation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H119', 'A16', 'Minor', 'Bitter Tonic: bitter latex mildly stimulates digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H119', 'A09', 'Minor', 'Anti-inflammatory: mild, via lactucopicrin and related lactones.');
