INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP10', 'Primary', 'Anxiety and nervous agitation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP50', 'Primary', 'Dry, irritable, tickling, or spasmodic cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP39', 'Secondary', 'Muscular tension and spasm.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP37', 'Secondary', 'Muscle cramps.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP77', 'Secondary', 'Generalized pain (the anodyne use).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP22', 'Secondary', 'Neuralgia.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP29', 'Minor', 'Dysmenorrhea: painful, cramping periods.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H119', 'CP19', 'Minor', 'Nervous and tension headache.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H119', 'P01', 'Primary', 'Tincture of leaf or lactucarium, the classic Eclectic form.');
