INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H119', 'C01', 'Indicated', 'Secondary', 'Sanguine: warm, over-excited, restless; cooled and quieted.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898): Lactucarium and Lactuca.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898): Lactucarium and Lactuca.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Lettuce, Wild; Besharat S, Besharat M, Jabbari A, Wild lettuce (Lactuca virosa) toxicity, BMJ Case Reports 2009;2009:bcr06.2008.0134; Wesolowska A, Nikiforuk A, Michalska K, Kisiel W, Chojnacka-Wojcik E, Anal", "locator": "Grieve, A Modern Herbal (1931): Lettuce, Wild; Besharat S, Besharat M, Jabbari A, Wild lettuce (Lactuca virosa) toxicity, BMJ Case Reports 2009;2009:bcr06.2008.0134; Wesolowska A, Nikiforuk A, Michalska K, Kisiel W, Chojnacka-Wojcik E, Anal", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
