INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI314', 'H119', 'pregnancy', 'Pregnancy', 'moderate', 'CNS-active, sedative, mildly anticholinergic herb with inadequate human safety data; potential fetal CNS exposure.', 'Avoid during pregnancy; no established safe dose.', 'WebMD wild lettuce monograph; Mills and Bone, Principles and Practice of Phytotherapy (precautionary; no AHPA class located).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI315', 'H119', 'breastfeeding', 'Breastfeeding', 'moderate', 'Sedative, CNS-active constituents may pass into breast milk; no lactation safety data.', 'Avoid while breastfeeding.', 'WebMD wild lettuce monograph (precautionary; no LactMed entry).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI316', 'H119', 'pediatric', 'Infants and young children', 'moderate', 'Narrow margin CNS depressant; children are more vulnerable to sedation and to the anticholinergic toxidrome. Youngest documented toxicity case was age 12.', 'Do not use in infants or young children; adolescents only under professional supervision.', 'Besharat, Besharat and Jabbari, BMJ Case Reports 2009; WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI317', 'H119', 'drug_interaction', 'Sedatives, hypnotics, benzodiazepines, barbiturates, opioids, alcohol, and sedating herbs', 'moderate', 'Additive central nervous system depression and sedation.', 'Do not combine; avoid alcohol; caution with any sedating medication or herb.', 'WebMD wild lettuce monograph; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI318', 'H119', 'drug_interaction', 'Anesthesia and perioperative CNS depressants', 'moderate', 'Additive CNS depression with anesthetic agents.', 'Discontinue at least one to two weeks before elective surgery.', 'Mills and Bone (general CNS-depressant herb precaution); WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI319', 'H119', 'drug_interaction', 'Anticholinergic drugs', 'moderate', 'Overdose produces an anticholinergic-type toxidrome (dry mouth, urinary retention, mydriasis, blurred vision); theoretical additive anticholinergic burden.', 'Use caution with anticholinergic medications, and in narrow-angle glaucoma, BPH, or urinary retention.', 'Besharat et al., BMJ Case Reports 2009 (anticholinergic toxidrome).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI320', 'H119', 'other', 'Overdose or excessive/raw-plant ingestion', 'moderate', 'Narrow therapeutic margin; excess causes agitation, hallucinations, mydriasis, tachycardia, urinary retention, diaphoresis, and stupor.', 'Practitioner-dosed only; do not dose-stack; seek emergency care for overdose signs.', 'Besharat, Besharat and Jabbari, BMJ Case Reports 2009 (8-patient toxicity series).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI321', 'H119', 'other', 'Asteraceae (daisy family) allergy', 'low', 'Sesquiterpene lactones can trigger allergy or contact dermatitis in Asteraceae-sensitive people.', 'Avoid in known Asteraceae/Compositae allergy.', 'Herbal Reality wild lettuce monograph; general sesquiterpene-lactone allergy literature.');
