INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI322', 'H120', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional emmenagogue and deobstruent; larger doses (above roughly 2 g of powder) are reported to provoke menstrual spotting and may stimulate the uterus. No modern reproductive-toxicology data.', 'Avoid throughout pregnancy. Prefer better-studied nervines under supervision if a calming herb is needed.', 'AHPA Botanical Safety Handbook (2nd ed.); NCCIH (insufficient-data principle); Drugs.com / Natural Medicines, Jatamansi.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI323', 'H120', 'breastfeeding', 'Breastfeeding', 'moderate', 'Sedative sesquiterpene constituents could pass into breast milk; no human lactation data and no NIH LactMed monograph.', 'Avoid or use only under professional supervision; safety not established.', 'NIH LactMed (no monograph on record); Drugs.com / Natural Medicines; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI324', 'H120', 'pediatric', 'Infants and young children', 'moderate', 'Marked sedative action; modern pediatric safety and dosing not established.', 'Avoid in infants and young children; use in older children only under a qualified practitioner.', 'NCCIH (insufficient-data principle); AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI325', 'H120', 'drug_interaction', 'CNS depressants (benzodiazepines, barbiturates, opioids, sedating antihistamines, sedative herbs, alcohol)', 'moderate', 'Additive central nervous system depression; jatamansi has documented CNS-depressant/sedative activity.', 'Avoid combining or use only under supervision; warn about drowsiness and impaired alertness for driving.', 'Brinker, Herb Contraindications and Drug Interactions; Mills and Bone; CNS-depressant study, PMC9261992 (2022).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI326', 'H120', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Additive blood-pressure lowering; jatamansone and related sesquiterpenes are documented hypotensives.', 'Use cautiously with antihypertensives; monitor blood pressure. Caution in those already hypotensive.', 'Brinker; Mills and Bone; pharmacology review, Oriental Journal of Chemistry 32(2) (2016).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI327', 'H120', 'drug_interaction', 'Antiarrhythmics and cardiac glycosides (e.g., digoxin)', 'moderate', 'Documented antiarrhythmic activity of jatamansone may add to or interfere with cardiac-rhythm drugs.', 'Use cautiously and under medical supervision in those on antiarrhythmic or cardiac-glycoside therapy.', 'Brinker; pharmacology reviews of N. jatamansi (jatamansone antiarrhythmic activity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI328', 'H120', 'other', 'Major surgery / general anesthesia', 'moderate', 'Additive CNS-depressant and hypotensive effects with anesthetic agents.', 'Discontinue at least one to two weeks before scheduled surgery.', 'Brinker; Mills and Bone (general sedative-botanical peri-operative principle).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI329', 'H120', 'other', 'CITES Appendix II, IUCN Critically Endangered', 'moderate', 'Wild rhizome is harvested by destructive whole-plant uprooting; the species is critically endangered and internationally trade-restricted, and adulteration with Valeriana jatamansi is common.', 'Use sparingly or substitute; source only cultivated material with legal CITES documentation and verified identity.', 'CITES Appendix II (1997); IUCN Red List 2021 (e.T50126627A88304158); United Plant Savers.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H120', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Spikenard (the Indian or true nard, Nardostachys jatamansi, distinguished from American Spikenard, Aralia racemosa).", "locator": "Grieve, A Modern Herbal (1931), Spikenard (the Indian or true nard, Nardostachys jatamansi, distinguished from American Spikenard, Aralia racemosa).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Nadkarni, Indian Materia Medica (Nardostachys jatamansi); Warrier et al., Indian Medicinal Plants (Arya Vaidya Sala); AHPA Botanical Safety Handbook (2nd ed.); NCCIH; Drugs.com / Natural Medicines Comprehensive Database, Jatamansi; Brinker,", "locator": "Nadkarni, Indian Materia Medica (Nardostachys jatamansi); Warrier et al., Indian Medicinal Plants (Arya Vaidya Sala); AHPA Botanical Safety Handbook (2nd ed.); NCCIH; Drugs.com / Natural Medicines Comprehensive Database, Jatamansi; Brinker,", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
