INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI330', 'H121', 'pregnancy', 'Pregnancy', 'moderate', 'Cumin has traditional emmenagogue use, and limited animal data suggest possible antifertility or anti-implantation activity at high doses; human safety at therapeutic doses is not established.', 'Culinary/food amounts are considered safe (GRAS). Avoid concentrated therapeutic doses, seed extracts and the essential oil during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed.; Drugs.com and WebMD cumin monographs (2024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI331', 'H121', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas e.g. glyburide, metformin)', 'moderate', 'Cumin has demonstrated blood-glucose-lowering activity; additive pharmacodynamic effect may cause hypoglycemia.', 'Monitor blood glucose closely; antidiabetic dose adjustment may be needed at therapeutic cumin doses.', 'Ansari et al. 2019, pharmacodynamic interaction of cumin with glyburide, PMID 31348760; WebMD and Drugs.com cumin monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI332', 'H121', 'other', 'Scheduled surgery', 'moderate', 'Blood-sugar-lowering effect may interfere with glycemic control during and after surgery.', 'Discontinue therapeutic doses at least two weeks before scheduled surgery.', 'WebMD cumin monograph (2024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI333', 'H121', 'other', 'Apiaceae allergy; cumin essential oil', 'low', 'Possible cross-reactivity in people sensitive to other Apiaceae (caraway, fennel, coriander, celery); phototoxic contact reactions reported with the essential oil.', 'Patch-test the essential oil, keep it diluted, and avoid sun exposure on treated skin; do not take the essential oil internally undiluted.', 'Drugs.com and NCBI LactMed cumin monographs.');
