INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI334', 'H122', 'population', 'Pregnancy', 'absolute', 'Traditional emmenagogue and abortifacient; the pinocamphone-rich essential oil is a documented convulsant and a uterine stimulant in large doses.', 'Avoid during pregnancy, especially the essential oil and concentrated extracts.', 'AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI335', 'H122', 'condition', 'Epilepsy or seizure disorders', 'absolute', 'Pinocamphone and isopinocamphone in the essential oil are neurotoxic convulsants that lower the seizure threshold; human seizures have followed ingestion of hyssop oil.', 'Do not use the essential oil or high-dose extracts; those with seizure disorders should avoid concentrated hyssop preparations altogether.', 'Tisserand and Young, Essential Oil Safety, 2nd ed. (2014); published convulsant essential-oil case reports.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI336', 'H122', 'drug_interaction', 'Anticonvulsant and antiepileptic medications', 'moderate', 'The convulsant essential oil may lower the seizure threshold and antagonize the effect of antiepileptic drugs.', 'Avoid the essential oil; monitor closely if any hyssop preparation is used alongside antiseizure therapy.', 'Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI337', 'H122', 'drug_interaction', 'Blood-glucose-lowering (antidiabetic) drugs and insulin', 'low', 'Hyssop extracts show hypoglycemic activity in animal studies; theoretical additive lowering of blood glucose.', 'Monitor blood glucose if combined; human data are limited.', 'Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI338', 'H122', 'population', 'Lactation', 'moderate', 'No reliable safety data in breastfeeding; the essential oil is neurotoxic.', 'Avoid the essential oil; use whole-herb tea only if clearly needed and in moderation.', 'Restorative Medicine Hyssop monograph; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI339', 'H122', 'population', 'Infants and young children', 'absolute', 'Essential oils containing pinocamphone and camphor can cause seizures and respiratory distress in children.', 'Never give the essential oil internally to children and keep the oil away from the face of infants; mild tea only, sparingly, in older children.', 'NCCIH; AHPA Botanical Safety Handbook, 2nd ed.');
