INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H123', 'C01', 'Indicated', 'Primary', 'Sanguine: warm, damp, plethoric tissue that the astringent tones and the cool tempers.', '{"title": "Grieve''s A Modern Herbal (1931): Self-Heal (All-Heal, Prunella vulgaris).", "locator": "Grieve''s A Modern Herbal (1931): Self-Heal (All-Heal, Prunella vulgaris).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper''s Complete Herbal (1653): Self-Heal; Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Xia Ku Cao / Spica Prunellae); Bai Y. et al., Prunella vulgaris L.: A Review of its Ethnopharmacology, Phytochemistry, Quality Control", "locator": "Culpeper''s Complete Herbal (1653): Self-Heal; Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Xia Ku Cao / Spica Prunellae); Bai Y. et al., Prunella vulgaris L.: A Review of its Ethnopharmacology, Phytochemistry, Quality Control", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H123', 'C02', 'Indicated', 'Secondary', 'Choleric: cooling clears heat and fire.', '{"title": "Grieve''s A Modern Herbal (1931): Self-Heal (All-Heal, Prunella vulgaris).", "locator": "Grieve''s A Modern Herbal (1931): Self-Heal (All-Heal, Prunella vulgaris).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper''s Complete Herbal (1653): Self-Heal; Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Xia Ku Cao / Spica Prunellae); Bai Y. et al., Prunella vulgaris L.: A Review of its Ethnopharmacology, Phytochemistry, Quality Control", "locator": "Culpeper''s Complete Herbal (1653): Self-Heal; Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Xia Ku Cao / Spica Prunellae); Bai Y. et al., Prunella vulgaris L.: A Review of its Ethnopharmacology, Phytochemistry, Quality Control", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
