INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI340', 'H123', 'pregnancy', 'Pregnancy (internal medicinal use)', 'moderate', 'Safety not established; no adequate human data for a cold, bitter herb of unknown reproductive activity.', 'Avoid internal medicinal use in pregnancy; limit to topical wound care or dilute gargles under qualified guidance.', 'WebMD / NCCIH consumer safety summary (safety not established); no specific rating located in modern safety references.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI341', 'H123', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety not established; no lactation data.', 'Avoid internal medicinal use while breastfeeding pending data.', 'WebMD / NCCIH consumer safety summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI342', 'H123', 'drug_interaction', 'Antihypertensive medications', 'moderate', 'Documented vasorelaxant, blood-pressure-lowering activity may be additive.', 'Monitor blood pressure; caution in existing hypotension or when combined with BP medication.', 'Bai et al., Front. Pharmacol. 2022;13:903171 (antihypertensive activity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI343', 'H123', 'drug_interaction', 'Antidiabetic / hypoglycemic medications', 'moderate', 'Documented glucose-lowering activity may be additive, risking hypoglycemia.', 'Monitor blood glucose; coordinate dose changes with the prescriber.', 'Bai et al., Front. Pharmacol. 2022;13:903171 (hypoglycemic activity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI344', 'H123', 'condition', 'Spleen / Stomach deficiency (cold, weak digestion)', 'moderate', 'Cold, bitter, drying nature aggravates cold-deficient digestion, causing loose stools or poor appetite.', 'Avoid prolonged internal use; if needed, pair with warming, digestive herbs.', 'Bensky and Gamble, Chinese Herbal Medicine: Materia Medica; Front. Pharmacol. 2022 review.');
