INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H124', 'Clove (Lavanga)', 'Syzygium aromaticum', 'Myrtaceae', 'Dried flower bud', 'Pungent, Bitter, Astringent', 'Hot', 'Dry', 'Cold, torpor and atony of digestion, damp-cold stagnation, gas and griping from a chilled gut.', 'Excess heat, acute inflammation, dryness, irritated or ulcerated mucosa.', 'Digestive (primary), Respiratory, Nervous (local anodyne), Immune (antimicrobial); Reproductive and Kidney-yang in Ayurveda and TCM.', 'Toothache and oral pain, nausea and vomiting, indigestion, bloating and flatulence, cold-type dyspepsia, halitosis, intestinal worms; topical antiseptic.', 'Cold, damp, atonic constitutions; the chilly, sluggish phlegmatic digestion that pools gas and mucus.', 'Kapha, Vata', 'Pitta', 'Spleen and Stomach cold (deficiency) with rebellious qi (vomiting, hiccup, poor appetite); Kidney yang deficiency (as Ding Xiang).', 'Heat and fire patterns, yin deficiency with heat signs; classically regarded as incompatible with Yu Jin (Radix Curcumae).', 'Concentrated clove essential oil is a mucosal and dermal irritant and can damage dental pulp and gums with repeated undiluted use. Internal use of the essential oil is hazardous. Keep clove oil away from children.', 'Known eugenol or clove hypersensitivity; active GI ulceration or acute gastritis (hot, irritant herb); bleeding disorders. Do not ingest the undiluted essential oil.', 'Culinary amounts of clove bud are considered safe (FDA GRAS). Therapeutic doses, concentrated supplements, and clove essential oil are not recommended in pregnancy: eugenol has antiplatelet activity and is a mucosal irritant at concentration. Source: AHPA Botanical Safety Handbook, 2nd ed. (2013); NCCIH/LiverTox.', 'Culinary use is compatible with lactation. Modern data on therapeutic doses and clove oil are insufficient; avoid concentrated internal use of the essential oil while nursing. Source: AHPA Botanical Safety Handbook, 2nd ed. (2013); Mills & Bone, Principles and Practice of Phytotherapy.', 'Culinary clove is fine. Clove essential oil must NOT be given internally to infants or children and is not recommended for teething; ingestion of 5 to 10 mL has caused fulminant hepatic failure, seizures, CNS depression, and disseminated intravascular coagulation. Source: LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251.', 'Anticoagulants and antiplatelets (warfarin, aspirin, clopidogrel, NSAIDs, apixaban): eugenol inhibits platelet aggregation and may add to bleeding risk, especially as clove oil or concentrated supplements; culinary amounts are low-risk. Theoretical additive sedation with CNS depressants at high oil doses. Source: Drugs.com professional interactions monograph (clove/warfarin, clove/apixaban); Mills & Bone.', 'Powder, infusion (tea), decoction, tincture, essential oil (diluted, topical and dental only), added to foods and soups, compress.', 'Powder or culinary bud: 0.5 to 2 g dried bud daily. Infusion: 1 to 3 buds (or about 1 g powdered) steeped in hot water, up to 2 to 3x daily. Tincture (1:5, 45%): 0.5 to 2 mL up to 3x daily. Dental: clove essential oil diluted in a carrier, applied sparingly to the affected tooth; do not swallow.', 'King''s American Dispensatory (Felter & Lloyd, 1898): Caryophyllus (Cloves).', 'Grieve, A Modern Herbal (1931), Cloves; Mills & Bone, Principles and Practice of Phytotherapy; NCCIH/LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251; AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aromaticum; Drugs.com professional interactions monograph.', 'Volatile oil is 15 to 20% of the dried bud, of which eugenol is roughly 70 to 90% (with eugenyl acetate and beta-caryophyllene); the bud also carries tannins, giving its light astringency. Eugenol is both the therapeutic principle (dental anodyne, antiseptic, carminative) and the toxic principle at concentration, which is why the whole bud is a gentle kitchen spice while the essential oil is a hazard. Known as Ding Xiang in TCM (warms the middle, directs rebellious Stomach qi downward, warms Kidney yang) and Lavanga in Ayurveda (ushna, katu; kapha-vata pacifying, pitta aggravating).', 'Not named in canonical Scripture. Native to the Maluku (Spice) Islands of Indonesia; reached the Mediterranean only as a costly trade spice, described by the Roman world (Pliny the Elder, Natural History, 1st c. AD, as ''caryophyllon''). A classical Ayurvedic dravya (Lavanga). Included in this materia medica among the Ayurvedic and Mediterranean-trade aromatics.', 'Widely cultivated (Zanzibar and Pemba, Madagascar, Indonesia, Sri Lanka); not wild-at-risk and not on the United Plant Savers list. Prefer organic, fair-trade sourcing to support growing communities.', 'Hot, dry aromatic stimulant: kindles cold, torpid digestion, disperses gas and damp-cold stagnation, and numbs pain (eugenol) where tissues are chilled and atonic, not hot or inflamed.', 'Severe or spreading dental infection, facial swelling, or fever (needs a dentist, not clove oil); persistent vomiting, blood in vomit or stool, or severe abdominal pain; unusual bruising or bleeding; any ingestion of clove essential oil by a child (medical emergency).', 'Clove: klohv. Latin Syzygium aromaticum: si-ZIJ-ee-um a-roh-MAT-ih-kum.', 'free', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Caryophyllus (Cloves).", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Caryophyllus (Cloves).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cloves; Mills & Bone, Principles and Practice of Phytotherapy; NCCIH/LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251; AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aroma", "locator": "Grieve, A Modern Herbal (1931), Cloves; Mills & Bone, Principles and Practice of Phytotherapy; NCCIH/LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251; AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aroma", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
