INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H124', 'TCM07', 'Secondary', 'Depletes fluids in yin-deficient heat.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Caryophyllus (Cloves).", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Caryophyllus (Cloves).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cloves; Mills & Bone, Principles and Practice of Phytotherapy; NCCIH/LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251; AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aroma", "locator": "Grieve, A Modern Herbal (1931), Cloves; Mills & Bone, Principles and Practice of Phytotherapy; NCCIH/LiverTox, Eugenol (Clove Oil), NBK551727; Eur J Pediatr 2005, PMID 15895251; AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aroma", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI345', 'H124', 'pediatric', 'Infants and children: clove essential oil (ingested or used for teething)', 'absolute', 'Eugenol is hepatotoxic and CNS-active in concentration; ingestion of 5 to 10 mL of clove oil has caused fulminant hepatic failure, seizures, CNS depression, metabolic acidosis, and disseminated intravascular coagulation in young children.', 'Never give clove essential oil internally to infants or children and do not use it for teething. Culinary clove in food is fine. Any pediatric ingestion of clove oil is a medical emergency (N-acetylcysteine may be indicated).', 'LiverTox, Eugenol (Clove Oil), NCBI Bookshelf NBK551727; Eur J Pediatr 2005 (PMID 15895251).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI346', 'H124', 'drug_interaction', 'Anticoagulants and antiplatelets (warfarin, aspirin, clopidogrel, NSAIDs, apixaban)', 'moderate', 'Eugenol inhibits platelet aggregation, which can be additive with anticoagulant and antiplatelet drugs and raise bleeding risk, particularly from clove oil or concentrated supplements.', 'Avoid concentrated clove oil and supplements with these medications; culinary amounts are low-risk. Monitor for bruising or bleeding if used regularly.', 'Drugs.com professional interactions monograph (clove/warfarin, clove/apixaban); Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI347', 'H124', 'pregnancy', 'Pregnancy: therapeutic doses, concentrated supplements, and clove essential oil', 'moderate', 'Eugenol has antiplatelet activity and is a mucosal irritant at concentration; safety of medicinal doses in pregnancy is not established, whereas culinary bud is considered safe (FDA GRAS).', 'Culinary clove is acceptable. Avoid clove essential oil and concentrated clove supplements during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), Syzygium aromaticum; NCCIH/LiverTox.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI348', 'H124', 'condition', 'Bleeding disorders; two weeks before scheduled surgery', 'moderate', 'Antiplatelet effect of eugenol may worsen bleeding tendency and interfere with surgical hemostasis.', 'Discontinue concentrated clove products before surgery and in patients with clotting disorders.', 'Mills & Bone, Principles and Practice of Phytotherapy; Drugs.com professional monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI349', 'H124', 'other', 'Undiluted clove essential oil on skin, gums, or dental pulp', 'moderate', 'Concentrated eugenol is a mucosal and dermal irritant; repeated or undiluted application can cause contact dermatitis, mucosal burns, and dental pulp and gum tissue damage.', 'Always dilute clove oil in a carrier and apply sparingly and briefly; do not apply neat to gums or skin.', 'LiverTox NBK551727; AHPA Botanical Safety Handbook, 2nd ed. (2013).');
