INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H125', 'TCM01', 'Primary', 'Cooling aggravates Kidney Yang deficiency', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590).", "locator": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590)."}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H125', 'TCM13', 'Secondary', 'Cold nature unsuited to Wind-Cold', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590).", "locator": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590)."}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H125', 'TCM10', 'Minor', 'Can be cloying in Dampness/Phlegm', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. 1 - Amalaki (Emblica officinalis / Phyllanthus emblica). Classical: Bhavaprakasha Nighantu - Amalaki; Charaka Samhita (Rasayana chapters).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590).", "locator": "Frawley & Lad, The Yoga of Herbs; Pole, Ayurvedic Medicine; Williamson, Major Herbs of Ayurveda; modern reviews (PMC10637531, PMC7801590)."}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI350', 'H125', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Amla exhibits measurable antiplatelet activity; an additive effect can increase bleeding risk.', 'Avoid high-dose or extract use alongside blood thinners; monitor for bruising or bleeding and coordinate with the prescriber.', 'Modern pharmacology reviews of amla antiplatelet activity; Mills & Bone herb-drug interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI351', 'H125', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Additive blood-glucose-lowering effect may cause hypoglycemia.', 'Monitor blood glucose; adjust medication only under professional supervision.', 'Modern reviews of amla hypoglycemic activity.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI352', 'H125', 'condition', 'Bleeding disorders and perioperative period', 'moderate', 'Antiplatelet activity may prolong bleeding.', 'Discontinue high-dose or extract use roughly one to two weeks before scheduled surgery.', 'Modern pharmacology reviews of amla antiplatelet activity.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI353', 'H125', 'pregnancy', 'Pregnancy (high-dose or medicinal use)', 'moderate', 'Insufficient human safety data for supplemental or extract doses; culinary amounts of the fruit are considered safe with no established teratogenicity.', 'Limit to culinary amounts; avoid high-dose supplements unless supervised.', 'Modern reviews note limited pregnancy safety data (NCCIH-style insufficient-data precaution).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI354', 'H125', 'breastfeeding', 'Breastfeeding (high-dose or medicinal use)', 'moderate', 'Insufficient lactation safety data for supplemental doses.', 'Culinary amounts acceptable; avoid medicinal high doses without professional guidance.', 'Modern reviews cite a lack of lactation studies.');
