INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H126', 'Haritaki', 'Terminalia chebula', 'Combretaceae', 'Fruit (pericarp)', 'Astringent, Sour, Bitter, Pungent, Sweet', 'Warm', 'Dry', 'Laxity (tones lax, boggy bowel and prolapsing, atonic tissue), Dampness (dries damp accumulation), Torpor and Stagnation (moves a sluggish, congested bowel downward). Its amphoteric action both binds a leaking bowel and unblocks a stuck one.', 'Dryness (astringency worsens dehydration and dry, depleted tissue), Exhaustion (avoid the purgative dose in the acutely spent or emaciated, though as a slow rasayana it rebuilds over time), Excess Heat (warming potency can inflame heat and bleeding).', 'Digestive (primary: bowel, agni, assimilation), Respiratory and Lungs (chronic cough, hoarseness, lost voice), Immune (rasayana rejuvenation); secondarily the Integumentary and Urinary systems.', 'Chronic constipation and sluggish, incomplete elimination; the opposite presentation of chronic loose stool, diarrhea, and dysentery (its astringency binds a lax bowel); bloating, poor appetite, and weak digestion; chronic cough, hoarseness, and loss of voice; general rasayana rejuvenation and healthy aging.', 'Cold-Damp-Relaxed and torpid: the sluggish, congested, lax-tissued phenotype with a boggy or atonic bowel. Also suits the depleted, Vata-dry constitution for rejuvenation, but only when the fruit is anointed with ghee or taken in warm water to offset its dryness.', 'Vata (primary), Kapha. Classically named tridoshic, but its action is strongest on Vata.', 'Pitta (its warming, ushna potency and drying quality can aggravate heat, thirst, or the dehydrated when overused or taken without a cooling, unctuous anupana).', 'He Zi (诃子): astringes the Intestines to bind chronic diarrhea and dysentery, and astringes the Lung to stop chronic cough and restore a lost voice. Enters the Lung and Large Intestine channels, suiting leakage and deficiency patterns.', 'Early-stage cough or diarrhea with an unresolved exterior pathogen, and acute Damp-Heat dysentery or interior excess with food stagnation, where astringing is premature.', 'Warming and drying, so large or prolonged doses can aggravate dryness, thirst, and Pitta-type heat, and may further deplete the very lean, dehydrated, or exhausted. Overdose causes griping and loose stools. Do not astringe an acute infectious diarrhea or dysentery before the pathogen has cleared.', 'Pregnancy (purgative, downward-moving action). Acute dehydration or recent excessive purging or fluid loss. Marked emaciation, debility, or exhaustion. Bowel obstruction. Acute febrile or exterior illness with an unexpelled pathogen.', 'Avoid. Traditionally contraindicated in Ayurveda for its downward-moving, purgative action, and modern clinical references rate Terminalia chebula as possibly unsafe taken orally in pregnancy because of its laxative-stimulant effect and the lack of human safety data. Source: NCCIH-aligned clinical monographs (Drugs.com Terminalia; WebMD), consistent with classical Ayurvedic contraindication.', 'Avoid, or use only under qualified supervision. Reliable lactation data are lacking, and traditional use regards Haritaki as tending to reduce breast milk. Source: consolidated clinical monographs (Drugs.com; WebMD) noting insufficient breastfeeding data, plus traditional Ayurvedic caution.', 'No established pediatric safety data for self-selected use. In Ayurvedic practice it is given to children only in small, adjusted doses; avoid the laxative dose in young children and use only under a qualified practitioner. Source: insufficient modern pediatric data (NCCIH-aligned monographs).', 'Antidiabetic drugs (insulin, sulfonylureas, metformin): Haritaki lowers blood glucose (chebulagic and chebulinic acid), so it may add to hypoglycemic medications; monitor blood sugar. CYP450: in vitro fruit fractions inhibit CYP450 enzymes, a theoretical interaction with drugs cleared by those enzymes (clinical significance unproven). Tannins: its high tannin content can bind and reduce absorption of iron, minerals, alkaloids, and some oral drugs; separate dosing by about 2 hours. As a laxative it can shorten transit time and reduce absorption of drugs taken at the same time. Sources: Mills & Bone, Principles and Practice of Phytotherapy; NCCIH; Drugs.com and WebMD Terminalia monographs; in vitro CYP450 and antidiabetic-activity studies.', 'Powder (churna, most common), decoction (kwath), capsule or tablet, tincture. A strong decoction is used cooled as a gargle for sore throat and hoarseness. Traditionally paired with an anupana (ghee, honey, rock salt, or warm water) matched to the dosha and the desired action.', 'Powder (churna): 1-2 g once or twice daily as a digestive and rasayana tonic; 3-6 g in warm water at bedtime for gentle laxative action. Decoction: 3-6 g dried fruit. Gargle: strong decoction, cooled. Start low and titrate to a comfortable stool.', 'Grieve''s A Modern Herbal (1931), heading Myrobalans (Chebulic).', 'Ayurvedic Pharmacopoeia of India, Part I (Haritaki); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (He Zi); Williamson (ed.), Major Herbs of Ayurveda; NCCIH; Drugs.com and WebMD Terminalia monographs.', 'Fruit pericarp is rich in hydrolyzable tannins (chebulinic and chebulagic acids, gallic and ellagic acids, corilagin, punicalagin, terflavin A), which underlie its dual, amphoteric bowel action: astringent and binding at low dose, gently laxative at higher dose. Chief of the three fruits in Triphala and lead rasayana of Ayurveda, praised in the Charaka and Sushruta Samhitas as ''abhaya'' (the fearless). Documented antioxidant, antimicrobial, and blood-glucose-lowering activity. Bounding cautions: warming and drying, so anoint with ghee for dry constitutions and avoid in pregnancy, acute dehydration, and marked depletion.', 'Not in canonical biblical texts; native to South and Southeast Asia. Foremost in Ayurveda (Charaka Samhita, Sushruta Samhita) as chief of the rasayana fruits and lead ingredient of Triphala, and known in Traditional Chinese Medicine as He Zi (诃子).', 'Not listed by United Plant Savers, whose at-risk list tracks North American species. Widely cultivated across its native South Asian range; choose cultivated or responsibly wild-harvested fruit, since localized overharvest and habitat pressure affect some wild stands.', 'Warm, dry, and astringent yet downward-moving: it tones and dries lax, boggy tissue while coaxing a torpid bowel to release; the rejuvenating rasayana that both binds and unbinds.', 'Refer for constipation or diarrhea persisting beyond 2 weeks despite use, blood in stool, black tarry stools, unexplained weight loss, severe or persistent abdominal pain, a new change in bowel habit after age 50, or fever with dysentery.', 'Haritaki: hah-ree-TAH-kee · Terminalia chebula: ter-mih-NAY-lee-uh keh-BYOO-lah.', 'free', 'Approved', '{"title": "Grieve''s A Modern Herbal (1931), heading Myrobalans (Chebulic).", "locator": "Grieve''s A Modern Herbal (1931), heading Myrobalans (Chebulic).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I (Haritaki); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (He Zi); Williamson (ed.), Major Herbs of Ayurveda; NCCIH; Drugs.com and WebMD Terminalia monographs.", "locator": "Ayurvedic Pharmacopoeia of India, Part I (Haritaki); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (He Zi); Williamson (ed.), Major Herbs of Ayurveda; NCCIH; Drugs.com and WebMD Terminalia monographs.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
