INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H126', 'TCM10', 'Secondary', 'Acute Damp-Heat dysentery or interior damp/food-stagnation excess; astringing is premature.', '{"title": "Grieve''s A Modern Herbal (1931), heading Myrobalans (Chebulic).", "locator": "Grieve''s A Modern Herbal (1931), heading Myrobalans (Chebulic).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I (Haritaki); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (He Zi); Williamson (ed.), Major Herbs of Ayurveda; NCCIH; Drugs.com and WebMD Terminalia monographs.", "locator": "Ayurvedic Pharmacopoeia of India, Part I (Haritaki); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (He Zi); Williamson (ed.), Major Herbs of Ayurveda; NCCIH; Drugs.com and WebMD Terminalia monographs.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI355', 'H126', 'population', 'Pregnancy', 'absolute', 'Downward-moving, purgative (bhedana/anulomana) action of a laxative-stimulant fruit; human safety data lacking.', 'Avoid during pregnancy.', 'Classical Ayurvedic contraindication; Drugs.com and WebMD Terminalia monographs (rated possibly unsafe in pregnancy).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI356', 'H126', 'population', 'Breastfeeding / lactation', 'moderate', 'Insufficient lactation safety data; traditional tendency to reduce breast milk.', 'Avoid, or use only under qualified supervision while nursing.', 'Drugs.com and WebMD Terminalia monographs; traditional Ayurvedic caution.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI357', 'H126', 'drug_interaction', 'Antidiabetic / hypoglycemic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Additive blood-glucose lowering from chebulagic and chebulinic acids.', 'Monitor blood glucose; watch for hypoglycemia and adjust doses with the prescriber.', 'Mills & Bone, Principles and Practice of Phytotherapy; WebMD; antidiabetic-activity studies (chebulagic acid).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI358', 'H126', 'drug_interaction', 'Oral drugs, iron, and mineral supplements taken concurrently', 'low', 'High tannin content binds and reduces absorption; laxative action shortens transit time.', 'Separate dosing from other oral medicines and supplements by about 2 hours.', 'Mills & Bone; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI359', 'H126', 'drug_interaction', 'Drugs metabolized by CYP450 enzymes', 'low', 'In vitro fruit fractions inhibit CYP450; clinical relevance unproven.', 'Theoretical caution with narrow-therapeutic-index CYP substrates; monitor and consult a prescriber.', 'In vitro CYP450 inhibition studies (Terminalia chebula ethyl acetate fraction).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI360', 'H126', 'condition', 'Acute dehydration, marked emaciation or debility, bowel obstruction, acute infectious dysentery', 'moderate', 'Drying and purgative action worsens fluid depletion; premature astringing can trap an unresolved pathogen.', 'Avoid in these states and treat the acute cause first.', 'Classical Ayurvedic and TCM contraindications; Bensky and Gamble, Materia Medica (He Zi).');
