INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H127', 'Senna', 'Senna alexandrina', 'Fabaceae (Leguminosae)', 'Leaf (leaflets) and pod (fruit)', 'Bitter', 'Cold', 'Dry', 'Stagnation and torpor of the bowel; excess, heat-bound constipation with abdominal fullness and congestion.', 'Deficiency, exhaustion, and dryness; cold, atonic, or lax bowel; the atrophic, laxative-dependent bowel.', 'Digestive (large intestine and colon).', 'Occasional constipation; short-term relief of sluggish, atonic, or heat-type constipation; bowel evacuation before diagnostic or surgical procedures.', 'Hot-Excess-Tense; the robust, congested, heat-bound phenotype with acute stagnant constipation. Wrong for the cold, thin, depleted, or dried-out.', 'Kapha, Pitta', 'Vata', 'Heat accumulation in the Large Intestine (Yang Ming) with dry, bound stool and abdominal fullness; drains downward and clears heat (Fan Xie Ye).', 'Spleen and Stomach Qi deficiency; cold-deficient or Yin/fluid-deficient constipation; pregnancy, postpartum, and menstruation.', 'Expect cramping and griping; combine with a carminative (ginger, fennel) and start with the lowest dose. Not for long-term use (limit to 1 to 2 weeks): risk of laxative dependence, melanosis coli, and fluid or electrolyte depletion. Harmless reddish-brown urine discoloration may occur.', 'Intestinal obstruction or ileus, acute inflammatory bowel disease (Crohn''s disease, ulcerative colitis), appendicitis, undiagnosed abdominal pain, and severe dehydration with electrolyte depletion.', 'Avoid; caution. AHPA Botanical Safety Handbook Class 2b (not to be used during pregnancy except under qualified supervision); stimulant laxatives are second-line to bulk-forming agents. If used at all, keep short-term and low-dose. Sources: AHPA Botanical Safety Handbook, 2nd ed.; WHO Monographs on Selected Medicinal Plants, Vol. 1 (Folium Sennae).', 'Compatible in recommended short-term amounts. Only minimal sennoside metabolites reach breast milk and monitoring shows no reliable change in infant stool frequency or consistency; avoid high or prolonged doses. Sources: NIH LactMed; AHPA Botanical Safety Handbook, 2nd ed. (Class 2c).', 'Not for children under 10 to 12 years except under medical supervision; professionally dosed pediatric sennoside products exist. Sources: ESCOP Monographs, 2nd ed.; German Commission E (Sennae folium).', 'Chronic use causes hypokalemia that can potentiate cardiac glycosides (digoxin) and antiarrhythmics, and adds to potassium loss from thiazide or loop diuretics, corticosteroids, and licorice. Shortened bowel transit can reduce absorption of concurrently taken oral drugs (separate doses by about 2 hours). Sources: German Commission E (Sennae folium); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.; Mills and Bone, Principles and Practice of Phytotherapy.', 'Cold or brief hot infusion of the leaflets (cold maceration lowers griping resins); tincture; powder; standardized sennoside capsules; syrup. Traditionally paired with a carminative to temper griping.', 'Dried leaf: 0.5 to 2 g as an infusion, once at bedtime. Standardized: 15 to 30 mg sennosides (hydroxyanthracene derivatives) per day. Use the lowest effective dose; do not exceed 1 to 2 weeks without professional guidance.', 'King''s American Dispensatory (Felter & Lloyd, 1898) - Senna.', 'German Commission E Monograph - Sennae folium; WHO Monographs on Selected Medicinal Plants, Vol. 1 - Folium Sennae; ESCOP Monographs, 2nd ed. - Sennae folium; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.', 'Active constituents are dianthrone glycosides (sennosides A to D, with rhein and aloe-emodin glycosides). These prodrugs are activated by colonic bacteria to rhein-anthrone, which stimulates the myenteric plexus to increase peristalsis and net fluid and electrolyte secretion in the colon, with effect in 6 to 12 hours. A dependable stimulant cathartic for acute, short-term use only; chronic use risks laxative dependence, melanosis coli, and hypokalemia.', 'Not in the canonical biblical texts and unknown to the classical Greeks and Romans; introduced to Western materia medica by Arab physicians (Mesue and Serapion, c. 9th century). Alexandrian senna is native to the Nile valley and Arabia; Tinnevelly senna is cultivated in India.', 'Not of conservation concern. Grown as a commodity field crop (Alexandrian senna in Sudan and Egypt; Tinnevelly senna in Tamil Nadu, India). Choose cultivated, sustainably harvested leaf and pod; not listed by United Plant Savers.', 'Cold, dry, and forcefully downward-draining: a stimulant purgative that whips the sluggish, heat-bound bowel into evacuation, depleting and habit-forming if leaned upon.', 'Refer for constipation lasting over 2 weeks or unresponsive to treatment, blood in the stool, unexplained weight loss, severe or localized abdominal pain, vomiting, alternating constipation and diarrhea, or any suspicion of bowel obstruction.', 'Senna: SEN-uh · Senna alexandrina: SEN-uh a-lek-zan-DREE-nuh', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Senna.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Senna.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monograph - Sennae folium; WHO Monographs on Selected Medicinal Plants, Vol. 1 - Folium Sennae; ESCOP Monographs, 2nd ed. - Sennae folium; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Ha", "locator": "German Commission E Monograph - Sennae folium; WHO Monographs on Selected Medicinal Plants, Vol. 1 - Folium Sennae; ESCOP Monographs, 2nd ed. - Sennae folium; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Ha", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
