INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI361', 'H127', 'pregnancy', 'Pregnancy', 'moderate', 'Anthraquinone stimulant laxative; theoretical reflex uterine stimulation and maternal fluid/electrolyte loss. AHPA Class 2b.', 'Avoid; use bulk-forming laxatives first. If necessary, short-term low dose under qualified supervision only.', 'AHPA Botanical Safety Handbook, 2nd ed. (Class 2b); WHO Monographs Vol. 1 (Folium Sennae).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI362', 'H127', 'breastfeeding', 'Breastfeeding', 'low', 'Minimal excretion of active sennoside metabolites in breast milk; high maternal doses may loosen infant stool.', 'Compatible in recommended short-term amounts; avoid high or prolonged dosing.', 'NIH LactMed; AHPA Botanical Safety Handbook, 2nd ed. (Class 2c).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI363', 'H127', 'drug_interaction', 'Cardiac glycosides (digoxin) and antiarrhythmics', 'moderate', 'Chronic use causes hypokalemia, which potentiates cardiac glycoside toxicity.', 'Avoid chronic concurrent use; if unavoidable, monitor serum potassium and limit duration.', 'German Commission E (Sennae folium); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI364', 'H127', 'drug_interaction', 'Potassium-depleting agents: thiazide/loop diuretics, corticosteroids, licorice', 'moderate', 'Additive potassium loss with chronic use.', 'Avoid combined chronic use; monitor electrolytes.', 'German Commission E (Sennae folium); Brinker, Herb Contraindications and Drug Interactions, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI365', 'H127', 'condition', 'Intestinal obstruction or ileus, IBD (Crohn''s disease, ulcerative colitis), appendicitis, undiagnosed abdominal pain', 'absolute', 'Stimulated peristalsis is hazardous in bowel obstruction or acute intestinal inflammation.', 'Do not use; refer for evaluation.', 'German Commission E (Sennae folium); ESCOP Monographs, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI366', 'H127', 'population', 'Children under 10 to 12 years', 'moderate', 'Potent stimulant cathartic; risk of fluid and electrolyte disturbance in children.', 'Use only under medical supervision with appropriate pediatric dosing.', 'German Commission E (Sennae folium); ESCOP Monographs, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI367', 'H127', 'other', 'Long-term or habitual use (over 1 to 2 weeks)', 'moderate', 'Laxative dependence, melanosis coli, hypokalemia, and worsening atonic constipation.', 'Limit to 1 to 2 weeks; address the underlying cause; taper if habituated.', 'AHPA Botanical Safety Handbook, 2nd ed. (Class 2d); WHO Monographs Vol. 1 (Folium Sennae).');
