INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H128', 'Cardamom (Ela)', 'Elettaria cardamomum', 'Zingiberaceae', 'Fruit (pod) and seed', 'Pungent, Sweet', 'Warm', 'Dry', 'Cold, Torpor (atonic, sluggish digestion), Dampness, Stagnation, Qi Stagnation, damp Phlegm', 'Excess Heat, Dryness, Acute Inflammation (hot, irritated, or ulcerated mucosa)', 'Digestive (primary), Respiratory, Urinary; also nervous (nervous dyspepsia)', 'Flatulence and bloating, nausea, atonic and cold dyspepsia (low digestive fire), sluggish digestion; cold-damp bronchial congestion; halitosis', 'Cold-Damp-Relaxed and Cold-Depleted (Vata-like) phenotypes: the sluggish, gassy, cold digestion. Aggravates hot, dry, choleric (Pitta) constitutions in excess.', 'Vata, Kapha', 'Pitta (heating or excess doses)', 'Damp obstructing the middle jiao, Spleen Qi deficiency with damp-cold, Stomach and Spleen Qi stagnation with rebellious Qi (nausea)', 'Yin Deficiency with heat, Heat/Fire patterns, dry cough of Yin deficiency', 'Culinary amounts broadly safe. Therapeutic doses: caution in cholelithiasis (may trigger biliary colic). The concentrated essential oil is for dilute aromatic or topical use, not high-dose internal use.', 'Active gallstones with colic (medicinal doses). No absolute contraindications at culinary doses.', 'Culinary and food amounts considered safe. Insufficient data for concentrated medicinal doses; standard guidance is to limit cardamom to food amounts during pregnancy. Not a documented abortifacient at food doses. (AHPA Botanical Safety Handbook 2nd ed.; Natural Medicines / WebMD-RxList.)', 'Culinary and food amounts considered safe and traditionally used. Insufficient data for concentrated medicinal doses; keep to food and tea amounts. (AHPA Botanical Safety Handbook 2nd ed.)', 'Culinary amounts safe and commonly used (chai, digestive seeds). Reserve concentrated extracts and essential oil for older children under guidance.', 'No well-documented clinically significant interactions (Commission E: none known; AHPA Interaction Class A). Theoretical additive effects at high therapeutic doses only: mild antiplatelet potential (additive with anticoagulant or antiplatelet drugs) and modest blood-pressure lowering (additive with antihypertensives, shown in RCT meta-analysis). Culinary use is unproblematic. (Mills & Bone; AHPA BSH; cardamom BP meta-analysis PMC10804083.)', 'Powdered seed (culinary spice, churna), infusion of freshly crushed seed or pod, decoction, warm milk decoction (Ayurvedic, for Vata), tincture, added to food. Essential oil for dilute aromatic use only.', 'Powdered seed: 0.5-1.5 g up to 3x daily (Commission E average daily dose 1.5 g). Tincture (1:5): 1-2 mL 3x daily (Commission E tincture 1-2 g). Infusion: 1.5 g freshly crushed seed per cup, 1-3x daily. Crush pods or seeds just before use; the volatile oil is the active fraction.', 'Grieve''s A Modern Herbal (1931): Cardamoms; British Pharmaceutical Codex (1911): Cardamomi Semina', 'German Commission E Monograph (Cardamomi fructus, Blumenthal 1998); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Mills & Bone, Principles and Practice of Phytotherapy; Ayurvedic Pharmacopoeia of India (Ela); cardamom blood-pressure and inflammation RCT meta-analysis (PMC10804083, 2024)', 'Green (true) cardamom, family Zingiberaceae (ginger family), Sanskrit Ela: a classic Ayurvedic aromatic and a component of the digestive formula Sitopaladi and of chai. Active fraction is the volatile oil (1,8-cineole, alpha-terpinyl acetate, limonene). Distinguish from black cardamom (Amomum subulatum) and the TCM cardamoms Sha Ren (Amomum villosum) and Bai Dou Kou (Amomum/Wurfbainia kravanh), which share the carminative, damp-transforming action but are different species.', 'Not named in the canonical biblical texts. Known to Greco-Roman antiquity as ''kardamomon'' or ''amomum'': described by Dioscorides (De Materia Medica) and Pliny, and long traded from the Malabar coast of India along the Levantine spice routes. A classic Ayurvedic aromatic (Sanskrit Ela).', 'Cultivated at scale in the shaded understory of the Western Ghats (India) and in Guatemala; not listed as at-risk. Prefer shade-grown, single-origin pods for potency and traceability; wild Elettaria stands in the Western Ghats benefit from habitat-conscious sourcing.', 'Warm, dry, sweet-pungent aromatic: the gentle carminative that kindles cold, damp, sluggish digestion, settles nausea and rising qi, and sweetens the breath.', 'T1 Self-Care. Refer if: persistent vomiting, difficulty swallowing, blood in vomit or stool, unexplained weight loss, or dyspepsia lasting more than 2 weeks (rule out ulcer or malignancy); known gallstones with colic or suspected biliary obstruction.', 'KAR-duh-mum; el-uh-TAIR-ee-uh kar-duh-MOH-mum', 'free', 'Approved', '{"title": "Grieve''s A Modern Herbal (1931): Cardamoms; British Pharmaceutical Codex (1911): Cardamomi Semina", "locator": "Grieve''s A Modern Herbal (1931): Cardamoms; British Pharmaceutical Codex (1911): Cardamomi Semina", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monograph (Cardamomi fructus, Blumenthal 1998); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Mills & Bone, Principles and Practice of Phytotherapy; Ayurvedic Pharmacopoeia of India (Ela); cardamom b", "locator": "German Commission E Monograph (Cardamomi fructus, Blumenthal 1998); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Mills & Bone, Principles and Practice of Phytotherapy; Ayurvedic Pharmacopoeia of India (Ela); cardamom b", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
