INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI368', 'H128', 'pregnancy', 'Pregnancy (medicinal or therapeutic doses)', 'moderate', 'Insufficient safety data for concentrated medicinal doses; traditional caution regarding large aromatic, pungent doses. Culinary amounts have a long record of safe use.', 'Limit to culinary and food amounts during pregnancy; avoid concentrated extracts and internal essential oil.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); Natural Medicines / WebMD-RxList (2024)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI369', 'H128', 'condition', 'Cholelithiasis (gallstones)', 'moderate', 'Cardamom is a mild cholagogue; medicinal doses can provoke gallbladder contraction and biliary (gallstone) colic.', 'Do not use above food amounts with known gallstones except under practitioner supervision.', 'German Commission E Monograph (Cardamomi fructus); Natural Medicines / WebMD-RxList');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI370', 'H128', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (e.g. warfarin, aspirin, clopidogrel)', 'low', 'Mild antiplatelet potential of cardamom constituents; theoretical additive bleeding risk at high therapeutic doses only.', 'Culinary use unproblematic; monitor if taking concentrated cardamom preparations with anticoagulants.', 'Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook (Interaction Class A)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI371', 'H128', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Cardamom modestly lowers blood pressure in clinical trials; theoretical additive hypotensive effect at therapeutic doses.', 'Monitor blood pressure if combining medicinal-dose cardamom with antihypertensive medication.', 'Cardamom blood-pressure and inflammation RCT meta-analysis (PMC10804083, 2024)');
