INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI372', 'H129', 'condition', 'Intestinal obstruction or ileus', 'absolute', 'A stimulant laxative increasing peristalsis against a mechanical block can worsen obstruction and risk perforation.', 'Do not use. Contraindicated in known or suspected bowel obstruction.', 'German Commission E; WHO Monographs Vol. 1.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI373', 'H129', 'condition', 'Acute inflammatory bowel disease, appendicitis, or undiagnosed abdominal pain', 'absolute', 'An irritant anthraquinone stimulant aggravates an inflamed or spastic bowel and can mask a surgical abdomen.', 'Do not use in Crohn''s, ulcerative colitis, appendicitis, acute abdomen, or abdominal pain of unknown cause.', 'German Commission E; WHO Monographs Vol. 1.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI374', 'H129', 'pregnancy', 'Pregnancy', 'moderate', 'Stimulant anthraquinone laxative; theoretical reflex uterine stimulation and maternal fluid and electrolyte loss. Human series (53 first-trimester exposures, Briggs) show no clear teratogenicity.', 'Avoid. Prefer bulk-forming laxatives; use only if those fail and under professional supervision.', 'German Commission E; AHPA Botanical Safety Handbook class 2b; Briggs, Drugs in Pregnancy and Lactation (10th ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI375', 'H129', 'breastfeeding', 'Breastfeeding', 'moderate', 'Active anthraquinone metabolites appear in breast milk in small amounts; loose stools reported in 10 of 22 nursing newborns across two small uncontrolled studies.', 'Avoid; prefer alternatives such as bisacodyl, magnesium hydroxide, or senna.', 'NIH LactMed (2021); AHPA Botanical Safety Handbook class 2c.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI376', 'H129', 'pediatric', 'Children under 12 years', 'moderate', 'Children dehydrate readily; stimulant laxatives risk dehydration, electrolyte imbalance, and cramping.', 'Do not use under 12 years except under medical supervision; prefer bulk-forming or osmotic laxatives.', 'German Commission E; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI377', 'H129', 'drug_interaction', 'Cardiac glycosides (digoxin, digitalis)', 'moderate', 'Chronic use causes potassium loss (hypokalemia), which potentiates cardiac glycoside toxicity and arrhythmia.', 'Avoid chronic or repeated use with cardiac glycosides; monitor serum potassium if co-administered.', 'Brinker, Herb Contraindications and Drug Interactions; Mills and Bone; WHO Monographs Vol. 1.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI378', 'H129', 'drug_interaction', 'Potassium-depleting drugs: thiazide and loop diuretics, corticosteroids, licorice root', 'moderate', 'Additive potassium depletion increases the risk of hypokalemia and its cardiac consequences.', 'Avoid concurrent chronic use; if used, keep courses short and monitor potassium.', 'Brinker; German Commission E.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI379', 'H129', 'other', 'Chronic or long-term use (more than 1 to 2 weeks)', 'moderate', 'Prolonged stimulant-laxative use causes laxative dependency, atonic (cathartic) colon, electrolyte loss, and melanosis coli; rare hepatotoxicity reported.', 'Limit to short courses of one to two weeks; use the lowest effective dose; reassess if constipation persists.', 'German Commission E; WHO Monographs Vol. 1; NIH LiverTox.');
