INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H130', 'C06', 'Indicated', 'Primary', 'Robust, hot, Pitta-like constitution with sharp feverish infective reactions.', '{"title": "Grieve, A Modern Herbal (1931), Kariyat (Andrographis paniculata).", "locator": "Grieve, A Modern Herbal (1931), Kariyat (Andrographis paniculata).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ayurvedic Pharmacopoeia of India, Part I (Kalmegh, Andrographis paniculata); WHO Monographs on Selected Medicinal Plants Vol. 2 (Herba Andrographidis, 2002); Bensky, Clavey and Stoger, Chinese Herbal Medicine Materia Medica (Chuan Xin Lian)", "locator": "Ayurvedic Pharmacopoeia of India, Part I (Kalmegh, Andrographis paniculata); WHO Monographs on Selected Medicinal Plants Vol. 2 (Herba Andrographidis, 2002); Bensky, Clavey and Stoger, Chinese Herbal Medicine Materia Medica (Chuan Xin Lian)", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
