INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI380', 'H130', 'pregnancy', 'Pregnancy', 'absolute', 'Antifertility and possible abortifacient or anti-implantation activity in animal studies, with reduced plasma progesterone in pregnant rats. Evidence is mixed, but the reproductive concern is consistent enough that use is conventionally contraindicated.', 'Do not use in pregnancy or when attempting to conceive.', 'WHO Monographs on Selected Medicinal Plants Vol. 2 (Herba Andrographidis, 2002); AHPA Botanical Safety Handbook; Memorial Sloan Kettering About Herbs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI381', 'H130', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data, and the herb shows hormonal and antifertility activity in animals.', 'Avoid during breastfeeding; there are insufficient safety data.', 'AHPA Botanical Safety Handbook; WHO Monographs Vol. 2; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI382', 'H130', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Possible additive bleeding risk; andrographolide increased warfarin exposure in animal pharmacokinetic studies.', 'Use caution and monitor; avoid combining around surgery or in bleeding disorders.', 'Memorial Sloan Kettering About Herbs; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI383', 'H130', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Possible additive blood-pressure lowering (transient hypotension reported at therapeutic doses).', 'Monitor blood pressure if combined.', 'Memorial Sloan Kettering About Herbs; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI384', 'H130', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs', 'moderate', 'Possible additive glucose lowering, with a pharmacokinetic interaction demonstrated for glipizide.', 'Monitor blood glucose if combined with insulin or oral hypoglycemics.', 'Herb-drug pharmacokinetic studies (glipizide); Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI385', 'H130', 'drug_interaction', 'Immunosuppressant drugs', 'moderate', 'Immunostimulant activity may theoretically antagonize immunosuppressive therapy.', 'Avoid in transplant recipients and others requiring immunosuppression.', 'Memorial Sloan Kettering About Herbs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI386', 'H130', 'other', 'Hypersensitivity to Andrographis or Acanthaceae', 'absolute', 'Allergic reactions including urticaria and, rarely, anaphylaxis have been reported.', 'Do not use with known hypersensitivity; discontinue at once if rash, swelling, or wheeze appears.', 'Memorial Sloan Kettering About Herbs; WHO Monographs Vol. 2.');
