INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI387', 'H131', 'pregnancy', 'Pregnancy', 'absolute', 'Documented antifertility and abortifacient activity: purified neem extracts and seed oil produce anti-implantation and pregnancy-terminating effects in rodent and primate models.', 'Do not use in any form during pregnancy. Counsel avoidance for anyone who may be pregnant.', 'Evidence-based review of Azadirachta indica as a contraceptive, J Ethnopharmacol 2021; Talwar et al. antifertility research; AHPA Botanical Safety Handbook (avoid in pregnancy); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI388', 'H131', 'other', 'Preconception, either partner (couples trying to conceive)', 'moderate', 'Antispermatogenic and spermicidal activity in males and anti-implantation activity in females; neem has been actively investigated as a reversible contraceptive.', 'Avoid internal use when actively trying to conceive; discontinue well before attempting conception.', 'J Ethnopharmacol 2021 contraceptive review; Royal Society B 1990 (intrauterine neem oil antifertility); Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI389', 'H131', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data; constituents uncharacterized in milk and the seed oil is overtly toxic.', 'Avoid internal use while breastfeeding; prefer alternatives with established safety.', 'NIH Drugs and Lactation Database (LactMed) (no adequate data); AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI390', 'H131', 'pediatric', 'Infants and children (neem seed oil, oral)', 'absolute', 'Neem seed oil causes toxic encephalopathy, metabolic acidosis, hepatic fatty degeneration, and a Reye-like syndrome; single small doses have been fatal in infants and children.', 'Never give neem seed oil by mouth to an infant or child. Treat any ingestion as a medical emergency.', 'Sinniah and Baskaran, Lancet 1981;1(8218):487-489; Sundaravalli et al. case series (10 of 12 fatal); Lai et al.; Dhongade et al., Indian J Pediatr 2008; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI391', 'H131', 'drug_interaction', 'Antidiabetic and glucose-lowering drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Neem leaf lowers blood glucose; additive effect may cause hypoglycemia.', 'Monitor blood sugar and watch for hypoglycemia; coordinate any dose changes with the prescriber.', 'Brinker, Herb Contraindications and Drug Interactions; Natural Medicines database; Biswas et al., Current Science 2002.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI392', 'H131', 'drug_interaction', 'Immunosuppressants (ciclosporin, tacrolimus, azathioprine; transplant and autoimmune regimens)', 'moderate', 'Neem is immunostimulant in animal and in-vitro models and may theoretically oppose immunosuppressive therapy.', 'Avoid in organ-transplant recipients and patients on immunosuppressant therapy.', 'Brinker; Natural Medicines database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI393', 'H131', 'condition', 'Hepatic or renal impairment (with concentrated or prolonged internal use)', 'moderate', 'High or prolonged doses of neem are hepatotoxic and nephrotoxic in animal studies; the seed oil is directly hepatotoxic.', 'Avoid concentrated or long-term internal use in liver or kidney disease; never ingest the seed oil.', 'Boeke et al., safety evaluation of neem, J Ethnopharmacol 2004; Sinniah and Baskaran, Lancet 1981.');
