INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H132', 'TCM01', 'Minor', 'Eliminative drainage is wrong for cold, deficient Kidney Yang.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Sarsaparilla (Smilax officinalis and related species, including S. ornata).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Sarsaparilla (Smilax officinalis and related species, including S. ornata).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Sarsaparilla; Mills and Bone, Principles and Practice of Phytotherapy; Braun and Cohen, Herbs and Natural Supplements; Brinker, Herbal Contraindications and Drug Interactions; Holmes, The Energetics of Wester", "locator": "Grieve, A Modern Herbal (1931), Sarsaparilla; Mills and Bone, Principles and Practice of Phytotherapy; Braun and Cohen, Herbs and Natural Supplements; Brinker, Herbal Contraindications and Drug Interactions; Holmes, The Energetics of Wester", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI394', 'H132', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient safety data; saponin-rich root may irritate the gastrointestinal tract, and safety of therapeutic doses in pregnancy is not established.', 'Avoid medicinal doses during pregnancy. Trace culinary/flavoring amounts are not the concern.', 'Mills and Bone, Principles and Practice of Phytotherapy; Braun and Cohen, Herbs and Natural Supplements.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI395', 'H132', 'breastfeeding', 'Breastfeeding', 'moderate', 'Theoretical transfer of saponins and other constituents into breast milk; no adequate safety data for the nursing infant.', 'Avoid or use only under professional supervision; prefer better-studied alternatives.', 'Mills and Bone; Braun and Cohen, Herbs and Natural Supplements.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI396', 'H132', 'pediatric', 'Young children', 'moderate', 'No pediatric safety data; saponin content can irritate the gut and diuresis risks dehydration in small children.', 'Use in children only under professional guidance.', 'Braun and Cohen; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI397', 'H132', 'drug_interaction', 'Cardiac glycosides (digoxin, digitoxin, digitalis)', 'moderate', 'Sarsaparilla saponins may increase absorption of digitalis glycosides, raising the risk of glycoside toxicity.', 'Avoid therapeutic use with cardiac glycosides; if unavoidable, separate dosing and monitor for toxicity under supervision.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI398', 'H132', 'drug_interaction', 'Warfarin and other anticoagulants', 'moderate', 'Theoretical potentiation of anticoagulant effect reported for sarsaparilla.', 'Avoid concurrent therapeutic use without professional supervision and INR monitoring.', 'Braun and Cohen, Herbs and Natural Supplements; Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI399', 'H132', 'drug_interaction', 'Lithium', 'moderate', 'Diuretic action may reduce lithium clearance and raise serum lithium to toxic levels.', 'Avoid with lithium unless levels are monitored by the prescriber.', 'Braun and Cohen, Herbs and Natural Supplements.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI400', 'H132', 'drug_interaction', 'Bismuth and other co-administered oral drugs', 'low', 'Saponins may increase absorption of bismuth and alter absorption or elimination of concurrent medicines; hypnotic elimination may be accelerated.', 'Separate sarsaparilla dosing from other oral medications by one to two hours.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI401', 'H132', 'condition', 'Renal impairment or active kidney disease', 'moderate', 'Saponin-driven diuresis can transiently irritate the kidneys and burden impaired renal function.', 'Avoid therapeutic doses in significant kidney disease; use cautiously and at low dose otherwise.', 'Herbal Reality practitioner monograph; Braun and Cohen.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI402', 'H132', 'condition', 'Gastro-oesophageal reflux (GERD)', 'low', 'May aggravate reflux; saponins can irritate upper gastrointestinal mucosa.', 'Use cautiously or avoid in active reflux; take with food.', 'Herbal Reality practitioner monograph.');
