INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H133', 'C05', 'Indicated', 'Primary', 'Thin, cold, depleted (Vata-like): the wasted, atrophic, underbuilt person.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Sabal (Serenoa serrulata, Saw Palmetto).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Sabal (Serenoa serrulata, Saw Palmetto).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Saw Palmetto (nccih.nih.gov); MedlinePlus / Natural Medicines Comprehensive Database, Saw Palmetto; Tacklind et al., Cochrane Database of Systematic Reviews (2012), Serenoa repens for benign prostatic hyperplasia; Agbabiaka et al., S", "locator": "NCCIH, Saw Palmetto (nccih.nih.gov); MedlinePlus / Natural Medicines Comprehensive Database, Saw Palmetto; Tacklind et al., Cochrane Database of Systematic Reviews (2012), Serenoa repens for benign prostatic hyperplasia; Agbabiaka et al., S", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
