INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI403', 'H133', 'pregnancy', 'Pregnancy', 'absolute', 'Anti-androgen activity (proposed 5-alpha-reductase inhibition, analogous to finasteride, a known teratogen) may interfere with normal fetal development, particularly male genital development.', 'Do not use in pregnancy.', 'NCCIH; MedlinePlus / Natural Medicines Comprehensive Database; mechanism analogous to finasteride (FDA pregnancy category X).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI404', 'H133', 'breastfeeding', 'Breastfeeding', 'moderate', 'Hormonal activity and no lactation safety data; transfer of constituents into milk is not characterized.', 'Avoid while breastfeeding; prefer better-studied alternatives.', 'NCCIH; MedlinePlus / Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI405', 'H133', 'pediatric', 'Children and adolescents', 'moderate', 'Anti-androgen hormonal activity is inappropriate for the developing endocrine system, and no pediatric safety data exist.', 'Not recommended for children or adolescents.', 'NCCIH; MedlinePlus / Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI406', 'H133', 'drug_interaction', 'Anticoagulants and antiplatelets (warfarin, aspirin, clopidogrel)', 'moderate', 'Possible additive bleeding risk; case reports and EMA data note increased INR or bleeding with warfarin (proposed CYP2C9 inhibition), although a controlled study showed no significant INR change.', 'Use caution and monitor for bleeding and INR; discontinue at least two weeks before scheduled surgery.', 'Brinker, Herb Contraindications and Drug Interactions; EMA / HMPC assessment report; Agbabiaka 2009, Drug Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI407', 'H133', 'drug_interaction', 'Hormonal agents (finasteride, dutasteride, androgen or estrogen therapy, oral contraceptives)', 'moderate', 'Saw palmetto affects androgen and estrogen metabolism, so it may theoretically add to or oppose hormonal medications.', 'Use caution and inform the prescriber when taking hormonal medications; note it does not appear to alter PSA readings.', 'Brinker, Herb Contraindications and Drug Interactions; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI408', 'H133', 'condition', 'Undiagnosed urinary symptoms / prostate cancer screening', 'moderate', 'Self-treating lower-urinary-tract symptoms may delay diagnosis of prostate cancer; saw palmetto does not lower PSA and is not proven effective for BPH.', 'Rule out prostate cancer and other causes before use; evaluate new or worsening urinary symptoms.', 'NCCIH; Cochrane (Tacklind 2012).');
