INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A09', 'Primary', 'Anti-inflammatory: saikosaponins are glucocorticoid-potentiating.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A49', 'Primary', 'Febrifuge / antipyretic: harmonizes and cools alternating Shao Yang fever.');
