INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A43', 'Secondary', 'Cholagogue: promotes bile flow; relieves gallbladder stagnation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A03', 'Secondary', 'Nervine relaxant: eases Liver-constraint tension; modern antidepressant research.');
