INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A25', 'Minor', 'Antioxidant (saikosaponins, flavonoids).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H134', 'A30', 'Minor', 'Antiviral: saikosaponins active against hepatitis and coronavirus in vitro.');
