INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP72', 'Primary', 'Sluggish liver and bile stagnation; gallbladder qi stasis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP76', 'Primary', 'Fever management in Shao Yang alternating chills and fever.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP32', 'Primary', 'PMS with irritability and breast or flank distension (Xiao Yao San).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP29', 'Secondary', 'Dysmenorrhea from Liver qi stagnation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP20', 'Secondary', 'Menstrual irregularity from constrained Liver qi.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP15', 'Secondary', 'Hormonal imbalance and stress-linked cycle disturbance.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP02', 'Secondary', 'Chronic stress and stress-related tension.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP10', 'Secondary', 'Anxiety and irritability with Liver constraint.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP54', 'Secondary', 'Bloating and epigastric or hypochondriac fullness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP12', 'Secondary', 'Digestive upset when the liver overacts on the spleen and stomach.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP13', 'Minor', 'Systemic inflammation (anti-inflammatory saikosaponins).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H134', 'CP41', 'Minor', 'Cold and flu onset with alternating chills and fever (within formula).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H134', 'P04', 'Primary', 'Decoction of the dried root, typically within a formula.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H134', 'P01', 'Secondary', 'Tincture (Western practice).');
