INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H134', 'C02', 'Indicated', 'Primary', 'Choleric: warm, tense, stuck Liver-qi terrain that the cool disperser cools and frees.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE): Chai Hu (Bupleurum).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE): Chai Hu (Bupleurum).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Chai Hu / Radix Bupleuri); Mills and Bone, Principles and Practice of Phytotherapy; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to; Herbal Reali", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Chai Hu / Radix Bupleuri); Mills and Bone, Principles and Practice of Phytotherapy; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to; Herbal Reali", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, 'authored_v2', true);
