INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H134', 'TCM07', 'Primary', 'Yin deficiency (with ascendant Liver yang or Liver fire): the ascending, drying nature consumes yin and raises yang.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE): Chai Hu (Bupleurum).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE): Chai Hu (Bupleurum).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Chai Hu / Radix Bupleuri); Mills and Bone, Principles and Practice of Phytotherapy; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to; Herbal Reali", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Chai Hu / Radix Bupleuri); Mills and Bone, Principles and Practice of Phytotherapy; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to; Herbal Reali", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI409', 'H134', 'drug_interaction', 'Interferon (e.g., interferon-alpha)', 'absolute', 'The Bupleurum-containing formula sho-saiko-to combined with interferon has caused interstitial pneumonitis, a potentially fatal lung reaction; concurrent use is contraindicated.', 'Do not use Bupleurum or Bupleurum-containing formulas during interferon therapy. Stop and seek urgent care for new cough, breathlessness, or fever.', 'Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to (interferon interaction; Japanese Ministry of Health and Welfare warning, 1994-1996).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI410', 'H134', 'drug_interaction', 'Corticosteroids (e.g., prednisolone)', 'moderate', 'Saikosaponins can potentiate and prolong glucocorticoid activity, altering the intended steroid effect and side-effect profile.', 'Use only with medical oversight; do not combine with systemic steroids without prescriber awareness.', 'Mills and Bone, Principles and Practice of Phytotherapy; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI411', 'H134', 'drug_interaction', 'Immunosuppressant medications', 'moderate', 'Immunomodulatory saikosaponins may theoretically interfere with immunosuppressive therapy.', 'Avoid in transplant or immunosuppressed patients unless supervised by the prescriber.', 'Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI412', 'H134', 'pregnancy', 'Pregnancy', 'moderate', 'Emmenagogue and qi- and blood-moving activity, potential saikosaponin hepatotoxicity, and no adequate human safety data.', 'Avoid during pregnancy.', 'WebMD and Drugs.com Bupleurum monographs; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI413', 'H134', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety during lactation not established; no adequate data.', 'Avoid while nursing pending data.', 'WebMD Bupleurum monograph; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI414', 'H134', 'condition', 'Yin deficiency with ascendant Liver yang or Liver fire', 'moderate', 'The bitter, acrid, ascending, dispersing nature consumes yin and raises yang, worsening rising-yang headache, dizziness, red eyes, and hypertension.', 'Avoid long-term or high-dose solo use in these patterns; if needed, pair with yin-nourishing and yang-anchoring herbs.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica; Herbal Reality, Chai Hu monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI415', 'H134', 'condition', 'Liver disease / high-dose use', 'moderate', 'Saikosaponin d is dose-dependently hepatotoxic in animal studies and some human reports; the essential oil and high root doses raise liver-injury risk.', 'Avoid high-dose or prolonged solo use; monitor liver function in those with liver disease.', 'Yang et al., Saikosaponin D: review on antitumour effects, toxicity and pharmacokinetics, Pharmaceutical Biology 2021; Memorial Sloan Kettering Cancer Center, About Herbs: Sho-saiko-to (hepatotoxicity).');
