INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H135', 'TCM11', 'Secondary', 'Heat or Fire patterns: warm, irritating nature aggravates heat.', '{"title": "Grieve''s A Modern Herbal (1931): Cowslip / Paigles (Primula veris).", "locator": "Grieve''s A Modern Herbal (1931): Cowslip / Paigles (Primula veris).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper''s Complete Herbal (1653): Cowslips; EMA/HMPC Community herbal monograph and assessment report on Primulae radix, EMA/HMPC/104095/2012; e-lactancia.org (Primula veris); Alrashidi et al. / genus Primula phytomedicine systematic revie", "locator": "Culpeper''s Complete Herbal (1653): Cowslips; EMA/HMPC Community herbal monograph and assessment report on Primulae radix, EMA/HMPC/104095/2012; e-lactancia.org (Primula veris); Alrashidi et al. / genus Primula phytomedicine systematic revie", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI416', 'H135', 'pregnancy', 'Pregnancy (medicinal doses of root or flowers)', 'moderate', 'No safety or fertility studies exist for primrose root or flowers; saponin content is of unknown reproductive activity.', 'Avoid medicinal use in pregnancy; culinary flower amounts are the only historically casual exposure. Prefer safer, better-studied expectorants.', 'EMA/HMPC Community herbal monograph and assessment report on Primulae radix, EMA/HMPC/104095/2012 (use in pregnancy not recommended, no data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI417', 'H135', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion in milk; EMA precautionary, though toxicity at appropriate doses is low.', 'Avoid sustained medicinal dosing of the saponin-rich root while nursing, or use only under qualified guidance. e-lactancia rates the plant low-risk and compatible at moderate doses.', 'EMA/HMPC/104095/2012 (not recommended, no data); e-lactancia.org (Primula veris, low-risk / compatible).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI418', 'H135', 'pediatric', 'Children (flowers under 12 years; root under 4 years)', 'moderate', 'Insufficient evidence to establish safe pediatric use; a young child''s cough may signal a condition needing assessment.', 'Do not use primrose flowers under 12 or primrose root under 4; use in children 4 to 12 only with age-appropriate products under guidance. Refer a cough in a child under 4.', 'EMA/HMPC Community herbal monograph on Primulae radix, EMA/HMPC/104095/2012.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI419', 'H135', 'condition', 'Active gastritis, gastric or duodenal ulcer, reflux', 'moderate', 'Triterpenoid saponins irritate the gastric mucosa (the basis of the reflex expectorant action), which can aggravate an already inflamed or ulcerated stomach.', 'Avoid the root in active gastritis, peptic ulcer, or reflux; take with food and reduce dose if mild upset occurs.', 'EMA/HMPC assessment report on Primulae radix, EMA/HMPC/104095/2012 (gastric mucosal irritation).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI420', 'H135', 'other', 'Hypersensitivity to Primula species', 'moderate', 'Primula species can provoke allergic and contact reactions (quinone allergens such as primin, most notoriously in P. obconica).', 'Avoid in known Primula allergy; discontinue if rash or hypersensitivity appears.', 'EMA/HMPC/104095/2012 (hypersensitivity to the active substances); genus Primula dermatology literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI421', 'H135', 'drug_interaction', 'CNS depressants (alcohol, benzodiazepines, sedatives)', 'low', 'The sedative, relaxant flowers may add to central nervous system depression.', 'Use caution when combining with sedatives or alcohol; watch for additive drowsiness.', 'Mechanism-based caution per Mills and Bone principles for sedative herbs; no clinical case reports (EMA/HMPC lists no interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI422', 'H135', 'drug_interaction', 'NSAIDs, aspirin, and other gastric irritants', 'low', 'Saponin gastric-mucosa irritation may be additive with other mucosal irritants.', 'Separate dosing or avoid the root alongside chronic NSAID/aspirin use, especially with any GI symptoms.', 'Mechanism-based caution (saponin expectorant); EMA/HMPC/104095/2012 reports no documented interactions.');
