INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI423', 'H136', 'condition', 'Pre-existing liver disease, hepatitis, or elevated liver enzymes', 'absolute', 'Polygonum multiflorum causes idiosyncratic, immune-mediated (HLA-B*35:01) hepatocellular injury; superimposing it on a compromised liver risks severe, occasionally fatal hepatitis.', 'Do not use in anyone with active or prior liver disease, hepatitis, or unexplained liver-enzyme elevation. Never rechallenge a person who reacted before.', 'NIH LiverTox (2020); NCCIH; Frontiers in Pharmacology (2019) review of Polygonum multiflorum liver injury.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI424', 'H136', 'drug_interaction', 'Hepatotoxic drugs and alcohol (acetaminophen, statins, isoniazid, methotrexate, azole antifungals)', 'moderate', 'Additive hepatocellular injury on top of the herb''s own idiosyncratic hepatotoxic potential.', 'Avoid concurrent use with known hepatotoxic drugs, herbs, or regular alcohol; if unavoidable, monitor liver function closely.', 'NIH LiverTox (2020); Brinker, Herb Contraindications and Drug Interactions (3rd ed.); NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI425', 'H136', 'pregnancy', 'Pregnancy', 'moderate', 'No established human safety data; documented maternal hepatotoxicity, animal embryotoxicity signals, and raw-root anthraquinone stimulant-laxative effect with theoretical reflex uterine stimulation.', 'Avoid in pregnancy.', 'NCCIH; Natural Medicines Comprehensive Database; Brinker, Herb Contraindications and Drug Interactions (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI426', 'H136', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation data; raw-root anthraquinone metabolites can enter breast milk and loosen the infant''s stool, and maternal liver-injury risk persists.', 'Avoid while breastfeeding; prefer better-characterized alternatives.', 'NCCIH; Natural Medicines; general anthraquinone-laxative guidance in NIH LactMed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI427', 'H136', 'pediatric', 'Infants and children', 'moderate', 'Risk of idiosyncratic liver injury and the laxative effect of raw-root anthraquinones, with insufficient pediatric safety data.', 'Do not use in infants or children except under professional supervision.', 'NCCIH; Natural Medicines; NIH LiverTox (2020).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI428', 'H136', 'drug_interaction', 'Cardiac glycosides (digoxin) and potassium-depleting drugs (thiazide and loop diuretics, stimulant laxatives)', 'moderate', 'Raw-root anthraquinones deplete potassium; resulting hypokalemia potentiates cardiac glycoside toxicity and adds to diuretic and laxative potassium loss.', 'Avoid chronic or repeated raw-root use with these drugs; if co-administered, keep courses short and monitor serum potassium.', 'Brinker, Herb Contraindications and Drug Interactions (3rd ed.); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI429', 'H136', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Possible additive blood-sugar lowering from the herb''s hypoglycemic effect.', 'Monitor blood glucose if combined; watch for hypoglycemia.', 'Natural Medicines Comprehensive Database; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI430', 'H136', 'other', 'Raw (unprocessed) root and prolonged or high-dose use', 'moderate', 'Raw root carries a higher anthraquinone and hepatotoxin load than the black-soybean-prepared root; prolonged or high-dose use raises hepatotoxicity risk and causes anthraquinone-driven loose stools and potassium loss.', 'Use only the correctly prepared (zhi) root, in time-limited courses at the lowest effective dose, with liver-function monitoring.', 'NIH LiverTox (2020); Frontiers in Pharmacology (2019) review; Bensky, Chinese Herbal Medicine: Materia Medica (3rd ed.).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H136', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596): He Shou Wu (He Shou Wu / \u4f55\u9996\u70cf) entry.", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596): He Shou Wu (He Shou Wu / \u4f55\u9996\u70cf) entry.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), He Shou Wu entry; NIH LiverTox / NCBI Bookshelf, Polygonum Multiflorum (2020); Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contra", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), He Shou Wu entry; NIH LiverTox / NCBI Bookshelf, Polygonum Multiflorum (2020); Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contra", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, true);
