INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI431', 'H137', 'pregnancy', 'Pregnancy (medicinal high-dose or extract use)', 'moderate', 'No recognized uterine or emmenagogue action, but concentrated therapeutic doses are unstudied in pregnancy; safety rests on an absence of data rather than demonstrated safety.', 'Limit to culinary amounts of the cooling root drink; avoid high-dose or extract medicinal use unless supervised by a qualified practitioner.', 'Modern reviews note a lack of controlled pregnancy safety data (NCCIH-style insufficient-data precaution).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI432', 'H137', 'breastfeeding', 'Breastfeeding (medicinal high-dose or extract use)', 'moderate', 'Insufficient modern lactation safety data for supplemental or extract doses.', 'Culinary amounts acceptable; avoid concentrated medicinal doses without professional guidance.', 'Modern sources cite an absence of controlled lactation studies.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI433', 'H137', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Root extracts show documented hypoglycemic activity in animal models; an additive blood-glucose-lowering effect is plausible.', 'Monitor blood glucose; adjust antidiabetic medication only under professional supervision.', 'Modern pharmacology reviews of Hemidesmus indicus hypoglycemic activity (streptozotocin/alloxan rat models; Phytotherapy Research review, 2013); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI434', 'H137', 'drug_interaction', 'Antihypertensive drugs', 'low', 'A mild vasorelaxant, hypotensive effect may be additive.', 'Monitor blood pressure when combining; watch for dizziness or hypotension.', 'Modern reviews of Hemidesmus indicus vasorelaxant activity; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI435', 'H137', 'condition', 'Cold, damp, low-agni digestion (weak digestive fire)', 'moderate', 'Cool, heavy, unctuous, sweet nature can depress weak digestion and add to Kapha, Dampness and ama.', 'Avoid as a stand-alone remedy in frank cold-damp states, or pair with a warming carminative adjuvant; choose a warmer alterative where appropriate.', 'Ayurvedic energetic contraindication (Bhavaprakasha Nighantu; Frawley & Lad, The Yoga of Herbs).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H137', 'EP01', 'match', 3, 0, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I - Sariva (Hemidesmus indicus). Classical: Bhavaprakasha Nighantu - Sariva; Charaka Samhita and Sushruta Samhita (raktaprasadana / varnya groups). Eclectic corroboration: King''s American Dispensat", "locator": "The Ayurvedic Pharmacopoeia of India, Part I - Sariva (Hemidesmus indicus). Classical: Bhavaprakasha Nighantu - Sariva; Charaka Samhita and Sushruta Samhita (raktaprasadana / varnya groups). Eclectic corroboration: King''s American Dispensat", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; modern reviews: George et al., The Bioactive and Therapeutic Potential of Hemidesmus indicus Root (Phytotherapy Research, 2013); Nandy et al., Journal of Ethnopharmacolo", "locator": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; modern reviews: George et al., The Bioactive and Therapeutic Potential of Hemidesmus indicus Root (Phytotherapy Research, 2013); Nandy et al., Journal of Ethnopharmacolo", "kind": "pubmed"}'::jsonb, true);
