INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H137', 'EP08', 'avoid', 0, 3, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I - Sariva (Hemidesmus indicus). Classical: Bhavaprakasha Nighantu - Sariva; Charaka Samhita and Sushruta Samhita (raktaprasadana / varnya groups). Eclectic corroboration: King''s American Dispensat", "locator": "The Ayurvedic Pharmacopoeia of India, Part I - Sariva (Hemidesmus indicus). Classical: Bhavaprakasha Nighantu - Sariva; Charaka Samhita and Sushruta Samhita (raktaprasadana / varnya groups). Eclectic corroboration: King''s American Dispensat", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; modern reviews: George et al., The Bioactive and Therapeutic Potential of Hemidesmus indicus Root (Phytotherapy Research, 2013); Nandy et al., Journal of Ethnopharmacolo", "locator": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; modern reviews: George et al., The Bioactive and Therapeutic Potential of Hemidesmus indicus Root (Phytotherapy Research, 2013); Nandy et al., Journal of Ethnopharmacolo", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H138', 'Guggul', 'Commiphora wightii', 'Burseraceae (torchwood, frankincense and myrrh family)', 'Purified oleo-gum-resin (shodhita guggulu), the fragrant gum resin tapped from the bark', 'Bitter, Pungent, Astringent', 'Warm', 'Dry', 'Stagnation of fat, blood, and lymph (the boggy, congested accumulation of medas and ama); dampness and heavy, sluggish accumulation that needs scraping and drying; phlegm and fatty nodules (lipoma, cysts, glandular swelling, goiter); torpor of a slow, cold metabolism (sluggish thyroid, weight gain, low digestive fire); cold, damp, stagnant joints that ache and stiffen with rest.', 'Excess heat and irritability (this is a heating resin that aggravates a hot constitution); acute hot inflammation with redness, fever, and burning; dryness and fluid depletion, where a drying, reducing herb further desiccates; states of excitation and overstimulation. Not for the thin, dry, overheated, or depleted person.', 'Musculoskeletal (chronic cold, stagnant arthritis and joint stiffness); Cardiovascular (elevated cholesterol and triglycerides, atherosclerotic tendency, sluggish circulation); Endocrine (a slow, hypofunctioning thyroid and slow metabolism); Lymphatic (fatty lumps, cysts, swollen glands, goiter); Integumentary (nodulocystic acne, slow-healing wounds). Secondary digestive kindling as a bitter scraper of ama.', 'Chronic osteoarthritis and rheumatoid joint pain of the cold, stagnant, boggy type; elevated cholesterol and triglycerides (hyperlipidemia); overweight and sluggish, ama-laden metabolism (medoroga); hypothyroid pattern with weight gain, cold, and fatigue; nodulocystic acne and slow-healing skin; fatty lumps, cysts, swollen glands, and simple goiter; systemic low-grade inflammation.', 'Cold-Damp-Stagnant: the phlegmatic, heavy, sluggish, overweight person whose tissues are boggy and whose metabolism has slowed to a crawl, with fat and fluid accumulating in stagnant deposits. Suits the cold, stiff, congested joint and the high-cholesterol, low-thyroid picture. Not for the thin, hot, dry, or nervous type.', 'Vata, Kapha', 'Pitta', 'Blood Stasis with fixed masses, nodules, and stubborn painful joints; Phlegm-Damp accumulation forming lumps, lipomas, and goiter; Qi and Blood stagnation in the channels. Its action closely parallels Mo Yao (myrrh, Commiphora myrrha), a sister Commiphora resin that invigorates Blood, dispels stasis, reduces swelling, and speeds healing of sores.', 'Yin deficiency with heat and dryness (the warm, drying resin consumes fluids); Heat and Fire patterns, where a heating, moving herb fans the fire; delicate or deficient patients without genuine stasis or accumulation to move.', 'Commonly causes gastrointestinal upset: nausea, belching, loose stools, and abdominal discomfort, most often with unpurified resin or high doses. Hypersensitivity skin reactions (itchy rash, erythema, dermatitis) are documented and can be marked. Only purified (shodhita) guggul processed in triphala decoction or cow''s urine should be used; raw resin is more irritating to gut and skin. Being heating, it can provoke Pitta or heat signs: acid reflux, flushing, headache, and irritability. High or prolonged doses have occasionally been linked to raised liver enzymes. Not a casual self-dosed herb when the patient takes cardiac, thyroid, or blood-thinning medication.', 'Pregnancy and lactation; hyperthyroidism or thyroid nodules under active treatment; acute hot inflammatory flares; inflammatory bowel disease or an easily irritated gut; known hypersensitivity to guggul or related resins; and concurrent anticoagulant or antiplatelet, thyroid hormone, propranolol, diltiazem, estrogen or oral-contraceptive, tamoxifen, or statin therapy without professional supervision. Discontinue at least two weeks before scheduled surgery.', 'Avoid. Guggul is a traditional emmenagogue and uterine stimulant, and controlled use has been reported to shorten the menstrual cycle and increase menstrual flow; guggulsterones also carry estrogen- and progesterone-receptor activity. The WHO monograph advises that safety in pregnancy has not been established and that use be discontinued during pregnancy. Some animal studies report no embryotoxic or fetotoxic effect, so the evidence is genuinely mixed, but the precautionary standard for a hormonally active, cycle-stimulating resin is to avoid throughout pregnancy. Sources: WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Natural Medicines / Medscape monograph; traditional emmenagogue classification.', 'Avoid; insufficient data. No adequate human lactation data exist, and the WHO advises discontinuation during breastfeeding. Because guggulsterones are hormonally and metabolically active and excretion into milk is uncharacterized, use is not recommended while nursing. Source: WHO Monographs on Selected Medicinal Plants, Vol. 3; NCCIH (insufficient-data position).', 'Not established; avoid in young children. There are no pediatric safety or dosing data, and the drug-interaction and thyroid-stimulating profile makes casual use inappropriate. Use in older children or adolescents only under qualified supervision. Source: WHO Monographs Vol. 3; NCCIH.', 'Guggulsterone is an agonist of the pregnane X receptor (PXR) and induces CYP3A4, so guggul can lower the plasma levels and effect of many co-administered drugs. A human study found that 1 g of gugulipid reduced the bioavailability of propranolol and diltiazem. It may reduce the efficacy of estrogens, oral contraceptives, and tamoxifen, and it alters the handling of other CYP3A4 substrates including statins (for example rosuvastatin). Being thyroid-stimulating, it can interfere with thyroid hormone replacement (levothyroxine) and thyroid-disease control. It may inhibit platelet aggregation and interact with anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel), adding to bleeding risk. Sources: Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; WHO Monographs Vol. 3; Natural Medicines / Medscape; Dalvi et al. clinical pharmacokinetic study (propranolol and diltiazem).', 'Only purified (shodhita) resin is used, classically cooked in triphala decoction, milk, or cow''s urine to remove irritant fractions. Common forms: standardized gugulipid capsules or tablets (the modern lipid-research form), purified powder, classical guggulu compound tablets (Yogaraj, Kaishore, Triphala, and Punarnava guggulu), decoction, and tincture. Applied in medicated ghee or oil salves over stagnant, cold joints and slow-healing wounds.', 'Purified guggul resin: 500 mg to 1 g two to three times daily with warm water. Standardized gugulipid: providing roughly 25 mg guggulsterones three times daily (about 75 mg guggulsterones per day). Tincture: 2 to 4 mL two to three times daily. Typically given in courses of three to six weeks with breaks, and best used under practitioner guidance, especially alongside any cardiac, thyroid, or anticoagulant medication. Sources: WHO Monographs Vol. 3; Ayurvedic Pharmacopoeia of India, Part I.', 'Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing sores.', 'WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindications and Drug Interactions; NCCIH; IUCN Red List assessment (2015, T31231A50131117); Sarup, Kirar and Meena, Pharmacology and Phytochemistry of Oleo-Gum Resin of Commiphora wightii (PMC4637499, 2015).', 'Family Burseraceae. The oleo-gum-resin carries a complex mix of gum, essential oil, and resin; the active fraction is the ketonic steroids E- and Z-guggulsterone, plus guggulsterols, lignans, and diterpenes. Guggulsterone antagonizes the farnesoid X receptor (FXR) and upregulates hepatic LDL receptors, the basis of its cholesterol- and triglyceride-lowering action, and it stimulates thyroid function in animal models, the basis of its use in hypothyroid and sluggish-metabolism patterns. Its classical Ayurvedic identity is lekhana (scraping) and medohara (reducing fat and ama), which maps onto the modern anti-hyperlipidemic, anti-obesity, and anti-arthritic research. The accepted botanical name is Commiphora wightii (Arn.) Bhandari; Commiphora mukul is a widely used synonym (much modern literature and the Ayurvedic Pharmacopoeia head the entry under mukul). Purification (shodhana) is essential to reduce gastric and skin irritation.', 'Bdellium (Hebrew bedolach) appears in Genesis 2:12, among the treasures of the land of Havilah (gold, bdellium, and onyx), and in Numbers 11:7, where the manna is likened in appearance to bdellium. Bdellium is traditionally identified with the aromatic oleo-gum-resin of Commiphora, and Commiphora wightii is specifically the Indian bdellium; the exact biblical species is debated (some read an African Commiphora, or even a pearl or crystal), so the identification is traditional rather than certain. In the classical Mediterranean world Dioscorides (De Materia Medica) and Pliny describe bdellium as an aromatic gum used medicinally and as an adulterant of the costlier myrrh.', 'At risk. Commiphora wightii is assessed as Critically Endangered on the IUCN Red List (2015), its wild populations in Rajasthan and Gujarat depleted by destructive over-tapping of the resin, slow growth, and poor natural regeneration. Source only certified cultivated or verifiably non-destructively tapped resin, avoid wild-collected material, and support restoration and sustainable-tapping programs. (Note: guggul is an IUCN Critically Endangered species; it is not, as sometimes stated, listed on the CITES appendices.)', 'Warm, dry, and scraping: a stimulating resin that rekindles a cold, sluggish metabolism and dissolves damp, stagnant accumulations of fat, phlegm, and stagnant blood without cloying.', 'Refer for chest pain or cardiac symptoms; symptomatic thyroid disease (palpitations, tremor, heat intolerance, or an enlarging goiter needing workup); lipid levels that remain high or that warrant statin therapy; hot, red, acutely swollen or feverish joints (rule out septic or acute inflammatory arthritis); any unexplained skin eruption or signs of hypersensitivity; jaundice or signs of liver injury; and pregnancy or lactation. Any patient on anticoagulant, thyroid, propranolol, diltiazem, estrogen, tamoxifen, or statin therapy should be co-managed with the prescriber.', 'Guggul: GOO-gool. Commiphora wightii: kom-MIFF-or-ah WITE-ee-eye.', 'seed', 'Approved', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "locator": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
