INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS08', 'Primary', 'Scrapes and moves stagnant fat, blood, and lymph (medas and ama).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS07', 'Primary', 'Dries heavy, damp, boggy accumulation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS23', 'Secondary', 'Resolves phlegm and fatty nodules, lipoma, and cysts.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS24', 'Secondary', 'Reduces glandular swelling, scrofula, and simple goiter.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS19', 'Secondary', 'Rouses a slow, cold, torpid metabolism and sluggish thyroid.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS17', 'Minor', 'Warms cold, stagnant joints and cold-damp conditions.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS05', 'Primary', 'Heating resin aggravates excess heat and Pitta.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS06', 'Secondary', 'Can irritate acute, hot inflammation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS03', 'Secondary', 'Drying, reducing action worsens dryness and fluid depletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H138', 'TS10', 'Minor', 'Stimulating warmth can overstimulate an already excited state.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY04', 'Primary', 'Chronic cold, stagnant arthritis and joint stiffness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY06', 'Primary', 'Lowers cholesterol and triglycerides; anti-atherosclerotic.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY02', 'Secondary', 'Stimulates a sluggish thyroid and slow metabolism.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY11', 'Secondary', 'Disperses fatty lumps, cysts, swollen glands, and goiter.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY10', 'Secondary', 'Nodulocystic acne and slow-healing wounds.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H138', 'SY08', 'Minor', 'Bitter scraper that kindles digestion and clears ama.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A09', 'Primary', 'Anti-inflammatory; the classic Ayurvedic anti-arthritic guggulu.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A14', 'Primary', 'Alterative, blood-cleansing scraper of accumulations (lekhana).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A21', 'Secondary', 'Lymphagogue; moves lymph, resolves glandular masses and goiter.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A25', 'Secondary', 'Antioxidant guggulsterones.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A19', 'Secondary', 'Emmenagogue and uterine stimulant (basis of the pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A28', 'Minor', 'Antimicrobial; used for acne and infected sores.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A24', 'Minor', 'Vulnerary; classical vrana-ropana wound healer.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H138', 'A16', 'Minor', 'Bitter tonic and digestive kindler (deepana).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP14', 'Primary', 'Chronic cold, stagnant osteoarthritis and rheumatoid joint pain.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP13', 'Secondary', 'Systemic low-grade inflammation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP25', 'Secondary', 'Hypothyroid pattern with weight gain, cold, and fatigue.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP71', 'Secondary', 'Lymphatic congestion, fatty lumps, cysts, swollen glands, goiter.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP69', 'Secondary', 'Nodulocystic acne.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H138', 'CP75', 'Minor', 'Oxidative stress; antioxidant guggulsterones.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H138', 'P02', 'Primary', 'Standardized gugulipid capsules or tablets, and classical guggulu compounds.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H138', 'P03', 'Secondary', 'Purified (shodhita) powder.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H138', 'P04', 'Secondary', 'Decoction; classical shodhana cooks the resin in triphala decoction.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H138', 'P01', 'Minor', 'Tincture.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H138', 'P07', 'Minor', 'Medicated salve or oil over cold, stagnant joints and wounds.');
