INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H138', 'TCM11', 'Primary', 'Warm, moving resin fans Heat and Fire.', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "locator": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H138', 'TCM07', 'Secondary', 'Drying and warming, it consumes Yin and worsens deficiency dryness.', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "locator": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI436', 'H138', 'pregnancy', 'Pregnancy', 'absolute', 'Traditional emmenagogue and uterine stimulant; controlled use shortens the menstrual cycle and increases flow, and guggulsterones have estrogen- and progesterone-receptor activity. WHO advises discontinuation in pregnancy. Some animal tox data show no embryo- or fetotoxicity, so evidence is mixed, but the precautionary standard applies.', 'Avoid throughout pregnancy.', 'WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Natural Medicines / Medscape; traditional emmenagogue classification.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI437', 'H138', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate human lactation data; guggulsterones are hormonally and metabolically active and milk excretion is uncharacterized. WHO advises discontinuation during breastfeeding.', 'Avoid while nursing; insufficient data.', 'WHO Monographs Vol. 3; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI438', 'H138', 'drug_interaction', 'Propranolol and diltiazem', 'moderate', 'Guggulsterone is a PXR agonist that induces CYP3A4 and reduces gastrointestinal absorption; a human study found 1 g gugulipid lowered the bioavailability of propranolol and diltiazem, reducing their effect.', 'Avoid the combination or monitor drug effect and adjust the prescription under the prescriber''s care.', 'Brinker, Herb Contraindications and Drug Interactions; Dalvi et al. clinical pharmacokinetic study; Natural Medicines.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI439', 'H138', 'drug_interaction', 'Thyroid hormone (levothyroxine) and thyroid-disease control', 'moderate', 'Guggul stimulates thyroid function; it can add to or interfere with thyroid hormone replacement and destabilize treated thyroid disease.', 'Do not combine without medical supervision and monitoring of thyroid function tests.', 'WHO Monographs Vol. 3; Natural Medicines / Medscape.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI440', 'H138', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Guggul may inhibit platelet aggregation and, via CYP induction, alter warfarin handling, adding to bleeding risk.', 'Avoid concurrent use without supervision; monitor and discontinue at least two weeks before surgery.', 'Natural Medicines / Medscape; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI441', 'H138', 'drug_interaction', 'Estrogens, oral contraceptives, and tamoxifen', 'moderate', 'Guggulsterones have estrogen-receptor and PXR / CYP3A4 activity that can lower the levels and reduce the efficacy of estrogen therapy and interfere with tamoxifen.', 'Avoid combining without professional advice; consider reduced hormonal-therapy efficacy.', 'Natural Medicines / Medscape.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI442', 'H138', 'condition', 'Hyperthyroidism or actively treated thyroid nodules', 'moderate', 'Thyroid-stimulating action may worsen a hyperfunctioning thyroid.', 'Avoid in hyperthyroidism; use in any thyroid disease only with monitoring.', 'WHO Monographs Vol. 3; Natural Medicines / Medscape.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI443', 'H138', 'condition', 'Inflammatory bowel disease or a sensitive, irritable gut', 'moderate', 'The resin is a gastrointestinal irritant that commonly causes loose stools, nausea, and abdominal discomfort, especially when unpurified.', 'Avoid in active IBD; use only purified resin at low dose in sensitive patients.', 'NTP toxicity report on gum guggul extract (NBK561197); Natural Medicines.');
