INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H138', 'EP08', 'match', 2, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp', 'computed_energetics', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Karpuradi varga, Guggulu; with Charaka Samhita and Sushruta Samhita references to guggulu as a lekhana (scraping) and medohara (fat-reducing) agent for medoroga, arthritis, and non-healing", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "locator": "WHO Monographs on Selected Medicinal Plants, Vol. 3 (Resina Mukul); Ayurvedic Pharmacopoeia of India, Part I, Guggulu; Williamson, Major Herbs of Ayurveda; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindicat", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H139', 'Kudzu (Ge Gen)', 'Pueraria lobata', 'Fabaceae (Leguminosae; the pea and bean family)', 'Root (dried root; Radix Puerariae; Ge Gen). The dry-roasted root (chao Ge Gen) is preferred for diarrhea.', 'Sweet, Pungent (acrid)', 'Cool', 'Moist', 'Tension and constriction of the muscle layer, the tight, heat-bound stiffness of the neck, shoulders, and upper back that eases when the surface is released; excess heat, febrile flushing and the surging heat of wind-heat invasion; dryness of thirst and fluid depletion, where the sweet, cooling root generates fluids and quenches; wind at the exterior with body ache and a stiff nape. Secondarily, torpor of the Spleen with clear yang that has sunk, giving loose stool that lifts when the yang is raised.', 'True cold of the Spleen and Stomach without any heat, where a cool, dispersing root deepens the chill and loosens the stool further; deficiency of the exterior with spontaneous, profuse sweating, where an outward-releasing herb opens the pores and drains fluid; excitation and ascendant, rising yang, where the upbearing, lifting action can aggravate an already over-rising energy.', 'Digestive (Spleen and Stomach); Musculoskeletal (the muscle layer of the neck, shoulders, and upper back); Cardiovascular (modern use for hypertension with neck tension and for angina and coronary insufficiency, via puerarin); Respiratory and the exterior or skin (releases exterior wind-heat and vents measles and incomplete eruptions).', 'Stiff, tense, aching neck, shoulders, and upper back, including the tight nape of tension-type and hypertensive presentations; wind-heat or wind-cold common cold with a rigid, aching nape and body; febrile illness with heat and thirst; thirst and the wasting-thirst pattern (xiao ke, an early diabetic picture); measles and rashes that will not erupt fully; damp-heat or Spleen-deficient diarrhea and dysentery (dry-roasted form). Modern additions: hypertension with neck tightness, angina and coronary insufficiency, and the reduction of alcohol craving and hangover.', 'Warm-Dry-Tense: the flushed, thirsty, tight-necked person whose heat binds and knots the muscle layer. Suits the robust, hot, choleric or Pitta-like type. Less suited to the cold, damp, deficient, loose-stooled phlegmatic, whom its cool, dispersing nature can chill.', 'Pitta', 'Kapha (and Vata if the person is cold and depleted, since the cool, light, dispersing quality can increase cold)', 'Wind-heat (and wind-cold, as in Ge Gen Tang) invading the exterior and muscle layer with a stiff, aching neck and upper back, which the acrid, cool root releases. Heat and Fire with thirst and Stomach heat injuring the fluids, which it clears while generating fluids. Damp-heat and Spleen Qi deficiency diarrhea and dysentery, which it checks by raising the sunken clear yang (Ge Gen Qin Lian Tang). Fluid-deficient thirst and wasting-thirst, which it moistens by generating fluids.', 'Exterior and Wei Qi deficiency with spontaneous, profuse sweating: a diaphoretic, exterior-releasing herb further opens the pores and worsens fluid loss. Cold of the Spleen and Stomach without heat: the cool nature deepens the cold. Yin-deficient ascendant yang or already-rebellious rising qi: the upbearing, lifting action can aggravate. Use the raw dispersing form with care where there is no heat; the dry-roasted form is gentler for deficiency-type diarrhea.', 'Generally very well tolerated and close to a food. Large doses of the raw, dispersing root can provoke light sweating, and its upbearing nature may cause fullness, distension, or lightheadedness in yin-deficient or sensitive people. The isoflavones (puerarin, daidzin, daidzein) are phytoestrogenic and also inhibit aldehyde dehydrogenase-2 (ALDH2), which can raise acetaldehyde. Rare case reports describe acute interstitial nephritis after about ten days of kudzu root juice and reversible liver-enzyme elevation. Concentrated puerarin injections used in Chinese hospitals have caused occasional hemolysis and are not a home preparation.', 'Estrogen-sensitive (estrogen-receptor-positive) conditions and cancers, and concurrent tamoxifen or hormone therapy, because the isoflavones are phytoestrogenic. Known hypersensitivity to kudzu. Use caution with methotrexate, antidiabetic drugs, antihypertensives, and anticoagulant or antiplatelet drugs (see Drug Interactions). In the traditional frame, exterior deficiency with profuse sweating and cold of the Spleen and Stomach without heat.', 'Avoid medicinal doses. Reliable human safety data in pregnancy are lacking, and the isoflavones (puerarin, daidzein, genistein) are phytoestrogenic and bind estrogen receptors, a theoretical reproductive concern. Professional references (Natural Medicines / Drugs.com Professional monograph; NCCIH; MSKCC About Herbs) state that safety and efficacy in pregnancy have not been established and advise against use. Culinary kudzu starch as a food is a separate, low-concern matter; concentrated root extracts should be avoided. Source: Natural Medicines Comprehensive Database; NCCIH; MSKCC Integrative Medicine (About Herbs: Kudzu).', 'Avoid medicinal doses; insufficient data. There is no established lactation safety record, and the phytoestrogenic isoflavones pass the same theoretical concern to the nursing infant. No LactMed entry establishes safety. Prefer to avoid concentrated kudzu root extracts while breastfeeding. Source: Natural Medicines Comprehensive Database; NCCIH.', 'No established pediatric dosing for medicinal extracts and insufficient safety data; avoid concentrated isoflavone or puerarin preparations in children except under professional guidance. Kudzu starch used as an ordinary food (an arrowroot-like thickener) is a separate, low-concern matter. Source: Natural Medicines Comprehensive Database; AHPA Botanical Safety Handbook.', 'Methotrexate: kudzu root extract and its constituent puerarin inhibit the MDR1 (P-glycoprotein) and renal OAT1 and OAT3 transporters, reducing methotrexate elimination and raising its levels; a rat study described a life-threatening interaction. Avoid concurrent use. Tamoxifen and hormone therapy: the estrogenic isoflavones may antagonize tamoxifen and stimulate estrogen-sensitive tissue; avoid in estrogen-sensitive cancer. Antidiabetic drugs (insulin, sulfonylureas, metformin): puerarin is antihyperglycemic, so additive hypoglycemia is possible; monitor blood glucose. Antihypertensives and anticoagulant or antiplatelet drugs: puerarin is hypotensive, vasodilatory, and antiplatelet; watch for additive effects. Alcohol and disulfiram: the isoflavones (daidzin, puerarin) inhibit ALDH2 and can raise acetaldehyde, a theoretical additive effect (though clinical alcohol-reduction trials have not shown a disulfiram-like flush at studied doses). Puerarin inhibits CYP2D6 and induces CYP1A2 in vitro, a theoretical effect on those substrates. Sources: MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database; NCCIH; Chiang et al., Toxicol Appl Pharmacol 2005 (methotrexate); PMID 24242937 (MDR1 and OAT1/OAT3 mechanism).', 'Decoction of the sliced dried root (the classic form, as in Ge Gen Tang and Ge Gen Qin Lian Tang); dry-roasted (chao) root decoction for diarrhea; powder; tincture and fluid extract; isoflavone- or puerarin-standardized capsule (used in trials for alcohol reduction and cardiovascular support); kudzu starch as a culinary and convalescent food. Puerarin injection is a hospital-only preparation and is not a home method.', 'Decoction: 9 to 15 g of dried root per day, up to 30 g for stubborn neck stiffness or hypertension (Chinese Pharmacopoeia; Bensky, Materia Medica). Tincture (1:5): roughly 3 to 6 mL, two to three times daily. Standardized extract for alcohol-craving reduction in trials: about 1.2 to 2 g per day of isoflavone-standardized kudzu extract. Use the dry-roasted root for deficiency-type diarrhea. Begin low in cool, deficient constitutions.', 'Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.com Professional monograph (Kudzu); NCCIH; AHPA Botanical Safety Handbook; PMID 24242937 (puerarin-methotrexate transporter interaction).', 'Family Fabaceae. The root is rich in isoflavonoids, chiefly the C-glycoside puerarin (the marker compound and basis of the cardiovascular preparations) with daidzin, daidzein, genistein, and formononetin, plus abundant starch (the source of kudzu or arrowroot-style starch). Ge Gen is one of the chief exterior-releasing, muscle-releasing herbs of the Chinese materia medica; its signature is loosening the heat-bound muscle layer of the neck and upper back, and it anchors the classic formulas Ge Gen Tang (wind-cold with stiff nape) and Ge Gen Qin Lian Tang (damp-heat dysentery). Modern research centers on puerarin for angina and coronary and cerebral circulation, on the whole-root isoflavones for reducing alcohol consumption (studied as NPI-028), and on isoflavones for menopausal and bone endpoints. Distinguish Ye Ge or Ge Gen (Pueraria lobata) from Fen Ge (Pueraria thomsonii), the starchier root sometimes sold under the same Chinese heading.', 'Not in the canonical biblical texts and unknown to the ancient Mediterranean materia medica (Dioscorides, Pliny). Native to East Asia; first recorded in the Han-dynasty Shennong Ben Cao Jing and used in Han-era formulas of the Shang Han Lun. Introduced to North America at the 1876 Philadelphia Centennial Exposition, where it later became the infamous invasive vine of the American Southeast, the vine that ate the South.', 'No conservation concern. Kudzu is one of the world''s most aggressive invasive weeds, notorious across the southeastern United States and listed as noxious or invasive in the United States, South Africa, Australia, and elsewhere. It is not on any United Plant Savers at-risk list. Harvesting wild kudzu root is ecologically beneficial; never plant or propagate it. Source root from cultivated stock or from wild invasive stands being cleared.', 'Cool, moist, and outward-releasing: a sweet, acrid relaxant that softens the heat-bound, stiff muscle layer of the neck and shoulders while generating fluids to quench thirst.', 'Refer for chest pain or suspected angina or any cardiac symptom (do not self-treat presumed heart disease with kudzu); stroke or new neurological deficit; severe or persistent hypertension; high or persistent fever, or a stiff neck with headache, photophobia, or rash (rule out meningitis); measles or serious eruptive febrile illness in a child; blood in the stool, dehydration, or diarrhea lasting more than a few days; uncontrolled blood sugar; and anyone taking methotrexate or tamoxifen or living with an estrogen-sensitive cancer.', 'Kudzu: KUD-zoo. Ge Gen: guh-GUN (Chinese ge gen). Pueraria lobata: pyoo-eh-RAIR-ee-ah loh-BAH-tah.', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
