INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H139', 'C06', 'Indicated', 'Primary', 'Robust, hot (Pitta-like) type with heat binding the muscle layer.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
