INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H139', 'TCM05', 'Primary', 'Exterior and Wei Qi deficiency with spontaneous, profuse sweating; a diaphoretic worsens fluid loss.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica Classic, Han dynasty), Ge Gen (Radix Puerariae); with Zhang Zhongjing, Shang Han Lun (Treatise on Cold Damage, c. 220 CE), Ge Gen Tang.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ge Gen; Chen & Chen, Chinese Medical Herbology and Pharmacology; MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database / Drugs.c", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI444', 'H139', 'drug_interaction', 'Methotrexate', 'moderate', 'Kudzu root extract and puerarin inhibit MDR1 (P-glycoprotein) and the renal OAT1 and OAT3 transporters, reducing methotrexate elimination and raising its plasma levels; a rat study reported a life-threatening interaction.', 'Avoid concurrent use. If methotrexate is essential, do not combine with kudzu; monitor methotrexate levels and toxicity if any exposure occurs.', 'Chiang et al., Toxicol Appl Pharmacol 2005; PMID 24242937; MSKCC Integrative Medicine (About Herbs: Kudzu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI445', 'H139', 'condition', 'Estrogen-sensitive conditions and cancers (ER-positive breast cancer); concurrent tamoxifen or hormone therapy', 'moderate', 'Isoflavones (puerarin, daidzein, genistein) bind estrogen receptors and may antagonize tamoxifen or stimulate estrogen-sensitive tissue.', 'Avoid in estrogen-receptor-positive cancer and with tamoxifen or hormone therapy.', 'MSKCC Integrative Medicine (About Herbs: Kudzu); Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI446', 'H139', 'pregnancy', 'Pregnancy', 'moderate', 'Reliable human safety data are lacking, and the phytoestrogenic isoflavones bind estrogen receptors, a theoretical reproductive concern.', 'Avoid medicinal (extract) doses. Culinary kudzu starch is a separate, low-concern matter.', 'Natural Medicines Comprehensive Database; NCCIH; MSKCC (About Herbs: Kudzu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI447', 'H139', 'breastfeeding', 'Breastfeeding', 'moderate', 'No established lactation safety record; the phytoestrogenic isoflavones raise the same theoretical concern for the nursing infant.', 'Avoid concentrated kudzu root extracts while breastfeeding; insufficient data.', 'Natural Medicines Comprehensive Database; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI448', 'H139', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Puerarin has antihyperglycemic activity that may add to glucose-lowering drugs.', 'Monitor blood glucose; watch for additive hypoglycemia.', 'MSKCC (About Herbs: Kudzu); Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI449', 'H139', 'drug_interaction', 'Antihypertensive, anticoagulant, and antiplatelet drugs', 'low', 'Puerarin is hypotensive, vasodilatory, and antiplatelet, which may add to these drugs.', 'Monitor blood pressure and for signs of bleeding when combined.', 'Natural Medicines Comprehensive Database; MSKCC (About Herbs: Kudzu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI450', 'H139', 'drug_interaction', 'Alcohol and disulfiram (ALDH2 inhibition)', 'low', 'Kudzu isoflavones (daidzin, puerarin) inhibit aldehyde dehydrogenase-2 and can raise acetaldehyde, a theoretical additive effect with alcohol or disulfiram.', 'Use caution combining with heavy alcohol intake or disulfiram, though clinical alcohol-reduction trials have not shown a disulfiram-like flush at studied doses.', 'MSKCC (About Herbs: Kudzu); pharmacology literature on daidzin and ALDH2.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI451', 'H139', 'condition', 'Exterior deficiency with profuse sweating (traditional contraindication)', 'moderate', 'An outward-releasing, diaphoretic herb further opens the pores and worsens fluid loss in the exterior-deficient, sweating patient.', 'Avoid the raw dispersing form in spontaneous, profuse sweating and in Spleen-Stomach cold without heat.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.).');
