INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H140', 'TCM06', 'Primary', 'Blood deficiency and bleeding without stasis; a mover depletes and worsens bleeding.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H140', 'TCM02', 'Minor', 'Qi deficiency without genuine stasis; moving further drains.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI452', 'H140', 'pregnancy', 'Pregnancy', 'moderate', 'Strong blood-invigorating herb that breaks blood stasis and moves blood; traditionally contraindicated in pregnancy, with added theoretical bleeding risk from documented antiplatelet activity.', 'Avoid throughout pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), Salvia miltiorrhiza; classical TCM contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI453', 'H140', 'drug_interaction', 'Warfarin', 'absolute', 'Displaces warfarin from plasma proteins and alters its pharmacokinetics, potentiating anticoagulation; documented case reports of raised INR, over-anticoagulation, and bleeding.', 'Do not combine. Avoid Danshen in any patient taking warfarin.', 'Chan TYK, Annals of Pharmacotherapy, 2001; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI454', 'H140', 'drug_interaction', 'Antiplatelet, anticoagulant, and thrombolytic drugs (aspirin, clopidogrel, heparin, DOACs) and NSAIDs', 'moderate', 'Additive inhibition of platelet aggregation and enhanced fibrinolysis increase bleeding risk.', 'Avoid, or use only under close medical supervision with bleeding monitoring.', 'Brinker; AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI455', 'H140', 'condition', 'Bleeding disorders and the perioperative period', 'moderate', 'Antiplatelet and fibrinolytic activity raises the risk of hemorrhage in bleeding disorders and around surgery.', 'Avoid in hemorrhagic disorders; discontinue one to two weeks before surgery or dental extraction.', 'Brinker; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI456', 'H140', 'drug_interaction', 'Digoxin (and serum digoxin immunoassays)', 'moderate', 'Danshen shows digoxin-like immunoreactivity that can falsely raise or lower measured serum digoxin and may add to cardiac glycoside effects.', 'Avoid combining; if a patient on digoxin has used Danshen, interpret digoxin levels with caution.', 'Brinker; published assay-interference reports (Wahed and Dasgupta).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI457', 'H140', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Danshen is mildly hypotensive and vasodilatory; additive blood-pressure lowering is possible.', 'Monitor blood pressure if combined.', 'Brinker; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI458', 'H140', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on transfer of tanshinones or salvianolic acids into milk or on infant effects; antiplatelet activity of unknown relevance to the infant.', 'Avoid during lactation for want of safety data.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H140', 'EP01', 'match', 2, 0, 'temperature: herb cold rebalances the pattern''s hot; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Dan Shen (Salvia miltiorrhiza).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Dan Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Brinker, Herb Contraindi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
