INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS09', 'Primary', 'Astringent tightening of lax, atonic, passively-bleeding tissue; the slack, flooding uterus and leaking vessels.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS07', 'Secondary', 'Mild diuresis drains boggy damp and fluid retention.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS05', 'Minor', 'Cools reckless blood-heat bleeding (TCM cools the blood).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS03', 'Primary', 'Astringent, drying diuretic worsens frank dryness and fluid deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS12', 'Secondary', 'Over-astringes tissue that is already constricted and tense.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H141', 'TS17', 'Minor', 'A cooling herb chills the already cold, weak, depleted.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H141', 'SY03', 'Primary', 'Reproductive: the classic remedy for passive uterine bleeding, flooding menses, and postpartum oozing.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H141', 'SY09', 'Primary', 'Urinary: hematuria, irritable and bleeding bladder, gravel, and mild diuresis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H141', 'SY06', 'Secondary', 'Cardiovascular and blood: systemic hemostatic; vasoactive amines affecting blood pressure and heart rate.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H141', 'SY08', 'Secondary', 'Digestive: astringent for diarrhea and dysentery.');
