INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H141', 'TCM07', 'Secondary', 'Drying diuretic-astringent depletes Yin and fluids.', '{"title": "Ellingwood''s American Materia Medica, Therapeutics and Pharmacognosy (Finley Ellingwood, 1919), Capsella bursa-pastoris (Shepherd''s Purse).", "locator": "Ellingwood''s American Materia Medica, Therapeutics and Pharmacognosy (Finley Ellingwood, 1919), Capsella bursa-pastoris (Shepherd''s Purse).", "source_id": "S22", "author": "Ellingwood \u2014 American Materia Medica", "year": "1919", "url": "https://www.henriettes-herb.com/eclectic/ellingwood/", "kind": "public_domain_text"}'::jsonb, '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Capsella; Grieve, A Modern Herbal (1931), Shepherd''s Purse; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions; AHPA Botani", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Capsella; Grieve, A Modern Herbal (1931), Shepherd''s Purse; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions; AHPA Botani", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI459', 'H141', 'pregnancy', 'Pregnancy', 'absolute', 'Documented oxytocic (uterine-contracting) and uterine-stimulant action risks provoking contractions.', 'Avoid throughout pregnancy as a home remedy. The only traditional obstetric use is short-term in or immediately after labor, under the care of an experienced midwife or clinician.', 'AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI460', 'H141', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient safety data; mustard-family glucosinolates may transfer into breast milk and disagree with the infant.', 'Avoid except under professional supervision; short-term supervised postpartum hemostatic use is a separate indication.', 'Mills and Bone; TRC Natural Medicines and WebMD clinical safety monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI461', 'H141', 'pediatric', 'Young children', 'moderate', 'No pediatric safety data; uterine and vasoactive amines are of unknown effect in children.', 'Use in children only under professional guidance; prefer gentler, better-studied options.', 'Mills and Bone; clinical safety monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI462', 'H141', 'drug_interaction', 'Warfarin and other anticoagulants/antiplatelets', 'moderate', 'Vitamin K content can antagonize warfarin and lower the INR; a case of disturbed anticoagulation has been reported.', 'Avoid unsupervised concurrent use; monitor INR closely if used with warfarin.', 'Brinker, Herbal Contraindications and Drug Interactions; documented warfarin case report; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI463', 'H141', 'drug_interaction', 'Antihypertensive and cardiovascular drugs (including cardiac glycosides)', 'moderate', 'Vasoactive amines can raise or lower blood pressure and alter heart rate, adding to or opposing cardiovascular medicines.', 'Use cautiously with blood-pressure and cardiac drugs; avoid in unstable cardiovascular disease without supervision.', 'Brinker; TRC Natural Medicines and WebMD/RxList clinical monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI464', 'H141', 'drug_interaction', 'Sedatives and CNS depressants', 'low', 'Large doses can cause drowsiness, potentially additive with sedative medications.', 'Avoid large doses alongside sedatives; watch for excess drowsiness.', 'TRC Natural Medicines and WebMD/RxList clinical monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI465', 'H141', 'drug_interaction', 'Thyroid hormone replacement', 'low', 'May reduce thyroid hormone activity and lessen the effect of thyroid replacement.', 'Use cautiously with levothyroxine; monitor thyroid status if combined.', 'TRC Natural Medicines and WebMD/RxList clinical monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI466', 'H141', 'condition', 'Cardiovascular disease, arrhythmia, or unstable blood pressure', 'moderate', 'Vasoactive amines can affect blood pressure and heart rate unpredictably.', 'Avoid therapeutic doses in significant cardiovascular disease or unstable blood pressure without professional supervision.', 'Brinker; clinical safety monographs.');
