INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H142', 'Baikal Skullcap (Huang Qin)', 'Scutellaria baicalensis', 'Lamiaceae (Labiatae)', 'Root (dried radix); Chinese Huang Qin', 'Bitter', 'Cold', 'Dry', 'Excess heat and damp-heat (yellow, hot, congested tissues with thick secretions); acute inflammation; acute infection with heat signs; frank excess conditions with fever and flushing.', 'Cold and deficiency states (Spleen/Stomach cold-deficiency, watery cold diarrhea, poor appetite without thirst); tissue dryness and fluid exhaustion, which prolonged use of this cold, bitter root can worsen.', 'Lungs and respiratory tract; digestive tract (stomach and intestines); hepatobiliary (liver and gallbladder); cardiovascular; immune.', 'Damp-heat diarrhea and dysentery; lung heat with cough and thick yellow phlegm; febrile and inflammatory conditions; hepatobiliary damp-heat (jaundice, bile stagnation); functional hypertension with heat and rising-yang signs; allergic reactivity and asthmatic tendency; heat-driven bleeding (nosebleed, blood in stool).', 'Hot-Damp-Excess; the flushed, congested, fire-and-damp phenotype. Choleric and robust Pitta-like constitutions.', 'Pitta, Kapha', 'Vata', 'Damp-heat (Lung, Stomach and Intestine, Liver and Gallbladder); excess Heat and Fire; Lung-heat cough; ascendant Liver fire; reckless heat in the blood; early-stage warm febrile (wind-heat) disease. Classically settles a restless fetus in Heat patterns (an tai) only under professional supervision.', 'Spleen and Stomach Qi and Yang deficiency with cold (cold diarrhea, poor appetite, no thirst); Kidney Yang deficiency; cold-from-deficiency without heat signs.', 'Cold, bitter, and drying. Prolonged or high-dose use can injure Spleen yang and body fluids, producing cold diarrhea, poor appetite, or dryness. Not for cold or deficient presentations.', 'Avoid in cold-deficiency digestive weakness (cold diarrhea, poor appetite without heat signs) and in Kidney or Spleen yang deficiency. Use only authenticated Scutellaria baicalensis root; skullcap products have been adulterated with hepatotoxic Teucrium (germander).', 'Not established by modern data. AHPA Botanical Safety Handbook (2nd ed, 2013) and Mills & Bone note a lack of controlled safety data; because it is a cold, bitter, descending root, Western practice generally avoids it in pregnancy. In TCM it is one of the few cold herbs traditionally used to calm a heat-pattern restless fetus (an tai), but only when prescribed and monitored by a qualified practitioner. Avoid in self-care.', 'Insufficient data; avoid without professional supervision. No reliable human lactation safety data (NCCIH; Mills & Bone). Traditional lactation use exists but is unverified.', 'Insufficient modern safety data for young children. Use only under professional guidance at weight-adjusted doses; not for infant or unsupervised pediatric self-care.', 'Documented and theoretical interactions (Biomedicine & Pharmacotherapy 2021 drug-herb interaction review; peer-reviewed pharmacokinetic studies): baicalin induces intestinal P-glycoprotein and can lower cyclosporine (ciclosporin) bioavailability, risking subtherapeutic immunosuppression and graft rejection; baicalin and scutellarin inhibit hepatic OATP1B1 and 1B3 uptake transporters and can alter plasma levels of statins such as rosuvastatin and other OATP substrates; possible additive effects with anticoagulant and antiplatelet drugs (monitor INR with warfarin) and with blood-glucose-lowering and antihypertensive agents. Avoid combining with transplant immunosuppressants; use caution and monitoring with narrow-therapeutic-index drugs.', 'Decoction of the dried root (classic); tincture; dried powder; encapsulated standardized (baicalin) extract.', 'Decoction: 3 to 9 g dried root per day (up to 12 g short-term in acute heat conditions). Tincture (1:5, 40 to 60 percent alcohol): 3 to 6 mL per day in divided doses. Favor short courses for acute heat and damp-heat; reassess with prolonged use.', 'Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty compilation, c. 200 CE), entry Huang Qin (Scutellaria).', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed), Huang Qin entry; Chen and Chen, Chinese Medical Herbology and Pharmacology; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook (2nd ed, 2013); NIH LiverTox: Skullcap (2020); Biomedicine and Pharmacotherapy 2021 drug-herb interaction review (article S0753332221002304).', 'Root of Scutellaria baicalensis (Lamiaceae), a foundational Chinese heat-clearing, damp-drying herb. Principal actives are the flavonoids baicalin, baicalein, wogonin, wogonoside, and oroxylin A, which underlie documented anti-inflammatory, antioxidant, antimicrobial, antiviral, hepatoprotective, and anti-allergic activity. A distinct species from S. lateriflora (American or Virginian skullcap), a nervine relaxant; do not conflate the two. Bounding caution: several case reports and small series link Chinese skullcap dietary supplements to acute hepatocellular liver injury after 1 to 3 months, some involving adulteration with hepatotoxic Teucrium (germander); use authenticated material and monitor.', 'Not in canonical biblical texts. Native to East Asia (northern China, Korea, Mongolia, and Siberia near Lake Baikal); first recorded in the Shennong Ben Cao Jing (c. 200 CE) and a staple of classical Chinese and Kampo medicine.', 'Widely field-cultivated in China for the commercial root supply; wild populations have been depleted by root harvest in parts of the native range. Not listed by United Plant Savers (a North American registry), but prefer cultivated, authenticated root to reduce wild-collection pressure and adulteration risk.', 'Cold and dry: a bitter, fire-draining root that clears damp-heat from the lungs, gut, and liver, cools reckless heat in the blood, and settles ascendant fire.', 'Refer for jaundice, dark urine, right-upper-quadrant pain, or persistent nausea (possible liver injury); high fever above 39 C persisting beyond 48 hours; bloody or dehydrating diarrhea; stiff neck or altered consciousness; or any severe or worsening infection.', 'Baikal Skullcap: BYE-kal SKUL-kap. Latin: Scutellaria baicalensis, skoo-teh-LAIR-ee-ah bye-kal-EN-sis. Huang Qin: HWAHNG-chin.', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty compilation, c. 200 CE), entry Huang Qin (Scutellaria).", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty compilation, c. 200 CE), entry Huang Qin (Scutellaria).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed), Huang Qin entry; Chen and Chen, Chinese Medical Herbology and Pharmacology; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed), Huang Qin entry; Chen and Chen, Chinese Medical Herbology and Pharmacology; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
