INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI467', 'H142', 'pregnancy', 'Pregnancy', 'moderate', 'Cold, bitter, descending root; modern controlled safety data are lacking. Western practice avoids it, while TCM uses it only for heat-pattern fetal restlessness (an tai) under supervision.', 'Avoid in self-care during pregnancy; use only if prescribed and monitored by a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed (2013); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI468', 'H142', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation safety data for Scutellaria baicalensis.', 'Avoid without professional supervision while breastfeeding.', 'NCCIH; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI469', 'H142', 'drug_interaction', 'Cyclosporine (ciclosporin) and other transplant immunosuppressants', 'moderate', 'Baicalin induces intestinal P-glycoprotein, reducing cyclosporine bioavailability and risking subtherapeutic immunosuppression and graft rejection.', 'Avoid combining with transplant immunosuppressants.', 'J Pharm Pharmacol 2019;71(5):788 (baicalin induces intestinal P-gp); Biomedicine and Pharmacotherapy 2021 drug-herb interaction review.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI470', 'H142', 'drug_interaction', 'OATP1B1 and 1B3 substrate drugs, including rosuvastatin and other statins', 'moderate', 'Baicalin and scutellarin inhibit hepatic OATP1B1/1B3 uptake transporters, altering plasma concentrations of substrate drugs.', 'Separate dosing, monitor for altered drug effect, and avoid with narrow-therapeutic-index OATP substrates.', 'Sci Rep 2020;10:874 (scutellarin and OATP1B1); Biomedicine and Pharmacotherapy 2021 review.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI471', 'H142', 'drug_interaction', 'Warfarin and antiplatelet/anticoagulant drugs', 'moderate', 'Flavonoids (baicalein) show antiplatelet and CYP-modulating activity that may alter anticoagulant effect.', 'Monitor INR and for bleeding if combined.', 'Biomedicine and Pharmacotherapy 2021 drug-herb interaction review.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI472', 'H142', 'drug_interaction', 'Blood-glucose-lowering and antihypertensive medications', 'low', 'Possible additive hypoglycemic and hypotensive pharmacodynamic effects.', 'Monitor blood glucose and blood pressure when combined.', 'Biomedicine and Pharmacotherapy 2021 review; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI473', 'H142', 'condition', 'Pre-existing liver disease; risk of idiosyncratic hepatotoxicity', 'moderate', 'Several case reports of acute hepatocellular injury with jaundice after 1 to 3 months of Chinese skullcap supplements, some involving adulteration with hepatotoxic Teucrium (germander).', 'Avoid in active liver disease; use authenticated product; discontinue and evaluate liver function if jaundice, dark urine, or right-upper-quadrant pain develop.', 'NIH LiverTox: Skullcap (2020).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI474', 'H142', 'other', 'Spleen and Stomach cold-deficiency (cold diarrhea, poor appetite, no thirst)', 'moderate', 'Cold, bitter root injures Spleen yang and can worsen cold-deficiency digestion.', 'Avoid in cold, deficient, non-heat presentations.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed).');
