INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI475', 'H143', 'pregnancy', 'Pregnancy', 'absolute', 'Buchu is a traditional emmenagogue and uterine stimulant; its volatile oil is rich in pulegone, an abortifacient and hepatotoxic ketone. Reports link buchu to miscarriage.', 'Avoid all medicinal use throughout pregnancy.', 'WebMD consumer safety monograph (Likely Unsafe; miscarriage reports); AHPA Botanical Safety Handbook (buchu leaf, pregnancy contraindication); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI476', 'H143', 'breastfeeding', 'Breastfeeding', 'moderate', 'Pulegone-bearing oil and insufficient lactation data; possibly acceptable only in small culinary amounts.', 'Avoid medicinal doses while breastfeeding pending data.', 'WebMD consumer safety monograph (possibly safe in food amounts; insufficient data for larger amounts).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI477', 'H143', 'drug_interaction', 'Lithium', 'moderate', 'Diuretic action can reduce renal lithium clearance and raise plasma lithium toward toxicity; documented with herbal-diuretic combinations that included buchu.', 'Avoid, or use only with lithium-level monitoring and prescriber oversight.', 'WebMD interaction monograph (Moderate); Pyevich D, Bogenschutz MP, Am J Psychiatry 2001;158(8):1329.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI478', 'H143', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, NSAIDs)', 'moderate', 'Buchu may slow blood clotting, giving additive bleeding and bruising risk.', 'Monitor for bleeding; coordinate with the prescriber; consider stopping before surgery.', 'WebMD interaction monograph (Moderate).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI479', 'H143', 'condition', 'Liver disease and high-dose or essential-oil use (pulegone hepatotoxicity)', 'moderate', 'Pulegone, concentrated in the essential oil and in the A. crenulata adulterant, is hepatotoxic (glutathione depletion, centrilobular necrosis at high exposure).', 'Do not use the neat essential oil internally; avoid high or prolonged doses; avoid in liver disease; prefer diosphenol-rich A. betulina leaf.', 'Drugs.com buchu monograph; Brendler et al, Front Pharmacol 2022;13:813142 (PMC8859318).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI480', 'H143', 'condition', 'Acute kidney inflammation (acute nephritis)', 'moderate', 'The irritant aromatic volatile oil may aggravate acutely inflamed renal tissue; aromatic urinary antiseptics are traditionally reserved for lower urinary and bladder complaints.', 'Avoid in acute nephritis; restrict to lower urinary-tract and bladder use and refer kidney involvement.', 'Mills S, Bone K, Principles and Practice of Phytotherapy; King''s American Dispensatory 1898 (historical caution).');
