INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI481', 'H144', 'pregnancy', 'Root/stem bark and concentrated alkaloid or high-dose rind extracts', 'absolute', 'Bark carries toxic pelletierine-group piperidine alkaloids and is an emetic, motor-nerve-active taenifuge traditionally contraindicated in pregnancy; concentrated extracts unstudied.', 'Avoid medicinal bark and high-dose rind extracts in pregnancy. Dietary fruit and juice are acceptable in normal food amounts.', 'NCCIH pomegranate monograph (fruit/juice possibly safe as food; other forms lack data); AHPA Botanical Safety Handbook, 2nd ed. (alkaloid-bearing bark, caution class); CIR/toxicology reviews of pelletierine alkaloids.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI482', 'H144', 'breastfeeding', 'Root/stem bark and alkaloid preparations', 'moderate', 'Pelletierine-group alkaloids are toxic and unstudied in lactation.', 'Avoid medicinal bark and concentrated extracts while nursing; culinary fruit and juice acceptable.', 'NCCIH (limited data on concentrated forms); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI483', 'H144', 'pediatric', 'Root/stem bark and isolated alkaloids in young children (traditionally under 5)', 'absolute', 'Narrow toxic margin; risk of motor-nerve paralysis, collapse in small children.', 'Do not give bark or alkaloid preparations to young children. Fruit and juice are food-safe; use rind astringent only in small, supervised doses.', 'Toxicology reviews of pelletierine alkaloids; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI484', 'H144', 'other', 'Self-administered root/stem bark or pelletierine alkaloids', 'absolute', 'Overdose causes nausea, vomiting, cramping, tremor, muscular weakness, giddiness, mental confusion, diplopia, mydriasis and motor-nerve paralysis.', 'Bark taenifuge is practitioner-administered only, after fasting and followed by a purgative; no casual self-dosing. Overdose is a medical emergency.', 'King''s American Dispensatory (1898) and Felter (1922) toxicity descriptions corroborated by modern pomegranate toxicology reviews (CIR 2020).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI485', 'H144', 'drug_interaction', 'Warfarin and other CYP2C9-metabolized anticoagulants', 'moderate', 'Pomegranate juice/extract inhibits CYP2C9; a published case reports raised anticoagulant effect (increased INR), and peel extract altered warfarin pharmacokinetics in rats.', 'Avoid or monitor INR closely with concentrated juice or extract; coordinate with the prescriber.', 'Warfarin case report PMID 19637955; rat PK study PMC6344987; Molecules 2023 review PMC10003857; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI486', 'H144', 'drug_interaction', 'CYP3A4 substrates (some statins, carbamazepine, certain calcium-channel blockers, sildenafil)', 'moderate', 'Pomegranate juice/extract can inhibit CYP3A4, plausibly raising substrate levels; clinical data are mixed (a controlled simvastatin study found no clinically relevant effect).', 'Use caution with concentrated juice or extract alongside narrow-index CYP3A4 substrates; monitor for increased drug effect.', 'Molecules 2023 CYP3A4/CYP2C9 review PMC10003857; simvastatin study PMID 25720525; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI487', 'H144', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Pomegranate juice can modestly lower blood pressure, a plausibly additive effect.', 'Monitor blood pressure when combining regular concentrated juice with antihypertensives.', 'NCCIH; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI488', 'H144', 'condition', 'Dry, atrophic or constipated bowel; frank cold-deficient digestion', 'moderate', 'Cool, drying, astringent action can worsen dryness, constipation and cold-deficiency states.', 'Avoid high-dose astringent bark/rind in dry, atrophic or constipated patients, or pair with moistening, warming adjuvants.', 'Traditional energetic contraindication (King''s American Dispensatory; Ayurvedic Dadima energetics).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H144', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Granatum (Pomegranate). Corroborated by Felter, Eclectic Materia Medica (1922) - Granatum, and the British Pharmaceutical Codex (Granati Cortex).", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Granatum (Pomegranate). Corroborated by Felter, Eclectic Materia Medica (1922) - Granatum, and the British Pharmaceutical Codex (Granati Cortex).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931) - Pomegranate; The Ayurvedic Pharmacopoeia of India - Dadima (Punica granatum); NCCIH pomegranate monograph; AHPA Botanical Safety Handbook, 2nd ed.; Faria & Calhau reviews of pomegranate pharmacology; MDPI Mo", "locator": "Grieve, A Modern Herbal (1931) - Pomegranate; The Ayurvedic Pharmacopoeia of India - Dadima (Punica granatum); NCCIH pomegranate monograph; AHPA Botanical Safety Handbook, 2nd ed.; Faria & Calhau reviews of pomegranate pharmacology; MDPI Mo", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, true);
