INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI489', 'H145', 'pregnancy', 'Pregnancy (therapeutic/medicinal doses)', 'moderate', 'Chicory root carries a traditional emmenagogue and abortifacient reputation and a theoretical uterine-stimulant effect at concentrated doses. Food amounts (roasted-root beverage, salad greens, inulin) are FDA GRAS and chicory is not on the AHPA pregnancy-avoid list.', 'Culinary/food amounts appear acceptable; avoid concentrated therapeutic doses, tinctures and high-dose extracts in pregnancy unless supervised by a qualified practitioner.', 'Drugs.com Review of Natural Products; Brinker, Herb Contraindications and Drug Interactions (3rd ed.); AHPA Botanical Safety Handbook; FDA GRAS.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI490', 'H145', 'condition', 'Gallstones or biliary obstruction', 'moderate', 'Cholagogue/choleretic action increases bile flow, which can be harmful against an obstructed duct and may provoke biliary colic.', 'Avoid, or use only under medical supervision, with known gallstones or bile-duct obstruction; refer for right-upper-quadrant pain or jaundice.', 'Drugs.com Review of Natural Products; Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI491', 'H145', 'other', 'Asteraceae/Compositae allergy (ragweed, daisy, marigold)', 'moderate', 'Sesquiterpene lactones can trigger IgE-mediated allergy and allergic contact dermatitis in sensitized individuals.', 'Avoid in known Asteraceae allergy; discontinue if rash, itching or swelling occurs.', 'Drugs.com Review of Natural Products; WebMD (chicory monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI492', 'H145', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Inulin and chicory extract can modestly lower post-prandial blood glucose, a theoretically additive hypoglycemic effect.', 'Monitor blood glucose and coordinate any dose adjustment with the prescriber.', 'Mills & Bone, Principles and Practice of Phytotherapy; Drugs.com Review of Natural Products.');
