INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H146', 'C04', 'Indicated', 'Primary', 'Phlegmatic: cold, boggy, gassy digestion with atonic tone.', '{"title": "Grieve, M. A Modern Herbal (1931), Dill (Anethum graveolens). Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Anethum / Oleum Anethi (Oil of Dill).", "locator": "Grieve, M. A Modern Herbal (1931), Dill (Anethum graveolens). Supplementary historical: King''s American Dispensatory (Felter & Lloyd, 1898), Anethum / Oleum Anethi (Oil of Dill).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (dill fruit); NIH LactMed / Drugs and Lactation Database, Dill (NBK501877); WebMD and RxList dill monographs; Brinker, Herb Contraindications and Drug Interactions; Ayurvedic references for Shatapushp", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (dill fruit); NIH LactMed / Drugs and Lactation Database, Dill (NBK501877); WebMD and RxList dill monographs; Brinker, Herb Contraindications and Drug Interactions; Ayurvedic references for Shatapushp", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
