INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI493', 'H146', 'pregnancy', 'Pregnancy: therapeutic seed doses, concentrated extracts and essential oil', 'moderate', 'Dill seed has traditional emmenagogue use (Ayurvedic Shatapushpa is a uterine, menstruation-promoting herb), and dill seed oil is high in dillapiole, an apiole-group phenylpropene; apioles are documented uterine stimulants and reproductive toxins at high doses, and human safety at medicinal doses is not established.', 'Culinary and food amounts are considered safe (GRAS). Avoid concentrated therapeutic doses, seed extracts and the essential oil during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (dill pregnancy/lactation review); maternal reproductive toxicity data on apiole/dillapiole (PMC7956842); WebMD and RxList dill monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI494', 'H146', 'drug_interaction', 'Lithium', 'moderate', 'Dill has a mild diuretic effect that may reduce renal clearance of lithium and raise serum lithium concentrations.', 'Avoid therapeutic dill doses with lithium unless serum levels are monitored and the prescriber adjusts the dose. Culinary amounts are not a concern.', 'WebMD and RxList dill monographs; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI495', 'H146', 'drug_interaction', 'Antidiabetic / hypoglycemic agents (insulin, sulfonylureas, metformin)', 'moderate', 'Dill extract has documented blood-glucose-lowering activity; therapeutic doses may add to the hypoglycemic effect of glucose-lowering drugs.', 'Monitor blood glucose and watch for hypoglycemia at therapeutic doses; coordinate any dose change with the prescriber. Culinary amounts are not a concern.', 'WebMD and RxList dill monographs; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI496', 'H146', 'other', 'Dill essential oil / concentrated seed oil (dillapiole), internal or undiluted use', 'moderate', 'Concentrated volatile oil high in dillapiole (especially Indian dill oil, roughly 20 to 52 percent); apioles are hepato- and nephrotoxic and uterotonic at high doses, and dillapiole inhibits CYP3A4 in vitro.', 'Do not take the essential oil internally undiluted. Reserve internal use for trained supervision; avoid concentrated oil in pregnancy and in young children.', 'Maternal reproductive toxicity and apiole/dillapiole toxicology reviews (PMC7956842 and related); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI497', 'H146', 'other', 'Apiaceae (Umbelliferae) allergy: dill, celery, caraway, fennel, anise, coriander; mugwort/birch pollen cross-reactivity', 'absolute', 'IgE cross-reactivity among Apiaceae species and related pollens; reports of contact dermatitis, urticaria and rhinitis.', 'Avoid in known dill or Apiaceae allergy. Introduce cautiously in atopic patients and discontinue on any allergic sign.', 'AHPA Botanical Safety Handbook, 2nd ed.; Apiaceae cross-reactivity literature.');
