INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H147', 'TCM03', 'Minor', 'Heavy, unctuous quality burdens weak, cold-damp Spleen digestion', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I - Gokshura (Tribulus terrestris). Classical corroboration: Bhavaprakasha Nighantu - Gokshura; Charaka Samhita and Sushruta Samhita (mutravirechaniya / vrishya groups). Chinese tradition: Bai Ji L", "locator": "The Ayurvedic Pharmacopoeia of India, Part I - Gokshura (Tribulus terrestris). Classical corroboration: Bhavaprakasha Nighantu - Gokshura; Charaka Samhita and Sushruta Samhita (mutravirechaniya / vrishya groups). Chinese tradition: Bai Ji L", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; Bensky et al., Chinese Herbal Medicine: Materia Medica (Ci Ji Li); Memorial Sloan Kettering Cancer Center integrative-medicine monograph on Tribulus terrestris; LiverTox", "locator": "Frawley & Lad, The Yoga of Herbs; Williamson, Major Herbs of Ayurveda; Bensky et al., Chinese Herbal Medicine: Materia Medica (Ci Ji Li); Memorial Sloan Kettering Cancer Center integrative-medicine monograph on Tribulus terrestris; LiverTox", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI498', 'H147', 'pregnancy', 'Pregnancy (medicinal or extract use)', 'moderate', 'Purported androgen-modulating hormonal activity and a traditional fertility/uterine reputation; animal feeding studies (including a controlled sheep study) have examined effects on fetal development and pregnancy outcome. Controlled human pregnancy data are lacking.', 'Avoid medicinal and standardized-extract use in pregnancy; do not exceed incidental culinary exposure.', 'Memorial Sloan Kettering Cancer Center Tribulus monograph; sheep feeding study on fetal development and pregnancy outcome; NCCIH-style insufficient-data precaution; AHPA Botanical Safety Handbook pregnancy caution (specific class not confirmed, see flags).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI499', 'H147', 'breastfeeding', 'Breastfeeding (medicinal or extract use)', 'moderate', 'It is not known whether Tribulus constituents pass into breast milk, and controlled lactation safety data are absent.', 'Avoid medicinal doses while breastfeeding; limit to incidental culinary exposure.', 'Modern monograph statements that transfer into milk is unknown (WebMD/Natural Medicines); insufficient-data precaution.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI500', 'H147', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Tribulus has documented blood-glucose-lowering activity, so an additive hypoglycemic effect is plausible.', 'Monitor blood glucose; adjust antidiabetic medication only under professional supervision.', 'Memorial Sloan Kettering Cancer Center herb-drug interaction monograph; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI501', 'H147', 'drug_interaction', 'Antihypertensives and diuretics (and lithium)', 'moderate', 'Additive blood-pressure-lowering and diuretic effects; potent herbal diuresis can theoretically alter renal lithium clearance and raise lithium levels.', 'Monitor blood pressure and fluid/electrolyte status; use extra caution and monitor levels in patients on lithium.', 'Memorial Sloan Kettering Cancer Center monograph (additive diuretic/antihypertensive effect); standard herbal-diuretic lithium caution (Mills & Bone).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI502', 'H147', 'drug_interaction', 'Clopidogrel and other antiplatelet drugs', 'moderate', 'Tribulus has been reported to blunt the antiplatelet effect of clopidogrel, with stent thrombosis reported.', 'Avoid the combination in stented patients and others at high thrombotic risk.', 'Memorial Sloan Kettering Cancer Center herb-drug interaction monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI503', 'H147', 'drug_interaction', 'Statins (for example atorvastatin)', 'moderate', 'A case of rhabdomyolysis with mild transaminitis has been reported in a patient taking a Tribulus supplement while on long-term atorvastatin.', 'Monitor for muscle pain or weakness; check creatine kinase if symptomatic and consider discontinuing.', 'American Journal of Case Reports, rhabdomyolysis with over-the-counter Tribulus terrestris.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI504', 'H147', 'condition', 'Active or prior liver or kidney disease; concentrated supplement use', 'moderate', 'Case reports document severe hepatotoxicity and nephrotoxicity (acute liver and renal injury, with the saponin diosgenin implicated) from concentrated Tribulus extracts and body-building doses.', 'Avoid concentrated extracts; prefer traditional food-grade decoction/churna; stop and seek care for jaundice, dark urine or reduced urine output.', 'LiverTox (NIH/NIDDK) Tribulus record; ACG Case Reports Journal (2024) severe liver and renal injury; Memorial Sloan Kettering Cancer Center monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI505', 'H147', 'condition', 'Hormone-sensitive conditions (for example prostate cancer)', 'moderate', 'Purported androgenic/hormonal activity could theoretically stimulate hormone-sensitive tissue.', 'Patients with prostate cancer or other hormone-sensitive conditions should consult their physician before use.', 'Memorial Sloan Kettering Cancer Center Tribulus monograph.');
