INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS09', 'Primary', 'Astringent tones a boggy, dilated, over-worked heart and slack vessels; checks passive bleeding.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS01', 'Primary', 'Cardiac trophorestorative: strengthens and rebuilds a weakened, failing heart muscle (Ayurvedic kshaya).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS10', 'Secondary', 'Settles a racing, pounding, anxious heart with palpitations.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS08', 'Secondary', 'Moves blood stasis and improves coronary and peripheral circulation in angina and ischemia.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS05', 'Minor', 'Cooling; eases a hot, inflamed cardiovascular terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS17', 'Primary', 'Cooling nature aggravates cold, deficient terrain and weak circulation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H148', 'TS03', 'Secondary', 'Drying astringent worsens dry, thin, depleted tissue; tends to constipate.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY06', 'Primary', 'Cardiovascular: heart muscle, coronary and peripheral vessels; angina, CHF, palpitations, hypertension.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY12', 'Secondary', 'Hepatic: hypolipidemic and hepatoprotective; lowers total and LDL cholesterol.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY01', 'Secondary', 'Nervous: settles the anxious, palpitating heart.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY09', 'Minor', 'Urinary: mild diuresis useful in cardiac fluid retention.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY10', 'Minor', 'Integumentary: astringent vulnerary for wounds and skin.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H148', 'SY08', 'Minor', 'Digestive: astringent for diarrhea and passive bleeding.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A07', 'Primary', 'Cardiotonic: the signature action; strengthens myocardial contractility and cardiac function.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A15', 'Primary', 'Astringent (tannins, OPCs): tones lax cardiovascular and other tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A40', 'Primary', 'Trophorestorative to the heart muscle; rebuilds a weakened myocardium over time.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A25', 'Secondary', 'Antioxidant comparable to vitamin E in coronary patients; protects myocardium.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A37', 'Secondary', 'Hypotensive: mild, somewhat inconsistent lowering of systolic blood pressure.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A09', 'Secondary', 'Anti-inflammatory in cardiovascular and other tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A50', 'Secondary', 'Styptic/hemostatic: astringent checks passive bleeding (raktavikara).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A13', 'Minor', 'Hepatoprotective and hypolipidemic in models and trials.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A08', 'Minor', 'Mild diuretic; supports diuresis in congestive heart failure.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A24', 'Minor', 'Vulnerary: traditional wound and fracture (kshata) use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A28', 'Minor', 'Antimicrobial/antibacterial in vitro.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H148', 'A26', 'Minor', 'Anxiolytic: calms the nervous, palpitating heart.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP46', 'Primary', 'Palpitations and a racing, anxious heart.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP44', 'Secondary', 'Functional/mild hypertension (BP-lowering documented but inconsistent).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP47', 'Secondary', 'Poor peripheral and coronary circulation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP75', 'Secondary', 'Oxidative stress; antioxidant comparable to vitamin E in CHD patients.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP13', 'Minor', 'Systemic inflammation of the cardiovascular terrain.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP56', 'Minor', 'Diarrhea (astringent).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP18', 'Minor', 'Skin conditions; traditional complexion and wound use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H148', 'CP08', 'Minor', 'Poor wound healing; astringent vulnerary (kshata/vrana).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P04', 'Primary', 'Bark decoction (kwatha).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P06', 'Primary', 'Ksheerapaka: bark simmered in milk and water, the classic cardiac preparation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P03', 'Primary', 'Bark powder (arjuna churna), 1-3 g.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P02', 'Secondary', 'Standardized capsule or extract (modern).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P01', 'Secondary', 'Tincture of the bark.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H148', 'P14', 'Minor', 'Arjunarishta: traditional fermented cardiac tonic (elixir/cordial).');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H148', 'C01', 'Indicated', 'Primary', 'Sanguine: warm, damp, plethoric cardiovascular congestion the cool astringent tones and tempers.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "locator": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
