INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H148', 'C05', 'Aggravates', 'Secondary', 'Thin, cold, depleted (Vata-like): cold, dry, astringent qualities aggravate.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "locator": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
