INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H148', 'TCM03', 'Secondary', 'Spleen Qi deficiency with cold digestion and constipation: drying astringent deepens the pattern.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Arjuna (stem bark of Terminalia arjuna). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "locator": "Dwivedi S. Terminalia arjuna Wight & Arn.: a useful drug for cardiovascular disorders. J Ethnopharmacol. 2007;114(2):114-129. Dwivedi S, Chopra D. Revisiting Terminalia arjuna: an ancient cardiovascular drug. J Tradit Complement Med. 2014;4", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI506', 'H148', 'pregnancy', 'Pregnancy', 'moderate', 'Safety not established; traditionally contraindicated in pregnancy, with no adequate human data for a cooling, astringent cardioactive bark.', 'Avoid medicinal internal use during pregnancy.', 'Herbal Reality Arjuna monograph; WebMD consumer safety summary (insufficient evidence, avoid).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI507', 'H148', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate human lactation data; sources conflict.', 'Avoid medicinal internal use while breastfeeding pending data.', 'Herbal Reality Arjuna monograph; WebMD consumer safety summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI508', 'H148', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel) and pre-surgical period', 'moderate', 'Bark extract shows mild antiplatelet and anticoagulant activity (arjunolic acid, action similar to aspirin) that may be additive, increasing bleeding risk.', 'Monitor for bleeding; use only with clinician oversight; discontinue about 2 weeks before surgery.', 'Dwivedi & Chopra, J Tradit Complement Med 2014;4(4):224-231 (PMC4220499); Drugs.com/WebMD interaction summaries.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI509', 'H148', 'drug_interaction', 'Antihypertensive, beta-blocker, and antianginal cardiovascular drugs', 'moderate', 'Possible additive blood-pressure-, heart-rate-, and angina-lowering effects.', 'Monitor blood pressure and heart rate; coordinate dose changes with the prescriber; caution in existing hypotension or bradycardia.', 'Dwivedi & Chopra, J Tradit Complement Med 2014; WebMD interaction summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI510', 'H148', 'drug_interaction', 'Thyroid hormone (levothyroxine); hypothyroidism', 'moderate', 'Bark extract lowered serum T3 and T4 in animal studies (attenuating an L-thyroxine-induced rise by roughly 42 and 79 percent, comparable to propylthiouracil) and may reduce thyroid hormone levels, potentially opposing replacement or worsening hypothyroidism.', 'Avoid high or prolonged doses in thyroid disease; monitor thyroid function if used with levothyroxine.', 'Pharmazie 2006;61(9):793-795 (PMID 17020158) thyroid-hormone study; Dwivedi & Chopra, J Tradit Complement Med 2014.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI511', 'H148', 'drug_interaction', 'CYP450 substrate drugs (e.g. statins and others via CYP1A/2C9/2D6/3A4)', 'low', 'Constituents modulate several cytochrome P450 isoenzymes; theoretical altered drug metabolism.', 'Monitor for altered effect of narrow-therapeutic-index CYP substrates; theoretical, not clinically confirmed.', 'Dwivedi & Chopra, J Tradit Complement Med 2014.');
