INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI512', 'H149', 'pregnancy', 'Pregnancy (therapeutic doses and essential oil)', 'moderate', 'Traditional emmenagogue and mild uterine-stimulant reputation with no adequate human safety data at medicinal strength; culinary food amounts are recognized as safe.', 'Culinary use is fine; avoid concentrated medicinal doses and the essential oil during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (Class 1 seed in food use); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI513', 'H149', 'breastfeeding', 'Breastfeeding', 'low', 'Only trace carvone passes into milk; two nursing studies showed no adverse effects. Galactagogue benefit is unproven and the concentrated oil is best avoided.', 'Culinary and tea amounts are acceptable; avoid the concentrated essential oil.', 'LactMed (NIH Drugs and Lactation Database), Caraway.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI514', 'H149', 'drug_interaction', 'Antidiabetic agents (insulin, oral hypoglycemics)', 'moderate', 'Caraway extract showed mild glucose- and weight-lowering activity in a human trial; additive hypoglycemia is theoretically possible.', 'Monitor blood glucose if caraway is used medicinally alongside antidiabetic medication.', 'Kazemipoor et al., Evid Based Complement Alternat Med 2013 (PMC3844184); WebMD interaction summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI515', 'H149', 'drug_interaction', 'Paracetamol (acetaminophen)', 'low', 'Chronic caraway essential oil altered paracetamol pharmacokinetics in an animal model (reduced oral bioavailability, increased after injection); mechanism unconfirmed in humans.', 'Theoretical only; separate dosing and be aware of possible altered paracetamol levels with high, chronic caraway oil intake.', 'Samojlik et al., BMC Pharmacology and Toxicology 2012;13(Suppl 1):A27 (PMC3506285).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI516', 'H149', 'condition', 'Bile-duct obstruction or gallstones', 'moderate', 'As a warm aromatic carminative with mild bile-moving tendency, it may be inadvisable where bile flow is mechanically obstructed.', 'Use cautiously and under professional guidance in known biliary obstruction or gallstones.', 'German Commission E aromatic-digestive caution; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI517', 'H149', 'other', 'Infants and young children (neat essential oil, internal)', 'moderate', 'The concentrated essential oil can irritate the gut and mucous membranes of infants and young children.', 'Use only dilute seed-water or tea for childhood colic; do not give the neat essential oil internally to infants or young children.', 'LactMed; German Commission E.');
