INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS19', 'Primary', 'Rouses a torpid liver and sluggish, under-firing digestion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS09', 'Primary', 'Restores tone to atonic, slack digestive musculature and secretion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS01', 'Secondary', 'Depleted digestive vitality; convalescent debility.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS11', 'Secondary', 'Depressed, under-functioning digestive and secretory activity.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS04', 'Minor', 'Debility and exhaustion after fever.');
