INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS03', 'Secondary', 'Drying to already dry, fluid-deficient tissues.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H150', 'TS17', 'Minor', 'Over-cooling a frankly cold, deficient digestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H150', 'SY08', 'Primary', 'Stomach, appetite, and digestive secretion; the archetypal bitter.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H150', 'SY12', 'Primary', 'Liver and gallbladder; promotes bile flow, for jaundice and hepatic torpor.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H150', 'SY09', 'Secondary', 'Mild diuretic action on the kidneys; historic use in dropsy.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H150', 'SY10', 'Minor', 'Depurative for chronic skin complaints and slow-healing wounds.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A16', 'Primary', 'The archetypal stomachic bitter tonic, restoring appetite and digestive tone.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A43', 'Primary', 'Cholagogue; promotes bile flow for a torpid liver and jaundice.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A44', 'Secondary', 'Choleretic; stimulates bile production.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A17', 'Secondary', 'Carminative; relieves flatulence, fullness, and griping.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A13', 'Secondary', 'Hepatoprotective; experimental liver-protective activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A49', 'Secondary', 'Febrifuge; the old feverwort for intermittent and low fevers.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A14', 'Secondary', 'Alterative and depurative blood cleanser for chronic skin and rheumatic complaints.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A32', 'Minor', 'Traditional vermifuge for intestinal worms.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A19', 'Minor', 'Reputed emmenagogue; the basis of the pregnancy caution.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H150', 'A36', 'Minor', 'Documented anti-hyperglycemic activity; traditional use in diabetes.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP58', 'Primary', 'Weak, atonic digestion with poor appetite and low digestive fire; the core bitter indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP72', 'Primary', 'Sluggish liver and poor bile flow; hepatic torpor.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP12', 'Secondary', 'General atonic digestive upset with heartburn and fullness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP74', 'Secondary', 'Jaundice and cholestasis; traditionally paired with barberry.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP54', 'Secondary', 'Bloating and flatulence; carminative bitter.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP57', 'Secondary', 'Nausea of weak, under-toned digestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP03', 'Secondary', 'Debility and slow convalescence after fever.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP76', 'Secondary', 'Intermittent and low fevers; the old feverwort.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP62', 'Minor', 'Intestinal worms; traditional vermifuge.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H150', 'CP27', 'Minor', 'Blood-sugar dysregulation; documented anti-hyperglycemic activity.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H150', 'P05', 'Primary', 'Cold or warm infusion of the dried flowering tops, the classic domestic form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H150', 'P01', 'Primary', 'Tincture, and as part of compound bitters such as tincture of gentian.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H150', 'P03', 'Secondary', 'Powdered herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H150', 'P14', 'Minor', 'Aromatic bitter or aperitif elixir taken before meals.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H150', 'C04', 'Indicated', 'Primary', 'Phlegmatic, cold-damp, atonic, sluggish digestion needing bitter stimulation.', '{"title": "Grieve, A Modern Herbal (1931), Centaury (Erythraea Centaurium).", "locator": "Grieve, A Modern Herbal (1931), Centaury (Erythraea Centaurium).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Dispensatory of the United States / National Formulary, Centaurium (Erythraea Centaurium); King''s American Dispensatory (Felter and Lloyd, 1898), Sabbatia (American Centaury, the New World analogue); Culpeper, The English Physician (Cen", "locator": "The Dispensatory of the United States / National Formulary, Centaurium (Erythraea Centaurium); King''s American Dispensatory (Felter and Lloyd, 1898), Sabbatia (American Centaury, the New World analogue); Culpeper, The English Physician (Cen", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
