INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H150', 'TCM07', 'Secondary', 'Drying nature aggravates Yin and Blood deficiency dryness.', '{"title": "Grieve, A Modern Herbal (1931), Centaury (Erythraea Centaurium).", "locator": "Grieve, A Modern Herbal (1931), Centaury (Erythraea Centaurium).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Dispensatory of the United States / National Formulary, Centaurium (Erythraea Centaurium); King''s American Dispensatory (Felter and Lloyd, 1898), Sabbatia (American Centaury, the New World analogue); Culpeper, The English Physician (Cen", "locator": "The Dispensatory of the United States / National Formulary, Centaurium (Erythraea Centaurium); King''s American Dispensatory (Felter and Lloyd, 1898), Sabbatia (American Centaury, the New World analogue); Culpeper, The English Physician (Cen", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI518', 'H150', 'condition', 'Active gastric or duodenal (peptic) ulcer', 'absolute', 'Centaury stimulates gastric acid secretion, which aggravates and delays healing of an active ulcer.', 'Do not use in active peptic ulceration.', 'Herbal Reality (Centaury); RxList/Drugs.com; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI519', 'H150', 'condition', 'Acute gastritis and gastric hyperacidity / acid reflux', 'moderate', 'Bitter stimulation of acid secretion worsens hyperacidity, gastritis, and reflux driven by excess acid.', 'Avoid where there is stomach irritation, inflammation, or hyperacidity.', 'Herbal Reality (Centaury); Bartram, Encyclopedia of Herbal Medicine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI520', 'H150', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional emmenagogue (Parkinson listed it to draw down the menses); intense bitters may reflexively stimulate uterine activity. Adequate human data are lacking.', 'Avoid during pregnancy.', 'Herbal Reality (Centaury); Bartram; Mills and Bone; Drugs.com.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI521', 'H150', 'breastfeeding', 'Breastfeeding', 'moderate', 'No safety data during lactation; intense bitter principles may pass into breast milk.', 'Avoid while breastfeeding; prefer a better-documented bitter if needed.', 'Herbal Reality (Centaury).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI522', 'H150', 'pediatric', 'Young children', 'moderate', 'No pediatric safety data; the extreme bitterness is poorly tolerated and can provoke nausea.', 'Avoid in young children; in older children use only low, short-term doses under professional guidance.', 'Herbal Reality (Centaury); precautionary practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI523', 'H150', 'drug_interaction', 'Acid-suppressing drugs (antacids, H2-receptor antagonists, proton-pump inhibitors)', 'moderate', 'Pharmacodynamic antagonism: centaury stimulates gastric acid, opposing the therapeutic aim of acid-suppressing drugs, which in turn blunt its digestive action.', 'Avoid concurrent use, or separate dosing and reassess the need for the bitter.', 'Herbal Reality (Centaury); RxList/Drugs.com.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI524', 'H150', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Additive blood-glucose lowering: centaury has documented anti-hyperglycemic activity and may potentiate hypoglycemic drugs.', 'Monitor blood glucose and watch for hypoglycemia if combined with diabetic medication.', 'Herbal Reality (Centaury); RxList/Drugs.com; anti-hyperglycemic animal studies.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI525', 'H150', 'other', 'Prolonged high-dose use', 'moderate', 'Animal studies of medium-term high dosing reported adverse effects on the liver and kidneys (conflicting evidence; other rat studies found a wide safety margin at traditional doses).', 'Limit to short-to-medium-term courses at customary doses; avoid indefinite daily high-dose use.', 'RxList/Drugs.com; toxicology studies of Centaurium erythraea (Erythraea centaurium) in rats.');
