INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H151', 'C02', 'Indicated', 'Primary', 'Choleric (hot, dry, irritated): the cool, moistening demulcent tempers heat and dryness.', '{"title": "Grieve M. A Modern Herbal (1898 material medica tradition, published 1931), heading: Mallows (public domain).", "locator": "Grieve M. A Modern Herbal (1898 material medica tradition, published 1931), heading: Mallows (public domain).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Dioscorides, De Materia Medica, Malache (ancient Mediterranean anchor); Hoffmann D, Medical Herbalism; Mills S & Bone K, Principles and Practice of Phytotherapy; Batiha GE-S et al., a review of the phytochemistry, pharmacology, and safety o", "locator": "Dioscorides, De Materia Medica, Malache (ancient Mediterranean anchor); Hoffmann D, Medical Herbalism; Mills S & Bone K, Principles and Practice of Phytotherapy; Batiha GE-S et al., a review of the phytochemistry, pharmacology, and safety o", "source_id": "S18", "author": "Hoffmann \u2014 Medical Herbalism", "year": "2003", "url": null}'::jsonb, 'authored_v2', true);
