INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H151', 'TCM03', 'Secondary', 'Spleen Qi deficiency with cold, weak digestion: burdens the Spleen and can loosen the stool.', '{"title": "Grieve M. A Modern Herbal (1898 material medica tradition, published 1931), heading: Mallows (public domain).", "locator": "Grieve M. A Modern Herbal (1898 material medica tradition, published 1931), heading: Mallows (public domain).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Dioscorides, De Materia Medica, Malache (ancient Mediterranean anchor); Hoffmann D, Medical Herbalism; Mills S & Bone K, Principles and Practice of Phytotherapy; Batiha GE-S et al., a review of the phytochemistry, pharmacology, and safety o", "locator": "Dioscorides, De Materia Medica, Malache (ancient Mediterranean anchor); Hoffmann D, Medical Herbalism; Mills S & Bone K, Principles and Practice of Phytotherapy; Batiha GE-S et al., a review of the phytochemistry, pharmacology, and safety o", "source_id": "S18", "author": "Hoffmann \u2014 Medical Herbalism", "year": "2003", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI526', 'H151', 'pregnancy', 'Pregnancy', 'moderate', 'No clinical safety studies in pregnancy. The herb is a food-grade demulcent with no reported human toxicity, but concentrated or prolonged medicinal use is not established as safe.', 'Culinary and mild-tea amounts are considered low-risk; avoid concentrated or prolonged medicinal doses without qualified practitioner guidance.', 'Drugs.com Natural Products Database, Mallow (no clinical evidence for safe use in pregnancy or lactation); Batiha et al., Front. Pharmacol. review of Malva sylvestris, 2023 (PMC9898411).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI527', 'H151', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation studies exist. Food-grade with no documented human toxicity, but medicinal-strength use is not established as safe.', 'Prefer food-level and mild-tea amounts; seek practitioner guidance before medicinal-strength use.', 'Drugs.com Natural Products Database, Mallow; Batiha et al., Front. Pharmacol. review of Malva sylvestris, 2023.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI528', 'H151', 'drug_interaction', 'Oral medications taken concurrently, especially narrow-therapeutic-index drugs (levothyroxine, digoxin, lithium, insulin)', 'moderate', 'The gel-forming mucilage can coat the gut lining and delay or reduce the gastrointestinal absorption of drugs and nutrients taken at the same time, a class effect of demulcents.', 'Separate mallow from all oral medication by about 1 to 2 hours; take particular care with narrow-therapeutic-index drugs and monitor their effect.', 'Mills S & Bone K, Principles and Practice of Phytotherapy (demulcent mucilage and drug absorption); Brinker F, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI529', 'H151', 'condition', 'Cold, damp, phlegmatic constitution and loose, watery digestion', 'low', 'The cool, moist, mucilaginous nature can add dampness, burden weak digestion, and loosen the stool in cold or damp-dominant individuals.', 'Use heavier medicinal doses sparingly in cold, damp, phlegm-heavy or loose-bowel patterns; pair with warming, carminative herbs if needed.', 'Traditional Western and Eastern energetic classification; Hoffmann D, Medical Herbalism.');
