INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H152', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS24', 'Primary', 'The defining alterative action: disperses scrofulous and lymphatic/glandular stagnation and swollen glands.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS08', 'Primary', 'Stimulating depurative that moves stagnant, congested, morbid accumulation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS07', 'Primary', 'Resolves damp, boggy, weeping skin and congested lymph.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS05', 'Secondary', 'Cooling; clears heat from hot, eruptive skin and inflamed lymph.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS06', 'Secondary', 'Anti-inflammatory in acute skin and lymphatic inflammation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS25', 'Secondary', 'Vulnerary for chronic sores, ulcers, and non-healing lesions.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS23', 'Minor', 'Dissipates phlegm/nodular (scrofulous) accumulation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS17', 'Primary', 'Cooling herb aggravates cold, deficient terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS03', 'Secondary', 'Drying eliminative worsens frank dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS01', 'Secondary', 'A depurative is wrong for the frankly deficient without a toxic/damp excess.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H152', 'TS04', 'Minor', 'Draining elimination depletes the truly exhausted.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY11', 'Primary', 'Lymphatic: alterative and lymphagogue for scrofula, swollen glands, nodules.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY10', 'Primary', 'Integumentary: the premier depurative for chronic eczema, psoriasis, eruptions; topical vulnerary.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY12', 'Secondary', 'Hepatic: bitter hepatic stimulant supporting depurative clearance.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY09', 'Secondary', 'Urinary: mild diuretic elimination.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY08', 'Secondary', 'Digestive: mild laxative (iridoids); bitter.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY04', 'Minor', 'Musculoskeletal: rheumatic and gouty joints.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H152', 'SY06', 'Minor', 'Cardiovascular: cardioactive (positive inotrope), a caution more than a therapeutic use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A14', 'Primary', 'Alterative/depurative: the defining blood- and lymph-cleansing action for chronic skin disease.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A21', 'Primary', 'Lymphagogue: moves lymph, resolves scrofulous and glandular congestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A09', 'Primary', 'Anti-inflammatory (harpagoside and phenolic acids) for skin, lymph, and joints.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A24', 'Secondary', 'Vulnerary: heals wounds, ulcers, hemorrhoids, and skin lesions (topical ointment).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A08', 'Secondary', 'Mild diuretic: eliminative clearance through the kidneys.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A38', 'Secondary', 'Mild laxative/purgative (iridoids, aucubin).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A27', 'Secondary', 'Anodyne/analgesic for rheumatic and inflammatory pain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A28', 'Minor', 'Antimicrobial (phenolic acids).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A16', 'Minor', 'Bitter tonic / hepatic stimulant.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A10', 'Minor', 'Spasmolytic on smooth muscle (documented on isolated intestine).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A25', 'Minor', 'Antioxidant (flavonoids, phenolic acids).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H152', 'A07', 'Minor', 'Cardioactive (positive inotrope) from cardioactive glycosides; underlies the cardiac contraindication rather than a therapeutic use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP18', 'Primary', 'Chronic skin conditions of a congested, toxic picture (general).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP67', 'Primary', 'Eczema/atopic dermatitis, a signature indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP68', 'Primary', 'Psoriasis and scaly eruptive dermatoses.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP71', 'Primary', 'Lymphatic congestion, swollen glands, scrofula.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP61', 'Secondary', 'Hemorrhoids: the old Doctrine-of-Signatures use, topically and internally.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP08', 'Secondary', 'Poor wound healing: topical vulnerary for wounds, ulcers, bruises, burns.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP14', 'Secondary', 'Joint pain: rheumatism and gout.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP70', 'Secondary', 'Boils and abscesses of a toxic constitution.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP69', 'Minor', 'Acne and congested complexion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP13', 'Minor', 'Systemic inflammation underlying skin and joint disease.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP55', 'Minor', 'Constipation: mild laxative action.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H152', 'CP09', 'Minor', 'Chronic infection / the historical scrofulous taint.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P05', 'Primary', 'Infusion of the dried flowering herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P01', 'Primary', 'Tincture of the fresh or dried herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P07', 'Primary', 'Ointment/salve of the fresh herb, the classic topical skin use.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P08', 'Secondary', 'Fresh poultice on wounds, swellings, and hemorrhoids.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P10', 'Secondary', 'Compress of the infusion for inflamed skin and bruises.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H152', 'P11', 'Minor', 'Fomentation for swollen glands and skin.');
