INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI530', 'H152', 'condition', 'Ventricular tachycardia and cardiac arrhythmia', 'absolute', 'Figwort contains cardioactive glycosides and increases the force of myocardial contraction, which can precipitate or worsen arrhythmia.', 'Do not use in ventricular tachycardia; avoid in any heart-rhythm disorder or with a pacemaker except under specialist supervision.', 'British Herbal Pharmacopoeia (cardioactive glycosides; avoid in ventricular tachycardia); NCCIH/WebMD figwort safety summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI531', 'H152', 'drug_interaction', 'Cardiac glycosides and antiarrhythmics (digoxin, digitoxin, digitalis)', 'absolute', 'Figwort''s own cardioactive glycosides are additive with digitalis-type drugs, raising the risk of glycoside toxicity and arrhythmia.', 'Avoid concurrent use with digoxin, digitalis, or antiarrhythmic medication.', 'British Herbal Pharmacopoeia; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI532', 'H152', 'pregnancy', 'Pregnancy', 'moderate', 'Safety not established; cardioactive-glycoside content makes medicinal use inadvisable.', 'Avoid medicinal use during pregnancy.', 'NCCIH/WebMD consumer safety summary (insufficient reliable data; avoid); Mills and Bone precautionary principle.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI533', 'H152', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety not established; no adequate data for the nursing infant and cardioactive constituents present.', 'Avoid medicinal use while breastfeeding.', 'NCCIH/WebMD consumer safety summary (insufficient reliable data; avoid).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI534', 'H152', 'drug_interaction', 'Lithium', 'moderate', 'Figwort''s diuretic action may reduce lithium clearance and raise serum lithium toward toxic levels.', 'Avoid with lithium unless serum levels are monitored by the prescriber.', 'NCCIH/WebMD figwort drug-interaction summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI535', 'H152', 'drug_interaction', 'Potassium-depleting diuretics', 'moderate', 'Additive with figwort''s diuretic action, which can increase urinary potassium loss.', 'Avoid combining, or monitor serum potassium if co-administered.', 'NCCIH/WebMD figwort drug-interaction summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI536', 'H152', 'drug_interaction', 'Antidiabetic / hypoglycemic medications', 'low', 'Figwort may lower blood glucose, giving an additive hypoglycemic effect.', 'Monitor blood glucose; coordinate dose changes with the prescriber.', 'NCCIH/WebMD figwort safety summary (blood-sugar caution).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI537', 'H152', 'pediatric', 'Young children (internal use)', 'moderate', 'No pediatric safety data; cardioactive-glycoside and laxative-diuretic activity make internal use inappropriate.', 'Avoid internal use in children; dilute topical use to intact skin only, under guidance.', 'NCCIH/WebMD consumer safety summary (insufficient data).');
