INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI538', 'H153', 'pregnancy', 'Pregnancy', 'moderate', 'A strong Qi- and Blood-moving herb used to regulate and unblock menstruation, with estrogen-modulating sesquiterpenes; theoretical risk of stimulating uterine activity. Adequate human safety data are lacking.', 'Avoid in pregnancy except under qualified professional supervision; do not self-treat.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI539', 'H153', 'breastfeeding', 'Breastfeeding', 'low', 'Long traditional use in nursing mothers (Ayurvedic stanya-shodhana) but no formal modern lactation safety data.', 'Small traditional culinary or decoction amounts have a long record; take therapeutic doses only under professional guidance.', 'Ayurvedic Pharmacopoeia of India (Musta); no modern human lactation data located.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI540', 'H153', 'condition', 'Yin or Blood deficiency with dryness and heat', 'moderate', 'The aromatic, acrid, drying, Qi-scattering nature consumes fluids and Blood, worsening deficiency dryness.', 'Avoid or combine with fluid- and Blood-nourishing herbs in Yin- or Blood-deficient patients.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI541', 'H153', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Cyperus rotundus has documented hypoglycemic activity that may add to glucose-lowering medication.', 'Monitor blood glucose and watch for hypoglycemia if combined with antidiabetic drugs.', 'Modern pharmacology reviews of Cyperus rotundus (Phytochemistry Reviews, 2023, PMC10183317; Cyperi Rhizoma review, PMC9585201).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI542', 'H153', 'drug_interaction', 'Hormonal therapy and hormone-sensitive conditions', 'moderate', 'Sesquiterpenes from the rhizome modulate estrogen receptor-alpha and -beta (both estrogenic and antiestrogenic effects).', 'Use caution alongside hormone therapy or oral contraceptives and in hormone-sensitive conditions; seek professional advice.', 'Bioassay-guided estrogenic-activity studies of Cyperus rotundus sesquiterpenes (phytochemistry reviews, 2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI543', 'H153', 'pediatric', 'Young children (concentrated extracts)', 'low', 'Traditional dilute decoctions have long pediatric use, but concentrated extracts and essential oil lack modern pediatric safety data.', 'Use only low, short-term doses of simple traditional preparations under professional guidance; avoid concentrated extracts and essential oil.', 'Ayurvedic Pharmacopoeia of India (Musta), traditional pediatric use; no modern pediatric trials located.');
