INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS07', 'Primary', 'Dries damp, boggy digestive and respiratory mucosa.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS08', 'Primary', 'Disperses stagnant, congested fluids and stuck function.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS23', 'Secondary', 'Warms and moves cold phlegm.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS19', 'Secondary', 'Rouses torpid, sluggish digestion and metabolism.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS18', 'Secondary', 'Aromatic antispasmodic easing cold, cramping tension of the gut.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS03', 'Primary', 'Warm, drying nature aggravates dry, irritable coughs and parched mucosa.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS05', 'Primary', 'Adds heat to excess-heat and hot-infection patterns.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H154', 'TS06', 'Secondary', 'Not for acute, hot inflammation.');
