INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI544', 'H154', 'population', 'Pregnancy (therapeutic doses and essential oil)', 'absolute', 'Traditional emmenagogue; the carvacrol- and thymol-rich essential oil is a potential uterine stimulant, so amounts above food use raise a theoretical miscarriage risk.', 'Culinary food amounts are considered safe. Avoid concentrated medicinal preparations, standardized extracts, and the essential oil throughout pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions; American Pregnancy Association.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI545', 'H154', 'population', 'Lactation (medicinal doses and essential oil)', 'moderate', 'No reliable safety data for therapeutic doses or the oil during breastfeeding.', 'Dietary culinary amounts are acceptable; avoid concentrated medicinal doses and the essential oil.', 'AHPA Botanical Safety Handbook, 2nd ed.; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI546', 'H154', 'drug_interaction', 'Anticoagulant and antiplatelet medications (warfarin, aspirin, clopidogrel)', 'moderate', 'Carvacrol and thymol inhibit platelet aggregation and oregano polyphenols inhibit CYP2C9 and CYP3A4 in vitro, which may add to bleeding risk with large or concentrated doses.', 'Avoid large medicinal doses with these drugs; culinary use is fine. Monitor for bruising or bleeding and discontinue high doses about two weeks before surgery.', 'Brinker, Herb Contraindications and Drug Interactions; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI547', 'H154', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Oregano may lower blood glucose, giving a theoretical additive hypoglycemic effect.', 'Monitor blood glucose if concentrated oregano is combined with glucose-lowering therapy; human data are limited.', 'Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI548', 'H154', 'condition', 'Bleeding disorders and scheduled surgery', 'moderate', 'Antiplatelet activity of carvacrol and thymol may increase bleeding tendency at high doses.', 'Avoid concentrated doses with bleeding disorders and discontinue them about two weeks before surgery.', 'NCCIH; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI549', 'H154', 'condition', 'Allergy to oregano or other Lamiaceae (mint-family) herbs', 'moderate', 'IgE-mediated cross-reactivity within Lamiaceae; systemic reactions have followed ingestion of oregano and thyme in sensitized people.', 'Avoid in anyone with known allergy to oregano, basil, marjoram, mint, sage, or thyme.', 'Benito et al., Labiatae allergy: systemic reactions due to ingestion of oregano and thyme (Annals of Allergy, Asthma and Immunology).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI550', 'H154', 'other', 'Undiluted essential oil (skin, mucous membranes, young children)', 'moderate', 'The carvacrol- and thymol-rich oil is a strong skin and mucous-membrane irritant when applied neat or taken undiluted.', 'Always dilute the essential oil; never apply it neat or to mucous membranes; do not give the oil internally to infants or young children.', 'Tisserand and Young, Essential Oil Safety, 2nd ed. (2014).');
