INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H154', 'EP08', 'match', 2, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Marjorams / Wild Marjoram (Origanum vulgare); Culpeper, The English Physician / Complete Herbal (1653), Wild Marjoram (Organy); Dioscorides, De Materia Medica (origanon).", "locator": "Grieve, A Modern Herbal (1931), Marjorams / Wild Marjoram (Origanum vulgare); Culpeper, The English Physician / Complete Herbal (1653), Wild Marjoram (Organy); Dioscorides, De Materia Medica (origanon).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (2013); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH; American Pregnancy Association; Benito et al., Labiatae allergy: systemic", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (2013); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; NCCIH; American Pregnancy Association; Benito et al., Labiatae allergy: systemic", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H155', 'Parsley', 'Petroselinum crispum (Mill.) Fuss', 'Apiaceae (Umbelliferae), the carrot and celery family', 'Root, leaf (aerial herb), and ripe seed (fruit); the seed is the strongest and most volatile-oil-rich part', 'Pungent (aromatic), Bitter; the leaf and root carry a mild green sweetness', 'Warm', 'Dry', 'Torpor and cold, boggy sluggishness of the kidneys and lower pelvis: the water-logged, under-firing system that holds fluid it cannot move. Dampness and fluid stagnation, as in dropsical swelling, gravel, and a slow, congested urinary tract that needs warming stimulation to drain. A cold, torpid, congested uterus with scanty, delayed, or suppressed menses that a warming aromatic stimulant rouses back into flow.', 'Acute inflammation and irritation of the kidneys and urinary tract: active nephritis, acute cystitis, and any hot, inflamed, or bleeding condition of the renal tissue, which the warming, irritant volatile oil aggravates. Excess heat and a dry, depleted constitution, where an over-warming, over-drying diuretic further heats and dries already deficient tissue.', 'Urinary (kidneys and bladder: the archetypal warming irrigant diuretic for gravel and fluid retention); Reproductive (uterus: emmenagogue for cold, delayed, scanty menses). Secondary action on the Digestive tract (aromatic carminative for flatulence and bloating) and on the Musculoskeletal system and joints (traditional depurative for gout and rheumatism through elimination of uric acid).', 'Fluid retention and dropsical swelling; urinary gravel and small stones (Commission E irrigation therapy); irrigation of the lower urinary tract in mild, uncomplicated cystitis; scanty, delayed, or suppressed menstruation; painful menstruation of the cold, congested type; flatulence and bloating; gout and rheumatic complaints linked to poor uric-acid clearance; and, in food amounts, halitosis (the classic breath freshener after garlic and onion).', 'Cold-Damp-Stagnant: the phlegmatic, boggy, fluid-retaining, water-logged type with a cold, sluggish, congested pelvis and kidneys that a warming aromatic stimulant drains and moves. Not for the hot, dry, robust Pitta-like type, and not for anyone with acutely inflamed, hot, or bleeding kidneys.', 'Kapha', 'Pitta, Vata', 'Cold-Damp accumulation of the Lower Jiao with fluid retention and difficult, scanty urination (a warming, draining diuretic that transforms Dampness and promotes urination), and Qi and Blood stagnation of the uterus with cold, delayed, or suppressed menses that a warm, moving, aromatic herb frees.', 'Yin deficiency with empty Heat and dryness, and true Heat or Fire patterns, where the warm, dry, aromatic nature scorches fluids and aggravates heat. Also inappropriate in Blood deficiency with dryness, which the drying diuretic worsens.', 'Draw a sharp line between food and medicine. Parsley as a leaf, garnish, and potherb is safe, but the seed, the essential oil, and the isolated constituents apiole and myristicin are toxic in quantity, with documented poisonings and deaths (notably from apiol taken to procure abortion) causing gastrointestinal, hepatic, renal, and neurological harm. Never take the essential oil internally. The volatile oil and the furanocoumarins (bergapten, psoralen, xanthotoxin) can provoke phototoxic and contact dermatitis, especially with heavy or occupational handling. Avoid medicinal doses in kidney inflammation and in pregnancy (see the dedicated safety fields).', 'Pregnancy in medicinal amounts (seed, oil, apiole, and concentrated extracts). Acute or inflammatory kidney disease (nephritis), and edema arising from impaired heart or kidney function, for which Commission E specifically contraindicates irrigation therapy. Known allergy to Apiaceae plants (carrot, celery, fennel, dill, anise), which cross-react. Internal use of the isolated essential oil at any time.', 'Culinary amounts (leaf as food and garnish) are recognized as safe. Avoid all medicinal and concentrated amounts during pregnancy: the German Commission E lists pregnancy as a contraindication, and the seed, the essential oil, and their isolated apiole and myristicin are documented uterine stimulants used historically as emmenagogues and abortifacients, with recorded cases of severe maternal poisoning and death from apiol taken to end pregnancy. Do not use parsley seed, essential oil, or concentrated extracts in pregnancy. Sources: German Commission E (Petroselini herba and radix); AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions.', 'Food amounts are compatible with nursing. Avoid medicinal and large amounts: parsley is a traditional anti-galactagogue and is combined with sage in commercial preparations sold to reduce or dry up milk, so therapeutic doses may lower supply in a mother wishing to maintain it. The NIH LactMed database notes there are no data on the excretion of parsley constituents into breast milk and warns that the essential oil should not be used because of the toxicity of its apiole and myristicin. Sources: NIH LactMed (Drugs and Lactation Database), Parsley; AHPA Botanical Safety Handbook, 2nd ed.', 'Food amounts are safe (parsley is GRAS as a food). No therapeutic dose is established for young children, and the apiole-rich seed and the essential oil must never be given internally to infants or children because of their toxicity. A dilute leaf tea in small amounts follows ordinary culinary tradition; reserve medicinal diuretic and emmenagogue use for adults. Sources: NIH LactMed; AHPA Botanical Safety Handbook (culinary and GRAS status).', 'Warfarin and other vitamin-K-antagonist anticoagulants: parsley leaf is high in vitamin K and can antagonize warfarin and reduce its effect; a published case linked long-term intake of a parsley-containing herbal product to disturbed INR that settled after stopping. Keep vitamin K intake consistent, avoid large medicinal amounts, and monitor INR. Lithium: the diuretic action of parsley seed may reduce lithium clearance and raise serum lithium toward toxic levels; avoid medicinal diuretic doses with lithium and monitor levels. Diuretic and antihypertensive drugs: parsley seed adds to fluid and potassium loss while high leaf or root intake may promote retention, either of which can disturb the drug''s effect; monitor. Antidiabetic drugs: parsley has documented blood-glucose-lowering activity and may add to insulin and oral hypoglycemics; monitor blood glucose. At culinary and food amounts no clinically significant interactions are documented. Sources: NCCIH; AHPA Botanical Safety Handbook; Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; Drugs.com and WebMD parsley monographs.', 'Infusion (tea) of the dried or fresh leaf; decoction of the root or of the crushed seed (the stronger diuretic form); tincture of leaf, root, or seed; freshly pressed juice of the leaf; and generous use of the fresh leaf as a potherb and garnish in soups and food. The isolated essential oil is not used internally.', 'Leaf infusion: 2 to 4 g dried leaf (or a generous fresh handful) in 150 mL water, up to three times daily. Root decoction: 2 to 4 g simmered, three times daily. Crushed-seed infusion or decoction (stronger, for gravel and dropsy, short courses only): 1 to 2 g up to three times daily. Tincture (1:5 in 40 to 45 percent alcohol): 2 to 4 mL three times daily. Fresh juice, traditionally 1 to 2 teaspoons. Commission E average daily dose: 6 g of the herb or root. Do not use the isolated essential oil internally.', 'King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.', 'German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; NIH LactMed (Drugs and Lactation Database), Parsley; NCCIH; Herbal Reality (Parsley) practitioner monograph; United Plant Savers.', 'Family Apiaceae. Grown in three main forms: curly-leaf (var. crispum), flat-leaf or Italian (var. neapolitanum), and Hamburg root parsley (var. tuberosum); the accepted binomial is Petroselinum crispum, with the synonyms P. sativum and P. hortense in older texts. Key constituents: the flavonoids apigenin and luteolin (as the glycoside apiin), a volatile oil rich in myristicin and apiole (highest in the seed, roughly 2 to 7 percent oil), furanocoumarins (bergapten, psoralen, xanthotoxin), abundant vitamin C, iron, chlorophyll, and notably high vitamin K. The diuretic action is attributed to apiole and myristicin inhibiting the renal Na+/K+ pump, increasing sodium and water excretion; the same volatile principles drive the emmenagogue and, in quantity, the abortifacient and toxic effects, apiole having once been sold as apiol for exactly those purposes with fatal results. The green leaf, rich in chlorophyll, is the traditional after-meal breath freshener. King''s American Dispensatory treats parsley as a diuretic and emmenagogue and separately catalogs apiol as its active abortifacient principle.', 'Not named in canonical Scripture. Parsley is native to the central and eastern Mediterranean and was well known to the Greeks and Romans: Dioscorides (De Materia Medica, petroselinon, rock-parsley) and Pliny describe it as a diuretic and emmenagogue, and the Greeks wove it into funeral wreaths and into the victors'' crowns of the Isthmian and Nemean games. The name petroselinon means rock-celery, from petra (rock) and selinon (celery or parsley).', 'Not at-risk. Parsley is a cultivated biennial grown worldwide as a kitchen herb and commercial crop, not wild-harvested from threatened populations, and it is not listed by United Plant Savers. It is easily grown at home from seed; prefer organically grown leaf, root, and seed.', 'Warm, dry, and draining: an aromatic stimulant diuretic that flushes stagnant water from cold, boggy kidneys and warms and moves a sluggish, congested pelvis.', 'Refer for blood in the urine, severe or one-sided flank pain, fever with urinary symptoms, or inability to pass urine (possible obstructing stone, pyelonephritis, or serious kidney disease); for new or worsening generalized swelling, breathlessness, or edema suggesting heart or kidney failure; and for any pregnancy in which an herb has been taken in medicinal amounts. Diuretic and emmenagogue herbs support, but never replace, evaluation of the cause of fluid retention, stones, or menstrual change.', 'Parsley: PARS-lee. Petroselinum crispum: pet-roh-seh-LY-num KRIS-pum.', 'free', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "locator": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
