INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS19', 'Primary', 'Warms and rouses cold, torpid, sluggish kidney and pelvic function.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS07', 'Primary', 'Drains dampness and retained fluid: dropsy, edema, gravel.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS08', 'Secondary', 'Moves stagnant fluid and blood in a congested lower pelvis; suppressed menses.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS17', 'Minor', 'Warming to a cold, boggy, under-firing constitution.');
