INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS05', 'Secondary', 'Warming nature aggravates excess heat and hot, bleeding urinary conditions.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H155', 'TS03', 'Minor', 'Over-drying to an already dry, depleted constitution.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H155', 'SY09', 'Primary', 'Kidneys and bladder; the archetypal warming irrigant diuretic for gravel and fluid retention.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H155', 'SY03', 'Primary', 'Uterus; emmenagogue for cold, scanty, delayed, or suppressed menses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H155', 'SY08', 'Secondary', 'Aromatic carminative for flatulence and bloating.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H155', 'SY04', 'Minor', 'Traditional depurative for gout and rheumatism via uric-acid elimination.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A08', 'Primary', 'Warming stimulant diuretic; irrigation of the urinary tract, gravel, dropsy.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A19', 'Primary', 'Emmenagogue; apiole and myristicin rouse scanty, delayed, suppressed menses. Basis of the pregnancy contraindication.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A17', 'Secondary', 'Carminative; relieves flatulence and bloating.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A42', 'Secondary', 'Anti-galactagogue; traditionally reduces or dries up milk supply.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A14', 'Secondary', 'Alterative depurative; traditional for gout and rheumatism through elimination.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A25', 'Secondary', 'Antioxidant; rich in apigenin, luteolin, and vitamin C.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H155', 'A41', 'Minor', 'Oxytocic and abortifacient in high-dose apiole; the toxic basis of the pregnancy ban.');
