INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP30', 'Primary', 'Amenorrhea: scanty, delayed, or suppressed menses; the classic warming emmenagogue.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP63', 'Secondary', 'Irrigation of the lower urinary tract in mild, uncomplicated cystitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP20', 'Secondary', 'Menstrual irregularity of the cold, congested type.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP29', 'Secondary', 'Painful menstruation with delayed, congested flow.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP54', 'Secondary', 'Bloating and flatulence; aromatic carminative.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP14', 'Minor', 'Gout and rheumatic joint pain; depurative uric-acid elimination.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H155', 'CP27', 'Minor', 'Blood-sugar dysregulation; documented hypoglycemic activity.');
