INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H155', 'TCM08', 'Secondary', 'Moves Qi and Blood stagnation of the uterus; frees cold, suppressed menses.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "locator": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H155', 'TCM07', 'Primary', 'Warm, dry, aromatic nature scorches fluids and aggravates Yin deficiency with empty Heat.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "locator": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H155', 'TCM11', 'Secondary', 'Warming action aggravates true Heat and Fire patterns.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Petroselinum (Parsley), and the related entry Apiol.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "locator": "German Commission E Monographs, Parsley herb and Parsley root (Petroselini herba, Petroselini radix); Grieve, A Modern Herbal (1931), Parsley; Culpeper, The English Physician; Dioscorides, De Materia Medica (petroselinon); AHPA Botanical Sa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI551', 'H155', 'pregnancy', 'Pregnancy (medicinal seed, essential oil, apiole, and concentrated extracts)', 'absolute', 'Apiole and myristicin are uterine stimulants; the seed and oil act as emmenagogues and, in quantity, abortifacients, with documented cases of severe maternal poisoning and death from apiol taken to end pregnancy.', 'Culinary leaf amounts are fine. Do not use parsley seed, essential oil, or concentrated extracts during pregnancy.', 'German Commission E (Petroselini herba and radix); AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI552', 'H155', 'condition', 'Acute or inflammatory kidney disease (nephritis); edema from impaired heart or kidney function', 'absolute', 'The warming, irritant volatile oil (apiole, myristicin) increases renal epithelial blood flow and irritates inflamed kidney tissue; irrigation is inappropriate where edema stems from cardiac or renal failure.', 'Do not use for irrigation therapy in nephritis or in edema caused by impaired heart or kidney function.', 'German Commission E (Parsley herb and root); Drugs.com professional monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI553', 'H155', 'breastfeeding', 'Breastfeeding (medicinal amounts)', 'moderate', 'Traditional anti-galactagogue that may reduce milk supply; no data on excretion into milk; the essential oil is toxic (apiole, myristicin).', 'Culinary amounts are fine. Avoid medicinal, seed, and oil doses while nursing, especially if maintaining supply.', 'NIH LactMed (Drugs and Lactation Database), Parsley; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI554', 'H155', 'drug_interaction', 'Warfarin and vitamin-K-antagonist anticoagulants', 'moderate', 'Parsley leaf is high in vitamin K, which antagonizes warfarin and can lower its anticoagulant effect; a case report linked long-term parsley-containing herbal intake to disturbed INR that settled on stopping.', 'Keep vitamin K intake consistent, avoid large medicinal amounts, and monitor INR.', 'NCCIH; clinical herb-warfarin interaction reviews; WebMD parsley monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI555', 'H155', 'drug_interaction', 'Lithium', 'moderate', 'The diuretic action of parsley seed may reduce lithium clearance and raise serum lithium toward toxic levels.', 'Avoid medicinal diuretic doses of parsley with lithium; monitor serum lithium.', 'Drugs.com and WebMD parsley monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI556', 'H155', 'drug_interaction', 'Diuretic and antihypertensive drugs', 'moderate', 'Parsley seed adds to fluid and potassium loss, while high leaf or root intake may promote retention; either can disturb the drug''s intended effect and electrolyte balance.', 'Use only culinary amounts with these drugs, or monitor fluid status and electrolytes.', 'German Commission E; WebMD parsley monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI557', 'H155', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Parsley has documented blood-glucose-lowering activity that may add to hypoglycemic drugs.', 'Monitor blood glucose if taking parsley medicinally with diabetic medication.', 'Mills and Bone, Principles and Practice of Phytotherapy; WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI558', 'H155', 'pediatric', 'Infants and young children', 'moderate', 'No established therapeutic dose; the apiole-rich seed and essential oil are toxic to children.', 'Food amounts are fine; do not give the seed, oil, or apiole internally to infants or children.', 'NIH LactMed; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI559', 'H155', 'other', 'Apiaceae allergy and photosensitivity', 'low', 'Cross-reactivity with carrot, celery, fennel, and dill; furanocoumarins (bergapten, psoralen, xanthotoxin) can cause phototoxic and contact dermatitis with heavy handling.', 'Avoid in known Apiaceae allergy; handlers should limit skin contact and sun exposure.', 'NIH LactMed; Drugs.com professional monograph.');
