INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H156', 'C06', 'Indicated', 'Primary', 'Robust/Hot (Pitta-like): tense, bilious, gassy digestion; androgen excess', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Mentha Viridis (Spearmint; the entry treats Mentha viridis L., an older synonym of Mentha spicata L.). Corroborated by Grieve, A Modern Herbal (1931) - Mint, Spearmint.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Mentha Viridis (Spearmint; the entry treats Mentha viridis L., an older synonym of Mentha spicata L.). Corroborated by Grieve, A Modern Herbal (1931) - Mint, Spearmint.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills & Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; NCCIH (peppermint / spearmint safety); Grant P., Spearmint herbal tea has significant anti-androgen effects in polycystic ovarian syndrome: a randomized con", "locator": "Mills & Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; NCCIH (peppermint / spearmint safety); Grant P., Spearmint herbal tea has significant anti-androgen effects in polycystic ovarian syndrome: a randomized con", "source_id": "S18", "author": "Hoffmann \u2014 Medical Herbalism", "year": "2003", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
