INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI560', 'H156', 'pregnancy', 'Pregnancy (medicinal high-dose tea or internal essential oil)', 'moderate', 'Spearmint has a demonstrated anti-androgen, hormone-modulating effect, and concentrated spearmint tea has produced uterine oxidative stress in animal studies; therapeutic doses are unstudied and lack a demonstrated safety margin in pregnancy.', 'Food and light culinary tea are acceptable; avoid concentrated medicinal doses and internal essential oil during pregnancy.', 'Grant 2010 (Phytotherapy Research, anti-androgen RCT); animal uterine oxidative-stress data on concentrated M. spicata tea; NCCIH-style insufficient-data precaution.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI561', 'H156', 'breastfeeding', 'Breastfeeding (large or concentrated medicinal amounts)', 'low', 'Mints carry a traditional anti-galactagogue reputation (possible reduction of milk supply); modern controlled lactation data are limited.', 'Culinary and light tea amounts are acceptable; nursing mothers wishing to protect supply should avoid large or concentrated medicinal doses.', 'Traditional anti-galactagogue caution for Mentha species; Mills & Bone; absence of controlled lactation studies (NCCIH-style note).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI562', 'H156', 'drug_interaction', 'Anti-androgen and androgen/hormone therapies (spironolactone, finasteride, cyproterone; testosterone replacement)', 'moderate', 'Spearmint tea significantly lowered free and total testosterone in controlled trials; the effect may be additive with anti-androgen drugs and could theoretically oppose testosterone-replacement therapy.', 'Monitor when sustained medicinal spearmint tea is combined with hormone-modulating drugs; coordinate changes with the prescriber.', 'Grant P., Phytotherapy Research 2010;24(2):186-188 (PMID 19585478); Akdogan M. et al., Phytotherapy Research 2007;21(5):444-447 (PMID 17310494).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI563', 'H156', 'condition', 'Gastroesophageal reflux disease / hiatal hernia', 'low', 'Like other mints, spearmint can relax the lower esophageal sphincter and may aggravate reflux symptoms, though it is milder and lower in menthol than peppermint.', 'Reflux-prone patients should monitor tolerance and reduce or discontinue if symptoms worsen.', 'Mills & Bone, Principles and Practice of Phytotherapy; NCCIH peppermint monograph (cautiously extended to spearmint).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI564', 'H156', 'condition', 'Low testosterone, male subfertility, or hormone-sensitive concerns', 'low', 'Sustained high-dose spearmint tea lowers androgens; concentrated tea affected reproductive parameters in male rat studies.', 'Men with low testosterone or fertility concerns should avoid sustained high-dose medicinal tea; occasional culinary use is not a concern.', 'Grant 2010 (Phytotherapy Research); male-rat reproductive toxicity study (PMC4224956); Mills & Bone interaction principles.');
