INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H157', 'TCM01', 'Minor', 'Cold nature aggravates Kidney Yang Deficiency / interior Cold', '{"title": "Grieve, A Modern Herbal (1931) - Vervain (Verbena officinalis). Corroborating public-domain texts: Culpeper, The Complete Herbal (1653) - Vervain; King''s American Dispensatory (Felter & Lloyd, 1898) - Verbena.", "locator": "Grieve, A Modern Herbal (1931) - Vervain (Verbena officinalis). Corroborating public-domain texts: Culpeper, The Complete Herbal (1653) - Vervain; King''s American Dispensatory (Felter & Lloyd, 1898) - Verbena.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Modern: NIH LactMed (Drugs and Lactation Database, Vervain, NBK501852); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytothe", "locator": "Modern: NIH LactMed (Drugs and Lactation Database, Vervain, NBK501852); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytothe", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI565', 'H157', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Long-documented uterine-stimulant, oxytocic and emmenagogue action (iridoid glycoside verbenalin); reported dopamine-receptor binding with luteinizing-hormone stimulation; animal reproductive studies report reduced fetal weight gain and reduced bone ossification.', 'Avoid throughout pregnancy in medicinal amounts, including tea and tincture.', 'AHPA Botanical Safety Handbook, 2nd ed. (contraindicated in pregnancy; reported safety class 2b); Brinker, Herbal Contraindications and Drug Interactions; corroborated by Chinese materia medica (Ma Bian Cao contraindicated in pregnancy).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI566', 'H157', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion of vervain components into breastmilk or on infant safety; galactagogue reputation is unproven; contains uterine-active iridoid glycosides.', 'Avoid medicinal doses during lactation; occasional culinary-strength tea is likely low-risk. Do not rely on vervain as a galactagogue.', 'NIH LactMed (Drugs and Lactation Database, Vervain, NBK501852).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI567', 'H157', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Vervain has a mild hypotensive effect that may be additive with blood-pressure-lowering medication.', 'Monitor blood pressure; watch for dizziness or hypotension when combining.', 'drugs.com Natural Products database (Vervain); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI568', 'H157', 'drug_interaction', 'Anticoagulants / antiplatelets (e.g. warfarin)', 'moderate', 'Conflicting theoretical concern: vervain''s vitamin K content may antagonize warfarin, while general antiplatelet caution is also cited for the herb.', 'Monitor INR, keep intake consistent, and avoid large or fluctuating doses; coordinate with the prescriber.', 'drugs.com Natural Products database (Vervain); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI569', 'H157', 'drug_interaction', 'CNS depressants / sedatives', 'low', 'Documented sedative and anxiolytic activity in animal models suggests additive central depression.', 'Use caution with sedatives, hypnotics or alcohol; watch for excess drowsiness.', 'Anticonvulsant, Anxiolytic and Sedative Activities of Verbena officinalis (PMC5174135); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI570', 'H157', 'condition', 'Menorrhagia / endometriosis / heavy uterine bleeding', 'moderate', 'Emmenagogue and blood-moving action may increase menstrual or uterine bleeding.', 'Avoid or use only under practitioner supervision in heavy or abnormal uterine bleeding.', 'Botanical safety literature (uterine-stimulant reputation); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI571', 'H157', 'condition', 'Cold, dry, depleted constitution (frank deficiency)', 'moderate', 'Cool, drying, bitter, dispersing nature depletes true cold or deficiency states rather than nourishing them.', 'Avoid as a sole remedy in frank cold-dry depletion, or pair with warming, nourishing tonics.', 'Traditional energetic contraindication (Western and Ayurvedic energetics; Chinese materia medica).');
