INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H157', 'EP08', 'avoid', 1, 2, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Vervain (Verbena officinalis). Corroborating public-domain texts: Culpeper, The Complete Herbal (1653) - Vervain; King''s American Dispensatory (Felter & Lloyd, 1898) - Verbena.", "locator": "Grieve, A Modern Herbal (1931) - Vervain (Verbena officinalis). Corroborating public-domain texts: Culpeper, The Complete Herbal (1653) - Vervain; King''s American Dispensatory (Felter & Lloyd, 1898) - Verbena.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Modern: NIH LactMed (Drugs and Lactation Database, Vervain, NBK501852); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytothe", "locator": "Modern: NIH LactMed (Drugs and Lactation Database, Vervain, NBK501852); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytothe", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H158', 'Pippali (Long Pepper)', 'Piper longum', 'Piperaceae (pepper family)', 'Fruit: the small dried fruiting spikes (catkins), gathered while still green and unripe and dried until blackish. The root and thicker stem base (pippali mula, piplamool) are used separately in Ayurveda; this record concerns the fruit spike.', 'Pungent (katu). Ayurveda notes an unusual sweet post-digestive effect (madhura vipaka) and a slightly unctuous quality, so it is warming and pungent yet gentler and less drying than black pepper.', 'Hot', 'Dry', 'Cold and torpor of the digestion and metabolism: the weak, under-firing digestive fire (mandagni) that leaves food undigested with gas, heaviness, and cold. Atony and laxity of a slack, cold stomach and bowel. Cold, boggy accumulation of thin, watery phlegm in weak lungs, with chronic cold cough and wheeze. Deficiency and depletion of digestive and respiratory vitality, where a warming stimulant tonic (rasayana) is needed to rekindle heat and restore tone. Exhaustion of metabolic fire in the cold, sluggish, phlegmatic constitution.', 'Excess heat and acute inflammation: active gastritis, hyperacidity, peptic ulcer, and acid reflux, which a hot, acrid stimulant aggravates. Dryness and fluid depletion, and heat-type or yin-deficient constitutions with thirst, burning, or red inflamed mucosa. States of over-excitation and irritability, where a warming stimulant adds unwanted heat and drive.', 'Digestive (stomach, small intestine, and the metabolic digestive fire); Respiratory and lungs (chronic cold, phlegmatic cough, wheeze, and as a lung rejuvenative). Secondary action on the Spleen and middle burner (TCM), on peripheral Circulation (a warming, dispersing stimulant), and on the Immune and metabolic terrain as a rasayana and thermogenic.', 'Weak, cold digestion with low digestive fire, gas, bloating, and heaviness; cold colic and cramping; nausea and vomiting of the cold, under-toned stomach; chronic cold cough, bronchial congestion, wheeze, and asthmatic tendency of the phlegmatic, cold-damp type; recurrent colds and the onset of cold, shivery infection; sluggish metabolism and fatigue; intestinal worms; and, classically, use as a bioavailability enhancer (yogavahi) that carries and potentiates other remedies. Traditionally applied for toothache.', 'Cold-Damp-Relaxed and cold-depleted: the phlegmatic, boggy, sluggish, cold constitution with weak digestion and damp, congested lungs, and the thin, cold, depleted (Vata-like) person who runs cold and under-fired. A warming stimulant tonic that rekindles heat and tone. Not for the hot, robust, choleric (Pitta-like) constitution, which it overheats.', 'Vata, Kapha', 'Pitta', 'Bi Bo. Cold of the Spleen and Stomach (middle burner) with epigastric and abdominal pain, cold vomiting, hiccup, and cold-type diarrhea; it warms the middle, dispels cold, and descends rebellious Qi. It also warms and transforms cold phlegm and cold accumulation, and is applied locally for toothache. Acrid and hot, entering Stomach and Large Intestine.', 'Heat and Fire patterns, and Yin deficiency with heat signs (thirst, night sweats, red tongue, burning). The acrid, hot nature strongly aggravates any pattern of internal heat, so it is reserved for genuine cold and cold-phlegm patterns, not for heat, dryness, or deficiency-fire.', 'A hot, acrid stimulant. Large or prolonged doses can irritate the stomach and aggravate heat, hyperacidity, reflux, and inflamed or ulcerated mucosa, and may feel over-heating in hot, dry, or Pitta constitutions. Its most important modern caution is pharmacological: pippali is rich in piperine, a potent inhibitor of drug-metabolizing enzymes and transporters that can raise blood levels of many co-administered medicines (see Drug Interactions). Use only culinary amounts, or none, alongside narrow-therapeutic-index drugs unless supervised.', 'Active peptic ulcer, acute gastritis, and hyperacidity or acid reflux; hot, inflammatory, or yin-deficient heat conditions with burning and thirst; known hypersensitivity to pepper (Piper) species. Concurrent use of narrow-therapeutic-index medications without supervision (piperine interaction). Pregnancy and lactation in therapeutic doses (see safety fields).', 'Avoid therapeutic doses. Culinary spice amounts are generally regarded as safe, but concentrated medicinal doses should be avoided in pregnancy. Piperine, pippali''s principal alkaloid, shows anti-implantation, antifertility, and embryotoxic effects in rodents at therapeutic-scale doses, and adequate human safety data are lacking. Ayurvedic practice also treats pippali as strongly heating and reserves it in pregnancy. Sources: Malini and Vanithakumari, reproductive toxicity of piperine, Planta Medica 2000; postcoital antifertility effect of piperine, Contraception 1982; RxList (Indian long pepper); AHPA Botanical Safety Handbook (Piper longum); Mills and Bone.', 'Insufficient data; avoid therapeutic doses. There is no reliable human safety information for medicinal doses of pippali during lactation, and piperine is pharmacologically active and can alter the handling of other substances. Culinary use in food is not a concern; concentrated supplements or extracts are best avoided while breastfeeding. Sources: RxList (Indian long pepper); AHPA Botanical Safety Handbook; precautionary practice.', 'Culinary amounts are fine. Small doses of pippali with honey are a classical Ayurvedic remedy for children''s cough, but formal pediatric safety data for medicinal doses are lacking and the herb is heating and irritant in excess. Use only low, short-term doses for a child under professional guidance, and avoid concentrated piperine supplements in children. Sources: traditional Ayurvedic pediatric use (Nadkarni); precautionary practice; no formal pediatric safety studies.', 'Significant and well-documented. Pippali is rich in piperine, which inhibits the drug-metabolizing enzymes CYP3A4 and CYP2C9 and the efflux transporter P-glycoprotein, and slows first-pass metabolism. This raises the blood levels and effect of many co-administered drugs and can push narrow-therapeutic-index medicines toward toxicity. Human studies show piperine (about 20 mg/day) increases the bioavailability of propranolol and theophylline (Bano et al., Eur J Clin Pharmacol 1991), phenytoin (Bano et al. 1987), and rifampicin, and it raises exposure to CYP3A4 substrates (carbamazepine, midazolam), CYP2C9 substrates (diclofenac, phenytoin, and possibly warfarin), and P-glycoprotein substrates (fexofenadine, possibly digoxin); it famously increases curcumin absorption about twentyfold (Shoba et al. 1998). Use caution also with additive effects on antidiabetic drugs, as piperine may lower blood sugar. Culinary spice amounts pose little risk; medicinal doses and piperine supplements should be avoided or supervised in anyone on chronic medication. Sources: Bhardwaj et al., J Pharmacol Exp Ther 2002 (piperine inhibits human P-glycoprotein and CYP3A4); Bano et al. 1987, 1991; Pharmacy Times piperine drug-interaction review; Mills and Bone, Principles and Practice of Phytotherapy.', 'Powder (churna), often taken with honey or warm water; milk decoction (pippali simmered in milk), the classic rasayana and respiratory form; water decoction; honey syrup or linctus for cough; and as a culinary and formulary spice, notably in Trikatu (with black pepper and ginger) and in classical electuaries such as Chyawanprash. Tincture and honey electuary (avaleha) are also used.', 'Powder: 250 mg to 1 g once or twice daily, typically with honey, ghee, or warm milk (classical single doses up to about 1 to 2 g). Milk decoction: 1 to 3 g of fruit simmered in milk. Water decoction: 1 to 3 g. As Trikatu: usually 250 to 500 mg of the combined powder before meals. Begin low; pippali is potent and heating. The classical graduated rasayana (pippali vardhamana) escalates and then tapers the dose under guidance and is not a self-care regimen.', 'Grieve, A Modern Herbal (1931), Pepper (Long Pepper, Piper longum).', 'Nadkarni, Indian Materia Medica (Piper longum, Pippali); Bhavaprakasha Nighantu and Charaka Samhita (Pippali, Ayurvedic classics); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Bi Bo, Fructus Piperis Longi); Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed. (Piper longum); RxList (Indian long pepper); Bano et al., Eur J Clin Pharmacol 1991; Bhardwaj et al., J Pharmacol Exp Ther 2002; Malini and Vanithakumari, Planta Medica 2000.', 'Family Piperaceae. The pungency and pharmacology come chiefly from the alkaloid piperine, together with related amides (piperlongumine, also called piplartine, plus piperlonguminine and pipernonaline), lignans, and a volatile oil. Piperine is a well-studied bioenhancer: by inhibiting CYP3A4, CYP2C9, P-glycoprotein, and glucuronidation it slows metabolism and increases the absorption of many co-taken substances, the pharmacological basis of the Ayurvedic concept of pippali as yogavahi, a carrier that potentiates other remedies. In Ayurveda pippali is a premier Kapha- and Vata-reducing dipana-pachana (digestive kindler) and a rasayana for the lungs, given in the graduated pippali vardhamana rasayana for chronic cough, asthma, and debility; it is one of the three peppers of Trikatu. In TCM the fruit is Bi Bo, an acrid, hot herb that warms the middle burner and disperses cold. Piperlongumine has drawn modern research interest for antioxidant and anticancer activity. The heating, stimulant, enzyme-inhibiting nature is also the source of its main cautions.', 'Not named in canonical Scripture; native to the Indian subcontinent and Indo-Malaya. It was, however, well known to the classical Mediterranean world as a costly Indian import: Dioscorides (De Materia Medica) describes long pepper among the peppers, and Pliny the Elder (Natural History) lists piper longum and complains of the great sums Rome paid for pepper. Its home tradition is Ayurveda, where Pippali is one of the most esteemed herbs.', 'Native to and widely cultivated across the Indian subcontinent, Sri Lanka, and Southeast Asia, and grown commercially as a spice and medicine, so cultivated material is readily available. It is not within the scope of United Plant Savers, which lists North American at-risk species. Wild stands in parts of India face collection pressure, so prefer cultivated, organically grown fruit from a reputable source.', 'Hot, dry, and stimulating: a pungent warming tonic that rekindles a cold, torpid digestive fire and clears cold, boggy phlegm from weak lungs.', 'Refer for chest pain, breathlessness at rest, or coughing up blood; a cough lasting more than a few weeks or with fever, night sweats, or weight loss (rule out serious lung disease); severe or persistent abdominal pain, vomiting blood, or black tarry stools; high or persistent fever; and any sign of drug toxicity in a person taking regular medication, since piperine can raise drug levels. Warming digestives and cough remedies do not treat serious underlying disease.', 'Pippali: PIP-uh-lee (also pip-PAH-lee). Long pepper. Piper longum: PY-per LON-gum.', 'seed', 'Approved', '{"title": "Grieve, A Modern Herbal (1931), Pepper (Long Pepper, Piper longum).", "locator": "Grieve, A Modern Herbal (1931), Pepper (Long Pepper, Piper longum).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Nadkarni, Indian Materia Medica (Piper longum, Pippali); Bhavaprakasha Nighantu and Charaka Samhita (Pippali, Ayurvedic classics); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Bi Bo, Fructus Piperis Longi); Mills and Bone, Pr", "locator": "Nadkarni, Indian Materia Medica (Piper longum, Pippali); Bhavaprakasha Nighantu and Charaka Samhita (Pippali, Ayurvedic classics); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Bi Bo, Fructus Piperis Longi); Mills and Bone, Pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H158', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS17', 'Primary', 'Warms cold, under-fired digestion and cold, damp lungs; the core terrain.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS19', 'Primary', 'Rouses a sluggish, torpid digestive fire and slow metabolism.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS01', 'Secondary', 'Rasayana for depleted digestive and respiratory vitality.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS07', 'Secondary', 'Dries cold damp and boggy accumulation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS23', 'Secondary', 'Warms and disperses cold, thin, watery phlegm from weak lungs.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS09', 'Minor', 'Restores tone to a slack, atonic stomach and bowel.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS11', 'Minor', 'Lifts depressed, under-functioning digestive and respiratory activity.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS05', 'Primary', 'Hot, acrid nature aggravates heat, hyperacidity, and fire patterns.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS06', 'Primary', 'Worsens active gastritis, ulcer, and inflamed mucosa.');
