INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H158', 'TS10', 'Minor', 'Stimulant heat can overstimulate an already excited, irritable state.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H158', 'SY08', 'Primary', 'Kindles digestive fire; carminative for cold gas, colic, and weak digestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H158', 'SY07', 'Primary', 'Warms and clears cold phlegm; lung rasayana for chronic cough, wheeze, asthma.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H158', 'SY13', 'Secondary', 'TCM: warms the Spleen and middle burner, dispelling cold.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H158', 'SY06', 'Minor', 'Warming, dispersing stimulant to sluggish peripheral circulation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H158', 'SY05', 'Minor', 'Rasayana and warming support at the onset of cold infection.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A23', 'Primary', 'Rasayana and digestive kindler (dipana-pachana); warming restorative for lungs and metabolism.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A17', 'Primary', 'Carminative; relieves cold gas, bloating, colic, and cramping.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A12', 'Primary', 'Expectorant; warms and expels cold, watery bronchial phlegm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A33', 'Secondary', 'Antitussive; classic remedy for chronic cold cough and wheeze.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A45', 'Secondary', 'Antiemetic; settles nausea and vomiting of the cold, under-toned stomach.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A32', 'Secondary', 'Vermifuge; traditional remedy for intestinal worms.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A09', 'Secondary', 'Anti-inflammatory; piperine has documented anti-inflammatory activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A18', 'Minor', 'Diaphoretic; warming, promotes gentle sweating at the onset of cold.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A27', 'Minor', 'Anodyne; applied locally for toothache and used for pain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A28', 'Minor', 'Antimicrobial; piperine and piperlongumine show antimicrobial activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H158', 'A13', 'Minor', 'Hepatoprotective; piperine shows experimental liver-protective activity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP58', 'Primary', 'Weak, cold digestion (mandagni) with gas and heaviness; core indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP54', 'Primary', 'Cold gas, bloating, and colic; carminative.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP49', 'Primary', 'Chronic cold, phlegmy cough; warms and clears watery phlegm.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP51', 'Secondary', 'Cold, damp bronchial congestion and wheeze.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP53', 'Secondary', 'Cold, phlegmatic asthmatic tendency; classical lung rasayana.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP57', 'Secondary', 'Nausea and vomiting of the cold, under-toned stomach.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP41', 'Secondary', 'Warming at the onset of cold, shivery infection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP12', 'Secondary', 'General cold, atonic digestive upset.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP56', 'Minor', 'Cold-type diarrhea; warms the middle.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP62', 'Minor', 'Traditional vermifuge for intestinal worms.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP07', 'Minor', 'Sluggish metabolism and cold fatigue; warming rasayana.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H158', 'CP47', 'Minor', 'Warming, dispersing stimulant to cold extremities.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P03', 'Primary', 'Powder (churna), usually with honey, ghee, or warm water.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P06', 'Primary', 'Milk decoction; the classic rasayana and respiratory form, pippali simmered in milk.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P09', 'Secondary', 'Honey syrup or linctus for cough.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P04', 'Secondary', 'Water decoction of the fruit.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P12', 'Secondary', 'Culinary and formulary spice, as in Trikatu.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P01', 'Minor', 'Tincture (alcoholic extract).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H158', 'P14', 'Minor', 'Honey electuary (avaleha), as in Chyawanprash.');
