INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H158', 'TCM07', 'Secondary', 'Hot, drying nature worsens yin deficiency with heat.', '{"title": "Grieve, A Modern Herbal (1931), Pepper (Long Pepper, Piper longum).", "locator": "Grieve, A Modern Herbal (1931), Pepper (Long Pepper, Piper longum).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Nadkarni, Indian Materia Medica (Piper longum, Pippali); Bhavaprakasha Nighantu and Charaka Samhita (Pippali, Ayurvedic classics); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Bi Bo, Fructus Piperis Longi); Mills and Bone, Pr", "locator": "Nadkarni, Indian Materia Medica (Piper longum, Pippali); Bhavaprakasha Nighantu and Charaka Samhita (Pippali, Ayurvedic classics); Bensky and Gamble, Chinese Herbal Medicine: Materia Medica (Bi Bo, Fructus Piperis Longi); Mills and Bone, Pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI572', 'H158', 'drug_interaction', 'CYP3A4, CYP2C9, and P-glycoprotein substrates (e.g., phenytoin, carbamazepine, propranolol, theophylline, rifampicin, midazolam, diclofenac, warfarin, fexofenadine, possibly digoxin)', 'moderate', 'Piperine inhibits CYP3A4, CYP2C9, and P-glycoprotein and slows first-pass metabolism, raising plasma levels of many co-administered drugs; shown in human bioavailability studies.', 'Avoid medicinal doses and piperine supplements alongside narrow-therapeutic-index or chronically dosed medicines unless supervised; culinary spice amounts pose little risk. Monitor for enhanced drug effect or toxicity.', 'Bhardwaj et al., J Pharmacol Exp Ther 2002; Bano et al., Eur J Clin Pharmacol 1991; Pharmacy Times piperine drug-interaction review; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI573', 'H158', 'pregnancy', 'Pregnancy', 'moderate', 'Piperine shows anti-implantation, antifertility, and embryotoxic effects in animal studies and the herb is strongly heating; adequate human data are lacking.', 'Avoid therapeutic and medicinal doses in pregnancy; culinary spice amounts are acceptable.', 'Malini and Vanithakumari, Planta Medica 2000; postcoital antifertility effect of piperine, Contraception 1982; RxList; AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI574', 'H158', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human safety data at medicinal doses; piperine is pharmacologically active and alters absorption of other substances.', 'Avoid medicinal doses while breastfeeding; culinary use is acceptable.', 'RxList (Indian long pepper); AHPA Botanical Safety Handbook; precautionary practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI575', 'H158', 'condition', 'Active peptic ulcer, acute gastritis, hyperacidity, or acid reflux', 'moderate', 'The hot, acrid stimulant increases gastric irritation and acid, aggravating inflamed or ulcerated mucosa.', 'Avoid in active peptic ulcer, gastritis, and acid reflux; reserve for cold, atonic digestion.', 'Traditional energetics; Mills and Bone; AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI576', 'H158', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Piperine may lower blood glucose and can increase absorption of oral antidiabetic drugs, giving additive hypoglycemic effect.', 'Monitor blood glucose if combined with antidiabetic medication.', 'RxList (Indian long pepper); pharmacology reviews of piperine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI577', 'H158', 'pediatric', 'Young children', 'moderate', 'No formal pediatric safety data for medicinal doses; the herb is heating and irritant in excess.', 'Culinary use is fine; use low, short-term medicinal doses in children only under professional guidance, and avoid piperine supplements.', 'Traditional Ayurvedic pediatric use (Nadkarni); precautionary practice.');
