INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H159', 'TCM01', 'Secondary', 'Cool nature aggravates Kidney and Spleen Yang deficiency with internal cold.', '{"title": "Grieve, A Modern Herbal (1931), Plantain (Psyllium / Plantago Psyllium and Plantago ovata).", "locator": "Grieve, A Modern Herbal (1931), Plantain (Psyllium / Plantago Psyllium and Plantago ovata).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Plantago ovata; NCCIH herb profile (psyllium); NIH Drugs and Lactation Database (LactMed); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principl", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Plantago ovata; NCCIH herb profile (psyllium); NIH Drugs and Lactation Database (LactMed); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principl", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI578', 'H159', 'condition', 'Gastrointestinal obstruction, ileus, fecal impaction, esophageal stricture or narrowing, or difficulty swallowing (dysphagia)', 'absolute', 'The husk swells to a viscous gel and adds bulk; against a narrowing or block, or in someone who cannot swallow it safely, it can lodge and cause esophageal or bowel obstruction or choking.', 'Do not use with known or suspected obstruction, stricture, impaction, or swallowing difficulty. Documented esophageal obstruction and fatal choking cases exist.', 'AHPA Botanical Safety Handbook, 2nd ed.; US FDA OTC laxative monograph (psyllium); ISMP Canada safety bulletin; case reports (esophageal obstruction, PMID 35321163).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI579', 'H159', 'other', 'Inadequate fluid intake / taking psyllium dry', 'absolute', 'Without enough liquid the mucilage swells in the throat or gut and can cause choking, esophageal blockage, or intestinal obstruction.', 'Always take each dose with at least a full 240 mL glass of water plus a second glass. Never dry-scoop. Do not take immediately before lying down.', 'US FDA OTC laxative monograph (psyllium); ISMP Canada; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI580', 'H159', 'drug_interaction', 'Co-administered oral medications, especially narrow-therapeutic-index drugs (lithium, carbamazepine, digoxin, levothyroxine) and minerals', 'moderate', 'The gel delays and reduces absorption of drugs and minerals taken at the same time, lowering their serum levels and effect.', 'Separate psyllium from other oral medicines by at least 2 hours (about 4 hours for levothyroxine). Monitor levels of narrow-margin drugs.', 'Brinker, Herb Contraindications and Drug Interactions; NCCIH; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI581', 'H159', 'drug_interaction', 'Insulin and oral antidiabetic drugs', 'moderate', 'By slowing carbohydrate absorption psyllium adds to the glucose-lowering effect, which can compound hypoglycemic drug action.', 'Monitor blood glucose when starting or changing psyllium; antidiabetic doses may need adjustment. This effect is generally beneficial but should be supervised.', 'NCCIH; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI582', 'H159', 'other', 'Psyllium (ispaghula) hypersensitivity', 'moderate', 'IgE-mediated sensitization, most often from inhaled psyllium dust in healthcare and pharmaceutical workers, can cause rhinitis, asthma, urticaria, and, rarely, anaphylaxis on ingestion.', 'Avoid in anyone with known psyllium allergy. Minimize dust exposure for repeated handlers. Stop and seek care for wheeze, throat tightness, hives, or faintness after a dose.', 'Annals of Allergy, Asthma and Immunology (psyllium anaphylaxis case reports and review); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI583', 'H159', 'pregnancy', 'Pregnancy and lactation', 'low', 'Psyllium is not absorbed systemically, so it does not reach the fetus or breast milk.', 'Considered safe and a first-line bulk laxative for constipation in pregnancy and breastfeeding; take with adequate fluid. Documented here to record the assessment, not a restriction.', 'AHPA Botanical Safety Handbook, 2nd ed. (safety class 1); MotherToBaby (OTIS); NIH LactMed; NCCIH.');
