INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI584', 'H160', 'pregnancy', 'Pregnancy (high intake or concentrated extract)', 'moderate', 'Caffeine crosses the placenta (high intake linked to low birth weight and preterm risk), and green tea catechins (EGCG) inhibit dihydrofolate reductase and folate transport, potentially lowering folate during the neural-tube window.', 'Limit to moderate dietary amounts keeping total caffeine under about 200 mg/day; avoid high-dose green tea extract and EGCG supplements; separate tea from prenatal folate and iron by roughly two hours.', 'NCCIH Green Tea; CIR Safety Assessment of Camellia sinensis; antifolate pharmacology of tea catechins (Navarro-Peran et al., Cancer Res 2005, PMID 15781612).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI585', 'H160', 'breastfeeding', 'Breastfeeding (high intake or extract)', 'moderate', 'Caffeine passes into breast milk and can cause infant irritability and poor sleep; tannins reduce maternal iron absorption.', 'Limit to about one to two cups per day (total caffeine under ~300 mg/day); avoid concentrated extracts while nursing.', 'NCCIH Green Tea; standard lactation references (LactMed-style caffeine data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI586', 'H160', 'drug_interaction', 'Nadolol and other OATP1A2/OATP2B1-substrate beta-blockers', 'moderate', 'Green tea catechins inhibit intestinal OATP1A2 uptake, reducing nadolol Cmax and AUC by about 85 percent and blunting its antihypertensive effect.', 'Do not take green tea around the same time as nadolol; separate dosing and monitor blood pressure and heart rate.', 'Misaka et al., Green Tea Ingestion Greatly Reduces Plasma Concentrations of Nadolol, Clin Pharmacol Ther 2014 (PMID 24448639).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI587', 'H160', 'drug_interaction', 'Warfarin', 'moderate', 'Green tea contains vitamin K; large or variable intake can antagonize warfarin and lower the INR (documented fall from 3.8 to 1.1).', 'Keep intake modest and consistent; monitor INR and coordinate with the prescriber before changing tea habits.', 'Taylor & Wilt, Probable Antagonism of Warfarin by Green Tea, Ann Pharmacother 1999; Brinker; Natural Medicines.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI588', 'H160', 'drug_interaction', 'Bortezomib and boronic-acid proteasome inhibitors', 'absolute', 'EGCG directly and chemically antagonizes bortezomib, blocking proteasome inhibition and abolishing its cytotoxic anticancer effect.', 'Avoid green tea and EGCG-containing supplements entirely during bortezomib therapy.', 'Golden et al., Green tea polyphenols block the anticancer effects of bortezomib, Blood 2009.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI589', 'H160', 'condition', 'Liver disease / high-dose green tea extract (EGCG)', 'moderate', 'High-dose green tea extract (EGCG, signal at or above roughly 800 mg/day, associated with HLA-B*35:01) can cause idiosyncratic, occasionally severe hepatocellular injury, worse when taken fasting; the brewed beverage carries far lower risk.', 'Take green tea extract with food, not on an empty stomach; avoid extracts in known liver disease; stop and seek care if jaundice, dark urine or unexplained fatigue occur; the beverage is generally fine.', 'LiverTox: Green Tea (NCBI Bookshelf NBK547925); NCCIH; USP green tea extract monograph and safety advisory.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI590', 'H160', 'drug_interaction', 'Nonheme iron (and iron-deficiency anemia)', 'low', 'Tea tannins chelate nonheme iron and reduce its absorption from food and supplements.', 'Separate green tea from iron supplements or iron-rich meals by one to two hours, especially in iron-deficiency anemia.', 'Modern nutrition reviews; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI591', 'H160', 'condition', 'Anxiety, insomnia, cardiac arrhythmia and caffeine sensitivity', 'moderate', 'Caffeine adds central and cardiac stimulation, worsening anxiety, insomnia, palpitations and arrhythmia, and can aggravate hyperthyroidism and reflux.', 'Limit intake, prefer weaker or decaffeinated preparations, and avoid late-day consumption in sensitive individuals.', 'NCCIH Green Tea; standard caffeine pharmacology.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H160', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "locator": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "locator": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H160', 'EP02', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "locator": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "locator": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
