INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H160', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "locator": "Grieve, A Modern Herbal (1931) - Tea (Camellia thea / Thea sinensis). Classical corroboration: the Chinese materia medica tradition for Lu Cha (green tea), rooted in Lu Yu''s Cha Jing (c. 760 CE) and later Bencao literature.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "locator": "NCCIH, Green Tea (nccih.nih.gov/health/green-tea); AHPA Botanical Safety Handbook, 2nd ed. (Camellia sinensis leaf); Brinker, Herbal Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy; Bensky, Cla", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H161', 'Horse Chestnut', 'Aesculus hippocastanum', 'Sapindaceae (soapberry family; formerly placed in its own family Hippocastanaceae). Despite the common name it is not a true, edible chestnut (Castanea, Fagaceae).', 'Seed (standardized, de-esculinated aescin extract for internal use; seed and bark also used traditionally and topically)', 'Astringent, Bitter', 'Cool', 'Dry', 'Laxity and venous atony (the signature use: lax, dilated, incompetent, valve-weak veins and slack, over-stretched, leaky capillary walls that need tightening and toning); Dampness (boggy leg edema and fluid weeping into the tissues from permeable vessels); congested, pooled, sluggish venous blood with varicosities and hemorrhoidal engorgement; and, in lesser measure, Acute Inflammation and Excess Heat in hot, throbbing, aching, purple, over-full veins and piles.', 'Dryness and Atrophy: the drying, cooling, astringent seed is depleting to thin, dry, cold, or wasted tissue and to a frankly cold, deficient terrain. Avoid the raw, unprocessed seed, bark, leaf, and flower entirely; they are toxic by mouth.', 'Cardiovascular (primary: the veins, venous valves, and capillary beds of the lower limbs and pelvis); Digestive and lower bowel (hemorrhoids and rectal congestion); Integumentary (topical for bruising, edema, and varicosities); Urinary and Lymphatic (mild anti-edematous, fluid-clearing effect).', 'Chronic venous insufficiency with heavy, aching, tired, swollen legs, night cramps, itching, and pitting ankle edema (its best-evidenced use); varicose and spider veins; hemorrhoids and rectal congestion; leg and ankle edema and fluid retention; easy bruising and capillary fragility; topically for varicosities, bruises, and post-traumatic swelling. Historically the bark served as a tonic, astringent febrifuge for fevers and dysentery.', 'The full, plethoric, congested venous phenotype: throbbing, purple, over-filled, boggy vessels in a warm, damp terrain. Best for the Sanguine (warm, damp, full-blooded venous congestion the cool astringent tones and cools) and the damp, relaxed, boggy Phlegmatic (still-water venous laxity and edema the drying astringent tightens). The cold, dry, astringent action aggravates the thin, cold, depleted (Vata-like) and the cold, dry Melancholic.', 'Pitta, Kapha', 'Vata', 'Functionally, Blood Stasis in the vessels of the lower body with pooling, distension, varicosities, and hemorrhoids, and Dampness with leg edema and fluid accumulation. The cool, astringent, anti-edematous action tightens and moves the stagnant, boggy terrain. It is not a classical Chinese materia medica herb; these are energetic correspondences.', 'Yin deficiency with dryness, and Kidney or Spleen Yang deficiency with cold: the drying, cooling, astringent nature further parches dry, thin tissue and deepens a cold, deficient, weak-circulation terrain. Also avoid in Qi and Blood deficiency without stasis.', 'Use only standardized, de-esculinated seed extract internally; the raw seed, bark, leaf, and flower are toxic by mouth (esculin/aesculin, a hydroxycoumarin). Standardized extracts are generally well tolerated but may cause dizziness, headache, digestive upset, nausea, or itching. Aescin has mild antiplatelet activity and the coumarin fraction can thin the blood, so monitor for bleeding, use cautiously with anticoagulant, antiplatelet, or antidiabetic drugs and with lithium, and discontinue about 2 weeks before surgery. Avoid in kidney or liver disease; high-dose or parenteral aescin has been linked to renal injury. People allergic to latex may cross-react to horse chestnut.', 'Contraindicated as the raw, unprocessed seed, bark, leaf, or flower (toxic by mouth). Avoid in pregnancy and lactation (insufficient safety data), in children, in kidney or liver disease, and in bleeding disorders. Use cautiously with blood thinners, antiplatelet drugs, antidiabetic medication, and lithium, and stop before surgery. Not a substitute for medical evaluation of leg swelling, which can signal serious disease.', 'Avoid. Little is known about the safety of horse chestnut seed extract in pregnancy and standardized data are lacking; there is also a theoretical uterine-stimulant concern and the coumarin/antiplatelet activity of the plant. Default to avoidance. Source: NCCIH Horse Chestnut fact sheet; Drugs.com and WebMD consumer safety summaries.', 'Insufficient data for the whole seed extract; avoid pending data. Little is known about safety while breastfeeding per NCCIH. The isolated saponin aescin is high-molecular-weight and unlikely to pass into milk in meaningful amounts, and lactation references rate aescin itself low risk, but whole-extract data are absent, so err toward avoidance. Source: NCCIH Horse Chestnut fact sheet; e-lactation.com (aescin, low risk).', 'Not recommended. No pediatric dosing or safety data exist for the standardized extract, and the raw seeds (conkers) are a well-documented cause of poisoning in children. Keep raw seeds away from children and reserve any internal use for qualified practitioner guidance. Source: NCCIH Horse Chestnut fact sheet; AHPA Botanical Safety Handbook, 2nd ed.', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, apixaban, rivaroxaban): aescin reduces platelet aggregation and the esculin/aesculin hydroxycoumarin fraction, together with aescin''s high plasma-protein binding, may add to or unpredictably alter anticoagulant effect and raise bleeding risk; monitor and stop about 2 weeks before surgery (rated a moderate interaction by Drugs.com). Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas, metformin): horse chestnut may lower blood sugar, an additive effect; monitor glucose. Lithium: a mild diuretic effect may reduce lithium clearance and raise serum levels; monitor. Nephrotoxic drugs and existing kidney disease: additive renal risk; avoid. Aescin also modulates several CYP450 isoenzymes in vitro, a theoretical basis for altered metabolism of narrow-therapeutic-index drugs. Sources: NCCIH Horse Chestnut fact sheet; Memorial Sloan Kettering Cancer Center, About Herbs: Horse Chestnut; Drugs.com and WebMD interaction summaries; Brinker, Herb Contraindications and Drug Interactions.', 'Standardized seed extract (capsule or tablet), de-esculinated and standardized to aescin (escin), the principal internal form; tincture of the seed; topical gel, cream, or ointment (aescin 1-2 percent) for varicose veins, bruises, and swelling; compress or fomentation. Traditional (historical) bark decoction as an astringent febrifuge. Do not prepare the raw seed as a simple tea or powder for internal use.', 'Standardized seed extract: 250-315 mg twice daily, delivering roughly 90-150 mg aescin per day (trials commonly used 50 mg aescin twice daily for up to 12 weeks). Seed tincture (1:5): 1-4 mL up to 3x daily. Topical aescin gel (1-2 percent): apply to the affected area 2-4x daily. Use standardized, de-esculinated products only.', 'Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.', 'Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse Chestnut. Commission E and ESCOP monographs (Aesculus hippocastanum seed). AHPA Botanical Safety Handbook, 2nd ed. Brinker, Herb Contraindications and Drug Interactions. Mills & Bone, Principles and Practice of Phytotherapy.', 'Sapindaceae (soapberry family; formerly Hippocastanaceae); native to the Balkan Peninsula. Key constituents: the triterpene saponin complex aescin/escin (alpha- and beta-aescin), the hydroxycoumarin glycosides esculin (aesculin) and fraxin, flavonoids (quercetin and kaempferol glycosides), and oligomeric proanthocyanidins. Aescin is the venoactive principle: it reduces capillary permeability and fragility, inhibits the lysosomal enzymes elastase and hyaluronidase that degrade vessel walls, tightens venous tone, and is anti-edematous and anti-inflammatory. A Cochrane review supports standardized seed extract as a safe, effective short-term treatment for chronic venous insufficiency. Because raw seed contains toxic esculin, only de-esculinated, aescin-standardized extract is used internally. Common name notwithstanding, it is not a true chestnut (Castanea, Fagaceae) and its seeds are not edible.', 'Not named in the canonical biblical texts and unknown to the classical Mediterranean writers (Dioscorides, Pliny): the tree is native to the Balkan Peninsula and was introduced to Western Europe only in the 16th century, reaching Vienna about 1576. Its medicinal reputation is European and modern, formalized in Commission E and ESCOP monographs and in standardized clinical extracts.', 'Although superabundant as a planted street and park ornamental across the temperate world, Aesculus hippocastanum is assessed as Vulnerable in its small native Balkan range (IUCN Red List), pressured by the leaf-miner moth Cameraria ohridella and habitat loss. It is not on the United Plant Savers list (which tracks North American natives). Harvest seed from the plentiful cultivated ornamental trees rather than wild Balkan stands; commercial extract is cultivation-sourced.', 'Cool, dry, and astringent: a venous tonic that tightens lax, dilated, leaky veins and capillaries, drives out boggy edema, and cools the hot, throbbing fullness of varicose veins and piles.', 'Refer for a sudden, painful, hot, red, or swollen calf (possible deep vein thrombosis); one-sided leg swelling, chest pain, or breathlessness (possible clot or embolism); a leg ulcer, non-healing sore, or skin breakdown; rapidly worsening or bilateral swelling with breathlessness (possible heart, kidney, or liver disease); rectal bleeding that is heavy, dark, or persistent, or any change in bowel habit (do not assume hemorrhoids). Standardized extract is an adjunct to compression and medical care, not a replacement.', 'Horse Chestnut = HORS CHESS-nut; Aesculus hippocastanum = ESS-kew-lus hip-oh-kass-TAY-num', 'seed', 'Approved', '{"title": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "locator": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "locator": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H161', 'T04');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H161', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS09', 'Primary', 'Venous tonic: tightens and tones lax, dilated, valve-weak veins and slack, leaky capillary walls.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS07', 'Primary', 'Anti-edematous: clears boggy leg edema and fluid weeping from permeable vessels.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS08', 'Secondary', 'Moves pooled, congested, sluggish venous blood; varicosities and hemorrhoidal engorgement.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS06', 'Secondary', 'Anti-inflammatory (aescin) for hot, swollen, inflamed veins.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS05', 'Minor', 'Cools throbbing, purple, over-full venous congestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS03', 'Primary', 'Drying astringent worsens dry, thin, parched tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS02', 'Secondary', 'Depleting to wasted, thin, atrophic tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H161', 'TS17', 'Secondary', 'Cooling nature aggravates a frankly cold, deficient terrain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H161', 'SY06', 'Primary', 'Cardiovascular: veins, venous valves, and capillary beds; chronic venous insufficiency, varicosities, edema.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H161', 'SY08', 'Secondary', 'Digestive/lower bowel: hemorrhoids and rectal congestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H161', 'SY10', 'Secondary', 'Integumentary: topical for bruising, edema, and varicose veins.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H161', 'SY09', 'Minor', 'Urinary: mild anti-edematous, fluid-clearing effect.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H161', 'SY11', 'Minor', 'Lymphatic: reduces tissue edema and fluid stasis.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A15', 'Primary', 'Astringent: tightens and tones lax, leaky veins and capillary walls; reduces capillary permeability and fragility.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A09', 'Primary', 'Anti-inflammatory: aescin downregulates inflammatory mediators and is anti-edematous.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A08', 'Secondary', 'Diuretic: mild; helps clear boggy leg edema.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A25', 'Secondary', 'Antioxidant: flavonoids and proanthocyanidins protect vessel walls.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A24', 'Minor', 'Vulnerary: topical for bruises, swelling, and post-traumatic edema.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A27', 'Minor', 'Anodyne: eases the aching, throbbing pain of congested veins and piles (Eclectic rectal use).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H161', 'A49', 'Minor', 'Febrifuge: historical astringent febrifuge use of the bark for fevers.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H161', 'CP48', 'Primary', 'Varicose veins and venous stasis; chronic venous insufficiency (best evidence).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H161', 'CP61', 'Primary', 'Hemorrhoids and rectal congestion (Eclectic and traditional signature).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H161', 'CP47', 'Secondary', 'Poor peripheral circulation; sluggish venous return, heavy aching legs.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H161', 'CP66', 'Secondary', 'Fluid retention: leg and ankle edema.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H161', 'CP13', 'Minor', 'Systemic/vascular inflammation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H161', 'P02', 'Primary', 'Standardized, de-esculinated aescin capsule or tablet: the main internal form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H161', 'P07', 'Primary', 'Topical aescin gel, cream, or ointment for veins, bruises, and swelling.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H161', 'P01', 'Secondary', 'Seed tincture.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H161', 'P10', 'Minor', 'Compress over varicosities and bruises.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H161', 'P04', 'Minor', 'Traditional bark decoction (historical, external and febrifuge).');
