INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H161', 'TCM07', 'Primary', 'Yin deficiency with dryness: the drying astringent parches thin, dry tissue.', '{"title": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "locator": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "locator": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H161', 'TCM01', 'Secondary', 'Kidney Yang deficiency (cold, weak circulation): cooling aggravates, plus renal caution.', '{"title": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "locator": "Grieve, A Modern Herbal (1931): Horse Chestnut. Supported by King''s American Dispensatory (Felter & Lloyd, 1898): Aesculus (Hippocastanum) for the Eclectic rectal and hemorrhoidal indications.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "locator": "Pittler MH, Ernst E. Horse chestnut seed extract for chronic venous insufficiency. Cochrane Database Syst Rev. 2012;(11):CD003230 (PMID 23152216). NCCIH Horse Chestnut fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Horse C", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI592', 'H161', 'pregnancy', 'Pregnancy', 'moderate', 'Safety not established; standardized data lacking, with a theoretical uterine-stimulant concern and coumarin/antiplatelet activity.', 'Avoid medicinal internal use during pregnancy.', 'NCCIH Horse Chestnut fact sheet; Drugs.com and WebMD consumer safety summaries.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI593', 'H161', 'breastfeeding', 'Breastfeeding', 'moderate', 'No whole-extract lactation data; the isolated saponin aescin is high-molecular-weight and rated low risk, but the extract is unstudied.', 'Avoid medicinal internal use while breastfeeding pending data.', 'NCCIH Horse Chestnut fact sheet; e-lactation.com (aescin, low risk).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI594', 'H161', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, apixaban, rivaroxaban) and the pre-surgical period', 'moderate', 'Aescin reduces platelet aggregation and the esculin/aesculin hydroxycoumarin fraction plus high protein binding may add to or unpredictably alter anticoagulant effect, raising bleeding risk.', 'Avoid the combination or use only with clinician oversight and bleeding monitoring; discontinue about 2 weeks before surgery.', 'Drugs.com interaction monograph (moderate); Memorial Sloan Kettering About Herbs; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI595', 'H161', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Horse chestnut may lower blood sugar, an additive effect that could cause hypoglycemia.', 'Monitor blood glucose and coordinate dosing with the prescriber.', 'WebMD and Drugs.com interaction summaries.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI596', 'H161', 'drug_interaction', 'Lithium', 'moderate', 'A mild diuretic effect may reduce lithium clearance and raise serum lithium to toxic levels.', 'Avoid unless supervised; monitor lithium levels and adjust dose as directed.', 'WebMD interaction summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI597', 'H161', 'condition', 'Kidney or liver disease (and concurrent nephrotoxic drugs)', 'moderate', 'High-dose or parenteral aescin has been linked to renal injury, and horse chestnut may worsen existing kidney disease.', 'Avoid in renal or hepatic impairment; do not exceed labeled doses of standardized extract.', 'Memorial Sloan Kettering About Herbs: Horse Chestnut; WebMD safety summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI598', 'H161', 'other', 'Raw seed, bark, leaf, and flower (unprocessed plant)', 'absolute', 'Contain toxic esculin (aesculin), a hydroxycoumarin; ingestion causes gastrointestinal and neurologic poisoning, with cases reported especially in children who eat the seeds (conkers).', 'Never ingest the raw plant; use only de-esculinated, aescin-standardized seed extract internally.', 'NCCIH Horse Chestnut fact sheet.');
