INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI599', 'H162', 'pregnancy', 'Root, bark and flower preparations', 'absolute', 'Root and bark are traditional emmenagogues and abortifacients; they contain uterus-active alkaloids (moringine, moringinine) and animal studies show alcoholic stem-bark extract to be strongly abortive and uterus-stimulating.', 'Do not use Moringa root, bark or flower preparations at any dose during pregnancy.', 'Controlled animal abortifacient studies (alcoholic stem-bark extract ~100% abortive in mice, World J Pharm Res; leaf/seed abortifacient studies, J Ethnopharmacol); RxList/NatMed pregnancy caution.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI600', 'H162', 'pregnancy', 'High-dose or extract leaf/seed preparations', 'moderate', 'Aqueous and ethanol leaf extracts are abortive in rats at therapeutic-equivalent doses; concentrated leaf powder and extracts have not been established as safe in pregnancy, though modest culinary leaf appears tolerated, especially after the first trimester.', 'Limit pregnancy use to modest culinary leaf and pod as food; avoid high-dose leaf powder, standardized extracts, tinctures and capsules unless supervised by a qualified practitioner.', 'Animal abortifacient studies (leaf/seed extract ~100% abortive at 175 mg/kg); NCCIH-style insufficient-data precaution.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI601', 'H162', 'breastfeeding', 'Root and bark preparations', 'moderate', 'Leaf is a studied galactagogue and generally regarded as compatible, but root and bark carry the same alkaloid and safety concerns as in pregnancy and are not appropriate for nursing mothers; long-term infant effects of concentrated extracts are unstudied.', 'Use leaf as food or modest powder as a galactagogue; avoid root, bark and concentrated extracts while breastfeeding.', 'Systematic reviews of Moringa leaf galactagogue safety (Egyptian Pediatric Association Gazette 2026; Foods 2025, PMC12294722); precautionary note on parts and extracts.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI602', 'H162', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Moringa leaf lowers blood glucose in animal and human studies; an additive hypoglycemic effect is plausible.', 'Monitor blood glucose; adjust antidiabetic medication only under professional supervision.', 'Stohs & Hartman review (Phytother Res 2015, PMID 25808883); human and animal hypoglycemia studies; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI603', 'H162', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Moringa leaf is hypotensive; combined use may cause excessive blood-pressure lowering.', 'Monitor blood pressure; watch for dizziness or hypotension when combining.', 'Stohs & Hartman review (Phytother Res 2015); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI604', 'H162', 'drug_interaction', 'Levothyroxine and thyroid hormone therapy', 'moderate', 'Moringa reduces conversion of T4 to active T3 in animal models and may decrease levothyroxine effectiveness (anti-thyroid signal).', 'Separate dosing, monitor thyroid function, and avoid high-dose Moringa in those on thyroid hormone or with hypothyroidism.', 'Animal thyroid studies (Tahiliani & Kar, J Ethnopharmacol); NatMed/RxList interaction note.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI605', 'H162', 'drug_interaction', 'CYP3A4, CYP2D6 and CYP1A2 substrate drugs of narrow therapeutic index', 'moderate', 'Moringa leaf extracts inhibit CYP3A4, CYP2D6 and CYP1A2 in vitro, and a nevirapine case-report signal exists, so plasma levels of drugs cleared by these enzymes could theoretically rise.', 'Separate dosing from narrow-therapeutic-index medications and use caution; prefer food-grade leaf amounts alongside such drugs.', 'Monera et al. CYP3A4 inhibition study (PMID 19745507); in vitro CYP inhibition reviews; Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI606', 'H162', 'condition', 'Hot, dry, Pitta-excess constitutions and acute inflammatory or feverish heat', 'moderate', 'The warm, drying, pungent potency can aggravate heat, dryness and irritability despite the plant''s systemic anti-inflammatory chemistry.', 'Avoid or pair with cooling, moistening adjuvants in hot, dry, Pitta-Choleric individuals and in acute hot inflammation.', 'Ayurvedic energetic contraindication (Bhavaprakasha Nighantu; Frawley & Lad, The Yoga of Herbs).');
