INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H162', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, M., A Modern Herbal (1931) - Horse-Radish Tree (Moringa pterygosperma, syn. M. oleifera). The Ayurvedic Pharmacopoeia of India, Part I - Shigru (Moringa oleifera); classical Ayurvedic corroboration in Bhavaprakasha Nighantu, Charaka", "locator": "Grieve, M., A Modern Herbal (1931) - Horse-Radish Tree (Moringa pterygosperma, syn. M. oleifera). The Ayurvedic Pharmacopoeia of India, Part I - Shigru (Moringa oleifera); classical Ayurvedic corroboration in Bhavaprakasha Nighantu, Charaka", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Stohs, S.J. & Hartman, M.J., Review of the Safety and Efficacy of Moringa oleifera (Phytotherapy Research, 2015; PMID 25808883); systematic reviews of Moringa as a galactagogue (Egyptian Pediatric Association Gazette, 2026; Foods, 2025, PMC", "locator": "Stohs, S.J. & Hartman, M.J., Review of the Safety and Efficacy of Moringa oleifera (Phytotherapy Research, 2015; PMID 25808883); systematic reviews of Moringa as a galactagogue (Egyptian Pediatric Association Gazette, 2026; Foods, 2025, PMC", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null, "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H163', 'Peruvian Bark (Cinchona)', 'Cinchona officinalis', 'Rubiaceae (the madder and coffee family). Cinchona officinalis is one of several bark-yielding species of the genus (with C. calisaya, C. ledgeriana, C. pubescens and C. succirubra); it is the national tree of Peru and Ecuador.', 'Bark (dried stem and branch bark; the botanical source of the alkaloids quinine, quinidine, cinchonine and cinchonidine)', 'Bitter, Astringent', 'Cold', 'Dry', 'Deficiency, exhaustion and torpor: the signature use is as an intensely bitter convalescent tonic that rekindles a sluggish, torpid appetite and digestion and rebuilds the depleted, wrung-out, debilitated terrain left by prolonged or periodic fever. Laxity and atony: the astringent bark tightens and tones lax, relaxed, atonic tissue and checks passive weeping and discharge. Excess Heat: the cold bitter breaks and cools the paroxysms of periodic, intermittent, malarial fever. Chronic Infection: it addresses the relapsing, periodic infective process itself, its historic role as the premier antimalarial febrifuge.', 'Cold and Dryness: the cold, drying, astringent bitter aggravates a frankly cold, deficient, hypofunctional terrain and further parches thin, dry, depleted tissue. Avoid in the shivering, chills-without-heat cold stage and in the constitutionally cold, dry person.', 'Immune and blood (primary: the febrile, infective, malarial process); Digestive (primary: a bitter gastric stimulant that raises appetite, secretion and tone); Cardiovascular (the bark carries quinidine, an antiarrhythmic, and quinine is cardiotoxic in overdose); Nervous (quinine acts on the eighth cranial nerve and cortex, the seat of cinchonism); Musculoskeletal (quinine lowers the excitability of skeletal muscle, the basis of its use for night cramps).', 'Periodic, intermittent and remittent fever, above all malaria (its historic, defining use as the fever bark); convalescent debility, weakness and wasting after acute or prolonged illness; poor appetite, atonic dyspepsia and low digestive fire; general fatigue and exhaustion; nocturnal leg and muscle cramps (the quinine indication). Historically also used for the relapsing agues and as a bitter astringent for passive, atonic states.', 'The hot, feverish, over-heated terrain the cold bitter cools: best for the Choleric (hot, dry, bilious, feverish) and the warm, full Robust/Hot (Pitta-like) in the paroxysm of fever. It also serves the deficient, pale, convalescent constitution as a restorative bitter tonic once the acute heat has broken. The cold, dry, astringent action aggravates the thin, cold, depleted (Vata-like) and the cold, boggy Phlegmatic.', 'Pitta, Kapha', 'Vata', 'Functionally, Heat and Fire with high, cyclical, intermittent fever that the cold bitter drains and clears, and Damp-Heat in the periodic, malarial nue (ague) pattern. It is not a classical Chinese materia medica herb (it is a New World bark); these are energetic correspondences, though Chinese medicine treats the same intermittent-fever pattern with Chang Shan and Qing Hao.', 'Kidney and Spleen Yang deficiency with cold: the cold, bitter, draining nature injures the digestive fire and deepens a cold, weak, hypofunctional terrain. Avoid also in Qi deficiency without heat and in the cold (chill) stage of an intermittent fever.', 'Cinchona bark contains quinine and related alkaloids with a narrow margin of safety. Excess or prolonged use causes cinchonism: ringing in the ears, deafness, headache, blurred vision, nausea and vertigo, reversible at first but potentially serious. Larger overdose is cardiotoxic (the bark also holds quinidine) and can cause dangerous arrhythmia and hypotension; it can trigger immune thrombocytopenia (bruising and bleeding) and, in G6PD-deficient people, hemolysis. Quinine stimulates insulin release and can cause hypoglycemia. Ground bark and quinine are notable sensitizers, causing urticaria, contact dermatitis and other hypersensitivity reactions. Use only low, well-measured bitter-tonic doses; this is a practitioner-gated herb, not for casual or high-dose self-treatment.', 'Contraindicated in known hypersensitivity to quinine, quinidine or cinchona; in G6PD deficiency (hemolysis); in a history of quinine-induced thrombocytopenia, hemolytic-uremic syndrome or blackwater fever; in optic neuritis, tinnitus or hearing disorders; in myasthenia gravis (quinine worsens neuromuscular weakness); and in cardiac conduction defects or QT prolongation. Avoid in pregnancy (see below). Not a substitute for the diagnosis and treatment of malaria, which is a medical emergency.', 'Avoid the medicinal herb in pregnancy. Cinchona has a long abortifacient and oxytocic reputation, quinine crosses the placenta, and overdose in pregnancy has been linked in case reports to stillbirth, congenital deafness, optic-nerve hypoplasia and CNS, limb, facial and cardiac anomalies; quinine also stimulates insulin, causing maternal and fetal hypoglycemia that can be severe in late pregnancy. Prescription quinine is used to treat life-threatening malaria in pregnancy under medical supervision, where benefit outweighs risk, but uncontrolled-dose herbal bark should not be used. Source: UKTIS, Use of Quinine in Pregnancy; AHPA Botanical Safety Handbook, 2nd ed. (Cinchona); Brinker, Herb Contraindications and Drug Interactions.', 'Generally compatible in small amounts, with one firm exception. Quinine passes into breast milk only at low levels (about 2.6 mg/L on maternal antimalarial dosing) and is rated compatible with breastfeeding by the American Academy of Pediatrics, so a bitter-tonic dose is unlikely to harm a healthy infant. It is contraindicated, however, when the infant is G6PD-deficient: quinine in milk (even from tonic water) has caused severe hemolytic crises in G6PD-deficient breastfed babies. Source: LactMed (Drugs and Lactation Database, NCBI), Quinine.', 'Not for self-treatment in children. Quinine has a narrow safety margin and children are vulnerable to cinchonism, hypoglycemia and, if G6PD-deficient, hemolysis; fatal pediatric quinine poisonings are documented. Any use for a child, for example prescription quinine for malaria, belongs with a physician. Source: AHPA Botanical Safety Handbook, 2nd ed.; Qualaquin (quinine sulfate) FDA prescribing information.', 'Anticoagulants (warfarin): quinine can potentiate anticoagulation and raise INR and bleeding risk; monitor. Digoxin and cardiac glycosides: quinine raises steady-state digoxin levels by roughly a third (reduced clearance); monitor levels and adjust dose. QT-prolonging drugs and Class Ia or III antiarrhythmics (quinidine, amiodarone, sotalol, plus macrolide and fluoroquinolone antibiotics): additive QT prolongation and torsades risk; avoid the combination. CYP2D6 substrates: antimalarial-dose quinine inhibits CYP2D6 and can raise levels of metoprolol, flecainide, dextromethorphan and paroxetine. Antidiabetic and hypoglycemic drugs: quinine stimulates insulin secretion and can add to blood-sugar lowering; monitor glucose. Mefloquine: additive cardiac and seizure risk. Aluminum-containing antacids reduce quinine absorption. Sources: Qualaquin (quinine sulfate) FDA prescribing information (DailyMed); Brinker, Herb Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy.', 'Bark decoction (the classic febrifuge preparation); tincture of the bark (the official Tinctura Cinchonae); powdered bark; compound bitter tincture or medicated wine (the historic vinum cinchonae, quinine wine, and the compound tinctures of the dispensatories); cold infusion. Modern use is chiefly as a small-dose bitter tonic; isolated quinine is a pharmaceutical, not an herbal preparation.', 'As a bitter tonic (not as an antimalarial): bark tincture (1:5), 1-2 mL up to 3x daily, or a few drops to a teaspoon of the compound tincture before meals; decoction of 0.5-1 g dried bark up to 3x daily; powdered bark 0.3-1 g. Keep doses low and time-limited, watch for the earliest sign of cinchonism (tinnitus) and stop. Antimalarial dosing with isolated quinine is a physician-directed pharmaceutical matter, not covered here.', 'King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.', 'Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and Lactation Database, NCBI): Quinine. UKTIS: Use of Quinine in Pregnancy. Qualaquin (quinine sulfate) FDA prescribing information (DailyMed).', 'Rubiaceae; native to the wet montane cloud forests of the Andes (Colombia, Ecuador, Peru, Bolivia), 1600-2700 m; the national tree of Peru and Ecuador. The bark''s key alkaloids are quinine (antimalarial, antipyretic, bitter), quinidine (a Class Ia antiarrhythmic), cinchonine and cinchonidine, alongside bitter quinovin glycosides and astringent cinchotannic acid. Quinine was the world''s only effective antimalarial for roughly three centuries after the bark reached Europe in the 1630s (as Jesuit''s bark or Peruvian bark), until synthetic antimalarials arrived in the 20th century; it remains in use for chloroquine-resistant falciparum malaria and for nocturnal leg cramps. In the traditional materia medica the bark is valued less for isolated quinine than as an intensely bitter astringent febrifuge and convalescent tonic. Because of the narrow margin and real cardiac, hematologic and ototoxic risks, it is a practitioner-gated (Paid) herb.', 'Not named in the canonical biblical texts and unknown to the classical Mediterranean writers (Dioscorides, Pliny): Cinchona is a New World tree, native to the Andes and used by Quechua-speaking peoples of South America. It entered European medicine only in the 1630s, carried back by Jesuit missionaries and popularized as Jesuit''s bark, Peruvian bark, and the Countess''s powder. Its tradition of origin is Andean, not Mediterranean or biblical.', 'Historic bark-stripping drove destructive wild harvest of Andean Cinchona in the 18th and 19th centuries, and wild C. officinalis is now uncommon in parts of its native range. Commercial bark and quinine have long come from cultivated plantations (established in Java, India and elsewhere from smuggled seed), so cultivation-sourced bark is both available and the responsible choice. Cinchona is a South American native and is not on the United Plant Savers list (which tracks North American species); even so, buy plantation-grown, not wild-stripped, bark.', 'Cold, dry, intensely bitter and astringent: the archetypal fever bark that breaks and cools periodic, intermittent fever, tightens lax atonic tissue, and rekindles appetite and digestion in the wrung-out, convalescent, depleted.', 'Refer urgently for suspected malaria (fever after travel to an endemic area is a medical emergency needing diagnosis and treatment, not self-medication); for ringing in the ears, hearing loss, or visual disturbance (cinchonism); for unexplained bruising, bleeding, dark urine or pallor (thrombocytopenia or hemolysis); and for palpitations, fainting or an irregular pulse (cardiac toxicity). Anyone pregnant, G6PD-deficient, or taking warfarin, digoxin or a heart-rhythm drug should not use cinchona without medical oversight.', 'Peruvian Bark = puh-ROO-vee-un bark; Cinchona officinalis = sin-KOH-nuh oh-fiss-ih-NAY-liss', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "locator": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
