INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H163', 'TS17', 'Primary', 'Cold, draining bitter aggravates a frankly cold, deficient, hypofunctional terrain and the cold chill stage.');
