INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H163', 'SY01', 'Minor', 'Nervous: quinine acts on the eighth cranial nerve and cortex (cinchonism).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H163', 'SY04', 'Minor', 'Musculoskeletal: quinine reduces skeletal-muscle excitability (night cramps).');
