INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H163', 'A28', 'Secondary', 'Antimicrobial/antiprotozoal: quinine''s antimalarial (antiplasmodial) action (see new_actions for the specific antimalarial code).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H163', 'A23', 'Secondary', 'Tonic: restorative in convalescent debility and wasting.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H163', 'A10', 'Minor', 'Antispasmodic: quinine lowers skeletal-muscle excitability; used for nocturnal leg cramps.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP76', 'Primary', 'Fever management: periodic, intermittent and malarial fever (the fever bark).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP03', 'Primary', 'Debility: convalescent weakness and wasting after acute or prolonged illness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP09', 'Secondary', 'Chronic infection: the relapsing, periodic malarial process (see new_complaints for malaria-specific code).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP58', 'Secondary', 'Dyspepsia/low digestive fire: poor appetite and atonic dyspepsia answered by the bitter.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP07', 'Secondary', 'Fatigue and exhaustion in convalescence.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H163', 'CP37', 'Minor', 'Muscle cramps: nocturnal leg and muscle cramps (quinine indication).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H163', 'P01', 'Primary', 'Bark tincture (Tinctura Cinchonae): the official and common form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H163', 'P04', 'Primary', 'Decoction of the bark: the classic febrifuge preparation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H163', 'P03', 'Secondary', 'Powdered bark.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H163', 'P14', 'Secondary', 'Compound elixir / medicated wine (vinum cinchonae, quinine wine).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H163', 'P05', 'Minor', 'Cold infusion.');
