INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H163', 'C06', 'Indicated', 'Secondary', 'Robust/Hot (Pitta-like): warm, full, feverish terrain cooled by the cold bitter.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "locator": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H163', 'C07', 'Indicated', 'Secondary', 'Deficient/pale convalescent: restorative bitter tonic once acute heat has broken.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "locator": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
