INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H163', 'TCM03', 'Secondary', 'Spleen Qi deficiency: bitter cold injures the digestive fire in a cold, weak terrain.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Cinchona.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "locator": "Grieve, A Modern Herbal (1931): Peruvian Bark / Cinchona. Mills & Bone, Principles and Practice of Phytotherapy. AHPA Botanical Safety Handbook, 2nd ed. (Cinchona). Brinker, Herb Contraindications and Drug Interactions. LactMed (Drugs and L", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI607', 'H163', 'pregnancy', 'Pregnancy', 'moderate', 'Long abortifacient/oxytocic reputation; quinine crosses the placenta and overdose is linked to stillbirth, congenital deafness, optic-nerve hypoplasia and CNS/limb/facial/cardiac anomalies; quinine-induced insulin release can cause severe maternal and fetal hypoglycemia, especially in late pregnancy.', 'Avoid uncontrolled-dose herbal bark in pregnancy. Prescription quinine for life-threatening malaria in pregnancy is a separate physician-supervised decision.', 'UKTIS, Use of Quinine in Pregnancy; AHPA Botanical Safety Handbook, 2nd ed. (Cinchona); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI608', 'H163', 'breastfeeding', 'Breastfeeding (infant with G6PD deficiency)', 'moderate', 'Quinine enters milk at low levels and is generally compatible (AAP), but even small amounts (including from tonic water) have caused severe hemolytic crises in G6PD-deficient breastfed infants.', 'A low bitter-tonic dose is generally acceptable for a healthy infant; contraindicated when the infant is G6PD-deficient.', 'LactMed (Drugs and Lactation Database, NCBI), Quinine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI609', 'H163', 'drug_interaction', 'Warfarin and other anticoagulants', 'moderate', 'Quinine can potentiate anticoagulant effect, raising INR and bleeding risk.', 'Avoid or use only with clinician oversight and INR monitoring.', 'Qualaquin (quinine sulfate) FDA prescribing information (DailyMed); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI610', 'H163', 'drug_interaction', 'Digoxin and cardiac glycosides', 'moderate', 'Quinine reduces digoxin clearance and raises steady-state digoxin levels by roughly one third.', 'Monitor serum digoxin and adjust dose; avoid without supervision.', 'Qualaquin (quinine sulfate) FDA prescribing information (DailyMed).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI611', 'H163', 'drug_interaction', 'QT-prolonging drugs and Class Ia/III antiarrhythmics (quinidine, amiodarone, sotalol, macrolide and fluoroquinolone antibiotics)', 'moderate', 'Quinine and its congener quinidine prolong the QT interval; additive effect raises the risk of torsades de pointes.', 'Avoid the combination.', 'Qualaquin (quinine sulfate) FDA prescribing information (DailyMed).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI612', 'H163', 'drug_interaction', 'CYP2D6 substrates (metoprolol, flecainide, dextromethorphan, paroxetine)', 'moderate', 'Antimalarial-dose quinine inhibits CYP2D6, raising levels of co-administered substrates.', 'Monitor for exaggerated substrate effect; low bitter-tonic doses pose less risk than antimalarial doses.', 'Qualaquin (quinine sulfate) FDA prescribing information (DailyMed).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI613', 'H163', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas)', 'moderate', 'Quinine stimulates insulin secretion, adding to blood-sugar lowering and hypoglycemia risk.', 'Monitor blood glucose.', 'UKTIS, Use of Quinine in Pregnancy; Qualaquin (quinine sulfate) FDA prescribing information.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI614', 'H163', 'condition', 'G6PD deficiency', 'absolute', 'Quinine can precipitate acute hemolysis (including blackwater fever) in G6PD-deficient individuals.', 'Do not use.', 'LactMed (Drugs and Lactation Database, NCBI), Quinine; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI615', 'H163', 'condition', 'Quinine hypersensitivity, prior quinine-induced thrombocytopenia or HUS, optic neuritis or tinnitus, myasthenia gravis, cardiac conduction defect', 'absolute', 'Quinine causes immune thrombocytopenia and hemolytic-uremic syndrome, worsens neuromuscular weakness in myasthenia gravis, is ototoxic and optic-toxic, and depresses cardiac conduction.', 'Contraindicated in these conditions.', 'Qualaquin (quinine sulfate) FDA prescribing information (DailyMed); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI616', 'H163', 'other', 'Overdose or high-dose / prolonged use (cinchonism and cardiotoxicity)', 'absolute', 'Narrow margin of safety: excess causes cinchonism (tinnitus, deafness, visual loss, headache, nausea) and, at higher doses, arrhythmia, hypotension and rarely death.', 'Use only low, measured, time-limited bitter-tonic doses; stop at the first sign of tinnitus. Not for high-dose self-treatment.', 'AHPA Botanical Safety Handbook, 2nd ed. (Cinchona); Qualaquin (quinine sulfate) FDA prescribing information.');
