INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H164', 'TS05', 'Primary', 'Excess Heat: draws down fever and cools hot, red, throbbing tissue (salicin, salicylate).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H164', 'TS06', 'Primary', 'Acute Inflammation: anti-inflammatory for hot, swollen, painful joints and inflamed tissue.');
