INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H164', 'TS03', 'Secondary', 'Dryness: drying astringent worsens thin, dry, parched tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H164', 'TS01', 'Secondary', 'Deficiency: a cold bitter can drain an already weak, cold, depleted constitution.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H164', 'SY04', 'Primary', 'Musculoskeletal: hot, inflamed arthritic and rheumatic joints, low back, aching muscles (best modern evidence).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H164', 'SY01', 'Secondary', 'Nervous: analgesic for headache and neuralgia; pain modulation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H164', 'SY05', 'Secondary', 'Immune and systemic: febrifuge for fever and feverish inflammation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H164', 'SY08', 'Minor', 'Digestive: bitter, astringent tone; traditional astringent for lax bowels.');
