INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A09', 'Primary', 'Anti-inflammatory: salicylates downregulate prostaglandin-driven inflammation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A27', 'Primary', 'Anodyne: analgesic for joint, back, muscle, head, and nerve pain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A15', 'Secondary', 'Astringent: condensed tannins tighten and tone; astringent wash and for lax bowels.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A25', 'Minor', 'Antioxidant: flavonoids and polyphenols.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A16', 'Minor', 'Bitter tonic: bitter bark gives mild digestive and hepatic stimulation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H164', 'A10', 'Minor', 'Antispasmodic: eases cramping pain, traditionally menstrual.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP76', 'Primary', 'Fever management: the classic febrifuge use (adults).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP14', 'Primary', 'Joint pain: osteoarthritic and rheumatic joints.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP77', 'Primary', 'Generalized pain: broad analgesic / anodyne use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP40', 'Secondary', 'Back pain: standardized extract has the best clinical evidence here.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP19', 'Secondary', 'Headaches: analgesic for tension and inflammatory headache.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP13', 'Secondary', 'Systemic inflammation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP38', 'Secondary', 'Myalgia: muscle aches and soreness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP22', 'Minor', 'Neuralgia.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H164', 'CP29', 'Minor', 'Dysmenorrhea: traditional for menstrual cramping.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H164', 'P04', 'Primary', 'Decoction of the dried bark: the traditional form for a bark.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H164', 'P01', 'Primary', 'Tincture of the bark.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H164', 'P02', 'Secondary', 'Standardized capsule or tablet expressed as total salicin.');
