INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI617', 'H164', 'pregnancy', 'Pregnancy (particularly the third trimester)', 'moderate', 'Salicin yields salicylic acid, which crosses the placenta and is cleared slowly by the newborn; like aspirin it risks premature closure of the fetal ductus arteriosus, prolonged gestation and labor, and maternal or neonatal bleeding. Willow bark is unstudied in pregnancy.', 'Avoid throughout pregnancy, and strictly in the third trimester.', 'United States Pharmacopeia Safety Review of Willow Bark (Planta Medica 2019; PMID 31604354); NCCIH; LactMed (NBK501904).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI618', 'H164', 'breastfeeding', 'Breastfeeding', 'moderate', 'Salicylic acid passes into breast milk after salicylate ingestion, rising disproportionately at higher maternal doses; high-dose maternal aspirin has caused metabolic acidosis in a breastfed infant and salicylate carries a theoretical Reye''s concern.', 'Avoid while breastfeeding; use safer analgesics and antipyretics.', 'LactMed / Drugs and Lactation Database, Willow Bark (NBK501904); Drugs.com breastfeeding summary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI619', 'H164', 'other', 'Children and adolescents under 18, especially during fever or viral illness (influenza, chickenpox)', 'absolute', 'Salicylates are causally linked to Reye''s syndrome, a rare but frequently fatal acute swelling of the liver and brain, when given to children or teens during a viral infection. Willow bark tea for fever has caused fatal pediatric Reye''s syndrome.', 'Do not give willow bark to anyone under 18 with fever or viral illness; use acetaminophen for pediatric fever.', 'Memorial Sloan Kettering About Herbs, Willow Bark; StatPearls, Reye Syndrome (NBK526101); LactMed (NBK501904).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI620', 'H164', 'other', 'Aspirin or salicylate hypersensitivity, and aspirin-exacerbated respiratory disease / aspirin-sensitive asthma', 'absolute', 'Cross-reactivity with the salicylate moiety; anaphylaxis has been reported from a willow-bark-containing supplement in an aspirin-allergic person, and salicylates can precipitate bronchospasm in aspirin-sensitive asthma.', 'Do not use in anyone with known aspirin or salicylate allergy or aspirin-sensitive asthma.', 'Boullata et al., anaphylactic reaction to a willow-bark supplement (PMID 12773073); Memorial Sloan Kettering About Herbs, Willow Bark.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI621', 'H164', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, clopidogrel, ticlopidine, pentoxifylline, low-dose aspirin) and the pre-surgical period', 'moderate', 'Salicylate adds to antiplatelet and anticoagulant effect, increasing bleeding risk.', 'Avoid the combination or use only with clinician oversight and bleeding monitoring; stop about 2 weeks before surgery.', 'Memorial Sloan Kettering About Herbs, Willow Bark; Drugs.com willow bark monograph; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI622', 'H164', 'drug_interaction', 'Methotrexate', 'moderate', 'Salicylates reduce renal clearance of methotrexate and displace it from plasma protein, raising serum levels and the risk of hepatic, GI, and marrow toxicity.', 'Avoid concurrent use; if unavoidable, use only under oncology or rheumatology supervision with level monitoring.', 'Memorial Sloan Kettering About Herbs, Willow Bark; Drugs.com willow bark monograph; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI623', 'H164', 'drug_interaction', 'Other salicylates and NSAIDs (aspirin, ibuprofen, naproxen)', 'moderate', 'Additive salicylate load with additive gastrointestinal irritation, ulcer, and renal risk.', 'Avoid stacking with other salicylates or NSAIDs; monitor for GI symptoms.', 'Drugs.com willow bark monograph; United States Pharmacopeia Safety Review of Willow Bark (PMID 31604354).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI624', 'H164', 'condition', 'Active peptic ulcer or history of GI bleeding; also gout, diabetes, and kidney or liver disease', 'moderate', 'Salicylates irritate the gastric mucosa and can worsen ulceration and bleeding; they blunt uricosurics in gout, can shift glycemic control, and stress renal and hepatic clearance.', 'Avoid in active peptic ulcer or GI bleeding; use cautiously with medical oversight in gout, diabetes, and renal or hepatic disease.', 'United States Pharmacopeia Safety Review of Willow Bark (PMID 31604354); Drugs.com willow bark monograph.');
