INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS09', 'Primary', 'Laxity/atony: astringent tightens lax, weeping bowel mucosa and slack, leaky capillary and venous walls.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS07', 'Primary', 'Dampness: tannins bind and dry the damp, over-loose, watery bowel of acute diarrhea.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS08', 'Secondary', 'Sluggish, pooled microcirculation and venous congestion; anthocyanins tone and protect vessels.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS05', 'Minor', 'Cools excess heat in hot, over-full, irritated vessels and mucous membranes.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS06', 'Minor', 'Anti-inflammatory for inflamed mouth/throat mucosa and irritated vessels.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS03', 'Primary', 'Drying astringent worsens dry, thin, parched tissue and dry constipation (over-binding).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H165', 'TS17', 'Secondary', 'Cooling nature aggravates a frankly cold, deficient terrain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H165', 'SY08', 'Primary', 'Digestive/lower bowel: astringent antidiarrheal; topical gargle for mouth and throat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H165', 'SY06', 'Primary', 'Cardiovascular: capillaries, veins, and retinal microcirculation; capillary fragility, venous congestion, retinopathy support.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H165', 'SY02', 'Secondary', 'Endocrine/metabolic: leaf traditionally lowers blood sugar.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H165', 'SY09', 'Minor', 'Urinary: mild astringent and diuretic leaf action (traditional).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A15', 'Primary', 'Astringent: tannins bind the loose bowel and tighten lax, leaky vessels and mucous membranes.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A25', 'Primary', 'Antioxidant: anthocyanins scavenge free radicals and stabilize collagen and capillary walls.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A09', 'Secondary', 'Anti-inflammatory: anthocyanins lower inflammatory mediators (CRP, interleukins).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A36', 'Secondary', 'Hypoglycemic: leaf traditionally lowers blood glucose (alpha-glucosidase inhibition, chromium).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A28', 'Minor', 'Antimicrobial: anthocyanins and tannins are mildly antimicrobial/astringent in the gut.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H165', 'A08', 'Minor', 'Diuretic: mild, from the leaf (traditional).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H165', 'CP56', 'Primary', 'Acute nonspecific diarrhea (Commission E signature use of the dried berry).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H165', 'CP47', 'Secondary', 'Poor peripheral circulation; sluggish microcirculation, capillary fragility, easy bruising.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H165', 'CP48', 'Secondary', 'Varicose veins and venous stasis; venous congestion.');
