INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H165', 'P04', 'Primary', 'Decoction of dried ripe berries: the classic antidiarrheal preparation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H165', 'P02', 'Primary', 'Standardized anthocyanin fruit extract (capsule/tablet), the main modern vascular/vision form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H165', 'P05', 'Secondary', 'Infusion/tea of dried berries; cooled decoction as an astringent gargle.');
