INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI625', 'H165', 'pregnancy', 'Pregnancy', 'moderate', 'Fruit is safe as food, but safety of amounts greater than found in foods is not established; the leaf carries chronic-toxicity potential (hydroquinone) with no pregnancy data.', 'Ripe berries as food are acceptable; avoid concentrated therapeutic extract doses and avoid the leaf entirely.', 'NCCIH Bilberry fact sheet; LactMed (Drugs and Lactation Database) Bilberry record.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI626', 'H165', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion of bilberry components into breast milk or on safety in nursing mothers or infants; no recommendation can be made for large quantities.', 'Limit to food amounts of the fruit; avoid concentrated extracts and the leaf while breastfeeding.', 'LactMed (Drugs and Lactation Database) Bilberry record; NCCIH Bilberry fact sheet.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI627', 'H165', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, apixaban, rivaroxaban) and NSAIDs, and the pre-surgical period', 'moderate', 'Bilberry anthocyanins inhibit platelet aggregation and may raise prothrombin and partial thromboplastin times; a case of rectal bleeding and hematuria was reported with long-term bilberry plus a newly started anticoagulant, with synergistic bleeding described with aspirin and NSAIDs.', 'Use cautiously with clinician oversight and bleeding monitoring; discontinue about 2 weeks before surgery.', 'Memorial Sloan Kettering Cancer Center, About Herbs: Bilberry Fruit; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI628', 'H165', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Bilberry, especially the leaf, may lower blood glucose, an additive effect that could cause hypoglycemia.', 'Monitor blood glucose and coordinate dosing with the prescriber.', 'Memorial Sloan Kettering Cancer Center, About Herbs: Bilberry Fruit; NCCIH Bilberry fact sheet.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI629', 'H165', 'other', 'Bilberry leaf, prolonged or high-dose internal use', 'moderate', 'Chronic high-dose leaf intake has caused wasting (cachexia), anemia, jaundice, and death in animals, attributed to hydroquinone and related constituents.', 'Use the leaf only short term and at modest doses, or avoid it; the ripe fruit does not carry this risk.', 'NCCIH Bilberry fact sheet; AHPA Botanical Safety Handbook, 2nd ed.; Commission E (bilberry leaf not approved).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H165', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931): Bilberry (Whortleberry, Vaccinium myrtillus). Supported by Commission E monograph (Myrtilli fructus, dried bilberry fruit) for acute nonspecific diarrhea and topical mild inflammation of the mouth and throat.", "locator": "Grieve, A Modern Herbal (1931): Bilberry (Whortleberry, Vaccinium myrtillus). Supported by Commission E monograph (Myrtilli fructus, dried bilberry fruit) for acute nonspecific diarrhea and topical mild inflammation of the mouth and throat.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH Bilberry fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Bilberry Fruit. LactMed (Drugs and Lactation Database) Bilberry record (NBK501825). ESCOP and Commission E monographs (Vaccinium myrtillus fruit). AHPA Botanica", "locator": "NCCIH Bilberry fact sheet. Memorial Sloan Kettering Cancer Center, About Herbs: Bilberry Fruit. LactMed (Drugs and Lactation Database) Bilberry record (NBK501825). ESCOP and Commission E monographs (Vaccinium myrtillus fruit). AHPA Botanica", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, true);
