INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI630', 'H166', 'pregnancy', 'Pregnancy (unsupervised self-use)', 'moderate', 'Uterine-active (uterotropic) agent. Traditionally used IN pregnancy for threatened miscarriage under supervision, but robust modern human safety data are lacking and general references class it possibly unsafe for self-use.', 'Do not self-administer in pregnancy; use only under a qualified herbalist or physician.', 'Drugs.com (Black Haw NPP); RxList; WebMD; Mills and Bone; Herbal Reality.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI631', 'H166', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate safety data during lactation.', 'Use only under professional supervision while breastfeeding.', 'Herbal Reality (Black Haw); Drugs.com.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI632', 'H166', 'pediatric', 'Young children', 'moderate', 'No pediatric safety data; not traditionally given to children.', 'Avoid in young children; adolescent use only under professional guidance.', 'Drugs.com (no pediatric data); precautionary practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI633', 'H166', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Coumarin (scopoletin) and salicylate content may add to bleeding risk.', 'Combine only with caution and clinical monitoring; watch for bruising or bleeding.', 'Drugs.com (Black Haw NPP); RxList; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI634', 'H166', 'condition', 'History of oxalate (calcium-oxalate) kidney stones', 'moderate', 'Contains oxalic acid, which could contribute to stone formation, though the oxalates are largely water-insoluble.', 'Use cautiously or avoid in those with a history of oxalate kidney stones.', 'Drugs.com (Black Haw NPP); RxList; WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI635', 'H166', 'other', 'Aspirin / salicylate hypersensitivity', 'moderate', 'Contains salicin and salicylates that may cross-react in aspirin-sensitive individuals.', 'Avoid in known aspirin or salicylate allergy.', 'Drugs.com (Black Haw NPP); WebMD; Herbal Reality.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI636', 'H166', 'condition', 'Cold-deficiency and dryness constitutional states', 'low', 'Cool, drying, astringent qualities can chill, tighten, and deplete an already cold, dry, deficient interior.', 'Combine with warming, moistening, tonic herbs where the picture is cold and depleted rather than hot and tense.', 'Traditional energetic assessment (King''s American Dispensatory; Mills and Bone).');
