INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H167', 'SY08', 'Secondary', 'Digestive: sialagogue and bitter; emetic in large doses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H167', 'SY06', 'Secondary', 'Cardiovascular: cardioactive via Na+/K+-ATPase inhibition (a caution).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H167', 'SY03', 'Minor', 'Reproductive: historical uterine stimulant / emmenagogue (a safety flag, not a use).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A12', 'Primary', 'Stimulating (nauseating) expectorant for thick, stuck catarrh.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A28', 'Primary', 'Antimicrobial: sanguinarine is antibacterial and antifungal.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A10', 'Secondary', 'Antispasmodic for spasmodic, asthmatic, croupy cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A14', 'Secondary', 'Alterative in small doses for chronic respiratory and skin conditions.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A19', 'Minor', 'Emmenagogue / uterine stimulant (historical; carries abortifacient risk, never in pregnancy).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H167', 'A45', 'Minor', 'Antiemetic in very small doses (paradoxically emetic in large doses).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP51', 'Primary', 'Bronchial congestion: stimulating expectorant for thick, boggy catarrh.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP49', 'Primary', 'Productive cough that will not loosen.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP17', 'Secondary', 'Respiratory issues (general): chronic catarrh, croup, laryngitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP53', 'Secondary', 'Asthmatic tendency: antispasmodic for spasmodic cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP52', 'Minor', 'Sore throat / laryngitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP18', 'Minor', 'Skin conditions (general): historical topical escharotic use, now strongly discouraged.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H167', 'CP41', 'Minor', 'Cold / flu onset with congestion (traditional).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H167', 'P01', 'Primary', 'Tincture: the preferred, dose-controllable internal form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H167', 'P03', 'Secondary', 'Powdered rhizome in small amounts.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H167', 'P04', 'Minor', 'Weak short-term decoction, low dose.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H167', 'P09', 'Minor', 'Compound expectorant syrup (historical).');
