INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H167', 'TCM11', 'Primary', 'Heat / Fire: aggravates red, hot, inflamed, dry-cough heat patterns.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Sanguinaria.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Sanguinaria.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Sanguinaria; Grieve, A Modern Herbal (1931): Bloodroot; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): Sanguinaria canadensis; Brinker, Herbal ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Sanguinaria; Grieve, A Modern Herbal (1931): Bloodroot; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): Sanguinaria canadensis; Brinker, Herbal ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI637', 'H167', 'pregnancy', 'Pregnancy (all trimesters) and preconception', 'absolute', 'Documented uterine stimulant, emmenagogue, and historical abortifacient; cytotoxic benzophenanthridine alkaloids (sanguinarine, chelerythrine) with protopine/chelerythrine uterine-stimulant activity.', 'Do not use in pregnancy or when trying to conceive, in any form or dose. Screen for possible pregnancy before use.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013): not for use in pregnancy; Brinker, Herbal Contraindications and Drug Interactions; Croaker et al. 2016 (PMC5037693).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI638', 'H167', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation safety data; cytotoxic quaternary benzophenanthridine alkaloids with uncharacterized transfer into milk.', 'Avoid internal use while breastfeeding pending data.', 'AHPA Botanical Safety Handbook, 2nd ed. (insufficient data); NCCIH consumer guidance principle.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI639', 'H167', 'other', 'Escharotic paste / black salve on skin lesions, moles, or suspected skin cancer', 'absolute', 'Bloodroot escharotics cause indiscriminate tissue necrosis, permanent scarring and disfigurement, and can mask a progressing malignancy beneath the eschar; efficacy against skin cancer is unproven.', 'Do not self-treat any skin lesion or suspected cancer with bloodroot or black salve; seek dermatological diagnosis and proven therapy.', 'U.S. FDA Consumer Update, ''Black Salve Is Dangerous and Called by Many Names''; case series on black-salve injury; Croaker et al. 2016 (PMC5037693).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI640', 'H167', 'drug_interaction', 'Cardiac glycosides and antiarrhythmic / cardioactive drugs (digoxin, digitalis)', 'moderate', 'Sanguinarine inhibits Na+/K+-ATPase (IC50 about 6.0 to 6.5 micromolar), the digoxin target, risking additive cardiotoxicity and arrhythmia.', 'Avoid internal bloodroot in patients on cardiac glycosides or antiarrhythmics; use only under practitioner supervision if at all.', 'Croaker et al. 2016 (PMC5037693); Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI641', 'H167', 'condition', 'Chronic oral / mucosal exposure (oral leukoplakia risk)', 'moderate', 'Sanguinarine-containing dental products (Viadent) were associated with an 8- to 11-fold higher risk of oral leukoplakia, a potentially premalignant lesion, and were withdrawn from the market.', 'Avoid repeated or long-term oral/mucosal application of bloodroot; do not use sanguinarine oral products chronically.', 'Damm et al. and Eversole et al., sanguinaria-associated leukoplakia studies; ''Rise and Fall of Oral Health Products with Canadian Bloodroot Extract'' (Phytother Res, 2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI642', 'H167', 'condition', 'Overdose / narrow therapeutic margin', 'moderate', 'Larger doses are emetic and cardioactive: burning epigastric pain, vomiting, intense thirst, visual dimness, faintness, and bradycardia or arrhythmia.', 'Keep strictly to low, controlled doses; do not exceed recommended amounts; keep out of reach of children.', 'AHPA Botanical Safety Handbook, 2nd ed.; King''s American Dispensatory (Felter & Lloyd, 1898); Croaker et al. 2016 (PMC5037693).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI643', 'H167', 'condition', 'Glaucoma', 'low', 'Sanguinarine is the alkaloid implicated in epidemic-dropsy glaucoma (via Argemone-oil contamination), suggesting caution in raised intraocular pressure.', 'Use cautiously, if at all, in glaucoma; monitor for visual symptoms.', 'Croaker et al. 2016 (PMC5037693); epidemic-dropsy sanguinarine literature.');
