INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI644', 'H168', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Anthranoid stimulant laxative: vigorous colonic stimulation can provoke reflex uterine activity, and Da Huang has a strong traditional blood-moving, stasis-dispelling and emmenagogue action contraindicated in pregnancy.', 'Avoid entirely during pregnancy, in decoction, powder or tincture.', 'AHPA Botanical Safety Handbook, 2nd ed. (rhubarb root not for use during pregnancy); ESCOP and German Commission E (anthranoid laxatives contraindicated in pregnancy); Brinker, Herbal Contraindications and Drug Interactions; Bensky et al., Chinese Herbal Medicine: Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI645', 'H168', 'breastfeeding', 'Breastfeeding', 'moderate', 'Anthraquinones were undetectable in one older study of nursing mothers with no infant laxative effect, but current reviewers caution that cathartic effects in the breastfed infant are possible.', 'Avoid medicinal purging doses during breastfeeding; if a laxative is truly needed, use under professional guidance.', 'NIH LactMed (Drugs and Lactation Database, Rhubarb, NBK501862); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI646', 'H168', 'drug_interaction', 'Cardiac glycosides (digoxin)', 'moderate', 'Stimulant-laxative potassium loss potentiates cardiac glycoside toxicity.', 'Avoid combined or prolonged use; if unavoidable, monitor potassium and for signs of digoxin toxicity.', 'AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herbal Contraindications and Drug Interactions; Memorial Sloan Kettering About Herbs (Rhubarb).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI647', 'H168', 'drug_interaction', 'Potassium-depleting drugs (thiazide/loop diuretics, corticosteroids, licorice)', 'moderate', 'Additive potassium loss increases the risk of hypokalemia and its sequelae.', 'Avoid regular concurrent use; monitor electrolytes if combined.', 'AHPA Botanical Safety Handbook, 2nd ed.; ESCOP monograph (Rhei radix); Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI648', 'H168', 'drug_interaction', 'Oral medications generally (e.g. cyclosporine, some CYP substrates)', 'low', 'Accelerated intestinal transit and tannin binding can reduce absorption; reduced cyclosporine bioavailability and altered exposure of some substrates reported.', 'Separate dosing of the herb from other oral drugs by at least 2 hours; clinical relevance varies.', 'Memorial Sloan Kettering About Herbs (Rhubarb); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI649', 'H168', 'condition', 'Bowel obstruction, ileus, IBD (Crohn''s/ulcerative colitis), appendicitis, undiagnosed abdominal pain', 'absolute', 'Stimulant purgatives are dangerous in obstruction and acute inflamed or undiagnosed abdomen.', 'Do not use; seek medical evaluation for undiagnosed or acute abdominal pain.', 'German Commission E and ESCOP monographs for anthranoid laxatives (Rhei radix).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI650', 'H168', 'condition', 'Children under 12; prolonged self-use; calcium-oxalate kidney stones', 'moderate', 'Fluid/electrolyte risk in young children and with prolonged stimulant-laxative use; oxalate content is a concern in stone-formers.', 'Avoid as a home laxative in children under 12; limit to 1 to 2 weeks; use caution with a history of calcium-oxalate stones.', 'Commission E and ESCOP (stimulant laxatives, children under 12; short-term use); Memorial Sloan Kettering About Herbs (oxalate/kidney).');
