INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS05', 'Primary', 'Clears heat rising to the head and eyes; red, hot, irritated eyes and flushed face.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS10', 'Primary', 'Subdues ascendant Liver yang; throbbing headache, dizziness, a wound-up, over-stimulated head.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS20', 'Primary', 'Disperses wind-heat; onset of hot colds and flu, wind-heat headache.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS18', 'Secondary', 'Relaxes tension and constraint in the head and Liver channel; tight, gripping headaches.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS06', 'Secondary', 'Anti-inflammatory for hot, red, inflamed eyes and throat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS12', 'Minor', 'Eases vascular and Liver-channel constriction; mildly vasodilatory.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS17', 'Primary', 'Cooling; aggravates a cold, chilled terrain and wind-cold patterns.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H169', 'TS01', 'Secondary', 'Cold and bitter; weakens a deficient, cold digestion (poor appetite, loose stools).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H169', 'SY12', 'Primary', 'Clears Liver heat and calms ascendant Liver yang; the eye and vision organ.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H169', 'SY07', 'Primary', 'Disperses wind-heat at the surface; early colds, sore throat, cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H169', 'SY06', 'Secondary', 'Traditional and mildly hypotensive, vessel-relaxing herb for headache and high blood pressure.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H169', 'SY01', 'Secondary', 'Headache, dizziness, and a calming, cooling effect on an over-heated head.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H169', 'A18', 'Primary', 'Disperses wind-heat; gentle surface-releasing diaphoretic for hot colds.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H169', 'A09', 'Primary', 'Anti-inflammatory for red, hot eyes, throat, and head.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H169', 'A49', 'Secondary', 'Febrifuge; cools mild wind-heat fever.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H169', 'A25', 'Secondary', 'Antioxidant; flavonoids (luteolin, apigenin) and chlorogenic acid.');
