INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H169', 'TCM03', 'Secondary', 'Cold and bitter; aggravates cold, deficient Spleen digestion (poor appetite, loose stools).', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han-dynasty compilation) - Ju Hua (Chrysanthemum flower), listed among the superior / upper-grade herbs.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han-dynasty compilation) - Ju Hua (Chrysanthemum flower), listed among the superior / upper-grade herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Ju Hua (Chrysanthemi Flos); Memorial Sloan Kettering Cancer Center, About Herbs: Chrysanthemum; Natural Medicines Comprehensive Database (Chrysanthemum); NCCIH; ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Ju Hua (Chrysanthemi Flos); Memorial Sloan Kettering Cancer Center, About Herbs: Chrysanthemum; Natural Medicines Comprehensive Database (Chrysanthemum); NCCIH; ", "source_id": "S30", "author": "NCCIH Herbs at a Glance", "year": "current", "url": "https://www.nccih.nih.gov/health/herbsataglance"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI651', 'H169', 'other', 'Asteraceae/Compositae allergy (ragweed, marigold, daisy, chamomile, feverfew)', 'moderate', 'Cross-reactive plant allergens and sesquiterpene lactones; a documented primary sensitizer causing allergic, airborne, and occupational contact dermatitis, and rarely respiratory reactions.', 'Avoid in people with known daisy-family or ragweed allergy; discontinue if rash, itching, or swelling occurs. Handling fresh plant material poses the highest dermatitis risk.', 'Natural Medicines Comprehensive Database; Memorial Sloan Kettering Cancer Center (About Herbs: Chrysanthemum); DermNet NZ.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI652', 'H169', 'drug_interaction', 'CYP3A4 substrates, especially immunosuppressants (tacrolimus, cyclosporine, sirolimus)', 'moderate', 'Chrysanthemum inhibits CYP3A4; a case report describes a transplant patient developing toxic blood levels of immunosuppressant medication after drinking chrysanthemum-containing tea.', 'Avoid concentrated or regular medicinal use with narrow-therapeutic-index CYP3A4 substrates; monitor drug levels closely if co-used with immunosuppressants, some statins, calcium-channel blockers, or benzodiazepines.', 'Memorial Sloan Kettering Cancer Center (About Herbs: Chrysanthemum); Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI653', 'H169', 'drug_interaction', 'P-glycoprotein substrates (for example digoxin)', 'moderate', 'Chrysanthemum inhibits the P-glycoprotein transporter, which can raise intracellular and blood levels of P-gp substrate drugs.', 'Use caution with P-gp substrate drugs of narrow therapeutic index; monitor for enhanced drug effect.', 'Memorial Sloan Kettering Cancer Center (About Herbs: Chrysanthemum).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI654', 'H169', 'other', 'Photosensitivity / sun exposure', 'low', 'Chrysanthemum can increase skin sensitivity to sunlight and has caused chronic actinic (UV-A) dermatitis in exposed workers.', 'Use sun protection during regular use, especially in light-skinned or already photosensitive individuals; consider additive risk with photosensitizing drugs.', 'Natural Medicines Comprehensive Database; Memorial Sloan Kettering Cancer Center.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI655', 'H169', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable safety data for medicinal amounts in pregnancy.', 'Avoid medicinal or supplemental amounts; culinary-strength tea has a long traditional history but concentrated use is best avoided for want of data.', 'Natural Medicines Comprehensive Database; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI656', 'H169', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable safety data during lactation.', 'Avoid amounts greater than found in food; mothers with Asteraceae allergy should be cautious.', 'Natural Medicines Comprehensive Database; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI657', 'H169', 'condition', 'Spleen/Stomach qi deficiency with cold (poor appetite, loose stools)', 'moderate', 'A cool, bitter flower further chills and weakens a cold, deficient digestion and can loosen the stool.', 'Avoid or use only in warming, digestion-supporting formulas in cold, qi-deficient, loose-stool patients.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Ju Hua.');
