INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H169', 'EP08', 'avoid', 0, 2, 'temperature: herb cold reinforces the pattern''s cold; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han-dynasty compilation) - Ju Hua (Chrysanthemum flower), listed among the superior / upper-grade herbs.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han-dynasty compilation) - Ju Hua (Chrysanthemum flower), listed among the superior / upper-grade herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Ju Hua (Chrysanthemi Flos); Memorial Sloan Kettering Cancer Center, About Herbs: Chrysanthemum; Natural Medicines Comprehensive Database (Chrysanthemum); NCCIH; ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Ju Hua (Chrysanthemi Flos); Memorial Sloan Kettering Cancer Center, About Herbs: Chrysanthemum; Natural Medicines Comprehensive Database (Chrysanthemum); NCCIH; ", "source_id": "S30", "author": "NCCIH Herbs at a Glance", "year": "current", "url": "https://www.nccih.nih.gov/health/herbsataglance"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H170', 'Goji / Wolfberry (Gou Qi Zi)', 'Lycium barbarum', 'Solanaceae', 'Ripe fruit (berry), dried', 'Sweet (predominant), faintly Sour', 'Neutral', 'Moist', 'Deficiency and Blood Deficiency (a sweet, nourishing yin and blood tonic for Liver and Kidney depletion: pallor, dizziness, blurred vision, weak low back and knees); Dryness (moistens yin-deficient dryness, dry eyes, thirst, a dry constitutional pattern); Atrophy (rebuilds in wasting, essence depletion, poor vision and premature graying); Exhaustion (a restorative food-herb for convalescence, debility and long-standing depletion). Its action is building and tonifying, not dispersing.', 'Dampness (the sweet, moist, slightly cloying berry burdens a damp, boggy Spleen and can loosen the stool); Phlegm (unsuitable where damp-phlegm accumulation predominates); active external or Acute Infection (traditionally withheld while an exterior pathogenic factor or acute febrile illness is present, as a rich tonic can hold the pathogen in).', 'Hepatic (Liver: nourishes Liver blood and yin, brightens the eyes); Reproductive (Kidney essence and fertility, low libido); Urinary (Kidney, weak low back and knees); Endocrine (Kidney-adrenal restorative, blood-sugar modulation); Immune (Lycium barbarum polysaccharides modulate immune function); Cardiovascular (nourishes blood, supports retinal microcirculation, mild effects on lipids and blood pressure); Nervous and the eyes (vision, retinal and macular support, cerebral tonic).', 'Fatigue, debility and depleted convalescence in the dry, thin, blood-deficient type; blurred vision, poor night vision, tired dry eyes and age-related vision decline (the signature ''brightens the eyes'' use); dizziness, tinnitus and weak aching low back and knees of Liver-Kidney deficiency; low libido, seminal and fertility weakness (Kidney essence); premature graying and thinning; pallor and blood deficiency; blood-sugar dysregulation and oxidative-stress-driven aging; low immune resilience and frequent illness; general restorative food-tonic for the elderly and the convalescent.', 'Deficient/Pale and Thin/Cold/Depleted (Vata-like): the dry, wiry, blood- and essence-depleted phenotype that runs down easily, with pallor, dry eyes and weak vision. Also suits the Melancholic, dry-depleted temperament. Poorly suited to the Phlegmatic, damp, boggy constitution with sluggish digestion and loose stools, where the sweet, moist berry adds to the damp load.', 'Vata primarily (sweet rasa, unctuous and nourishing, cool-to-neutral virya: rebuilds depleted tissue, ojas and essence, a classic rasayana of the dry, depleted type); also settling to Pitta through its sweet, cooling, blood-nourishing quality.', 'Kapha: the sweet, heavy, moist, building nature increases Kapha and can aggravate a damp, congested, low-digestive-fire (ama) state if used in quantity.', 'Gou Qi Zi (Fructus Lycii), sweet and neutral, entering Liver and Kidney: nourishes and tonifies Liver and Kidney yin and essence, and enriches Liver blood (dizziness, blurred and diminished vision, sore weak low back and knees, nocturnal emission, wasting and thirsting disorder / xiao ke); benefits the eyes (the premier ''brighten the eyes'' yin tonic); moistens the Lungs in yin-deficient dry cough.', 'Dampness/Phlegm and Spleen Qi Deficiency with dampness (loose stools, poor appetite, damp-heat), where the sweet, moist, enriching berry is cloying and burdens the middle. Traditionally also withheld during acute exterior conditions with an unresolved external pathogenic factor and heat.', 'Generally very well tolerated as a food. As a nightshade-family fruit it carries rare allergy potential: reports of allergic reactions and isolated anaphylaxis have been linked to a lipid-transfer-protein allergen that cross-reacts with peach, tomato and other foods, and photosensitivity has been reported. The sweet, moist quality can loosen the stool and aggravate damp, phlegmatic digestion. The clinically important concern is potentiation of warfarin (see drug interactions) and additive blood-sugar lowering with antidiabetic therapy. Imported dried berries should be sourced from suppliers who test for pesticide and heavy-metal residues.', 'Concurrent warfarin or other coumarin anticoagulant therapy (documented potentiation of anticoagulant effect with bleeding). Use cautiously with antidiabetic (hypoglycemic) medication because of additive blood-sugar lowering, and with immunosuppressant therapy on theoretical grounds (immune-stimulating polysaccharides). Avoid concentrated or therapeutic (supplement/extract) doses in pregnancy pending better data; ordinary culinary amounts are considered low-risk. Solanaceae (nightshade) allergy or known lipid-transfer-protein food allergy.', 'Avoid concentrated or therapeutic doses; ordinary culinary amounts are considered low-risk. Modern references note that safety and efficacy data in pregnancy are lacking, so supplemental or extract-strength use is not recommended; the fruit is rich in betaine, which has a traditional reputation for uterine activity, though robust human evidence is absent. Basis: drugs.com Natural Products (Goji berry) and AHPA Botanical Safety Handbook, 2nd ed. (insufficient pregnancy data); precaution consistent with NCCIH guidance to avoid unstudied botanicals in pregnancy.', 'Insufficient data; use caution. There are no controlled human lactation studies and no data on transfer of goji constituents into breastmilk; independent lactation resources rate ordinary dietary amounts as low-risk while advising against concentrated supplement doses. Basis: e-lactation (Goji berries, low-risk for dietary use) and drugs.com Natural Products (limited lactation data); treat medicinal/extract doses as insufficiently studied.', 'Ordinary food amounts of the berry are generally well tolerated in children; concentrated extracts and therapeutic doses have not been studied in pediatric populations and are not recommended without guidance. Watch for nightshade/lipid-transfer-protein food allergy in atopic children. Basis: absence of controlled pediatric studies (NCCIH-style insufficient-data precaution); drugs.com Natural Products (Goji berry).', 'Warfarin and other coumarin anticoagulants: multiple published case reports describe elevated INR and bleeding (epistaxis, bruising, rectal bleeding) after goji juice, tea or wine in warfarin-treated patients, with a Naranjo-probable relationship; the likely mechanism is inhibition of CYP2C9-mediated warfarin metabolism. Avoid or, if unavoidable, monitor INR closely. Antidiabetic (hypoglycemic) drugs: Lycium barbarum polysaccharides can lower blood glucose, so additive hypoglycemia is plausible; monitor blood sugar. Immunosuppressants: theoretical antagonism from immune-stimulating polysaccharides (e.g. in transplant or autoimmune therapy); use caution. Basis: Lam 2001 and Rivera et al. 2012 (Pharmacotherapy) and the Gouqizi-wine case (PMC5598317); AHPA Botanical Safety Handbook (Lycium fruit, Interactions Class C); Mills & Bone herb-drug interaction principles. Human interaction data beyond the warfarin reports are limited.', 'Eaten directly as a dried fruit or added to soups, congee, broths and stews (the most common traditional use); water decoction; infusion (tea); medicinal wine or elixir (the classic Gou Qi wine); tincture; dried-fruit powder. Frequently combined with chrysanthemum (Ju Hua) for the eyes and with other yin and blood tonics.', 'Dried fruit: 6-15 g daily, decocted or simply eaten (a small handful). As a food, roughly 10-30 g of dried berries daily. Tea: 1-2 teaspoons of dried berries steeped per cup. Tincture (1:5): 3-5 mL up to three times daily. Higher single intakes (more than about 6-12 g concentrated) are the ones implicated in warfarin potentiation.', 'Shennong Ben Cao Jing (Han dynasty) - Gou Qi (Lycium). Corroborating classical text: Li Shizhen, Ben Cao Gang Mu (1596) - Gou Qi Zi.', 'Modern: Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Gou Qi Zi); AHPA Botanical Safety Handbook, 2nd ed. (Lycium barbarum, Interactions Class C); drugs.com Natural Products database (Goji berry); Rivera et al., Probable Interaction Between Lycium barbarum (Goji) and Warfarin, Pharmacotherapy 2012 (PMID 22392461); Bleeding due to a probable interaction between warfarin and Gouqizi (PMC5598317); review: Lycium Barbarum: A Traditional Chinese Herb and A Promising Anti-Aging Agent (PMC5758351).', 'Constituents: Lycium barbarum polysaccharides (LBP, the principal immunomodulatory and hypoglycemic fraction), the carotenoid zeaxanthin dipalmitate and other carotenoids (beta-carotene, lutein) underpinning the eye-supportive and antioxidant reputation, betaine, cerebrosides, flavonoids and phenolics, plus vitamins and trace minerals. A ubiquitous tonic food-herb of Chinese medicine, sweet and neutral, nourishing Liver and Kidney yin, blood and essence. Nomenclature: ''Gou Qi Zi'' commercial goji derives from the fruit of Lycium barbarum and the closely related Lycium chinense; the root bark of the same plants is a separate, energetically opposite medicine, Di Gu Pi (Cortex Lycii), which is cold and clears deficiency heat, and must not be confused with the warming-neutral fruit. As a Solanaceae (nightshade) fruit it carries the family''s small allergy caveat. Some Western sources describe the fruit as slightly warming rather than strictly neutral.', 'Not named in the canonical biblical texts. Native to China and the Himalayan region and first documented in the Shennong Ben Cao Jing (Han dynasty). A Mediterranean relative, the boxthorn Lycium europaeum, does grow in the Holy Land and has been proposed by some scholars as a candidate for the thornbush (atad) of Jotham''s parable (Judges 9:14-15) or for the crown of thorns, but that identification is speculative and concerns a different species, not the medicinal goji.', 'Lycium barbarum is a widely cultivated agricultural crop (notably in Ningxia, China) and is not at risk in the wild; it carries no United Plant Savers listing. Favor cultivated, food-grade berries from suppliers who test for pesticide and heavy-metal residues, as contamination has been documented in some imported goji products.', 'Neutral and moist, deeply nourishing: a sweet yin and blood tonic that replenishes Liver and Kidney, moistens dryness, and brightens the eyes.', 'Refer for any unexplained bleeding or bruising, especially in anyone taking warfarin or another anticoagulant; sudden or progressive vision loss, flashes, floaters or eye pain (an ophthalmologic emergency, not a self-treatment target); uncontrolled or symptomatic blood-sugar swings; and any allergic reaction (hives, swelling, breathing difficulty). Those on warfarin, antidiabetic or immunosuppressant medication, and anyone pregnant considering more than culinary amounts, should coordinate use with their prescriber.', 'Goji (GOH-jee); Wolfberry (WOOLF-behr-ee); Gou Qi Zi (goh chee dzuh); Lycium barbarum (LISS-ee-um BAR-bar-um).', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (Han dynasty) - Gou Qi (Lycium). Corroborating classical text: Li Shizhen, Ben Cao Gang Mu (1596) - Gou Qi Zi.", "locator": "Shennong Ben Cao Jing (Han dynasty) - Gou Qi (Lycium). Corroborating classical text: Li Shizhen, Ben Cao Gang Mu (1596) - Gou Qi Zi.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Modern: Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Gou Qi Zi); AHPA Botanical Safety Handbook, 2nd ed. (Lycium barbarum, Interactions Class C); drugs.com Natural Products database (Goji berry); Rivera et al.,", "locator": "Modern: Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Gou Qi Zi); AHPA Botanical Safety Handbook, 2nd ed. (Lycium barbarum, Interactions Class C); drugs.com Natural Products database (Goji berry); Rivera et al.,", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
