INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI658', 'H170', 'drug_interaction', 'Warfarin and other coumarin anticoagulants', 'moderate', 'Multiple published case reports (goji juice, tea and wine) describe elevated INR and bleeding in warfarin-treated patients, Naranjo-probable; likely inhibition of CYP2C9-mediated warfarin metabolism potentiating anticoagulation.', 'Avoid combining. If a patient chooses to continue goji, monitor INR closely, keep intake consistent, and coordinate with the prescriber; watch for bruising, epistaxis or bleeding.', 'Rivera et al., Pharmacotherapy 2012 (PMID 22392461); Lam et al. 2001; Gouqizi-wine case (PMC5598317); AHPA Botanical Safety Handbook, 2nd ed. (Lycium fruit, Interactions Class C).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI659', 'H170', 'drug_interaction', 'Antidiabetic (hypoglycemic) drugs', 'moderate', 'Lycium barbarum polysaccharides can lower blood glucose, giving a plausible additive hypoglycemic effect with insulin or oral antidiabetics.', 'Monitor blood glucose and watch for hypoglycemia when combining; dose adjustment may be needed.', 'drugs.com Natural Products (Goji berry); Mills & Bone herb-drug interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI660', 'H170', 'drug_interaction', 'Immunosuppressant therapy', 'low', 'Immune-stimulating Lycium barbarum polysaccharides could theoretically oppose immunosuppression (e.g. in transplant or autoimmune therapy).', 'Use caution and avoid concentrated extracts in immunosuppressed patients; coordinate with the prescriber.', 'AHPA Botanical Safety Handbook, 2nd ed. (Lycium fruit, Interactions Class C); Mills & Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI661', 'H170', 'pregnancy', 'Pregnancy (concentrated/therapeutic doses)', 'moderate', 'Safety and efficacy data in pregnancy are lacking; the fruit is rich in betaine, which carries a traditional reputation for uterine activity, though robust human evidence is absent.', 'Avoid supplemental, extract or medicinal-strength doses in pregnancy pending better data; ordinary culinary amounts of the berry are considered low-risk.', 'drugs.com Natural Products (Goji berry); AHPA Botanical Safety Handbook, 2nd ed. (insufficient pregnancy data); NCCIH precautionary guidance.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI662', 'H170', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'No controlled lactation studies and no data on transfer of goji constituents into breastmilk.', 'Ordinary dietary amounts are rated low-risk; avoid concentrated supplement or extract doses during lactation.', 'e-lactation (Goji berries, low-risk for dietary use); drugs.com Natural Products (limited lactation data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI663', 'H170', 'condition', 'Solanaceae / lipid-transfer-protein food allergy', 'low', 'Goji is a nightshade fruit; a lipid-transfer-protein allergen cross-reacts with peach, tomato and related foods, with rare reports of allergic reactions and isolated anaphylaxis.', 'Avoid in known nightshade or LTP food allergy; introduce cautiously in atopic individuals and stop for any allergic response.', 'drugs.com Natural Products (Goji berry); case reports of goji hypersensitivity/anaphylaxis.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H170', 'EP01', 'neutral', 1, 1, 'moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Han dynasty) - Gou Qi (Lycium). Corroborating classical text: Li Shizhen, Ben Cao Gang Mu (1596) - Gou Qi Zi.", "locator": "Shennong Ben Cao Jing (Han dynasty) - Gou Qi (Lycium). Corroborating classical text: Li Shizhen, Ben Cao Gang Mu (1596) - Gou Qi Zi.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Modern: Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Gou Qi Zi); AHPA Botanical Safety Handbook, 2nd ed. (Lycium barbarum, Interactions Class C); drugs.com Natural Products database (Goji berry); Rivera et al.,", "locator": "Modern: Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Gou Qi Zi); AHPA Botanical Safety Handbook, 2nd ed. (Lycium barbarum, Interactions Class C); drugs.com Natural Products database (Goji berry); Rivera et al.,", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
