INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS12', 'Primary', 'Constriction: the flagship action, releasing bronchial and muscular spasm and opening the airways.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS18', 'Primary', 'Tension: the great general relaxant, easing spasmodic tension throughout the body.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS08', 'Secondary', 'Stagnation: moves stuck, congested phlegm and a stifled chest.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS23', 'Secondary', 'Phlegm: stimulating expectorant that resolves phlegm-laden airways.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS01', 'Primary', 'Deficiency: a violent emetic and dispersant further depletes the weak.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS04', 'Secondary', 'Exhaustion: evacuation and dispersal lower vitality in the depleted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS03', 'Secondary', 'Dryness: the warm, drying, dispersing action worsens dry tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H171', 'TS02', 'Minor', 'Atrophy: dispersal is wrong for wasted tissue that needs building.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H171', 'SY07', 'Primary', 'Respiratory: antispasmodic, stimulating expectorant, and respiratory relaxant for asthma, croup, and bronchitis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H171', 'SY01', 'Secondary', 'Nervous: the great general relaxant, easing spasm and tension.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H171', 'SY04', 'Secondary', 'Musculoskeletal: antispasmodic and anodyne for muscular spasm and cramp; topical liniment for sprains.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H171', 'SY08', 'Minor', 'Digestive: emetic, and relaxant to visceral spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A10', 'Primary', 'Antispasmodic: the defining action, for bronchial and general spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A12', 'Primary', 'Expectorant: stimulating expectorant that clears congested airways.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A03', 'Primary', 'Nervine Relaxant: the archetypal relaxant, releasing tension and spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A33', 'Secondary', 'Antitussive: calms the spasmodic, irritable cough (croup, whooping cough).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A18', 'Secondary', 'Diaphoretic: promotes sweating; the Thomsonian fever and relaxant use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A27', 'Minor', 'Anodyne: eases pain through relaxation, chiefly in topical liniment.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H171', 'A35', 'Minor', 'Rubefacient: warming topical liniment (traditionally with cayenne) over spasming muscles and chest.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP53', 'Primary', 'Asthmatic tendency: bronchial spasm; the flagship indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP51', 'Primary', 'Bronchial congestion: stimulating expectorant for the congested chest.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP17', 'Secondary', 'Respiratory issues (general): spasmodic croup, whooping cough, bronchitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP49', 'Secondary', 'Cough productive: expectorant clearing of phlegm.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP39', 'Secondary', 'Muscular tension and spasm, including topical use for sprains and strains.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H171', 'CP37', 'Minor', 'Muscle cramps: antispasmodic to skeletal muscle.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H171', 'P01', 'Primary', 'Tincture, including the classic Eclectic acid (acetous) tincture; the stronger seed tincture is dosed lower.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H171', 'P05', 'Secondary', 'Infusion of the dried herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H171', 'P03', 'Secondary', 'Powdered herb or seed (Thomsonian practice; the seed is strongest).');
