INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H171', 'TCM11', 'Minor', 'Heat/Fire: the herb''s warmth can aggravate heat patterns.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898): Lobelia.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898): Lobelia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931): Lobelia; Cook, The Physio-Medical Dispensatory (1869): Lobelia inflata; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Lobelia inflata (safety class 2b, interaction class A); Memorial S", "locator": "Grieve, A Modern Herbal (1931): Lobelia; Cook, The Physio-Medical Dispensatory (1869): Lobelia inflata; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Lobelia inflata (safety class 2b, interaction class A); Memorial S", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI664', 'H171', 'pregnancy', 'Pregnancy', 'absolute', 'Lobeline is a nicotinic acetylcholine receptor agonist; the herb is emetic and alters respiration, heart rate, and blood pressure. AHPA safety class 2b (not to be used during pregnancy).', 'Do not use during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Lobelia inflata (class 2b); Memorial Sloan Kettering About Herbs, Lobelia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI665', 'H171', 'breastfeeding', 'Breastfeeding', 'moderate', 'Lobeline is a nicotinic alkaloid that may pass into breast milk; no lactation safety data. AHPA advises against use in lactation.', 'Avoid while breastfeeding.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); NIH LactMed (no entry).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI666', 'H171', 'pediatric', 'Infants and young children', 'moderate', 'Low therapeutic margin, emetic, with nicotinic alkaloids to which children are especially vulnerable (nausea, vomiting, respiratory and cardiovascular effects).', 'Do not use in infants or young children; older children only under qualified professional supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); Memorial Sloan Kettering About Herbs, Lobelia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI667', 'H171', 'drug_interaction', 'Nicotine, nicotine-replacement products (patch, gum, lozenge), and tobacco', 'moderate', 'Lobeline and nicotine act on the same nicotinic receptors, giving additive nicotinic toxicity.', 'Avoid combining; use caution in tobacco users.', 'Memorial Sloan Kettering About Herbs, Lobelia (nicotine-containing products listed as a contraindication).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI668', 'H171', 'condition', 'Cardiovascular disease, hypertension, cardiac arrhythmia', 'moderate', 'Nicotinic action raises then depresses heart rate and blood pressure; overdose can cause tachycardia followed by bradycardia and hypotension.', 'Use caution in heart disease, hypertension, and arrhythmia.', 'Memorial Sloan Kettering About Herbs, Lobelia; ScienceDirect, Lobelia inflata overview (lobeline cardiovascular effects).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI669', 'H171', 'other', 'Overdose / narrow therapeutic index', 'absolute', 'Excess causes nausea and violent emesis, sweating, tremor, tachycardia then bradycardia, hypotension, respiratory depression, seizures, and coma. Toxicity reported from roughly 50 mg of dried herb, 1 mL of tincture, or 8 mg of pure lobeline in sensitive individuals.', 'Practitioner-dosed only; begin low and titrate to first nausea; do not dose-stack; seek emergency care for overdose signs.', 'ScienceDirect, Lobelia inflata overview (toxic doses and clinical signs); AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI670', 'H171', 'condition', 'Acute or severe asthma attack', 'moderate', 'Lobelia is not an established rescue therapy; relying on it during an acute attack risks dangerous delay of effective medical care.', 'Do not use to self-treat an acute or severe asthma attack; seek urgent medical care.', 'Memorial Sloan Kettering About Herbs, Lobelia (not established as effective for asthma); general clinical practice.');
