INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS18', 'Primary', 'Relaxes the tight, tense, painful chest and the closed, non-sweating skin of a fever.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS12', 'Primary', 'Antispasmodic for the constricted, spasmodic, tight cough and bronchi.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS06', 'Primary', 'Cools and settles inflamed pleura and serous membranes (pleurisy, pneumonia).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS05', 'Secondary', 'Cooling diaphoresis vents febrile heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS03', 'Secondary', 'Coaxes hot, dry serous and bronchial membranes to moisten and secrete.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS15', 'Secondary', 'Acute febrile respiratory infection, influenza.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS08', 'Minor', 'Loosens retained, hard-to-raise bronchial secretion as expectoration begins.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS17', 'Primary', 'Cool herb deepens chilled, cold, low-vitality states.');
