INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H172', 'TS01', 'Minor', 'Depleted, feeble patients: large or repeated doses can nauseate and drain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H172', 'SY07', 'Primary', 'Respiratory: relaxing diaphoretic and expectorant for pleurisy, pneumonia, bronchitis.');
