INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H172', 'A03', 'Minor', 'Mild systemic relaxant easing nervous, tense acute states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H172', 'A33', 'Minor', 'Eases a harsh, painful cough through relaxation as secretion frees up.');
