INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H172', 'TCM13', 'Primary', 'Wind-Cold invasion: the cool herb is unsuited to chilled exterior patterns.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "locator": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H172', 'TCM10', 'Secondary', 'Cold Dampness or Cold Phlegm of the Lung: cool, moist nature aggravates boggy cold congestion.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "locator": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI671', 'H172', 'pregnancy', 'Pregnancy (medicinal doses of the root)', 'absolute', 'Uterine-stimulant (uterotonic) activity in animal studies, plus emetic action and possible estrogenic activity; AHPA Safety Class 2b.', 'Do not use medicinally at any stage of pregnancy. Choose safer, better-studied diaphoretics and expectorants.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Asclepias tuberosa (Safety Class 2b); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI672', 'H172', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on milk excretion or infant safety; cardioactive pregnane/cardenolide constituents and emetic potential warrant precaution.', 'Avoid, or use only under qualified supervision, while nursing.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); Herbal Reality clinical monograph (use during breastfeeding only under practitioner guidance).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI673', 'H172', 'pediatric', 'Children (self-treatment)', 'moderate', 'No pediatric safety data; the root is emetic in excess and carries cardioactive constituents, and a child''s febrile chest illness may need medical assessment.', 'Avoid unsupervised use in children; refer a febrile chest illness in a young child for evaluation.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); general precaution per Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI674', 'H172', 'drug_interaction', 'Cardiac glycosides (digoxin, digitoxin) and other cardioactive agents', 'moderate', 'Cardioactive pregnane glycosides (and cardenolides reported by some analyses) may add to or potentiate cardiac glycoside effects and toxicity; potassium-depleting diuretics compound the risk.', 'Avoid concurrent use with cardiac glycosides; use caution with other cardioactive drugs and in patients with arrhythmia. Note AHPA assigns Interaction Class A, but mechanism-based caution is advised.', 'Brinker, Herb Contraindications and Drug Interactions; Herbal Reality clinical monograph; AHPA Botanical Safety Handbook, 2nd ed. (2013, Interaction Class A).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI675', 'H172', 'condition', 'Peptic ulcer, hiatus hernia, reflux, esophageal varices', 'moderate', 'The acrid root is irritant and emetic in excess, which can aggravate an already irritated or fragile upper GI tract.', 'Use cautiously and at low, food-buffered doses, if at all, in active peptic ulcer, hiatus hernia, reflux, or esophageal varices; discontinue if nausea or upper-GI symptoms appear.', 'Herbal Reality clinical monograph (Asclepias tuberosa); Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI676', 'H172', 'condition', 'Overdose / excessive dosing', 'moderate', 'Large doses are emetic and purgative (nausea, vomiting, diarrhea), and the cardioactive constituents raise a theoretical cardiotoxicity concern at high intake.', 'Keep strictly to recommended doses; discontinue and seek care if vomiting, diarrhea, palpitations, or faintness occur.', 'King''s American Dispensatory (Felter and Lloyd, 1898); AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H172', 'EP01', 'match', 3, 0, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898): Asclepias (Asclepias tuberosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "locator": "Grieve''s A Modern Herbal (1931): Pleurisy Root / Asclepias tuberosa; American Herbal Products Association Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013): Asclepias tuberosa (Safety Class 2b, Interaction Class A); Brinker, H", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
