INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H173', 'TCM03', 'Secondary', 'Burdens a deficient-cold Spleen with dampness and cold diarrhea.', '{"title": "Shennong Ben Cao Jing (Han dynasty) - Shao Yao (Paeonia). Note that the earliest classic listed a single Shao Yao; the white (peeled) and red (unpeeled) peony distinction was formalized later, by Tao Hongjing and the Song materia medica. Co", "locator": "Shennong Ben Cao Jing (Han dynasty) - Shao Yao (Paeonia). Note that the earliest classic listed a single Shao Yao; the white (peeled) and red (unpeeled) peony distinction was formalized later, by Tao Hongjing and the Song materia medica. Co", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Bai Shao / Radix Paeoniae Alba); Chen and Chen, Chinese Medical Herbology and Pharmacology (Bai Shao); Herbal Reality practitioner monograph (Bai Shao); AHPA Botan", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Bai Shao / Radix Paeoniae Alba); Chen and Chen, Chinese Medical Herbology and Pharmacology (Bai Shao); Herbal Reality practitioner monograph (Bai Shao); AHPA Botan", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI677', 'H173', 'pregnancy', 'Pregnancy (unsupervised self-use)', 'moderate', 'Acts on the female reproductive system; Western practitioner sources advise avoidance, while Chinese medicine uses it in supervised pregnancy formulas. Robust modern human safety data are lacking and guidance conflicts.', 'Do not self-administer in pregnancy; use only under a qualified herbalist or physician.', 'Herbal Reality (Bai Shao); AHPA Botanical Safety Handbook, 2nd ed. (confirm class at merge); Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI678', 'H173', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation studies and no data on transfer into breast milk; Western sources advise avoidance during lactation.', 'Use only under professional supervision while breastfeeding; prefer a better-documented remedy.', 'Herbal Reality (Bai Shao); absence of lactation data (precautionary).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI679', 'H173', 'pediatric', 'Young children', 'moderate', 'No modern pediatric safety data for isolated white peony.', 'Avoid unsupervised use in young children; give only under professional guidance.', 'Absence of pediatric data (precautionary practice); Bensky, Clavey and Stoger, Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI680', 'H173', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Paeoniflorin and paeonol have documented platelet-anti-aggregatory and mild anticoagulant activity, giving a theoretical additive bleeding risk.', 'Combine only with caution and monitoring; watch for bruising or bleeding and hold before surgery.', 'Herbal Reality (Bai Shao); antiplatelet studies of paeoniflorin/paeonol (PMC6834133); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI681', 'H173', 'drug_interaction', 'Antidiabetic (hypoglycemic) drugs', 'low', 'Paeoniflorin shows anti-hyperglycemic activity, giving a plausible additive blood-sugar-lowering effect.', 'Monitor blood glucose when combining with insulin or oral antidiabetics.', 'Pharmacological reviews of paeoniflorin; Mills and Bone interaction principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI682', 'H173', 'drug_interaction', 'Immunosuppressant therapy', 'low', 'Total glucosides of paeony are immunomodulatory (used in autoimmune disease) and could theoretically interact with immunosuppression.', 'Use only under supervision in transplant or autoimmune patients on immunosuppressants.', 'Clinical literature on total glucosides of paeony (rheumatoid arthritis); Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI683', 'H173', 'condition', 'Deficient-cold digestion / yang deficiency with cold diarrhea', 'low', 'Cool, sour, moist qualities can chill and burden a weak-yang, cold-damp Spleen and worsen deficient-cold diarrhea.', 'Combine with warming, tonifying herbs where the picture is cold and deficient rather than hot and tense, or avoid.', 'Herbal Reality (Bai Shao); Bensky, Clavey and Stoger, Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI684', 'H173', 'other', 'Veratrum (li lu)', 'moderate', 'Traditional eighteen incompatibilities of Chinese medicine list peony as antagonistic to Veratrum.', 'Do not combine white peony with li lu (Veratrum).', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (eighteen incompatibilities).');
