INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H174', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H174', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS24', 'Primary', 'Scrofulous/lymphatic stagnation: swollen, boggy glands and cervical nodes, the core indication.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS08', 'Primary', 'Stagnation: moves congested, sluggish lymphatic and glandular tissue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS15', 'Primary', 'Acute infection: septic, putrid states with tissue breakdown (Eclectic signature).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS25', 'Primary', 'Ulceration: fetid ulcerated throat, mouth, gums, and putrid skin ulcers.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS14', 'Secondary', 'Chronic infection: recurrent low-grade and lingering septic conditions.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS05', 'Secondary', 'Excess heat: low, foul, septic and typhoid febrile heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS06', 'Secondary', 'Acute inflammation: hot, inflamed, infected glandular and mucosal tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS17', 'Primary', 'Cold: a cooling, mildly toxic alterative is wrong for the cold constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS01', 'Primary', 'Deficiency: not a tonic; a small-dose acute antiseptic, not for the frankly depleted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS03', 'Secondary', 'Dryness: a bitter, drying antiseptic worsens fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H174', 'TS04', 'Secondary', 'Exhaustion: an emetic, draining herb further burdens the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY11', 'Primary', 'Lymphatic: swollen glands, tonsillar and cervical node congestion, scrofula.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY05', 'Primary', 'Immune: antiseptic and immune-stimulating action for septic and infective states.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY07', 'Secondary', 'Respiratory/throat: ulcerated sore throat, tonsillitis, pharyngitis, URIs.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY08', 'Secondary', 'Digestive/mouth: ulcerated foul mucosa, mouth ulcers, typhoid enteric involvement.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY10', 'Secondary', 'Skin: boils, abscesses, and putrid, non-healing ulcers (topical and internal).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H174', 'SY12', 'Minor', 'Hepatic: mild hepatic stimulant and cholagogue (King''s).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A14', 'Primary', 'Alterative: clears septic, putrid, glandular toxicity from blood and lymph.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A28', 'Primary', 'Antimicrobial/antiseptic: the defining Eclectic action against putrid infection.');
