INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A04', 'Primary', 'Immunomodulator: immunostimulating polysaccharides and glycoproteins (Esberitox fraction).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A09', 'Secondary', 'Anti-inflammatory: cools hot, inflamed, infected glandular and mucosal tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A29', 'Secondary', 'Antibacterial: against the septic bacterial load of putrid states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A49', 'Secondary', 'Febrifuge: addresses septic and typhoid (adynamic) fever.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A24', 'Secondary', 'Vulnerary: topically for putrid ulcers, boils, and foul wounds.');
