INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A43', 'Minor', 'Cholagogue: mild hepatic and biliary stimulation (King''s hepatic stimulant).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H174', 'A38', 'Minor', 'Laxative: small doses are gently laxative (large doses emeto-cathartic).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H174', 'CP52', 'Primary', 'Ulcerated, fetid, septic sore throat and tonsillitis, the classic indication.');
