INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H174', 'TCM07', 'Secondary', 'Yin deficiency: a bitter, drying antiseptic injures the fluids.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Baptisia (Wild Indigo): an antiseptic to septic, ulcerative, and typhoid (adynamic) states, with specific indications of fullness of tissue with dusky, leaden, purplish, or livid discol", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Baptisia (Wild Indigo): an antiseptic to septic, ulcerative, and typhoid (adynamic) states, with specific indications of fullness of tissue with dusky, leaden, purplish, or livid discol", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; Southern Cross University Medicinal Plant Monograph, Baptisia tinctoria; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and D", "locator": "Mills and Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; Southern Cross University Medicinal Plant Monograph, Baptisia tinctoria; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and D", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H174', 'TCM13', 'Minor', 'Wind-Cold: a cooling herb is unsuited to a cold exterior pattern.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Baptisia (Wild Indigo): an antiseptic to septic, ulcerative, and typhoid (adynamic) states, with specific indications of fullness of tissue with dusky, leaden, purplish, or livid discol", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Baptisia (Wild Indigo): an antiseptic to septic, ulcerative, and typhoid (adynamic) states, with specific indications of fullness of tissue with dusky, leaden, purplish, or livid discol", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; Southern Cross University Medicinal Plant Monograph, Baptisia tinctoria; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and D", "locator": "Mills and Bone, Principles and Practice of Phytotherapy; Hoffmann, Medical Herbalism; Southern Cross University Medicinal Plant Monograph, Baptisia tinctoria; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and D", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI685', 'H174', 'pregnancy', 'Pregnancy', 'absolute', 'Baptisia root contains teratogenic and toxic quinolizidine alkaloids, notably anagyrine (the lupine ''crooked calf'' teratogen) and cytisine (a toxic nicotinic agonist); the herb is also emeto-cathartic in more than small doses and carries a traditional tissue-stimulating, emmenagogue reputation.', 'Do not use during pregnancy in any form or dose.', 'WebMD/RxList Wild Indigo safety (unsafe, avoid); AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; EFSA Scientific Opinion on quinolizidine alkaloids (EFSA Journal 2019).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI686', 'H174', 'breastfeeding', 'Breastfeeding', 'moderate', 'Toxic quinolizidine alkaloids (cytisine, anagyrine) may pass into breast milk, and there are no adequate human safety data for Wild Indigo during lactation; the herb is also emetic in excess.', 'Avoid while breastfeeding; prefer better-studied lymphatic and immune herbs.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, Principles and Practice of Phytotherapy; WebMD/RxList Wild Indigo safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI687', 'H174', 'pediatric', 'Infants and young children', 'moderate', 'The root''s quinolizidine alkaloids are toxic and the herb is emeto-cathartic in more than small amounts, making overdose easy in a child; no adequate pediatric safety data.', 'Not for infants or long-term use; older children only under qualified supervision at low, short-course doses.', 'Mills and Bone, Principles and Practice of Phytotherapy; WebMD/RxList Wild Indigo safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI688', 'H174', 'other', 'Large or prolonged doses', 'moderate', 'In more than small therapeutic amounts the root is emeto-cathartic (nausea, vomiting, salivation, diarrhea, gastroenteritis); cytisine is a nicotinic-receptor agonist, and large overdoses can cause the nicotinic quinolizidine-poisoning picture (headache, vertigo, weakness, cramps, and in extreme excess convulsions and respiratory depression).', 'Use only small doses for short courses; do not use as a long-term tonic. Stop for nausea, vomiting, or diarrhea.', 'WebMD/RxList Wild Indigo safety; EFSA Scientific Opinion on quinolizidine alkaloids (EFSA Journal 2019); King''s American Dispensatory (Felter and Lloyd, 1898) for the historical dose-toxicity note.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI689', 'H174', 'condition', 'Autoimmune disease and organ transplantation', 'moderate', 'Wild Indigo contains immune-stimulating polysaccharides and glycoproteins that may theoretically aggravate autoimmune activity or oppose the intended effect of immunosuppressive therapy, by analogy to other immunostimulant herbs.', 'Avoid in active autoimmune disease and in transplant recipients on immunosuppressants unless supervised by a qualified practitioner.', 'NCCIH consumer information (immunostimulant-herb caution); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI690', 'H174', 'drug_interaction', 'Immunosuppressant drugs (cyclosporine, tacrolimus, corticosteroids)', 'moderate', 'The immune-stimulating fraction may theoretically counter immunosuppression, reducing the effectiveness of these drugs.', 'Avoid concurrent use in patients dependent on immunosuppressive therapy without professional supervision.', 'NCCIH consumer information; Brinker, Herbal Contraindications and Drug Interactions.');
