INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H175', 'TCM11', 'Secondary', 'Heat/Fire: a warm herb aggravates heat and heat-type bleeding.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ju You / Ju Pi (tangerine, the peel of Citrus reticulata), among the fruit-peel remedies for the middle burner.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ju You / Ju Pi (tangerine, the peel of Citrus reticulata), among the fruit-peel remedies for the middle burner.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Chen Pi (Pericarpium Citri Reticulatae); Chen and Chen, Chinese Medical Herbology and Pharmacology, Chen Pi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, He", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Chen Pi (Pericarpium Citri Reticulatae); Chen and Chen, Chinese Medical Herbology and Pharmacology, Chen Pi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, He", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H175', 'TCM06', 'Minor', 'Blood deficiency: a drying, dispersing herb is unsuited to frank dryness/depletion without stagnation.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ju You / Ju Pi (tangerine, the peel of Citrus reticulata), among the fruit-peel remedies for the middle burner.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ju You / Ju Pi (tangerine, the peel of Citrus reticulata), among the fruit-peel remedies for the middle burner.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Chen Pi (Pericarpium Citri Reticulatae); Chen and Chen, Chinese Medical Herbology and Pharmacology, Chen Pi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, He", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Chen Pi (Pericarpium Citri Reticulatae); Chen and Chen, Chinese Medical Herbology and Pharmacology, Chen Pi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, He", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI691', 'H175', 'condition', 'Yin deficiency with dry cough, internal heat/empty fire, and frank dryness', 'moderate', 'Chen Pi is warm, aromatic, and drying; in dry, heat, or fluid-deficient patterns it injures Yin fluids and worsens a dry, unproductive cough and empty heat.', 'Avoid as a solo remedy in yin-deficient dry cough and heat patterns; if needed, use in small amounts paired with moistening, Yin-nourishing herbs.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI692', 'H175', 'drug_interaction', 'Narrow-therapeutic-index CYP3A4 and P-glycoprotein substrates (e.g. ciclosporin, tacrolimus, some statins)', 'moderate', 'Citrus peel constituents modulate CYP3A4 and P-glycoprotein in both directions (PXR-mediated induction by peel extracts; CYP3A4 inhibition by hesperidin and P-gp inhibition by nobiletin/tangeretin), so high herbal doses could alter substrate drug levels. Evidence is largely in vitro/theoretical; sweet tangerine peel is low in the furanocoumarins that drive the grapefruit interaction.', 'Separate high herbal doses in time from narrow-index CYP3A4/P-gp substrates and monitor; food and modest therapeutic amounts are unlikely to matter.', 'Brinker, Herbal Contraindications and Drug Interactions; Kim et al., Front Pharmacol 2017 (PMC5318391); flavonoid and furanocoumarin drug-interaction review (PMC12029527).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI693', 'H175', 'drug_interaction', 'Stimulants and monoamine-oxidase inhibitors (high-dose)', 'low', 'Chen Pi contains a small amount of synephrine (far less than bitter orange, Citrus aurantium), a mild sympathomimetic; a theoretical additive stimulant effect could arise at high doses.', 'Avoid megadoses of the peel with stimulants or MAO inhibitors; culinary and modest therapeutic amounts pose little risk. Do not confuse Chen Pi with the more synephrine-rich bitter-orange peel (Zhi Shi/Zhi Ke).', 'Brinker, Herbal Contraindications and Drug Interactions (synephrine content of Citrus species).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI694', 'H175', 'pregnancy', 'Pregnancy (high or prolonged qi-moving doses)', 'moderate', 'Chen Pi is a mild, food-grade qi-regulator, used under supervision in classical formulas to ease the nausea of pregnancy, but it is warm, drying, and qi-moving, so high or prolonged dosing is not advisable.', 'Culinary and low therapeutic amounts are generally considered safe; avoid high or prolonged qi-moving doses and use therapeutic amounts under professional supervision.', 'AHPA Botanical Safety Handbook (2nd ed.), Citrus reticulata pericarp; Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica.');
