INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H176', 'Coptis / Goldthread (Huang Lian)', 'Coptis chinensis', 'Ranunculaceae (buttercup family)', 'Dried rhizome (Rhizoma Coptidis; Huang Lian), the knotted, bright-yellow rootstock', 'Bitter (the most intensely bitter herb in the Chinese materia medica, from berberine and related isoquinoline alkaloids).', 'Cold', 'Dry', 'Damp-heat of the middle burner: hot, foul, urgent, often bloody dysenteric diarrhea and damp-heat of the gut. Blazing Stomach fire with burning epigastric pain, sour regurgitation, and heat-driven vomiting or excessive hunger. Heart fire that scorches the mind, with restlessness, irritability, insomnia, and red, sore ulceration of the mouth and tongue. High fever with delirium, hot boils and carbuncles, and red, hot, infected, suppurating tissue where heat and toxin combine. Damp-heat eruptions of the skin and hot, red, inflamed eyes and ears.', 'Cold, weak, deficient digestion, since the bitterest of cold herbs quenches an already low digestive fire and loosens the stool. Frank dryness and fluid depletion, which a drying bitter deepens. Constitutional weakness and cold exhaustion without a true damp-heat or fire excess to clear. Because it drains and cools more forcefully than almost any herb, it is wrong wherever the picture is cold, empty, or dry rather than hot and damp.', 'Digestive and Stomach above all, the seat of its fire-draining and damp-heat clearing: stomach, intestines, and the dysenteric gut. Nervous and Cardiovascular (the TCM Heart): heat-driven restlessness, insomnia, and delirium. Hepatic and gallbladder (Liver and Gallbladder fire, damp-heat jaundice). Integumentary (skin) for damp-heat sores and eruptions. Immune, for heat-toxin infection and suppuration. Secondary Spleen involvement in middle-burner damp.', 'Damp-heat dysentery and diarrhea (the premier herb for hot, urgent, bloody, foul stool). Stomach fire: burning epigastric pain, acid regurgitation and reflux, heat-driven nausea and vomiting, mouth and tongue ulcers, and foul breath. Heart fire: restlessness, irritability, anxiety, and insomnia, and high fever with delirium (heat entering the pericardium). Heat-toxin: boils, carbuncles, hot abscesses, and damp-heat skin eruptions (internal and topical). Red, hot, inflamed eyes and ears (topical wash). Also studied for blood-sugar dysregulation on the strength of its berberine.', 'Hot-Damp-Excess: the robust, ruddy, hot-running phenotype with damp-heat of the gut, a fiery stomach, and a restless, overheated mind, prone to burning digestion, acid reflux, mouth sores, and hot eruptions. Emphatically not for the pale, cold, loose-bowelled, weak (Vata- or yang-deficient) constitution, whom the bitterest cold in the pharmacy only chills and dries.', 'Pitta, Kapha', 'Vata', 'Damp-Heat, especially of the Stomach and Intestines: damp-heat dysentery and diarrhea, the herb''s signature. Blazing Fire and Heat-toxin: high fever, irritability, delirium, hot sores and carbuncles (as in Huang Lian Jie Du Tang, which drains fire toxin from all three burners). Stomach fire and Liver-Stomach disharmony with acid reflux and vomiting (Zuo Jin Wan, Coptis with Evodia). Heart fire blazing with restlessness and insomnia, and Heart and Kidney failing to communicate (Huang Lian E Jiao Tang). One of the ''three yellows'' (San Huang) with Huang Qin (Scutellaria, upper burner) and Huang Bai (Phellodendron, lower burner); Huang Lian is the middle-burner member and the strongest at clearing Heart and Stomach fire.', 'Spleen and Stomach deficiency-cold with poor appetite and loose stools, which the bitter-cold rhizome worsens by quenching the digestive fire. Yang deficiency and cold-from-deficiency, where a fire-draining cold is precisely wrong. Yin and fluid deficiency without genuine damp-heat, since sustained bitter-dryness injures the fluids. It must not be used long-term or in high dose, because prolonged bitter-cold damages the Spleen and Stomach yang.', 'The most intensely bitter and one of the coldest herbs in the materia medica. Even short courses can chill and slow digestion, and prolonged or high-dose use damages the Spleen and Stomach, causing poor appetite, loose stools, and cold in the belly, so it is best paired with warming, digestive-protective herbs or reserved for genuine damp-heat and fire. The berberine-type alkaloids can provoke gastrointestinal upset. In anyone with glucose-6-phosphate dehydrogenase (G6PD) deficiency, berberine can precipitate hemolysis and must be avoided, and it must not be given to newborns because of the risk of kernicterus. Berberine also carries meaningful drug-interaction potential (see Drug Interactions).', 'Pregnancy and lactation (berberine risk; see safety fields). Neonates and infants, especially with jaundice or G6PD deficiency (kernicterus and hemolysis risk). Spleen and Stomach deficiency-cold and yang deficiency (TCM). Known G6PD deficiency. Concurrent cyclosporine, tacrolimus, and other narrow-therapeutic-index CYP3A4 or P-glycoprotein substrates without professional supervision.', 'Avoid. Coptis (Rhizoma Coptidis) is one of the richest berberine sources in the materia medica (roughly 5 to 10 percent berberine), and berberine crosses the placenta and displaces bilirubin from serum albumin; in the fetus and newborn this raises the risk of jaundice and kernicterus (bilirubin brain injury). The hazard was serious enough that Rhizoma Coptidis and berberine were banned in Singapore from 1978, a prohibition prompted by neonatal jaundice in G6PD-deficient infants and not lifted until 2016. Berberine is also reported to stimulate uterine contraction. Modern references (AHPA Botanical Safety Handbook, 2nd ed., which classes berberine-containing herbs as not for use in pregnancy; Mills and Bone, Principles and Practice of Phytotherapy; Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica; Brinker, Herbal Contraindications and Drug Interactions) advise against use in pregnancy. There is no safe dose that justifies the fetal risk.', 'Avoid. Berberine passes into breast milk, and the nursing newborn, whose blood-brain barrier and bilirubin conjugation are immature, can suffer displaced bilirubin, jaundice, and kernicterus, a risk that is greatest in infants with G6PD deficiency. Chen and Chen, Bensky, Clavey and Stoger, and the AHPA Botanical Safety Handbook advise against maternal use of berberine-containing herbs while breastfeeding a newborn. Prefer better-studied, non-alkaloidal alternatives during lactation.', 'Not for newborns or infants; for older children only under professional supervision. Berberine is specifically hazardous to neonates and jaundiced infants because it displaces bilirubin and can cause kernicterus, and it can trigger hemolysis in children with G6PD deficiency; historically, Coptis given to newborns was tied to neonatal jaundice, the basis of the Singapore ban. In older children the intense bitter-cold readily chills digestion and causes loose stools. Reserve any pediatric use to a qualified practitioner at low, short-course, damp-heat-specific doses.', 'Driven by berberine and the related protoberberine alkaloids, in which Coptis is especially rich. Berberine inhibits cytochrome P450 3A4 (and 2D6 and 2C9) and P-glycoprotein: a randomized clinical study in renal-transplant recipients (Wu et al., European Journal of Clinical Pharmacology, 2005) found that 0.2 g berberine three times daily significantly raised blood levels of cyclosporine A, so Coptis must not be combined with cyclosporine, and caution applies to other narrow-margin CYP3A4 or P-gp substrates (tacrolimus, many statins, some calcium-channel blockers, midazolam). Berberine lowers blood glucose and can add to insulin and oral hypoglycemics (metformin, sulfonylureas), risking hypoglycemia and requiring monitoring. It may potentiate anticoagulant and antiplatelet drugs (warfarin, clopidogrel) and additively lower blood pressure with antihypertensives. By displacing protein-bound drugs (and bilirubin) from albumin it can raise the free levels of highly protein-bound medicines. Separate dosing from other oral drugs. Evidence ranges from controlled human data (cyclosporine) to mechanistic and theoretical inference (Brinker; Chen and Chen; Mills and Bone).', 'Decoction of the dried rhizome is the standard form. Raw (unprepared) rhizome for clearing damp-heat and draining fire-toxin. Ginger-fried (jiang zhi) Coptis to temper the coldness and check heat-driven vomiting; wine-fried (jiu) Coptis to carry the action upward to the eyes and head; Evodia-processed (with Wu Zhu Yu) Coptis for Liver-Stomach heat and acid reflux (Zuo Jin Wan). Powder and capsules of the dried rhizome. Topically as a wash, eyewash, or paste for hot eyes, mouth ulcers, and damp sores. Berberine is often standardized in modern extracts.', 'Decoction: 2 to 10 g dried rhizome daily (commonly 3 to 6 g, the low doses reflecting its extreme bitterness), in divided doses. Powder or capsules: about 1 to 2 g daily. Tincture (1:5): 1 to 3 mL up to three times daily. Topical: decoction as a wash or eyewash, or the powder in a paste, for hot sores and inflamed eyes. A clearing, draining herb for damp-heat and fire, given in short courses rather than as a long-term tonic.', 'Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; Wu et al., berberine and cyclosporin A pharmacokinetics (Eur J Clin Pharmacol 2005, PMID 16133554); Chan, displacement of bilirubin from albumin by berberine (Biol Neonate 1993, PMID 8513024); Ho et al., From Prejudice to Evidence: The Case of Rhizoma Coptidis in Singapore (Evid Based Complement Alternat Med 2014); NCCIH consumer information on berberine.', 'Family Ranunculaceae. The rhizome is among the richest natural sources of isoquinoline (protoberberine) alkaloids, dominated by berberine (the yellow, intensely bitter principle, roughly 5 to 10 percent, higher than in Phellodendron or Scutellaria), with palmatine, coptisine, jatrorrhizine (jateorhizine), epiberberine, columbamine, and magnoflorine. Berberine underlies most of the pharmacology: broad antimicrobial, antibacterial, antiprotozoal (against the dysentery amoeba and Giardia), and antifungal action; anti-inflammatory and antidiarrheal (antisecretory) effects; and well-studied blood-glucose and lipid lowering. Several species supply the drug, and the Chinese Pharmacopoeia lists them together as Huang Lian: Coptis chinensis (Wei Lian, assigned here), Coptis deltoidea (Ya Lian), and Coptis teeta (Yun Lian). Classically Huang Lian is one of the ''three yellows'' (San Huang) with Huang Qin (Scutellaria) and Huang Bai (Phellodendron), and it is the middle-burner member, the strongest at draining Heart and Stomach fire. Signature formulas include Huang Lian Jie Du Tang (fire toxin of the three burners), Zuo Jin Wan (with Evodia, for Liver-Stomach heat and acid reflux), Ge Gen Huang Qin Huang Lian Tang (damp-heat diarrhea), Huang Lian E Jiao Tang (Heart-fire insomnia), and Ban Xia Xie Xin Tang (epigastric focal distention). In Japanese Kampo the herb is known as Oren.', 'Not in canonical biblical texts, and unknown to the ancient Mediterranean world; native to the mountains of central and southern China (Sichuan, Chongqing, Hubei, Shaanxi). Its documented tradition is Chinese: it entered the materia medica in the Han-era Shen Nong Ben Cao Jing as Huang Lian and was carried through every later Chinese and Japanese (Kampo, as Oren) pharmacopoeia. It should not be confused with the North American goldthread (Coptis trifolia / Coptis groenlandica), a related Ranunculaceae rhizome used by Native American and Eclectic practitioners as a bitter mouth-sore wash.', 'Harvest pressure is a real concern. The assigned Coptis chinensis is a slow-growing mountain perennial whose rhizome takes about five to six years to mature and whose wild populations in China have been all but depleted by overharvest, so that more than ninety percent of the market supply now comes from cultivation in Sichuan, Chongqing, and Hubei; prefer cultivated, traceable rhizome. Its relatives Coptis teeta (endangered in the eastern Himalaya) and the North American goldthread Coptis trifolia are of greater wild-conservation concern; goldthread (Coptis spp.) appears on the United Plant Savers ''To-Watch'' list for North American medicinal plants. Confirm the species and prefer cultivated stock.', 'Cold and drying: the bitterest, most berberine-dense rhizome in the pharmacy, draining damp-heat from the gut, quenching Heart and Stomach fire, and disinfecting hot, toxic, suppurating tissue.', 'Refer for bloody or severe dysenteric diarrhea, diarrhea with dehydration, or high or persistent fever; any newborn or infant with jaundice (do not give berberine herbs); severe or unremitting epigastric pain, vomiting of blood, or black stools (possible ulcer or bleed); confusion or delirium with fever; rapidly spreading skin infection, abscess with fever, or non-healing ulcers; and eye infection with pain or change in vision. Refer anyone who is pregnant or breastfeeding, has G6PD deficiency, or takes cyclosporine, tacrolimus, warfarin, or diabetes medication before use.', 'Coptis: KOP-tiss. Coptis chinensis: KOP-tiss chih-NEN-sis. Huang Lian: hwahng lee-EN.', 'seed', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H176', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS05', 'Primary', 'Excess heat: drains Heart and Stomach fire and clears fire-toxin.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS07', 'Primary', 'Dampness: the signature action is drying damp-heat of the gut (dysentery).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS06', 'Secondary', 'Acute inflammation: hot, red, suppurating damp-heat tissue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS15', 'Secondary', 'Acute infection: damp-heat dysentery, hot bacterial and amoebic gut infection.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS16', 'Secondary', 'Excess conditions: a forceful draining, clearing herb for genuine repletion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS25', 'Secondary', 'Ulceration: mouth and tongue ulcers, hot sores (topical and internal).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS14', 'Minor', 'Chronic infection: lingering damp-heat and low-grade suppuration.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS17', 'Primary', 'Cold: the bitterest cold quenches an already cold, weak digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS01', 'Primary', 'Deficiency: a forceful draining, cooling bitter is wrong for the frankly depleted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS03', 'Secondary', 'Dryness: a drying bitter worsens fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H176', 'TS04', 'Minor', 'Exhaustion: draining cold further depletes the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY08', 'Primary', 'Digestive/Stomach: damp-heat dysentery, Stomach fire, acid reflux, vomiting.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY01', 'Primary', 'Nervous: Heart-fire restlessness, irritability, insomnia, delirium.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY06', 'Secondary', 'Cardiovascular (TCM Heart): blazing Heart fire, palpitations of heat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY12', 'Secondary', 'Hepatic/gallbladder: Liver and Gallbladder fire, damp-heat jaundice.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY10', 'Secondary', 'Skin: damp-heat sores, boils, and hot eruptions (topical).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY05', 'Minor', 'Immune: heat-toxin abscesses and infection.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H176', 'SY13', 'Minor', 'Spleen: middle-burner damp-heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A16', 'Primary', 'Bitter tonic: the archetypal, most intense bitter, stimulating secretion (used cold).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A28', 'Primary', 'Antimicrobial: berberine''s broad antibacterial and antiprotozoal reach.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A09', 'Primary', 'Anti-inflammatory: cools hot, damp, inflamed tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A29', 'Secondary', 'Antibacterial: classic use against dysentery bacilli.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A31', 'Secondary', 'Antifungal: berberine against Candida and dermatophytes.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A49', 'Secondary', 'Febrifuge: clears high heat and febrile fire.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A14', 'Secondary', 'Alterative: clears damp-heat and toxin from gut and skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A45', 'Secondary', 'Antiemetic: clears Stomach heat and checks heat-driven vomiting (Zuo Jin Wan).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A36', 'Minor', 'Hypoglycemic: berberine lowers blood glucose.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H176', 'A25', 'Minor', 'Antioxidant: alkaloid free-radical scavenging.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP56', 'Primary', 'Damp-heat diarrhea and dysentery, the signature indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP62', 'Primary', 'Dysbiosis/parasites: berberine against dysentery bacilli, amoeba, and Giardia.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP59', 'Secondary', 'GERD/reflux: Stomach-fire acid regurgitation (Zuo Jin Wan).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP57', 'Secondary', 'Nausea and heat-driven vomiting from Stomach fire.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP04', 'Secondary', 'Insomnia from blazing Heart fire (Huang Lian E Jiao Tang).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP10', 'Secondary', 'Anxiety, restlessness, and irritability of Heart fire.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP70', 'Secondary', 'Boils, carbuncles, and hot suppurating abscesses (fire-toxin).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP18', 'Secondary', 'Damp-heat skin eruptions generally.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP09', 'Secondary', 'Chronic damp-heat infection and low-grade suppuration.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP27', 'Minor', 'Blood-sugar dysregulation: berberine''s glucose-lowering effect.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP76', 'Minor', 'Fever management in high febrile heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H176', 'CP13', 'Minor', 'Systemic inflammation underlying damp-heat and fire presentations.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H176', 'P04', 'Primary', 'Decoction of the dried rhizome, the standard form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H176', 'P03', 'Secondary', 'Powdered rhizome (raw, ginger-fried, wine-fried, or Evodia-processed).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H176', 'P02', 'Secondary', 'Capsules of the dried rhizome or standardized berberine.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H176', 'P01', 'Secondary', 'Tincture.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H176', 'P10', 'Minor', 'Wash, eyewash, or paste for hot eyes, mouth ulcers, and damp sores.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H176', 'C06', 'Indicated', 'Primary', 'Robust/Hot (Pitta-like) with damp-heat gut, stomach fire, and hot eruptions.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
