INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H176', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Huang Lian (Coptis), listed among the upper-class herbs for heat, damp, and toxic dysenteric disease.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Lian; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Lian; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Coptis; AHPA Bot", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI695', 'H176', 'pregnancy', 'Pregnancy', 'absolute', 'Coptis is berberine-rich; berberine crosses the placenta and displaces bilirubin from serum albumin, raising the fetal and neonatal risk of jaundice and kernicterus, and is reported to stimulate uterine contraction.', 'Do not use during pregnancy in any form or dose.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, Principles and Practice of Phytotherapy; Chan, displacement of bilirubin from albumin by berberine (Biol Neonate 1993, PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI696', 'H176', 'breastfeeding', 'Breastfeeding a newborn', 'absolute', 'Berberine passes into breast milk and can displace bilirubin in the newborn, whose bilirubin handling and blood-brain barrier are immature, risking jaundice and kernicterus, especially with G6PD deficiency.', 'Avoid while breastfeeding a newborn; prefer better-studied, non-alkaloidal alternatives.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI697', 'H176', 'pediatric', 'Neonates and jaundiced infants', 'absolute', 'Berberine displaces bilirubin and can precipitate kernicterus in the newborn, and can cause hemolysis in infants with G6PD deficiency. Neonatal jaundice from Rhizoma Coptidis was the basis of the 1978 Singapore ban on the herb and berberine.', 'Never give to neonates or jaundiced infants. Older children only under qualified supervision at low, short-course doses.', 'Ho et al., From Prejudice to Evidence: The Case of Rhizoma Coptidis in Singapore (Evid Based Complement Alternat Med 2014); Chan (Biol Neonate 1993, PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI698', 'H176', 'condition', 'G6PD deficiency', 'absolute', 'Berberine can precipitate hemolysis in glucose-6-phosphate dehydrogenase-deficient individuals, and neonates with G6PD deficiency are at particular risk of hemolytic jaundice.', 'Avoid Coptis and other berberine-containing herbs in anyone with known or suspected G6PD deficiency.', 'Wong et al., Berberine-induced Haemolysis Revisited: Safety of Rhizoma coptidis and Cortex phellodendri (Phytother Res 2012).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI699', 'H176', 'drug_interaction', 'Cyclosporine (ciclosporin A) and tacrolimus', 'moderate', 'Berberine inhibits CYP3A4 and P-glycoprotein; a randomized clinical study showed berberine significantly raised cyclosporine blood levels, risking toxicity of these narrow-index immunosuppressants.', 'Do not combine with cyclosporine or tacrolimus without specialist supervision and drug-level monitoring.', 'Wu et al., Eur J Clin Pharmacol 2005 (PMID 16133554); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI700', 'H176', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Berberine lowers blood glucose and can add to the glucose-lowering effect of diabetes medication, risking hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined; watch for hypoglycemia.', 'NCCIH consumer information on berberine; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI701', 'H176', 'drug_interaction', 'CYP3A4 and P-glycoprotein substrates (statins, midazolam, some calcium-channel blockers)', 'moderate', 'Berberine inhibits CYP3A4/2D6 and P-gp, potentially raising levels of co-administered substrate drugs.', 'Use caution and separate dosing; avoid with narrow-margin substrates without supervision.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI702', 'H176', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, clopidogrel)', 'moderate', 'Berberine may potentiate anticoagulant and antiplatelet effect and can displace protein-bound drugs from albumin.', 'Avoid concurrent therapeutic use without professional supervision and coagulation monitoring.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI703', 'H176', 'condition', 'Spleen/Stomach deficiency-cold and yang deficiency (TCM)', 'moderate', 'The intensely bitter-cold rhizome quenches an already weak digestive fire and cold constitution, worsening poor appetite, loose stools, and cold in the abdomen.', 'Avoid in cold-deficient digestive and yang-deficient patterns; if used, combine with warming, protective herbs and limit duration.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
