INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H177', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS05', 'Primary', 'Excess heat: clears heat and drains fire, including Heart fire.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS15', 'Primary', 'Acute infection: wind-heat and early warm-febrile disease, hot sores.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS06', 'Primary', 'Acute inflammation: hot, red, swollen throat, carbuncles, and abscesses.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS24', 'Secondary', 'Scrofulous/lymphatic swellings: dissolves phlegm-heat nodules and scrofula.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS16', 'Secondary', 'Excess conditions: a clearing, draining herb for genuine heat-toxin repletion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS23', 'Minor', 'Phlegm: softens firm phlegm-heat nodules and lumps.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS25', 'Minor', 'Ulceration: hot carbuncles, boils, and ulcerated skin sores.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS14', 'Minor', 'Chronic infection: lingering heat-toxin and unresolved suppuration.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS17', 'Primary', 'Cold: bitter-cold fruit worsens a cold, weak digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS01', 'Primary', 'Deficiency: a draining, cooling bitter is wrong for the frankly depleted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS03', 'Secondary', 'Dryness: a cold, drying bitter deepens yin and fluid deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H177', 'TS04', 'Minor', 'Exhaustion: draining cold further depletes the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY07', 'Primary', 'Respiratory: wind-heat, warm-disease onset, sore throat, cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY05', 'Primary', 'Immune: heat-toxin infection; broad antimicrobial/antiviral reach.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY11', 'Primary', 'Lymphatic: dissolves scrofula, phlegm-heat nodules, and swollen glands.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY14', 'Secondary', 'Lungs: the Lung channel; venting wind-heat and clearing Lung heat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY10', 'Secondary', 'Skin: hot carbuncles, boils, abscesses, and heat eruptions.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY09', 'Secondary', 'Urinary: drains heat downward, easing hot, scanty urination.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H177', 'SY01', 'Minor', 'Nervous/Heart: restlessness and irritability of interior heat (lian qiao xin).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A28', 'Primary', 'Antimicrobial: broad action of forsythiaside and related glycosides.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A49', 'Primary', 'Febrifuge/antipyretic: clears heat and reduces fever.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A09', 'Primary', 'Anti-inflammatory: cools hot, swollen, inflamed tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A30', 'Secondary', 'Antiviral: key constituent of studied anti-influenza formulas.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A29', 'Secondary', 'Antibacterial: classic use against heat-toxin infection and sores.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A21', 'Secondary', 'Lymphagogue: dissolves scrofula and phlegm-heat nodules.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A14', 'Secondary', 'Alterative: clears heat-toxin from blood, skin, and lymph.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A25', 'Minor', 'Antioxidant: phenylethanoid glycoside free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A08', 'Minor', 'Diuretic: guides heat out through the urine.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H177', 'A18', 'Minor', 'Diaphoretic: helps vent wind-heat at the exterior (with honeysuckle).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP41', 'Primary', 'Cold/flu onset of the wind-heat type (Yin Qiao San).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP52', 'Primary', 'Sore, hot, swollen throat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP76', 'Primary', 'Fever management in warm-febrile illness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP70', 'Primary', 'Boils, abscesses, carbuncles, and breast abscess (mastitis).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP71', 'Secondary', 'Lymphatic congestion: scrofula, swollen glands, phlegm-heat nodules.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP17', 'Secondary', 'Respiratory infection generally (wind-heat, cough).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP18', 'Secondary', 'Hot, toxic skin conditions and eruptions.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP09', 'Secondary', 'Chronic or lingering heat-toxin infection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP13', 'Minor', 'Systemic inflammation underlying heat presentations.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H177', 'CP63', 'Minor', 'Hot, scanty, painful urination (heat drained via urine).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H177', 'P04', 'Primary', 'Decoction of the dried fruit, the standard form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H177', 'P01', 'Secondary', 'Tincture of the fruit.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H177', 'P03', 'Secondary', 'Powdered fruit.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H177', 'P05', 'Secondary', 'Brief infusion/light decoction for exterior wind-heat (added near the end).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H177', 'P02', 'Minor', 'Capsules of the dried fruit.');
