INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H177', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Lian Qiao (Forsythia), among the heat-clearing, toxin-relieving herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Lian Qiao (Forsythia), among the heat-clearing, toxin-relieving herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Lian Qiao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Lian Qiao; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Forsythia; AHPA Bo", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Lian Qiao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Lian Qiao; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Forsythia; AHPA Bo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI704', 'H177', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional emmenagogue and uterine-stimulant reputation; AHPA assigns Forsythia fruit a pregnancy-restriction class (historically 2B, not for use in pregnancy), and modern human safety data are lacking.', 'Avoid during pregnancy in all forms and doses.', 'AHPA Botanical Safety Handbook (McGuffin et al.); Natural Medicines / WebMD forsythia monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI705', 'H177', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation safety data for Forsythia fruit.', 'Avoid while breastfeeding for want of data; prefer better-studied, gentler alternatives.', 'Natural Medicines / WebMD forsythia monograph; AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI706', 'H177', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, NSAIDs)', 'moderate', 'Forsythia may slow blood clotting (antiplatelet effect), which can add to anticoagulant/antiplatelet drugs and increase bruising and bleeding risk.', 'Use caution or avoid with these drugs; discontinue at least two weeks before scheduled surgery; monitor for bleeding.', 'Natural Medicines Comprehensive Database (WebMD/RxList) forsythia monograph; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI707', 'H177', 'condition', 'Spleen/Stomach deficiency-cold with chronic diarrhea', 'moderate', 'The bitter, cold fruit quenches a weak digestive fire and loosens the stool.', 'Avoid in cold, deficient digestion with loose stools; if used, combine with warming, protective herbs and limit duration.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology; Acupuncture Today forsythia monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI708', 'H177', 'condition', 'Yin deficiency with heat in the blood', 'moderate', 'A cold, draining bitter injures already deficient fluids and does not address deficiency-type heat.', 'Avoid as a sole or prolonged remedy in yin-deficient heat; use fluid-nourishing herbs instead or in combination.', 'Bensky, Clavey and Stoger, Materia Medica; Acupuncture Today forsythia monograph.');
