INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H178', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhi Zi (Gardenia), listed among the herbs for heat, irritability, jaundice, and hot sores.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhi Zi (Gardenia), listed among the herbs for heat, irritability, jaundice, and hot sores.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Zhi Zi; Chen and Chen, Chinese Medical Herbology and Pharmacology, Zhi Zi; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Gardenia; AHPA Botanical", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Zhi Zi; Chen and Chen, Chinese Medical Herbology and Pharmacology, Zhi Zi; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Gardenia; AHPA Botanical", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI709', 'H178', 'pregnancy', 'Pregnancy', 'moderate', 'Bitter, cold, fire-draining and blood-cooling herb that can chill the Spleen and injure the Blood, both readily depleted in pregnancy; its constituents geniposide and genipin are also dose-dependently hepatotoxic at high doses.', 'Avoid for self-care. Use only short-course, low-dose within a practitioner-prescribed formula for a genuine acute heat pattern; avoid routine or prolonged use.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI710', 'H178', 'breastfeeding', 'Breastfeeding', 'moderate', 'Limited data on transfer of Zhi Zi constituents into breast milk; its cold nature may disturb an infant''s digestion, and prolonged or high-dose maternal use raises hepatotoxicity concern.', 'Avoid prolonged or high-dose use while nursing; only short low-dose courses under professional supervision. Prefer gentler alternatives.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI711', 'H178', 'condition', 'High-dose or prolonged use; pre-existing liver disease', 'moderate', 'Geniposide and its aglycone genipin are dose- and time-dependently hepatotoxic in animal studies (genipin LD50 about 510 mg/kg in mice; hepatotoxic at 125 to 500 mg/kg; reversible on withdrawal); customary therapeutic doses have not shown hepatotoxicity.', 'Keep to customary doses and short courses; avoid large or prolonged dosing, especially in liver disease; monitor liver function if extended use is needed.', 'Genipin acute and subacute hepatotoxicity in mice (Heliyon 2023, PMID 38027867); Yamano et al., potential hepatotoxicity of geniposide (Food Chem Toxicol 1990).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI712', 'H178', 'drug_interaction', 'Hepatotoxic and narrow-margin liver-metabolized drugs (acetaminophen, statins, isoniazid, methotrexate)', 'moderate', 'Geniposide and genipin modulate hepatic CYP450 and UDP-glucuronosyltransferase and are hepatotoxic at high dose, risking additive liver stress; a rat study showed the Gardenia jasminoides and simvastatin interaction varied with liver-disease status.', 'Use caution and separate dosing; avoid high-dose or prolonged combination without supervision and liver-function monitoring.', 'Chin et al., disease-status-dependent Gardenia jasminoides and simvastatin interaction (2021, PMC8103205); geniposide CYP450/glutathione S-transferase modulation (PMID 9463529); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI713', 'H178', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Blood-cooling herb with theoretical mild antiplatelet activity that could add to anticoagulant or antiplatelet effect. Evidence is theoretical.', 'Use caution and monitor; avoid concurrent therapeutic use without professional supervision and coagulation monitoring.', 'Brinker, Herbal Contraindications and Drug Interactions (theoretical).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI714', 'H178', 'condition', 'Spleen/Stomach deficiency-cold and Kidney yang deficiency (TCM)', 'moderate', 'Bitter-cold Zhi Zi quenches an already weak digestive fire and cold constitution, worsening poor appetite, loose stools, and cold in the abdomen.', 'Avoid in cold-deficient digestive and yang-deficient patterns; if used, combine with warming, protective herbs and limit duration.', 'Bensky, Clavey and Stoger, Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
