INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H178', 'EP08', 'avoid', 1, 2, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhi Zi (Gardenia), listed among the herbs for heat, irritability, jaundice, and hot sores.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhi Zi (Gardenia), listed among the herbs for heat, irritability, jaundice, and hot sores.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Zhi Zi; Chen and Chen, Chinese Medical Herbology and Pharmacology, Zhi Zi; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Gardenia; AHPA Botanical", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Zhi Zi; Chen and Chen, Chinese Medical Herbology and Pharmacology, Zhi Zi; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Gardenia; AHPA Botanical", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H179', 'Guduchi (Giloy)', 'Tinospora cordifolia', 'Menispermaceae (moonseed family)', 'Stem (the mature climbing stem is the officinal part; the root is used secondarily, and a purified aqueous starch extract of the stem, guduchi satva, is a traditional form)', 'Bitter (tikta) and astringent (kashaya) on the tongue, with a characteristically sweet post-digestive effect (madhura vipaka). The fresh stem is mucilaginous and starchy.', 'Cool (functional). Classical Ayurveda assigns Guduchi a hot potency (ushna virya), yet its signature clinical role is antipyretic and Pitta-pacifying and it is the premier remedy for fevers, inflammation, and heat, so in the Western energetic column encoded here it reads as cooling in effect. The classical ushna virya is noted and flagged for the reviewer.', 'Neutral. A bitter alterative with a drying, toxin-clearing tendency that is offset by its unctuous (snigdha) rasayana quality and sweet post-digestive effect, keeping it broadly Vata-neutral and usable in convalescence and depletion, so on balance it is neither markedly drying nor moistening.', 'Excess heat and heat with toxicity: fevers, inflamed and autoimmune heat, gouty and rheumatic heat, and heated, itching skin, which this cooling bitter clears. Dampness and damp-heat with accumulated toxins (ama): a sticky, congested, toxic terrain it decongests and detoxifies. Chronic and recurrent infection with a worn, under-responsive defense, which it modulates and strengthens. And, as a rasayana, deficiency and exhaustion: the depleted, convalescent, immune-worn state after prolonged or repeated illness, which it rebuilds. In short a cooling, clearing, immune-modulating tonic bitter for hot, toxic, and depleted-after-illness tissue.', 'Cold and cold depletion: a cooling bitter can further chill a frankly cold, hypometabolic terrain and, used alone and unbalanced, may aggravate a thin, cold, depleted (Vata-like) constitution. Frank yang deficiency with cold digestion. There are no strong classical tissue contraindications because Guduchi is tridoshic, but its clearing bitterness is best balanced with warming, carminative anupanas (ginger, honey, warm water) in cold and depleted states.', 'Immune (primary: the classic Ayurvedic immunomodulator and rasayana, raising and balancing defense). Hepatic / Liver (primary but double-edged: a traditional liver protectant used in jaundice and toxic hepatitis, yet the organ implicated in modern idiosyncratic liver-injury reports). Digestive (bitter tonic and grahi, kindling appetite and clearing ama). Musculoskeletal (anti-inflammatory in gout, amavata, and rheumatoid heat). Integumentary / Skin (alterative for heated, itching, chronic skin disease). Endocrine / metabolic (blood-sugar- and lipid-lowering). Nervous (medhya, a mild cerebral tonic).', 'Chronic, recurrent, and post-infective fevers and convalescence; frequent illness and a worn, under-responsive immune defense; chronic and low-grade infection; autoimmune and rheumatic inflammation (amavata / rheumatoid arthritis) and gout with elevated uric acid; general debility and fatigue after illness; elevated blood sugar (prameha / diabetes); heated, itching, chronic skin disease (kushtha); sluggish liver and toxic-heat jaundice (traditional); allergic and inflammatory reactivity; and, as a rasayana, mental dullness and premature aging. It is the Ayurvedic Amrita, the nectar herb given to clear heat and toxins while rebuilding vitality.', 'The hot, robust, toxic, inflamed phenotype (Robust / Hot, Pitta-like, and the bilious Choleric): fevers, damp-heat, autoimmune and gouty inflammation, and heated skin, which this cooling bitter clears and detoxifies. Also suited to the depleted, post-illness, immune-worn constitution, which it rebuilds as a rasayana. Least suited to the very cold, thin, depleted (Vata-like) type when its clearing bitterness is used alone and unbalanced.', 'Vata, Pitta, Kapha (tridoshahara / tridoshic; especially pacifies Pitta and Kapha, and its unctuous quality and sweet vipaka keep it broadly Vata-neutral to Vata-balancing)', 'None classically (Guduchi is tridoshahara). In excess, or in a very cold and depleted person, its bitterness may mildly increase Vata; balance with a warming anupana.', 'Heat and Fire, including damp-heat and lingering (yin-consuming) heat: high, recurrent, and low-grade fevers, toxic heat, and heat in the joints and skin, which this cooling bitter clears (a functional qing re jie du picture). Dampness and Phlegm with turbid accumulation (ama), which it dries and detoxifies. And Wei-Qi weakness with a worn, under-responsive defense, which it modulates and tonifies. Guduchi is not a classical Chinese herb (it is an Ayurvedic remedy); these are functional correspondences.', 'Kidney-Yang and Spleen-Yang deficiency with true cold (cold limbs, cold, weak digestion, loose cold stool) and Wind-Cold patterns, where a cooling, clearing bitter can further chill and weaken the yang. In such patterns combine only with warming, yang-supporting herbs, or choose a warmer remedy.', 'The most important modern caution is the liver. Despite Guduchi''s classical reputation as a liver protectant, a cluster of herb-induced liver injury cases with autoimmune-like features was documented in India during the 2020 to 2022 COVID immune-booster surge (idiosyncratic hepatitis, sometimes unmasking latent autoimmune liver disease); monitor liver function, use only correctly identified material, and stop at once for jaundice, dark urine, marked fatigue, or right-upper-abdominal pain. Because Guduchi stimulates and modulates immunity, it may worsen activity in autoimmune disease and may antagonize immunosuppressant therapy, so avoid it in transplant recipients and in immunosuppressed autoimmune patients unless supervised. It lowers blood sugar, so use cautiously with diabetes and hypoglycemia. Species substitution is a real hazard: the more hepatotoxic Tinospora crispa and the related Tinospora sinensis are sometimes sold as guduchi, so source verified Tinospora cordifolia. Pregnancy and lactation data are insufficient.', 'Active autoimmune hepatitis or unexplained acute hepatitis (avoid; the herb has been implicated). Autoimmune disease with active flares (caution; may aggravate). Concurrent immunosuppressant therapy, including organ transplantation (avoid or use only under supervision; possible antagonism). Pregnancy and lactation (insufficient data; avoid). Caution in diabetes and with blood-sugar-lowering medication. Relative constitutional caution in very cold, thin, depleted (Vata / yang-deficient) states. Discontinue and seek testing at any sign of liver injury.', 'Insufficient reliable data; avoid. Modern consumer and clinical references state there is not enough reliable information to know whether Tinospora cordifolia is safe during pregnancy and advise staying on the safe side and not using it. Although classical Ayurveda used Guduchi in some conditions, modern safety data are lacking and the herb is immunoactive, so avoid in pregnancy. Sources: WebMD (Tinospora cordifolia); RxList (Tinospora cordifolia); Drugs.com (Tinospora).', 'Insufficient reliable data; avoid. There are no adequate modern lactation safety data, and standard consumer references advise avoiding use while breastfeeding. Prefer a better-documented remedy. Sources: WebMD (Tinospora cordifolia, insufficient information); RxList; Drugs.com (Tinospora).', 'Not established by modern data. Ayurveda has traditionally given small doses of Guduchi and of guduchi satva to children for recurrent fevers and immunity, but formal modern pediatric safety and dosing data are absent, and idiosyncratic liver injury has been reported in adults, so reserve internal use for qualified practitioner guidance and monitor. Sources: precautionary practice; WebMD / RxList (no pediatric data); Kulkarni et al., Hepatology Communications 2022 (herb-induced liver injury).', 'Immunosuppressant drugs (cyclosporine, tacrolimus, sirolimus, azathioprine, mycophenolate, corticosteroids, basiliximab): Guduchi stimulates and modulates immune activity and may decrease the effectiveness of these drugs and worsen autoimmune activity, so avoid in transplant and immunosuppressed autoimmune patients (WebMD rates immunosuppressant interaction as significant). Antidiabetic drugs (insulin, sulfonylureas, metformin): additive blood-glucose lowering, with a risk of hypoglycemia; monitor blood sugar and adjust with the prescriber (WebMD; RxList). Hepatotoxic drugs and other liver-loading herbs: given the documented idiosyncratic liver-injury reports, avoid stacking with known hepatotoxins and monitor liver enzymes (Kulkarni et al. 2022). Anticoagulant and antiplatelet drugs (warfarin, aspirin): a theoretical additive bleeding risk is noted with limited clinical data. Antihypertensive drugs: possible additive blood-pressure lowering, limited data. Overall the immunosuppressant and antidiabetic interactions are the best supported. Sources: WebMD (Tinospora cordifolia interactions); RxList; Drugs.com (Tinospora); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.', 'Decoction (kwatha / kashaya) of the dried or fresh stem, the classic form; stem powder (churna); guduchi satva, the purified aqueous starch settled from the pounded fresh stem, a gentle cooling form suited to children and to Pitta and bleeding conditions; fresh-stem juice (swarasa); cold or hot water infusion of the chopped fresh stem (guduchi water); and modern tincture and standardized capsule or extract. Often combined with ginger for fever, with other rasayanas in convalescence, or within classical formulas such as Guduchi ghana, Sanshamani vati, and Amrita guggulu.', 'Stem powder (churna): 3 to 6 g per day in 2 to 3 divided doses (Ayurvedic Pharmacopoeia of India), commonly 1 to 3 g twice daily. Decoction (kwatha): 20 to 30 g of dried stem simmered down, taken as about 40 to 80 mL twice daily; or 50 mL of a 1:4 decoction. Guduchi satva (starch): 0.5 to 1 g once or twice daily. Fresh-stem juice: 10 to 20 mL. Standardized aqueous or hydro-alcoholic extract (modern): roughly 300 mg once or twice daily. Tincture: commonly 2 to 4 mL two to three times daily. Use for defined courses with periodic liver-function monitoring rather than open-ended high-dose use.', 'Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, Pharmacographia Indica (1890), Guluncha (Tinospora cordifolia).', 'Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmacopoeia of India, Part I, Guduchi (dried stem). Upadhyay AK, et al. Tinospora cordifolia (Willd.) Hook. f. and Thoms. (Guduchi): validation of the Ayurvedic pharmacology through experimental and clinical studies. Int J Ayurveda Res 2010;1(2):112-121 (PMC2924974). Saha S, Ghosh S. Tinospora cordifolia: one plant, many roles. Anc Sci Life 2012;31(4):151-159 (PMC3644751). Kulkarni AV, et al. Tinospora cordifolia (Giloy)-Induced Liver Injury During the COVID-19 Pandemic: Multicenter Nationwide Study From India. Hepatol Commun 2022;6(6):1289-1300 (PMC9134809). Nagral A, et al. Herbal Immune Booster-Induced Liver Injury in the COVID-19 Pandemic: A Case Series. J Clin Exp Hepatol 2021 (PMID 34230786). WebMD, RxList, and Drugs.com (Tinospora cordifolia) consumer safety and interaction summaries; AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions.', 'Menispermaceae. Sanskrit Amrita, the nectar of immortality, also Guduchi, Giloy, Guduchika, Madhuparni, and Chinnaruha or Chinnodbhava, the vine that regenerates from a cut stem piece. The mature stem is the officinal part. Reported constituents include isoquinoline and aporphine alkaloids (berberine, palmatine, jatrorrhizine, magnoflorine, tembetarine, tinosporin), clerodane and furanoid diterpenes and their glycosides (tinosporide, tinosporaside, columbin, tinosporon, cordifolioside), the immunomodulatory arabinogalactan polysaccharide G1-4A, sesquiterpenoids, sterols (giloinsterol), and the phenylpropanoid glycoside syringin. Documented modern activities include immunomodulatory, antipyretic, anti-inflammatory, antioxidant, hypoglycemic and antidiabetic, hypolipidemic, hepatoprotective (in classical use and many models, though idiosyncratic liver injury is now reported), antistress and adaptogenic, nootropic, radioprotective, and adjunct antineoplastic effects. Classically it is rasayana and vayasthapana (rejuvenative and life-prolonging), balya (strengthening), jvaraghna (antipyretic), amahara (toxin-clearing), medhya (a mind tonic), and kushtaghna (for skin disease), used in jvara (fever), amavata (rheumatoid disease), vatarakta (gout), prameha (diabetes), kushtha (skin disease), pandu and kamala (anemia and jaundice), and kasa and svasa (cough and dyspnea). A caution runs alongside the praise: species substitution with the more hepatotoxic Tinospora crispa and with Tinospora sinensis is common, and the 2020 to 2022 use of giloy as a COVID immune booster in India produced a documented cluster of herb-induced liver injury with autoimmune features, which tempers its classical reputation as a liver protectant.', 'Not named in the canonical biblical texts. Guduchi is native to the tropical Indian subcontinent, Myanmar, and Sri Lanka, and its medicine is anchored in Ayurveda, where it is celebrated as Amrita, the nectar of the gods, and described in the Charaka Samhita, the Sushruta Samhita, and the Bhavaprakasha Nighantu. It also enters Unani medicine (Gilo). It is a plant of the classical Indian materia medica rather than the ancient Mediterranean or biblical world.', 'Not on the United Plant Savers At-Risk or To-Watch lists, which track North American natives. Tinospora cordifolia is a fast-growing, hardy, easily propagated climbing vine (it strikes readily from stem cuttings, the basis of its name Chinnaruha), widely cultivated and not threatened. The real stewardship concerns are adulteration and misidentification: the more hepatotoxic Tinospora crispa and the related Tinospora sinensis are sometimes substituted, and demand from the immune-supplement market is heavy. Prefer verified, correctly identified, cultivated or ethically sourced Tinospora cordifolia.', 'Cool, clearing, and yet rebuilding: Amrita, the nectar bitter, an antipyretic immunomodulating alterative that clears heat, damp-heat, and toxic inflammation while restoring vitality after illness.', 'Refer at once for any sign of liver injury while using Guduchi: jaundice (yellow eyes or skin), dark urine, pale stool, marked fatigue, nausea, or right-upper-abdominal pain, and stop the herb (possible herb-induced liver injury). Refer for fever that is high, persistent beyond about 3 days, or accompanied by rash, stiff neck, severe headache, breathlessness, or confusion (rule out serious infection such as dengue, malaria, or meningitis); for a known autoimmune disease that flares; for uncontrolled or symptomatic diabetes; and for unexplained weight loss or a joint attack needing diagnosis. Guduchi is a supportive remedy, not a substitute for diagnosis and treatment of serious infection, liver, or autoimmune disease.', 'Guduchi = goo-DOO-chee; Giloy = gih-LOY; Amrita = UM-rih-tuh. Tinospora cordifolia = tin-OSS-por-uh kor-dih-FOH-lee-uh.', 'seed', 'Approved', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P"}'::jsonb, '{"title": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "locator": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
