INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H179', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS05', 'Primary', 'Excess heat; the cooling antipyretic bitter clears fevers, inflammatory and autoimmune heat, and heated skin.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS14', 'Primary', 'Chronic and recurrent infection with a worn, under-responsive defense; immunomodulates and strengthens.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS07', 'Secondary', 'Dampness and damp-heat with turbid toxin accumulation (ama), which it dries and detoxifies.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS01', 'Secondary', 'Deficiency; as a rasayana it rebuilds the depleted, convalescent, immune-worn state after illness.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS04', 'Secondary', 'Exhaustion; a restorative tonic for post-illness debility and fatigue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS13', 'Secondary', 'Wei Qi weakness; strengthens a worn defensive capacity against recurrent illness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS17', 'Primary', 'Cold; a cooling bitter can further chill a frankly cold, hypometabolic terrain unless warmed.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H179', 'TS01', 'Minor', 'In a very cold, thin, depleted (Vata-like) state its clearing bitterness, used alone and unbalanced, may further deplete.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY05', 'Primary', 'Immune; the classic Ayurvedic immunomodulator and rasayana that raises and balances defense.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY12', 'Primary', 'Hepatic; traditional liver protectant in jaundice and toxic heat, and the organ implicated in modern idiosyncratic liver-injury reports.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY08', 'Secondary', 'Digestive; bitter tonic and grahi that kindles appetite and clears ama.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY04', 'Secondary', 'Musculoskeletal; anti-inflammatory in gout, amavata, and rheumatoid heat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY10', 'Secondary', 'Integumentary; alterative for heated, itching, chronic skin disease (kushtha).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY02', 'Secondary', 'Endocrine and metabolic; blood-sugar- and lipid-lowering.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H179', 'SY01', 'Minor', 'Nervous; medhya, a mild cerebral and anti-stress tonic.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A04', 'Primary', 'Immunomodulator; the signature action, raising and balancing immune response (arabinogalactan G1-4A and alkaloids).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A01', 'Primary', 'Adaptogen; a classic rasayana that builds resilience and restores after stress and illness.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A49', 'Primary', 'Febrifuge / antipyretic; jvaraghna, the premier remedy for recurrent and lingering fevers.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A14', 'Primary', 'Alterative; a blood- and tissue-cleansing bitter for toxic heat and chronic skin disease.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A09', 'Secondary', 'Anti-inflammatory; eases gouty, rheumatic, and autoimmune inflammation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A16', 'Secondary', 'Bitter tonic; kindles digestion and clears ama while toning the liver.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H179', 'A06', 'Secondary', 'Immune tonic; balya rasayana that rebuilds a worn defense against recurrent illness.');
