INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H179', 'TCM13', 'Secondary', 'Wind-Cold patterns, where a cooling remedy is inappropriate without warming support.', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P"}'::jsonb, '{"title": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "locator": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI715', 'H179', 'condition', 'Autoimmune disease and idiosyncratic liver injury (autoimmune-like hepatitis)', 'moderate', 'Guduchi stimulates and modulates immunity; documented herb-induced liver injury with autoimmune features (idiosyncratic hepatitis, sometimes unmasking latent autoimmune liver disease) during the 2020 to 2022 immune-booster surge.', 'Avoid in active or unexplained hepatitis and in flaring autoimmune disease; if used, monitor liver function and stop at once for jaundice, dark urine, marked fatigue, or right-upper-abdominal pain; use only verified Tinospora cordifolia.', 'Kulkarni et al., Tinospora cordifolia (Giloy)-Induced Liver Injury, Hepatology Communications 2022 (PMC9134809); Nagral et al., J Clin Exp Hepatol 2021 (PMID 34230786).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI716', 'H179', 'drug_interaction', 'Immunosuppressant drugs (cyclosporine, tacrolimus, sirolimus, azathioprine, mycophenolate, corticosteroids, basiliximab)', 'moderate', 'Immunostimulant and immunomodulatory activity may antagonize immunosuppressant therapy and worsen autoimmune activity.', 'Avoid in organ-transplant recipients and immunosuppressed autoimmune patients unless supervised.', 'WebMD (Tinospora cordifolia interactions, significant); RxList (Tinospora cordifolia).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI717', 'H179', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'The herb lowers blood glucose and may add to antidiabetic drugs, risking hypoglycemia.', 'Monitor blood sugar closely and adjust medication with the prescriber.', 'WebMD (Tinospora cordifolia interactions); RxList; Drugs.com (Tinospora).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI718', 'H179', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable safety data for an immunoactive herb.', 'Avoid in pregnancy.', 'WebMD (Tinospora cordifolia); RxList; Drugs.com (Tinospora).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI719', 'H179', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate modern lactation safety data.', 'Avoid while breastfeeding; prefer a better-documented remedy.', 'WebMD (insufficient information); RxList (Tinospora cordifolia).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI720', 'H179', 'pediatric', 'Children', 'moderate', 'No formal modern pediatric safety data; idiosyncratic liver injury reported in adults.', 'Use only in small practitioner-guided doses with monitoring; guduchi satva is the gentler traditional form.', 'Precautionary practice; WebMD / RxList (no pediatric data); Kulkarni et al. 2022.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI721', 'H179', 'drug_interaction', 'Hepatotoxic drugs and liver-loading herbs', 'moderate', 'Documented idiosyncratic liver-injury signal; additive hepatic risk when combined with hepatotoxins.', 'Avoid stacking with known hepatotoxic drugs or herbs; monitor liver enzymes during use.', 'Kulkarni et al. 2022 (PMC9134809); Nagral et al. 2021.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI722', 'H179', 'condition', 'Cold, yang-deficient constitutions (very cold, thin, depleted / Vata)', 'low', 'A cooling, clearing bitter can further chill and deplete a frankly cold, hypometabolic terrain.', 'Use with a warming anupana (ginger, honey, warm water) or choose a warmer remedy; avoid dry, single-herb use in these states.', 'Traditional energetic assessment (Bhavaprakasha Nighantu; Ayurvedic Pharmacopoeia of India).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H179', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P"}'::jsonb, '{"title": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "locator": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, true);
