INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H179', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), No. 40 Tinospora cordifolia, Miers. Public-domain historical Indian materia medica with a dedicated heading (synonyms, vernacular names, habitat, and medicinal uses). Supported by Dymock, P"}'::jsonb, '{"title": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "locator": "Charaka Samhita and Sushruta Samhita (classical descriptions of Guduchi and Amrita); Bhavaprakasha Nighantu (Guduchyadi varga: rasa tikta and kashaya, guna guru and snigdha, virya ushna, vipaka madhura, tridoshahara). The Ayurvedic Pharmaco", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H180', 'Japanese Honeysuckle (Jin Yin Hua)', 'Lonicera japonica Thunb.', 'Caprifoliaceae (the honeysuckle family)', 'Flower bud (the dried flower bud and partially opened flower, Lonicerae Japonicae Flos)', 'Sweet, with a light aromatic, wind-dispersing quality', 'Cold', 'Neutral', 'Excess heat and heat-toxin in the blood and flesh (hot, red, swollen, painful sores, carbuncles, boils, and abscesses; the flushed heat of an early febrile illness); acute infection and inflammation (hot swollen sore throat, hot skin infections, the first hot flush of a cold or flu); wind-heat at the surface (fever, sore throat, and headache at the onset of a hot cold); damp-heat in the gut and lower body (hot, urgent, damp-heat dysentery and dysenteric diarrhea, hot painful urination). A cooling, cleansing flower for the hot, toxic, inflamed terrain.', 'Cold and deficiency, especially a cold, weak, deficient digestion (poor appetite, loose stools) where a strongly cold flower further chills and slows the terrain; the thin, cold, depleted constitution and yang-deficient states that run cold and tired; wind-cold patterns (chills, clear runny nose, aversion to cold) where a cooling wind-heat clearer is the wrong direction.', 'Immune (the premier clear-heat, relieve-toxicity herb of Chinese medicine for hot infections, sores, and heat-toxin); Respiratory/Lungs (disperses wind-heat at the surface; early hot colds and flu, fever, sore throat); Digestive/Stomach (clears damp-heat from the gut; hot dysentery and enteritis, with the counter-caution that it chills a cold, weak digestion); Integumentary/Skin (hot, inflamed, infected skin, carbuncles, boils, and abscesses); Lymphatic (hot swollen glands and the drainage of heat-toxin). Enters the Lung, Heart, and Stomach channels.', 'Hot, red, swollen, painful sores, carbuncles, boils, and abscesses (the classic heat-toxin skin herb of Chinese medicine); the onset of wind-heat colds and flu with fever, headache, and sore throat (a lead herb in Yin Qiao San); febrile and warm-disease heat; hot, urgent damp-heat dysentery and dysenteric diarrhea; hot swollen sore throat and swollen glands. Traditionally a cooling flower to clear heat, relieve fire-toxin, and cool the blood.', 'Hot and full: the robust, red-faced, plethoric, easily-inflamed type running hot with fever, hot infected skin, and heat that has flared into toxin and sores. Cools and cleanses the choleric and the hot, hard-driving constitution. Not for the thin, cold, depleted, weak-digestion type.', 'Pitta (sweet, cold, and cleansing; clears heat, inflammation, and fire-toxin from the blood and skin and settles a hot, sharp, inflamed Pitta state).', 'Vata (cold and light; can further chill and unsettle the cold, dry, depleted Vata constitution, especially in excess or in the cold season). Cold can also burden a cold, damp, sluggish Kapha digestion.', 'Wind-heat invading the exterior and the Lung (fever, headache, sore throat, and thirst at the onset of a hot cold or warm-febrile disease; a chief herb of Yin Qiao San with forsythia); heat-toxin and fire-toxin (hot painful sores, carbuncles, boils, abscesses, and swollen sore throat, internal and external); and damp-heat in the intestines (hot, urgent dysentery and dysenteric diarrhea, for which the charred flower, Jin Yin Hua Tan, is preferred). Lonicerae Japonicae Flos (Jin Yin Hua) is classed as sweet and cold, entering the Lung, Heart, and Stomach channels.', 'Spleen and Stomach qi deficiency with cold (poor appetite, loose stools, cold-natured digestion), where a strongly cold, bitter-sweet flower further weakens digestion; yang deficiency and internal cold; and wind-cold patterns (chills predominant, clear nasal discharge, no thirst), where a cooling wind-heat clearer is contraindicated. Best used in short courses, since prolonged use of strongly cold heat-clearing herbs damages Spleen yang.', 'Honeysuckle flower is a gentle, food-grade herb with a wide safety margin and a long culinary and medicinal history, but several real cautions apply. First, being strongly cold it is poorly suited to cold, weak, deficient digestion and can cause loose stools or belly ache in cold-natured people; it is best used in short courses for acute heat rather than long-term. Second, modern laboratory and animal research reports antiplatelet, blood-sugar-lowering, and anti-early-pregnancy and antifertility activity, which underlies theoretical cautions in pregnancy and with anticoagulant, antiplatelet, and antidiabetic medications. Third, use the correct part and species: the medicinal material is the dried flower bud of Lonicera japonica, not the berries; the berries of various ornamental honeysuckles can cause nausea, vomiting, and diarrhea if eaten. As with any botanical, allergic reactions are possible; discontinue if rash or swelling occurs.', 'Cold, deficient digestive states and yang deficiency, in which a strongly cold herb aggravates; wind-cold colds (as opposed to wind-heat); pregnancy and lactation in medicinal amounts (insufficient safety data, plus animal reports of anti-early-pregnancy and antifertility activity); and concurrent anticoagulant, antiplatelet, or blood-sugar-lowering drug therapy without supervision. Do not use the berries.', 'Insufficient reliable modern data; avoid medicinal or supplemental amounts. There is not enough reliable information to know whether honeysuckle is safe in pregnancy, and standard guidance is to avoid use. This caution is reinforced by animal and laboratory studies reporting anti-early-pregnancy and antifertility activity for Lonicera japonica. Occasional culinary-strength tea has a long traditional history, but concentrated or therapeutic use should be avoided for want of safety data. (RxList/WebMD, drawing on Natural Medicines Comprehensive Database; Shang et al., Lonicerae Japonicae Flos systematic pharmacology review, J Ethnopharmacol 2011, PMC4519546.)', 'Insufficient reliable data; avoid amounts greater than in food. There is not enough reliable information on honeysuckle during lactation; culinary-strength tea amounts are presumed low-risk, but supplemental or therapeutic doses should be avoided for want of safety data. (RxList/WebMD, drawing on Natural Medicines Comprehensive Database; NCCIH general herb-in-lactation guidance.)', 'No established medicinal dose in children; robust safety data are lacking. Weak culinary-strength honeysuckle tea and honeysuckle-flower syrups are traditionally given in East Asia for children''s heat, fever, and sore throat, but concentrated or prolonged medicinal use should be avoided without professional guidance, and a cold herb is best kept to short courses. (RxList/WebMD, drawing on Natural Medicines Comprehensive Database.)', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin): Lonicera japonica shows antiplatelet-aggregation activity in laboratory studies, so concentrated or regular use is a theoretical additive bleeding risk; use caution and monitor. Antidiabetic drugs (insulin, sulfonylureas, metformin): documented blood-sugar-lowering (hypoglycemic) activity means possible additive glucose lowering; monitor blood sugar. Immunosuppressant therapy: honeysuckle has immune-stimulating activity that could theoretically oppose immunosuppression; use caution with agents such as azathioprine or in transplant recipients. Overall clinical interaction data are limited and largely theoretical or preclinical; no well-documented human drug interactions are established, but the antiplatelet and hypoglycemic signals are the most relevant. (Shang et al., Lonicerae Japonicae Flos systematic pharmacology review, J Ethnopharmacol 2011, PMC4519546; Herbal Reality, Honeysuckle monograph; RxList/WebMD, Natural Medicines Comprehensive Database.)', 'Decoction is the primary traditional form (the dried flower buds simmered, often paired with forsythia for wind-heat or with other heat-toxin herbs for sores); infusion/tea (flower buds steeped in hot water, a common cooling summer drink); tincture; a strong decoction used cooled as an external wash, soak, or compress over hot infected skin, sores, and boils; and syrup or honey-infusion for children''s heat and sore throat. The charred flower (Jin Yin Hua Tan) is used for damp-heat dysentery, and the flower distillate (Jin Yin Hua Lu) as a cooling summer drink.', 'Decoction: 6 to 15 g dried flower buds per day for ordinary heat clearing, increased to 15 to 30 g (occasionally to 60 g, short-term, under professional care) for severe heat-toxin, sores, or acute febrile disease. Tea/infusion: 3 to 9 g steeped in hot water, 1 to 3 cups daily for early wind-heat colds. Tincture: per manufacturer or practitioner guidance. External: a strong, cooled decoction as a wash or compress over hot infected skin and sores. Best used in short courses for acute heat rather than long-term.', 'Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacology 2011 (PMC4519546); Herbal Reality, Honeysuckle (Lonicera) monograph; RxList/WebMD (Natural Medicines Comprehensive Database), Honeysuckle; Pharmacopoeia of the People''s Republic of China (Lonicerae Japonicae Flos).', 'Family Caprifoliaceae. Jin Yin Hua, literally ''gold-silver flower'', is named for its blossoms opening white and aging to gold, so a single vine bears both colors at once. The medicinal material is the dried flower bud; the stem and leaf (Ren Dong Teng, Lonicerae Japonicae Caulis) is a related but distinct heat-clearing, channel-freeing medicine. Key constituents include chlorogenic acid and isochlorogenic acids, the iridoid glycosides secologanin and loganin, the flavonoid luteolin and its glycosides, and saponins; these underlie documented broad antibacterial, antiviral, anti-inflammatory, antioxidant, antipyretic, and hepatoprotective activity, with additional reported antiplatelet, hypoglycemic, and antifertility effects. One of the most widely used clear-heat, relieve-toxicity herbs in Chinese medicine and a lead ingredient of the classic wind-heat formula Yin Qiao San (with Forsythia, Lian Qiao). Note that some commercial Jin Yin Hua derives from related species (Lonicera hypoglauca, Lonicera confusa, Lonicera macranthoides), collectively sold as Shan Yin Hua / Lonicerae Flos.', 'Not in canonical biblical texts. Japanese honeysuckle is native to East Asia (China, Japan, Korea) and is a classic of Chinese medicine, recorded in the Chinese materia medica tradition (Tang Ben Cao, 7th century, and elaborated by Li Shizhen in the Bencao Gangmu, 1596) and documented for Western readers in Stuart''s Chinese Materia Medica (1911). It is not a plant of the biblical Mediterranean world.', 'Not at risk; the opposite concern applies. Lonicera japonica is a vigorous, widely cultivated plant and an aggressive invasive weed across the eastern United States (introduced in the 1800s, now invasive in dozens of states), where it smothers native vegetation. There is no conservation pressure on this species; wild flowers can be harvested freely, and removing it benefits native habitat. Source flowers grown without pesticides, and take care to identify the species correctly, since some ornamental honeysuckles have mildly toxic berries.', 'Cold, sweet, and cleansing: a cooling flower that draws fire and toxin out of the blood and flesh, quenching hot swollen sores and the first hot flush of a fever.', 'Refer for a spreading skin infection or abscess with red streaking, marked swelling, or fever (possible cellulitis or a collection needing drainage or antibiotics); sore throat with drooling, difficulty swallowing, or difficulty breathing (possible epiglottitis or peritonsillar abscess); high fever with stiff neck, confusion, or rash (possible meningitis); dysentery or bloody diarrhea with high fever or signs of dehydration; and any high or persistent fever, since honeysuckle tea is not a substitute for antibiotic or urgent care in serious bacterial infection or sepsis.', 'Honeysuckle: HUN-ee-suk-uhl. Jin Yin Hua: jin yin hwah. Lonicera japonica: loh-NISS-er-uh juh-PON-ih-kuh.', 'free', 'Approved', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H180', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H180', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS05', 'Primary', 'Clears excess heat and fire-toxin from the blood and flesh; hot sores, febrile heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS15', 'Primary', 'Acute infection: hot skin infections, sore throat, early febrile illness.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS06', 'Primary', 'Acute inflammation: hot, red, swollen, painful sores, carbuncles, and throat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS14', 'Secondary', 'Chronic and lingering heat-toxin infection; recurring sores and abscesses.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS20', 'Secondary', 'Disperses wind-heat at the surface; onset of hot colds and flu.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS07', 'Secondary', 'Clears damp-heat from the gut and lower body; hot dysentery, hot painful urination.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS17', 'Primary', 'Strongly cold; aggravates a cold, chilled terrain, yang deficiency, and wind-cold.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H180', 'TS01', 'Secondary', 'Cold flower weakens a deficient, cold digestion (poor appetite, loose stools).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H180', 'SY05', 'Primary', 'Premier clear-heat, relieve-toxicity herb; hot infections, sores, heat-toxin.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H180', 'SY07', 'Primary', 'Disperses wind-heat; early hot colds and flu, fever, sore throat (Yin Qiao San).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H180', 'SY08', 'Secondary', 'Clears damp-heat from the gut; hot dysentery and enteritis (chills cold digestion).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H180', 'SY10', 'Secondary', 'Hot, inflamed, infected skin; carbuncles, boils, abscesses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H180', 'SY11', 'Minor', 'Hot swollen glands and drainage of heat-toxin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A28', 'Primary', 'Antimicrobial: the clear-heat, relieve-toxicity herb; broad antibacterial and antiviral action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A09', 'Primary', 'Anti-inflammatory for hot, red, swollen sores, throat, and skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A29', 'Secondary', 'Antibacterial; documented activity against many pathogenic bacteria.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A30', 'Secondary', 'Antiviral; used in Chinese formulas for influenza and warm-febrile disease.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A18', 'Secondary', 'Diaphoretic; gentle surface-releasing disperser of wind-heat at the onset of hot colds.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A49', 'Secondary', 'Febrifuge/antipyretic; cools febrile and warm-disease heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A14', 'Secondary', 'Alterative; clears heat-toxin from the blood, the traditional sore and skin cleanser.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A25', 'Minor', 'Antioxidant; chlorogenic acid and luteolin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A21', 'Minor', 'Lymphagogue; hot swollen glands and drainage of toxin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H180', 'A36', 'Minor', 'Hypoglycemic; documented blood-sugar-lowering activity (note additive-drug caution).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP41', 'Primary', 'Wind-heat cold/flu onset: fever, headache, sore throat (Yin Qiao San).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP70', 'Primary', 'Hot, swollen sores, carbuncles, boils, and abscesses (the signature heat-toxin use).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP52', 'Primary', 'Hot, swollen wind-heat and heat-toxin sore throat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP76', 'Secondary', 'Cools febrile and warm-disease heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP09', 'Secondary', 'Heat-toxin infections, including lingering and recurrent ones.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP56', 'Secondary', 'Hot, urgent damp-heat dysentery and dysenteric diarrhea (charred flower).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP13', 'Secondary', 'Systemic and local inflammation from heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP71', 'Minor', 'Hot swollen glands and lymphatic heat-toxin.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP18', 'Minor', 'Hot, inflamed, infected skin conditions.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP63', 'Minor', 'Damp-heat in the lower jiao; hot, painful urination.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H180', 'CP75', 'Minor', 'Antioxidant support (chlorogenic acid, luteolin).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P04', 'Primary', 'Decoction; the flower buds simmered, often with forsythia or other heat-toxin herbs.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P05', 'Primary', 'Infusion/tea; buds steeped as a cooling drink for early wind-heat colds.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P10', 'Secondary', 'Compress/wash; a strong cooled decoction over hot infected skin and sores.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P01', 'Secondary', 'Tincture; liquid extract.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P09', 'Minor', 'Syrup; for children''s heat and sore throat.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H180', 'P12', 'Minor', 'Added to cooling drinks and food (flower distillate, Jin Yin Hua Lu).');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'C06', 'Indicated', 'Primary', 'Robust/Hot (Pitta-like): the hot, plethoric, red-faced type running hot with fever and hot infected skin.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'C02', 'Indicated', 'Primary', 'Choleric: cools the hot, hard-driving, inflamed type with heat that has flared into toxin and sores.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'C05', 'Aggravates', 'Secondary', 'Thin/Cold/Depleted (Vata-like): cold and light; aggravates the cold, dry, depleted constitution.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'C04', 'Aggravates', 'Minor', 'Phlegmatic: strongly cold; can further chill a cold, damp, weak-digestion type.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'D02', 'Primary', 'Sweet and cold; clears heat, inflammation, and fire-toxin from blood and skin, settles Pitta.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
