INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'TCM03', 'Secondary', 'Strongly cold; aggravates cold, deficient Spleen digestion (poor appetite, loose stools).', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H180', 'TCM01', 'Minor', 'Cold nature aggravates internal cold and yang deficiency; keep to short courses.', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (G. A. Stuart, 1911) - Lonicera japonica (Jin Yin Hua, honeysuckle).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Jin Yin Hua (Lonicerae Japonicae Flos); Shang X et al., Lonicera japonica Thunb.: Ethnopharmacology, phytochemistry and pharmacology, Journal of Ethnopharmacolog", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI723', 'H180', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable safety data for medicinal amounts; animal and laboratory studies report anti-early-pregnancy and antifertility activity for Lonicera japonica.', 'Avoid medicinal or supplemental amounts. Occasional culinary-strength tea has a long traditional history, but concentrated or therapeutic use is best avoided for want of data.', 'RxList/WebMD (Natural Medicines Comprehensive Database); Shang et al., Lonicerae Japonicae Flos systematic pharmacology review, J Ethnopharmacol 2011 (PMC4519546).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI724', 'H180', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable safety data during lactation.', 'Avoid amounts greater than found in food; culinary-strength tea is presumed low-risk but supplemental or therapeutic doses should be avoided.', 'RxList/WebMD (Natural Medicines Comprehensive Database); NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI725', 'H180', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin)', 'moderate', 'Lonicera japonica shows antiplatelet-aggregation activity in laboratory studies, giving a theoretical additive bleeding risk.', 'Use caution and monitor with concentrated or regular use alongside anticoagulant or antiplatelet drugs; watch for bruising or bleeding.', 'Shang et al., Lonicerae Japonicae Flos systematic pharmacology review, J Ethnopharmacol 2011 (PMC4519546); Herbal Reality, Honeysuckle monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI726', 'H180', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Documented blood-sugar-lowering (hypoglycemic) activity may add to the effect of glucose-lowering medication.', 'Monitor blood sugar if used regularly with antidiabetic drugs; watch for hypoglycemia and adjust as needed with the prescriber.', 'Shang et al., J Ethnopharmacol 2011 (PMC4519546); UPLC-Q-TOF-MS hypoglycemic-component study (PMC11510595).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI727', 'H180', 'drug_interaction', 'Immunosuppressant therapy (for example azathioprine; transplant recipients)', 'low', 'Immune-stimulating activity could theoretically oppose intended immunosuppression; evidence is limited and theoretical.', 'Use caution and involve the prescriber before regular medicinal use in people on immunosuppressants or after transplant.', 'Herbal Reality, Honeysuckle monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI728', 'H180', 'condition', 'Spleen/Stomach qi deficiency with cold, yang deficiency (poor appetite, loose stools, cold-natured digestion)', 'moderate', 'A strongly cold flower further chills and weakens a cold, deficient digestion and can loosen the stool; prolonged use of cold heat-clearing herbs damages Spleen yang.', 'Avoid or use only in warming, digestion-supporting formulas and in short courses in cold, qi- or yang-deficient, loose-stool patients.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Jin Yin Hua.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI729', 'H180', 'other', 'Honeysuckle berries (wrong plant part; ornamental Lonicera species)', 'low', 'The medicinal material is the flower bud; the berries of various ornamental honeysuckles can be mildly toxic and cause nausea, vomiting, and diarrhea.', 'Use only the correctly identified flower bud of Lonicera japonica; do not ingest the berries, and keep ornamental honeysuckle berries away from children.', 'RxList/WebMD (Natural Medicines Comprehensive Database).');
