INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H181', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H181', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS03', 'Primary', 'Dryness: the signature action is moistening dry Lung and Stomach, dry cough, dry mouth and throat, and dry stool.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS01', 'Primary', 'Deficiency: the cardinal yin-deficiency (fluid-deficiency) tonic.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS02', 'Secondary', 'Atrophy: replenishes wasted, undernourished, dried-out mucosa after fever and in wasting-and-thirsting disorders.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS05', 'Minor', 'Excess Heat: clears the heat that scorches the fluids, both deficiency heat and, in warm febrile disease, heat injuring yin.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS17', 'Primary', 'Cold: sweet, cool moisture quenches an already cold, weak digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS07', 'Primary', 'Dampness: its moisture aggravates damp accumulation and Spleen-deficiency damp.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H181', 'TS23', 'Secondary', 'Phlegm: unsuited to damp-phlegm cough and phlegm accumulation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY07', 'Primary', 'Respiratory: the yin-deficient dry, hacking, scanty-sputum cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY08', 'Primary', 'Digestive/Stomach: Stomach yin deficiency, dry mouth, thirst, and dry constipation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY14', 'Secondary', 'Lungs: Lung-channel organ affinity, moistens Lung yin.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY06', 'Secondary', 'Cardiovascular: clears Heart deficiency heat, eases palpitations (Sheng Mai San).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY01', 'Secondary', 'Nervous: calms deficiency-heat restlessness, irritability, and insomnia.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H181', 'SY02', 'Minor', 'Endocrine: wasting-and-thirsting (diabetes-type) fluid depletion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A11', 'Primary', 'Demulcent: moistens dry mucosa of the Lung, throat, gut, and mouth.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A23', 'Primary', 'Tonic: the cardinal yin (fluid) tonic, generates fluids.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A40', 'Secondary', 'Trophorestorative: restores depleted, atrophied yin tissue and fluid reserves.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A33', 'Secondary', 'Antitussive: soothes the dry, unproductive yin-deficient cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A22', 'Secondary', 'Sedative: calms deficiency-heat restlessness and irritable insomnia.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A49', 'Minor', 'Febrifuge: clears heat injuring the fluids in warm disease and low-grade hectic heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A36', 'Minor', 'Hypoglycemic: polysaccharides and saponins lower blood glucose (wasting-and-thirsting use).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A38', 'Minor', 'Laxative: gently moistens the intestines for dry constipation (Zeng Ye Tang).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A04', 'Minor', 'Immunomodulator: MDG-1 and related polysaccharides.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H181', 'A25', 'Minor', 'Antioxidant: saponin and homoisoflavonoid free-radical scavenging.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP50', 'Primary', 'Dry, unproductive yin-deficient cough with scanty sticky sputum.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP55', 'Secondary', 'Dry constipation from fluid deficiency (moistens the intestines).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP27', 'Secondary', 'Blood sugar dysregulation / wasting-and-thirsting (xiao ke) with thirst and fluid depletion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP04', 'Secondary', 'Deficiency-heat irritable insomnia.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP46', 'Secondary', 'Palpitations of Heart yin deficiency (Sheng Mai San).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H181', 'CP10', 'Minor', 'Restlessness and irritability of yin-deficient heat.');
