INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H181', 'TCM13', 'Secondary', 'Wind-Cold: a moistening yin tonic can retain an unresolved exterior pathogen.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI730', 'H181', 'condition', 'Spleen and Stomach deficiency-cold with diarrhea, and damp-phlegm patterns (TCM)', 'moderate', 'Sweet, cool, moist, and cloying, it burdens weak digestion, dampens the Spleen, and worsens loose stools, damp accumulation, and phlegm.', 'Avoid in cold-damp, Spleen-deficient, diarrheal, or phlegm-damp presentations; if needed, combine with warming, qi-moving, Spleen-protective herbs and limit use.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI731', 'H181', 'condition', 'Acute exterior wind-cold with cough and copious clear or white phlegm', 'moderate', 'A moistening yin tonic can retain an unresolved exterior pathogen and thicken a damp, phlegmy cough.', 'Do not use in acute wind-cold colds or wet cough; resolve the exterior and clear phlegm first.', 'Bensky, Clavey and Stoger, Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI732', 'H181', 'pregnancy', 'Pregnancy', 'moderate', 'Not an emmenagogue or reputed abortifacient and traditionally used under supervision, but reliable modern human safety data for medicinal doses are lacking, and its cool, cloying moisture can aggravate the Spleen-deficiency dampness common in pregnancy.', 'Avoid casual self-prescription; use only under a qualified practitioner.', 'AHPA Botanical Safety Handbook (2nd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica (3rd ed.); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI733', 'H181', 'breastfeeding', 'Breastfeeding', 'low', 'No specific modern lactation safety data; a food-grade yin tonic traditionally regarded as fluid-generating, but human breastfeeding data are absent.', 'Use only under professional guidance while breastfeeding; prefer better-studied alternatives if a moistening tonic is needed.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI734', 'H181', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Ophiopogon polysaccharides (MDG-1) and saponins show blood-glucose-lowering activity and could add to the effect of hypoglycemic medication, risking hypoglycemia.', 'Monitor blood glucose and watch for hypoglycemia if combined; adjust medication under supervision.', 'Brinker, Herbal Contraindications and Drug Interactions; Chen and Chen, Chinese Medical Herbology and Pharmacology; NCCIH consumer botanical information.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H181', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
