INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H181', 'EP08', 'avoid', 1, 2, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Mai Men Dong (Ophiopogon), listed among the superior (upper-class) tonic herbs that nourish and prolong life.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Mai Men Dong; Chen and Chen, Chinese Medical Herbology and Pharmacology, Mai Men Dong; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Ophiopogon; ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H182', 'Phellodendron (Amur Cork Tree, Huang Bai)', 'Phellodendron amurense', 'Rutaceae (rue and citrus family)', 'Dried inner bark (cortex), the yellow bark with the outer corky layer removed (Cortex Phellodendri; the northern ''Guan Huang Bai'')', 'Bitter (intense, from berberine and related isoquinoline alkaloids). Salt-water-fried bark carries an added Salty note that directs it to the Kidney.', 'Cold', 'Dry', 'Damp-heat lodged in the lower burner: hot, turbid, burning discharge and dampness below the waist (urine, genitals, lower limbs). Acute damp-heat of the gut (hot, dysenteric diarrhea) and of the skin (weeping eczema, damp sores, hot ulcers). Red, hot, infected, suppurating tissue where heat and toxin combine. Also the flushed, night-sweating empty heat that rises when spent Kidney water no longer restrains the fire below (the salt-prepared indication).', 'Cold, weak, deficient digestion, since bitter-cold quenches an already low digestive fire and loosens the stool. Frank dryness and fluid deficiency, which a drying bitter deepens. Constitutional depletion and cold exhaustion without a genuine damp-heat excess to clear. It drains and cools, so it is wrong wherever the picture is cold, empty, or dry rather than hot and damp.', 'Urinary and Reproductive (the lower burner) above all, the seat of its damp-heat clearing: bladder, urethra, and genitals. Digestive and large intestine (damp-heat diarrhea and dysentery). Integumentary (skin), for weeping eczema and damp sores. Hepatic and gallbladder (damp-heat jaundice). Secondary Endocrine/Kidney (deficiency fire, night sweats) and Immune (heat-toxin infection).', 'Lower-burner damp-heat: hot, burning, turbid urination and urinary tract infection; hot, yellow, itching vaginal discharge (leukorrhea); damp-heat of the genitals and lower limbs. Damp-heat diarrhea and dysentery. Damp-heat jaundice. Weeping eczema, damp sores, hot skin ulcers, and boils (internal and topical). Yin-deficient fire: night sweats, afternoon and ''steaming-bone'' fever, five-palm heat, and seminal emission (salt-fried, paired with Anemarrhena).', 'Hot-Damp-Excess: the robust, ruddy, damp-heat phenotype who runs hot and wet in the lower body, with turbid discharge, burning urine, and damp eruptions. Also the overheated, spent type whose Kidney water no longer banks the fire (yin-deficient heat), for whom the salt-prepared bark is used. Not for the pale, cold, loose-bowelled, deficient (Vata- or yang-deficient) constitution, whom its bitter cold only chills and dries.', 'Pitta, Kapha', 'Vata', 'Damp-Heat, especially of the lower burner: damp-heat pouring down as leukorrhea, hot painful urination (lin), damp-heat diarrhea and dysentery, damp-heat jaundice, and damp-heat sores and eczema. Fire toxin (hot abscesses and sores). And Yin deficiency with vigorous empty fire: steaming-bone fever, night sweats, and seminal emission, where salt-fried Huang Bai with Zhi Mu (Anemarrhena), as in Zhi Bai Di Huang Wan, drains the ministerial fire from the Kidney. One of the ''three yellows'' (San Huang) with Huang Lian (Coptis) and Huang Qin (Scutellaria), and the lower-burner member of the trio.', 'Spleen and Stomach deficiency-cold with poor appetite and loose stools, which bitter-cold Huang Bai worsens by quenching the digestive fire. Kidney yang deficiency and cold-from-deficiency, where a fire-draining cold is precisely wrong. Frank Qi deficiency without damp-heat. It should also not be used long-term or alone in Yin and Blood deficiency without fluid-nourishing partners, since sustained bitter-cold drying injures the very fluids. Overdose or prolonged use impairs the Spleen and Stomach.', 'Intensely bitter and cold. Even short courses can chill and slow digestion, and prolonged or high-dose use damages the Spleen and Stomach, causing poor appetite, loose stools, and cold in the belly, so it is best given with warming, digestive-protective herbs or reserved for genuine damp-heat. The berberine-type alkaloids can provoke gastrointestinal upset in susceptible people. In anyone with glucose-6-phosphate dehydrogenase (G6PD) deficiency, berberine can precipitate hemolysis and must be avoided. Berberine also carries meaningful drug-interaction potential (see Drug Interactions).', 'Pregnancy and lactation (berberine risk; see safety fields). Neonates and infants, especially with jaundice or G6PD deficiency (kernicterus risk). Spleen and Stomach deficiency-cold and Kidney yang deficiency (TCM). Known G6PD deficiency. Concurrent cyclosporine, tacrolimus, and other narrow-therapeutic-index CYP3A4 or P-glycoprotein substrates without professional supervision.', 'Avoid. Huang Bai is a berberine-rich bark, and berberine crosses the placenta and displaces bilirubin from serum albumin; in the fetus and newborn this raises the risk of jaundice and kernicterus (bilirubin brain injury), a hazard considered serious enough that the berberine-containing herbs Coptis and Phellodendron were banned in Singapore for decades. Berberine is also reported to stimulate uterine contraction. Modern references (AHPA Botanical Safety Handbook, 2nd ed., which classes berberine-containing herbs as not for use in pregnancy; Mills and Bone, Principles and Practice of Phytotherapy; Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica; Brinker, Herbal Contraindications and Drug Interactions) advise against use in pregnancy. There is no safe dose that justifies the fetal risk.', 'Avoid. Berberine passes into breast milk, and the nursing newborn, whose blood-brain barrier and bilirubin conjugation are immature, can suffer displaced bilirubin, jaundice, and kernicterus, a risk that is greatest in infants with G6PD deficiency. Chen and Chen, Bensky, Clavey and Stoger, and the AHPA Botanical Safety Handbook advise against maternal use of berberine-containing herbs while breastfeeding a newborn. Prefer better-studied, non-alkaloidal alternatives during lactation.', 'Not for infants; for older children only under professional supervision. Berberine is specifically contraindicated in neonates and jaundiced infants because it displaces bilirubin and can cause kernicterus, and it is hazardous in children with G6PD deficiency (hemolysis). In older children the intense bitter-cold readily chills digestion and causes loose stools. Reserve any pediatric use to a qualified practitioner, at low, short-course, damp-heat-specific dosing.', 'Driven by berberine and the related protoberberine alkaloids. Berberine inhibits cytochrome P450 3A4 (and 2D6 and 2C9) and P-glycoprotein: a randomized clinical study in renal-transplant recipients (Wu et al., European Journal of Clinical Pharmacology, 2005) found that 0.2 g berberine three times daily significantly raised blood levels of cyclosporine A, so Huang Bai must not be combined with cyclosporine, and caution applies to other narrow-margin CYP3A4 or P-gp substrates (tacrolimus, many statins, some calcium-channel blockers, midazolam). Berberine lowers blood glucose and can add to insulin and oral hypoglycemics (metformin, sulfonylureas), risking hypoglycemia and requiring monitoring. It may potentiate anticoagulant and antiplatelet drugs (warfarin, clopidogrel) and additively lower blood pressure with antihypertensives. By displacing protein-bound drugs (and bilirubin) from albumin it can raise the free levels of highly protein-bound medicines. Separate dosing from other oral drugs. Evidence ranges from controlled human data (cyclosporine) to mechanistic and theoretical inference (Brinker; Chen and Chen; Mills and Bone).', 'Decoction of the dried bark is the standard form. Raw (unprepared) bark for clearing damp-heat and heat-toxin. Salt-water-fried (yan zhi) bark to temper the bitterness, direct the action to the Kidney, and drain deficiency fire. Wine-fried bark to carry the action upward. Powder and capsules of the dried bark. Topically as a wash, compress, or powder-paste for damp sores, eczema, and mouth ulcers. Berberine is often standardized in modern extracts.', 'Decoction: 3 to 12 g dried bark daily (commonly 6 to 10 g) in divided doses. Powder or capsules: about 1.5 to 3 g daily. Tincture (1:5): 2 to 4 mL up to three times daily. Topical: decoction as a wash or compress, or the powder in a paste, for damp skin lesions. A clearing, draining herb for damp-heat, given in short courses rather than as a long-term tonic; salt-fried for deficiency-fire use.', 'Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; Wu et al., berberine and cyclosporin A pharmacokinetics (Eur J Clin Pharmacol 2005, PMID 16133554); Chan, displacement of bilirubin from albumin by berberine (Biol Neonate 1993, PMID 8513024); Linn et al., berberine-induced haemolysis revisited: safety of Rhizoma coptidis and Cortex phellodendri (Phytother Res 2012, PMID 22002596); NCCIH consumer information on berberine.', 'Family Rutaceae. The bark is rich in isoquinoline (protoberberine) alkaloids, chiefly berberine (the yellow, bitter principle, roughly 0.6 to 2.5 percent), with palmatine, jatrorrhizine, phellodendrine, magnoflorine, and candicine, plus limonoid bitters (obacunone, obakulactone/limonin), phytosterols (beta-sitosterol), and flavonoids (amurensin). Berberine underlies most of the pharmacology: broad antimicrobial and antifungal action (against dysentery bacilli, Candida, and dermatophytes), anti-inflammatory and antidiarrheal (antisecretory) effects, and blood-glucose and lipid lowering. Two species supply the drug and the Chinese Pharmacopoeia now lists them separately: Phellodendron amurense (Guan Huang Bai, the northern/Amur bark, assigned here) and Phellodendron chinense (Chuan Huang Bai, the Sichuan bark), which tends to run higher in berberine. Classically Huang Bai is one of the ''three yellows'' (San Huang) with Huang Lian (Coptis) and Huang Qin (Scutellaria), the trio of bitter-cold damp-heat and fire-draining herbs, and it is the lower-burner member. Salt-fried Huang Bai with Zhi Mu (Anemarrhena) in Zhi Bai Di Huang Wan is the classic formula for Kidney deficiency fire (night sweats, seminal emission, steaming-bone fever). In Japanese Kampo the herb is known as Obaku.', 'Not in canonical biblical texts, and unknown to the ancient Mediterranean world; native to northeastern Asia (the Amur River region of China, plus Korea, Japan, and the Russian Far East). Its documented tradition is Chinese: it entered the materia medica in the Han-era Shen Nong Ben Cao Jing as Bo Mu / Huang Bai and was carried through every later Chinese and Japanese (Kampo, as Obaku) pharmacopoeia.', 'A study in contrasts by species. The assigned Phellodendron amurense (Amur cork tree) is not threatened; it is widely cultivated as a street and shade tree and has become an invasive species in the woodlands of the northeastern United States (New York, Pennsylvania, Illinois, and beyond), where prolific female trees crowd out native oaks and hickories, so bark from managed or removed North American trees is an ecologically positive source. Its Chinese sister species Phellodendron chinense (Chuan Huang Bai), by contrast, is a nationally protected, endangered medicinal tree in southern China, heavily depleted by bark harvest, which girdles and can kill the tree. Prefer cultivated or plantation bark, confirm the species, and avoid wild-stripped P. chinense. Not listed by United Plant Savers (a North American native-plant registry).', 'Cold and drying: an intensely bitter, berberine-rich bark that clears damp-heat and drains fire from the lower burner, cools the empty fire of spent Kidney water, and disinfects hot, damp, suppurating tissue.', 'Refer for high or persistent fever, rigors, flank pain, or blood in the urine (possible kidney or upper urinary infection); jaundice, which needs medical diagnosis rather than self-treatment; bloody or severe dysenteric diarrhea, or diarrhea with dehydration; any newborn or infant with jaundice (do not give berberine herbs); rapidly spreading skin infection, abscess with fever, or non-healing ulcers; and abnormal vaginal discharge with pelvic pain or fever. Refer anyone who is pregnant or breastfeeding, has G6PD deficiency, or takes cyclosporine, tacrolimus, warfarin, or diabetes medication before use.', 'Phellodendron: fell-oh-DEN-dron. Phellodendron amurense: fell-oh-DEN-dron am-ur-EN-see. Huang Bai: hwahng BYE.', 'free', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H182', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS05', 'Primary', 'Excess heat: drains fire from the lower burner and clears heat-toxin.');
