INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS15', 'Secondary', 'Acute infection: damp-heat dysentery, urinary and genital infection.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS14', 'Secondary', 'Chronic infection: lingering damp-heat and low-grade suppuration.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS16', 'Secondary', 'Excess conditions: a draining, clearing herb for genuine repletion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS25', 'Minor', 'Ulceration: damp sores, eczema, and hot ulcers (topical and internal).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS17', 'Primary', 'Cold: bitter-cold quenches an already cold, weak digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS01', 'Primary', 'Deficiency: a draining, cooling bitter is wrong for the frankly depleted.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS03', 'Secondary', 'Dryness: a drying bitter worsens fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H182', 'TS04', 'Minor', 'Exhaustion: draining cold further depletes the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H182', 'SY09', 'Primary', 'Urinary: hot, burning, turbid urination and lower-burner damp-heat (lin).');
