INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H182', 'SY10', 'Secondary', 'Skin: weeping eczema, damp sores, hot ulcers (topical).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H182', 'SY12', 'Secondary', 'Hepatic/gallbladder: damp-heat jaundice.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H182', 'SY02', 'Minor', 'Endocrine/Kidney: deficiency fire, night sweats (salt-fried).');
