INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H182', 'A49', 'Secondary', 'Febrifuge: clears heat and the hectic, steaming-bone fever.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H182', 'A14', 'Secondary', 'Alterative: clears damp-heat and toxin from skin, gut, and lower burner.');
