INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H182', 'CP67', 'Secondary', 'Weeping eczema and damp dermatitis (topical and internal).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H182', 'CP70', 'Secondary', 'Boils, abscesses, and hot suppurating sores.');
