INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H182', 'CP09', 'Secondary', 'Chronic damp-heat infection and low-grade suppuration.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H182', 'CP76', 'Minor', 'Hectic, afternoon, steaming-bone fever of yin deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H182', 'CP13', 'Minor', 'Systemic inflammation underlying damp-heat presentations.');
