INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H182', 'TCM02', 'Secondary', 'Qi deficiency without damp-heat: draining depletes further.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H182', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Bo Mu / Huang Bai (Phellodendron), among the herbs for heat, dampness, and toxic sores.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Huang Bai; Chen and Chen, Chinese Medical Herbology and Pharmacology, Huang Bai; G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (1911), Phellodendron; AHP", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI735', 'H182', 'pregnancy', 'Pregnancy', 'absolute', 'Berberine crosses the placenta and displaces bilirubin from serum albumin, raising the fetal/neonatal risk of jaundice and kernicterus; berberine is also reported to stimulate uterine contraction.', 'Do not use during pregnancy in any form or dose.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, Principles and Practice of Phytotherapy; Chan, displacement of bilirubin from albumin by berberine (Biol Neonate 1993, PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI736', 'H182', 'breastfeeding', 'Breastfeeding a newborn', 'absolute', 'Berberine passes into breast milk and can displace bilirubin in the newborn, whose bilirubin handling and blood-brain barrier are immature, risking jaundice and kernicterus, especially with G6PD deficiency.', 'Avoid while breastfeeding a newborn; prefer better-studied, non-alkaloidal alternatives.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI737', 'H182', 'pediatric', 'Neonates and jaundiced infants', 'absolute', 'Berberine displaces bilirubin and can precipitate kernicterus in the newborn; hemolysis risk in infants with G6PD deficiency. Berberine-containing herbs were banned in Singapore over this concern.', 'Never give to neonates or jaundiced infants. Older children only under qualified supervision at low, short-course doses.', 'Linn et al., berberine-induced haemolysis revisited: safety of Rhizoma coptidis and Cortex phellodendri (Phytother Res 2012, PMID 22002596); Chan, displacement of bilirubin from albumin by berberine (Biol Neonate 1993, PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI738', 'H182', 'condition', 'G6PD deficiency', 'absolute', 'Berberine can precipitate hemolysis in glucose-6-phosphate dehydrogenase-deficient individuals (reduced GSH, raised methaemoglobin in G6PD-deficient blood).', 'Avoid Huang Bai and other berberine-containing herbs in anyone with known or suspected G6PD deficiency, especially neonates.', 'Linn et al., berberine-induced haemolysis revisited: safety of Rhizoma coptidis and Cortex phellodendri (Phytother Res 2012, PMID 22002596).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI739', 'H182', 'drug_interaction', 'Cyclosporine (ciclosporin A) and tacrolimus', 'moderate', 'Berberine inhibits CYP3A4 and P-glycoprotein; a randomized clinical study showed berberine significantly raised cyclosporine blood levels, risking toxicity of these narrow-index immunosuppressants.', 'Do not combine with cyclosporine or tacrolimus without specialist supervision and drug-level monitoring.', 'Wu et al., Eur J Clin Pharmacol 2005 (PMID 16133554); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI740', 'H182', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Berberine lowers blood glucose and can add to the glucose-lowering effect of diabetes medication, risking hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined; watch for hypoglycemia.', 'NCCIH consumer information on berberine; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI741', 'H182', 'drug_interaction', 'CYP3A4 and P-glycoprotein substrates (statins, midazolam, some calcium-channel blockers)', 'moderate', 'Berberine inhibits CYP3A4/2D6 and P-gp, potentially raising levels of co-administered substrate drugs.', 'Use caution and separate dosing; avoid with narrow-margin substrates without supervision.', 'Brinker, Herbal Contraindications and Drug Interactions; repeated-berberine CYP inhibition study (Eur J Clin Pharmacol 2011, PMID 21870106).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI742', 'H182', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, clopidogrel)', 'moderate', 'Berberine may potentiate anticoagulant/antiplatelet effect and can displace protein-bound drugs from albumin.', 'Avoid concurrent therapeutic use without professional supervision and coagulation monitoring.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI743', 'H182', 'condition', 'Spleen/Stomach deficiency-cold and Kidney yang deficiency (TCM)', 'moderate', 'Bitter-cold Huang Bai quenches an already weak digestive fire and cold constitution, worsening poor appetite, loose stools, and cold in the abdomen.', 'Avoid in cold-deficient digestive and yang-deficient patterns; if used, combine with warming, protective herbs and limit duration.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
