INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H183', 'TCM07', 'Primary', 'Yin deficiency with dryness: warm, drying, acrid nature injures yin and worsens yin-deficient dry cough.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H183', 'TCM11', 'Secondary', 'Heat/Fire: aggravates heat-phlegm, fire, and reckless bleeding; use only with heat-clearing modification.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI744', 'H183', 'other', 'Raw, unprocessed rhizome (Sheng Ban Xia)', 'absolute', 'Needle-like calcium oxalate raphides and toxic lectins cause intense burning and swelling of the mouth, tongue, and throat with a risk of airway edema, plus gastrointestinal irritation and, in animal studies, cardiotoxicity.', 'Never ingest the raw tuber. Use only properly processed forms (Jiang, Fa, or Qing Ban Xia), practitioner-administered.', 'Zhang W et al. J Ethnopharmacol 2022 (PubMed 36087845); AHPA Botanical Safety Handbook, 2nd ed.; Nature Sci Rep 2016 (srep34692) on processing and cardiotoxicity.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI745', 'H183', 'pregnancy', 'Pregnancy', 'absolute', 'Embryotoxicity in animal studies and disturbed placental and amniotic-fluid metabolomic profiles in pregnant rats, with a theoretical uterine and fluid-drying concern; AHPA Botanical Safety Handbook Safety Class 2d (amended from Class 3).', 'Avoid in pregnancy. Any exception (a small, ginger-processed dose in a classical morning-sickness formula) belongs only to qualified TCM supervision, not self-use.', 'AHPA Botanical Safety Handbook, 2nd ed.; pregnant-rat placenta and amniotic-fluid metabolomic study (PubMed 26923539); WebMD/RxList Pinellia ternata.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI746', 'H183', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data; the warm, drying, fluid-reducing nature raises a theoretical concern for milk supply.', 'Avoid while breastfeeding pending data; reserve any use for practitioner guidance.', 'WebMD/RxList Pinellia ternata; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI747', 'H183', 'other', 'Infants and young children', 'moderate', 'No pediatric safety data, and the raw tuber''s acrid raphides pose a real risk of oral, pharyngeal, and airway swelling.', 'Use only a properly processed form under qualified supervision; keep raw material away from children.', 'AHPA Botanical Safety Handbook, 2nd ed.; Zhang W et al. J Ethnopharmacol 2022 (PubMed 36087845).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI748', 'H183', 'other', 'Aconite-containing herbs and formulas (Fu Zi, Chuan Wu, Cao Wu; Aconitum spp.)', 'absolute', 'A classical Eighteen Incompatibilities (shiba fan) pairing; co-decoction inhibits hydrolysis of diester aconitine alkaloids and can raise toxic aconitine levels, and a Fuzi-Banxia combination aggravated cardiotoxicity in an animal model.', 'Do not combine Ban Xia with any aconite herb or formula.', 'Sun et al. Evid Based Complement Alternat Med 2018 (PMC6146551 / PubMed 30258466); classical Eighteen Incompatibilities; Bensky, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI749', 'H183', 'condition', 'Yin deficiency, dryness, heat-phlegm, fire, and active bleeding (hemoptysis, hematemesis)', 'moderate', 'The warm, drying, acrid nature injures fluids and stokes heat and bleeding.', 'Avoid, or modify only with fluid-preserving and heat-clearing herbs under practitioner care.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI750', 'H183', 'drug_interaction', 'CNS depressants and sedatives (theoretical)', 'low', 'Mild central antitussive/sedative activity could be additive; human data are limited.', 'Use cautiously with sedative medications and monitor for additive drowsiness.', 'WebMD/RxList Pinellia ternata (limited data).');
