INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H183', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Ban Xia (Pinellia), listed among the lower-class (xia pin) herbs for cold and heat from injury, fullness in the chest, cough with rebellious qi, ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Ban Xia. Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004), Ban Xia. AHPA Botanical Safety Handbook, 2nd ed. Zhang W et al. A review of", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H184', 'Poria (Fu Ling, Hoelen, Tuckahoe, Indian Bread)', 'Poria cocos', 'Polyporaceae (the polypore family; a wood-decay Basidiomycota fungus, not a flowering plant). The current accepted mycological name is Wolfiporia extensa / Wolfiporia cocos; Poria cocos is the pharmacopeial name retained here for the common name.', 'Dried sclerotium, the dense underground fungal storage body that grows on the roots of pine (Pinus spp.). Traditional grades: whole Fu Ling; the thin outer peel Fu Ling Pi (superficial edema); the reddish outer flesh Chi Fu Ling (drains damp-heat through the urine); the white inner flesh Bai Fu Ling (strengthens the Spleen); and Fu Shen, the portion enclosing the pine root, favored to calm the spirit.', 'Sweet and bland. The near-flavorless blandness, a distinct category in Chinese medicine, is what leaches and drains dampness downward through the urine; the faint sweetness is what gently supplements the Spleen and harmonizes the middle. Recorded in the junction as Sweet, the closest match in the six-taste vocabulary.', 'Neutral. Classically balanced (ping), neither warming nor cooling, so Fu Ling can be added to hot and cold formulas alike.', 'Dry (functionally). It is bland and gentle rather than harshly desiccating, but its net action is to remove excess water, so it belongs on the drying side.', 'Dampness and boggy fluid accumulation: waterlogged, puffy tissue, edema, damp diarrhea, thin watery phlegm-fluid (tan yin), and scanty or turbid urine. The pale, lax, atonic tissue of a weak, damp Spleen, where laxity and Spleen qi deficiency let fluid pool rather than move. Phlegm-fluid unsettling the Heart, with palpitations and a restless, sleepless spirit riding on that dampness.', 'Dryness and fluid or yin deficiency, which a steady, leaching diuretic only deepens. Frank exhaustion with already scanty fluids, and cold-from-deficiency states that leak fluid downward (copious clear urination, spermatorrhea, or sinking, prolapsing qi), where draining more water is exactly wrong. Not for a dry, thin, depleted picture that needs moistening and consolidating rather than draining.', 'Urinary (its diuretic, damp-leaching core), Spleen and Digestive (strengthens a weak, damp Spleen: poor appetite, loose stool, distension), and Nervous and Cardiovascular (the Heart channel, settling a phlegm-troubled, palpitating, sleepless spirit). Secondarily Immune (pachyman and other beta-glucan polysaccharides are immunomodulatory) and Respiratory (thin, watery phlegm).', 'Fluid retention and edema, scanty or turbid urination, and damp accumulation of every kind. Spleen-damp digestive complaints: poor appetite, abdominal fullness and bloating, loose stools and damp diarrhea. Phlegm-fluid patterns with palpitations, dizziness, and a stuffy chest. Restlessness, anxiety, and insomnia when a damp, phlegm-laden Heart cannot settle. General fatigue and heaviness of a boggy, qi-deficient Spleen.', 'Cold-Damp-Relaxed, the still-water, boggy phenotype: the pale, puffy, heavy person who pools fluid, tires easily, digests weakly, and whose tissues feel waterlogged and lax. The classic phlegmatic. Not for the thin, dry, fluid-depleted (Vata-like) constitution, whom a steady diuretic only desiccates.', 'Kapha, Pitta', 'Vata', 'Dampness and Phlegm-fluid (damp accumulation, edema, phlegm-rheum/tan yin with palpitations and dizziness) and Spleen Qi Deficiency with dampness (poor appetite, loose stools, fatigue, a Spleen too weak to move water). Also disturbed Heart shen riding on dampness and phlegm: palpitations, restlessness, and insomnia (the Fu Shen portion, and Fu Ling paired with Suan Zao Ren). One of the most widely combined herbs in the entire materia medica: Si Jun Zi Tang (Spleen qi), Wu Ling San and Ze Xie Tang (water metabolism), Ling Gui Zhu Gan Tang (phlegm-fluid), Gui Zhi Fu Ling Wan, and Suan Zao Ren Tang.', 'Yin deficiency with dryness or heat and depleted fluids, where a leaching diuretic further injures yin. Cold from deficiency that already leaks fluid downward: frequent, copious, clear urination, spermatorrhea, or sunken, prolapsing qi, for which draining more water is counterproductive. Use cautiously and in reduced amounts where fluids are already scanty.', 'A remarkably benign, food-grade herb; adverse effects are uncommon and usually mild (occasional digestive upset or, rarely, an allergic reaction). Because it is a genuine diuretic, high or prolonged dosing can in theory contribute to fluid or electrolyte loss, so it should not be pushed in the dehydrated, the fluid-depleted, or those on strong pharmaceutical diuretics without oversight. A traditional Chinese pairing caution holds Fu Ling to be incompatible with vinegar (a food-combining, not a pharmacological, caution). Confirm identity: true Fu Ling is the pine-borne sclerotium.', 'No absolute contraindications for the general adult. Relative cautions: yin-deficient dryness and cold-deficiency states with excessive urination, spermatorrhea, or prolapse (TCM); significant dehydration or electrolyte depletion; and concurrent strong diuretic therapy (additive fluid loss). Rigorous human data in pregnancy and lactation are limited (see those fields).', 'Generally regarded as low risk in normal therapeutic and culinary amounts. Fu Ling is a component of several classical formulas used during pregnancy, with no signal of teratogenicity in the traditional or animal literature. However, rigorous modern human safety studies are lacking and it is a functioning diuretic, so high or sustained diuretic dosing should be avoided in pregnancy and any use is best supervised. Modern safety references (AHPA Botanical Safety Handbook, which places Poria among the more benign botanicals; Bensky, Clavey and Stoger, Materia Medica, which lists no pregnancy contraindication) treat it as benign, while consumer monographs (NCCIH-style, RxList/WebMD) note that data are limited and advise caution. Reasonable position: safe in ordinary food-grade amounts, avoid high-dose diuretic use, use under professional guidance.', 'No specific concern is documented, and Fu Ling has a long record of use in nursing women in East Asian practice; Bensky, Clavey and Stoger list no lactation contraindication. Rigorous modern data are limited, so ordinary food-grade amounts under professional guidance are reasonable while high-dose diuretic use is avoided. (AHPA Botanical Safety Handbook; Bensky, Clavey and Stoger; NCCIH-style consumer guidance.)', 'Gentle enough for supervised pediatric use, and Fu Ling appears in many traditional children''s formulas for damp digestive complaints and unsettled sleep. Give low, weight-appropriate doses, preferably as a decoction or cooked into food (congee), and avoid high diuretic dosing in a small child. No specific pediatric toxicity is documented. (Bensky, Clavey and Stoger; AHPA Botanical Safety Handbook.)', 'No well-documented clinical drug interactions; the AHPA Botanical Safety Handbook assigns Poria its lowest interaction concern and no significant pharmacokinetic interactions are established. Theoretical, mechanism-based cautions only: as a diuretic it could add to the fluid- and electrolyte-lowering effect of pharmaceutical diuretics (furosemide, thiazides) and, by that route, interact with lithium (levels rise as sodium and water fall) and with digoxin (potassium shifts); its mild glucose- and lipid-modulating and sedative actions could in theory add to antidiabetic drugs and to sedatives or hypnotics. Monitor rather than prohibit. (Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook.)', 'Decoction is the standard form and Fu Ling is nearly always cooked into a formula; because the active polysaccharides are water-soluble, water extraction (decoction, or long simmering in soups and congee) is preferred over alcohol. Also powdered, taken in capsules, or cooked into medicinal foods. Fu Ling Pi (the peel) is decocted for superficial edema; Fu Shen (the root-bearing core) for calming the spirit.', 'Decoction: 9 to 15 g dried sclerotium daily (up to about 30 g for marked edema), simmered with the formula. Powder or capsules: roughly 1 to 3 g, two to three times daily. Tincture is a weaker choice for this water-soluble fungus; if used, 2 to 4 mL up to three times daily. Well tolerated for extended use as a gentle tonic-diuretic.', 'Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; Rios, Chemical constituents and pharmacological properties of Poria cocos (Planta Medica 2011, PMID 21347995); Lee et al., diuretic effect via renal aquaporin-2 suppression (J Ethnopharmacol 2014, PMID 24933223); NCCIH-style consumer monographs (RxList/WebMD, Poria mushroom).', 'A fungus, not a plant: the medicinal part is the sclerotium, a dense underground storage body of the wood-decay polypore historically named Poria cocos (F.A. Wolf) and now classified as Wolfiporia extensa / Wolfiporia cocos (Polyporaceae, Basidiomycota), with a 2020 revision proposing Pachyma hoelen for the cultivated Asian Fuling. Grown commercially in China by inoculating cut pine logs (the duan mu fa method). Key constituents: beta-glucan polysaccharides (pachyman and its more active derivative pachymaran), which drive the immunomodulatory and much of the diuretic activity, and triterpenoid acids (pachymic, tumulosic, eburicoic, and dehydrotumulosic acids), which carry anti-inflammatory, diuretic (aquaporin-2 down-regulating), and antitumor effects. Modern studies document diuresis via suppression of renal aquaporin-2, sedative, anxiolytic and sleep-improving actions, immune modulation, and glucose-lipid and renal-protective effects. Distinguished from true reishi (Ganoderma) and from Polyporus (Zhu Ling), a stronger, non-tonifying diuretic relative. Traditional grades (Bai and Chi Fu Ling, Fu Ling Pi, Fu Shen) direct the same sclerotium to the Spleen, damp-heat, skin edema, or the spirit.', 'Not in canonical biblical texts and unknown to the ancient Mediterranean world; native to East Asia and also to North America. Its documented tradition is Chinese, entering the materia medica in the Han-era Shen Nong Ben Cao Jing as Fu Ling, ranked among the superior longevity herbs, and it remains one of the most frequently used herbs in Chinese and Japanese (Kampo, as Bukuryo) medicine. The same fungus was eaten by Native Americans and colonists in the American South as tuckahoe or Indian bread.', 'Not at risk. Fu Ling is produced on a very large scale by cultivation on inoculated pine logs (chiefly in Yunnan, Hubei, Anhui, and Guizhou), so demand is met by farming rather than wild harvest, and the North American form is a common, non-threatened wood-decay fungus. Not listed by United Plant Savers (a registry of North American native plants). The main stewardship questions are the pine timber used as substrate and correct species identification, not wild depletion.', 'Neutral and quietly drying: a bland, sweet fungal sclerotium that leaches dampness out through the urine, firms and strengthens a boggy, deficient Spleen, and settles a phlegm-troubled, restless Heart.', 'Refer for edema with breathlessness, chest pain, or swelling that is sudden, one-sided, or rapidly worsening (possible heart, kidney, or liver failure, or a clot); markedly reduced urine output, blood in the urine, or flank pain; unexplained rapid weight change; persistent or severe palpitations; jaundice; or any pregnancy, significant kidney or heart disease, or diuretic, lithium, or digoxin therapy before regular use. Edema is a symptom to diagnose, not simply to drain.', 'Poria: POR-ee-uh. Poria cocos: POR-ee-uh KOH-kos. Fu Ling: foo ling (roughly foo LING).', 'free', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H184', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS07', 'Primary', 'Dampness: its signature action, leaching dampness and fluid out through the urine.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS09', 'Secondary', 'Laxity: firms boggy, lax, waterlogged tissue and a weak Spleen.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS01', 'Secondary', 'Deficiency: gently supplements the Spleen qi deficiency underlying the damp.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS23', 'Secondary', 'Phlegm: transforms thin, watery phlegm-fluid (tan yin).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS19', 'Minor', 'Torpor: rouses a sluggish, damp-laden Spleen and digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS03', 'Primary', 'Dryness: a leaching diuretic worsens fluid and yin dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H184', 'TS04', 'Minor', 'Exhaustion: draining more fluid is wrong in the frankly depleted and spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY09', 'Primary', 'Urinary: diuretic that drains dampness downward through the urine.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY13', 'Primary', 'Spleen: strengthens a weak, damp Spleen; the harmonizing middle herb.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY08', 'Secondary', 'Digestive: poor appetite, bloating, loose stools, damp diarrhea.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY01', 'Secondary', 'Nervous: calms a restless spirit; anxiety and insomnia (Fu Shen).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY06', 'Secondary', 'Cardiovascular: Heart channel, phlegm-fluid palpitations and cardiac edema.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H184', 'SY05', 'Minor', 'Immune: pachyman and beta-glucan polysaccharides are immunomodulatory.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A08', 'Primary', 'Diuretic: leaches out dampness; down-regulates renal aquaporin-2.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A23', 'Primary', 'Tonic: gently strengthens the Spleen and qi while it drains.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A22', 'Secondary', 'Sedative: quiets the Heart and settles a restless spirit.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A04', 'Secondary', 'Immunomodulator: beta-glucan polysaccharides (pachyman, pachymaran).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A26', 'Minor', 'Anxiolytic: eases anxiety and restlessness of a damp, unsettled Heart.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A25', 'Minor', 'Antioxidant: triterpenoid and polysaccharide free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H184', 'A36', 'Minor', 'Hypoglycemic: modulates glucose and lipid metabolism.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP66', 'Primary', 'Fluid retention: edema and damp accumulation, the leading indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP04', 'Secondary', 'Insomnia: calms a phlegm-troubled, restless spirit (Fu Shen).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP10', 'Secondary', 'Anxiety: restlessness and unsettled shen.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP46', 'Secondary', 'Palpitations: phlegm-fluid palpitations (Ling Gui Zhu Gan Tang).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP54', 'Secondary', 'Bloating/flatulence: Spleen-damp abdominal fullness and distension.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP56', 'Secondary', 'Diarrhea: Spleen-damp loose stools and diarrhea (with Bai Zhu).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP07', 'Minor', 'Fatigue: heaviness and tiredness of a boggy, qi-deficient Spleen.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP12', 'Minor', 'Digestive upset: poor appetite and damp digestive complaints.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H184', 'CP65', 'Minor', 'Urinary irritation: scanty, turbid, or uncomfortable urination.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H184', 'P04', 'Primary', 'Decoction: standard, cooked into the formula (water-soluble actives).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H184', 'P12', 'Secondary', 'Added to soups and food: congee and medicinal soups; food-grade.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H184', 'P03', 'Secondary', 'Powdered sclerotium.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H184', 'P02', 'Secondary', 'Capsules of the powder or extract.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H184', 'P01', 'Minor', 'Tincture: weaker for this water-soluble fungus; decoction preferred.');
