INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H184', 'C05', 'Aggravates', 'Minor', 'Thin/Cold/Depleted (Vata-like): a steady diuretic over-dries the thin, dry, depleted.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
