INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H184', 'TCM07', 'Primary', 'Yin Deficiency: a draining diuretic injures depleted yin and fluids.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H184', 'TCM01', 'Secondary', 'Kidney Yang Deficiency: deficiency-cold with copious clear urine or spermatorrhea, do not drain more.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI751', 'H184', 'pregnancy', 'Pregnancy', 'moderate', 'Fu Ling is a functioning diuretic; although it is traditionally used in pregnancy formulas with no teratogenic signal, rigorous modern human safety data are limited, and sustained diuretic dosing could affect maternal fluid balance.', 'Ordinary food-grade amounts are acceptable under professional guidance; avoid high-dose or prolonged diuretic use in pregnancy.', 'AHPA Botanical Safety Handbook (2nd ed.); Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (no pregnancy contraindication listed); NCCIH-style consumer guidance.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI752', 'H184', 'breastfeeding', 'Breastfeeding', 'low', 'No specific concern documented and a long record of traditional use in nursing women; modern human data are limited.', 'Ordinary food-grade amounts under professional guidance are reasonable; avoid high-dose diuretic use.', 'AHPA Botanical Safety Handbook (2nd ed.); Bensky, Clavey and Stoger, Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI753', 'H184', 'drug_interaction', 'Pharmaceutical diuretics (furosemide, thiazides) and, via fluid/electrolyte shifts, lithium and digoxin', 'moderate', 'As a genuine diuretic, Fu Ling may add to the fluid- and electrolyte-lowering effect of pharmaceutical diuretics; the resulting sodium, water, and potassium changes can in theory raise lithium levels and alter digoxin sensitivity. Theoretical, mechanism-based; no clinical cases established.', 'Avoid high-dose combination without oversight; monitor fluid status and drug levels where relevant.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI754', 'H184', 'condition', 'Yin-deficient dryness, dehydration/electrolyte depletion, and cold-deficiency with excessive urination or spermatorrhea (TCM)', 'moderate', 'A leaching diuretic worsens fluid and yin depletion and adds to downward fluid leakage in cold-from-deficiency patterns.', 'Avoid or reduce the dose in these patterns; if used, combine with fluid-nourishing and consolidating herbs.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
