INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H184', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Fu Ling (Poria), listed among the superior, long-life tonic herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Fu Ling; Chen and Chen, Chinese Medical Herbology and Pharmacology, Fu Ling; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H185', 'Sour Jujube Seed (Suan Zao Ren)', 'Ziziphus jujuba Mill. var. spinosa (Bunge) Hu ex H.F. Chow (syn. Ziziphus spinosa Hu; pharmaceutical Semen Ziziphi Spinosae)', 'Rhamnaceae (buckthorn family)', 'Dried ripe seed (kernel) of the wild spiny/sour jujube (Semen Ziziphi Spinosae), traditionally crushed and dry-fried (chao Suan Zao Ren) before use', 'Sweet and sour (suan means sour, and the sourness gives the herb its name), with a faint astringency. The sweet nourishes and moistens the blood, the sour astringes and, with the sweet, generates fluids and settles a restless spirit.', 'Neutral', 'Moist', 'Blood and yin deficiency of the Heart and Liver: the undernourished, depleted nervous system that cannot rest, with insomnia, light dream-disturbed sleep, palpitations, poor memory, and daytime fatigue in a person who is worn down and empty rather than wound up (''tired but empty,'' not repletion). Nervous exhaustion and depletion following overwork, chronic worry, long illness, or blood loss. Deficiency-type night sweats and spontaneous sweating from the laxity of unsecured, undernourished fluids that the sweet-sour seed both nourishes and astringes.', 'Frank excess and repletion, where a sweet, moist, nourishing seed is too cloying. Damp, phlegm-laden, sluggish digestion with loose stools or diarrhea, which the oily seed can worsen. Acute high internal heat or fire (vigorous excess heat) that must first be drained, since a nourishing calmative does not clear real fire. Marked food stagnation with a heavy, full abdomen.', 'Nervous system above all (the calm-spirit, sleep-restoring action). Cardiovascular and Heart (palpitations, the anxious fluttering heart). Hepatic and Liver (nourishes Liver blood and settles the dream-disturbed sleep of Liver-blood deficiency). Secondary Digestive and Spleen (the sweet seed appears in Spleen-supporting formulas, and its oil can burden a weak gut) and the fluid-regulating interface that governs sweating. TCM channels: Heart, Liver, Gallbladder, Spleen.', 'Insomnia, especially difficulty falling asleep and light, easily-broken, dream-disturbed sleep in a depleted, blood-deficient person (the classic remedy of Suan Zao Ren Tang). Anxiety, irritability, and restlessness of emptiness. Heart palpitations and an anxious, fluttering heart. Nervous exhaustion and depletion after overwork, chronic stress, long illness, or blood loss. Poor memory of blood deficiency. Deficiency-type night sweats and spontaneous sweating.', 'The depleted, dried-out, ''tired-but-wired-from-emptiness'' nervous type: thin, pale, blood-deficient, and worn down, who lies awake from exhaustion rather than agitation (a Vata-deficiency picture), and the anxious, over-thinking, sleep-poor melancholic. Not the robust, damp, phlegmatic, sluggish constitution, in whom the sweet moist seed is too cloying, nor a case of frank fiery repletion that needs clearing rather than nourishing.', 'Vata, Pitta', 'Kapha', 'Heart and Liver Blood deficiency: insomnia, dream-disturbed sleep, palpitations, poor memory, and anxiety in a depleted person, the pattern of Suan Zao Ren Tang and a component of Gui Pi Tang and Tian Wang Bu Xin Dan. Heart and Liver Yin deficiency with empty heat: restlessness, irritability, night sweats, and a dry mouth. Deficiency-pattern insomnia where the spirit (shen) is unanchored because blood and yin no longer house it.', 'Excess-heat and fire patterns with vigorous internal heat, which must be drained rather than nourished. Damp-heat and phlegm patterns, and Spleen deficiency with dampness, loose stools, or diarrhea, where the sweet, oily, moist seed is cloying and can deepen the dampness. Acute repletion with strong food stagnation.', 'A gentle, food-grade herb (the seed of an edible fruit) that is well tolerated; the main cautions are its sedative strength and its cloying, moist nature. Because it measurably deepens and prolongs drug-induced sleep, it can add to the effect of sedatives, sleep medicines, and alcohol (see Drug Interactions), and it should be disclosed before surgery or anesthesia. Large doses may cause digestive heaviness or daytime grogginess. Rare allergic reactions to jujube have been reported. Its oily, nourishing quality can aggravate loose stools, diarrhea, or heavy dampness.', 'Concurrent sedative, hypnotic, anxiolytic, or other CNS-depressant drugs and alcohol without supervision (additive sedation). Heavy dampness, phlegm, or diarrhea, and Spleen deficiency with dampness (TCM). Vigorous excess-heat and fire patterns. Known allergy to jujube (Ziziphus). Pregnancy and lactation are best approached cautiously given limited modern safety data (see safety fields).', 'Insufficient modern human safety data; caution advised. Suan Zao Ren is a food-grade seed with a long record of gentle use, and it is not a recognized emmenagogue or uterine stimulant, but controlled data in pregnancy are lacking and some sources advise against use. Modern references (Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica; AHPA Botanical Safety Handbook, 2nd ed.) do not document teratogenicity but counsel caution. Given the herb''s sedative activity and the absence of controlled data, prudent practice is to avoid unsupervised use in pregnancy. Source: Chen and Chen; Bensky, Clavey and Stoger; AHPA Botanical Safety Handbook (2nd ed.).', 'Insufficient modern data; caution advised. There are no controlled lactation studies and no LactMed monograph. The sedative constituents (jujubosides, spinosin) could in theory pass into milk and add to infant drowsiness, so unsupervised use while breastfeeding is best avoided; if used, watch the nursing infant for excess sleepiness. Source: Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook (2nd ed.); no specific human lactation data.', 'Traditionally given, in reduced dose, to children for restless sleep and night terrors, and the seed is food-grade; nonetheless, because of its sedative action and the lack of controlled pediatric data, it should be used in children only under professional guidance at low, weight-appropriate doses, and not combined with sedating medications. Source: Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica.', 'The principal, well-documented interaction is additive central-nervous-system depression. Suan Zao Ren extracts prolong and deepen drug-induced sleep in animal studies (potentiating pentobarbital and thiopental sleeping time) and modulate GABA-A and serotonergic (5-HT1A) signaling, so the herb can add to the sedative effect of benzodiazepines, Z-drugs (zolpidem, zopiclone), barbiturates, sedating antihistamines, opioid analgesics, general anesthetics, anticonvulsants, and alcohol, increasing drowsiness and psychomotor impairment. Its mild blood-pressure-lowering and heart-rate-slowing activity may add to antihypertensive and cardiac-sedative medication. Do not stack with sleep or sedative drugs without supervision, and disclose use before surgery. Evidence is chiefly pharmacological and animal plus mechanistic inference. Source: Chen and Chen, Chinese Medical Herbology and Pharmacology (Suan Zao Ren); Bensky, Clavey and Stoger, Materia Medica; He et al., Ziziphi Spinosae Semen review (Evid Based Complement Alternat Med 2020, article 5861821).', 'Dry-fried seed (chao Suan Zao Ren), crushed, is the classic form and is held to strengthen the calming, sleep-promoting action; the seed is broken before decoction so the actives extract. Decoction is the standard delivery (as in Suan Zao Ren Tang). Powder of the fried seed, often taken at bedtime. Capsules and tablets of concentrated extract. Tincture. Added to congee or soup (jujube-seed porridge). Some traditions distinguish raw seed (said to suit daytime drowsiness) from fried seed (for insomnia), a distinction that is debated.', 'Decoction: 9 to 18 g daily of the crushed seed (commonly 10 to 15 g, up to about 30 g for stubborn insomnia), taken in the evening. Powder of fried seed: 1.5 to 3 g at bedtime. Tincture (1:5): 2 to 4 mL up to three times daily, with the main dose before sleep. Best taken 30 to 60 minutes before bed for insomnia, and given as a nourishing course over weeks for depletion rather than as a single night''s dose.', 'Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacological, Pharmacokinetic and Toxicological Characteristics of Ziziphi Spinosae Semen: A Review,'' Evidence-Based Complementary and Alternative Medicine (2020, article 5861821); Zhang et al., quality-control review of Ziziphus jujuba var. spinosa seed (PubMed 36720435); AHPA Botanical Safety Handbook (2nd ed.).', 'Family Rhamnaceae. Suan Zao Ren is the seed of the wild spiny/sour jujube (Ziziphus jujuba var. spinosa), a thorny shrub-tree of arid northern China, distinct from its cultivated sweet relative the red jujube or Da Zao (Ziziphus jujuba var. jujuba, the fruit) and from the Middle Eastern Christ''s-thorn (Ziziphus spina-christi). The sedative-hypnotic and anxiolytic activity is attributed chiefly to the dammarane saponins jujubosides A and B and the flavonoid C-glycoside spinosin (with swertisin and 6-feruloylspinosin), which modulate GABA-A and serotonergic (5-HT1A) signaling; the seed also contains betulinic and betulonic triterpene acids, sanjoinine cyclopeptide alkaloids, a fixed oil, and phytosterols. Classically it ''nourishes Heart and Liver blood and quiets the spirit (an shen)'' and ''astringes sweat.'' It anchors Suan Zao Ren Tang (with Fu Ling, Zhi Mu, Chuan Xiong, and Gan Cao) for deficiency insomnia and is a component of Gui Pi Tang and Tian Wang Bu Xin Dan. Modern randomized trials and meta-analyses support Suan Zao Ren Tang for insomnia, with efficacy approaching conventional hypnotics but without documented dependence, tolerance, or rebound. A common adulterant is the seed of the related Ziziphus mauritiana (Indian jujube).', 'Not in canonical biblical texts. The genus Ziziphus reaches the biblical and Mediterranean world through the Christ''s-thorn jujube (Ziziphus spina-christi), a Levantine relative traditionally linked to Christ''s crown of thorns, and through the jujube fruit described by Dioscorides and Pliny; Suan Zao Ren itself, however, is the Chinese spiny jujube, whose documented tradition is East Asian, first recorded in the Han-era Shen Nong Ben Cao Jing as Suan Zao and carried through every later Chinese materia medica.', 'Not at risk. The wild spiny jujube is a hardy, abundant, widely distributed shrub-tree across northern and northwestern China and is both wild-harvested and cultivated for its seed, a mainstream, high-volume commodity; seed harvest does not kill the plant. The sourcing concern is authenticity and adulteration (the seed of the related Ziziphus mauritiana, Indian jujube, is a documented substitute) rather than wild-population survival, so confirm species, variety, and geographic origin. Not listed by United Plant Savers (a North American native-plant registry).', 'Neutral and moistening: a sweet-and-sour, food-grade seed that nourishes Heart and Liver blood, houses and settles a spirit left restless by emptiness, and quietly astringes the sweat of depletion.', 'Refer for insomnia with severe or worsening depression, suicidal thoughts, mania, or psychosis; sleep loss with chest pain, breathlessness, or a genuinely irregular or racing heartbeat (rule out cardiac arrhythmia); insomnia driven by untreated sleep apnea, thyroid disease, or another medical condition; persistent insomnia that does not respond after a few weeks; and drenching night sweats with fever, weight loss, or swollen lymph nodes, which need medical evaluation. Refer before combining with prescription sedatives and before use in pregnancy.', 'Sour Jujube: sow-er JOO-joob. Suan Zao Ren: swahn dzow run. Ziziphus jujuba var. spinosa: ZIZ-ih-fus joo-JOO-buh var. spih-NOH-suh.', 'free', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H185', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H185', 'T06');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS21', 'Primary', 'Blood deficiency: nourishes Heart and Liver blood, the core action.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS01', 'Primary', 'Deficiency: Heart and Liver yin-and-blood deficiency underlying the insomnia.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS04', 'Primary', 'Exhaustion: nervous depletion and burnout insomnia, the ''tired but empty'' picture.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS03', 'Secondary', 'Dryness: yin-deficiency dryness; the moist seed nourishes fluids.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS09', 'Secondary', 'Laxity: astringes the lax, unsecured pores that leak deficiency sweat.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS07', 'Primary', 'Dampness: the oily, cloying seed worsens damp, loose stools and diarrhea.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS16', 'Secondary', 'Excess conditions: a nourishing tonic is wrong for frank repletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS05', 'Secondary', 'Excess heat: vigorous fire must be drained, not nourished.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H185', 'TS23', 'Minor', 'Phlegm: heavy phlegm-damp is burdened by a rich, oily seed.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H185', 'SY01', 'Primary', 'Nervous: the calm-spirit, sleep-restoring, anxiolytic action.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H185', 'SY06', 'Primary', 'Cardiovascular: palpitations and the anxious, fluttering heart.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H185', 'SY12', 'Secondary', 'Hepatic/Liver: nourishes Liver blood; dream-disturbed sleep.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H185', 'SY08', 'Minor', 'Digestive/Spleen: used in Spleen-supporting formulas; oil can burden a weak gut.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H185', 'SY02', 'Minor', 'Endocrine/stress axis: deficiency night sweats and stress-linked sleep loss.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A22', 'Primary', 'Sedative: quiets a restless spirit and promotes rest.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A47', 'Primary', 'Hypnotic: deepens and lengthens sleep in deficiency insomnia.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A26', 'Primary', 'Anxiolytic: eases anxiety, irritability, and palpitations of emptiness.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A02', 'Primary', 'Nervine tonic: nourishes and strengthens a depleted nervous system.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A40', 'Secondary', 'Trophorestorative: restores nervous and blood depletion over a course.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A15', 'Secondary', 'Astringent: astringes deficiency night sweats and spontaneous sweating.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A23', 'Secondary', 'Tonic: nourishes Heart and Liver blood and yin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A03', 'Secondary', 'Nervine relaxant: gently relaxes without heavy suppression.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A25', 'Minor', 'Antioxidant: flavonoid and saponin free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H185', 'A37', 'Minor', 'Hypotensive: mild blood-pressure and heart-rate lowering.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP04', 'Primary', 'Insomnia, especially deficiency-type light, dream-disturbed sleep.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP10', 'Primary', 'Anxiety, irritability, and restlessness of emptiness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP46', 'Primary', 'Palpitations, the anxious fluttering heart of blood deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP21', 'Secondary', 'Nervous exhaustion and depletion after overwork or illness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP02', 'Secondary', 'Chronic stress with poor, unrefreshing sleep.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP24', 'Minor', 'Poor memory and mental dullness of Heart-blood deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H185', 'CP07', 'Minor', 'Daytime fatigue from depletion and broken sleep.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H185', 'P04', 'Primary', 'Decoction of the crushed, dry-fried seed (Suan Zao Ren Tang).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H185', 'P03', 'Secondary', 'Powder of the fried seed, taken at bedtime.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H185', 'P02', 'Secondary', 'Capsules or tablets of concentrated extract.');
