INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H185', 'TCM11', 'Secondary', 'Heat/Fire: vigorous excess fire must be drained, not nourished.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI755', 'H185', 'drug_interaction', 'Sedatives, hypnotics, anxiolytics, and other CNS depressants (benzodiazepines, Z-drugs, barbiturates, sedating antihistamines, opioids, anticonvulsants, general anesthetics) and alcohol', 'moderate', 'Suan Zao Ren modulates GABA-A and serotonergic signaling and prolongs drug-induced (barbiturate/pentobarbital) sleep in animal studies, so it adds to the sedative effect of CNS depressants, increasing drowsiness and psychomotor impairment.', 'Do not stack with sleep or sedative drugs or alcohol without supervision; disclose use before surgery and anesthesia.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology (Suan Zao Ren); Bensky, Clavey and Stoger, Materia Medica; He et al., Ziziphi Spinosae Semen review (Evid Based Complement Alternat Med 2020, article 5861821).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI756', 'H185', 'pregnancy', 'Pregnancy', 'moderate', 'A food-grade seed with no recognized emmenagogue or uterine-stimulant action, but modern controlled data in pregnancy are lacking and the herb is sedative.', 'Avoid unsupervised use in pregnancy given the sedative activity and absence of controlled safety data; use only under qualified supervision if at all.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI757', 'H185', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation data; sedative constituents (jujubosides, spinosin) could in theory pass into milk and add to infant drowsiness.', 'Avoid unsupervised use while breastfeeding; if used, monitor the nursing infant for excess sleepiness.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI758', 'H185', 'drug_interaction', 'Antihypertensive and cardiac-sedative medication', 'moderate', 'Mild blood-pressure-lowering and heart-rate-slowing activity may add to antihypertensive and rate-slowing drugs.', 'Monitor blood pressure and heart rate if combined; use caution in those already on such medication.', 'He et al., Ziziphi Spinosae Semen review (Evid Based Complement Alternat Med 2020); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI759', 'H185', 'condition', 'Dampness, phlegm, diarrhea, or Spleen deficiency with dampness (TCM)', 'moderate', 'The sweet, oily, moist seed is cloying and can worsen dampness, loose stools, and diarrhea.', 'Avoid or use with damp-draining, digestive-protective partners in damp, phlegm-laden, or diarrhea-prone patterns.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI760', 'H185', 'other', 'Jujube (Ziziphus) allergy', 'moderate', 'Rare hypersensitivity reactions to jujube have been reported.', 'Avoid in anyone with known allergy to jujube or related Rhamnaceae fruit.', 'He et al., Ziziphi Spinosae Semen review (Evid Based Complement Alternat Med 2020, toxicology section).');
