INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H185', 'EP08', 'neutral', 1, 1, 'moisture: herb damp reinforces the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Suan Zao (sour jujube), listed among the superior (upper-class) tonifying herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Suan Zao Ren; Chen and Chen, Chinese Medical Herbology and Pharmacology, Suan Zao Ren; He, Zhang, Liu et al., ''Botanical, Traditional, Phytochemical, Pharmacologi", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H186', 'Szechuan Lovage (Chuan Xiong)', 'Ligusticum chuanxiong', 'Apiaceae (Umbelliferae)', 'Rhizome', 'Pungent', 'Warm', 'Dry', 'Stagnation (blood stasis), qi stagnation, constriction and tension (spasmodic and cramping pain), cold-type obstruction of the channels.', 'Dryness and fluid deficiency, excess heat and rising yang, excitation and agitation (yin-deficient restlessness).', 'Cardiovascular, Reproductive, Nervous, Musculoskeletal, Hepatic (Liver channel).', 'Headache and migraine, dysmenorrhea, irregular or absent menses, postpartum abdominal pain, blood-stasis pain and traumatic injury, poor circulation (including coronary insufficiency and angina), wind-damp joint pain.', 'Cold, dry, stagnant melancholic phenotype: congealed blood, fixed stabbing or cramping pains, dusky or purplish complexion, cold extremities. Best combined with blood-nourishing, moistening herbs since it is itself drying.', 'Kapha; Vata (cold-stagnation and cramping pain, short-term).', 'Pitta; Vata (drying, with prolonged or high-dose use).', 'Blood stasis and qi stagnation with pain; wind-cold headache; blood-stasis dysmenorrhea, amenorrhea, and postpartum abdominal pain; wind-damp bi (joint) pain.', 'Yin deficiency with heat, ascendant liver yang (yang-rising headache), reckless bleeding or menorrhagia, and profuse sweating from qi or yin deficiency.', 'Strongly ascending and dispersing; large or prolonged doses may cause headache, dizziness, nausea, or vomiting. Discontinue before surgery because of antiplatelet activity. Not appropriate for headaches from rising liver yang or yin deficiency.', 'Avoid in yin deficiency with heat, rising liver-yang headache, active bleeding, heavy menstruation (menorrhagia), and profuse sweating. Contraindicated in pregnancy for self-care.', 'Contraindicated for self-care. Chuan Xiong is a blood-invigorating emmenagogue with uterine-stimulant potential; standard modern Chinese materia medica references list it as contraindicated or for use only under qualified supervision in pregnancy. (Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., 2004; Chen and Chen, Chinese Medical Herbology and Pharmacology, 2004.)', 'Insufficient reliable data; avoid. No established lactation safety profile for this blood-moving herb; use only under professional guidance. (Bensky et al., 2004; Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed., 2013.)', 'Not established; avoid in infants and young children except under qualified practitioner care. Chuan Xiong is a strong blood-mover without pediatric safety data. (Bensky et al., 2004.)', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, DOACs): additive bleeding risk. Tetramethylpyrazine (ligustrazine) inhibits platelet aggregation, and L. chuanxiong inhibits CYP2C9 and CYP1A2, raising free warfarin and prolonging PT, INR, and APTT. Theoretical additive effect with antihypertensives and vasodilators. Monitor closely or avoid, and stop before surgery. (Mills and Bone, 2013; Wang et al., Front. Pharmacol. 2022, PMC9849362; Chen and Chen, 2004.)', 'Decoction (standard); powder (for example Chuan Xiong Cha Tiao San taken with green tea); tincture; sometimes added to medicinal soups. Commonly paired with Dang Gui (blood tonic) to offset its dryness.', 'Decoction: 3-9 g/day. Powder: 1-1.5 g per dose. Tincture (1:5): 2-4 mL up to 3x/day. Favor lower doses; high doses can provoke vomiting or headache.', 'Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanxiong: a chemical, pharmacological and clinical review, Front. Pharmacol. 2025 (PMC11996930).', 'Rhizome of Ligusticum chuanxiong Hort. (Apiaceae). The currently accepted botanical name per WCVP is Conioselinum anthriscoides, with Ligusticum chuanxiong retained as the Chinese Pharmacopoeia and trade name. Key constituents: volatile phthalides (ligustilide, senkyunolide A), the alkaloid tetramethylpyrazine (ligustrazine, a vasodilator and antiplatelet agent), and ferulic acid (antioxidant, antiplatelet). Classically the ''qi herb within the blood'': it moves qi as it invigorates blood, which lets it reach the head (headache and migraine) and the uterus (dysmenorrhea). Chuan Xiong Cha Tiao San is its signature wind-headache formula; Si Wu Tang pairs it with Dang Gui, Shu Di, and Bai Shao for blood-stasis gynecology. Widely studied for cerebral and coronary microcirculation.', 'Not in canonical biblical texts. A Chinese materia medica herb native to Sichuan, first recorded in the Shennong Ben Cao Jing (Han dynasty, c. 200 CE).', 'Low conservation concern. Chuan Xiong is a cultivated cultigen propagated vegetatively from rhizome nodes (ling zi) and grown as an agricultural crop in Sichuan and neighboring provinces; it is not wild-harvested and not listed as at-risk. Source from reputable growers who test for sulfur-dioxide fumigation and heavy metals.', 'Warm, dry, acrid blood-and-qi mover: the aromatic vasodilator that ascends to the head and descends to the blood chamber to unblock stasis and stop pain.', 'Refer for sudden severe or thunderclap headache, headache with neurological deficit or fever and neck stiffness, chest pain or suspected angina, heavy or abnormal uterine bleeding, or any bleeding while on anticoagulants.', 'Szechuan Lovage / Chuan Xiong (chwahn shyong); Ligusticum chuanxiong (lih-GUSS-tih-kum chwahn-shee-ONG).', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H186', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS08', 'Primary', 'Blood stasis, the core indication; disperses congealed blood.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS22', 'Primary', 'Qi stagnation; the ''qi within the blood'' also moves qi.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS12', 'Secondary', 'Vasoconstriction and spasmodic pain; vasorelaxant/antispasmodic.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS18', 'Secondary', 'Tension and cramping pain, especially uterine.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS17', 'Minor', 'Warms cold-type stagnation and obstruction pain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS03', 'Primary', 'Warm, acrid, drying; aggravates dryness and fluid deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS05', 'Primary', 'Warm and ascending; aggravates heat and rising yang.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H186', 'TS10', 'Secondary', 'Ascending and stimulating; aggravates agitation and yin-deficient restlessness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H186', 'SY06', 'Primary', 'Blood mover and vasodilator; cerebral and coronary microcirculation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H186', 'SY03', 'Primary', 'Gynecology: dysmenorrhea, amenorrhea, postpartum pain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H186', 'SY01', 'Secondary', 'Headache and migraine; reaches the head.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H186', 'SY04', 'Secondary', 'Wind-damp joint pain and traumatic injury.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H186', 'SY12', 'Secondary', 'Enters the Liver channel; moves Liver blood and qi.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A27', 'Primary', 'Premier anodyne for blood-stasis pain anywhere in the body.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A10', 'Primary', 'Antispasmodic/vasorelaxant; eases cramping and vascular tension.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A19', 'Primary', 'Emmenagogue; promotes menstruation and clears retained lochia.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A09', 'Secondary', 'Anti-inflammatory (ligustilide, ferulic acid).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A37', 'Secondary', 'Mild hypotensive via tetramethylpyrazine vasodilation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H186', 'A25', 'Secondary', 'Antioxidant (ferulic acid, ligustrazine).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP19', 'Primary', 'Migraine and blood-stasis/wind headache; classic Chuan Xiong Cha Tiao San.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP29', 'Primary', 'Blood-stasis dysmenorrhea; core gynecological use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP20', 'Secondary', 'Irregular menses from blood stasis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP30', 'Secondary', 'Blood-stasis amenorrhea.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP47', 'Secondary', 'Poor circulation, including coronary insufficiency and angina (blood-stasis chest pain).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H186', 'CP77', 'Secondary', 'Blood-stasis pain anywhere and traumatic injury.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H186', 'P04', 'Primary', 'Standard decoction, 3-9 g.');
