INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H186', 'TCM07', 'Primary', 'Warm, acrid, drying; consumes yin and fluids; avoid in yin deficiency with heat.', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H186', 'TCM11', 'Primary', 'Ascending and warming; aggravates fire and rising liver yang; avoid in yang-rising or yin-deficient headache.', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty, c. 200 CE) - Xiong Qiong / Chuan Xiong.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013); Ligusticum chuanx", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI761', 'H186', 'pregnancy', 'Pregnancy', 'absolute', 'Blood-invigorating emmenagogue with uterine-stimulant potential; blood-movers can promote uterine contraction.', 'Avoid for self-care throughout pregnancy. Use only within specific formulas under qualified TCM supervision.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI762', 'H186', 'breastfeeding', 'Breastfeeding', 'moderate', 'No established lactation safety data for this blood-moving herb.', 'Avoid during breastfeeding unless directed by a qualified practitioner.', 'Bensky et al. (2004); Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI763', 'H186', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, DOACs)', 'moderate', 'Additive bleeding risk: tetramethylpyrazine inhibits platelet aggregation, and L. chuanxiong inhibits CYP2C9 and CYP1A2, raising free warfarin and prolonging PT, INR, and APTT.', 'Avoid combination, or monitor INR and bleeding signs closely under professional supervision; discontinue before surgery.', 'Mills and Bone (2013); Wang et al., Front. Pharmacol. 2022 (PMC9849362); Chen and Chen (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI764', 'H186', 'condition', 'Active bleeding, menorrhagia, or bleeding tendency', 'moderate', 'Blood-invigorating and antiplatelet action may worsen hemorrhage.', 'Avoid during active bleeding, heavy menstruation, or known bleeding disorders.', 'Bensky et al. (2004); Chen and Chen (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI765', 'H186', 'condition', 'Yin deficiency with heat / rising liver-yang headache', 'moderate', 'Warm, acrid, ascending herb aggravates heat and upward-rising yang.', 'Avoid, or combine with yin-nourishing and heat-clearing herbs; not for yin-deficient or liver-yang headaches.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004).');
