INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H187', 'TCM11', 'Primary', 'Heat/Fire: a warm herb aggravates heat and fire patterns.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhu / Bai Zhu (Atractylodes), listed among the superior tonic herbs for strengthening the middle and drying dampness. Classical Z", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhu / Bai Zhu (Atractylodes), listed among the superior tonic herbs for strengthening the middle and drying dampness. Classical Z", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bai Zhu; Chen and Chen, Chinese Medical Herbology and Pharmacology, Bai Zhu; AHPA Botanical Safety Handbook (2nd ed.), Atractylodes macrocephala; Herbal Reality, ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bai Zhu; Chen and Chen, Chinese Medical Herbology and Pharmacology, Bai Zhu; AHPA Botanical Safety Handbook (2nd ed.), Atractylodes macrocephala; Herbal Reality, ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H187', 'TCM08', 'Secondary', 'Qi stagnation: a cloying tonic can deepen distension and fullness.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhu / Bai Zhu (Atractylodes), listed among the superior tonic herbs for strengthening the middle and drying dampness. Classical Z", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Zhu / Bai Zhu (Atractylodes), listed among the superior tonic herbs for strengthening the middle and drying dampness. Classical Z", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bai Zhu; Chen and Chen, Chinese Medical Herbology and Pharmacology, Bai Zhu; AHPA Botanical Safety Handbook (2nd ed.), Atractylodes macrocephala; Herbal Reality, ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bai Zhu; Chen and Chen, Chinese Medical Herbology and Pharmacology, Bai Zhu; AHPA Botanical Safety Handbook (2nd ed.), Atractylodes macrocephala; Herbal Reality, ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI766', 'H187', 'pregnancy', 'Pregnancy (self-medication)', 'moderate', 'No modern controlled safety data. Bai Zhu is classically used in TCM during pregnancy to strengthen the Spleen and calm a restless fetus, but consumer references advise against unsupervised use because too little is known.', 'Do not self-prescribe in pregnancy. Use only under a qualified, registered Chinese-herbal practitioner, at appropriate (usually dry-fried, in-formula) doses.', 'Herbal Reality, Atractylodes monograph; AHPA Botanical Safety Handbook (2nd ed.), Atractylodes macrocephala; RxList/WebMD consumer monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI767', 'H187', 'breastfeeding', 'Breastfeeding (self-medication)', 'moderate', 'No modern safety data during lactation. Long traditional food-grade use, but human data are absent.', 'Avoid unsupervised use while breastfeeding; take only under a qualified practitioner.', 'RxList/WebMD consumer monograph (avoid, not enough is known); Herbal Reality, Atractylodes.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI768', 'H187', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Atractylodes macrocephalae polysaccharides lower fasting blood glucose and plasma insulin, which may add to glucose-lowering medication and risk hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined.', 'Front. Pharmacol. review of Atractylodes macrocephala (PMC8595830); RxList/WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI769', 'H187', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Reported anticoagulant/antiplatelet activity of the herb may add to bleeding risk with these drugs.', 'Avoid concurrent therapeutic use without professional supervision and coagulation monitoring.', 'Herbal Reality, Atractylodes; Front. Pharmacol. review (PMC8595830).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI770', 'H187', 'drug_interaction', 'CYP1A2 and CYP2C19 substrates (theophylline, caffeine, omeprazole and other PPIs)', 'moderate', 'In vitro, the rhizome extract and its atractylenolides potently inhibit CYP1A2 and moderately inhibit CYP2C19, inhibit UGT glucuronidation, and activate PXR, potentially altering levels of narrow-margin substrate drugs. Preclinical, not yet clinically confirmed.', 'Use caution and separate dosing; avoid with narrow-margin substrates without supervision.', 'Front. Pharmacol. review of Atractylodes macrocephala (PMC8595830); Herbal Reality, Atractylodes.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI771', 'H187', 'drug_interaction', 'Diuretics', 'low', 'Higher doses of Bai Zhu are genuinely diuretic and may add to the fluid- and electrolyte-losing effect of diuretic drugs.', 'Monitor for excess fluid or electrolyte loss if combined; adjust under supervision.', 'Herbal Reality, Atractylodes; Front. Pharmacol. review (PMC8595830).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI772', 'H187', 'condition', 'Yin deficiency with heat or dryness, and qi stagnation with fullness (TCM)', 'moderate', 'Warm, drying, sweet tonification injures yin and fluids in heat/dryness patterns and can worsen distension in true qi stagnation.', 'Avoid or combine with fluid-preserving and qi-moving herbs in yin-deficient heat, dryness, or stagnation with oppression.', 'Bensky, Clavey and Stoger, Materia Medica, Bai Zhu; Herbal Reality, Atractylodes.');
