INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H188', 'TCM11', 'Primary', 'Heat / Fire; drains Liver and Stomach Fire, as the berberine herbs Huang Lian and Huang Bai do.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H188', 'TCM10', 'Primary', 'Dampness / Phlegm, specifically Damp-Heat; clears Damp-Heat of Liver-Gallbladder (jaundice) and Intestines (dysentery).', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H188', 'TCM03', 'Primary', 'Spleen Qi (and Yang) deficiency with cold; a bitter-cold, draining herb injures a weak, cold digestion.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H188', 'TCM01', 'Secondary', 'Kidney Yang deficiency and interior cold; the coldness further quenches the yang.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Berberis (Berberis vulgaris), the root bark as a bitter tonic, cholagogue, and hepatic for jaundice, biliousness, and atonic dyspepsia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Berberis. Grieve, A Modern Herbal (1931), Barberry. Hoffmann, Medical Herbalism (2003). Mills and Bone, Principles and Practice of Phytotherapy, 2nd ed. (berberine ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI773', 'H188', 'pregnancy', 'Pregnancy', 'absolute', 'Berberine crosses the placenta, carries a uterine-stimulant reputation, and displaces bilirubin from albumin (about tenfold more potent than phenylbutazone in vitro), raising free bilirubin and risking fetal and neonatal kernicterus.', 'Do not use barberry or berberine in any form during pregnancy.', 'MotherToBaby (Berberine), NCBI Bookshelf NBK600384; AHPA Botanical Safety Handbook, 2nd ed. (Berberis vulgaris); RxList / WebMD; Chan E., Biol Neonate 1993 (PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI774', 'H188', 'breastfeeding', 'Breastfeeding', 'absolute', 'Berberine is transferred into breast milk and displaces bilirubin from albumin, risking kernicterus in the bilirubin-vulnerable newborn.', 'Do not use while breastfeeding.', 'MotherToBaby (Berberine), NBK600384; RxList / WebMD; Chan 1993 (PMID 8513024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI775', 'H188', 'pediatric', 'Neonates and young infants', 'absolute', 'Berberine raises free bilirubin by displacing it from albumin and can precipitate kernicterus in newborns; jaundiced or premature infants are at highest risk.', 'Do not give internal barberry or berberine to newborns or infants; reserve any older-child use for qualified guidance and short courses.', 'Chan E., Biol Neonate 1993 (PMID 8513024); RxList / WebMD; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI776', 'H188', 'drug_interaction', 'Cyclosporine', 'absolute', 'Berberine inhibits CYP3A4 and competes at P-glycoprotein, markedly raising cyclosporine blood levels (AUC and Cmax increased roughly 60 to 90 percent in a healthy-volunteer study); cyclosporine has a narrow therapeutic window.', 'Avoid barberry and berberine in anyone taking cyclosporine.', 'Wu X et al., pharmacokinetics of ciclosporin A with berberine in healthy volunteers (2005); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI777', 'H188', 'drug_interaction', 'CYP3A4 / CYP2D6 / P-glycoprotein substrates (statins, calcium-channel blockers, tacrolimus, midazolam, and others)', 'moderate', 'Berberine inhibits CYP3A4 and CYP2D6 and P-glycoprotein, raising serum levels of drugs cleared by these routes.', 'Review the medication list; monitor or avoid with narrow-therapeutic-index substrates.', 'Guo Y et al., berberine effect on CYP3A and P-gp substrates; Brinker; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI778', 'H188', 'drug_interaction', 'Antidiabetic drugs (metformin, insulin, sulfonylureas)', 'moderate', 'Berberine independently lowers blood glucose and may add to antidiabetic drugs, risking hypoglycemia.', 'Monitor blood sugar; adjust medication with the prescriber; discontinue before surgery.', 'Yin J et al., Metabolism 2008 (berberine in type 2 diabetes); RxList (berberine interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI779', 'H188', 'condition', 'Hyperbilirubinemia, hemolytic states, and G6PD deficiency; cold, weak, deficient digestion', 'moderate', 'Berberine raises free bilirubin (unsafe where bilirubin is already high or hemolysis is present), and, energetically, a cold, draining bitter injures a cold, deficient, hypofunctional digestion.', 'Avoid in significant jaundice, hemolysis, or G6PD deficiency; in cold, deficient digestion use only briefly, in small dose, with warming correctives, if at all.', 'Chan 1993 (PMID 8513024); traditional energetic assessment (King''s American Dispensatory, 1898); AHPA Botanical Safety Handbook.');
