INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H189', 'TCM04', 'Minor', 'Secures the Lung; checks chronic productive cough and hoarseness.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "locator": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H189', 'TCM07', 'Primary', 'Yin deficiency with dryness (dry cough, dry stool); the warming drying nature injures fluids.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "locator": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H189', 'TCM11', 'Secondary', 'Frank Heat or Fire; the warming virya can aggravate unless cooled and moistened.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bibhitaka (dried fruit rind of Terminalia bellirica). Official monograph, Government of India, Ministry of AYUSH.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "locator": "Bhavaprakasha Nighantu (Haritakyadi varga) and the Charaka and Sushruta Samhitas (classical descriptions of Vibhitaki and Triphala). Kumari S, et al. Terminalia bellirica (Gaertn.) Roxb. (Bahera) in health and disease: a systematic and comp", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI780', 'H189', 'pregnancy', 'Pregnancy', 'moderate', 'Classed possibly unsafe by mouth in pregnancy; a mildly laxative, purgative myrobalan traditionally cautioned in pregnancy.', 'Avoid in pregnancy.', 'WebMD (Terminalia bellirica, possibly unsafe in pregnancy); Drugs.com (Terminalia); traditional Ayurvedic contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI781', 'H189', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient modern safety data and a traditional report that the fruit reduces breast milk.', 'Avoid while breastfeeding; prefer a better-documented remedy.', 'WebMD (insufficient information); traditional Ayurvedic sources.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI782', 'H189', 'pediatric', 'Young children (fruit); seed kernel at any age', 'moderate', 'No formal pediatric safety data; the seed kernel is mildly narcotic and causes drowsiness.', 'Use the fruit rind only in small practitioner-guided doses in children; never give the seed kernel.', 'Precautionary practice; WebMD / Drugs.com (no pediatric data); Nighantu tradition (seed kernel narcotic).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI783', 'H189', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'The fruit lowers blood glucose and may add to antidiabetic drugs, risking hypoglycemia.', 'Monitor blood sugar closely; adjust medication with the prescriber; stop about 2 weeks before surgery.', 'WebMD (Terminalia bellirica interactions, moderate); Drugs.com (Terminalia).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI784', 'H189', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Reported antiplatelet, antithrombotic, and thrombolytic activity may add to bleeding risk.', 'Combine only with caution and monitoring; discontinue about 2 weeks before surgery.', 'Kumari et al. 2020 review (antiplatelet/thrombolytic activity); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI785', 'H189', 'drug_interaction', 'Urate-lowering drugs (allopurinol, febuxostat)', 'low', 'Inhibits xanthine oxidase and lowers uric acid; effects may be additive.', 'Monitor uric acid if combined; adjust dosing with the prescriber.', 'Usharani et al. hyperuricemia clinical studies (2016, PMC4922806; 2020, PMC7493401); Kumari et al. 2020 review.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI786', 'H189', 'condition', 'Dry, deficient (Vata) and yin-deficient dryness constitutions', 'low', 'The warming, drying, astringent nature parches dry tissue, hardens a dry bowel, and injures fluids.', 'Use with an unctuous carrier (ghee, honey, warm water) or within Triphala; avoid dry, single-herb use in these states.', 'Traditional energetic assessment (Ayurvedic Pharmacopoeia of India; Bhavaprakasha Nighantu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI787', 'H189', 'condition', 'Male subfertility (preclinical/animal data)', 'low', 'Preclinical animal (male rat) studies report reduced circulating androgen with lowered sperm count and motility; no human confirmation.', 'Men actively seeking conception may prefer to use cautiously and limit prolonged high-dose use.', 'Preclinical animal antispermatogenic/antisteroidogenic studies of Terminalia bellirica extract; preliminary, no human data.');
