INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H190', 'TCM01', 'Primary', 'Kidney Yang deficiency with cold (copious clear urination, cold limbs); a cold, cooling sour berry injures yang and chills a bladder that needs warming.', '{"title": "Grieve, M. A Modern Herbal (1931), Cranberry entry (historical Western/North American description of the fruit and its urinary and dietary use). This is a brief historical anchor; the substantive clinical evidence is modern and is cited in ", "locator": "Grieve, M. A Modern Herbal (1931), Cranberry entry (historical Western/North American description of the fruit and its urinary and dietary use). This is a brief historical anchor; the substantive clinical evidence is modern and is cited in ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Cranberry: Usefulness and Safety (nccih.nih.gov). Williams G, et al. Cranberries for preventing urinary tract infections. Cochrane Database of Systematic Reviews 2023 (about a 30 percent relative reduction in UTI in susceptible group", "locator": "NCCIH, Cranberry: Usefulness and Safety (nccih.nih.gov). Williams G, et al. Cranberries for preventing urinary tract infections. Cochrane Database of Systematic Reviews 2023 (about a 30 percent relative reduction in UTI in susceptible group", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H190', 'TCM07', 'Minor', 'Yin deficiency with dryness; the drying astringency can aggravate fluid depletion unless combined with moistening herbs.', '{"title": "Grieve, M. A Modern Herbal (1931), Cranberry entry (historical Western/North American description of the fruit and its urinary and dietary use). This is a brief historical anchor; the substantive clinical evidence is modern and is cited in ", "locator": "Grieve, M. A Modern Herbal (1931), Cranberry entry (historical Western/North American description of the fruit and its urinary and dietary use). This is a brief historical anchor; the substantive clinical evidence is modern and is cited in ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "NCCIH, Cranberry: Usefulness and Safety (nccih.nih.gov). Williams G, et al. Cranberries for preventing urinary tract infections. Cochrane Database of Systematic Reviews 2023 (about a 30 percent relative reduction in UTI in susceptible group", "locator": "NCCIH, Cranberry: Usefulness and Safety (nccih.nih.gov). Williams G, et al. Cranberries for preventing urinary tract infections. Cochrane Database of Systematic Reviews 2023 (about a 30 percent relative reduction in UTI in susceptible group", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI788', 'H190', 'drug_interaction', 'Warfarin and other coumarin anticoagulants', 'moderate', 'Case reports and pharmacovigilance signals of raised INR and bleeding with cranberry juice plus warfarin; one study raised INR AUC by about 30 percent. Evidence is mixed but the safety signal prompted regulatory warnings.', 'Keep cranberry intake modest and stable and monitor INR closely; avoid large or concentrated cranberry products while on warfarin.', 'MHRA/CSM warfarin-cranberry advisory (2004); NCCIH (Cranberry); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI789', 'H190', 'condition', 'History of calcium-oxalate kidney stones (urolithiasis)', 'moderate', 'The fruit is high in oxalate, and heavy or concentrated intake can raise urinary oxalate in susceptible people, potentially favoring calcium-oxalate stone formation.', 'People with a history of calcium-oxalate stones should avoid concentrated cranberry supplements and limit large juice intake; maintain good hydration.', 'NCCIH (Cranberry); Terris et al., urinary oxalate with cranberry supplementation; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI790', 'H190', 'condition', 'Active, febrile, or complicated UTI and pyelonephritis', 'moderate', 'Cranberry acts by anti-adhesion and is preventive, not bactericidal; it does not clear an established infection and relying on it can delay effective antibiotic treatment of an ascending or systemic infection.', 'Use cranberry for prevention only; seek prompt medical evaluation and antibiotics for active, febrile, or complicated UTI, and for any UTI in pregnancy, men, children, or the immunocompromised.', 'Cochrane review (Williams et al. 2023); NCCIH (Cranberry); standard clinical guidance.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI791', 'H190', 'pregnancy', 'Pregnancy', 'low', 'Food and juice amounts appear safe; concentrated supplements are less well studied. A survey of about 400 pregnant women found no adverse events, and AHPA classes the fruit as Class 1.', 'Food and juice amounts are considered acceptable; use high-dose supplements only with clinician advice, and treat any UTI in pregnancy medically.', 'NCCIH (Cranberry); Wing et al., cranberry-in-pregnancy survey; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI792', 'H190', 'breastfeeding', 'Breastfeeding', 'low', 'Consumed as a common food with low toxicity; moderate consumption during lactation is regarded as low risk, though data on concentrated extracts are limited.', 'Food and juice amounts are acceptable while breastfeeding; concentrated supplements are less well characterized.', 'NCCIH (Cranberry); e-lactation / LactMed-style assessment (cranberry, low risk).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI793', 'H190', 'other', 'Salicylate or aspirin sensitivity', 'low', 'Cranberry contains salicylates; large medicinal amounts could provoke reactions in genuinely salicylate-sensitive individuals.', 'Those with true salicylate or aspirin allergy should avoid large medicinal amounts.', 'Brinker, Herb Contraindications and Drug Interactions; salicylate-content analyses of cranberry.');
