INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI794', 'H191', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional emmenagogue and possible abortifacient reputation; safety of medicinal (extract or essential-oil) doses is unknown, and animal data raise fetal-development concerns.', 'Avoid medicinal and essential-oil doses in pregnancy; culinary/food amounts are likely safe.', 'NCCIH (Boswellia); WebMD/RxList (Boswellia); Tiran, Aromatherapy in Midwifery Practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI795', 'H191', 'breastfeeding', 'Breastfeeding', 'moderate', 'No specific lactation safety data for medicinal amounts of boswellia or frankincense.', 'Avoid medicinal doses while breastfeeding; prefer a better-documented remedy.', 'NCCIH (Boswellia; little known in medicinal amounts while breastfeeding).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI796', 'H191', 'pediatric', 'Infants and children (internal use)', 'moderate', 'No established pediatric dosing and no NCCIH pediatric guidance; safety not established.', 'Reserve internal use for qualified practitioner guidance; aromatic and well-diluted topical use is lower-risk.', 'NCCIH (no pediatric guidance); precautionary practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI797', 'H191', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Boswellia can slow warfarin metabolism and may add to antiplatelet or bleeding risk; the best-documented interaction concern.', 'Monitor INR and bleeding; combine only with caution and prescriber oversight.', 'WebMD/RxList (Boswellia, warfarin); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI798', 'H191', 'drug_interaction', 'Drugs metabolized by CYP3A4/CYP3A5 and CYP2C9 (statins, calcium-channel blockers, cyclosporine and other immunosuppressants)', 'low', 'Boswellic acids inhibit CYP3A4/5 and CYP2C9 in vitro, so levels of substrate drugs could theoretically rise; shown in the laboratory, not confirmed in humans.', 'Monitor for enhanced drug effect if combined; adjust with the prescriber.', 'In-vitro CYP3A4/5 and CYP2C9 inhibition study (Applied In Vitro Toxicology, 2018); NCCIH; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI799', 'H191', 'drug_interaction', 'Asthma and leukotriene-modifying medicines (montelukast, zileuton); immunosuppressants', 'low', 'Boswellia inhibits 5-lipoxygenase and modulates immune activity, so effects may be additive with anti-leukotriene or immune-modulating drugs.', 'Do not alter prescribed asthma or immunosuppressant therapy; combine only with medical supervision.', 'NCCIH (asthma-medicine caution); Ammon, Boswellic acids review (Phytomedicine).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI800', 'H191', 'condition', 'Acute hot inflammation and dry, yin-deficient or depleted (Vata) constitutions', 'low', 'A warming, drying, astringent resin can aggravate acute hot inflammation and parch dry, yin-deficient, or Vata-depleted tissue.', 'Avoid in acute hot, red inflammation; in dry constitutions use with an unctuous carrier or a better-suited cooling herb.', 'Traditional energetic assessment (Herbal Reality; Bensky, Ru Xiang).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI801', 'H191', 'condition', 'Weak or easily nauseated digestion (Spleen/Stomach weakness)', 'low', 'The raw resin is harsh on the stomach and can cause nausea, reflux, epigastric discomfort, and diarrhea.', 'Take with food or reduce the dose; discontinue if the resin is poorly tolerated.', 'WebMD/RxList (Boswellia GI side effects); Bensky, Materia Medica (Ru Xiang harsh on a weak stomach).');
