INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI802', 'H192', 'pregnancy', 'Pregnancy', 'absolute', 'Rated likely unsafe in medicinal (greater-than-food) oral amounts; documented concern for promoting miscarriage. The diuretic, renally active oil adds theoretical uterine and renal stress; concentrated-oil safety data are lacking.', 'Avoid internal medicinal use and the concentrated essential oil during pregnancy.', 'Natural Medicines Comprehensive Database (white sandalwood / Santalum album), 2024');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI803', 'H192', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable data on safety during lactation.', 'Avoid medicinal internal use while breastfeeding.', 'Natural Medicines Comprehensive Database (white sandalwood), 2024');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI804', 'H192', 'condition', 'Kidney disease, nephritis, or renal impairment', 'absolute', 'The essential oil is excreted through and can irritate or damage the renal parenchyma; nephrotoxic in large or prolonged internal doses, with kidney damage possible when used longer than about six weeks.', 'Do not use internally in existing kidney disease; limit any internal oil course to under six weeks; avoid in anyone with a history of renal disease or stones.', 'Natural Medicines Comprehensive Database (white sandalwood), 2024; Dwivedi et al., Food and Chemical Toxicology, 2008');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI805', 'H192', 'drug_interaction', 'Lithium', 'moderate', 'Diuretic effect may reduce renal clearance of lithium, raising serum lithium levels and the risk of toxicity.', 'Avoid combining; if used, monitor serum lithium and adjust dose under medical supervision.', 'Natural Medicines Comprehensive Database (white sandalwood), 2024');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI806', 'H192', 'drug_interaction', 'Other diuretics and nephrotoxic drugs (e.g., aminoglycosides, high-dose NSAIDs)', 'moderate', 'Additive renal burden with a renally excreted, potentially nephrotoxic oil (theoretical/mechanistic).', 'Avoid concurrent internal medicinal use; monitor renal function if unavoidable.', 'Mechanistic extrapolation from renal-excretion pharmacology; Natural Medicines Comprehensive Database, 2024');
