INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H193', 'TCM07', 'Minor', 'Yin deficiency with dryness: a drying herb can further injure the fluids.', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), ''Adhatoda vasica'' (Malabar Nut, Vasaka), the leaf.", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), ''Adhatoda vasica'' (Malabar Nut, Vasaka), the leaf."}'::jsonb, '{"title": "Grieve, M., A Modern Herbal (1931), ''Adhatoda Vasica'' (Malabar Nut); Nadkarni, Indian Materia Medica, ''Adhatoda vasica''; The Ayurvedic Pharmacopoeia of India, Part I, Vasa (Adhatoda vasica / Justicia adhatoda), leaf; Claeson, Malmfors, Wikm", "locator": "Grieve, M., A Modern Herbal (1931), ''Adhatoda Vasica'' (Malabar Nut); Nadkarni, Indian Materia Medica, ''Adhatoda vasica''; The Ayurvedic Pharmacopoeia of India, Part I, Vasa (Adhatoda vasica / Justicia adhatoda), leaf; Claeson, Malmfors, Wikm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI807', 'H193', 'pregnancy', 'Pregnancy (all medicinal doses)', 'absolute', 'The leaf''s principal alkaloid vasicine (peganine) is a uterine stimulant with oxytocic activity comparable to oxytocin and a documented abortifacient effect, enhanced under estrogen priming.', 'Do not use Vasa in any medicinal form during pregnancy. Avoid entirely; refer to appropriate care.', 'Vasicine, alkaloid of Adhatoda vasica, a promising uterotonic abortifacient (PMID 750386); Claeson et al., J Ethnopharmacol 2000;72(1-2):1-20; The Ayurvedic Pharmacopoeia of India.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI808', 'H193', 'breastfeeding', 'Breastfeeding (therapeutic doses)', 'moderate', 'No reliable modern data on Vasa during lactation; the leaf carries potent quinazoline alkaloids (vasicine, vasicinone).', 'Avoid therapeutic and medicinal-strength doses while breastfeeding in the absence of safety data.', 'Insufficient modern data; precautionary (Brinker, Herbal Contraindications and Drug Interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI809', 'H193', 'drug_interaction', 'Uterotonic drugs (oxytocin, ergometrine, prostaglandin analogues)', 'moderate', 'Vasicine has intrinsic oxytocic/uterine-stimulant activity that can add to that of uterotonic drugs.', 'Do not combine Vasa with uterotonic drugs except under obstetric supervision.', 'Claeson et al., J Ethnopharmacol 2000;72(1-2):1-20; PMID 750386.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI810', 'H193', 'drug_interaction', 'Antihypertensive and cardiac medication', 'low', 'Vasicine and vasicinone show hypotensive and cardiac-depressant activity in animal studies; additive effects with antihypertensives or cardiac glycosides are theoretically possible.', 'Use with caution and monitor in those on blood-pressure or cardiac drugs; human interaction data are limited.', 'Claeson et al., J Ethnopharmacol 2000;72(1-2):1-20 (animal pharmacology; limited human data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI811', 'H193', 'pediatric', 'Infants and young children', 'moderate', 'Traditional low-dose pediatric use is long-established, but modern pediatric safety data for the alkaloid-bearing leaf are limited.', 'Use only low, traditional doses (leaf-juice-with-honey or syrup) under qualified guidance; avoid in infants and avoid medicinal doses without supervision.', 'Limited modern pediatric data; precautionary (traditional use per Kirtikar and Basu, Indian Medicinal Plants, 1918).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H193', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Kirtikar and Basu, Indian Medicinal Plants (1918), ''Adhatoda vasica'' (Malabar Nut, Vasaka), the leaf.", "locator": "Kirtikar and Basu, Indian Medicinal Plants (1918), ''Adhatoda vasica'' (Malabar Nut, Vasaka), the leaf."}'::jsonb, '{"title": "Grieve, M., A Modern Herbal (1931), ''Adhatoda Vasica'' (Malabar Nut); Nadkarni, Indian Materia Medica, ''Adhatoda vasica''; The Ayurvedic Pharmacopoeia of India, Part I, Vasa (Adhatoda vasica / Justicia adhatoda), leaf; Claeson, Malmfors, Wikm", "locator": "Grieve, M., A Modern Herbal (1931), ''Adhatoda Vasica'' (Malabar Nut); Nadkarni, Indian Materia Medica, ''Adhatoda vasica''; The Ayurvedic Pharmacopoeia of India, Part I, Vasa (Adhatoda vasica / Justicia adhatoda), leaf; Claeson, Malmfors, Wikm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, true);
