INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H194', 'Anise (Aniseed)', 'Pimpinella anisum', 'Apiaceae (Umbelliferae; the carrot and parsley family)', 'Seed (the dried ripe fruit, a schizocarp of two mericarps); the steam-distilled essential oil', 'Sweet, Pungent', 'Warm', 'Dry', 'Stagnation (trapped wind, gas, bloating, and a sluggish, distended gut that will not move); Tension and Constriction (the cramping, colicky spasm of the gut wall and airway that the sweet aromatic oil relaxes, the classic griping colic including infant colic); Cold (a cold, underactive, poorly warmed stomach with weak appetite and gassy digestion); Phlegm (a boggy, cold, catarrhal chest with stuck bronchial mucus that the warm aromatic loosens and expels); Torpor (an atonic, cold, slow gut roused by the warming aromatic), in smaller measure.', 'Excess Heat and Dryness: the warming, drying, sweet-pungent aromatic aggravates hot, inflamed, or already dry, depleted terrain. Use cautiously in hyperacid, burning, or acutely inflamed digestion, in dry, irritable, spasmodic dry cough without congestion, and in thin, heat-signed constitutions where a moving warm carminative is not wanted.', 'Digestive (primary: stomach and intestines, appetite, gas, spasm, and colic); Respiratory (a signature warm aromatic expectorant and antitussive for bronchial catarrh, spasmodic and irritable cough, and congested chest); Reproductive (traditional galactagogue and emmenagogue with mild estrogenic activity; eases menstrual cramp and menopausal vasomotor symptoms); Nervous (mild sedative and antispasmodic reputation), in smaller measure.', 'Flatulent dyspepsia with bloating, belching, and trapped wind; spasmodic, colicky abdominal pain, including infant colic and griping; sluggish, cold, low-appetite digestion; nausea. Respiratory: productive bronchial catarrh and congested, spasmodic, or irritable cough, where the warm aromatic loosens phlegm and eases the cough reflex, and it is a classic ingredient of cough and gripe syrups. Reproductive: traditionally to promote and enrich the flow of milk in nursing mothers, to ease menstrual cramping and scanty menses, and, on modern trial evidence, to soften menopausal hot flushes.', 'The cold, damp, atonic phenotype: a sluggish, gassy, cramping, poorly warmed stomach with bloating and trapped wind, and a cold, boggy, catarrhal chest. Best for the Phlegmatic and for the cold, nervous, gassy (Vata-like) type; the warming, drying aromatic aggravates the hot, bilious Choleric and the robust hot (Pitta-like) constitution.', 'Kapha, Vata', 'Pitta', 'Cold and Qi Stagnation of the middle jiao with Spleen and Stomach cold and cold-damp: distension, flatulence, colicky pain, poor appetite, and gurgling, together with cold, phlegm-damp congestion of the Lung. The warm, sweet, aromatic seed moves stuck Qi, warms the center, transforms cold phlegm, and directs Qi. True anise (Pimpinella anisum) is not a classical Chinese materia medica herb; the Chinese aromatic Da Hui Xiang is star anise (Illicium verum), a botanically unrelated plant, so these are functional correspondences.', 'Heat or Fire patterns and Yin deficiency with heat or dryness: the warming, drying, aromatic nature can stoke heat and further dry a yin-deficient, heat-signed terrain (burning epigastric pain, thirst, dry irritable cough, red dry tongue).', 'Generally very well tolerated at culinary and normal medicinal seed doses. Anise essential oil is potent and rich in trans-anethole: high or undiluted oral doses can irritate the gut and, rarely, cause nausea; neat oil can irritate skin and mucous membranes and provoke allergic contact reactions (anethole is a recognized sensitizer). The seed and oil carry mild estrogenic activity, so use is cautious in estrogen-sensitive conditions. The oil contains a small amount of estragole (methyl chavicol), a compound genotoxic and carcinogenic in rodents at high exposure, so do not exceed recommended essential-oil doses or use the concentrated oil long term. Its warming, drying quality can aggravate hot, hyperacid, or acutely inflamed digestion and a dry, irritable cough. Do not confuse true anise (Pimpinella anisum) with star anise: Chinese star anise (Illicium verum) is a distinct but food-safe substitute, whereas Japanese star anise (Illicium anisatum) is neurotoxic and has caused seizures in infants given contaminated star-anise teas.', 'Avoid concentrated, therapeutic-strength preparations and the essential oil in pregnancy (culinary food amounts are recognized as safe). Avoid the neat essential oil internally in infants and young children. Use cautiously in known estrogen-sensitive conditions (estrogen-receptor-positive breast, uterine, or ovarian cancer, endometriosis, uterine fibroids) given the seed''s mild estrogenic action. Use cautiously in hot, hyperacid, or acutely inflamed digestion and in dry, irritable, unproductive cough. Discontinue if an allergic or contact-sensitivity reaction occurs; cross-reactivity is possible in people allergic to other Apiaceae (fennel, caraway, dill, celery, coriander) or to anethole.', 'Culinary and food amounts are recognized as safe (anise is GRAS in the United States). Concentrated medicinal doses and the essential oil are best avoided in pregnancy: anise seed carries traditional emmenagogue and abortifacient use, its anethole and dimeric phytoestrogens (dianethole, photoanethole) are mildly estrogenic, and the essential oil contains estragole, which is genotoxic and carcinogenic in rodents at high exposure. Adequate human safety data at therapeutic strength are lacking. Source: AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions (emmenagogue/estrogenic caution); EMA/HMPC Assessment Report on Pimpinella anisum L. fructus and aetheroleum (estragole exposure limits); US FDA GRAS status.', 'Anise has a long tradition as a galactagogue, and anethole is thought to raise prolactin by competitively antagonizing dopamine; a meta-analysis found a small increase in milk volume versus no treatment. Moderate, occasional culinary and tea use is generally considered compatible with breastfeeding. However, excessive maternal intake of an anise-containing herbal tea was linked to toxicity in two breastfed newborns consistent with anethole, and high-dose trans-anethole can both reduce milk output and cause neurotoxicity (seizures) in the mother. Avoid the concentrated essential oil and do not consume large medicinal quantities while nursing. Source: LactMed (NIH Drugs and Lactation Database), Anise monograph.', 'The seed as a mild tea or a dilute, sweetened syrup has a long history of use for infant and childhood colic, wind, and cough, and small culinary amounts are safe. Do not give the neat, concentrated essential oil internally to infants or young children owing to the risk of gut and mucous-membrane irritation and the potency of trans-anethole. Critically, avoid star-anise preparations in infants: products sold as star anise for colic have caused neurological toxicity and seizures in babies because Japanese star anise (Illicium anisatum), which is neurotoxic, is difficult to distinguish from and has adulterated Chinese star anise. Reserve essential-oil dosing for adults or qualified pediatric guidance. Source: LactMed; NCCIH; German Commission E (aniseed for dyspeptic complaints and respiratory catarrh); AAP/FDA case reports on star-anise neonatal toxicity.', 'Estrogens, hormonal contraceptives, and hormone-replacement therapy: anise is mildly estrogenic and may add to or interfere with estrogen therapy; use cautiously and coordinate with a clinician. Tamoxifen and other anti-estrogen or estrogen-modulating agents: by affecting estrogen activity, anise could theoretically blunt their effect. Antidiabetic agents (insulin, oral hypoglycemics): anise has shown mild blood-glucose-lowering activity, so additive hypoglycemia is possible; monitor blood sugar. Sedatives and CNS depressants: possible mild additive sedation given anise''s mild sedative reputation. Theoretical additive effect with anticoagulant or antiplatelet drugs from the seed''s coumarin content, though no clinical bleeding interaction is documented. Otherwise no well-documented interactions (limited data). Sources: WebMD and RxList Anise monographs; Herbal Reality (Aniseed); Mediscript, Herb-Drug Interactions (Williamson, Driver, Baxter); Mills and Bone, Principles and Practice of Phytotherapy.', 'Crushed-seed infusion or tea (the traditional aniseed water for wind, colic, and cough); tincture of the seed; ground seed powder; sweetened syrup or a gripe-style water for cough and childhood colic (dilute, not neat oil); the steam-distilled essential oil in cough, carminative, and lozenge products; culinary use in breads, cakes, confections, and spiced beverages (the anethole aroma of ouzo, anisette, and similar drinks).', 'Seed infusion: 1-2 teaspoons (about 2-4 g) of freshly crushed seed per cup, up to 3x daily, taken warm before or after meals; German Commission E gives an average daily dose of about 3 g of seed. Tincture (1:5, 45 percent): 1-3 mL, 3x daily. Powdered seed: 1-3 g up to 3x daily. Essential oil: 0.05-0.2 mL (about 1-4 drops) daily, well diluted, for adults only; Commission E cites 0.3 g oil per day. Do not exceed recommended oil doses because of the estragole content.', 'King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).', 'The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, mild spasmodic GI complaints, flatulence, and catarrh of the upper respiratory tract). EMA/HMPC Assessment Report on Pimpinella anisum L., fructus and aetheroleum. LactMed (NIH Drugs and Lactation Database), Anise. Tabanca N, et al. Estrogenic activity of isolated compounds and essential oils of Pimpinella species. Planta Med 2004;70(8):728-735 (PMID 15368661). Mills S, Bone K, Principles and Practice of Phytotherapy; Hoffmann D, Medical Herbalism; Grieve M, A Modern Herbal (1931), Anise.', 'Apiaceae. Key constituents: 1.5-6 percent essential oil (typically 2-3 percent) dominated by trans-anethole (roughly 80-93 percent), with estragole/methyl chavicol (roughly 1-3 percent), anisaldehyde, anise ketone, pseudoisoeugenol esters, and small amounts of limonene and pinenes; the estrogenic dimers dianethole and photoanethole; about 8-11 percent fixed oil; protein; coumarins (scopoletin, umbelliferone, bergapten); and flavonoids. trans-Anethole accounts for the sweet aroma and the carminative, antispasmodic, expectorant, and estrogenic actions. German Commission E and ESCOP approve aniseed for dyspeptic complaints and catarrh of the respiratory tract. Anise has been valued and cultivated around the Mediterranean since antiquity. Distinguish anise from three aroma-alikes it is often confused with: fennel (Foeniculum vulgare), anise hyssop (Agastache foeniculum), and star anise (Illicium verum), all botanically distinct despite the shared anethole/licorice scent.', 'Not securely named in the canonical biblical texts. The King James Version of Matthew 23:23 reads that the Pharisees tithed ''mint and anise and cumin,'' but the Greek word rendered ''anise'' is anethon (Strong''s Greek 432), which is dill (Anethum graveolens), not true anise; modern translations (NIV, ESV, NASB, RSV) correctly read ''dill.'' True anise (Pimpinella anisum) is instead documented across the classical Mediterranean corpus: Dioscorides describes it in De Materia Medica (1st century CE), Pliny the Elder praises it highly in his Natural History as a breath-sweetener, digestive, and sleep aid, and the Romans baked the spiced ''mustaceum'' wedding cake with it. Native to the eastern Mediterranean and western Asia and cultivated from ancient Egypt and Greece onward.', 'A widely cultivated culinary and commercial crop (the Mediterranean basin, the Middle East, Egypt, Turkey, Spain, and India); not threatened and not on the United Plant Savers at-risk list, which tracks native North American medicinals. Prefer organically grown seed to limit pesticide load. No wild-harvest conservation concern.', 'Warm, dry, and sweetly aromatic: a moving, relaxing carminative and warm expectorant that breaks up trapped wind, eases colicky spasm, and loosens a cold, congested chest.', 'Refer for severe, persistent, or worsening abdominal pain; vomiting, blood in the stool or vomit, black tarry stools, unexplained weight loss, jaundice, or high fever; dyspepsia with alarm features (difficulty swallowing, anemia, GI bleeding, or new onset over age 55); and for cough that is persistent beyond a few weeks, produces blood, or is accompanied by breathlessness, chest pain, or high fever. For infants, refer any colic with fever, vomiting, bloody stool, poor feeding, or failure to thrive rather than treating at home, and never use star-anise preparations in babies.', 'Anise = AN-iss; Pimpinella anisum = pim-pih-NEL-ah an-EYE-sum', 'free', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H194', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H194', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS08', 'Primary', 'Moves stagnation: disperses trapped wind, gas, and bloating in a stuck, distended gut.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS18', 'Primary', 'Relaxes the colicky tension and spasm of gut and airway smooth muscle (antispasmodic).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS12', 'Secondary', 'Eases constriction and griping cramp, the classic colic and spasmodic-cough indication.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS17', 'Secondary', 'Warms a cold, underactive stomach with weak appetite and gassy digestion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS23', 'Secondary', 'Transforms and expels cold bronchial phlegm; warm aromatic expectorant for congested catarrh.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS19', 'Minor', 'Rouses an atonic, torpid, cold gut with its warming aromatic stimulation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS05', 'Primary', 'Warming aromatic aggravates hot, hyperacid, or inflamed digestion (excess heat).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS03', 'Secondary', 'Drying quality worsens thin, dry, depleted tissue and dry irritable cough.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H194', 'TS06', 'Minor', 'Not for acutely, hotly inflamed states, where a warm stimulant is unwanted.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H194', 'SY08', 'Primary', 'Digestive: the signature affinity; gas, bloating, spasm, colic, low appetite, cold sluggish digestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H194', 'SY07', 'Primary', 'Respiratory: warm aromatic expectorant and antitussive for bronchial catarrh and spasmodic cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H194', 'SY03', 'Secondary', 'Reproductive: galactagogue, emmenagogue, mild estrogenic; menstrual cramp and menopausal flushes.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H194', 'SY01', 'Minor', 'Nervous: mild sedative and antispasmodic reputation; aromatic settling.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A17', 'Primary', 'Carminative: the signature action; expels gas and relieves flatulent, bloated digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A10', 'Primary', 'Antispasmodic: anethole relaxes gut and bronchial smooth muscle, easing colic and cough spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A12', 'Primary', 'Expectorant: warm aromatic loosens and expels cold bronchial phlegm and catarrh.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A20', 'Secondary', 'Galactagogue: classic traditional milk-promoter; anethole antagonizes dopamine to raise prolactin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A19', 'Secondary', 'Emmenagogue: mild estrogenic and traditional menstruation-promoting action (basis of pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A28', 'Secondary', 'Antimicrobial: the essential oil is antibacterial and antifungal in vitro.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A33', 'Minor', 'Antitussive: eases the irritable cough reflex; a classic cough-syrup ingredient.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A31', 'Minor', 'Antifungal: essential oil active against Candida and other fungi in vitro.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A22', 'Minor', 'Sedative: mild CNS-calming and anxiolytic activity in preliminary studies.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A32', 'Minor', 'Anthelmintic/insecticidal: anethole-rich oil has traditional and in-vitro anti-parasite and anti-lice use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H194', 'A25', 'Minor', 'Antioxidant: seed and oil scavenge free radicals in vitro.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP54', 'Primary', 'Bloating and flatulence: the defining indication; disperses trapped wind.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP58', 'Primary', 'Dyspepsia and low digestive fire; warms and stimulates a cold, weak stomach.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP12', 'Secondary', 'General digestive upset and gassy, crampy indigestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP51', 'Secondary', 'Bronchial congestion: warm aromatic expectorant loosens cold catarrhal phlegm.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP49', 'Secondary', 'Productive cough: expectorant for congested, catarrhal, spasmodic cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP50', 'Minor', 'Dry/irritable cough: antitussive soothing of the cough reflex (classic syrup ingredient).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP57', 'Minor', 'Nausea; aromatic settling of the stomach.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP60', 'Minor', 'IBS-pattern spasm; antispasmodic easing of functional gut cramp.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP29', 'Minor', 'Dysmenorrhea; antispasmodic and emmenagogue easing of menstrual cramp.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H194', 'CP33', 'Minor', 'Menopausal vasomotor symptoms; anise reduced hot-flush frequency and severity in RCTs (estrogenic).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P05', 'Primary', 'Crushed-seed infusion or tea, the traditional aniseed water, taken warm.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P09', 'Secondary', 'Sweetened syrup or gripe-style water for cough and childhood colic (dilute, not neat oil).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P01', 'Secondary', 'Tincture of the seed.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P03', 'Secondary', 'Ground seed powder.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P13', 'Secondary', 'Essential oil in cough, carminative, and lozenge products (adults, well diluted).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H194', 'P12', 'Minor', 'Added to food; culinary carminative in breads, cakes, confections, and spiced drinks.');
