INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'C02', 'Aggravates', 'Secondary', 'Choleric: warming, aromatic seed stokes an already hot, bilious constitution.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'C06', 'Aggravates', 'Minor', 'Robust hot (Pitta-like): heat aggravates hyperacid, burning digestion and dry cough.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
