INSERT INTO public.herbs_doshas_aggravates (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'D02', 'Primary', 'Heating, pungent (ushna) nature increases Pitta heat and hyperacidity.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'TCM08', 'Primary', 'Qi Stagnation of the middle jiao: distension, flatulence, colicky pain; moves and directs stuck Qi.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'TCM10', 'Secondary', 'Cold Dampness/Phlegm: warm aromatic transforms cold phlegm and dries the center and chest.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'TCM03', 'Secondary', 'Spleen Qi deficiency with cold: warms and supports a weak, cold digestion (functional).', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'TCM11', 'Primary', 'Heat/Fire: the warming, pungent seed aggravates heat and hyperacidity.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H194', 'TCM07', 'Secondary', 'Yin deficiency with heat/dryness: warming, drying nature worsens the pattern and dry cough.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Anisum (Anise).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "locator": "The Complete German Commission E Monographs (American Botanical Council, 1998) - Anise seed and oil (approved for dyspeptic complaints and catarrh of the respiratory tract). ESCOP Monographs, 2nd ed. - Anisi fructus (dyspeptic complaints, m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI812', 'H194', 'pregnancy', 'Pregnancy (therapeutic doses and essential oil)', 'moderate', 'Traditional emmenagogue and abortifacient use; mild estrogenic activity from anethole and its dimers (dianethole, photoanethole); the oil''s estragole is genotoxic/carcinogenic in rodents at high exposure. No adequate human safety data at medicinal strength; culinary food amounts are recognized as safe.', 'Culinary use is fine; avoid concentrated medicinal doses and the essential oil during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed.; Brinker, Herb Contraindications and Drug Interactions; EMA/HMPC Assessment Report on Pimpinella anisum (estragole limits).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI813', 'H194', 'breastfeeding', 'Breastfeeding (large or medicinal amounts, essential oil)', 'moderate', 'Anethole is a mild phytoestrogen and prolactin-raising galactagogue, but excess maternal anise-tea intake was linked to anethole-consistent toxicity in two breastfed newborns, and high-dose trans-anethole can reduce milk output and cause maternal seizures.', 'Moderate culinary and tea use is acceptable; avoid the concentrated essential oil and large medicinal quantities while nursing.', 'LactMed (NIH Drugs and Lactation Database), Anise.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI814', 'H194', 'drug_interaction', 'Estrogens, hormonal contraceptives, and HRT', 'moderate', 'Anise is mildly estrogenic and may add to or interfere with exogenous estrogen therapy.', 'Use cautiously and coordinate with a clinician if taking estrogen-containing medication.', 'WebMD and RxList Anise monographs; Mediscript, Herb-Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI815', 'H194', 'drug_interaction', 'Tamoxifen and estrogen-modulating agents', 'moderate', 'By affecting estrogen activity, anise could theoretically blunt the anti-estrogen effect of tamoxifen.', 'Avoid medicinal anise doses with tamoxifen unless cleared by the prescribing clinician.', 'WebMD Anise monograph; Herbal Reality (Aniseed).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI816', 'H194', 'drug_interaction', 'Antidiabetic agents (insulin, oral hypoglycemics)', 'low', 'Anise has shown mild blood-glucose-lowering activity, so additive hypoglycemia is theoretically possible.', 'Monitor blood glucose if anise is used medicinally alongside antidiabetic medication.', 'WebMD Anise monograph; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI817', 'H194', 'condition', 'Estrogen-sensitive conditions (ER-positive breast/uterine/ovarian cancer, endometriosis, fibroids)', 'moderate', 'The seed''s mild estrogenic activity may be inadvisable where estrogen exposure should be minimized.', 'Avoid concentrated medicinal doses in hormone-sensitive conditions; culinary amounts are of low concern.', 'Tabanca et al., Planta Med 2004 (estrogenic activity, PMID 15368661); Herbal Reality (Aniseed).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI818', 'H194', 'other', 'Infants and young children (neat essential oil; any star-anise product)', 'moderate', 'The concentrated essential oil can irritate the gut and mucous membranes; separately, star-anise teas given for infant colic have caused neurotoxicity and seizures because neurotoxic Japanese star anise (Illicium anisatum) adulterates Chinese star anise. True anise (Pimpinella anisum) seed tea is the safer choice.', 'Use only dilute aniseed water or tea for childhood colic; do not give neat essential oil to infants; never use star-anise preparations in babies.', 'LactMed; NCCIH; FDA/AAP star-anise neonatal toxicity reports.');
