INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H195', 'TCM11', 'Primary', 'Acute Damp-Heat or Fire dysentery in its early toxic phase, where a strong astringent can trap heat and the pathogen; the warming nature also adds to heat.', '{"title": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "locator": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H195', 'TCM07', 'Secondary', 'Yin deficiency with dryness; the warming, drying, astringent nature injures fluids.', '{"title": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "locator": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI819', 'H195', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable human safety data, plus documented anti-implantation and abortifacient activity of Aegle marmelos extracts in animal studies.', 'Avoid in pregnancy.', 'WebMD (Bael, insufficient information, avoid); animal abortifacient / anti-implantation studies of Aegle marmelos; PMC3556045 (antifertility).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI820', 'H195', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation safety data; modern references group it with pregnancy and advise avoidance.', 'Avoid while breastfeeding; prefer a better-documented remedy.', 'WebMD (Bael, not enough reliable information, avoid).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI821', 'H195', 'condition', 'Acute toxic infective dysentery (early feverish phase)', 'moderate', 'A strong astringent used too early can trap the pathogen and heat before they are cleared, and delay needed rehydration and antimicrobial treatment.', 'Do not use as an early astringent in acute, feverish, bloody dysentery; rehydrate and refer, and reserve bael for the chronic, boggy, lingering phase.', 'Traditional energetic and clinical assessment (grahi timing); WHO diarrheal-disease management principles.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI822', 'H195', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Bael lowers blood glucose and may add to antidiabetic drugs, risking hypoglycemia.', 'Monitor blood sugar; adjust medication with the prescriber; stop about 2 weeks before surgery.', 'WebMD (Bael interactions, moderate).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI823', 'H195', 'drug_interaction', 'Cholinergic and anticholinergic drugs', 'moderate', 'Bael may raise acetylcholine-type activity, adding to cholinergic agents and opposing anticholinergics.', 'Use cautiously and monitor for additive cholinergic effects or reduced anticholinergic efficacy.', 'WebMD (Bael interactions, moderate).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI824', 'H195', 'drug_interaction', 'Drugs metabolized by the liver (CYP450 substrates)', 'low', 'Bael may slow hepatic drug metabolism, raising blood levels and side effects of some medications.', 'Use cautiously with narrow-therapeutic-index hepatically metabolized drugs; monitor.', 'WebMD (Bael interactions, minor).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI825', 'H195', 'condition', 'Dry, deficient (Vata) and yin-deficient dryness constitutions', 'low', 'The warming, drying, astringent nature parches dry tissue and can harden a dry, constipated bowel.', 'Use briefly and with a moistening carrier (warm water, honey, ghee, buttermilk); discontinue once stool normalizes to avoid constipation.', 'Traditional energetic assessment (Ayurvedic Pharmacopoeia of India; Bhavaprakasha Nighantu).');
