INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H195', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "locator": "Grieve, M. A Modern Herbal (1931), heading Bael (Bengal Quince), Aegle marmelos: the unripe fruit as an astringent remedy for chronic diarrhea and dysentery.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bilva (unripe fruit of Aegle marmelos), Government of India, Ministry of AYUSH. Bhavaprakasha Nighantu, Charaka Samhita, and Sushruta Samhita (classical descriptions of Bilva as a grahi and deep", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H196', 'Bay Laurel (Sweet Bay)', 'Laurus nobilis', 'Lauraceae (the laurel family)', 'Dried leaf (folium) primarily; also the ripe berry (fruit) and the fixed oil pressed from the berry, the green ''oil of bays'' (oleum lauri)', 'Pungent (warm and aromatic), Bitter (the aromatic bitter of the dried leaf), with a faint Astringent edge from leaf tannins.', 'Warm', 'Dry', 'Cold, damp, atonic digestion: the boggy, cold, torpid gut marked by torpor and atony of digestive tone, that traps wind and gas, gurgles, and digests weakly, giving flatulent colic and a heavy, sluggish appetite. Laxity and cold relaxation of the digestive tissue that has lost its warmth and drive. Cold, damp heaviness of the chest and sinuses with thin, watery catarrh. Cold, aching, wind-damp joints and muscles that feel better for warmth (the province of the topical oil of bays). In every case the tissue is cold, damp, and slack rather than hot, dry, or overheated, and it is warmth, aroma, and gentle stimulation that it needs.', 'Heat and dryness. A warming, drying, aromatic stimulant is wrong for hot, dry, irritated, or overheated tissue: acid, burning dyspepsia and reflux, a dry inflamed gut, hot flushed constitutions, and febrile or acutely inflamed states, all of which its warmth and dryness only worsen. Frank fluid dryness and depletion, which a drying aromatic deepens. Nervous over-stimulation and excitation, since large doses are themselves excitant.', 'Digestive above all, the seat of its warming, carminative, appetite-kindling action (stomach, small intestine, and the sluggish, gassy gut). Musculoskeletal, through the topical oil of bays for cold, aching, wind-damp joints, sprains, and bruises. Respiratory, as a warming aromatic diaphoretic and expectorant for damp, cold catarrh and the onset of a chill. Secondary Integumentary (skin, topical), Nervous (a mild aromatic excitant), Reproductive (the historical emmenagogue use of the berry), and Urinary (the old use in dropsy and urinary sluggishness).', 'Cold, weak, gassy digestion: flatulent colic, bloating and wind, poor appetite, and the torpid, sluggish digestion of a cold constitution (as a warming culinary and medicinal aromatic). Topically, as the oil of bays or diluted essential oil: cold, aching, wind-damp joints and rheumatic pain, sprains, bruises, muscular aches, and the traditional drop of warm oil in the ear for earache. As a warming diaphoretic: the shivery onset of a cold or chill with thin catarrh and a damp, cold chest. Historically the berry was used to bring on delayed menses and ''remove obstructions.'' Modern interest centers on its blood-sugar and blood-lipid lowering effect in type 2 diabetes.', 'Cold-Damp-Relaxed: the boggy, cold, phlegmatic phenotype with a slow, weak, gassy digestion, cold hands and feet, thin catarrh, and a sluggish appetite, who is warmed, dried, and gently roused by an aromatic stimulant. It also suits the thin, cold, depleted (Vata-like) person whose digestion is cold and wind-bound, provided it is given with food and fat so its dryness does not overreach. It is wrong for the hot, dry, tense, and easily inflamed (choleric, Pitta-like) constitution, whom its warmth and dryness aggravate.', 'Kapha, Vata', 'Pitta', 'Bay laurel is not a herb of the classical Chinese materia medica; the following is an energetic mapping from its warm, pungent-bitter, aromatic, drying nature. It warms the middle burner and disperses cold and damp: Spleen and Stomach cold with weak digestion, bloating, wind, and poor appetite; Cold-Damp and Phlegm-Damp of the middle and the chest, which its aromatic warmth transforms; stagnant, gas-bound qi of the abdomen, which its carminative warmth moves; and Wind-Cold at the exterior, which its warming diaphoresis helps to release at the onset of a chill.', 'Heat and Fire patterns (excess heat, hot dyspepsia, hot skin eruptions), which a warm, drying aromatic aggravates. Yin deficiency and fluid dryness with heat signs, since its warmth and dryness further injure the fluids. Wind-Heat exterior patterns, for which a warming diaphoretic is the wrong direction. Blazing Stomach fire with acid reflux and burning pain.', 'Culinary use of one or two whole leaves, simmered in a dish and removed before eating, is well tolerated and long-established. The chief hazard is mechanical: whole and broken bay leaves stay stiff, leathery, and sharp-edged even after long cooking and do not soften or dissolve, so a swallowed fragment can scratch, lodge in, or rarely perforate the throat, esophagus, or gut. Always remove bay leaves before serving and never eat the leaf whole, and take special care with children and anyone who has difficulty swallowing. The leaf and the oil of bays are documented contact allergens through their sesquiterpene lactones (costunolide, laurenobiolide), and can provoke allergic contact dermatitis, particularly in people sensitive to Compositae/Asteraceae plants. The concentrated essential oil is rich in 1,8-cineole and contains methyleugenol, a naturally occurring constituent flagged as a possible genotoxic carcinogen: the essential oil should not be taken internally undiluted, should be kept away from the face of infants (cineole can trigger reflex apnea or bronchospasm), and should not be used long-term at high dose. Per the old texts, large medicinal doses are narcotic and, larger still, emetic. A single well-documented case of herb-induced liver injury has been reported with heavy, prolonged bay-leaf tea consumption.', 'Known allergy to bay/laurel or to Compositae (Asteraceae) sesquiterpene lactones. Swallowing whole or fragmented leaves (risk of throat/gastrointestinal laceration or obstruction), especially in children and those with dysphagia. Therapeutic and medicinal-strength doses, and the essential oil, during pregnancy and lactation (emmenagogue reputation; see safety fields). Internal use of the concentrated essential oil, and its application near the face of infants (1,8-cineole apnea/bronchospasm risk). Caution alongside blood-sugar-lowering medication (additive hypoglycemia).', 'Culinary use of bay leaf as a cooking spice, added to a dish and removed before eating, is regarded as safe in pregnancy. Therapeutic and medicinal-strength doses, concentrated berry preparations, and the essential oil should be avoided: bay has a documented traditional reputation as an emmenagogue, the berry being used historically ''to bring on the menses'' and ''remove obstructions'' (Grieve, A Modern Herbal, 1931), and the essential oil is advised against in pregnancy in modern essential-oil safety references (Tisserand and Young, Essential Oil Safety, 2nd ed.). There is no modern clinical safety data for medicinal doses in pregnancy, so the prudent course is culinary-only. Avoid the essential oil and any concentrated internal preparation.', 'Culinary use as a cooking spice is regarded as compatible with breastfeeding. There is no reliable modern data on the safety of therapeutic or medicinal-strength doses, or of the essential oil, during lactation, so these should be avoided in favor of ordinary culinary amounts. The concentrated essential oil in particular should not be taken internally while nursing (limited data; methyleugenol and 1,8-cineole content).', 'Bay leaf as a culinary flavoring is acceptable for children, but the whole leaf must always be removed before serving: rigid, sharp bay-leaf fragments are a documented choking and gastrointestinal-injury hazard and are especially dangerous for young children. The essential oil should not be given internally to children, and 1,8-cineole-rich (eucalyptol) essential oils must be kept away from the face and nose of infants and toddlers because inhaled cineole can trigger reflex apnea, laryngospasm, or bronchospasm. Mild culinary and topical (well-diluted) use only, under adult supervision.', 'The best-documented interaction is additive blood-sugar lowering. In a randomized trial, 1 to 3 g of ground bay leaf daily for 30 days lowered fasting serum glucose by 21 to 26 percent and improved the lipid profile in people with type 2 diabetes (Khan, Zaman and Anderson, J Clin Biochem Nutr 2009, PMID 19177188), so therapeutic doses taken alongside insulin or oral hypoglycemics (metformin, sulfonylureas) can add to their effect and require glucose monitoring and possible dose adjustment. The old texts describe large medicinal doses as narcotic, so large amounts could theoretically add to the sedation of CNS depressants (this is a traditional, not a clinically confirmed, concern). At ordinary culinary intake no well-documented drug interactions are established (limited data). Modern references: Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.', 'Whole leaf added to soups, stocks, stews, and braises for flavor and gentle carminative warmth (removed before eating). Warm leaf infusion (tea) as a digestive after meals. Decoction of leaf or crushed berry. Tincture of the leaf. Topically: the oil of bays (oleum lauri, the fixed berry oil) or the essential oil well diluted in a carrier, rubbed into cold, aching, wind-damp joints and muscles, or as a warm fomentation/compress; a warmed drop of the oil in the ear was the traditional remedy for earache.', 'Culinary: 1 to 2 whole leaves per pot, simmered and removed before serving. Infusion: 1 to 2 g dried leaf (about half a leaf to one leaf, crumbled) per cup, up to two or three times daily after meals. Tincture (1:5, 40 to 45 percent): 1 to 2 mL up to three times daily. Studied diabetic dose: 1 to 3 g ground leaf daily (short courses, with glucose monitoring). Topical: oil of bays or 1 to 3 percent diluted essential oil in a carrier, applied to the affected area. A gentle aromatic best used in modest, food-scale amounts; the essential oil is potent and for external, diluted use.', 'Grieve, M., A Modern Herbal (1931), ''Laurel (Bay) / Sweet Bay'' (Laurus nobilis).', 'Felter and Lloyd, King''s American Dispensatory (1898), ''Laurus'' (Laurel, Sweet Bay); Dioscorides, De Materia Medica (1st c. CE), Daphne (laurel); Khan, Zaman and Anderson, ''Bay leaves improve glucose and lipid profile of people with type 2 diabetes,'' J Clin Biochem Nutr 2009;44(1):52-6 (PMID 19177188); Tisserand and Young, Essential Oil Safety (2nd ed., 2014), Laurel leaf; Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; case report of Laurus nobilis herb-induced liver injury assessed by updated RUCAM (PMC12842737).', 'Family Lauraceae. The dried leaf yields roughly 1 to 3 percent essential oil dominated by 1,8-cineole (eucalyptol, commonly 30 to 50 percent), with alpha- and beta-pinene, sabinene, alpha-terpinyl acetate, linalool, eugenol, methyleugenol, and geraniol; these give the warming, carminative, mildly antimicrobial character. The bitter, aromatic principle and the plant''s contact allergens are sesquiterpene lactones (costunolide, laurenobiolide, reynosin, santamarine). Isoquinoline alkaloids (reticuline, boldine, actinodaphnine) and polyphenols/flavonoids (catechins, proanthocyanidins, kaempferol and quercetin glycosides) are also present, the latter underpinning the antioxidant and glucose/lipid effects. The berry gives a green, lard-like fixed oil, the ''oil of bays'' (oleum lauri), rich in glycerides of lauric acid (laurin/laurostearine) plus retained essential oil, long used as a warming topical. Note the caution around methyleugenol (a naturally occurring possible genotoxic carcinogen) in the concentrated oil. True (Indian) tejpat/tejpatra of Ayurveda is properly Cinnamomum tamala, a different Lauraceae leaf; Laurus nobilis is the Mediterranean bay and is used and classified here on its own energetics. The classical Greco-Roman laurel of victory (Apollo''s wreath, the crown of poets and generals; the ''bacca-laureus'' behind ''bachelor'' and ''baccalaureate'').', 'The King James Version of Psalm 37:35 reads, ''I have seen the wicked in great power, and spreading himself like a green bay tree,'' and older English herbals took this as the laurel. The underlying Hebrew (ke''ezrach ra''anan) is disputed and most modern translations render it ''a luxuriant/green tree in its native soil'' rather than the bay specifically, though Laurus nobilis is native to the eastern Mediterranean and the Holy Land and would have been familiar to the psalmist. The laurel is abundantly documented in the ancient Mediterranean world as daphne: Dioscorides describes it in De Materia Medica and the Greeks and Romans crowned victors, poets, and generals with its leaves (the classical symbol of victory and the root of ''laureate'').', 'Laurus nobilis is not at risk. It is a widely cultivated evergreen, a staple culinary tree grown across the Mediterranean and in gardens and pots worldwide, and both leaf and berry come almost entirely from cultivation rather than wild harvest. It is not listed by United Plant Savers (a North American native-plant registry). The most sustainable source is a home-grown bay tree or shrub, which yields leaf year-round; prefer cultivated, food-grade leaf.', 'Warm and drying: an aromatic, bitter culinary leaf that kindles a cold, torpid, gassy digestion, opens a damp cold chest, and warms cold, aching, wind-damp joints as the topical oil of bays.', 'Refer for severe or persistent abdominal pain, vomiting, or signs of bowel obstruction, and seek urgent care if a whole bay leaf is swallowed and causes choking, chest or throat pain, or difficulty swallowing (risk of laceration or perforation). Refer for jaundice, dark urine, or right-upper-quadrant pain (possible liver injury); for uncontrolled diabetes or symptoms of hypoglycemia if therapeutic doses are added to medication; for a spreading skin rash or blistering from topical use (allergic contact dermatitis); and for any pregnant or breastfeeding person considering medicinal doses or the essential oil.', 'Bay Laurel: BAY LOR-uhl. Laurus nobilis: LOR-us NOH-bih-liss.', 'free', 'Approved', '{"title": "Grieve, M., A Modern Herbal (1931), ''Laurel (Bay) / Sweet Bay'' (Laurus nobilis).", "locator": "Grieve, M., A Modern Herbal (1931), ''Laurel (Bay) / Sweet Bay'' (Laurus nobilis).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Felter and Lloyd, King''s American Dispensatory (1898), ''Laurus'' (Laurel, Sweet Bay); Dioscorides, De Materia Medica (1st c. CE), Daphne (laurel); Khan, Zaman and Anderson, ''Bay leaves improve glucose and lipid profile of people with type 2 ", "locator": "Felter and Lloyd, King''s American Dispensatory (1898), ''Laurus'' (Laurel, Sweet Bay); Dioscorides, De Materia Medica (1st c. CE), Daphne (laurel); Khan, Zaman and Anderson, ''Bay leaves improve glucose and lipid profile of people with type 2 ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
