INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H196', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H196', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS17', 'Primary', 'Cold: warms a cold, chilled digestion and cold, aching joints.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS19', 'Primary', 'Torpor: rouses a torpid, sluggish, weakly-digesting gut.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS07', 'Secondary', 'Dampness: aromatic warmth dries and disperses cold damp and thin catarrh.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS09', 'Secondary', 'Laxity: tones a slack, atonic, gassy digestive tissue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS23', 'Minor', 'Phlegm: warming expectorant for thin, cold, damp catarrh of the chest.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS05', 'Primary', 'Excess heat: warmth aggravates hot, flushed, overheated states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS03', 'Secondary', 'Dryness: a drying aromatic worsens frank fluid dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS06', 'Secondary', 'Acute inflammation: warming stimulation is wrong for hot, inflamed tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H196', 'TS10', 'Minor', 'Excitation: large doses are excitant and over-stimulate.');
