INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H196', 'TCM12', 'Minor', 'Wind-Heat: a warming diaphoretic is the wrong direction.', '{"title": "Grieve, M., A Modern Herbal (1931), ''Laurel (Bay) / Sweet Bay'' (Laurus nobilis).", "locator": "Grieve, M., A Modern Herbal (1931), ''Laurel (Bay) / Sweet Bay'' (Laurus nobilis).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Felter and Lloyd, King''s American Dispensatory (1898), ''Laurus'' (Laurel, Sweet Bay); Dioscorides, De Materia Medica (1st c. CE), Daphne (laurel); Khan, Zaman and Anderson, ''Bay leaves improve glucose and lipid profile of people with type 2 ", "locator": "Felter and Lloyd, King''s American Dispensatory (1898), ''Laurus'' (Laurel, Sweet Bay); Dioscorides, De Materia Medica (1st c. CE), Daphne (laurel); Khan, Zaman and Anderson, ''Bay leaves improve glucose and lipid profile of people with type 2 ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI826', 'H196', 'pregnancy', 'Pregnancy (therapeutic/medicinal doses and essential oil)', 'moderate', 'Documented traditional emmenagogue reputation (the berry used historically to bring on the menses and ''remove obstructions''); the essential oil is advised against in pregnancy in modern essential-oil safety references. No modern clinical safety data for medicinal doses.', 'Culinary use of bay leaf (added and removed) is regarded as safe; avoid therapeutic/medicinal-strength doses, concentrated berry preparations, and the essential oil in pregnancy.', 'Grieve, A Modern Herbal (1931); Tisserand and Young, Essential Oil Safety (2nd ed., 2014).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI827', 'H196', 'breastfeeding', 'Breastfeeding (therapeutic doses and essential oil)', 'low', 'No reliable data on medicinal doses or the essential oil during lactation; essential oil contains methyleugenol and 1,8-cineole.', 'Culinary amounts are compatible with breastfeeding; avoid therapeutic doses and internal essential oil while nursing.', 'Insufficient modern data; precautionary (Brinker, Herbal Contraindications and Drug Interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI828', 'H196', 'pediatric', 'Infants and young children', 'moderate', 'Rigid, sharp bay-leaf fragments are a documented choking and gastrointestinal-injury hazard; inhaled 1,8-cineole (eucalyptol) from the essential oil can cause reflex apnea, laryngospasm, or bronchospasm in infants.', 'Always remove whole leaves before serving; do not give the essential oil internally to children and keep cineole-rich oils away from the face/nose of infants and toddlers.', 'Case reports of bay-leaf GI injury; Tisserand and Young, Essential Oil Safety (1,8-cineole in infants).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI829', 'H196', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Ground bay leaf (1 to 3 g/day for 30 days) lowered fasting serum glucose by 21 to 26 percent in type 2 diabetics; therapeutic doses can add to the glucose-lowering effect of diabetes medication.', 'Monitor blood glucose and adjust medication under supervision if therapeutic doses are combined; watch for hypoglycemia.', 'Khan, Zaman and Anderson, J Clin Biochem Nutr 2009;44(1):52-6 (PMID 19177188); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI830', 'H196', 'condition', 'Compositae/Asteraceae or sesquiterpene-lactone allergy', 'moderate', 'Bay leaf and oil of bays contain the sesquiterpene lactones costunolide and laurenobiolide, documented contact allergens that can cause allergic contact dermatitis, with cross-reactivity in Compositae-sensitive individuals.', 'Avoid the topical oil and handling of the leaf in anyone with known bay/laurel or Compositae sesquiterpene-lactone allergy; patch-test before topical use.', 'Contact Dermatitis case literature (allergic contact dermatitis from bay leaf / laurel fruit oil).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI831', 'H196', 'drug_interaction', 'CNS depressants / sedatives (large medicinal doses)', 'low', 'Classical texts describe large medicinal doses of bay as narcotic; theoretical additive sedation with CNS depressants at large amounts (not clinically confirmed; not a concern at culinary intake).', 'Avoid large medicinal doses alongside sedatives; culinary use is not a concern.', 'Grieve, A Modern Herbal (1931) (traditional); theoretical.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI832', 'H196', 'condition', 'Liver disease / hepatic caution (heavy prolonged tea use)', 'low', 'A single well-documented case of Laurus nobilis herb-induced liver injury has been reported with heavy, prolonged bay-leaf tea consumption (idiosyncratic).', 'Avoid excessive, prolonged high-dose bay-leaf tea; seek care for jaundice, dark urine, or right-upper-quadrant pain.', 'Case report of Laurus nobilis herb-induced liver injury assessed by updated RUCAM (PMC12842737).');
