INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H197', 'TCM09', 'Primary', 'Blood Stasis: astringing bleeding that is due to fixed clots and stasis only traps the stagnation.', '{"title": "Felter and Lloyd, King''s American Dispensatory (1898), ''Trillium'' (Beth Root, Birthroot): astringent, tonic, and antiseptic; used in hemoptysis, hematuria, menorrhagia, uterine hemorrhage, leucorrhea, and topically for indolent ulcers.", "locator": "Felter and Lloyd, King''s American Dispensatory (1898), ''Trillium'' (Beth Root, Birthroot): astringent, tonic, and antiseptic; used in hemoptysis, hematuria, menorrhagia, uterine hemorrhage, leucorrhea, and topically for indolent ulcers.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, M., A Modern Herbal (1931), ''Bethroot'' (Trillium erectum / pendulum); Ellingwood, F., American Materia Medica, Therapeutics and Pharmacognosy (1919), Trillium; Plants For A Future (PFAF) medicinal database, Trillium erectum (''should", "locator": "Grieve, M., A Modern Herbal (1931), ''Bethroot'' (Trillium erectum / pendulum); Ellingwood, F., American Materia Medica, Therapeutics and Pharmacognosy (1919), Trillium; Plants For A Future (PFAF) medicinal database, Trillium erectum (''should", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H197', 'TCM07', 'Secondary', 'Yin deficiency with dryness: a drying astringent further injures the fluids.', '{"title": "Felter and Lloyd, King''s American Dispensatory (1898), ''Trillium'' (Beth Root, Birthroot): astringent, tonic, and antiseptic; used in hemoptysis, hematuria, menorrhagia, uterine hemorrhage, leucorrhea, and topically for indolent ulcers.", "locator": "Felter and Lloyd, King''s American Dispensatory (1898), ''Trillium'' (Beth Root, Birthroot): astringent, tonic, and antiseptic; used in hemoptysis, hematuria, menorrhagia, uterine hemorrhage, leucorrhea, and topically for indolent ulcers.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, M., A Modern Herbal (1931), ''Bethroot'' (Trillium erectum / pendulum); Ellingwood, F., American Materia Medica, Therapeutics and Pharmacognosy (1919), Trillium; Plants For A Future (PFAF) medicinal database, Trillium erectum (''should", "locator": "Grieve, M., A Modern Herbal (1931), ''Bethroot'' (Trillium erectum / pendulum); Ellingwood, F., American Materia Medica, Therapeutics and Pharmacognosy (1919), Trillium; Plants For A Future (PFAF) medicinal database, Trillium erectum (''should", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI833', 'H197', 'pregnancy', 'Pregnancy (all internal use before term)', 'absolute', 'Beth root (birthroot) is a documented uterine stimulant with a parturient and emmenagogue reputation, used traditionally to promote and ease labor; a uterine stimulant risks provoking uterine contractions in pregnancy. No modern clinical data establish a safe dose.', 'Do not self-administer in pregnancy. Its traditional parturient use belongs only to term, under the direct supervision of a qualified midwife or practitioner; avoid entirely in the first and second trimesters and for all self-directed use.', 'Plants For A Future medicinal database, Trillium erectum (''should not be taken during pregnancy except under professional supervision''); Drugs.com Natural Products (Professional) monograph, Trillium/Bethroot; documented Native American and Eclectic parturient use (Grieve 1931; Ellingwood 1919).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI834', 'H197', 'breastfeeding', 'Breastfeeding (internal therapeutic doses)', 'moderate', 'No reliable modern safety data during lactation; saponin and tannin content and a drying, astringent action, with no evidence of safety for the nursing infant.', 'Avoid internal therapeutic doses while breastfeeding; topical use as a wash for sore nipples is the only traditional lactation use. Precautionary in the absence of data.', 'Insufficient modern data; precautionary (Mills and Bone, Principles and Practice of Phytotherapy; no established lactation monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI835', 'H197', 'drug_interaction', 'Oxytocic / uterotonic drugs (oxytocin, ergometrine, prostaglandin agents) and labor-inducing herbs', 'moderate', 'Beth root is itself a uterine stimulant, so combining it with uterotonic drugs or other labor-promoting herbs could produce additive uterine-stimulant effects.', 'Do not combine with oxytocic drugs or labor-inducing herbs outside supervised obstetric or midwifery care.', 'Mechanistic/class caution based on documented parturient action (Ellingwood 1919; Mills and Bone, Principles and Practice of Phytotherapy).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI836', 'H197', 'drug_interaction', 'Orally administered drugs, alkaloids, and mineral supplements (for example iron)', 'low', 'High tannin and saponin content can, like other tannin-rich astringents, bind and reduce the absorption of concurrently taken drugs, alkaloids, and minerals.', 'Separate beth root doses from oral medication and mineral supplements by about two hours.', 'Brinker, Herbal Contraindications and Drug Interactions (general tannin-astringent absorption cautions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI837', 'H197', 'condition', 'High-dose or fresh-root use; sensitive gastrointestinal tract', 'moderate', 'The rhizome contains calcium oxalate raphides and steroidal saponins; large or concentrated doses, and the fresh root, can cause nausea, vomiting, and local gastric or mucosal irritation.', 'Use the dried root, begin at the low end of the dose range, and avoid large or concentrated doses; discontinue if nausea or gastric irritation occurs.', 'Drugs.com Natural Products (Professional) monograph, Trillium/Bethroot; Plants For A Future (nausea in high doses, local irritation).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI838', 'H197', 'pediatric', 'Internal use in infants and children', 'moderate', 'No modern pediatric safety data; a strong astringent uterine/hemostatic herb with no established pediatric role, and high doses are locally irritant (calcium oxalate, saponins).', 'Avoid internal use in children except under qualified professional care.', 'Insufficient modern data; precautionary.');
