INSERT INTO public.herbs_doshas_aggravates (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H198', 'D02', 'Primary', 'Classical texts assign Ushna virya and mild Pitta increase; balance with cooling herbs. A major practical and Western tradition instead treats it as Pitta-pacifying (see flags).', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "locator": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
