INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H198', 'TCM03', 'Primary', 'Spleen Qi deficiency: cold, enriching herb burdens weak digestion; especially contraindicated with diarrhea.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "locator": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H198', 'TCM01', 'Primary', 'Kidney Yang deficiency: a cold yin tonic is wrong for yang deficiency and interior cold.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "locator": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H198', 'TCM10', 'Secondary', 'Dampness/Phlegm: enriching and cold, it can worsen damp-cold accumulation.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "locator": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI839', 'H198', 'pregnancy', 'Pregnancy', 'moderate', 'Coumestan constituents (wedelolactone) are weak phytoestrogens with theoretical hormonal and uterine activity; the Chinese materia medica contraindicates the herb in pregnancy; hepatotoxicity is demonstrated at very high doses. Controlled human safety data are absent.', 'Avoid during pregnancy in any internal form unless directed by a qualified practitioner.', 'Restorative Medicine monograph (Eclipta alba/prostrata); Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Han Lian Cao); AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI840', 'H198', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation data; a phytoestrogenic constituent is present; the Chinese materia medica contraindicates the herb in nursing and modern monographs advise avoidance for potential liver toxicity, though some Ayurvedic postpartum use exists (conflicting).', 'Best avoided while breastfeeding, or used only under qualified supervision; prefer better-studied alternatives.', 'Restorative Medicine monograph; Bensky, Clavey and Stoger, Materia Medica.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI841', 'H198', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Eclipta lowers blood glucose via alpha-glucosidase and aldose-reductase inhibition (eclalbasaponins, echinocystic-acid glycosides), which can add to the effect of diabetes medication and risk hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined; watch for hypoglycemia.', 'Antidiabetic principle from Eclipta prostrata (Planta Medica); Restorative Medicine monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI842', 'H198', 'drug_interaction', 'Immunosuppressant therapy (transplant, autoimmune)', 'moderate', 'The herb is immunomodulatory and could theoretically oppose immunosuppression.', 'Use cautiously or avoid in patients on immunosuppressants without professional supervision.', 'Feng et al., Eclipta prostrata review (Biomolecules 2021, PMID 34827736).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI843', 'H198', 'drug_interaction', 'Corticosteroids (glucocorticoids)', 'low', 'Eclipta modulates 11-beta-hydroxysteroid dehydrogenase, which may theoretically alter glucocorticoid activity.', 'Be aware of possible modulation of corticosteroid effect; monitor if co-administered.', 'Study of Eclipta prostrata on 11-beta-hydroxysteroid dehydrogenase in rat liver and kidney.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI844', 'H198', 'condition', 'Biliary obstruction or gallstones', 'moderate', 'The herb stimulates bile flow (cholagogue action), which can be problematic where the biliary tract is obstructed.', 'Avoid in biliary obstruction or symptomatic gallstones without professional supervision.', 'Clinical Ayurvedic caution for bile-stimulating herbs; Restorative Medicine monograph (hepatobiliary use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI845', 'H198', 'condition', 'High-dose or prolonged use, and significant liver disease', 'moderate', 'Animal studies show a biphasic, dose-dependent hepatic effect: protective at customary doses but hepatotoxic at very high doses.', 'Use customary doses only, avoid megadoses and prolonged high-dose use, and monitor in existing liver disease.', 'Restorative Medicine monograph (biphasic hepatic dose-response).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI846', 'H198', 'other', 'Asteraceae (Compositae) allergy', 'low', 'As a daisy-family plant it can rarely provoke allergic reaction or contact dermatitis in sensitive individuals.', 'Avoid in those with known Asteraceae allergy; discontinue if rash or reaction occurs.', 'AHPA Botanical Safety Handbook (Asteraceae allergy class); general botanical safety.');
