INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H198', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "locator": "Ayurvedic Pharmacopoeia of India, Part I, Vol. I, Bhringaraja (the whole plant of Eclipta alba Hassk., accepted name Eclipta prostrata (L.) L.), the government-published pharmacopeial monograph; grounded in the classical Bhavaprakasha Nigha", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "locator": "Bhavaprakasha Nighantu, Guduchyadi Varga, Bhringaraja; Restorative Medicine (Association for the Advancement of Restorative Medicine) monograph, Bhringaraj / Eclipta alba, prostrata; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Mater", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H199', 'Bhumyamalaki (Bhui Amla / Chanca Piedra / Stonebreaker)', 'Phyllanthus niruri L.', 'Phyllanthaceae (the leaf-flower family; segregated from the older Euphorbiaceae under modern APG classification)', 'Whole plant (the aerial herb with root; the fresh or dried whole plant is used)', 'Bitter (tikta) and astringent (kashaya), with a faint sweet undertone and a sweet post-digestive effect (madhura vipaka). The tiny leaves and stems are markedly bitter.', 'Cool. The Ayurvedic potency is sheeta (cold/cooling); it is a cooling, heat-clearing bitter, which is why it settles bilious, pitta-type liver heat and hot dysuria.', 'Dry', 'Excess heat and damp-heat: a hot, congested, bilious terrain with jaundice, hepatitis, and hot, scanty, burning urination, which this cool bitter drains and clears. Dampness: a boggy, damp-heat liver and lower burner, which it dries and decongests. Stagnation: sluggish, obstructed bile and a congested, gravel-forming urinary tract, which it moves and flushes (the classic stonebreaker action on urinary calculi). Chronic infection: chronic viral hepatitis and low-grade damp-heat, where its antiviral, hepatoprotective action is used over time. In short a cool, draining, decongesting bitter for a hot, damp, stagnant liver and urinary terrain.', 'Cold above all: a cooling, draining bitter aggravates cold, hypofunctioning digestion and a cold, deficient constitution. Dryness: its light, dry, astringent quality parches dry, thin, depleted (Vata-like) tissue, so it is given to such states only briefly and with a moistening carrier. Frank deficiency and depletion, where a cold, draining bitter used alone can further weaken digestive fire and vitality.', 'Hepatic / Liver (primary: the foremost yakrit herb of the Bhavaprakasha, hepatoprotective and antiviral, traditional in jaundice and hepatitis). Urinary (primary: the stonebreaker, a diuretic antilithic for gravel, stones, and hot dysuria). Digestive (bitter cholagogue for biliousness and sluggish bile). Immune (antiviral, notably against hepatitis B). Integumentary / Skin (alterative for hot, damp skin, minor).', 'Jaundice and viral hepatitis, especially hepatitis B (the signature research indication); a sluggish, inflamed, congested liver and bile stagnation; biliousness and hot, pitta-type dyspepsia; urinary gravel and kidney or bladder stones (the stonebreaker, quebra-pedra); hot, burning, scanty urination and uncomplicated urinary infection; elevated blood sugar; and low-grade fever with damp-heat. Traditionally also a cooling alterative for hot, damp skin.', 'The hot, damp, bilious, congested-liver phenotype: a robust, ruddy, overheated, sluggish-liver terrain (the Choleric and the robust hot Pitta-like type) that this cool draining bitter clears and settles. It is poorly suited to the thin, cold, dry, depleted (Vata-like) constitution and the cold, weak-digestion type, whom its cold, drying, draining nature further chills and depletes.', 'Pitta, Kapha', 'Vata', 'Damp-Heat in the Liver and Gallbladder: jaundice, hepatitis, bitter taste, and a hot, congested liver, which this cool bitter clears and drains. Damp-Heat pouring into the Bladder: hot, burning, scanty, gravelly urination and stones (a Lin-type pattern), which it flushes. Heat and Fire in the middle and lower burner generally. It is not a classical Chinese herb (it enters Ayurveda as Bhumyamalaki and Amazonian folk medicine as chanca piedra); these are functional correspondences.', 'Cold from Yang deficiency (Spleen and Kidney Yang deficiency) with cold limbs, loose stool, and weak digestion, and Qi deficiency with a cold, hypofunctioning middle burner, where this cold, draining bitter injures the Yang and weakens transformation. Use in such patterns only when warmed and balanced, or avoid.', 'It lowers blood sugar, so use cautiously in diabetes and hypoglycemia and watch for additive effects with glucose-lowering medication. It is mildly hypotensive and diuretic, so it can add to blood-pressure-lowering and diuretic drugs. Its lignans (phyllanthin and hypophyllanthin) are potent mechanism-based inhibitors of liver CYP3A4 (and also inhibit CYP1A2, 2D6, and 2E1), so it can raise blood levels of drugs cleared by these enzymes; this matters most for narrow-margin drugs such as the immunosuppressants tacrolimus and cyclosporine. Being cold, light, and drying, it aggravates Vata and cold, deficient, dry constitutions. A practical caution: commercial Bhumyamalaki is frequently the botanically distinct species Phyllanthus amarus or Phyllanthus fraternus rather than true P. niruri, so insist on correctly identified material. Given the blood-sugar and possible antiplatelet effects, stop about 2 weeks before surgery.', 'Pregnancy (avoid; animal data show maternal and offspring effects and human safety data are lacking) and lactation (avoid; insufficient data). Caution in diabetes and hypoglycemia, in low blood pressure, and alongside blood-sugar-, blood-pressure-, and CYP3A4-metabolized narrow-margin drugs, especially immunosuppressants. Relative constitutional caution in cold, dry, weak-digestion (Vata) states. Not a substitute for medical care in viral hepatitis or obstructing urinary stones.', 'Avoid. Controlled rodent studies of aqueous Phyllanthus niruri extract given during gestation report maternal kidney changes and reduced offspring body weight with later neurobehavioral changes, and there are no adequate human pregnancy data, so use is not recommended. Modern consumer references likewise advise avoiding chanca piedra in pregnancy for lack of reliable safety data. Sources: de Souza et al., maternal-fetal repercussions of P. niruri in rat pregnancy (J Ethnopharmacol 2020, S0378874119309717); P. niruri pregnancy and lactation neurobehavioral rat study (Brain Res 2025, PMID 39694168); WebMD / Drugs.com (Chanca piedra, avoid in pregnancy).', 'Avoid; insufficient data. Animal studies of exposure through lactation report neurobehavioral changes in the offspring, and there are no human lactation safety data, so a better-documented remedy is preferred. Sources: P. niruri pregnancy and breastfeeding rat study (Brain Res 2025, PMID 39694168); Ferreira et al., aqueous P. niruri during pregnancy and lactation, neurobehavioral effects in rat offspring (2021, S037887412100088X); WebMD / Drugs.com (Chanca piedra, insufficient information, avoid).', 'Not well established; practitioner-guided use only. Ayurveda has used small doses of the fresh juice or decoction for children''s jaundice, but there are no formal modern pediatric safety or dosing data, so reserve internal use for qualified guidance and avoid the concentrated standardized extract in young children. Sources: precautionary practice; WebMD / Drugs.com (no pediatric data); Ayurvedic Pharmacopoeia of India (traditional pediatric jaundice use).', 'CYP3A4-metabolized drugs, especially narrow-margin agents (immunosuppressants tacrolimus and cyclosporine, and many statins, calcium-channel blockers, and others): the lignans phyllanthin and hypophyllanthin are mechanism-based inhibitors of CYP3A4 and also inhibit CYP1A2, 2D6, and 2E1, so co-use can raise drug levels toward toxicity; avoid or use only with monitoring (this is the best-characterized, mechanistic interaction). Antidiabetic drugs (insulin, sulfonylureas, metformin): additive glucose lowering with hypoglycemia risk; monitor blood sugar. Antihypertensive and diuretic drugs: additive blood-pressure lowering and diuresis; monitor. Lithium: theoretical, its diuretic action may reduce lithium clearance and raise levels. Anticoagulant and antiplatelet drugs: limited data, use cautiously. Sources: Appiah-Opong et al., inhibition of human CYP by Phyllanthus amarus lignans, CYP3A4 mechanism-based inhibition (Chem Biol Interact 2011, PMID 21178301); WebMD / Drugs.com (Chanca piedra interactions); Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.', 'Fresh whole-plant juice (swarasa), the classic Ayurvedic form for jaundice; decoction (kwatha) of the dried whole plant; whole-plant powder (churna); water infusion or tea (the common chanca piedra preparation); tincture; and capsules of dried herb or standardized extract (modern). Traditionally taken as the fresh juice with honey or as a decoction for liver and urinary complaints.', 'Fresh whole-plant juice (swarasa): 10 to 20 mL once or twice daily. Whole-plant powder (churna): 3 to 6 g per day in 2 to 3 divided doses (Ayurvedic Pharmacopoeia of India). Decoction: 5 to 10 g dried whole plant simmered in water, taken in 2 divided doses. Tea / infusion (chanca piedra): 1 to 3 g dried herb per cup, up to 2 to 3 cups daily. Capsule of standardized extract: commonly 500 mg once or twice daily. Tincture: per manufacturer, commonly 2 to 4 mL up to three times daily. Use in defined courses rather than indefinitely, and start low in cold or dry constitutions.', 'The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavaprakasha Nighantu (Bhumyamalaki as a foremost liver herb).', 'Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus niruri hepatoprotective, antiviral, and antilithic pharmacology (e.g., J Adv Biol Biotechnol 2024 comprehensive review). Appiah-Opong et al. 2011 (CYP3A4 inhibition, PMID 21178301). Reproductive-safety rodent studies (J Ethnopharmacol 2020 and 2021; Brain Res 2025, PMID 39694168). WebMD and Drugs.com (Chanca piedra) consumer safety and interaction summaries. Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.', 'Phyllanthaceae (segregated from Euphorbiaceae). A small, fast-growing, pantropical annual weed of disturbed ground, 30 to 60 cm tall, bearing tiny leaf-like branchlets with minute flowers and fruits set underneath the branches, resembling a ground-level amla, hence bhumi (earth) amalaki. Key constituents include the lignans phyllanthin, hypophyllanthin, niranthin, and nirtetralin; the ellagitannins geraniin, corilagin, amariin, and phyllanthusiin; flavonoids (quercetin, rutin, kaempferol, astragalin); Securinega-type alkaloids; and triterpenes. Documented modern activities: hepatoprotective, antiviral (inhibits hepatitis B virus DNA polymerase and lowers HBsAg, the classic research use), antilithic (inhibits calcium-oxalate crystal nucleation and growth, the stonebreaker action), antioxidant, antidiabetic, anti-inflammatory, diuretic, and mildly hypotensive. Important taxonomic caution: much material sold and studied as Bhumyamalaki or P. niruri in India is in fact the closely related Phyllanthus amarus or Phyllanthus fraternus, and the names are used loosely across trade and literature, so identity should be confirmed. Classical Ayurvedic energetics: tikta and kashaya rasa, laghu and ruksha guna, sheeta virya, madhura vipaka, pacifying Kapha and Pitta and, in excess, aggravating Vata; the Bhavaprakasha ranks it among the foremost liver remedies.', 'Not named in the canonical biblical texts. Bhumyamalaki is a pantropical plant whose medicinal use is anchored in Ayurveda, where it is described in the Bhavaprakasha Nighantu and the Ayurvedic Pharmacopoeia of India as a foremost liver and urinary herb, and, as chanca piedra or quebra-pedra (stonebreaker), in the folk medicine of the Amazon, the West Indies, and tropical South America for stones and jaundice. It is a plant of the Indian and tropical New World materia medica rather than the ancient Mediterranean or biblical world.', 'Not on the United Plant Savers At-Risk or To-Watch lists (which track North American natives). Phyllanthus niruri is an abundant, fast-reproducing pantropical annual weed of gardens, fields, and waste ground, gathered as the whole plant without conservation concern, so wild harvest is sustainable. The chief integrity issue here is botanical, not ecological: because commercial Bhumyamalaki is frequently the look-alike species P. amarus or P. fraternus, prefer correctly identified, verified material from a reputable supplier over sustainability alone.', 'Cool, dry, and bitter: a draining hepatic and urinary bitter that clears damp-heat from a hot, congested liver and flushes gravel and heat from the urinary tract.', 'Refer for jaundice, dark urine, pale stools, right-upper-quadrant pain, or suspected hepatitis, which need medical diagnosis and monitoring (viral hepatitis, biliary obstruction, and liver failure are not self-treatable); for severe or colicky flank pain, blood in the urine, fever with urinary symptoms, or a stone that will not pass (risk of obstruction and kidney infection); for uncontrolled or symptomatic blood sugar; and for anyone on immunosuppressants or other narrow-margin medication before use. Bhumyamalaki is a supportive remedy, not a substitute for antiviral treatment or urological care.', 'Bhumyamalaki = BHOOM-yuh-MAH-luh-kee (Bhui Amla, BHOO-ee AM-lah; Chanca Piedra, CHAHN-kah pee-EH-drah). Phyllanthus niruri = fil-AN-thus nih-ROO-ree.', 'free', 'Approved', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H199', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H199', 'T04');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H199', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS05', 'Primary', 'Excess heat; a cool bitter clearing bilious, pitta-type liver heat and hot dysuria.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS07', 'Primary', 'Dampness; drains and decongests a damp-heat liver and lower burner.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS08', 'Primary', 'Stagnation; moves obstructed bile and flushes a congested, gravel-forming urinary tract.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS14', 'Secondary', 'Chronic infection; antiviral and hepatoprotective in chronic viral hepatitis and low-grade damp-heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS06', 'Secondary', 'Acute inflammation; anti-inflammatory in an inflamed, hot liver and urinary tract.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS17', 'Primary', 'Cold; a cooling, draining bitter aggravates cold, hypofunctioning digestion and a cold constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS03', 'Secondary', 'Dryness; light, dry, astringent quality parches dry, thin (Vata-like) tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H199', 'TS01', 'Secondary', 'Deficiency; a cold draining bitter used alone can further weaken digestive fire and vitality.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H199', 'SY12', 'Primary', 'Hepatic; hepatoprotective and antiviral, the foremost yakrit herb for jaundice and hepatitis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H199', 'SY09', 'Primary', 'Urinary; the stonebreaker, a diuretic antilithic for gravel, stones, and hot dysuria.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H199', 'SY08', 'Secondary', 'Digestive; bitter cholagogue for biliousness and sluggish bile.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H199', 'SY05', 'Secondary', 'Immune; antiviral, notably against hepatitis B virus.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H199', 'SY10', 'Minor', 'Skin; cooling alterative for hot, damp skin conditions.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A13', 'Primary', 'Hepatoprotective; protects liver cells and is the classic remedy for jaundice and hepatitis.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A16', 'Primary', 'Bitter tonic; a cooling bitter that stimulates bile and settles a hot, sluggish liver and digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A08', 'Primary', 'Diuretic; increases urine flow and flushes the urinary tract (chanca piedra).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A30', 'Secondary', 'Antiviral; inhibits hepatitis B virus DNA polymerase and lowers surface antigen.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A14', 'Secondary', 'Alterative; cooling blood-cleanser for damp-heat of the liver and skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A43', 'Secondary', 'Cholagogue; promotes bile flow, relieving biliousness and bile stagnation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A09', 'Secondary', 'Anti-inflammatory; eases hepatic and urinary inflammation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A25', 'Secondary', 'Antioxidant; corilagin, geraniin, and other tannins and flavonoids.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A36', 'Secondary', 'Hypoglycemic; lowers blood glucose in animal and early human studies.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A49', 'Minor', 'Febrifuge; traditional for low-grade fever with damp-heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A37', 'Minor', 'Hypotensive; mild blood-pressure-lowering activity reported.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H199', 'A28', 'Minor', 'Antimicrobial; broad activity from its tannins and lignans.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP72', 'Primary', 'Sluggish liver and bile stagnation; hepatic bitter and cholagogue (see also viral hepatitis in new_complaints).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP64', 'Primary', 'Urinary stones and gravel; the stonebreaker, inhibits calcium-oxalate crystal formation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP74', 'Secondary', 'Cholestasis and jaundice; cooling hepatic that clears bilious damp-heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP09', 'Secondary', 'Chronic infection; chronic viral hepatitis, antiviral and hepatoprotective over time.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP65', 'Secondary', 'Hot, burning urinary irritation and dysuria; cooling diuretic.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP63', 'Secondary', 'Uncomplicated urinary infection; diuretic antimicrobial flush.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP13', 'Secondary', 'Systemic and hepatic inflammation; anti-inflammatory.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP27', 'Secondary', 'Blood-sugar dysregulation; hypoglycemic activity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP75', 'Minor', 'Oxidative stress; tannin and flavonoid antioxidant.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H199', 'CP76', 'Minor', 'Low-grade fever with damp-heat; traditional febrifuge.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H199', 'P04', 'Primary', 'Decoction (kwatha) of the dried whole plant for liver and urinary complaints.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H199', 'P05', 'Primary', 'Water infusion or tea; the common chanca piedra preparation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H199', 'P03', 'Primary', 'Whole-plant powder (churna).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H199', 'P01', 'Secondary', 'Tincture (modern).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H199', 'P02', 'Secondary', 'Capsule of dried herb or standardized extract (modern).');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'C06', 'Indicated', 'Primary', 'The robust, hot, bilious (Pitta-like) type, whom this cool draining bitter clears and settles.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'C02', 'Indicated', 'Secondary', 'The Choleric, hot, congested-liver constitution, cooled and decongested by a bitter hepatic.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'C05', 'Aggravates', 'Primary', 'The thin, cold, dry, depleted (Vata-like) type, further chilled and dried by a cold draining bitter.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'D02', 'Primary', 'Cool, bitter, draining; the classic pitta-pacifying liver herb, clearing bilious heat.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'D03', 'Secondary', 'Bitter, astringent, light, and drying, it also reduces damp Kapha; a kapha-pitta shamaka.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_aggravates (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'D01', 'Primary', 'Cold, light, dry, rough qualities increase Vata; balance with a warming, moistening carrier or avoid in Vata states.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'TCM10', 'Primary', 'Clears Damp-Heat from the Liver, Gallbladder, and Bladder; jaundice, hepatitis, and hot gravelly urination.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'TCM11', 'Secondary', 'Clears Heat and Fire in the middle and lower burner.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'TCM01', 'Primary', 'Kidney Yang deficiency and cold; a cold draining bitter injures the Yang.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H199', 'TCM03', 'Secondary', 'Spleen Qi deficiency with cold; weakens a cold, hypofunctioning middle burner.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "locator": "The Ayurvedic Pharmacopoeia of India, Part I: Bhumyamalaki (whole plant of Phyllanthus, listed under Phyllanthus amarus / Phyllanthus niruri). Official monograph, Government of India, Ministry of AYUSH. Classical description in the Bhavapra", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "locator": "Bhavaprakasha Nighantu and Dravyaguna tradition (energetics: tikta-kashaya rasa, laghu-ruksha guna, sheeta virya, madhura vipaka, kapha-pitta shamaka). Easy Ayurveda practitioner monograph (Bhumyamalaki). Modern reviews of Phyllanthus nirur", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI847', 'H199', 'pregnancy', 'Pregnancy', 'moderate', 'Rodent studies of aqueous extract in gestation show maternal kidney changes, reduced offspring weight, and later neurobehavioral changes; no adequate human data.', 'Avoid in pregnancy.', 'de Souza et al., J Ethnopharmacol 2020 (S0378874119309717); Brain Res 2025 (PMID 39694168); WebMD / Drugs.com (Chanca piedra).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI848', 'H199', 'breastfeeding', 'Breastfeeding', 'moderate', 'Lactational-exposure rodent studies show offspring neurobehavioral changes; no human lactation safety data.', 'Avoid while breastfeeding; prefer a better-documented remedy.', 'Brain Res 2025 (PMID 39694168); Ferreira et al. 2021 (S037887412100088X); WebMD / Drugs.com.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI849', 'H199', 'drug_interaction', 'CYP3A4-metabolized narrow-margin drugs, especially immunosuppressants (tacrolimus, cyclosporine)', 'moderate', 'Lignans phyllanthin and hypophyllanthin are mechanism-based CYP3A4 inhibitors (also inhibit CYP1A2, 2D6, 2E1), raising blood levels of drugs cleared by these enzymes toward toxicity.', 'Avoid with narrow-margin CYP3A4 substrates, or use only with drug-level monitoring and prescriber oversight.', 'Appiah-Opong et al., Chem Biol Interact 2011 (PMID 21178301); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI850', 'H199', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'The herb lowers blood glucose and may add to antidiabetic drugs, risking hypoglycemia.', 'Monitor blood sugar; adjust medication with the prescriber; stop about 2 weeks before surgery.', 'WebMD / Drugs.com (Chanca piedra); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI851', 'H199', 'drug_interaction', 'Antihypertensive and diuretic drugs', 'moderate', 'Mild hypotensive and diuretic activity may add to blood-pressure-lowering and diuretic medication.', 'Monitor blood pressure and fluid status if combined.', 'WebMD / Drugs.com (Chanca piedra); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI852', 'H199', 'drug_interaction', 'Lithium', 'low', 'Theoretical; a diuretic effect may reduce renal lithium clearance and raise serum levels.', 'Monitor lithium levels if combined; adjust with the prescriber.', 'Brinker, Herb Contraindications and Drug Interactions (diuretic-lithium class effect).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI853', 'H199', 'condition', 'Cold, dry, deficient (Vata) and cold-deficient-digestion constitutions', 'low', 'The cold, light, drying, draining nature chills and parches cold, dry, weak-digestion terrain and can weaken digestive fire.', 'Use only briefly and with a warming, moistening carrier in these states, or choose a warmer hepatic.', 'Traditional energetic assessment (Ayurvedic Pharmacopoeia of India; Bhavaprakasha Nighantu).');
