INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H200', 'TCM01', 'Secondary', 'Kidney Yang Deficiency: a cooling, contracting herb is wrong for interior cold.', '{"title": "Grieve, A Modern Herbal (1931), Butcher''s Broom (Ruscus aculeatus), recording the aperient, diaphoretic, and diuretic root and the wine decoction for gravel, dropsy, and jaundice.", "locator": "Grieve, A Modern Herbal (1931), Butcher''s Broom (Ruscus aculeatus), recording the aperient, diaphoretic, and diuretic root and the wine decoction for gravel, dropsy, and jaundice.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Rusci rhizoma (butcher''s broom rhizome); German Commission E Monograph, Rusci aculeati rhizoma; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions; Bruneton, Ph", "locator": "ESCOP Monographs, Rusci rhizoma (butcher''s broom rhizome); German Commission E Monograph, Rusci aculeati rhizoma; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions; Bruneton, Ph", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI854', 'H200', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable safety data, and the herb is an alpha-adrenergic vasoconstrictor capable of affecting vascular tone. No established teratogenicity, but safety is not established.', 'Avoid in pregnancy. A specific European standardized combination product has been used for pregnancy-related varicosities only under medical supervision.', 'Natural Medicines / WebMD monograph (not enough reliable information, avoid); ESCOP Monograph, Rusci rhizoma; AHPA Botanical Safety Handbook precautionary approach.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI855', 'H200', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation-safety data; the herb is a vasoconstrictor. e-lactancia rates it low risk but formal data are absent.', 'Prefer to avoid, or use only briefly under professional guidance while breastfeeding.', 'e-lactancia.org (Ruscus aculeatus, low risk); Natural Medicines / WebMD monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI856', 'H200', 'condition', 'Hypertension', 'moderate', 'Ruscogenins are alpha-1 and alpha-2 adrenergic agonists that constrict vessels and can raise blood pressure.', 'Use caution or avoid in uncontrolled or poorly controlled hypertension; monitor blood pressure.', 'Natural Medicines / WebMD monograph; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI857', 'H200', 'drug_interaction', 'Alpha-adrenergic antagonists (alpha-blockers: terazosin, doxazosin, prazosin)', 'moderate', 'Butcher''s broom stimulates alpha-adrenergic tone and can reduce the blood-pressure-lowering and prostatic (BPH) effect of alpha-blockers.', 'Avoid concurrent use, or monitor blood pressure and prostatic symptoms under supervision.', 'Natural Medicines / WebMD monograph (moderate interaction); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI858', 'H200', 'drug_interaction', 'Alpha-adrenergic agonist / sympathomimetic stimulants (e.g. pseudoephedrine)', 'moderate', 'Additive alpha-adrenergic vasoconstriction may raise blood pressure or heart rate excessively.', 'Avoid combining with decongestant or stimulant sympathomimetics.', 'Natural Medicines / WebMD monograph (moderate interaction).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI859', 'H200', 'drug_interaction', 'Monoamine oxidase inhibitors (MAOIs)', 'moderate', 'Theoretical additive vasopressor and hypertensive risk from the herb''s sympathomimetic activity (some sources also cite tyramine content).', 'Avoid the combination; the interaction is theoretical but potentially serious.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI860', 'H200', 'drug_interaction', 'Antihypertensive drugs (general)', 'low', 'Vasoconstriction and a tendency to raise blood pressure may oppose antihypertensive therapy.', 'Monitor blood pressure if combined.', 'Natural Medicines / WebMD monograph; Brinker, Herbal Contraindications and Drug Interactions.');
