INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H201', 'C07', 'Indicated', 'Secondary', 'Deficient/Pale: warms and fortifies the cold, depleted type.', '{"title": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "locator": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
