INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H201', 'TCM11', 'Primary', 'Heat/Fire, real or from excess: a hot bark inflames it further.', '{"title": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "locator": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H201', 'TCM12', 'Secondary', 'Wind-Heat: a warming interior bark is unsuited to a heat exterior pattern.', '{"title": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "locator": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI861', 'H201', 'pregnancy', 'Pregnancy (therapeutic and supplemental doses)', 'moderate', 'Cinnamon bark is a documented emmenagogue and mild uterine stimulant (Grieve), and animal studies indicate cinnamaldehyde exposure in pregnancy may harm the fetus; the coumarin burden adds concern. Food amounts appear safe; medicinal doses lack safety data.', 'Season food freely if desired, but avoid therapeutic doses, concentrated supplements, and the essential oil during pregnancy.', 'NCCIH, Cinnamon; AHPA Botanical Safety Handbook (2nd ed.); Grieve, A Modern Herbal; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI862', 'H201', 'breastfeeding', 'Breastfeeding (large or medicinal doses)', 'low', 'Cinnamon bark can reduce milk secretion (a mild lactifuge reputation, Grieve), so sustained medicinal doses may lower supply; the coumarin content argues against concentrated, prolonged use. No infant toxicity is documented at culinary intake.', 'Use food amounts freely; avoid therapeutic doses and the neat essential oil while nursing, especially if maintaining milk supply.', 'Grieve, A Modern Herbal; NCCIH, Cinnamon; AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI863', 'H201', 'condition', 'Liver disease / hepatic impairment', 'moderate', 'Cassia is coumarin-rich (about 1,000 to 6,000 mg/kg) and coumarin is hepatotoxic in susceptible people, reported as raised liver enzymes with high or prolonged intake.', 'Avoid concentrated or long-term cassia in anyone with liver disease; prefer low-coumarin Ceylon cinnamon or none. Keep sustained coumarin intake below 0.1 mg/kg body weight per day.', 'NCCIH, Cinnamon; EFSA opinion on coumarin (tolerable daily intake 0.1 mg/kg bw).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI864', 'H201', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'The coumarin in cassia has mild anticoagulant activity and may, at high or prolonged supplemental intake, add to anticoagulants and destabilize anticoagulation control, with a theoretical additive bleeding risk.', 'Avoid concentrated cassia supplements with anticoagulant or antiplatelet therapy; culinary amounts are generally tolerated. Monitor INR if used.', 'AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI865', 'H201', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Cassia lowers blood glucose (procyanidins improve insulin sensitivity) and can add to the glucose-lowering effect of diabetes medication, risking hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined; watch for hypoglycemia.', 'AHPA Botanical Safety Handbook (2nd ed.), Cinnamomum aromaticum; NCCIH, Cinnamon.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI866', 'H201', 'drug_interaction', 'Hepatotoxic drugs (high-dose acetaminophen, methotrexate, isoniazid, some statins)', 'moderate', 'Coumarin is hepatotoxic, so concentrated cassia may add to the liver burden of hepatotoxic medications.', 'Do not stack concentrated or long-term cassia with hepatotoxic drugs; limit to culinary amounts and monitor liver function if exposure is unavoidable.', 'NCCIH, Cinnamon; EFSA opinion on coumarin; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI867', 'H201', 'other', 'Cinnamon/cinnamaldehyde allergy and balsam of Peru/tolu cross-reactivity', 'moderate', 'Cinnamaldehyde is a well-known contact sensitizer causing allergic contact dermatitis, cheilitis, and oral mucositis; it cross-reacts with balsam of Peru.', 'Avoid in anyone with known cinnamon or balsam-of-Peru allergy; always dilute the essential oil and avoid prolonged mucosal contact.', 'AHPA Botanical Safety Handbook (2nd ed.); contact-dermatitis literature (cinnamaldehyde as fragrance allergen).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI868', 'H201', 'condition', 'Yin deficiency with heat, interior heat/fire, and heat-type bleeding (TCM)', 'moderate', 'A hot, acrid, blood-moving bark aggravates heat and empty fire and can worsen bleeding driven by heat in the blood.', 'Avoid in yin-deficient heat, interior heat/fire, and reckless heat bleeding; reserve for genuine cold and yang-deficiency patterns.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
