INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H201', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "locator": "Grieve, M., A Modern Herbal (1931), ''Cinnamon, Cassia'' (Cinnamomum cassia), the dried inner bark. Public domain, botanical.com/botanical/mgmh/c/cassia31.html.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Rou Gui (Cortex Cinnamomi); Chen and Chen, Chinese Medical Herbology and Pharmacology, Rou Gui; NCCIH, ''Cinnamon'' consumer information (nccih.nih.gov/health/cinna", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H202', 'Cranesbill (Wild Geranium)', 'Geranium maculatum', 'Geraniaceae (the geranium and storksbill family)', 'Dried rhizome (root), the official Eclectic drug, known as alum root or cranesbill root. The leaf and aerial parts are also astringent and are used as a gentler, more sustainable tea.', 'Astringent (predominant, the puckering tannin taste) with a mild bitterness. King''s American Dispensatory lists it as a powerful, purely astringent drug free of any nauseous or acrid quality.', 'Cool. A tannin astringent is cooling and condensing to relaxed, inflamed, weeping tissue; the coolness is mild and secondary to a marked drying, tightening action.', 'Dry. A markedly drying astringent: the hydrolyzable tannins precipitate proteins, condense and tone the tissue, and check fluid loss and excess secretion.', 'Laxity and atony of the mucous membranes: the relaxed, boggy, leaking surfaces that weep profuse, debilitating discharges. Passive hemorrhage from atonic, ungripping vessels: chronic mucous diarrhea and dysentery, passive uterine bleeding (menorrhagia), blood in the urine, bleeding piles, and oozing wounds. Dampness expressed as chronic catarrh, leucorrhea, and watery, mucous stools. Ulceration of relaxed surfaces: aphthous sore mouth, thrush, spongy gums, indolent ulcers, and raw, weeping skin.', 'Frank dryness and fluid deficiency, which a drying astringent deepens, binding the bowel toward constipation. Atrophy of thinned, withered mucosa, which tannins only parch and shrink further. Cold depletion, poorly served by a cooling, contracting root. Acute, obstructed conditions where a discharge or pathogen must be expelled rather than checked and retained.', 'Digestive tract above all: the astringent of choice for relaxed, leaking gut mucosa, chronic mucous diarrhea, and dysentery. Reproductive: passive uterine hemorrhage (menorrhagia) and leucorrhea. Integumentary (skin) and the mucous membranes generally: bleeding wounds, indolent ulcers, aphthous sore mouth, and a sore, relaxed throat as a gargle. Urinary: hematuria and an irritable, catarrhal bladder. Secondary Respiratory, for passive pulmonary bleeding and chronic catarrh.', 'The premier non-irritating astringent for passive, atonic conditions. Chronic diarrhea and dysentery with profuse mucous discharge. Passive hemorrhage of any relaxed surface: menorrhagia and passive uterine bleeding, hematuria, bleeding hemorrhoids, oozing wounds and nosebleed (as a styptic powder), and passive gastric or pulmonary bleeding. Aphthous sore mouth, thrush, and ulcerated or spongy gums (as a wash or gargle). A relaxed, sore throat. Leucorrhea and relaxed vaginal discharge. Weeping, ulcerated skin and slow-healing wounds. It is especially suited to infants, the aged, and delicate stomachs on account of its freedom from irritating or nauseous qualities.', 'Damp-Relaxed: the boggy, atonic, leaky-membrane phenotype with passive, debilitating discharges and lax, ungripping tissue that weeps, oozes, and bleeds. Its cool, condensing dryness suits the relaxed, over-moist, mildly inflamed surface. Not for the thin, dry, cold, depleted (Vata-like) constitution, nor the dry melancholic, in whom a drying, binding astringent parches tissue and locks the bowel.', 'Pitta, Kapha', 'Vata', 'Not a classical Chinese materia medica herb (Geranium maculatum is a North American plant), but by nature it astringes and stops leakage and stops bleeding: it binds Dampness and chronic discharge (mucous diarrhea, leucorrhea, seminal or urinary leakage) and checks passive, non-clotting bleeding from lax vessels. Functionally it parallels the Chinese astringent and stop-bleeding class (the styptic role of herbs such as Di Yu or Ce Bai Ye) and secures leakage in chronic diarrhea of Spleen deficiency as a symptomatic astringent rather than a tonic.', 'Yin deficiency with dryness, which a drying astringent worsens. Acute, early-stage damp-heat dysentery or any exterior or acute pathogen that must be expelled: astringing too soon retains the pathogen (the classic caution against premature use of binders). Kidney Yang deficiency cold is poorly served by a cooling root.', 'A high-tannin astringent (historically assayed at about 13 to 17 percent tannin): reserve internal use for short courses, since sustained high-tannin intake can irritate the stomach, promote constipation, and impair the absorption of iron and other minerals. Give at least two hours apart from iron supplements, mineral supplements, and alkaloidal or other oral medications, whose absorption tannins reduce. Best avoided in iron-deficiency anemia, chronic constipation, and frank tissue dryness. Not a substitute for rehydration in acute infectious diarrhea, and not for undiagnosed or brisk bleeding, which needs medical evaluation. Discontinue if it causes nausea or constipation.', 'Frank tissue dryness, atrophy, and constipation (a drying, binding astringent). Iron-deficiency anemia and malnutrition (tannins impair mineral absorption). Prolonged or high-dose internal use. Concurrent dosing with iron, mineral supplements, thiamine, or alkaloidal and other oral drugs without a two-hour separation. Undiagnosed hemorrhage or acute infectious dysentery, which require medical assessment. Insufficient safety data in pregnancy and lactation: avoid sustained internal use.', 'Insufficient reliable data; avoid sustained internal use. Geranium maculatum has no documented uterine-stimulant, emmenagogue, or abortifacient action (it is a mechanical tannin astringent, used traditionally to check rather than to provoke uterine bleeding), so the concern is the absence of formal reproductive-safety studies together with its high tannin load, which can impair maternal iron absorption. Short-term topical use (styptic, wash) and a mouth gargle are low-risk; reserve any internal use for professional supervision. (AHPA Botanical Safety Handbook, 2nd ed.: no reliable pregnancy data for Geranium maculatum; general tannin-astringent caution, Mills and Bone, Principles and Practice of Phytotherapy.)', 'Insufficient data; short-term use likely low-risk, avoid sustained internal use. No lactation-specific studies exist for Geranium maculatum. As a large, poorly absorbed tannin molecule it is unlikely to reach milk in meaningful amounts, but sustained high-tannin intake can reduce maternal iron absorption. Topical and gargle use is not a concern; keep any internal use brief. (AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, Principles and Practice of Phytotherapy, on tannins.)', 'Traditionally a favored pediatric astringent: King''s American Dispensatory singles it out as well adapted to infants for cholera infantum and childhood diarrhea because it is non-irritating and free of nauseous qualities, and a dilute decoction is a classic wash for a child''s sore mouth and thrush. Modern guidance: use low doses for short courses only, since high-tannin herbs can impair iron absorption and constipate; do not use it in place of oral rehydration for acute diarrhea, and seek care for a dehydrated or persistently ill child. (AHPA Botanical Safety Handbook, 2nd ed.; NCCIH general guidance on unstudied botanicals in children. The pediatric-use tradition is cited from King''s 1898 as tradition, not as a modern safety clearance.)', 'Tannin-mediated absorption interference is the principal, well-characterized interaction. The hydrolyzable tannins in cranesbill precipitate and bind metal ions (iron, zinc, copper) and thiamine, and complex with alkaloidal and other basic drugs, reducing their absorption when taken together. Separate cranesbill from iron and mineral supplements, thiamine, and oral alkaloidal medications (for example ephedrine, and in principle other oral drugs) by at least two hours, and use it cautiously alongside iron-repletion therapy for anemia. No CYP450, anticoagulant, or other pharmacodynamic drug interactions are documented for Geranium maculatum. (Brinker, Herbal Contraindications and Drug Interactions, tannin-containing herbs; Mills and Bone, Principles and Practice of Phytotherapy, tannins; Brune and Hallberg, phenolic and tannin inhibition of non-heme iron absorption, PMID 2598894.)', 'Decoction of the dried rhizome (the standard Eclectic form; also used as a gargle, mouth wash, and rectal or vaginal injection). Tincture or specific/fluid extract of the root. Powdered dried root, taken internally or dusted directly on bleeding wounds and nosebleed as a styptic. Cold or warm infusion of the leaf and aerial parts (a gentler, more sustainable astringent tea). Compress or wash of the decoction on weeping skin, indolent ulcers, and hemorrhoids.', 'Powdered root: 20 to 30 grains (about 1.3 to 2 g) up to three times daily (King''s). Decoction: 1 to 2 fluid ounces of a standard root decoction, repeated as needed, and used undiluted or diluted as a gargle, mouth wash, or injection. Specific or fluid extract: 5 to 30 drops. Tincture (1:5): 2 to 4 mL up to three times daily. As a styptic, apply the powder directly to the bleeding surface. Use internally in short courses; reduce or stop if constipation or nausea occurs.', 'King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Geranium maculatum, for the Eclectic clinical detail.', 'Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Botanical Safety Handbook, 2nd ed. (Geranium maculatum); reviews of the ellagitannin geraniin, cranesbill''s principal hemostatic tannin (Phytochemistry Reviews, 2016).', 'Family Geraniaceae. The dried rhizome (alum root) is a hydrolyzable-tannin astringent, historically assayed at about 13 to 17 percent tannin (Bowman 1869; Kramer 1882, per King''s), part of the tannin converting to gallic acid on drying; its characteristic ellagitannin is geraniin, alongside gallic acid, pectin, gum, starch, resin, and calcium oxalate. Its astringency is non-irritating, which made it the Eclectic astringent of choice for infants and delicate patients and set it apart from harsher mineral astringents. It is a symptomatic astringent, styptic, and vulnerary, not a systemic alterative or tonic. Native American peoples (Cherokee, Iroquois, Chippewa, Meskwaki, and others) used the root for diarrhea, dysentery, hemorrhage, sore mouth and thrush, and as a wash, and the Eclectics standardized these uses. Both common names, cranesbill (from the beaked seed capsule) and spotted or wild geranium, denote this one species. Do not confuse it with Old World Geranium robertianum (herb Robert) or with the unrelated scented geranium oil of Pelargonium.', 'Not named in the canonical biblical texts. Geranium maculatum is a North American woodland native with no Old World or Mediterranean scriptural presence. Its documented tradition is Native American (Cherokee, Iroquois, Chippewa, Meskwaki, and others used the astringent root for diarrhea, sore mouth, and hemorrhage, and as a wash) and Eclectic and Physiomedical American, standardized in King''s American Dispensatory (Felter and Lloyd, 1898) and admitted to the United States Pharmacopoeia. The cranesbill of Dioscorides and the European herbals is a different plant (Geranium robertianum and Geranium sanguineum), so classical Mediterranean citations should not be transferred to this American species.', 'Geranium maculatum is a common, widespread native woodland wildflower of eastern North America and is not listed as at-risk by United Plant Savers (unlike its Eclectic neighbors goldenseal and bloodroot). It is not endangered. Root harvest, however, kills the plant, and its slow-spreading clonal colonies are slow to recover, so prefer cultivated root, or harvest the astringent leaf and aerial parts (which regrow) instead of the rhizome where these suffice.', 'Cool and drying: a non-irritating tannin astringent that tightens lax, weeping mucous membranes, stanches passive hemorrhage and chronic diarrhea, and knits raw, ulcerated, or bleeding tissue.', 'Refer for any brisk, unexplained, or persistent bleeding (vomiting or coughing blood, black or bloody stool, blood in the urine, postmenopausal bleeding, or menorrhagia causing anemia); diarrhea or dysentery with high fever, blood, severe pain, or signs of dehydration, and any diarrhea in an infant, elderly, or frail person that does not quickly settle (rehydration and diagnosis come first); non-healing ulcers or wounds; and undiagnosed pelvic or urinary bleeding. Cranesbill checks a symptom (bleeding, discharge, loose stool) and can mask a condition that needs diagnosis, so treat it as a short-term adjunct, not a remedy for the underlying cause.', 'Cranesbill: KRAYNZ-bil. Wild geranium / Geranium maculatum: jeh-RAY-nee-um mak-yoo-LAY-tum.', 'free', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "locator": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H202', 'T04');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H202', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS09', 'Primary', 'Laxity and atony of the mucous membranes: the core indication; tones relaxed, leaking surfaces.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS07', 'Secondary', 'Dampness: dries profuse mucous discharge, catarrh, leucorrhea, and watery stools.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS25', 'Secondary', 'Ulceration: aphthous sore mouth, spongy gums, indolent ulcers, weeping skin.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS03', 'Primary', 'Dryness: a drying astringent deepens fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS02', 'Secondary', 'Atrophy: tannins parch and shrink already thinned, withered mucosa.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS12', 'Minor', 'Constriction: binding astringency can worsen a constricted, constipated bowel.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H202', 'TS17', 'Minor', 'Cold: a cooling, contracting root is poorly suited to frank cold depletion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H202', 'SY08', 'Primary', 'Digestive: chronic mucous diarrhea, dysentery, and relaxed, leaking gut mucosa.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H202', 'SY03', 'Primary', 'Reproductive: passive uterine hemorrhage (menorrhagia) and leucorrhea.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H202', 'SY10', 'Secondary', 'Skin and mucous membranes: bleeding wounds, ulcers, aphthous sore mouth, gargle.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H202', 'SY09', 'Secondary', 'Urinary: hematuria and irritable, catarrhal bladder.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H202', 'SY07', 'Minor', 'Respiratory: passive pulmonary bleeding and chronic catarrh.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A15', 'Primary', 'Astringent: the defining action; tannins tone and condense lax tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A50', 'Primary', 'Styptic/hemostatic: checks passive hemorrhage; geraniin-mediated, used as a styptic powder.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A24', 'Secondary', 'Vulnerary: heals wounds and indolent ulcers; topical astringent.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A09', 'Secondary', 'Anti-inflammatory: soothes and tones inflamed, weeping mucous membranes.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A23', 'Minor', 'Tonic: an astringent tonic to lax, atonic tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H202', 'A28', 'Minor', 'Antimicrobial: tannins are mildly antimicrobial, of use in infective diarrhea and sore mouth.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H202', 'CP56', 'Primary', 'Chronic diarrhea and dysentery with mucous discharge; the headline use.');
