INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H202', 'TCM01', 'Minor', 'Kidney Yang deficiency: a cooling, contracting root is unsuited to yang-deficient cold.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "locator": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI869', 'H202', 'pregnancy', 'Pregnancy', 'moderate', 'No formal reproductive-safety data; the herb has no known uterine-stimulant or abortifacient action, but its high tannin content can impair maternal iron absorption and sustained internal safety is unestablished.', 'Avoid sustained internal use in pregnancy; short-term topical or gargle use is low-risk. Use internally only under professional supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (Geranium maculatum, no reliable pregnancy data); Mills and Bone, Principles and Practice of Phytotherapy (tannin astringents).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI870', 'H202', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation-safety data; a poorly absorbed tannin is unlikely to reach milk, but sustained high-tannin intake can reduce maternal iron absorption.', 'Keep any internal use brief; topical and gargle use is not a concern.', 'AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, Principles and Practice of Phytotherapy (tannins).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI871', 'H202', 'drug_interaction', 'Iron and mineral supplements, thiamine, and alkaloidal or other oral drugs', 'moderate', 'Hydrolyzable tannins precipitate and bind iron, zinc, copper, and thiamine and complex with alkaloidal and basic drugs, reducing their absorption when taken concurrently.', 'Separate cranesbill from iron, mineral supplements, thiamine, and oral medications by at least two hours; use cautiously alongside iron-repletion therapy.', 'Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); Mills and Bone, Principles and Practice of Phytotherapy; Brune and Hallberg, PMID 2598894 (phenolic/tannin inhibition of iron absorption).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI872', 'H202', 'condition', 'Iron-deficiency anemia, chronic constipation, and malnutrition', 'moderate', 'Tannins reduce mineral (especially iron) absorption and a binding astringent can aggravate constipation.', 'Avoid prolonged internal use in these states; correct anemia and constipation independently.', 'Mills and Bone, Principles and Practice of Phytotherapy (tannins); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI873', 'H202', 'other', 'Prolonged or high-dose internal use', 'low', 'Sustained high intake of a 13 to 17 percent tannin astringent can irritate the stomach, constipate, and impair nutrient absorption.', 'Use internally in short courses rather than continuous long-term use; prefer the milder leaf tea for repeated use.', 'AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, Principles and Practice of Phytotherapy (tannin-rich astringents).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI874', 'H202', 'other', 'Undiagnosed hemorrhage or acute infectious dysentery', 'moderate', 'As a symptomatic astringent it can mask serious bleeding or check an infective process that should be diagnosed and cleared, and it does not replace rehydration.', 'Do not use to self-treat brisk or unexplained bleeding or febrile/bloody dysentery; refer for diagnosis and ensure rehydration.', 'King''s American Dispensatory (Felter and Lloyd, 1898) for the astringent indication; modern clinical-referral standard (NCCIH consumer guidance).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H202', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "locator": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
