INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H202', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Geranium (Geranium maculatum); earlier admitted to the United States Pharmacopoeia as Geranium, U.S.P. Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Gerani", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "locator": "Grieve, A Modern Herbal (1931), Cranesbill / American Cranesbill; Mills and Bone, Principles and Practice of Phytotherapy (tannins and astringents); Brinker, Herbal Contraindications and Drug Interactions (tannin-containing herbs); AHPA Bot", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H203', 'Culver''s Root (Culver''s Physic, Black Root, Bowman''s Root, Leptandra)', 'Veronicastrum virginicum (L.) Farw.', 'Plantaginaceae (plantain family). Historically placed in Scrophulariaceae (the figwort family); the genus was moved to Plantaginaceae on molecular grounds in the early 2000s, so older Eclectic and herbal sources still file it under Scrophulariaceae.', 'Root and rhizome, DRIED and aged at least one year. The fresh (undried) root is a violent emetic and cathartic and is not used; drying and aging destroy the drastic, acrid quality and leave a gentler cholagogue, hepatic stimulant, and bitter tonic.', 'Bitter (predominant) and Pungent (acrid), with an astringent undertone from the tannins.', 'Cool. The bitter, clearing quality of a cooling hepatic and cholagogue.', 'Dry. Bitter and draining; the drying, decongesting action of a cholagogue-laxative.', 'Hepatic and biliary torpor: the sluggish, atonic, underactive liver with thick, slow bile, the bilious and congested hepatic picture behind non-obstructive jaundice, constipation of the upper bowel, and bilious headache. Atony and boggy laxity of the digestive tract with foul, sluggish digestion, the torpid state that a bitter stimulant rouses. Damp, congested heat in the liver and gallbladder, and passive portal and venous congestion downstream of a slow liver.', 'Cold, dry, deficient, and depleted constitutions, where a cooling, drying, draining bitter only chills, empties, and further dries. Exhaustion and true debility, quenched rather than helped by a purgative bitter. Frank fluid dryness. Acute inflammation of the bowel and any acute biliary obstruction or impacted gallstone, where a cholagogue that drives bile is dangerous.', 'Hepatic (liver) and biliary above all, the seat of its cholagogue, choleretic, hepatic-stimulant action, and the Digestive tract (gastric, intestinal: a bitter tonic that rouses torpid digestion and gently opens the bowel). Secondary Urinary (mild diuresis, used in the old dropsy indication) and, through hepatic clearance, the Integumentary (skin) as a background alterative.', 'The classic Eclectic hepatic and cholagogue for chronic hepatic torpor and biliary congestion: the sluggish, bilious, congested liver with thick, slow bile. Non-obstructive (catarrhal) jaundice. Bilious dyspepsia and low, foul digestion. Constipation of the upper bowel from a slow liver, and the atonic, sluggish bowel. Bilious headache. Hepatic-origin nausea (small doses settle the bilious stomach). Chronic diarrhea and dysentery of the atonic, dried-root type. A background alterative for skin conditions rooted in poor hepatic clearance.', 'The cold, damp, sluggish, boggy, torpid-liver phenotype, the still-water type whose hepatic and digestive function has gone atonic and congested, and equally the hot, bilious, congested (choleric) liver that a cool, draining bitter cools and decongests. Not for the thin, cold, dry, depleted (Vata-like) or exhausted constitution, whom a bitter, cooling, purgative cholagogue chills, dries, and empties.', 'Pitta, Kapha', 'Vata', 'Best read as Damp-Heat of the Liver and Gallbladder (the bilious, jaundiced, congested liver: bitter and cold, it drains damp-heat and promotes the flow of bile) and Liver Qi and bile stagnation with hepatic congestion, which its cholagogue action unblocks. It also clears Heat/Fire from the Liver and Gallbladder in bilious, hot states. Culver''s root is a Western botanical with no classical Chinese record; this is an energetic mapping, not a traditional Chinese materia medica entry.', 'Spleen and Stomach deficiency-cold with poor appetite and loose stools, which a bitter, cold, purgative cholagogue worsens. Qi deficiency and Kidney Yang deficiency (cold, depleted patterns), where a draining, cooling herb is wrong. Wind-Cold exterior patterns. Any presentation without damp-heat, bile stasis, or hepatic congestion, where a purgative bitter is unnecessary and depleting.', 'Use only the DRIED root, aged at least one year. The fresh root is a violent emetic and cathartic (severe vomiting, purging, vertigo, bloody stools) and has been associated with miscarriage. Overdose even of the dried root purges and gripes, so begin at low doses and titrate. As a cholagogue it should be avoided in acute gallstone attack or bile-duct obstruction, and its laxative action can aggravate internal hemorrhoids and acute inflammatory bowel conditions. Traditionally avoided during menstruation. Being bitter, cool, and drying, it is ill-suited to the cold, dry, depleted, or exhausted constitution.', 'Pregnancy and lactation. Use of the fresh (undried) root in any form. Acute biliary obstruction, impacted or symptomatic gallstones, and acute inflammatory bowel conditions. Internal hemorrhoids (cathartic aggravation). Cold, dry, deficient, or exhausted constitutions, and Spleen/Stomach deficiency-cold (TCM). Caution during menstruation.', 'Avoid. Culver''s root is contraindicated in pregnancy: the fresh root is a violent cathartic and emetic with a recorded risk of provoking miscarriage, and the dried root is a bitter cholagogue-laxative whose safety in pregnancy has not been established. Both the modern herbal-safety literature and the historical Eclectic texts advise against use. (Brinker, Herbal Contraindications and Drug Interactions, lists Culver''s root / Leptandra as contraindicated in pregnancy; Review of Natural Products, Facts and Comparisons; the abortifacient risk of the fresh root is additionally recorded in King''s American Dispensatory, 1898.)', 'Avoid; insufficient data. There are no human lactation-safety studies for Culver''s root, and a bitter cathartic principle could in theory pass into the milk and purge the infant. In the absence of any margin-of-safety data, avoid during breastfeeding and prefer better-characterised hepatics. (AHPA Botanical Safety Handbook, 2nd ed., notes insufficient lactation data; Brinker, Herbal Contraindications and Drug Interactions.)', 'Not recommended for internal use in infants and young children; for older children only under qualified supervision at low, short-course doses of the DRIED root, never the fresh. The fresh or overdosed root is a drastic purgative and emetic. Historically the dried root was given in very small doses for childhood diarrhea during dentition (King''s American Dispensatory), but modern pediatric safety data are lacking, so the conservative verdict is avoidance except under professional guidance. (AHPA Botanical Safety Handbook; Brinker, Herbal Contraindications and Drug Interactions.)', 'No well-documented, clinically confirmed drug interactions are established for Culver''s root; the available data are limited. On theoretical grounds shared by bitter cholagogue-laxative herbs: with prolonged or high (cathartic) dosing, laxative-type potassium loss could potentiate cardiac glycosides (digoxin) and add to potassium-depleting drugs (thiazide and loop diuretics, corticosteroids, licorice); as a cholagogue it may add to other bile-stimulating agents and should be kept away from bile-duct obstruction. These are precautionary extrapolations from the herb''s actions, not confirmed interactions. (Brinker, Herbal Contraindications and Drug Interactions; Review of Natural Products, Facts and Comparisons.)', 'Decoction of the dried, aged root. Tincture of the dried root (1:5). Cold or standard infusion of the dried root. Powdered dried root (small doses; large doses are cathartic). Capsules of the dried root. Never the fresh root, and never as an essential oil.', 'Use only dried root aged at least one year. Tincture (1:5, dried root): 1 to 20 drops (roughly 0.05 to 1 mL), 1 to 3 times daily, starting at the low end. Decoction or infusion: about 1 teaspoon of dried root per cup, up to 3 times daily. Powdered dried root: keep well below the old cathartic dose of 20 to 60 grains (about 1.3 to 4 g); a hepatic-tonic dose is a fraction of this. Reduce or stop at any sign of griping or purging. Never use the fresh root.', 'King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).', 'Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraindicated in pregnancy; avoid with bile-duct obstruction, gallstones, internal hemorrhoids, menstruation); AHPA Botanical Safety Handbook, 2nd ed. (reviewed 2021); Review of Natural Products, Facts and Comparisons (Culver''s root monograph, drugs.com).', 'Family Plantaginaceae; the former placement in Scrophulariaceae (figwort family) was split on molecular grounds in the early 2000s, and many herb references still list the obsolete family. The Eclectic drug name ''Leptandra'' derives from the synonyms Leptandra virginica (Nutt.) and Veronica virginica (L.); Farwell''s combination Veronicastrum virginicum is the accepted name. Root constituents include a bitter glycosidic/resinoid principle historically called leptandrin, iridoid glycosides, cinnamic-acid derivatives (4-methoxy- and 3,4-dimethoxycinnamic acids and their esters), a volatile oil, saponins, and tannins; the isolated ''resinoid'' leptandrin was largely abandoned by the Eclectics in favour of the dried alcoholic extract. Drying, or aging at least one year, destroys the acrid, drastically cathartic-emetic quality of the fresh root, leaving a gentler cholagogue, hepatic stimulant, mild laxative, and bitter tonic used for hepatic torpor, biliary congestion, non-obstructive jaundice, and bilious dyspepsia. Modern clinical and pharmacological data are sparse; the profile rests on the Eclectic and Physio-Medical record and the general pharmacology of bitter cholagogues.', 'Not named in the canonical biblical texts, and with no Old-World or Mediterranean classical record: Culver''s root is a North American native (eastern and central USA and Canada). Its documented tradition is Native American (used by the Seneca, Menominee, and other peoples as an emetic, purgative, and liver remedy) and, following them, the 19th-century Eclectic and Physio-Medical physicians (King''s American Dispensatory; Cook''s Physio-Medical Dispensatory).', 'Culver''s root is a perennial of moist prairies, meadows, and open woods across eastern and central North America and is widely grown as a garden ornamental, so cultivated root is readily available. It is not listed as at-risk by United Plant Savers. Wild stands have declined regionally with prairie and wet-meadow habitat loss, and because root and rhizome harvest kills the plant, prefer cultivated or nursery-propagated stock over wild digging.', 'Cool and drying: a bitter hepatic stimulant and cholagogue that rouses a torpid, congested liver, thins and moves sluggish bile, and gently opens the bowel.', 'Refer for jaundice (yellowing of the skin or eyes), which needs diagnosis rather than self-treatment; severe or persistent right-upper-quadrant or abdominal pain, suspected gallstones or biliary obstruction, or fever with abdominal pain; persistent vomiting or vomiting of blood; black, tarry, or bloody stools; unexplained weight loss; and any established liver disease, hepatitis, or abnormal liver function. Refer before use in pregnancy or breastfeeding, and if any purging, severe griping, or vertigo follows a dose (signs of overdose or of fresh-root material).', 'Culver''s Root: KUL-verz root. Veronicastrum virginicum: veh-RON-ih-KAS-trum vir-JIN-ih-kum. Leptandra: lep-TAN-druh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "locator": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H203', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H203', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H203', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS19', 'Primary', 'Torpor: the sluggish, atonic, underactive liver and bowel that a bitter stimulant rouses (the defining state).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS08', 'Secondary', 'Stagnation: biliary and portal congestion, thick slow bile, which the cholagogue unblocks (prose renders this as ''congestion'' to keep the derived tone clean).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS11', 'Secondary', 'Depression: depressed hepatic and digestive function.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS07', 'Secondary', 'Dampness: damp-heat and boggy congestion in the liver and gallbladder.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS09', 'Minor', 'Laxity: the atonic, boggy, sluggish bowel.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS05', 'Minor', 'Excess Heat: bilious heat in the liver and gallbladder.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS17', 'Primary', 'Cold: a cooling herb aggravates a cold constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS01', 'Primary', 'Deficiency: a draining, purgative bitter empties the depleted further.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS03', 'Secondary', 'Dryness: a drying bitter worsens fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS04', 'Secondary', 'Exhaustion: a purgative cooling herb further weakens the truly spent.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H203', 'TS06', 'Minor', 'Acute Inflammation: acute bowel inflammation or acute biliary obstruction, where a cholagogue-cathartic is dangerous.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H203', 'SY12', 'Primary', 'Hepatic: the seat of its cholagogue, choleretic, hepatic-stimulant action.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H203', 'SY08', 'Primary', 'Digestive: bitter tonic that rouses torpid digestion and gently opens the bowel.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H203', 'SY09', 'Minor', 'Urinary: mild diuresis (the old dropsy indication).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A43', 'Primary', 'Cholagogue: promotes the flow of bile from a torpid liver (the defining action).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A16', 'Primary', 'Bitter Tonic: bitter hepatic and digestive stimulant.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A44', 'Secondary', 'Choleretic: increases the biliary secretions (King''s).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A38', 'Secondary', 'Laxative: the dried root gently opens the constipated upper bowel (the fresh root is drastically cathartic).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A14', 'Secondary', 'Alterative: depurative through hepatic and biliary clearance.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A45', 'Minor', 'Antiemetic: small doses settle bilious, hepatic-origin nausea.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A15', 'Minor', 'Astringent: tannins; the dried root for chronic diarrhea and dysentery.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A28', 'Minor', 'Antimicrobial: the traditional antiseptic action attributed to the root.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H203', 'A08', 'Minor', 'Diuretic: mild; the historical dropsy use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP72', 'Primary', 'Sluggish liver / bile stagnation: the headline hepatic-torpor and biliary-congestion indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP74', 'Secondary', 'Cholestasis / non-obstructive (catarrhal) jaundice.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP55', 'Secondary', 'Constipation of the upper bowel from a slow liver.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP58', 'Secondary', 'Bilious dyspepsia and low, foul digestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP57', 'Minor', 'Nausea of bilious, hepatic origin (small doses).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP73', 'Minor', 'Hangover / bilious congestion cleared through hepatic action.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP56', 'Minor', 'Chronic diarrhea and dysentery of the atonic, dried-root type.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP18', 'Minor', 'Skin conditions rooted in poor hepatic clearance (background alterative).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H203', 'CP19', 'Minor', 'Bilious headache.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H203', 'P04', 'Primary', 'Decoction of the dried, aged root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H203', 'P01', 'Primary', 'Tincture of the dried root (1:5).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H203', 'P03', 'Secondary', 'Powdered dried root (small, sub-cathartic doses).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H203', 'P05', 'Secondary', 'Infusion of the dried root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H203', 'P02', 'Minor', 'Capsules of the dried root.');
