INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H203', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "locator": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI875', 'H203', 'pregnancy', 'Pregnancy', 'absolute', 'The fresh root is a violent cathartic and emetic with a recorded risk of provoking miscarriage; the dried root is a bitter cholagogue-laxative. Safety in pregnancy is not established.', 'Do not use during pregnancy in any form or preparation.', 'Brinker, Herbal Contraindications and Drug Interactions (Culver''s root / Leptandra contraindicated in pregnancy); Review of Natural Products, Facts and Comparisons.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI876', 'H203', 'breastfeeding', 'Breastfeeding', 'moderate', 'No human lactation-safety data; a bitter cathartic principle could pass into milk and purge the infant.', 'Avoid while breastfeeding; prefer better-characterised hepatics.', 'AHPA Botanical Safety Handbook, 2nd ed. (insufficient lactation data); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI877', 'H203', 'other', 'Fresh (undried) root', 'absolute', 'The fresh root is a drastic emetic and cathartic, causing severe vomiting, purging, vertigo, and bloody stools; drying or aging at least one year removes this drastic quality.', 'Use only the dried root aged at least one year; never use the fresh root.', 'Review of Natural Products, Facts and Comparisons; corroborated historically by King''s American Dispensatory, 1898.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI878', 'H203', 'condition', 'Bile-duct obstruction and symptomatic gallstones', 'absolute', 'As a cholagogue that drives bile flow, it can precipitate biliary colic or worsen obstruction when the duct is blocked or stones are present.', 'Do not use with bile-duct obstruction or acute/symptomatic gallstones.', 'Brinker, Herbal Contraindications and Drug Interactions; standard cholagogue contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI879', 'H203', 'condition', 'Internal hemorrhoids and acute inflammatory bowel conditions', 'moderate', 'The cathartic/laxative action can aggravate internal hemorrhoids and acute intestinal inflammation.', 'Avoid in active internal hemorrhoids and acute inflammatory bowel states.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI880', 'H203', 'condition', 'Menstruation', 'moderate', 'Traditionally avoided during menstruation (pelvic and uterine stimulation, possible increased flow).', 'Use caution or avoid during menses.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI881', 'H203', 'drug_interaction', 'Cardiac glycosides (digoxin) and potassium-depleting drugs (thiazide/loop diuretics, corticosteroids, licorice)', 'low', 'Theoretical only: with prolonged or high (cathartic) dosing, laxative-type potassium loss could potentiate cardiac glycosides and add to potassium-depleting agents. Not a documented clinical interaction.', 'Avoid prolonged/high dosing; use ordinary hepatic-tonic doses short-term and monitor if combined.', 'Brinker, Herbal Contraindications and Drug Interactions; general stimulant-laxative pharmacology (Review of Natural Products, Facts and Comparisons).');
