INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H203', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Leptandra (Veronica virginica / Leptandra virginica).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "locator": "Cook, The Physio-Medical Dispensatory (1869), Leptandra virginica; Felter, The Eclectic Materia Medica, Pharmacology and Therapeutics (1922); Grieve, A Modern Herbal (1931); Brinker, Herbal Contraindications and Drug Interactions (contraind", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H204', 'Grindelia (Gumweed)', 'Grindelia robusta', 'Asteraceae (Compositae; the daisy, aster, and sunflower family)', 'Dried leaves and flowering tops (the resinous, sticky flower heads gathered at or just before full bloom). The pharmacopoeial drug Grindeliae herba is collected from Grindelia robusta, Grindelia camporum, and Grindelia squarrosa.', 'Pungent and bitter, with a resinous, balsamic aromatic quality and a hint of astringency. King''s American Dispensatory records the taste as ''pungently aromatic and bitter,'' the odor balsamic.', 'Warm. Herbalist tradition classes grindelia as a warming, resinous, aromatic expectorant, suited to chilled, boggy, congested lungs and to phlegm that lingers after the acute phase of a chest infection.', 'Dry. The resinous, aromatic, bitter herb is drying and decongesting, reducing boggy catarrh and thinning stuck lung mucus.', 'Bronchial constriction and tension: relaxes the spasm of asthma, spasmodic and whooping cough, and wheezing chests. Stagnation of the lungs: moves and dries stuck, boggy, rattling phlegm and chronic bronchial catarrh, and helps clear mucus that lingers after the acute phase of a chest infection. Topically, the congested, weeping, inflamed skin of poison-oak and poison-ivy dermatitis.', 'Dryness and atrophy of the mucous membranes: a warm, resinous, drying herb aggravates a dry, unproductive, yin-deficient cough and parched, thinned respiratory tissue. Frank heat and high acute inflammation of the airway, where a cooling remedy suits better than a warming one. It is also not for the depleted heart or the diseased kidney, which its dose-dependent cardiac depression and renal irritation can burden.', 'Respiratory above all, the seat of its antispasmodic and expectorant action on the bronchi. Integumentary (skin), for topical poison-oak and poison-ivy dermatitis, wounds, burns, and boils. Urinary (a mild diuretic, used traditionally for chronic cystitis and bladder catarrh, though it irritates the kidneys in excess). Cardiovascular and Nervous secondarily, reflecting a dose-dependent sedative effect on the heart, respiration, and motor activity.', 'Spasmodic respiratory complaints above all: asthma and asthmatic wheezing, bronchitis with copious mucus, whooping cough and other spasmodic coughs, and boggy, rattling chests where phlegm lingers after a cold. Catarrh of the upper respiratory tract (the Commission E and ESCOP indication). Topically, the classic remedy for poison-oak and poison-ivy (Rhus) dermatitis, and for wounds, burns, boils, and inflamed skin. Traditionally also for chronic cystitis and bladder catarrh as a mild urinary antiseptic and diuretic, and, as Grindelia squarrosa, for splenic congestion and dyspepsia.', 'Cold-Damp-Relaxed with bronchial constriction: the chilled, damp, boggy, congested respiratory phenotype whose wet, rattling chest also seizes into spasm and wheeze, met by a warming, drying, antispasmodic expectorant. Not for the thin, dry, hot, yin-deficient type with a dry, hacking, unproductive cough, whom its resinous warmth and dryness only parch further.', 'Kapha', 'Vata, Pitta', 'Phlegm-Damp obstructing the Lung: transforms and dries damp, boggy phlegm and stops the productive, rattling cough and wheeze. Cold-Phlegm and wind-cold wheezing: a warming expectorant for cold, wet chests. It also relieves the chest constriction and Qi stagnation of spasmodic, wheezing cough. Best for cold-damp and phlegm-damp Lung patterns, not for Lung heat or dryness.', 'Yin Deficiency with a dry, unproductive cough, which a warm, drying, resinous herb worsens. Lung Heat and Fire patterns with a hot, dry, or blood-streaked cough, where its warmth is unsuited. Use warming, drying grindelia only where the phlegm is cold, damp, and copious.', 'Grindelia is a resinous herb (the sticky flower heads carry up to roughly a third resin, rich in grindelic and other diterpene acids). In large doses it irritates the kidneys, which is the basis of its diuretic effect, and it depresses the heart and respiration, so large or prolonged internal doses should be avoided, especially in cardiac or renal disease. It can cause gastric upset or loose stools in sensitive people. As a member of the Asteraceae (daisy) family it can provoke allergic reactions and contact dermatitis in Compositae-sensitive individuals, an irony given its topical use for poison-oak rash. Grindelia species also accumulate selenium and heavy metals from the soil, so harvest only from clean ground and avoid roadside or contaminated sites.', 'Large or prolonged internal doses (renal irritation, cardiac and respiratory depression). Pre-existing kidney disease, and cardiac disease or marked hypotension. Pregnancy and lactation (insufficient data). Known Asteraceae/Compositae allergy. Avoid material wild-harvested from selenium-rich or contaminated soils.', 'Avoid; insufficient data. Grindelia has no established safety record in pregnancy: there are no adequate human or animal reproductive studies, and both the AHPA Botanical Safety Handbook approach for insufficiently-studied botanicals and the modern European monographs (ESCOP, German Commission E) default to avoidance in the absence of data. Grindelia is additionally a documented renal irritant in larger doses, which further argues against use in pregnancy. It is not a classical emmenagogue or abortifacient, so the concern is lack of data plus the renal-irritant potential rather than a proven uterine action. (AHPA Botanical Safety Handbook, 2nd ed.; ESCOP Grindeliae herba monograph.)', 'Avoid; insufficient data. No lactation-safety studies exist for Grindelia, and the resinous diterpene acids have not been characterised for transfer into milk. In the absence of data the prudent course, consistent with the AHPA Botanical Safety Handbook approach and the ESCOP and Commission E monographs, is to avoid internal use while breastfeeding and prefer better-studied respiratory herbs. (AHPA Botanical Safety Handbook, 2nd ed.; ESCOP Grindeliae herba.)', 'Use only in low, short courses under qualified supervision, and avoid large doses. Eclectic physicians did give small pediatric doses of grindelia for whooping cough and spasmodic bronchial cough (King''s American Dispensatory lists reduced children''s doses of the fluid extract and specific medicine), so there is a traditional pediatric use, but modern references provide no formal pediatric safety data. Because large doses irritate the kidneys and can depress the heart and respiration, keep to small, short-term, professionally guided dosing and avoid in infants. (King''s American Dispensatory 1898 for the historical pediatric dose; modern pediatric safety data lacking, AHPA Botanical Safety Handbook.)', 'No well-documented clinical drug interactions are established for Grindelia; the following are precautionary, extrapolated from its pharmacology (limited data). Antihypertensive drugs: large doses of grindelia lower blood pressure and depress the heart and respiration, so additive hypotension or bradycardia is theoretically possible; monitor. Cardiac glycosides (digoxin) and other negative chronotropes: theoretical additive cardiac depression, so use cautiously. Nephrotoxic drugs: because the resins irritate the kidneys in large or prolonged doses, avoid stacking additional renal burden. (Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.)', 'Tincture or fluid/liquid extract of the dried herb, the standard internal form since alcohol is needed to hold the resins. Infusion (tea) of the dried leaf and flowering tops. Cough syrup. Topically as a salve or ointment, a lotion, a compress or wash, or diluted tincture for poison-oak and poison-ivy dermatitis, wounds, burns, and boils.', 'Tincture (1:5, 45 to 60 percent alcohol, needed to hold the resins): 2 to 4 mL up to three times daily. Liquid/fluid extract (1:1): 0.5 to 2 mL three times daily (the historical Eclectic fluid-extract dose was about 0.6 to 4 mL, 10 to 60 minims). Infusion of the dried herb: 2 to 3 g in hot water up to three times daily; German Commission E gives a total of 4 to 6 g of herb per day. Topically as a lotion, compress, salve, or diluted tincture for poison-oak dermatitis and minor wounds. Avoid large or prolonged internal doses (renal irritation).', 'King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).', 'ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindications and Drug Interactions; Felter, Eclectic Materia Medica (1922).', 'Family Asteraceae (Compositae); the pharmacopoeial gumweed of the Eclectic physicians and of the German Commission E and ESCOP, which approve Grindeliae herba for catarrh of the upper respiratory tract. ''Grindelia robusta'' Nutt. is the historical trade and pharmacopoeial name; modern taxonomy increasingly treats robusta as a synonym or member of the highly variable Grindelia camporum / Grindelia hirsutula complex, and the official drug is gathered from G. robusta, G. camporum, and G. squarrosa. The sticky, resin-coated flower heads contain up to roughly 20 to 30 percent resin rich in grindelic acid and related labdane diterpene acids, plus an essential oil (borneol, limonene, pinene, germacrene-D), flavonoids (quercetin, kaempferol, luteolin), plant sterols, saponins, and phenolic acids; the bronchodilating, antispasmodic, and expectorant reputation rests largely on this resin fraction. Grindelia is also a classic Indigenous and Eclectic topical for Rhus (poison-oak and poison-ivy) dermatitis and for wounds, burns, and boils.', 'Not named in the canonical biblical texts and not a Mediterranean plant. Grindelia is a North American native of the western United States and Mexico, taken into Eclectic and later European practice from Indigenous North American use for bronchial and skin complaints. Its tradition of origin is Native American and Eclectic-American, not biblical.', 'Grindelia robusta and its relatives are hardy, weedy, drought-tolerant natives of open ground, roadsides, and disturbed soils across the western United States and Mexico, common and not threatened, and not listed by United Plant Savers. It is easily wild-harvested or cultivated. Because Grindelia accumulates selenium and heavy metals from the soil, harvest only from clean, uncontaminated ground, well away from roadsides and industrial sites, both for the plant''s sake and the user''s safety.', 'Warm and drying: a resinous, pungent-bitter antispasmodic expectorant that relaxes bronchial spasm and dries the boggy, congested, cold-damp lung.', 'Refer for severe or acute asthma or any breathing emergency (grindelia does not replace a rescue inhaler); high fever, chest pain, coughing up blood, or rust-colored or purulent sputum suggesting pneumonia; a cough lasting more than a few weeks or with weight loss or night sweats; known kidney or heart disease before internal use; and any pregnancy or breastfeeding. A poison-oak reaction involving the face, eyes, or genitals, or covering a large area, or any rapidly spreading skin infection, needs medical care rather than topical grindelia alone.', 'Grindelia: grin-DEE-lee-uh. Gumweed: GUM-weed. Grindelia robusta: grin-DEE-lee-uh roh-BUST-uh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "locator": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H204', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H204', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H204', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS12', 'Primary', 'Constriction: relaxes bronchial spasm in asthma and spasmodic cough.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS18', 'Primary', 'Tension: eases the muscular tension of wheeze and whooping cough.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS08', 'Secondary', 'Stagnation: moves stuck, boggy, congested phlegm and chronic catarrh.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS23', 'Secondary', 'Phlegm: expectorant for damp, rattling bronchial phlegm.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS07', 'Secondary', 'Dampness: dries wet, boggy, catarrhal mucous membranes.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS14', 'Minor', 'Chronic infection: lingering chronic bronchial catarrh after infection.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS03', 'Primary', 'Dryness: a warm, resinous, drying herb worsens a dry, unproductive cough.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS02', 'Secondary', 'Atrophy: parched, thinned respiratory mucosa is further dried.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H204', 'TS05', 'Minor', 'Excess heat: a warming herb is less suited to a frankly hot, inflamed airway.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H204', 'SY07', 'Primary', 'Respiratory: antispasmodic, expectorant action on the bronchi; the headline use.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H204', 'SY10', 'Secondary', 'Skin: topical poison-oak/ivy dermatitis, wounds, burns, and boils.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H204', 'SY09', 'Secondary', 'Urinary: mild diuretic; chronic cystitis and bladder catarrh (irritant in excess).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H204', 'SY06', 'Minor', 'Cardiovascular: dose-dependent sedative to the heart; the site of a key caution.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H204', 'SY01', 'Minor', 'Nervous: antispasmodic control of bronchial muscle; mild motor sedation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A10', 'Primary', 'Antispasmodic: relaxes bronchial spasm, wheeze, and spasmodic cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A12', 'Primary', 'Expectorant: the resin fraction loosens and expels boggy phlegm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A33', 'Secondary', 'Antitussive: quiets spasmodic and whooping cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A22', 'Secondary', 'Sedative: dose-dependent depression of heart, respiration, and motor activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A24', 'Secondary', 'Vulnerary: topical healing of poison-oak dermatitis, wounds, and burns.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A09', 'Secondary', 'Anti-inflammatory: topical and in-vitro anti-inflammatory activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A08', 'Minor', 'Diuretic: mild diuresis (via renal irritation); traditional bladder catarrh use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A28', 'Minor', 'Antimicrobial: in-vitro antibacterial and antifungal activity of the resin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A46', 'Minor', 'Anti-allergic: relieves allergic wheeze; soothes allergic (Rhus) contact dermatitis.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H204', 'A16', 'Minor', 'Bitter tonic: the pungent-bitter taste; the digestive use of G. squarrosa.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP53', 'Primary', 'Asthmatic tendency: relaxes bronchospasm and eases asthmatic wheeze.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP51', 'Primary', 'Bronchial congestion: bronchitis with copious, boggy mucus.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP49', 'Primary', 'Cough productive: wet, rattling, spasmodic, and whooping cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP17', 'Secondary', 'Respiratory issues general: catarrh of the upper respiratory tract (ESCOP/Commission E).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP18', 'Secondary', 'Skin conditions general: topical poison-oak/ivy dermatitis, wounds, burns, boils.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP42', 'Secondary', 'Allergic reactivity: allergic wheeze and Rhus allergic contact dermatitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP65', 'Minor', 'Urinary irritation/interstitial: chronic cystitis and bladder catarrh (traditional).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP63', 'Minor', 'UTI uncomplicated: traditional mild urinary antiseptic and diuretic use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP52', 'Minor', 'Sore throat: inflammation of the upper respiratory tract and throat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H204', 'CP41', 'Minor', 'Cold/flu onset: cough associated with the common cold.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P01', 'Primary', 'Tincture or fluid extract; alcohol holds the resins (the standard internal form).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P05', 'Secondary', 'Infusion (tea) of the dried leaf and flowering tops.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P09', 'Secondary', 'Cough syrup for spasmodic and productive cough.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P07', 'Secondary', 'Salve or ointment for poison-oak dermatitis and skin complaints.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P10', 'Minor', 'Compress, lotion, or wash for poison-oak, wounds, and burns.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H204', 'P08', 'Minor', 'Poultice on inflamed skin, boils, and sores.');
