INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H204', 'TCM07', 'Primary', 'Yin Deficiency: a warm, drying, resinous herb worsens a dry cough.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "locator": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H204', 'TCM11', 'Secondary', 'Heat/Fire: its warmth is unsuited to a hot, dry Lung-heat pattern.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Grindelia (Grindelia robusta and Grindelia squarrosa).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "locator": "ESCOP Monographs, Grindeliae herba (Grindelia); German Commission E Monograph, Grindeliae herba (catarrh of the upper respiratory tract); British Herbal Pharmacopoeia, Grindelia; Mills and Bone, Principles and Practice of Phytotherapy; Brin", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI882', 'H204', 'pregnancy', 'Pregnancy', 'moderate', 'No adequate reproductive-safety data; modern monographs default to avoidance for insufficiently-studied botanicals, and grindelia is a documented renal irritant in larger doses. Not a proven emmenagogue or abortifacient.', 'Avoid internal use during pregnancy; there is no established safe dose.', 'AHPA Botanical Safety Handbook, 2nd ed.; ESCOP Grindeliae herba monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI883', 'H204', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation-safety data; transfer of the resinous diterpene acids into milk is uncharacterised.', 'Avoid internal use while breastfeeding; prefer better-studied respiratory herbs.', 'AHPA Botanical Safety Handbook, 2nd ed.; ESCOP Grindeliae herba.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI884', 'H204', 'condition', 'Kidney (renal) disease', 'moderate', 'Grindelic and related resin acids irritate the renal tubules in large or prolonged doses (the basis of its diuretic effect); this adds burden to compromised kidneys.', 'Avoid large or prolonged internal doses in kidney disease; keep to short, low-dose courses.', 'Brinker, Herb Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy; King''s American Dispensatory 1898 (renal irritation noted).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI885', 'H204', 'condition', 'Cardiac disease or marked hypotension', 'moderate', 'Large doses depress the heart and respiration and lower blood pressure, which is hazardous in cardiac disease or existing hypotension.', 'Avoid large doses; use only low, short-term doses with monitoring in cardiac patients.', 'Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI886', 'H204', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Large doses are hypotensive and cardiodepressant; additive lowering of blood pressure or heart rate is theoretically possible (extrapolated, limited data).', 'Monitor blood pressure and heart rate if combined; avoid large doses.', 'Brinker, Herb Contraindications and Drug Interactions (precautionary).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI887', 'H204', 'drug_interaction', 'Cardiac glycosides (digoxin) and other negative chronotropes', 'moderate', 'Grindelia''s dose-dependent cardiac and respiratory depression could theoretically add to negative chronotropic drug effects (theoretical, limited data).', 'Use cautiously and avoid large doses in patients on cardiac-glycoside or rate-lowering therapy.', 'Brinker, Herb Contraindications and Drug Interactions (precautionary).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI888', 'H204', 'other', 'Asteraceae (Compositae) allergy', 'moderate', 'As a daisy-family plant, grindelia can provoke allergic reactions and contact dermatitis in Compositae-sensitive individuals, including on the very skin its topical use is meant to treat.', 'Avoid in known Asteraceae allergy; patch-test before topical use in sensitive individuals.', 'AHPA Botanical Safety Handbook, 2nd ed.');
