INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS10', 'Primary', 'Excitation: quiets an over-excited, over-stimulated nervous system that cannot settle into sleep.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS18', 'Primary', 'Tension: relaxes nervous and muscular tension, tension headache, and guarding.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS12', 'Primary', 'Constriction: antispasmodic to cramping, constricted smooth and skeletal muscle.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS06', 'Minor', 'Acute inflammation/irritation of nerve tissue underlying neuralgic and rheumatic pain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS17', 'Primary', 'Cold: a cooling depressant chills an already cold constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS01', 'Primary', 'Deficiency: sedating and depressant, wrong for the depleted and debilitated.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS11', 'Secondary', 'Depression: a CNS depressant worsens low, torpid, hypofunctional, melancholic states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H205', 'TS04', 'Minor', 'Exhaustion: further lowers a spent, exhausted vitality.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H205', 'SY01', 'Primary', 'Nervous: sedative, hypnotic, anodyne for pain-driven insomnia, neuralgia, anxiety.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H205', 'SY04', 'Secondary', 'Musculoskeletal: antispasmodic and anodyne for cramp, spasm, myalgia, rheumatism.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H205', 'SY03', 'Secondary', 'Reproductive: antispasmodic for spasmodic dysmenorrhea and pelvic neuroses.');
