INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H205', 'TCM07', 'Minor', 'Yin/Blood deficiency without true Heat-excess: not a nourishing herb.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Piscidia (Jamaica Dogwood, Piscidia erythrina / Piscidia piscipula).", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Piscidia (Jamaica Dogwood, Piscidia erythrina / Piscidia piscipula).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Piscidia; Restorative Medicine (AARM) clinical monograph, Jamaican Dogwood (Piscidia erythrina); Herbal Reality practitioner monograph, Jamaican Dogwood; The Naturo", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Piscidia; Restorative Medicine (AARM) clinical monograph, Jamaican Dogwood (Piscidia erythrina); Herbal Reality practitioner monograph, Jamaican Dogwood; The Naturo", "source_id": "S22", "author": "Ellingwood \u2014 American Materia Medica", "year": "1919", "url": "https://www.henriettes-herb.com/eclectic/ellingwood/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI889', 'H205', 'pregnancy', 'Pregnancy', 'absolute', 'Uterine depressant/uterotropic action that can affect the uterus, plus rotenoid (rotenone) content that is developmentally toxic in animal studies, and potent CNS/cardiac depression. No human pregnancy data.', 'Do not use in pregnancy in any form or dose.', 'RxList/WebMD (Jamaican dogwood, LIKELY UNSAFE in pregnancy, affects the uterus); Herbal Reality (uterine depressant, avoid); Restorative Medicine (AARM) monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI890', 'H205', 'breastfeeding', 'Breastfeeding', 'absolute', 'Contains toxic rotenoid constituents that may pass to the nursing infant, compounded by sedative/depressant action; no lactation safety data.', 'Avoid while breastfeeding; choose a better-documented, non-toxic alternative.', 'RxList/WebMD (LIKELY UNSAFE while breast-feeding, poisons it contains); Herbal Reality; Restorative Medicine monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI891', 'H205', 'pediatric', 'Infants and young children', 'absolute', 'Narrow-margin CNS and cardiac depressant; children have heightened neuromuscular sensitivity to it.', 'Do not give to infants or young children; older children/adolescents only under qualified supervision at low, short-course doses.', 'RxList/WebMD (children should not take it); Herbal Reality (avoid in children and the elderly).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI892', 'H205', 'drug_interaction', 'Sedatives and CNS depressants (benzodiazepines, barbiturates, Z-drugs, opioids/strong analgesics, alcohol)', 'moderate', 'Jamaican dogwood causes drowsiness and can add to sedative and CNS/respiratory depression.', 'Avoid combining, or use only under supervision with dose reduction; warn about excessive sedation.', 'RxList/WebMD (examples: clonazepam, lorazepam, phenobarbital, zolpidem); Herbal Reality (potentiates CNS depressants, strong analgesics, sedatives, tranquilisers).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI893', 'H205', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Mild hypotensive action may add to blood-pressure-lowering medication.', 'Monitor blood pressure; use cautiously with antihypertensives.', 'Herbal Reality; Restorative Medicine monograph (hypotensive action).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI894', 'H205', 'drug_interaction', 'Cardiac depressants and rate-slowing drugs (beta-blockers, calcium-channel blockers, digoxin)', 'moderate', 'The herb slows and, in excess, weakens the heart; theoretical additive bradycardia and cardiac depression.', 'Avoid or use only under supervision in anyone on heart-rate-slowing or cardiac-depressant drugs.', 'Herbal Reality (avoid in bradycardia and cardiac insufficiency); King''s American Dispensatory (slows and weakens heart action).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI895', 'H205', 'condition', 'Bradycardia, cardiac insufficiency, and hypotension', 'moderate', 'Pulse-slowing, blood-pressure-lowering, cardiac-depressant action deepens an already slow or weak circulation.', 'Avoid in bradycardia, heart failure/insufficiency, and low blood pressure.', 'Herbal Reality (Jamaican Dogwood safety); King''s American Dispensatory.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI896', 'H205', 'condition', 'Significant liver or kidney disease', 'moderate', 'Impaired clearance of a narrow-margin, toxic (rotenoid-containing) herb increases the risk of accumulation and adverse effects.', 'Avoid in significant hepatic or renal impairment.', 'Herbal Reality (avoid in liver/kidney disease).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI897', 'H205', 'other', 'Surgery / general anesthesia', 'moderate', 'Additive CNS depression with anesthetic agents.', 'Discontinue at least 7 to 10 days (2 weeks) before scheduled surgery.', 'RxList/WebMD; Herbal Reality (stop before surgery).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI898', 'H205', 'other', 'Overdose / prolonged high-dose use (rotenone neurotoxicity)', 'moderate', 'Even small doses have produced nausea, vomiting, and headache (convulsions reported at a half-drachm); isolated rotenone is a dopaminergic neurotoxin (mitochondrial complex-I inhibitor) at large or repeated doses.', 'Do not exceed the stated dose range (about 400 mg powder/day or professional-society tincture limits); use short-term only; practitioner-administered.', 'King''s American Dispensatory (1898); Restorative Medicine monograph (rotenone dopaminergic toxicity; caution above ~400 mg/day).');
