INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A09', 'Secondary', 'Anti-inflammatory: cools hot, inflamed skin and joints.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A50', 'Secondary', 'Styptic/hemostatic: cools blood to stop heat-driven bleeding (charred form).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A19', 'Secondary', 'Emmenagogue: moves stagnant uterine blood; promotes suppressed menses.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A15', 'Secondary', 'Astringent: the kashaya taste; tones and stanches.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A13', 'Secondary', 'Hepatoprotective: liver-protective, used for jaundice.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A25', 'Minor', 'Antioxidant: anthraquinone and phenolic free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A28', 'Minor', 'Antimicrobial: broad in vitro antimicrobial activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A08', 'Minor', 'Diuretic: promotes urine; gravel, stones, and dropsy.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A24', 'Minor', 'Vulnerary: traditional wound and ulcer healing.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H206', 'A49', 'Minor', 'Febrifuge: jvarahara, antipyretic in classical use.');
