INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP67', 'Secondary', 'Eczema and atopic dermatitis (blood-heat type).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP68', 'Secondary', 'Psoriasis (chronic, congested, blood-heat).');
