INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP14', 'Minor', 'Hot, rheumatic, inflamed joints.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP43', 'Minor', 'Autoimmune/inflammatory conditions (traditional depurative use).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP09', 'Minor', 'Chronic skin and glandular infection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H206', 'CP70', 'Minor', 'Boils and abscesses (heat-toxin eruptions).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H206', 'P04', 'Primary', 'Decoction of the dried root (Qian Cao; Ayurvedic kwatha).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H206', 'P03', 'Primary', 'Root powder/churna, the classic Ayurvedic form, with honey, ghee, or milk.');
