INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H206', 'TCM02', 'Secondary', 'Qi deficiency without stasis: a moving, draining herb depletes further.', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Manjishtha; and Charaka Samhita (Sutrasthana 4), which places Manjishtha among the Varnya (complexion-promoting), Jvarahara (antipyretic), and Vishaghna (antitoxic) maha", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Manjishtha; and Charaka Samhita (Sutrasthana 4), which places Manjishtha among the Varnya (complexion-promoting), Jvarahara (antipyretic), and Vishaghna (antitoxic) maha", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qian Cao / Radix Rubiae; Frawley and Lad, The Yoga of Herbs, Manjistha; Williamson, Major Herbs of Ayurveda; Verma et al., ''A comprehensive review of Rubia cordif", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qian Cao / Radix Rubiae; Frawley and Lad, The Yoga of Herbs, Manjistha; Williamson, Major Herbs of Ayurveda; Verma et al., ''A comprehensive review of Rubia cordif", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H206', 'TCM13', 'Minor', 'Wind-Cold: a cold herb is unsuited to a cold exterior pattern.', '{"title": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Manjishtha; and Charaka Samhita (Sutrasthana 4), which places Manjishtha among the Varnya (complexion-promoting), Jvarahara (antipyretic), and Vishaghna (antitoxic) maha", "locator": "Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Manjishtha; and Charaka Samhita (Sutrasthana 4), which places Manjishtha among the Varnya (complexion-promoting), Jvarahara (antipyretic), and Vishaghna (antitoxic) maha", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qian Cao / Radix Rubiae; Frawley and Lad, The Yoga of Herbs, Manjistha; Williamson, Major Herbs of Ayurveda; Verma et al., ''A comprehensive review of Rubia cordif", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qian Cao / Radix Rubiae; Frawley and Lad, The Yoga of Herbs, Manjistha; Williamson, Major Herbs of Ayurveda; Verma et al., ''A comprehensive review of Rubia cordif", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI899', 'H206', 'pregnancy', 'Pregnancy', 'absolute', 'Traditional emmenagogue and uterine blood-mover (theoretically abortifacient); the root also contains genotoxic, animal-carcinogenic anthraquinones (lucidin, rubiadin) that would expose the fetus.', 'Do not use during pregnancy in any form.', 'Frawley and Lad, The Yoga of Herbs; Bensky, Clavey and Stoger, Materia Medica (Qian Cao contraindicated in pregnancy); IARC Monographs vol. 82 (Rubia anthraquinones).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI900', 'H206', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation-safety data; the alizarin-type pigments pass into milk (madder colours the milk of animals fed on it), and the root carries genotoxic anthraquinones.', 'Avoid while breastfeeding; prefer better-characterised alternatives.', 'Comprehensive review, Verma et al. 2022 (clinical safety data lacking); AHPA Botanical Safety Handbook approach for genotoxic-anthraquinone botanicals.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI901', 'H206', 'other', 'Prolonged or high-dose internal use', 'moderate', 'Root anthraquinones lucidin and rubiadin are genotoxic and carcinogenic in animals (renal and hepatic tumours, DNA adducts); the sister species Rubia tinctorum was banned as a medicine and food colour in Germany/the EU on this basis.', 'Limit to short, intermittent, defined courses; favour water-based preparations; avoid chronic daily long-term internal use.', 'IARC Monographs vol. 82 (2002); Westendorf et al. on lucidin genotoxicity; German/EU madder-root ban.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI902', 'H206', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin)', 'moderate', 'Blood-invigorating action may add to antithrombotic/antiplatelet effect, increasing bleeding risk (theoretical, extrapolated from the herb''s action).', 'Avoid concurrent therapeutic use without professional supervision and coagulation monitoring.', 'Brinker, Herbal Contraindications and Drug Interactions; Bensky, Clavey and Stoger, Materia Medica (blood-mover cautions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI903', 'H206', 'condition', 'Bleeding disorders', 'moderate', 'A blood-moving herb may aggravate a bleeding tendency that is not driven by stasis.', 'Avoid in bleeding diatheses without a clear blood-stasis indication.', 'Bensky, Clavey and Stoger, Materia Medica (Qian Cao).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI904', 'H206', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Mildly hypotensive; may add to blood-pressure-lowering therapy.', 'Monitor blood pressure if combined; watch for hypotension.', 'Pharmacological reviews of Rubia cordifolia (hypotensive activity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI905', 'H206', 'condition', 'Spleen/Stomach deficiency-cold (TCM)', 'moderate', 'Bitter-cold Qian Cao quenches an already weak digestive fire, worsening poor appetite and loose stools.', 'Avoid in cold-deficient digestion, or combine with warming, protective herbs and limit duration.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI906', 'H206', 'condition', 'Chronic kidney disease or history of urinary stones', 'moderate', 'Anthraquinone genotoxicity is documented in the kidney; prolonged use may add renal burden.', 'Avoid prolonged use; use only short-term under supervision in renal patients.', 'IARC Monographs vol. 82 (2002); comprehensive review, Verma et al. 2022.');
