INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H207', 'T04');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H207', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS05', 'Primary', 'Excess heat: clears fever-heat and the hot, plethoric heat of a high blood pressure.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS18', 'Primary', 'Tension: relaxes vascular tension, the hallmark antihypertensive action.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS12', 'Secondary', 'Constriction: vasodilates and eases vascular constriction.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS10', 'Secondary', 'Excitation: settles the hot, restless overactivity of febrile and metabolic states.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS08', 'Secondary', 'Stagnation: metabolic stagnation of high sugar and high fats in the thickened, hot system.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS16', 'Secondary', 'Excess conditions: a cooling, draining herb for the full, hot, tense excess picture.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS15', 'Minor', 'Acute infection: feverish viral and bacterial illness (broad antimicrobial/antiviral leaf).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS25', 'Minor', 'Ulceration: hot, weeping sores and skin lesions (leaf, topical).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS17', 'Primary', 'Cold: a cooling herb is wrong for the cold, weak constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS01', 'Primary', 'Deficiency: a draining, cooling, drying bitter depletes the already deficient.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS03', 'Secondary', 'Dryness: the astringent leaf worsens frank dryness (the oil is the moist alternative).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H207', 'TS04', 'Minor', 'Exhaustion: further lowering and draining is wrong for the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY06', 'Primary', 'Cardiovascular: blood pressure, blood lipids, and endothelial function.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY05', 'Primary', 'Immune: febrifuge, broad antimicrobial and antiviral action.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY02', 'Secondary', 'Endocrine/metabolic: blood-sugar regulation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY08', 'Secondary', 'Digestive: the bitter leaf; the fixed oil as demulcent laxative and biliary lubricant.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY10', 'Secondary', 'Skin: the oil topically as an emollient; the leaf on hot, weeping sores.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY07', 'Minor', 'Respiratory: feverish respiratory infection; the oil for the chest.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY09', 'Minor', 'Urinary: mild traditional diuresis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H207', 'SY12', 'Minor', 'Hepatic: lipid and metabolic support; the oil as biliary lubricant.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A49', 'Primary', 'Febrifuge: leaves and bark ''febrifugal'' (Grieve); the Levantine fever decoction.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A37', 'Primary', 'Hypotensive: oleuropein-driven vasodilation; the leaf''s flagship modern action, trialed against captopril.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A25', 'Primary', 'Antioxidant: oleuropein and hydroxytyrosol are potent polyphenol antioxidants.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A36', 'Secondary', 'Hypoglycemic: lowers blood glucose (insulin release plus peripheral uptake).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A28', 'Secondary', 'Antimicrobial: broad antibacterial reach, including MRSA.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A30', 'Secondary', 'Antiviral: active against HSV, influenza, and other viruses (elenolate).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A15', 'Secondary', 'Astringent: the leaf is astringent (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A09', 'Secondary', 'Anti-inflammatory: oleocanthal and oleuropein anti-inflammatory action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A34', 'Secondary', 'Emollient: the fixed oil softens and soothes the skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A11', 'Secondary', 'Demulcent: the fixed oil is a bland, soothing demulcent (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A38', 'Minor', 'Laxative: the fixed oil is a gentle laxative, 1 to 2 fl oz (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H207', 'A08', 'Minor', 'Diuretic: mild traditional diuretic action.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H207', 'CP44', 'Primary', 'Functional hypertension: the leaf''s flagship modern use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H207', 'CP76', 'Primary', 'Fever management: the traditional febrifuge decoction.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H207', 'CP27', 'Secondary', 'Blood-sugar dysregulation and metabolic syndrome.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H207', 'CP41', 'Secondary', 'Cold/flu onset: febrifuge and antiviral leaf.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H207', 'CP09', 'Secondary', 'Chronic and recurrent infection (broad antimicrobial/antiviral).');
