INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI907', 'H207', 'drug_interaction', 'Antihypertensive drugs (beta-blockers, ACE inhibitors, ARBs, calcium-channel blockers, diuretics)', 'moderate', 'Olive leaf lowers blood pressure through oleuropein-mediated vasodilation (randomized human data, one trial comparable to captopril), which is additive to antihypertensive medication and can cause excessive hypotension. Preliminary data also suggest P-glycoprotein inhibition could raise absorbed drug levels.', 'Do not combine with blood-pressure medication without supervision; monitor blood pressure and adjust the drug dose as needed. Watch for dizziness and fainting.', 'Memorial Sloan Kettering Cancer Center, Integrative Medicine, Olive Leaf; drugs.com Natural Products monograph; Susalit et al., Phytomedicine 2011 (olive leaf vs captopril).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI908', 'H207', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Olive leaf lowers blood glucose by potentiating glucose-stimulated insulin release and peripheral glucose uptake, which is additive to hypoglycemic medication and can risk hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined; watch for signs of low blood sugar.', 'Memorial Sloan Kettering Cancer Center, Integrative Medicine, Olive Leaf; drugs.com Natural Products monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI909', 'H207', 'pregnancy', 'Concentrated olive leaf extract in pregnancy', 'moderate', 'No reliable human safety data; oleuropein reported to stimulate uterine contraction in animal studies; the leaf''s blood-pressure- and blood-sugar-lowering actions are undesirable in pregnancy. Culinary olive fruit and oil are foods and are safe in dietary amounts.', 'Avoid concentrated olive leaf extract in pregnancy; do not exceed amounts found in food. Culinary olive oil is fine.', 'Royal Women''s Hospital, Herbal Medicines in Pregnancy and Breastfeeding (2018); drugs.com Natural Products monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI910', 'H207', 'breastfeeding', 'Concentrated olive leaf extract while breastfeeding', 'moderate', 'No safety data during lactation; transfer of oleuropein and of the blood-pressure- and blood-sugar-lowering activity into milk is unknown and those effects are unwanted in a nursing infant. Culinary olive oil is a food and is safe.', 'Avoid concentrated olive leaf extract while nursing; keep to dietary olive oil and better-studied alternatives.', 'Royal Women''s Hospital, Herbal Medicines in Pregnancy and Breastfeeding (2018).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI911', 'H207', 'condition', 'Hypotension / tendency to faint', 'moderate', 'The leaf further lowers blood pressure and can worsen existing hypotension or orthostatic symptoms.', 'Avoid concentrated olive leaf extract in low blood pressure or a fainting tendency; monitor if used.', 'Memorial Sloan Kettering Cancer Center, Integrative Medicine, Olive Leaf (antihypertensive mechanism).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI912', 'H207', 'other', 'Scheduled surgery', 'moderate', 'The leaf''s blood-pressure- and blood-sugar-lowering effects can complicate perioperative hemodynamic and glucose control.', 'Discontinue concentrated olive leaf extract about two weeks before scheduled surgery.', 'General herb-surgery precaution; drugs.com Natural Products monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI913', 'H207', 'other', 'Olive / olive-pollen allergy', 'low', 'Olive pollen is a well-recognized respiratory allergen; allergic individuals may react, though the leaf and oil rarely cause allergy.', 'Avoid in known olive or olive-pollen allergy; discontinue if allergic symptoms occur.', 'Memorial Sloan Kettering Cancer Center, Integrative Medicine, Olive Leaf (adverse reactions).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H207', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Grieve, M., A Modern Herbal (1931), Olive (Olea europaea): the leaves ''astringent and antiseptic'' with ''valuable febrifugal qualities,'' the Levantine decoction for ''obstinate fevers,'' and the fixed oil as ''a nourishing demulcent and laxativ", "locator": "Grieve, M., A Modern Herbal (1931), Olive (Olea europaea): the leaves ''astringent and antiseptic'' with ''valuable febrifugal qualities,'' the Levantine decoction for ''obstinate fevers,'' and the fixed oil as ''a nourishing demulcent and laxativ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Dioscorides, De Materia Medica (Book I), on the olive and the astringent, cooling decoction of its leaves; Memorial Sloan Kettering Cancer Center, Integrative Medicine herb monograph, Olive Leaf (mechanism, purported uses, herb-drug interac", "locator": "Dioscorides, De Materia Medica (Book I), on the olive and the astringent, cooling decoction of its leaves; Memorial Sloan Kettering Cancer Center, Integrative Medicine herb monograph, Olive Leaf (mechanism, purported uses, herb-drug interac", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, true);
