INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H208', 'TCM11', 'Minor', 'Heat/Fire: cools mild Damp-Heat irritation of the lower burner (irritable bladder).', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H208', 'TCM07', 'Primary', 'Yin deficiency: a drying astringent injures fluids and worsens empty-heat dryness.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H208', 'TCM01', 'Secondary', 'Kidney Yang deficiency: a cool, contracting herb is unsuited to yang-deficient cold.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H208', 'TCM06', 'Minor', 'Blood deficiency: drying astringency deepens dryness in the blood-deficient.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Mitchella (Partridge Berry / Squaw Vine), which records it as parturient, diuretic, astringent, and tonic and as a remedy long used by Native American women to prepare for childbirth. A", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Chestnut School of Herbal Medicine, Partridgeberry materia medica (energetics, dosage, conservation); Grieve, A Mode", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI914', 'H208', 'pregnancy', 'Pregnancy (first and second trimesters; self-prescription at any stage)', 'absolute', 'A recognized uterine tonic and emmenagogue whose signature use is as a partus preparator acting on the pregnant uterus; early-pregnancy use is advised against and is associated with a theoretical miscarriage risk. Controlled human data are lacking.', 'Do not use in early pregnancy or self-prescribe. Reserve late-pregnancy partus-preparator use (final weeks) to qualified practitioner supervision only.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; WebMD/RxList squawvine consumer monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI915', 'H208', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation-safety data; the astringent tannins could theoretically reduce milk flow, and infant exposure is uncharacterized.', 'Use only briefly under qualified guidance, or prefer better-studied alternatives.', 'AHPA Botanical Safety Handbook, 2nd ed. (no lactation data); Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI916', 'H208', 'drug_interaction', 'Lithium', 'moderate', 'Mild diuretic action can reduce renal lithium clearance and raise serum lithium toward toxicity.', 'Avoid concurrent use without serum-lithium monitoring and physician oversight.', 'Brinker, Herbal Contraindications and Drug Interactions (diuretic herbs); WebMD/RxList squawvine interaction monograph (lithium).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI917', 'H208', 'drug_interaction', 'Diuretic and antihypertensive drugs; oral iron and mineral supplements', 'low', 'Additive diuretic/blood-pressure effects are theoretically possible; astringent tannins can bind and reduce absorption of iron, minerals, and some alkaloidal drugs if co-administered.', 'Monitor if combined with diuretics/antihypertensives; separate from iron, mineral supplements, and medications by about two hours.', 'Brinker, Herbal Contraindications and Drug Interactions (diuretic and tannin-containing herbs).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI918', 'H208', 'condition', 'Dry, atrophic, or fluid-deficient constitutions', 'moderate', 'A cool, drying astringent worsens parched, thin, atrophic tissue (atrophic vaginitis, dry constipation, dry cough).', 'Avoid, or pair with a demulcent and limit duration, in dry, depleted constitutions.', 'Chestnut School of Herbal Medicine, Partridgeberry materia medica (drying caution); Mills and Bone, The Essential Guide to Herbal Safety.');
