INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI919', 'H209', 'pregnancy', 'Pregnancy', 'absolute', 'Arbutin is metabolized to hydroquinone, a compound with genotoxic potential; pipsissewa shares this mechanism with uva-ursi, which authoritative references contraindicate in pregnancy, and this class of astringent-diuretic is traditionally cautioned to act on the gravid uterus. No adequate human safety data exist for pipsissewa.', 'Do not use during pregnancy in any form or dose.', 'AHPA Botanical Safety Handbook (2nd ed.) and EMA/ESCOP monograph, Uvae ursi folium (arbutin/hydroquinone herbs not for use in pregnancy); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI920', 'H209', 'breastfeeding', 'Breastfeeding', 'moderate', 'Hydroquinone and its conjugates are excreted and could reach the nursing infant; hydroquinone''s genotoxic potential makes infant exposure undesirable. No reliable lactation data for pipsissewa.', 'Avoid while breastfeeding; prefer gentler urinary demulcents such as marshmallow or cornsilk.', 'AHPA Botanical Safety Handbook (2nd ed.) and EMA/ESCOP uva-ursi precedent; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI921', 'H209', 'pediatric', 'Children under 12 years', 'absolute', 'Arbutin/hydroquinone-containing urinary herbs are contraindicated under age 12 because of hydroquinone exposure; astringent tannins also upset a child''s stomach.', 'Do not give to children under 12. Adolescents and adults only, for uncomplicated cases.', 'EMA/ESCOP monograph, Uvae ursi folium (not recommended under 12); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI922', 'H209', 'condition', 'Liver disease and prolonged/high-dose use', 'moderate', 'Arbutin yields hydroquinone, which is hepatically handled and, in large or prolonged amounts, potentially hepatotoxic and genotoxic.', 'Use short, defined courses at ordinary doses; avoid continuous or high-dose use and avoid in significant liver disease.', 'ESCOP monograph, Uvae ursi folium; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI923', 'H209', 'condition', 'Acute, severe, or obstructive kidney disease', 'moderate', 'As a stimulating, irritant diuretic it is unsuited to acute, high, febrile, or obstructive renal disease, which needs medical management.', 'Do not self-treat acute or obstructive kidney conditions; refer for medical care.', 'King''s American Dispensatory (Felter and Lloyd, 1898); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI924', 'H209', 'drug_interaction', 'Urinary acidifiers and cranberry (ascorbic acid, ammonium chloride, acidic diet)', 'moderate', 'The arbutin-derived antibacterial action is favored by alkaline urine (pH > 7); agents or foods that acidify the urine may reduce the urinary-antiseptic effect.', 'Avoid strong urinary acidifiers when using pipsissewa for a urinary antiseptic effect; some practitioners alkalinize the urine cautiously.', 'EMA/ESCOP monograph, Uvae ursi folium (shared arbutin/hydroquinone mechanism).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI925', 'H209', 'drug_interaction', 'Orally administered drugs, alkaloids, and iron', 'moderate', 'Leaf tannins can bind and reduce the absorption of drugs, alkaloids, and iron taken concurrently.', 'Separate pipsissewa from oral medicines and iron supplements by at least 2 hours; take with food.', 'Brinker, Herbal Contraindications and Drug Interactions; Yarnell, Chimaphila umbellata clinical monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI926', 'H209', 'drug_interaction', 'Prescription diuretics and lithium', 'moderate', 'Additive diuretic effect may increase fluid and electrolyte loss, and altered fluid balance could affect lithium clearance.', 'Monitor fluid, electrolytes, and lithium levels if combined; use under supervision.', 'Mills and Bone, Principles and Practice of Phytotherapy (general diuretic-herb interaction principle); Brinker.');
