INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H210', 'TCM10', 'Primary', 'Dampness/Phlegm: warms and dries cold-damp accumulation of the middle burner; expels parasites.', '{"title": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "locator": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "locator": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H210', 'TCM07', 'Primary', 'Yin deficiency: a warm, drying herb consumes the fluids.', '{"title": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "locator": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "locator": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H210', 'TCM11', 'Primary', 'Heat/Fire: aggravates heat, Stomach fire, and hyperacidity.', '{"title": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "locator": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "locator": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H210', 'TCM06', 'Secondary', 'Blood deficiency with dryness: the drying quality worsens it.', '{"title": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "locator": "Charaka Samhita (Sutrasthana 4), which names Vidanga the chief of the Krimighna (anthelmintic) mahakashaya; and Bhavaprakasha Nighantu (Bhavamishra, 16th century), Haritakyadi Varga, Vidanga. Standardised in the Ayurvedic Pharmacopoeia of I", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "locator": "Grieve, A Modern Herbal (1931), Embelia; Frawley and Lad, The Yoga of Herbs, Vidanga; Williamson, Major Herbs of Ayurveda, Embelia ribes; MDPI review, ''Reviewing the Traditional/Modern Uses, Phytochemistry, Essential Oils/Extracts and Pharm", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI927', 'H210', 'pregnancy', 'Pregnancy', 'absolute', 'The fruit constituent embelin is a documented anti-implantation and antifertility agent, producing dose-dependent anti-implantation with antiestrogenic and progestational effects in animal studies; an aqueous berry extract has been trialled as a human oral contraceptive. Interference with implantation and early pregnancy is directly hazardous to a pregnancy.', 'Do not use during pregnancy in any form.', 'Antifertility properties of Embelia ribes / embelin (Indian J Exp Biol; PubMed 7216303, 7439948); Krishnaswamy and Purushothaman, antifertility investigations on embelin (Planta Medica); anti-implantation mechanism of embelin in rats (Phytotherapy Research 1992).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI928', 'H210', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation-safety data exist, and embelin has demonstrated hormonal (antiestrogenic, progestational) and reproductive activity; excretion into milk and effect on the infant are uncharacterised.', 'Avoid while breastfeeding; prefer better-characterised alternatives.', 'No NCCIH or AHPA lactation monograph located; precaution extrapolated from documented embelin reproductive pharmacology (PubMed 7216303).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI929', 'H210', 'other', 'Attempting conception (either partner) or undergoing fertility treatment', 'moderate', 'Embelin causes reversible antifertility effects in both sexes: anti-implantation and antiestrogenic activity in females and antispermatogenic, sperm-immobilising effects in males (reduced motile sperm count, decapitation of sperm heads, impaired glycolytic enzymes), reversible after withdrawal.', 'Avoid in anyone actively trying to conceive; discontinue well before planned conception and counsel that fertility may be transiently reduced.', 'Antispermatogenic effect of embelin on male albino rats (Contraception 1989; PubMed 2714091); Antifertility Effects of Embelin in Male Rats (Andrologia 1986); female antifertility studies (PubMed 7216303, 7439948).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI930', 'H210', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin, and other hypoglycemics)', 'moderate', 'Embelin is well-documented as antihyperglycemic, so co-administration may have an additive blood-sugar-lowering effect and risk hypoglycemia.', 'Monitor blood glucose closely if combined; anticipate the possible need to adjust antidiabetic dosing under medical supervision.', 'Antidiabetic activity of Embelia ribes, embelin and derivatives: systematic review and meta-analysis (Pharmacological Research 2017); Brinker, Herbal Contraindications and Drug Interactions (framework).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI931', 'H210', 'condition', 'Hot or inflammatory upper-GI conditions (gastritis, hyperacidity, active peptic ulcer) and Pitta-excess or Yin-deficient heat states', 'moderate', 'A warm, sharp, pungent, drying herb aggravates heat, acidity, and mucosal irritation and further consumes the fluids in dry, heat-type constitutions.', 'Avoid in hot, dry, inflamed presentations; if used at all, combine with cooling, demulcent, protective herbs and keep doses low and courses short.', 'Ayurvedic energetics (ushna virya, katu, tikshna; Charaka Samhita; Ayurvedic Pharmacopoeia of India, Vidanga); Frawley and Lad, The Yoga of Herbs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI932', 'H210', 'other', 'High doses or prolonged continuous internal use', 'low', 'At ordinary traditional doses the dried fruit is well tolerated, but large doses can irritate the gut and cause nausea or loose stools; long-term reproductive effects of embelin are undesirable with sustained use.', 'Use short, targeted courses at traditional doses rather than prolonged daily intake.', 'Traditional dosing (Ayurvedic Pharmacopoeia of India, Vidanga); embelin reproductive pharmacology (PubMed 2714091, 7216303).');
