INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI933', 'H211', 'drug_interaction', 'Digoxin and other cardiac glycosides (Lanoxin, digitoxin)', 'absolute', 'Wahoo''s euonymin/digitaloid glycosides are digitalis-like; combined use is additive and can precipitate cardiac-glycoside toxicity (bradycardia, arrhythmia, heart block).', 'Do not combine. Wahoo is contraindicated in anyone taking a cardiac glycoside.', 'WebMD/RxList Wahoo monograph (Natural Medicines Comprehensive Database)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI934', 'H211', 'drug_interaction', 'Potassium-depleting diuretics (loop, thiazide) and other hypokalemia-inducing agents (corticosteroids, chronic licorice)', 'absolute', 'Hypokalemia sensitizes the myocardium to cardiac glycosides, magnifying wahoo''s cardiotoxic potential.', 'Avoid concurrent use; if the herb is used at all, potassium status must be monitored by a clinician.', 'WebMD/RxList Wahoo monograph (Natural Medicines)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI935', 'H211', 'drug_interaction', 'Stimulant laxatives', 'moderate', 'Additive catharsis speeds the bowel excessively, causing dehydration and electrolyte (potassium) loss, which in turn potentiates glycoside toxicity.', 'Do not combine with other stimulant laxatives.', 'WebMD/RxList Wahoo monograph (Natural Medicines)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI936', 'H211', 'pregnancy', 'Pregnancy', 'absolute', 'Drastic hydragogue cathartic plus cardioactive glycosides; traditional pelvic/uterine-stimulant reputation. Rated UNSAFE.', 'Contraindicated. Do not use in any trimester.', 'WebMD/RxList Wahoo monograph (Natural Medicines); general herbal-safety consensus');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI937', 'H211', 'breastfeeding', 'Breastfeeding', 'absolute', 'Cardiac-glycoside and cathartic toxicity with no reliable milk-transfer safety data.', 'Contraindicated. Avoid while nursing.', 'WebMD/RxList Wahoo monograph (precautionary)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI938', 'H211', 'other', 'Children', 'absolute', 'Toxic plant with a narrow margin; cardiac-glycoside and cathartic poisoning risk is high and children are especially vulnerable.', 'Contraindicated in children.', 'WebMD/RxList Wahoo monograph (Natural Medicines)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI939', 'H211', 'condition', 'Cardiac disease, arrhythmia, or hypokalemia', 'absolute', 'Endogenous cardioactive glycoside content is dangerous to a compromised or electrolyte-imbalanced heart.', 'Contraindicated. Do not use in known heart disease, arrhythmia, or low potassium.', 'WebMD/RxList Wahoo monograph; Mills & Bone (cardioactive-herb caution)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI940', 'H211', 'condition', 'Acute gastroenteritis, inflammatory bowel disease, diarrhea, or intestinal obstruction', 'moderate', 'A drastic gut-irritant cathartic aggravates inflamed or obstructed bowel and drives fluid/electrolyte loss.', 'Avoid in active bowel inflammation, diarrhea, IBS/IBD, or suspected obstruction.', 'WebMD/RxList Wahoo monograph (Natural Medicines)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H211', 'EP01', 'neutral', 1, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Euonymus'' (henriettes-herb.com). Verified: classes wahoo root bark as tonic, laxative, alterative, diuretic, and expectorant; a hepatic stimulant that ''stimulates the biliary flow'' for h", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Euonymus'' (henriettes-herb.com). Verified: classes wahoo root bark as tonic, laxative, alterative, diuretic, and expectorant; a hepatic stimulant that ''stimulates the biliary flow'' for h", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), ''Wahoo / Spindle Tree''; Bliss, C.A. (1957), ''Cardiac glycosides of Euonymus atropurpurea Jacq. I: Detection, separation, and isolation,'' J. Am. Pharm. Assoc. 46(1) (isolation of digitaloid glycosides); WebMD/", "locator": "Grieve, A Modern Herbal (1931), ''Wahoo / Spindle Tree''; Bliss, C.A. (1957), ''Cardiac glycosides of Euonymus atropurpurea Jacq. I: Detection, separation, and isolation,'' J. Am. Pharm. Assoc. 46(1) (isolation of digitaloid glycosides); WebMD/", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
