INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI941', 'H212', 'pregnancy', 'Pregnancy', 'absolute', 'Documented oxytocic/uterotonic activity together with anti-implantation, anti-progestational, and anti-estrogenic effects in animal and in vitro models; may threaten implantation and pregnancy maintenance.', 'Do not use during pregnancy.', 'Saraca asoca scoping review (J. Ethnopharmacol., 2022); ethnobotanical/pharmacological reviews of S. asoca bark. Not listed by NCCIH or the AHPA Botanical Safety Handbook.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI942', 'H212', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation safety or milk-excretion data; not covered by NCCIH or AHPA.', 'Avoid while breastfeeding unless supervised by a qualified practitioner.', 'Absence of data in NCCIH Herbs at a Glance and AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI943', 'H212', 'pediatric', 'Children', 'moderate', 'Traditionally an adult women''s remedy; no pediatric safety or dosing established.', 'Avoid in children.', 'Absence of pediatric data in modern references (NCCIH/AHPA).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI944', 'H212', 'drug_interaction', 'Antidiabetic / hypoglycemic agents', 'moderate', 'Documented hypoglycemic activity may add to glucose-lowering drugs.', 'Monitor blood glucose; watch for hypoglycemia if combined.', 'Pharmacological reviews of S. asoca reporting hypoglycemic/antihyperglycemic activity (2021-2022).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI945', 'H212', 'drug_interaction', 'Antihypertensive and cardiac medications', 'low', 'Reported cardiotonic/hypotensive activity may be additive.', 'Monitor blood pressure and cardiac status when combined.', 'S. asoca pharmacology reviews.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI946', 'H212', 'drug_interaction', 'Estrogen therapy, hormonal contraceptives, fertility treatment', 'moderate', 'Anti-estrogenic, anti-implantation, and anti-progestational activity in animal models may oppose hormonal or fertility therapy.', 'Avoid combining with hormone-dependent fertility treatment; discuss with the prescriber.', 'S. asoca reproductive-pharmacology reviews (anti-implantation/anti-estrogenic studies).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI947', 'H212', 'condition', 'Amenorrhea / scanty or suppressed menses', 'moderate', 'Astringent, cold, drying action can further suppress an already scanty flow.', 'Avoid in amenorrhea and suppressed menstruation.', 'The Ayurvedic Pharmacopoeia of India and Ayurvedic dravyaguna sources.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI948', 'H212', 'condition', 'Undiagnosed or postmenopausal abnormal uterine bleeding', 'moderate', 'Self-treating bleeding can mask fibroids, polyps, or endometrial malignancy.', 'Obtain a diagnosis before use; refer all postmenopausal bleeding.', 'Standard clinical red-flag guidance; The Ayurvedic Pharmacopoeia of India indications.');
