INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H213', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, M. A Modern Herbal (1931), Bistort (Polygonum bistorta). Public-domain botanical monograph: the root is powerfully astringent, demulcent, diuretic, febrifuge, laxative, and strongly styptic, containing tannin to about 21 percent wit", "locator": "Grieve, M. A Modern Herbal (1931), Bistort (Polygonum bistorta). Public-domain botanical monograph: the root is powerfully astringent, demulcent, diuretic, febrifuge, laxative, and strongly styptic, containing tannin to about 21 percent wit", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "The Dispensatory of the United States of America (Wood and Bache; usdisp, Bistorta): astringent comparable to but less powerful than kino, powder dose 20 to 30 grains (1.3 to 2.0 g). Culpeper, The Complete Herbal (1653), Bistort or Snakewee", "locator": "The Dispensatory of the United States of America (Wood and Bache; usdisp, Bistorta): astringent comparable to but less powerful than kino, powder dose 20 to 30 grains (1.3 to 2.0 g). Culpeper, The Complete Herbal (1653), Bistort or Snakewee", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H214', 'Bitter Sophora (Ku Shen)', 'Sophora flavescens', 'Fabaceae (Leguminosae)', 'Root (dried; Radix Sophorae Flavescentis)', 'Bitter', 'Cold', 'Dry', 'Dampness, Excess Heat, Acute Inflammation, damp-heat infection (acute and chronic), Wind with itching skin, frank Excess conditions.', 'Cold, Deficiency, Dryness, Exhaustion; any yang-deficient or fluid-depleted state without genuine damp-heat.', 'Integumentary (skin), Digestive (large intestine and stomach), Urinary (bladder), Hepatic (liver), Reproductive (uro-genital mucosa), with minor immune-modulating reach.', 'Damp-heat skin disease (eczema, scabies, weeping itchy lesions, carbuncles), intractable itching, damp-heat dysentery and diarrhea, damp-heat leukorrhea and genital itch, hot burning painful urination, jaundice, bleeding hemorrhoids, and intestinal parasites.', 'Hot-Damp-Excess: the robust, ruddy, damp-heat phenotype with a greasy yellow tongue coat, foul discharges, and inflamed weeping skin. Poorly suited to thin, cold, depleted, or dry constitutions.', 'Pitta, Kapha', 'Vata', 'Damp-Heat of the skin, Large Intestine, Lower Burner, and Liver/Gallbladder; Damp-Heat presenting with itching, foul discharge, dysentery, or parasites.', 'Spleen and Stomach deficiency-cold; Kidney yang deficiency; Qi deficiency; Yin deficiency without damp-heat.', 'Extremely bitter and cold. Even short internal courses readily injure the spleen and stomach in cold or deficient patients. Narrow toxic margin: overdose causes irritability, muscle twitching and cramps, excitation, and, in gross overdose, dyspnea and respiratory depression. Prolonged or high-dose internal use may burden the kidneys. Practitioner-administered only; not for casual self-dosing.', 'Classical Eighteen Incompatibilities: absolutely incompatible with Li Lu (Veratrum nigrum). Contraindicated in spleen and stomach deficiency-cold, yang deficiency, and fluid-deficient states lacking true damp-heat. Avoid in pregnancy and lactation. Not for internal pediatric self-treatment.', 'Contraindicated. Traditional texts prohibit use in pregnancy, and the quinolizidine alkaloids (matrine, oxymatrine) are pharmacologically active with insufficient human safety data and potential uterine and cardiac activity. Avoid (aligns with AHPA Botanical Safety Handbook conservative classing for potent alkaloidal roots and the classical TCM contraindication).', 'Avoid. No adequate lactation safety data exist; the active alkaloids may transfer into milk. Insufficient data; avoid.', 'Not for internal use in children. The narrow toxic margin and bitter-cold, depleting nature make internal pediatric dosing inappropriate. Supervised external washes only, if used at all.', 'Modulates cytochrome P450 and P-glycoprotein. Sophocarpine from the root inhibits CYP3A4 and CYP2C9 in human liver microsomes, while matrine and oxymatrine can induce CYP2B, and the extract reduced oral indinavir levels in rats via CYP3A/P-gp. Use caution with narrow-therapeutic-index CYP3A4/2C9 substrates (warfarin, several statins, protease inhibitors, immunosuppressants such as cyclosporine and tacrolimus). Matrine has intrinsic cardiac/antiarrhythmic activity, so combine cautiously with antiarrhythmics, beta-blockers, or other rhythm-active drugs. Additive nephrotoxicity risk with other nephrotoxic agents at high or prolonged doses. Human clinical interaction data are limited; conclusions rest on in vitro human-microsome and animal pharmacokinetic studies.', 'Decoction for internal use; external wash, sitz bath, or fomentation of the decoction for itch and skin or genital lesions; powder or pill to mask the extreme bitterness; tincture; and medicated salve or ointment for topical skin use.', 'Practitioner-administered. Decoction 4.5-9 g/day of dried root (range 3-15 g); begin at the low end. Topical wash: 15-30 g decocted in water as an external soak or sitz bath. Tincture (1:5): 1-4 mL. Do not self-escalate; discontinue at the first sign of agitation, twitching, palpitations, or breathlessness.', 'Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ku Shen (苦参), listed among the middle-grade herbs.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Yim et al., Evid Based Complement Alternat Med 2019, CYP450 inhibition by S. flavescens in human liver microsomes (PMC6436327); Yang et al., PLOS One 2012, S. flavescens-indinavir CYP3A/P-gp interaction (PMC3281083); Yuan et al., Basic Clin Pharmacol Toxicol 2010, matrine/oxymatrine CYP effects (PMID 20524938).', 'The Chinese name Ku Shen means ''bitter root,'' and it is among the most bitter herbs in the materia medica. Chief constituents are quinolizidine alkaloids (matrine, oxymatrine, sophocarpine, sophoridine) plus prenylated flavonoids (kurarinone, kushenol). These alkaloids drive both its therapeutic actions (antiparasitic, antimicrobial, antipruritic, antiarrhythmic, airway-relaxant, and antineoplastic research interest) and its narrow toxic margin: overdose produces CNS excitation, muscle spasm, and respiratory depression. A middle-grade herb of the Shennong Ben Cao Jing, it is a heat-clearing, damp-drying, parasite-killing drain, not a tonic. It is bound by the Eighteen Incompatibilities (opposed to Li Lu / Veratrum) and traditionally counteracted by Bei Mu, Tu Si Zi, and Mai Men Dong.', 'Not in canonical biblical texts. Native to East Asia (China, Korea, Japan, and Siberia); first recorded in the Han-era Shennong Ben Cao Jing and continuous in Chinese materia medica thereafter.', 'Not at-risk. Sophora flavescens is widely cultivated and commercially abundant across China and is not listed by United Plant Savers or CITES. Source cultivated, lab-tested root (confirm the pharmacopoeial marker of roughly 1.2 percent or greater total alkaloids and screen for heavy metals and adulterants) from reputable suppliers.', 'Cold, dry, and intensely bitter: a damp-heat scouring drain that clears heat, dries dampness, kills parasites, and quiets itch.', 'Refer for high fever with rigors, bloody or dehydrating dysentery, spreading skin infection or cellulitis, jaundice, blood in the urine, or suspected systemic parasitic infection. Because of the narrow toxic margin, stop and seek care for palpitations, muscle twitching, agitation, or shortness of breath (early alkaloid toxicity).', 'Bitter Sophora / Ku Shen (koo shun); Sophora flavescens (so-FOR-uh fla-VESS-enz).', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ku Shen (\u82e6\u53c2), listed among the middle-grade herbs.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ku Shen (\u82e6\u53c2), listed among the middle-grade herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Yim et al., Evid Based Complement Alternat Med 2019, CYP450 inhibition by S. flavescens in human liver microsomes (PMC6436327); Yang et al., PLOS One 2012, S. flave", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Yim et al., Evid Based Complement Alternat Med 2019, CYP450 inhibition by S. flavescens in human liver microsomes (PMC6436327); Yang et al., PLOS One 2012, S. flave", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
