INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H214', 'C02', 'Indicated', 'Primary', 'Hot, damp-heat, robust excess type.', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ku Shen (\u82e6\u53c2), listed among the middle-grade herbs.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Ku Shen (\u82e6\u53c2), listed among the middle-grade herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Yim et al., Evid Based Complement Alternat Med 2019, CYP450 inhibition by S. flavescens in human liver microsomes (PMC6436327); Yang et al., PLOS One 2012, S. flave", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Yim et al., Evid Based Complement Alternat Med 2019, CYP450 inhibition by S. flavescens in human liver microsomes (PMC6436327); Yang et al., PLOS One 2012, S. flave", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
