INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI955', 'H214', 'other', 'Li Lu (Veratrum nigrum)', 'absolute', 'Classical Eighteen Incompatibilities (十八反): Ku Shen is among the Shen-named herbs opposed to Li Lu; the combination is held to produce dangerous toxicity.', 'Never combine Ku Shen with Li Lu (Veratrum) in any formula.', 'Classical Chinese materia medica (Eighteen Incompatibilities); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI956', 'H214', 'pregnancy', 'Pregnancy', 'absolute', 'Traditional prohibition; pharmacologically active quinolizidine alkaloids (matrine, oxymatrine) with potential uterine and cardiac activity and insufficient human safety data.', 'Do not use internally or as significant topical exposure during pregnancy.', 'AHPA Botanical Safety Handbook (2nd ed.) conservative classing for potent alkaloidal roots; classical TCM contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI957', 'H214', 'breastfeeding', 'Breastfeeding', 'moderate', 'No adequate lactation data; active alkaloids may transfer into breast milk.', 'Avoid during breastfeeding; insufficient data.', 'Absence of data in AHPA Botanical Safety Handbook / Mills & Bone; precautionary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI958', 'H214', 'condition', 'Spleen/Stomach deficiency-cold and yang deficiency', 'absolute', 'Intensely bitter and cold; injures digestive yang and worsens cold-deficiency presentations.', 'Contraindicated; do not use in weak, cold, or yang-deficient patients.', 'Shennong Ben Cao Jing tradition; Bensky, Clavey & Stoger, Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI959', 'H214', 'other', 'High or prolonged dosing', 'moderate', 'Quinolizidine alkaloid (matrine/oxymatrine) neurotoxicity: CNS excitation, irritability, muscle twitching and cramps, and, in gross overdose, dyspnea and respiratory depression; possible cumulative nephrotoxicity.', 'Practitioner-administered only; stay within 3-15 g decoction range, begin low, and discontinue at the first sign of agitation, twitching, palpitations, or breathlessness.', 'TCM clinical toxicology; matrine/oxymatrine pharmacology literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI960', 'H214', 'drug_interaction', 'Narrow-therapeutic-index CYP3A4/CYP2C9 substrates (warfarin, several statins, protease inhibitors, cyclosporine, tacrolimus)', 'moderate', 'Sophocarpine inhibits CYP3A4 and CYP2C9 and matrine/oxymatrine can induce CYP2B; S. flavescens also modulates P-glycoprotein, altering substrate exposure (reduced indinavir levels shown in rats).', 'Avoid concurrent use with narrow-index substrates or monitor drug levels/INR closely under clinical supervision.', 'Yim et al., Evid Based Complement Alternat Med 2019 (PMC6436327); Yang et al., PLOS One 2012 (PMC3281083); Yuan et al., Basic Clin Pharmacol Toxicol 2010 (PMID 20524938).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI961', 'H214', 'drug_interaction', 'Antiarrhythmics and cardiac rhythm-active drugs (beta-blockers, class I/III antiarrhythmics)', 'moderate', 'Matrine has intrinsic antiarrhythmic and cardiac depressant activity; effects may be additive with rhythm-modifying drugs.', 'Avoid combining with antiarrhythmic or rhythm-active cardiac medications without specialist oversight.', 'Matrine cardiovascular pharmacology literature; Mills & Bone precautionary principle.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI962', 'H214', 'condition', 'Renal impairment', 'moderate', 'Prolonged or high-dose internal use may burden the kidneys.', 'Avoid in renal impairment; limit dose and duration otherwise.', 'TCM clinical caution; alkaloid nephrotoxicity concern.');
