INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H215', 'Codonopsis (Dang Shen)', 'Codonopsis pilosula', 'Campanulaceae (the bellflower family)', 'Dried root (Radix Codonopsis; the long, wrinkled, malt-sweet root, often honey-fried as zhi dang shen to deepen its warming, Spleen-tonifying action)', 'Sweet (a soft, malt-like sweetness; the fresh root is faintly mucilaginous). Classically recorded as simply sweet.', 'Neutral. Recorded classically as sweet and neutral, neither heating nor chilling, which is exactly why it replaces ginseng in everyday deficiency where true ginseng would be too stimulating.', 'Moist. The root generates and preserves fluids (sheng jin) and is faintly mucilaginous, so it moistens as it tonifies.', 'Qi and blood deficiency: the tired, pale, soft-pulsed, easily-winded person whose reserves are spent. Spleen qi deficiency with weak digestion, poor appetite, loose stools, and a heavy, worn-out fatigue. Lung qi deficiency with a weak chronic cough, shortness of breath, and a quiet, low voice. Sinking or collapsed qi with laxity and prolapse of the tissues that qi should hold up. Fluid and yin depletion with dryness and thirst, and the wasting, emaciating exhaustion of long illness and convalescence, where the flesh has thinned toward atrophy. In short, the states of depletion, laxity, and exhaustion that a gentle building tonic is meant to fill.', 'Frank excess and heat: the robust, full, red, feverish, or acutely inflamed person has nothing to tonify, and a sweet building herb only adds fuel and fullness. Acute infection and external invasion (a fresh cold, flu, or fever), where tonifying too early can trap the pathogen inside. Damp and phlegm repletion with a thick, greasy tongue coat, chest and belly fullness, and heavy congestion, which the cloying sweetness can worsen. Marked food or qi stagnation with bloating and distention. It fills and holds, so it is wrong wherever the picture is full, hot, acutely infected, or clogged rather than empty and depleted.', 'Digestive above all, as the great tonic of the Spleen and Stomach: appetite, assimilation, stool formation, and the muscular tone that keeps the organs lifted. Respiratory and the Lungs, whose qi it rebuilds for chronic weak cough and breathlessness. Immune and the defensive (wei) qi, raising resistance in the frequently-ill and the convalescent. Cardiovascular and the Blood, which it helps generate for the pale, palpitating, anemic picture. Secondary Nervous-system and adaptive support, easing the mental fatigue and low stamina of chronic stress.', 'Qi-deficiency fatigue, debility, and slow convalescence after illness or childbirth. Weak Spleen digestion: poor appetite, bloating after eating, loose stools, and a tired heaviness in the limbs. Lung qi deficiency: chronic weak cough, shortness of breath on exertion, and a faint voice. Recurrent colds and infections with low defensive qi. Blood-deficiency signs: pallor, dizziness, and palpitations. Dryness and thirst from spent fluids, including the wasting-thirst (xiao ke) pattern. Burnout, low stamina, and the wear of chronic stress, where it serves as a gentle daily adaptogen.', 'Cold-to-neutral, dry, depleted: the thin, pale, tired, hollowed-out phenotype whose qi and blood are spent, who tires quickly, digests weakly, and catches every passing bug. The classic deficient and pale convalescent, and the worn, over-extended Vata-like person who needs grounding, moistening nourishment. Not for the robust, ruddy, hot, damp, or acutely-ill constitution, in whom a sweet building tonic only adds heat, damp, and fullness.', 'Vata, Pitta', 'Kapha', 'Spleen qi deficiency (fatigue, poor appetite, loose stools, sallow complexion) and Lung qi deficiency (weak chronic cough, shortness of breath, faint voice), the two anchor patterns. General qi deficiency and combined qi-and-blood deficiency (pallor, dizziness, palpitations), where it both tonifies qi and helps generate blood. Fluid deficiency and mild yin deficiency with thirst and dryness, since it generates fluids (sheng jin). Its defining role is as a gentler, food-grade stand-in for Ren Shen (Panax ginseng): after 1949 it became the routine substitute in tonic formulas such as Si Jun Zi Tang and Bu Zhong Yi Qi Tang for everyday qi deficiency, at roughly two to three times the dose, reserving true ginseng for collapse and severe deficiency.', 'Excess and heat patterns without deficiency, and vigorous yin-deficient fire, where a sweet neutral tonic is unhelpful or aggravating. Acute exterior invasion (wind-cold or wind-heat with an unresolved fever), where premature tonification can trap the pathogen. Damp-heat and phlegm-damp repletion with a thick greasy coat and fullness, which the cloying sweetness worsens. Marked qi stagnation or food stagnation with distention. Classically incompatible with Li Lu (Veratrum), one of the ''eighteen antagonisms'' (shi ba fan), and it should never be combined with it.', 'A gentle, food-grade tonic that is well tolerated at ordinary doses. Its sweet, moist, building nature can be cloying: in people carrying a lot of damp or phlegm, or with sluggish digestion and fullness, it can add to the congestion, so it is best paired with aromatic, damp-draining herbs. Because it is tonifying, it should not be pushed during an acute cold, flu, or fever. Very large doses have caused adverse effects in Chinese reports: roughly 30 to 60 g has been associated with throat discomfort, dizziness, and visual disturbance, and doses above 60 g per day with precordial discomfort and cardiac arrhythmia, all reversible on stopping. It may mildly slow blood clotting and lower blood sugar (see Drug Interactions). Classically it must not be combined with Li Lu (Veratrum).', 'Acute febrile or excess-heat illness and unresolved external (wind) invasion (TCM). Concurrent Li Lu (Veratrum) by the classical eighteen-antagonisms rule. Caution with anticoagulant or antiplatelet drugs, with diabetes medication, and with immunosuppressant therapy (see Drug Interactions). Discontinue at least one to two weeks before elective surgery because of a mild antiplatelet effect. No absolute contraindication in pregnancy or lactation, but formal safety data are limited, so medicinal use in those settings should be under professional guidance.', 'Likely low risk in moderation, but formal data are limited. Codonopsis is a food-grade herb with ''medicine and food homology'' status in China and is used within traditional Chinese medicine during pregnancy, including in qi- and blood-tonifying formulas for depleted, deficient mothers. There are, however, no controlled human pregnancy studies, and modern Western references (Natural Medicines / RxList; Herbal Reality) take the conservative position that safety is not established and advise either avoiding it or using it only under the supervision of a qualified herbalist or physician. Reserve medicinal doses for professional guidance; culinary amounts simmered in soups are generally regarded as low risk.', 'Probably compatible in moderation. There are no published data on excretion into human milk and no documented toxicity; the lactation reference e-lactancia.org classifies Dang Shen as probable compatibility (''fairly safe''), judging that moderate consumption during breastfeeding carries little or no risk. Traditionally it is a qi- and blood-building tonic given to support recovery and milk production in the postpartum period. Prefer moderate, food-like use from a reliable source, and seek professional guidance for higher medicinal doses.', 'Generally regarded as gentle enough for children in appropriate, reduced doses. Codonopsis is a mild, sweet, food-grade tonic long used in Chinese households (including for children and the elderly) in tonic soups and congees, and it lacks the over-stimulating heat of true ginseng. Formal pediatric safety and dosing studies are lacking, so medicinal doses in children should be scaled to body weight and guided by a qualified practitioner. Do not use it to tonify a child through an acute fever or infection.', 'Anticoagulant and antiplatelet drugs: Codonopsis can mildly inhibit platelet aggregation and slow blood clotting, so combining it with warfarin, heparin, aspirin, clopidogrel, or similar agents may increase the risk of bruising and bleeding (Natural Medicines / RxList rate this a moderate interaction); stop it one to two weeks before surgery. Antidiabetic drugs: its polysaccharides can lower blood glucose and may add to insulin and oral hypoglycemics (metformin, sulfonylureas), so monitor blood sugar. Immunosuppressants: because its polysaccharides stimulate and modulate immune function, it is prudent to avoid it, or use it only under supervision, alongside immunosuppressive therapy such as ciclosporin, tacrolimus, or high-dose corticosteroids in transplant and autoimmune patients, where it could theoretically oppose the drug. Antihypertensives: a possible additive blood-pressure-lowering effect has been suggested. Most of these interactions are mechanistic or based on limited data rather than clinical case reports; the best-documented is the additive bleeding risk. Classically (herb-herb) it is incompatible with Li Lu (Veratrum).', 'Decoction of the dried root is the standard form, alone or in tonic formulas. As a food-grade tonic it is very often simmered into soups, broths, bone broths, and congee (a classic addition to chicken or bone-broth tonics). Honey-fried root (zhi dang shen) is used to strengthen its warming, Spleen-tonifying action. It is also given as a tincture, powder, capsule, and in tonic syrups and medicated wines.', 'Decoction: 9 to 30 g of dried root daily (commonly 9 to 15 g; larger 15 to 30 g doses for more marked deficiency), simmered 30 to 60 minutes, in divided doses. Because it is milder than ginseng, it is dosed at roughly two to three times a ginseng dose for a comparable effect. Tincture (1:3 to 1:5): about 2 to 4 mL up to three times daily. Powder or capsules: about 3 to 9 g daily. Culinary: a few roots simmered in soup or congee. Keep single therapeutic doses well under the 30 g level at which adverse effects have been reported.', 'G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (revised from F. Porter Smith, Shanghai, 1911), Tang-shen / Campanumoea (Codonopsis) pilosula, discussed among the Campanulaceae (with Adenophora and Platycodon) as a root that resembles and is used ''as a tonic like ginseng,'' its taste ''sweetish and slightly mucilaginous, resembling that of malt.''', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Dang Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology, Dang Shen; Dharmananda (ITM), ''Codonopsis: Medicine and Food''; e-lactancia.org, Dang Shen (lactation risk assessment); Natural Medicines / RxList consumer monograph on Codonopsis; Herbal Reality, Codonopsis monograph; Bai et al., Codonopsis Radix ethnopharmacology, phytochemistry, pharmacology and toxicity review (PMC10117688); systematic review of Codonopsis pilosula mechanisms of action (PMC11128667).', 'Family Campanulaceae (bellflower family). The medicinal Dang Shen is chiefly Codonopsis pilosula, with C. pilosula subsp. tangshen (chuan dang shen, Sichuan) and several related Codonopsis species accepted in the Chinese Pharmacopoeia. The root is rich in polysaccharides (the Codonopsis polysaccharides, CPP, its main immunomodulating fraction), polyacetylenes/polyynes (lobetyolin, the standard quality marker, and lobetyol), phenylpropanoid glycosides (the species-defining tangshenosides I to VI), phytosterols (beta-sitosterol, stigmasterol), triterpenes and atractylenolides, inulin-type fructans and simple sugars (the source of its malt-like sweetness), and pyrrolidine alkaloids (codonopsine, codonopsinine) with the beta-carboline perlolyrine as minor constituents, plus amino acids and trace elements. Documented actions include immune modulation and enhancement, gastroprotection (anti-ulcer, gastric-acid modulation), support of hematopoiesis (red-cell and stem-cell proliferation, consistent with its blood-nourishing use), anti-fatigue, antioxidant, and neuroprotective effects; the herb carries ''medicine and food homology'' status and shows very low toxicity in modern testing. Historically it is a relatively late addition to the materia medica: the Qing-dynasty Ben Cao Cong Xin (Wu Yiluo, 1757) is generally credited with first clearly distinguishing Dang Shen from Ren Shen (ginseng), and after 1949 it became the everyday ginseng substitute in Chinese practice.', 'Not in canonical biblical texts and unknown to the ancient Mediterranean world; native to northern and northeastern China (with major cultivation in Gansu, Shanxi, and Shaanxi). Its documented tradition is wholly Chinese: the root Tang-shen (Dang Shen), long used as a food-grade tonic and, from the Qing dynasty onward, formally distinguished from ginseng and adopted as its gentler everyday substitute.', 'Not at risk. Codonopsis pilosula is one of the most widely cultivated of all Chinese tonic herbs, grown as a field crop across Gansu, Shanxi, Shaanxi, and neighboring provinces, and it holds ''medicine and food homology'' status, so demand is met from cultivation rather than wild harvest. Wild stands of the Sichuan subspecies (chuan dang shen) have been reduced by collection, so cultivated root is preferable where that subspecies matters. Not listed by United Plant Savers, which registers North American native plants; Codonopsis is an East Asian species.', 'Neutral and moistening: a soft, malt-sweet qi tonic that quietly rebuilds a spent Spleen and Lung, generates fluids, and nourishes blood in the tired, pale, and convalescent, the gentle everyday ginseng of ordinary deficiency.', 'Refer for unexplained or progressive fatigue, weight loss, or anemia that needs a diagnosis; a cough lasting more than a few weeks, coughing up blood, or breathlessness at rest; persistent palpitations, chest pain, or an irregular heartbeat; high fever or acute infection (do not tonify through an acute illness); blood in the stool or black, tarry stools; and known bleeding disorders. Refer anyone taking warfarin or other anticoagulants, insulin or diabetes medication, or immunosuppressant drugs before use, and anyone pregnant or breastfeeding who wants more than culinary amounts.', 'Codonopsis: koh-doh-NOP-sis. Codonopsis pilosula: koh-doh-NOP-sis pih-loh-SOO-lah. Dang Shen: dahng SHUN.', 'free', 'Approved', '{"title": "G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (revised from F. Porter Smith, Shanghai, 1911), Tang-shen / Campanumoea (Codonopsis) pilosula, discussed among the Campanulaceae (with Adenophora and Platycodon) as a root that resemble", "locator": "G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (revised from F. Porter Smith, Shanghai, 1911), Tang-shen / Campanumoea (Codonopsis) pilosula, discussed among the Campanulaceae (with Adenophora and Platycodon) as a root that resemble", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Dang Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology, Dang Shen; Dharmananda (ITM), ''Codonopsis: Medicine and Food''; e-lactancia.org, Dang Shen (l", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Dang Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology, Dang Shen; Dharmananda (ITM), ''Codonopsis: Medicine and Food''; e-lactancia.org, Dang Shen (l", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H215', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS01', 'Primary', 'Deficiency: the anchor state, qi and blood deficiency of the spent and depleted.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS04', 'Primary', 'Exhaustion: worn-out fatigue, burnout, and slow convalescence.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS03', 'Secondary', 'Dryness: generates fluids (sheng jin) for thirst, dryness, and dry cough.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS09', 'Secondary', 'Laxity: sinking or collapsed qi with weak tissue tone and prolapse.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS21', 'Secondary', 'Blood deficiency: nourishes blood for pallor, dizziness, and palpitations.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS13', 'Secondary', 'Wei qi weakness: strengthens defensive qi in the frequently-ill.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS02', 'Minor', 'Atrophy: wasting and emaciation of long depletion and illness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS16', 'Primary', 'Excess conditions: a building tonic is wrong in frank repletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS05', 'Primary', 'Excess heat: a sweet tonic adds fuel where heat, not depletion, rules.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS07', 'Secondary', 'Dampness: the cloying sweetness can worsen damp and phlegm repletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS15', 'Secondary', 'Acute infection: tonifying too early can trap an active pathogen.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H215', 'TS08', 'Minor', 'Stagnation: cloying tonic can add to food and qi stagnation, fullness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY08', 'Primary', 'Digestive: the great Spleen and Stomach qi tonic, appetite and assimilation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY13', 'Primary', 'Spleen: rebuilds Spleen qi, holds tissue up, forms stool.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY07', 'Primary', 'Respiratory: tonifies Lung qi for weak chronic cough and breathlessness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY14', 'Primary', 'Lungs: the Lung qi tonic, faint voice and shortness of breath.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY05', 'Secondary', 'Immune: raises defensive (wei) qi and resistance in the convalescent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY06', 'Secondary', 'Cardiovascular/Blood: generates blood for the pale, palpitating, anemic picture.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H215', 'SY01', 'Minor', 'Nervous/adaptive: eases mental fatigue and low stamina of chronic stress.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A23', 'Primary', 'Tonic: the defining qi tonic action for the Spleen and Lung.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A01', 'Primary', 'Adaptogen: gentle stress resilience, the everyday ginseng substitute.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A06', 'Primary', 'Immune tonic: strengthens defensive qi and resistance.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A39', 'Secondary', 'Nutritive: nourishing, builds qi and blood, food-grade tonic.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A40', 'Secondary', 'Trophorestorative: restores depleted Spleen and Lung function.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A11', 'Secondary', 'Demulcent: mucilaginous, moistens and generates fluids.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A04', 'Secondary', 'Immunomodulator: polysaccharides modulate immune activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A05', 'Secondary', 'Anabolic: building, blood- and flesh-nourishing action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A20', 'Minor', 'Galactagogue: supports lactation via qi and blood building.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A25', 'Minor', 'Antioxidant: documented free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H215', 'A36', 'Minor', 'Hypoglycemic: polysaccharides can lower blood glucose.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP07', 'Primary', 'Fatigue: qi-deficiency tiredness and low stamina.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP03', 'Primary', 'Debility: general depletion and slow convalescence.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP58', 'Secondary', 'Dyspepsia/low digestive fire: weak Spleen, poor appetite, fullness after eating.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP12', 'Secondary', 'Digestive upset: loose stools and weak assimilation of Spleen qi deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP17', 'Secondary', 'Respiratory issues: chronic weak cough and shortness of breath (Lung qi def).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP50', 'Secondary', 'Dry unproductive cough: Lung qi/fluid deficiency, generates fluids.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP06', 'Secondary', 'Frequent illness: recurrent colds from low defensive qi.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP16', 'Secondary', 'Immune weakness: raises resistance in the depleted and convalescent.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP01', 'Secondary', 'Adrenal fatigue: adaptogenic support of burnout and depletion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP02', 'Minor', 'Chronic stress: gentle daily resilience tonic.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP56', 'Minor', 'Diarrhea: loose stools of Spleen qi deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP46', 'Minor', 'Palpitations: blood-deficiency palpitations with pallor and dizziness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP27', 'Minor', 'Blood sugar dysregulation: wasting-thirst (xiao ke) and glucose-lowering effect.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H215', 'CP24', 'Minor', 'Mental fog: fatigue-related cognitive dullness, neuroprotective support.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P04', 'Primary', 'Decoction of the dried root, the standard form, alone or in formula.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P12', 'Primary', 'Added to soups, broths, and congee, the classic food-grade tonic use.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P01', 'Secondary', 'Tincture (1:3 to 1:5).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P03', 'Secondary', 'Powdered root (raw or honey-fried, zhi dang shen).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P02', 'Secondary', 'Capsules of the dried root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H215', 'P09', 'Minor', 'Tonic syrups and medicated wines.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H215', 'C07', 'Indicated', 'Primary', 'Deficient/Pale: the tired, pale, qi- and blood-deficient convalescent.', '{"title": "G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (revised from F. Porter Smith, Shanghai, 1911), Tang-shen / Campanumoea (Codonopsis) pilosula, discussed among the Campanulaceae (with Adenophora and Platycodon) as a root that resemble", "locator": "G.A. Stuart, Chinese Materia Medica: Vegetable Kingdom (revised from F. Porter Smith, Shanghai, 1911), Tang-shen / Campanumoea (Codonopsis) pilosula, discussed among the Campanulaceae (with Adenophora and Platycodon) as a root that resemble", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Dang Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology, Dang Shen; Dharmananda (ITM), ''Codonopsis: Medicine and Food''; e-lactancia.org, Dang Shen (l", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Dang Shen; Chen and Chen, Chinese Medical Herbology and Pharmacology, Dang Shen; Dharmananda (ITM), ''Codonopsis: Medicine and Food''; e-lactancia.org, Dang Shen (l", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
