INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI963', 'H215', 'pregnancy', 'Pregnancy', 'moderate', 'No controlled human data. Codonopsis is a food-grade tonic used within TCM during pregnancy for qi/blood deficiency, but Western references consider its safety unestablished. It also has a mild antiplatelet effect.', 'Culinary amounts in soups are generally low risk; reserve medicinal doses for use under a qualified herbalist or physician.', 'Natural Medicines / RxList consumer monograph on Codonopsis; Herbal Reality, Codonopsis monograph (pregnancy and lactation).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI964', 'H215', 'breastfeeding', 'Breastfeeding', 'low', 'No data on excretion into human milk and no documented toxicity; traditionally used as a qi/blood tonic postpartum.', 'Moderate, food-like use from a reliable source is judged low risk; seek professional guidance for higher medicinal doses.', 'e-lactancia.org, Dang Shen / Codonopsis pilosula (rated probable compatibility, ''fairly safe'').');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI965', 'H215', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel)', 'moderate', 'Codonopsis can inhibit platelet aggregation and slow blood clotting, adding to the effect of anticoagulant/antiplatelet drugs and raising bruising and bleeding risk.', 'Avoid concurrent therapeutic use without supervision; monitor for bleeding and stop one to two weeks before elective surgery.', 'Natural Medicines / RxList consumer monograph on Codonopsis (moderate interaction); Herbal Reality, Codonopsis monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI966', 'H215', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'moderate', 'Codonopsis polysaccharides can lower blood glucose and may add to the glucose-lowering effect of diabetes medication, risking hypoglycemia.', 'Monitor blood glucose and adjust medication under supervision if combined.', 'Bai et al., Codonopsis Radix pharmacology review (PMC10117688); attiliodalberto.com TCM herb monograph (Dang Shen, diabetes medication note).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI967', 'H215', 'drug_interaction', 'Immunosuppressant therapy (ciclosporin, tacrolimus, high-dose corticosteroids)', 'moderate', 'The immune-stimulating and immunomodulating polysaccharides could theoretically oppose immunosuppressive therapy in transplant and autoimmune patients.', 'Avoid or use only under specialist supervision in anyone on immunosuppressant drugs.', 'Bai et al., Codonopsis Radix pharmacology review (PMC10117688); mechanistic (immune-tonic class caution, Mills and Bone principles).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI968', 'H215', 'drug_interaction', 'Li Lu (Veratrum nigrum / black false hellebore)', 'moderate', 'Classical incompatibility under the ''eighteen antagonisms'' (shi ba fan); the ginseng-class tonics, including Dang Shen, are traditionally never combined with the toxic Li Lu.', 'Do not combine Codonopsis with Li Lu (Veratrum) in any formula.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); classical shi ba fan incompatibility list.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI969', 'H215', 'condition', 'Acute excess-heat or external (wind) invasion; excess patterns without deficiency', 'moderate', 'Tonifying during an acute cold, flu, or fever, or in a robust excess/heat pattern, can trap the pathogen or add heat and fullness where there is no deficiency to fill.', 'Do not tonify through an acute infection or febrile illness; use only where genuine deficiency is present.', 'Bensky, Clavey and Stoger, Materia Medica; Chen and Chen, Chinese Medical Herbology and Pharmacology (Dang Shen cautions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI970', 'H215', 'other', 'High-dose overdose (over 30 to 60 g/day)', 'moderate', 'Chinese clinical reports link roughly 30 to 60 g to throat discomfort, dizziness, and visual disturbance, and doses above 60 g/day to precordial discomfort and cardiac arrhythmia, all reversible on discontinuation.', 'Keep single therapeutic doses well under 30 g; discontinue if chest discomfort, palpitations, or visual symptoms occur.', 'Herbal Reality, Codonopsis monograph (overdose effects); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
