INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H216', 'Fringe Tree', 'Chionanthus virginicus', 'Oleaceae (olive family)', 'Root bark (dried bark of the root; fresh root bark preferred for tincture). Also called Old Man''s Beard, Snowdrop Tree, Poison Ash.', 'Bitter, Astringent', 'Cool', 'Dry', 'Stagnation and congestion of the hepatobiliary and portal terrain: biliary stasis, venous and portal congestion, and the boggy, sluggish, torpid liver. Damp-heat jaundice with sallow, greasy skin, icteric hue, and light, watery, clay-tinged stools. Hepatic tenderness and colicky congestion of the biliary tree.', 'Frank dryness, tissue depletion, and exhaustion. A cold, draining bitter further depletes the thin, dry, cold, deficient constitution and offers nothing to atrophy or true deficiency states.', 'Hepatic (liver) and biliary tract, primary; digestive; lymphatic and glandular; urinary; spleen.', 'Non-obstructive (cholestatic) jaundice; hepatic congestion with portal and venous stasis; sluggish liver and bile stagnation; gallstones and biliary gravel without duct obstruction; hepatic dyspepsia with nausea, vomiting, and right-upper-quadrant tenderness; glycosuria and blood-sugar dysregulation; glandular and lymphatic congestion (scrofula).', 'Cold-Damp-Stagnant: the sallow, boggy, torpid hepatic phenotype. Melancholic-phlegmatic, with an icteric or greasy complexion, expressionless eyes, hepatic tenderness, portal congestion, and thin light-colored stools.', 'Pitta, Kapha', 'Vata', 'Damp-Heat in the Liver and Gallbladder (damp-heat jaundice); Liver Qi stagnation with hepatic and portal congestion; a measure of Blood stasis in the venous system.', 'Spleen Qi deficiency with cold, Yin deficiency with dryness, and Kidney Yang deficiency. A cold, draining bitter aggravates these depleted, cold patterns.', 'Bitter and stimulating to bile flow. Large doses may provoke frontal headache, nausea, or ptyalism (excessive salivation was reported historically). Start at the low end and titrate upward. Aqueous infusions are weak because the active resin is water-insoluble; King''s called the plain infusion nearly inert. Alcoholic preparations (tincture or Eclectic specific medicine) are markedly more effective.', 'Contraindicated in biliary or bile-duct obstruction, impacted gallstones obstructing the duct, and malignant obstruction of the biliary tree. Do not use to force impacted stones through a blocked duct. Painful obstructive jaundice requires medical evaluation, not self-treatment.', 'Avoid. Safety in pregnancy is not established (insufficient modern data), and practitioner references contraindicate use in pregnancy without qualified professional supervision.', 'Avoid. No reliable safety data during lactation; insufficient data to establish safety.', 'Not established for infants or young children; no pediatric safety or dosing data exists. Use only under qualified professional guidance, if at all.', 'No well-documented clinical drug interactions (limited data). Theoretical: additive blood-glucose lowering with insulin or oral hypoglycemics, since historical use reduced glycosuria and urine specific gravity, so monitor blood glucose if combined. As a stimulating cholagogue it is theoretically inappropriate where mechanical biliary obstruction is being managed.', 'Tincture or Eclectic specific medicine (alcohol extraction, preferred). Decoction of the root bark. Powdered bark. Traditional water infusion (weak, largely inert). Bark poultice for external ulcers and wounds (folk use).', 'Tincture (1:5, 40-45% alcohol): 10-30 drops (0.5-2 ml) up to 3x daily. Specific Chionanthus: 10 drops in water every 3 hours; in acute hepatic colic, 10 drops every 30 minutes. Decoction: about 1-2 tsp dried root bark per cup of water, simmered ~25 minutes, 1 cup up to 3x daily.', 'King''s American Dispensatory (Felter & Lloyd, 1898) - Chionanthus.', 'Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Chionanthus; Cook, The Physio-Medical Dispensatory (1869) - Chionanthus; Michael Moore, Herbal Materia Medica / Southwest School of Botanical Medicine - Chionanthus; The Naturopathic Herbalist - Chionanthus virginicus; modern insufficient-data safety position (WebMD / RxList fringetree monograph); AHPA Botanical Safety Handbook, 2nd ed., for general precautionary framing.', 'Constituents of the root bark include lignan glycosides (phillyrin), the saponin glycoside chionanthin, and a water-insoluble resin held to carry the activity, which is why tinctures and specific medicine outperform aqueous infusions that King''s judged nearly inert. Modern work confirms antioxidant lignans in the plant. The 19th-century American Eclectic and Physiomedical physicians (King, Ellingwood, Cook) ranked Chionanthus their premier hepatic and cholagogue for non-obstructive jaundice, hepatic congestion, biliary colic, and cholelithiasis, and also employed it for glycosuria/diabetes and for portal and splenic congestion. It acts on the abdominal glandular organs and, to a degree, the venous system, relieving congestion. Bounding caution: it is a stimulating cholagogue and must never be used to drive impacted stones through an obstructed duct.', 'Not in canonical biblical texts. Chionanthus virginicus is native to the woodlands of the southeastern United States; the genus name means ''snow flower,'' from the drooping white spring panicles. Early settlers and Southeastern peoples used the root and bark as a wound wash and for liver, kidney, and skin complaints. It entered formal materia medica through the 19th-century American Eclectic and Physiomedical physicians, who prized it as their leading hepatic remedy.', 'A slow-growing native understory tree/shrub. Harvesting root bark is destructive and typically kills the plant, so wild-collection of root bark is inherently unsustainable; source from cultivated or nursery-propagated stock and use bark from prunings where possible. As a member of Oleaceae, white fringetree is a confirmed host of the invasive emerald ash borer, adding pressure to wild populations. Not currently listed by United Plant Savers, but treat it as a conserve-by-cultivation species.', 'A cool, dry, decongesting bitter that drains the stagnant, boggy, jaundiced liver and reopens biliary flow.', 'Refer for painful or deepening jaundice, clay-colored (acholic) stools with dark urine, fever with right-upper-quadrant pain, severe biliary colic with persistent vomiting, suspected gallstone impaction or cholecystitis, signs of hepatitis, or unexplained weight loss. These may indicate obstruction, infection, or malignancy needing medical or surgical care.', 'Fringe Tree (frinj tree); Chionanthus virginicus (kye-oh-NAN-thus ver-JIN-ih-kus).', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Chionanthus.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Chionanthus.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Chionanthus; Cook, The Physio-Medical Dispensatory (1869) - Chionanthus; Michael Moore, Herbal Materia Medica / Southwest School of Botanical Medicine - Chionanthu", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919) - Chionanthus; Cook, The Physio-Medical Dispensatory (1869) - Chionanthus; Michael Moore, Herbal Materia Medica / Southwest School of Botanical Medicine - Chionanthu", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_te