INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI971', 'H216', 'condition', 'Biliary / bile-duct obstruction (impacted or obstructing gallstones, malignant ductal obstruction)', 'absolute', 'As a stimulating cholagogue and choleretic it increases bile flow against a mechanical blockage, risking rising ductal pressure, biliary colic, or duct injury.', 'Do not use in known or suspected obstructive jaundice, impacted stones, or ductal malignancy. Refer for imaging and surgical evaluation.', 'Michael Moore, Herbal Materia Medica; The Naturopathic Herbalist (Chionanthus virginicus); King''s American Dispensatory 1898.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI972', 'H216', 'pregnancy', 'Pregnancy', 'moderate', 'Safety not established (insufficient modern data); a bitter cholagogue and alterative with historical hepatic-stimulant activity.', 'Avoid in pregnancy unless supervised by a qualified practitioner.', 'WebMD / RxList fringetree monograph (insufficient-data position); practitioner monographs (herbaltransitions, The Naturopathic Herbalist).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI973', 'H216', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable safety data during lactation.', 'Avoid during breastfeeding; insufficient data to establish safety.', 'WebMD / RxList fringetree monograph (insufficient-data position).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI974', 'H216', 'other', 'Infants and young children', 'moderate', 'No established pediatric safety or dosing data for a bitter hepatic stimulant.', 'Avoid in young children; use only under qualified professional guidance.', 'No pediatric data located; general AHPA/precautionary standard.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI975', 'H216', 'drug_interaction', 'Antidiabetic / hypoglycemic drugs (insulin, sulfonylureas)', 'low', 'Historical use reduced glycosuria and urine specific gravity, suggesting a blood-glucose-lowering tendency; additive hypoglycemia is theoretically possible.', 'Monitor blood glucose if combined. Theoretical only; no confirmed clinical interaction reports.', 'Ellingwood, American Materia Medica 1919 (glycosuria); mechanistic/theoretical.');
