INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H217', 'TCM10', 'Primary', 'Dampness/Phlegm: warm acrid herb that dries and transforms cold-damp phlegm and catarrh and drains damp via diuresis.', '{"title": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "locator": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "locator": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H217', 'TCM13', 'Secondary', 'Wind-Cold: disperses wind-cold in the exterior and channels; respiratory catarrh and cold-damp muscular and joint pain.', '{"title": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "locator": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "locator": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H217', 'TCM11', 'Primary', 'Heat/Fire: hot, acrid oil aggravates stomach fire, damp-heat, and inflamed or bleeding conditions.', '{"title": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "locator": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "locator": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H217', 'TCM07', 'Secondary', 'Yin deficiency: warming, drying pungency injures fluids and worsens dryness.', '{"title": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "locator": "Grieve M. A Modern Herbal (1931), Horseradish (Cochlearia armoracia): stimulant, aperient, rubefacient, diuretic and antiseptic, also expectorant and antiscorbutic, and if taken too freely emetic; the active volatile oil (allyl isothiocyana", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "locator": "German Commission E monograph, Armoraciae rusticanae radix (horseradish root), approved for catarrh of the respiratory tract and supportive treatment of urinary-tract infection, and externally for hyperemic (rubefacient) treatment of minor ", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI976', 'H217', 'pregnancy', 'Pregnancy', 'moderate', 'The volatile allyl isothiocyanate (mustard oil) is a toxic mucosal irritant, and the tincture used regularly or in large amounts is reported to risk miscarriage. Modern databases rate medicinal horseradish LIKELY UNSAFE in pregnancy.', 'Avoid therapeutic doses, tinctures, and concentrated preparations in pregnancy. Small culinary condiment amounts are generally considered acceptable.', 'WebMD/RxList Horseradish; Drugs.com Horseradish monograph; German Commission E monograph (Armoraciae rusticanae radix).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI977', 'H217', 'breastfeeding', 'Breastfeeding', 'moderate', 'Pungent isothiocyanates are excreted and are mucosal irritants; human lactation-safety data are lacking, and large or medicinal amounts are rated LIKELY UNSAFE.', 'Avoid therapeutic and large amounts while breastfeeding. Culinary seasoning amounts are generally considered acceptable.', 'WebMD/RxList Horseradish; Drugs.com Horseradish; German Commission E monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI978', 'H217', 'other', 'Children under 4 years', 'moderate', 'The mustard oil irritates the digestive tract; internal use is contraindicated by the German Commission E in children under four, and modern databases rate it LIKELY UNSAFE by mouth in young children.', 'Do not use medicinally in children under four. External rubefacient use on a child''s skin risks burning and is not advised.', 'German Commission E monograph (Armoraciae rusticanae radix); WebMD/RxList Horseradish.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI979', 'H217', 'drug_interaction', 'Levothyroxine and thyroid-hormone medication (levothyroxine, liothyronine)', 'moderate', 'Horseradish is goitrogenic (Brassica isothiocyanates depress thyroid activity) and may blunt the effect of thyroid-replacement hormone.', 'Avoid or use cautiously with thyroid medication; monitor thyroid status and consult the prescriber before combining.', 'WebMD/RxList Horseradish (levothyroxine interaction, Moderate); Natural Medicines / TRC Horseradish monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI980', 'H217', 'condition', 'Hypothyroidism and goiter', 'moderate', 'Goitrogenic isothiocyanates can depress thyroid iodine uptake and worsen an underactive thyroid.', 'Avoid medicinal horseradish in hypothyroidism or goiter; monitor thyroid function if used.', 'WebMD/RxList Horseradish; Drugs.com Horseradish.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI981', 'H217', 'condition', 'Gastrointestinal ulcers, gastritis, and inflammatory bowel disease', 'moderate', 'The acrid mustard oil is a direct gastrointestinal irritant that inflames ulcerated or inflamed mucosa; excess can cause bloody vomiting and diarrhea. Commission E lists GI ulcers as a contraindication.', 'Avoid in peptic or duodenal ulcers, gastritis, and inflammatory bowel disease.', 'German Commission E monograph; WebMD/RxList Horseradish; King''s American Dispensatory (Felter and Lloyd, 1898).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI982', 'H217', 'condition', 'Kidney disorders and acute nephritis', 'moderate', 'A strong diuretic and mucosal irritant; may aggravate impaired or irritated kidneys. Commission E lists kidney disorders as a contraindication.', 'Avoid in kidney disease and acute nephritis; refer suspected kidney infection for medical care.', 'German Commission E monograph; WebMD/RxList Horseradish.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI983', 'H217', 'other', 'Overdose / immoderate internal or prolonged topical use', 'moderate', 'Excess internal doses cause burning epigastric pain, nausea, vomiting, and in large amounts bloody vomiting and diarrhea; prolonged skin contact blisters and burns.', 'Stay within condiment-sized amounts internally; keep topical applications brief and remove at the first sting or reddening.', 'King''s American Dispensatory (1898); Grieve, A Modern Herbal (1931); WebMD/RxList Horseradish.');
