INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI984', 'H218', 'pregnancy', 'Pregnancy (internal therapeutic doses)', 'moderate', 'Long traditional reputation as a uterine astringent and menstrual (emmenagogue) herb; no reliable modern human safety data. Modern consumer references advise avoidance in pregnancy.', 'Avoid internal medicinal doses in pregnancy unless supervised by a qualified practitioner; external use (gargle, wash, compress) is not expected to be of concern.', 'Herbal Reality, Lady''s Mantle monograph; drugs.com natural-products monograph, ''Lady''s Mantle''; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI985', 'H218', 'breastfeeding', 'Breastfeeding (internal therapeutic doses)', 'moderate', 'No reliable human safety data during lactation; high tannin content. Same consumer references caution against use.', 'Avoid internal therapeutic doses while nursing without professional guidance; occasional external use is lower concern.', 'Herbal Reality, Lady''s Mantle monograph; insufficient modern data (precautionary).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI986', 'H218', 'pediatric', 'Infants and young children (internal use)', 'low', 'No pediatric safety data for internal therapeutic doses; high tannin load can irritate the gut and impair mineral absorption.', 'Prefer dilute, short-term external use (gargle, wash); keep any internal use brief and dilute, ideally under guidance.', 'Insufficient modern data (precautionary); Brinker, Herbal Contraindications and Drug Interactions (tannins).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI987', 'H218', 'drug_interaction', 'Oral iron, mineral supplements, and alkaloidal/other oral drugs', 'moderate', 'Tannins chelate iron and divalent minerals and can bind alkaloidal and other drugs in the gut, reducing their absorption when co-administered.', 'Separate the herb from iron, mineral supplements, and oral medications by about two hours; use short courses.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI988', 'H218', 'condition', 'Iron-deficiency anemia', 'moderate', 'Tannin chelation of dietary and supplemental iron can worsen iron-deficiency anemia with prolonged use.', 'Use only short-term in anemic individuals, dose away from iron and meals, and monitor.', 'Herbal Reality, Lady''s Mantle monograph; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI989', 'H218', 'condition', 'Chronic constipation / dry, atrophic tissue states', 'low', 'The binding, drying astringent action can aggravate constipation and further dry withered or fluid-depleted tissue.', 'Avoid in habitual dry constipation and in markedly dry, atrophic constitutions; prefer moistening herbs there.', 'Traditional astringent principle; Mills and Bone, Principles and Practice of Phytotherapy.');
