INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'C02', 'Aggravates', 'Secondary', 'Choleric: heating potency worsens a hot, dry, tense constitution.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'D03', 'Primary', 'Warming, drying, draining; reduces cold, damp, waterlogged Kapha and edema.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'D01', 'Secondary', 'Its warmth and sweet-rasayana base soothe Vata; balance the dry, light guna with unctuous anupana.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
