INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'TCM06', 'Minor', 'Blood deficiency: nourishing, iron-bearing rasayana for the pale, anemic picture.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'TCM07', 'Primary', 'Yin deficiency: warming, drying, water-draining action injures the yin and fluids.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H219', 'TCM11', 'Secondary', 'Heat/Fire: the heating potency aggravates excess heat and fire.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI990', 'H219', 'pregnancy', 'Pregnancy (therapeutic/medicinal doses)', 'moderate', 'Documented uterine and antifertility reputation with an abortifacient record in the ethnobotanical literature; animal studies show dose-dependent disruption of the estrous cycle, reduced ovarian weight, and teratogenic effect at high (not low) doses. No controlled human safety data.', 'Avoid therapeutic (medicinal) root preparations in pregnancy; classical use only under close physician supervision. Incidental culinary leaf is a lesser concern. Edema in pregnancy needs medical evaluation (pre-eclampsia) rather than self-treatment.', 'Frontiers in Pharmacology 2021 (contraceptive/abortifacient review); Ethnomedicinal review PMC10682173; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI991', 'H219', 'breastfeeding', 'Breastfeeding', 'low', 'No reliable modern data on milk transfer or infant effects; diuretic and hypotensive actions warrant care.', 'Use only under qualified supervision at ordinary (not high) doses; the cooked leaf is the gentlest form.', 'Insufficient modern data; precautionary (Brinker, Herbal Contraindications and Drug Interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI992', 'H219', 'drug_interaction', 'Diuretic drugs (furosemide, thiazides, spironolactone)', 'moderate', 'Additive diuresis increases the risk of dehydration and potassium/sodium depletion; punarnava is a genuine diuretic with a notable potassium-salt content.', 'Avoid combining with potent diuretics unless supervised; monitor fluid status and electrolytes; ensure adequate hydration.', 'Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI993', 'H219', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Additive blood-pressure lowering: the root lignan liriodendrin is a calcium-channel antagonist and the plant reduces sympathetic tone, on top of its diuretic effect.', 'Monitor blood pressure when combined with antihypertensives; watch for hypotension and dizziness.', 'Mishra et al., BioMed Research International 2014 (liriodendrin Ca-channel activity); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI994', 'H219', 'drug_interaction', 'Antidiabetic drugs (insulin, metformin, sulfonylureas)', 'low', 'Possible additive blood-sugar lowering from the herb''s mild hypoglycemic action.', 'Monitor blood glucose if therapeutic doses are combined with diabetes medication.', 'Ethnopharmacology reviews (antidiabetic activity); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI995', 'H219', 'drug_interaction', 'Lithium and cardiac glycosides (digoxin)', 'moderate', 'As a diuretic, punarnava may alter renal lithium clearance and change serum lithium levels (theoretical class effect), and diuretic-induced potassium loss could potentiate digoxin toxicity.', 'Monitor serum lithium and serum potassium; avoid unsupervised combination with these narrow-margin drugs.', 'Brinker, Herbal Contraindications and Drug Interactions (diuretic class effects); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI996', 'H219', 'condition', 'Dehydration, hyponatremia/hypokalemia, hypotension', 'moderate', 'The diuretic and hypotensive actions can worsen fluid depletion, low sodium or potassium, and low blood pressure, especially at doses above about 5 g of powder daily.', 'Avoid in clinically dehydrated or electrolyte-depleted or frankly hypotensive patients; keep to lower doses and maintain fluid intake.', 'High-dose electrolyte cautions in the ethnopharmacology literature; Mills and Bone, Principles and Practice of Phytotherapy.');
