INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H219', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. I (Government of India, Ministry of Health and Family Welfare, Dept. of AYUSH), monograph ''Punarnava'' (Boerhavia diffusa Linn., root). Rasa: Madhura, Tikta, Kashaya; Guna: Laghu, Ruksha; Vi", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "locator": "Bhavaprakasha Nighantu (Guduchyadi Varga), Punarnava; Kirtikar and Basu, Indian Medicinal Plants (1918), Boerhavia diffusa; Mishra et al., ''Phytochemical, Therapeutic, and Ethnopharmacological Overview for a Traditionally Important Herb: Bo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H220', 'Stillingia (Queen''s Delight)', 'Stillingia sylvatica', 'Euphorbiaceae', 'Root (dried, recently harvested)', 'Bitter, Pungent (acrid), Astringent', 'Warm', 'Dry', 'Torpor and depression of the lymphatic and depurative functions; laxity and boggy feebleness of glandular tissue, the cold still-water terrain; scrofulous and lymphatic stagnation with tardy removal of broken-down material; chronic low-grade infection of the blood. Classic Eclectic sign: mucous membranes tumid, red, and glistening with scanty secretion.', 'Excess heat and acute inflammation, where the acrid resin further irritates hot, red, angry tissue. Marked dryness or raw irritation of the mucous membranes. Frank ulceration or acute gastroenteritis of the gut, which the emeto-cathartic diterpene esters aggravate.', 'Lymphatic and glandular system; skin (integumentary); liver and depurative organs; respiratory tract (larynx, bronchi); immune system.', 'Chronic skin disease (eczema, psoriasis, moist red irritable eruptions, boils); scrofula and lymphatic or glandular congestion; secondary syphilitic and other chronic blood dyscrasias; chronic laryngitis and irritative winter bronchial cough with a tight chest and scanty secretion; sluggish hepatic and depurative function.', 'Cold-Damp-Relaxed: the boggy, torpid, still-water phenotype with feeble glandular tissue, sluggish elimination, and a scrofulous or tubercular diathesis.', 'Kapha', 'Pitta, Vata', 'Chronic Damp-Phlegm accumulation with scrofulous nodulation (luo li) and boggy lymphatic congestion; sluggish blood-level toxic accumulation with glandular masses. Warming, acrid, and dispersing to move what is stuck and cold.', 'Yin deficiency and Heat or Fire patterns, where the acrid warmth injures fluids and fans heat; Blood deficiency, which the drying, depleting resin worsens.', 'An acrid, irritant root. Large doses produce vertigo, a burning sensation of the mouth and stomach, nausea, vomiting, diarrhea, muscular aching, cough, prostration, and sweating. The fresh root and its expressed oil are strongly emeto-cathartic and too acrid for internal use unless combined with a mucilage. The juice of the green root blisters and inflames the skin. The root''s tigliane and daphnane diterpene esters (Stillingia factors S1 to S8) are protein-kinase-C activators with co-carcinogenic, tumor-promoting potential, so avoid prolonged or high-dose use. Use only small doses of recently dried, well-preserved root; the drug loses much of its virtue with age.', 'Pregnancy and lactation. Acute gastroenteritis or any inflamed, irritable GI state. Acute inflammatory or frankly hot, dry conditions. Known Euphorbiaceae sensitivity. Avoid prolonged internal use because of the co-carcinogenic diterpene esters.', 'Contraindicated. Avoid. The dried root is rated possibly unsafe and the fresh root likely unsafe in pregnancy; the acrid diterpene-ester resin is a powerful mucous-membrane and GI irritant and purgative with potential for reflex uterine irritation. (WebMD/RxList; Drugs.com professional monograph.)', 'Contraindicated. Avoid. Fresh and dried root are rated likely unsafe during breastfeeding; irritant diterpene esters with no lactation safety data. (WebMD/RxList.)', 'Not recommended for self-use. Although 19th-century compound cough syrups included small doses, the irritant, emeto-cathartic diterpene esters and the absence of modern pediatric safety data make it unsuitable for children except under expert professional supervision. (WebMD; Memorial Sloan Kettering.)', 'No well-documented clinical drug interactions (limited data). Theoretical concerns: additive mucous-membrane and GI irritation with other irritant botanicals, NSAIDs, or stimulant laxatives; because the root''s tigliane and daphnane diterpene esters are protein-kinase-C activators with tumor-promoting (co-carcinogenic) potential, avoid concurrent use with immunosuppressive or immunomodulatory therapy and in patients undergoing cancer treatment. (Memorial Sloan Kettering; Drugs.com; AHPA Botanical Safety Handbook, 2nd ed.)', 'Tincture of the recent root and the Eclectic specific medicine; decoction; compound syrup (classically Compound Syrup of Stillingia with sarsaparilla, blue flag, and prickly ash); topical liniment or ointment applied to the chest in bronchial and croupal states. The acrid oil is used externally only, or internally only when incorporated in a mucilage.', 'Eclectic specific Stillingia, 1 to 20 drops (minims); tincture, 0.5 to 1 fluid dram (about 2 to 4 mL); fluid extract, 10 to 60 minims; decoction, 1 to 2 fluid ounces. Modern practice: low doses in short courses, almost always compounded within an alterative formula rather than used alone. Start low; discontinue if burning, nausea, or vertigo appear.', 'King''s American Dispensatory (Felter & Lloyd, 1898): Stillingia.', 'Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Stillingia. Memorial Sloan Kettering Cancer Center, About Herbs: Stillingia. Drugs.com professional monograph: Queen''s Delight. WebMD/RxList: Queen''s Delight. AHPA Botanical Safety Handbook, 2nd ed. (McGuffin et al.). Adolf W, Hecker E, Tetrahedron Letters (1980): irritant diterpene-esters from roots of Stillingia sylvatica.', 'Root of Stillingia sylvatica L., spurge family (Euphorbiaceae), native to sandy pine-barren soils of the southeastern United States. Constituents: acrid resin and acrid fixed oil, volatile oil (about 3 to 4 percent), tannin (about 11 to 12 percent), gum, starch, the reputed principle stillingine, and a series of irritant tigliane and daphnane diterpene esters, the Stillingia factors S1 to S8, which include prostratin and gnidilatidin (Adolf & Hecker, 1980). Notably prostratin itself is a non-tumor-promoting PKC activator investigated for reversing HIV latency, whereas several sister Stillingia esters are irritant co-carcinogens, so the whole-root safety profile is governed by the harsh diterpene fraction. Ellingwood ranked it a front-rank Eclectic alterative for fifty years in syphilis, scrofula, blood taint, tubercular disease, and the cancerous diathesis, with a signature indication of a tight, hoarse, croupal chest lacking secretion. Traditionally paired with lobelia for croup and compounded in the Compound Syrup of Stillingia. Potency declines markedly with storage, so recent root is essential.', 'Not found in Scripture or the classical Mediterranean herbals (Dioscorides, Pliny). A New-World plant of the southeastern United States pine barrens that entered the materia medica through 19th-century Eclectic and Physiomedical practice (King''s American Dispensatory, 1898; Ellingwood, 1919).', 'Stillingia is gathered almost entirely from the wild, the root dug in autumn from southeastern pine-barren soils. It is not currently on the United Plant Savers At-Risk or To-Watch lists, but as a slow-establishing, exclusively wild-collected native it merits caution: prefer verified-sustainable or cultivated sources and avoid casual over-harvest.', 'Warm, dry, acrid stimulating alterative that whips the sluggish lymphatic and depurative fires of a cold, boggy, scrofulous terrain.', 'Refer for medical diagnosis with any undiagnosed or enlarging lymph nodes, persistent or non-healing skin lesions or ulcers, suspected active syphilis or tuberculosis, coughing of blood, unexplained weight loss, or drenching night sweats. These require diagnosis and definitive treatment, not self-medication.', 'Stillingia: stil-IN-jee-uh. Stillingia sylvatica: stil-IN-jee-uh sil-VAT-ih-kuh. Queen''s Delight.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Stillingia.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Stillingia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Stillingia. Memorial Sloan Kettering Cancer Center, About Herbs: Stillingia. Drugs.com professional monograph: Queen''s Delight. WebMD/RxList: Queen''s Delight. AHPA ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Stillingia. Memorial Sloan Kettering Cancer Center, About Herbs: Stillingia. Drugs.com professional monograph: Queen''s Delight. WebMD/RxList: Queen''s Delight. AHPA ", "source_id": "S22", "author": "Ellingwood \u2014 American Materia Medica", "year": "1919", "url": "https://www.henriettes-herb.com/eclectic/ellingwood/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
