INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI997', 'H220', 'pregnancy', 'Pregnancy', 'absolute', 'Acrid diterpene-ester resin is a strong mucous-membrane and GI irritant and purgative with potential for reflex uterine irritation; fresh root rated likely unsafe, dried root possibly unsafe.', 'Do not use during pregnancy.', 'WebMD/RxList (Queen''s Delight); Drugs.com professional monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI998', 'H220', 'breastfeeding', 'Breastfeeding', 'absolute', 'Irritant diterpene esters rated likely unsafe; no lactation safety data.', 'Avoid while breastfeeding.', 'WebMD/RxList (Queen''s Delight).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI999', 'H220', 'pediatric', 'Children', 'moderate', 'Emeto-cathartic irritant diterpene esters; no modern pediatric safety data.', 'Avoid in children except under expert professional supervision.', 'WebMD; Memorial Sloan Kettering About Herbs (Stillingia).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1000', 'H220', 'condition', 'Acute gastroenteritis / GI inflammation', 'moderate', 'Mucous-membrane irritant provokes burning, nausea, vomiting, and diarrhea; worsens an already irritated gut.', 'Avoid in active GI irritation or inflammatory bowel states.', 'WebMD/RxList (Queen''s Delight).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1001', 'H220', 'drug_interaction', 'Immunosuppressants and cancer chemotherapy', 'moderate', 'Tigliane and daphnane diterpene esters are protein-kinase-C activators with co-carcinogenic, tumor-promoting potential.', 'Avoid concurrent use with immunosuppressive/immunomodulatory therapy and in patients undergoing cancer treatment; avoid prolonged or high-dose internal use.', 'Memorial Sloan Kettering About Herbs; Drugs.com; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1002', 'H220', 'other', 'Prolonged or high-dose internal use', 'moderate', 'Cumulative irritant toxicity and co-carcinogenic diterpene esters; fresh root and expressed oil are strongly emeto-cathartic.', 'Use only small doses of recently dried, well-preserved root in short courses; discontinue if burning, vertigo, or nausea occur.', 'Drugs.com professional monograph; Memorial Sloan Kettering About Herbs.');
