INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS09', 'Primary', 'Laxity: firms the slack, relaxed, out-of-tone vein and capillary walls; the keynote.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS08', 'Primary', 'Stagnation: moves the passive venous stasis and pooled, backed-up portal and pelvic blood.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS07', 'Secondary', 'Dampness: drains the boggy, sodden, catarrhal congestion of pelvis and bladder.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS19', 'Secondary', 'Torpor: rouses a sluggish, torpid portal and pelvic circulation.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS03', 'Primary', 'Dryness: a drying astringent parches dry, fluid-poor tissue further.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS18', 'Secondary', 'Tension: a firming tonic tightens the already over-tight, wiry, taut constitution.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS05', 'Secondary', 'Excess heat: the warming, astringent action aggravates hot, flushed states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H221', 'TS06', 'Minor', 'Acute inflammation: wrong for an acutely inflamed, hot, thrombosed pile versus passive congestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H221', 'SY06', 'Primary', 'Cardiovascular (venous side): firms relaxed vein/capillary walls; heart tonic (Ellingwood).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H221', 'SY08', 'Secondary', 'Digestive: rectum and portal circulation; hemorrhoids, pelvic congestion, weak stomach.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H221', 'SY07', 'Secondary', 'Respiratory: the passively congested, relaxed larynx and pharynx of minister''s throat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H221', 'SY09', 'Secondary', 'Urinary: diuretic, stone-clearing use for gravel and bladder catarrh.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H221', 'SY03', 'Minor', 'Reproductive: varicocele and the pelvic and vulvo-vaginal varicosities of pregnancy.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A15', 'Primary', 'Astringent: tannin-rich toning of relaxed vein walls and mucous membranes; checks hemorrhoidal bleeding.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A23', 'Primary', 'Tonic: the defining venous and vascular tonic action, restoring tone to atonic vessels.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A07', 'Secondary', 'Cardiotonic: reputed tonic to a feeble, dilated heart (Ellingwood).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A08', 'Secondary', 'Diuretic: promotes urine flow; used for gravel and bladder catarrh.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A10', 'Secondary', 'Antispasmodic: relieves rectal and laryngeal spasm and vagal irritation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A14', 'Secondary', 'Alterative: classed alterative by King''s; improves congested venous and portal terrain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A16', 'Minor', 'Bitter tonic: tones a weak, atonic stomach and digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A22', 'Minor', 'Sedative: Grieve lists a mild sedative, calming vagal reflex irritation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A18', 'Minor', 'Diaphoretic: a minor traditional diaphoretic action (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H221', 'A50', 'Minor', 'Styptic/hemostatic: astringent checking of bleeding piles and passive hemorrhage.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP61', 'Primary', 'Hemorrhoids: the headline Eclectic use; congested, bleeding, weight-and-fullness piles.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP48', 'Primary', 'Varicose veins / venous stasis: ''most reliable remedy in varicosis'' (Ellingwood), incl. varicocele.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP47', 'Secondary', 'Poor peripheral circulation: dusky, blue, poorly returning venous blood of slack capillaries.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP52', 'Secondary', 'Sore throat / minister''s throat: chronic laryngitis, pharyngitis, hoarseness, aphonia from laryngeal congestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP64', 'Secondary', 'Urinary stones / gravel: its lithic, diuretic use, whence the name stone root.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP65', 'Minor', 'Urinary irritation: catarrh of the bladder and irritable, congested urinary complaints.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP58', 'Minor', 'Dyspepsia / atonic indigestion: tonic to a weak, torpid stomach and portal circulation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H221', 'CP55', 'Minor', 'Constipation: the constipated, engorged pelvic state of vascular congestion (King''s).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P01', 'Primary', 'Fresh-root tincture / specific collinsonia, the preferred Eclectic form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P03', 'Secondary', 'Dried-root powder (also capsuled).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P02', 'Secondary', 'Capsule of the dried-root powder, the common modern form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P05', 'Minor', 'Short, gentle infusion of the dried root (avoid a hard, prolonged boil).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P04', 'Minor', 'Decoction of the fresh root (Grieve), with the caveat that boiling degrades activity (King''s).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H221', 'P07', 'Minor', 'Topical/ointment application, often with witch hazel, for piles.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H221', 'C04', 'Indicated', 'Primary', 'Phlegmatic (cold-damp-relaxed): firms and drains the boggy, still-water, venous-congestion type.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "locator": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
