INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H221', 'TCM10', 'Secondary', 'Dampness/Phlegm (cold): boggy, catarrhal congestion of bladder and pelvis, drained by its diuresis.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "locator": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H221', 'TCM07', 'Primary', 'Yin deficiency: warming, drying, astringent action injures yin and fluids.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "locator": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H221', 'TCM11', 'Secondary', 'Heat/Fire: the warming, astringent action aggravates heat or locks it in.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Collinsonia (Stone-root). Actions given as alterative, tonic, stimulant, and diuretic, acting principally on the venous system and mucous tissues; specific for passive vascular engorge", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "locator": "Ellingwood, The American Materia Medica, Therapeutics and Pharmacognosy (1919) - Collinsonia (a specific remedy for hemorrhoids and ''my most reliable remedy in the treatment of varicosis''; heart tonic; clergyman''s sore throat). Grieve, A Mo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1003', 'H221', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient modern human safety data; the root is high in tannins and mildly diuretic. A traditional Eclectic use for pregnancy varicosities exists (Ellingwood), but no controlled safety data support it.', 'Avoid medicinal doses in pregnancy as a precaution; pregnancy-related varicosities and hemorrhoids should be evaluated by a clinician rather than self-treated.', 'WebMD/NMCD Stone Root monograph (avoid in pregnancy, insufficient data); Ellingwood, American Materia Medica (traditional pregnancy use, context).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1004', 'H221', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable modern data on transfer into milk or effects on the nursing infant.', 'Avoid medicinal doses while breastfeeding unless directed by a qualified practitioner.', 'WebMD/NMCD Stone Root monograph (avoid, insufficient data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1005', 'H221', 'drug_interaction', 'Iron and mineral supplements; alkaloidal/protein-based drugs', 'moderate', 'High tannin content can bind and reduce the absorption of iron and other minerals and of some drugs taken at the same time.', 'Separate stone root from iron, mineral supplements, and medications by at least two hours; use cautiously in iron-deficiency anemia.', 'Brinker, Herbal Contraindications and Drug Interactions (tannin interactions); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1006', 'H221', 'drug_interaction', 'Diuretic drugs and lithium', 'moderate', 'The herb''s diuretic action may be additive with diuretic drugs (increasing fluid/electrolyte loss) and, as a diuretic class effect, may alter renal lithium clearance and serum lithium levels.', 'Use cautiously with diuretics; monitor fluid status and, where lithium is co-prescribed, monitor serum lithium.', 'Brinker, Herbal Contraindications and Drug Interactions (diuretic class effects); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1007', 'H221', 'drug_interaction', 'Antihypertensive and cardiac medication', 'low', 'A traditional mild heart-tonic and circulatory action raises a theoretical additivity with blood-pressure or cardiac drugs; not well quantified.', 'Monitor blood pressure and cardiac status if combined; introduce cautiously.', 'Ellingwood, American Materia Medica (heart-tonic action); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1008', 'H221', 'condition', 'Kidney disease, dehydration, electrolyte depletion', 'moderate', 'The diuretic action can worsen fluid and electrolyte loss and burden compromised kidneys, especially at high or prolonged doses.', 'Avoid high or prolonged dosing in significant kidney disease or dehydration; keep to ordinary doses and maintain hydration.', 'WebMD/NMCD Stone Root monograph (diuretic cautions); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1009', 'H221', 'condition', 'Unexplained or heavily bleeding / thrombosed hemorrhoids and rectal bleeding', 'moderate', 'Rectal bleeding and acute thrombosed piles may signal serious pathology (including colorectal disease) that self-treatment can delay.', 'Do not self-treat unexplained rectal bleeding, a change in bowel habit, or thrombosed/strangulated piles; refer for evaluation.', 'General clinical safety (refer threshold); standard herbal practice.');
