INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H222', 'TCM08', 'Primary', 'Qi Stagnation: a strong binder worsens stagnation and, given too early, can retain a pathogen that should be expelled.', '{"title": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "locator": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "locator": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H222', 'TCM09', 'Secondary', 'Blood Stasis: further astringing and consolidating can worsen the stasis.', '{"title": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "locator": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "locator": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1010', 'H222', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient modern human safety data. No controlled pregnancy studies exist; the rhizome carries a very high tannin load.', 'Avoid medicinal doses (concentrated decoctions, tinctures, extracts) in pregnancy as a precaution; use only under qualified supervision if at all.', 'WebMD/NMCD Tormentil monograph (not enough reliable information; avoid use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1011', 'H222', 'breastfeeding', 'Breastfeeding', 'low', 'No data on excretion into breast milk; tannins are poorly absorbed and the herb is low in toxicity, but reliable human data are lacking. Sources differ on the level of caution.', 'Avoid large or prolonged medicinal doses while nursing; if used, favor short courses at ordinary doses, ideally with professional guidance.', 'e-lactancia.org Tormentil (low risk, likely compatible in moderation); WebMD/NMCD Tormentil monograph (avoid, insufficient data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1012', 'H222', 'drug_interaction', 'Iron and mineral supplements; alkaloidal or protein-based oral drugs', 'moderate', 'Very high tannin content binds iron and other minerals and can bind alkaloidal or protein-based drugs in the gut, reducing their absorption.', 'Separate tormentil from iron, mineral supplements, and oral medications by at least two hours; use cautiously in iron-deficiency anemia.', 'Brinker, Herbal Contraindications and Drug Interactions (tannin interactions); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1013', 'H222', 'drug_interaction', 'Insulin and oral antidiabetic drugs', 'low', 'A reported blood-sugar-lowering tendency raises a theoretical additive hypoglycemic effect when combined with glucose-lowering medication. Direct clinical data are limited.', 'Monitor blood glucose if combined with antidiabetic therapy; watch for symptoms of low blood sugar.', 'WebMD/NMCD Tormentil monograph (blood-sugar note); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1014', 'H222', 'condition', 'Chronic constipation and dry, atrophic bowel states', 'moderate', 'A powerful astringent tightens and dries the bowel, worsening constipation and parching already dry, atrophic mucosa.', 'Avoid in chronic constipation and dry, atrophic gut states; discontinue if it binds the bowel.', 'Mills and Bone, Principles and Practice of Phytotherapy (astringent cautions); ESCOP Tormentillae rhizoma.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1015', 'H222', 'condition', 'Bloody diarrhea with fever, dehydration, or diarrhea in infants and the frail', 'moderate', 'Bloody, febrile, or dehydrating diarrhea, and diarrhea in infants, the elderly, or the immunocompromised, may signal serious infection or disease that astringent self-treatment can mask or delay.', 'Do not self-treat; prioritize oral rehydration and clinical assessment and refer promptly (see refer threshold).', 'General clinical safety (refer threshold); WebMD/NMCD Tormentil monograph.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H222', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "locator": "Grieve, A Modern Herbal (1931) - Tormentil (Potentilla tormentilla / erecta). Given as one of the most powerful of the astringent, tannin-rich herbs; the decoction of the rhizome used for diarrhea, dysentery, and as a lotion, gargle, and wa", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "locator": "ESCOP Monographs, Tormentillae rhizoma (Tormentil rhizome) - astringent indications for acute non-specific diarrhea and, topically, for inflammations of the mouth and throat and minor skin inflammations. Culpeper, The Complete Herbal (1653)", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "pubmed"}'::jsonb, true);
