INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H223', 'TCM10', 'Primary', 'Dampness/Phlegm (damp-heat): clears and checks the hot, damp, mucoid/bloody dysenteric flux of the Large Intestine, akin to Bai Tou Weng.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "locator": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "locator": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H223', 'TCM11', 'Primary', 'Heat/Fire (toxin in the bowel): heat-clearing, toxin-resolving, astringent action on infective, inflamed colitis.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "locator": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "locator": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H223', 'TCM03', 'Primary', 'Spleen Qi Def: a cold, bitter, drying herb injures spleen yang in cold, deficiency-cold, watery diarrhea.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "locator": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "locator": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H223', 'TCM07', 'Secondary', 'Yin Def: the drying, astringent action further injures fluids in a dry, depleted patient.', '{"title": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "locator": "Ayurvedic Pharmacopoeia of India, Part I - Kutaja (Holarrhena antidysenterica); bark and seed classed as Sangrahika (bowel-firming) and Krimighna (antiparasitic), the premier Ayurvedic remedy for Atisara (diarrhea) and Pravahika (dysentery)", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "locator": "Metabolic Diversity and Therapeutic Potential of Holarrhena pubescens: An Important Ethnomedicinal Plant (review, PMC7565871, 2020) - phytochemistry (steroidal alkaloids, conessine) and antidysenteric, antidiarrheal, antimicrobial, anthelmi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1016', 'H223', 'pregnancy', 'Pregnancy', 'moderate', 'No modern controlled human safety or teratogenicity data. The bark and seed contain potent steroidal alkaloids (conessine and congeners), and conessine has documented CNS activity (a CNS-depressant, sedative histamine H3 antagonist with slow CNS clearance and adrenergic affinity). Long traditional Ayurvedic use in pregnancy exists but is not a modern safety clearance.', 'Avoid medicinal or high (especially seed-alkaloid) doses in pregnancy unless supervised by a qualified practitioner. Dysentery or persistent diarrhea in pregnancy should be medically assessed because of the dehydration risk.', 'Absence of modern controlled pregnancy data (NCCIH general guidance for herbs lacking reliable pregnancy information); conessine pharmacology (Zhang et al., Journal of Medicinal Chemistry, 2008).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1017', 'H223', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on transfer of Holarrhena''s steroidal alkaloids into breast milk or on effects in the nursing infant.', 'Avoid medicinal or concentrated seed-alkaloid doses while breastfeeding unless directed by a qualified practitioner.', 'Absence of modern lactation data; Mills and Bone, Principles and Practice of Phytotherapy (precautionary reasoning for alkaloid-bearing herbs).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1018', 'H223', 'drug_interaction', 'CNS depressants, sedatives, antihistamine/adrenergic and antihypertensive drugs', 'moderate', 'The principal alkaloid conessine is a CNS-depressant, sedative, potent histamine H3 receptor antagonist with adrenergic-receptor affinity, raising a theoretical concern for additive central effects and for interaction with centrally acting and adrenergic medications. Direct human interaction data are limited.', 'Use caution and monitor for additive sedation or central effects when combined with CNS depressants, sedatives, or adrenergic/antihypertensive drugs, particularly with concentrated seed-alkaloid preparations.', 'Conessine pharmacology (Zhang et al., Journal of Medicinal Chemistry, 2008); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1019', 'H223', 'drug_interaction', 'Antidiabetic (hypoglycemic) drugs', 'moderate', 'Holarrhena extracts show hypoglycemic/antidiabetic activity, which may be additive with blood-glucose-lowering medication.', 'Monitor blood glucose and adjust antidiabetic therapy as needed if used alongside insulin or oral hypoglycemics.', 'Holarrhena antidysenterica antidiabetic evidence (longitudinal meta-analysis, 2021); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1020', 'H223', 'drug_interaction', 'Iron/mineral supplements and alkaloidal drugs', 'low', 'The tannin content can bind and reduce the absorption of iron and other minerals and of alkaloidal drugs taken at the same time.', 'Separate Kutaj from iron, mineral supplements, and alkaloidal medications by at least two hours.', 'Brinker, Herbal Contraindications and Drug Interactions (tannin interactions).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1021', 'H223', 'condition', 'Cold, deficiency-cold / atonic diarrhea without heat', 'moderate', 'A cool, bitter, drying, astringent herb is energetically wrong for cold, deficient, watery diarrhea and can deepen the cold, dryness, and debility.', 'Reserve for damp-heat and infective dysentery; avoid in cold-deficiency (Spleen/Kidney yang deficient, Vata-depleted) diarrhea.', 'Traditional energetic contraindication (Ayurveda Sheeta/Ruksha virya; TCM damp-heat mapping).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1022', 'H223', 'condition', 'Severe/invasive dysentery, dehydration, high fever, suspected amoebic liver abscess', 'moderate', 'Self-treatment of invasive amoebiasis or severe dysentery risks progression (fulminant colitis, extraintestinal or liver abscess) and dehydration, especially in children, the elderly, and pregnancy.', 'Refer for medical diagnosis, rehydration, and conventional antiparasitic or antibiotic treatment where indicated; do not rely on self-treatment.', 'General clinical safety (NCCIH; standard herbal and medical practice).');
