INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H224', 'TCM11', 'Primary', 'Heat/Fire: contraindicated in damp-heat or acute heat diarrhea/dysentery; warming binding locks heat in.', '{"title": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "locator": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H224', 'TCM07', 'Secondary', 'Yin deficiency: a warming, drying aromatic further injures fluids and yin.', '{"title": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "locator": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1023', 'H224', 'pregnancy', 'Pregnancy (medicinal or large doses)', 'absolute', 'Traditional emmenagogue and reputed abortifacient; the psychoactive constituent myristicin crosses the placenta. Modern safety references classify the seed as not for use during pregnancy.', 'Avoid all medicinal and large doses throughout pregnancy; ordinary culinary amounts in food are generally regarded as acceptable. Assess pregnancy-related digestive complaints clinically rather than self-treating with medicinal nutmeg.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013), Myristica fragrans seed, not for use during pregnancy; corroborated by myristicin toxicology reviews (IJASEIT 5(3), 2015).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1024', 'H224', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'Insufficient modern data on transfer of myristicin into breast milk or effects on the nursing infant.', 'Avoid medicinal doses while breastfeeding unless directed by a qualified practitioner; culinary amounts in food are generally acceptable.', 'AHPA Botanical Safety Handbook, 2nd ed.; general modern lactation-herb consensus (precautionary avoidance at medicinal doses).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1025', 'H224', 'other', 'High-dose nutmeg (about 5 g or more; roughly one to two whole nutmegs)', 'absolute', 'Myristicin and elemicin at gram-scale doses cause a deliriant, sympathomimetic, anticholinergic-type intoxication: nausea, flushing, dry mouth, tachycardia, agitation, anxiety, hallucinations, and delirium, with a prolonged 24 to 48 hour course; hepatorenal stress and rare fatalities are reported.', 'Never exceed small medicinal doses (keep well under 1 g; hard ceiling well below 5 g). Do not use recreationally. Treat suspected overdose as a medical emergency and contact poison control or emergency care.', 'Toxicity of Nutmeg (Myristicin): A Review, IJASEIT 5(3), 2015; poison-center case reports; Grieve, A Modern Herbal (1931), overdose warning.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1026', 'H224', 'drug_interaction', 'MAO inhibitors and serotonergic/psychoactive drugs (SSRIs, SNRIs, TCAs, other serotonergic or stimulant agents)', 'moderate', 'Myristicin is a weak MAO inhibitor and is metabolized to amphetamine-like, sympathomimetic, and serotonergic compounds, raising the risk of additive or serotonergic-excess effects when combined with MAOIs or serotonergic drugs.', 'Avoid more than culinary amounts of nutmeg in anyone taking MAO inhibitors, serotonergic antidepressants, or other psychoactive/stimulant medication.', 'AHPA Botanical Safety Handbook, 2nd ed. (MAO activity/interaction potential); Brinker, Herbal Contraindications and Drug Interactions; myristicin pharmacology reviews.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1027', 'H224', 'drug_interaction', 'CNS depressants, sedatives, hypnotics, benzodiazepines, and alcohol', 'moderate', 'The sedative volatile oil may be additive with other CNS depressants, increasing drowsiness and sedation.', 'Use cautiously and avoid larger doses alongside sedating drugs or alcohol; do not combine for stronger sedative effect.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1028', 'H224', 'condition', 'Psychiatric illness, seizure disorder, and significant hepatic or renal disease', 'moderate', 'The psychoactive, deliriant, and sympathomimetic potential of myristicin can destabilize psychiatric and seizure conditions; high or repeated intake stresses the liver and kidneys.', 'Avoid medicinal nutmeg in psychiatric illness, seizure disorders, and hepatic or renal disease; keep to culinary amounts only.', 'Myristicin toxicology reviews; NCCIH; clinical-herb references (Mills and Bone).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1029', 'H224', 'condition', 'Acute, hot, or infective diarrhea and dysentery (fever, blood, or mucus)', 'moderate', 'A warming, binding, astringent spice is unsuited to a damp-heat or infective bowel, where binding and warming can lock pathogenic heat in and delay needed evaluation.', 'Do not self-treat hot, feverish, or bloody diarrhea with nutmeg; refer for assessment. Reserve nutmeg for cold, atonic, chronic loose stool.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou contraindicated in heat-type diarrhea); general clinical practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1030', 'H224', 'population', 'Young children (medicinal doses)', 'moderate', 'The narrow therapeutic margin and documented severity of pediatric nutmeg poisoning make medicinal dosing hazardous in children.', 'Do not give medicinal doses to young children; culinary amounts only, with any therapeutic use under qualified supervision at reduced, weight-appropriate doses. Keep concentrated oil and gram-scale amounts out of reach.', 'Pediatric myristicin poisoning case reports; AHPA Botanical Safety Handbook, 2nd ed.');
