INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H224', 'EP08', 'match', 2, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "locator": "Grieve, A Modern Herbal (1931), Nutmeg (Myristica fragrans): aromatic, stimulant, carminative, and, in large doses, narcotic and toxic; used for flatulence, to check diarrhea, and as a stomachic, with explicit warning of the dangers of over", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (Rou Dou Kou, binds the intestines and warms the middle to stop chronic cold diarrhea; contraindicated in heat/damp-heat diarrhea). Classical Ayurvedic materia medica (Jatip", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H225', 'Damiana', 'Turnera diffusa', 'Passifloraceae (the passionflower family; under the APG classification the genus Turnera is placed in Passifloraceae, having formerly been given its own family, Turneraceae).', 'Leaf (the dried aromatic leaf, sometimes with small flowering stems). King''s American Dispensatory lists Damiana as the leaves of Turnera; the leaf is gathered while the plant is in flower.', 'Bitter and Pungent (aromatic, faintly spicy), with a light Astringency. The fig-scented leaf is aromatic and warming on the tongue, bitter beneath, with a mild tannin pucker.', 'Warm. Damiana is a warming, stimulating aromatic; the Eclectics and modern energetic herbalists class it as a heating remedy that rouses cold, sluggish, depleted states.', 'Dry. The aromatic volatile oil, the bitterness, and the tannins give a drying, dispersing quality that stirs cold, boggy torpor rather than lubricating.', 'Atony and laxity of the reproductive and nervous tissues: the cold, depleted, atonic reproductive system with low libido and functional impotence, and the exhausted, flagging nervous system. Depression of vital tone: atonic melancholy and low mood with coldness and torpor, the flat, spent, joyless depletion that a warm stimulating tonic lifts. Exhaustion and debility from overwork, convalescence, or nervous depletion. Coldness and torpor of the digestive and reproductive organs that an aromatic bitter warms and rouses.', 'Excess heat and irritation: a warming stimulant aggravates hot, inflamed, or feverish states and heat in the reproductive or urinary tract. Excitation and over-stimulation: the wired, agitated, insomniac, or anxious-hot picture, where a stimulating nervine tips into restlessness and sleeplessness. Acute inflammation. Frank dryness, where a drying aromatic deepens parched, thin tissue unless paired with a moistening herb. Tense, constricted, high-strung heat rather than cold depletion.', 'Reproductive, above all: the classic aphrodisiac and reproductive restorative for cold, depleted sexual function in both sexes. Nervous, as a stimulating restorative nervine and mild antidepressant (thymoleptic) for nervous exhaustion, atonic depression, and debility. Urinary, secondarily, as a mild antiseptic diuretic (its arbutin content) for the irritable or catarrhal lower urinary tract. Digestive, as an aromatic bitter that warms the stomach and eases atonic, sluggish digestion and constipation. Endocrine, in a minor way, through its traditional reputation as a reproductive and hormonal tonic.', 'Low libido and sexual debility, the headline traditional use: cold, depleted, or performance-anxious loss of desire and function in both men and women, and functional impotence. Nervous exhaustion, atonic mild depression, low mood with fatigue, and general debility, especially where sexual depletion and nervous exhaustion travel together. Anxiety with nervous depletion (used cautiously, as it is stimulating). Convalescent and overworked debility. Atonic, sluggish digestion and mild constipation. Mild catarrhal or irritable urinary complaints. Traditionally also for cold, painful, or scanty menstruation (dysmenorrhea, atonic amenorrhea). Some traditional use as a supportive tonic in functional infertility from reproductive coldness and depletion.', 'Cold-Dry-Depleted and Cold-Damp-Sluggish: the cold, flat, spent phenotype whose reproductive and nervous fire has gone out, with low libido, atonic depression, and exhaustion, warmed and rekindled by a heating, stimulating, aromatic tonic. Well suited to the phlegmatic and the cold, depleted (Vata-like) type; poorly suited to the hot, robust, irritable choleric, whose heat and excitation it inflames.', 'Kapha, Vata', 'Pitta', 'Read through a Chinese-medicine lens (Turnera diffusa is a New World, not a classical Chinese, herb), it behaves as a warm, acrid-aromatic yang-warming and qi-moving tonic: it warms and rouses Kidney yang for cold impotence and low libido, moves stagnant qi to lift a flat, constrained mood, and gently tonifies depleted qi in nervous exhaustion. Its energetic center is the warming and rousing of a cold, depleted, torpid lower burner rather than any single documented classical zang-fu action.', 'Heat and Fire patterns, which a warming acrid stimulant aggravates (yang excess, ministerial fire blazing, damp-heat in the lower burner). Yin deficiency with empty heat, night sweats, and insomnia, which a warm, drying, stimulating herb worsens. Any hot, agitated, or fluid-depleted presentation rather than cold depletion.', 'Damiana is stimulating and can cause insomnia, restlessness, or a mild caffeine-like over-stimulation if taken late in the day or in large amounts, and it is best avoided in hot, agitated, anxious-wired, or insomniac states. It has mild blood-sugar-lowering activity, so people with diabetes or hypoglycemia and those on glucose-lowering drugs should monitor their blood sugar. The leaf contains small amounts of a cyanogenic glycoside and of arbutin (a hydroquinone precursor), so ordinary tea and tincture doses are considered safe but large or prolonged high doses should be avoided: rare case reports describe convulsions and strychnine-like paroxysms after roughly 200 grams (about 8 ounces) of concentrated extract. Being drying, it is best paired with a moistening herb in dry constitutions. It has a traditional reputation as an emmenagogue and abortifacient and must be avoided in pregnancy.', 'Pregnancy (traditional emmenagogue and abortifacient; avoid). Hot, feverish, acutely inflamed, or strongly agitated and insomniac states, which its warming stimulation aggravates. Diabetes and hypoglycemia without blood-sugar monitoring, given its glucose-lowering activity. Avoid large or prolonged high doses (cyanogenic glycoside and arbutin content). Known hypersensitivity. Reserve any use in dry, depleted, over-heated constitutions to careful, moistening-paired dosing.', 'Avoid in pregnancy. Damiana carries a long traditional reputation as an emmenagogue and abortifacient, its effects on the female hormonal system and the pregnant uterus are uncharacterized, and there are no adequate controlled human safety data. Modern safety references therefore place it among herbs to avoid during pregnancy. (AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions.)', 'Insufficient data; avoid. There are no controlled studies of Turnera diffusa during lactation, it is not known whether its constituents pass into breast milk, and infant safety is uncharacterized; prefer better-studied alternatives. (AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, The Essential Guide to Herbal Safety; NCCIH consumer guidance on unstudied botanicals in lactation.)', 'Not established for internal use in infants and children; no pediatric safety data exist, and the stimulating action plus the cyanogenic-glycoside and arbutin content make it inappropriate for young children. Keep out of reach of children. (AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, The Essential Guide to Herbal Safety.)', 'Antidiabetic drugs and insulin: Damiana has documented blood-sugar-lowering activity, so combining it with insulin or oral hypoglycemics (for example glyburide, glipizide, glimepiride, metformin) can affect glycemic control; monitor blood glucose and adjust medication under supervision. Because of this glucose effect, stop damiana about two weeks before scheduled surgery. Tannin-mediated: the astringent tannins may bind and reduce absorption of iron, other minerals, and some alkaloidal drugs if taken together, so separate dosing by about two hours. No severe, well-documented interactions are otherwise established (limited data); theoretical additive effects with other CNS stimulants or sedatives are precautionary. (Brinker, Herbal Contraindications and Drug Interactions, on hypoglycemic and tannin-containing herbs; Medscape and RxList damiana drug-interaction monographs; consumer-safety monographs on the surgery/blood-sugar precaution.)', 'Infusion (tea) of the dried leaf, the classic and most common form, often blended with other nervines or aromatics. Tincture of the dried leaf. Capsule or powder of the dried leaf. Traditional damiana liqueur, cordial, or elixir (the leaf steeped in sweetened spirit), the old Mexican preparation. Historically the leaf was also smoked as a mild relaxant, a use not recommended here.', 'Dried leaf infusion: about 2 to 4 g (roughly 1 to 2 teaspoons) of dried leaf per cup of water, steeped 10 to 15 minutes, up to three times daily; take earlier in the day to avoid sleep disturbance. Tincture (1:5, 40 to 60 percent alcohol): 2 to 5 mL up to three times daily. Fluid extract (1:1): 2 to 4 mL up to three times daily. Do not exceed recommended doses; avoid large or prolonged high-dose concentrated extracts.', 'King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ellingwood''s American Materia Medica, Therapeutics and Pharmacognosy (1919), Damiana, listing its use as a nerve tonic and reputed aphrodisiac in sexual and nervous debility.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnobotany, phytochemistry and bioactivity of the genus Turnera, Journal of Ethnopharmacology (2014); Kumar, Madaan and Sharma, review of Turnera; Drugs.com, Medscape, and RxList damiana clinical monographs.', 'Family Passifloraceae (formerly Turneraceae); Turnera diffusa is a small aromatic subshrub of southern Texas, Mexico, Central and South America, and the Caribbean, long used in Mexican folk medicine and adopted into nineteenth-century Eclectic American practice. Reported constituents include a volatile oil (roughly 0.5 to 1 percent, with 1,8-cineole, alpha- and beta-pinene, p-cymene, thymol, and other terpenes), flavonoids (including apigenin and its glycosides, which have benzodiazepine-receptor and anxiolytic activity in animal models), the bitter principle damianin, arbutin, tannins (around 3 to 4 percent), a cyanogenic glycoside (tetraphyllin B / deidaclin), beta-sitosterol, resins, and gums. Modern pharmacology reports aphrodisiac (pro-sexual), antidepressant-like, anxiolytic, hypoglycemic, aromatase-inhibiting, gastroprotective, and antioxidant activity in animal and in vitro studies; robust human clinical trials are lacking, and its reputation rests mainly on traditional use. A specialist reproductive and nervous-system herb with real pregnancy, blood-sugar, and high-dose cautions, hence the Paid tier.', 'Not named in the canonical biblical texts. Turnera diffusa is a New World plant native to the Americas (southern Texas through Mexico, Central and South America, and the Caribbean) with no Old World or Mediterranean pedigree; its documented tradition is Mesoamerican and Mexican folk medicine (the name ''damiana'' is of Spanish colonial origin), later adopted and recorded by the nineteenth-century Eclectic and Physiomedical physicians of North America.', 'Turnera diffusa is not currently listed as at-risk or endangered by United Plant Savers; it is a common subshrub across its range. It is, however, harvested largely from the wild in Mexico to supply the aphrodisiac, tea, and liqueur trade, so prefer cultivated or verifiably responsibly wild-harvested leaf, gather the leaf without uprooting the plant, and buy from suppliers who document sustainable sourcing.', 'Warm and dry, stimulating: an aromatic bitter nervine and reproductive tonic that warms cold, spent depletion, lifts atonic depression, and rekindles low libido and nervous exhaustion.', 'Refer persistent erectile dysfunction or loss of libido for medical evaluation, since it can signal cardiovascular disease, diabetes, low testosterone, or depression needing diagnosis. Refer depression that is severe, worsening, or accompanied by any thoughts of self-harm for prompt professional care. Refer anyone with diabetes on glucose-lowering medication before use (blood-sugar interaction), any pregnancy (do not use), infertility for workup, and any seizure disorder. Refer if high doses provoke agitation, insomnia, tremor, or convulsions, and refer blood in the urine, fever, or flank pain suggesting urinary infection.', 'Damiana: dam-ee-AH-nah. Turnera diffusa: tur-NAIR-uh dif-YOO-suh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H225', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H225', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H225', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS11', 'Primary', 'Depression: atonic melancholy and low, flat mood with coldness that a warm stimulating tonic lifts.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS17', 'Primary', 'Cold: cold, depleted reproductive and nervous states warmed and roused by a heating aromatic.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS04', 'Secondary', 'Exhaustion: nervous and sexual exhaustion, debility from overwork or convalescence.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS09', 'Secondary', 'Laxity/atony: the atonic, flagging reproductive system with low libido and functional impotence.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS19', 'Minor', 'Torpor: sluggish, cold digestive and reproductive organs roused by the aromatic bitter.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS05', 'Primary', 'Excess heat: a warming stimulant aggravates hot, feverish, inflamed states and reproductive/urinary heat.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS10', 'Secondary', 'Excitation: the wired, agitated, insomniac picture tipped further by a stimulating nervine.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS06', 'Secondary', 'Acute inflammation: warming stimulation is wrong for acutely inflamed tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS18', 'Minor', 'Tension: high-strung, tense heat rather than the cold depletion it suits.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H225', 'TS03', 'Minor', 'Dryness: a drying aromatic deepens parched, thin tissue unless moistening-paired.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H225', 'SY03', 'Primary', 'Reproductive: the classic aphrodisiac and restorative for cold, depleted sexual function.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H225', 'SY01', 'Primary', 'Nervous: stimulating restorative nervine and mild antidepressant for nervous exhaustion and atonic depression.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H225', 'SY09', 'Secondary', 'Urinary: mild antiseptic diuretic (arbutin) for the irritable or catarrhal lower urinary tract.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H225', 'SY08', 'Secondary', 'Digestive: aromatic bitter warming atonic, sluggish digestion and mild constipation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H225', 'SY02', 'Minor', 'Endocrine: traditional reproductive and hormonal tonic reputation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A02', 'Primary', 'Nervine tonic: restores the exhausted, depleted nervous system.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A23', 'Primary', 'Tonic: warming, stimulating general and reproductive tonic to cold depletion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A40', 'Secondary', 'Trophorestorative: restores depleted reproductive and nervous tissue over time.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A26', 'Secondary', 'Anxiolytic: apigenin content binds benzodiazepine receptors; eases nervous anxiety with depletion (used cautiously, as the herb is stimulating).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A16', 'Secondary', 'Bitter tonic: aromatic bitter that warms and stimulates atonic digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A36', 'Secondary', 'Hypoglycemic: documented blood-sugar-lowering activity (basis of the antidiabetic-drug caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A08', 'Minor', 'Diuretic: mild diuretic action on the urinary tract.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A38', 'Minor', 'Laxative: mild aperient for atonic, sluggish bowels (noted in King''s).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A28', 'Minor', 'Antimicrobial: arbutin gives a mild urinary antiseptic action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A17', 'Minor', 'Carminative: the aromatic volatile oil eases gas and settles the stomach.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A19', 'Minor', 'Emmenagogue: traditional promotion of scanty, cold menses (basis of the pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H225', 'A25', 'Minor', 'Antioxidant: flavonoid free-radical scavenging in vitro.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP05', 'Primary', 'Low libido: the headline aphrodisiac indication; also proxies functional impotence and sexual debility in both sexes.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP11', 'Primary', 'Depression: atonic, cold, low mood lifted by the warming thymoleptic nervine.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP21', 'Primary', 'Nervous exhaustion: restorative nervine for the spent, depleted nervous system.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP03', 'Secondary', 'Debility: general warming tonic to the exhausted and convalescent.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP07', 'Secondary', 'Fatigue: stimulating tonic for low, cold, flagging energy.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP10', 'Secondary', 'Anxiety: nervous anxiety with depletion (apigenin), used cautiously given the stimulating action.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP36', 'Secondary', 'Functional infertility: traditional reproductive tonic for coldness and depletion (not in pregnancy).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP55', 'Minor', 'Constipation: mild aperient for atonic, sluggish bowels.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP58', 'Minor', 'Dyspepsia/low digestive fire: aromatic bitter warming sluggish digestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP63', 'Minor', 'UTI (uncomplicated): mild arbutin urinary antiseptic for catarrhal or irritable bladder.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP29', 'Minor', 'Dysmenorrhea: warming antispasmodic for cold, painful menses.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP30', 'Minor', 'Amenorrhea: emmenagogue for scanty, cold, atonic menses (not in pregnancy).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP27', 'Minor', 'Blood sugar dysregulation: documented hypoglycemic activity (also the basis of the antidiabetic-drug caution).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H225', 'CP24', 'Minor', 'Mental fog/cognitive dullness: stimulating cerebral lift in the dullness of cold depression.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H225', 'P05', 'Primary', 'Infusion (tea) of the dried leaf, the classic form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H225', 'P01', 'Primary', 'Tincture of the dried leaf.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H225', 'P02', 'Secondary', 'Capsule of the dried leaf.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H225', 'P03', 'Minor', 'Powder of the dried leaf.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H225', 'P14', 'Minor', 'Elixir/liqueur: the traditional Mexican sweetened-spirit damiana cordial.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H225', 'C04', 'Indicated', 'Primary', 'Phlegmatic: the cold, damp, sluggish, low-libido, low-mood type warmed and roused by a heating stimulant tonic.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H225', 'C05', 'Indicated', 'Secondary', 'Thin/Cold/Depleted (Vata-like): warms cold, spent reproductive and nervous depletion; pair with a moistening herb to offset its dryness.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
