INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H225', 'TCM07', 'Primary', 'Yin deficiency: warm, drying, stimulating action injures fluids and worsens empty-heat, night sweats, and insomnia.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1031', 'H225', 'pregnancy', 'Pregnancy', 'absolute', 'Long traditional use as an emmenagogue and abortifacient; effects on the female hormonal system and pregnant uterus are uncharacterized and there are no adequate human safety data.', 'Avoid entirely in pregnancy; do not self-prescribe.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1032', 'H225', 'breastfeeding', 'Breastfeeding', 'moderate', 'No controlled lactation-safety data; excretion into breast milk and infant effects are uncharacterized.', 'Avoid, or use only briefly under qualified guidance; prefer better-studied alternatives.', 'AHPA Botanical Safety Handbook, 2nd ed.; Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1033', 'H225', 'drug_interaction', 'Antidiabetic drugs and insulin (for example glyburide, glipizide, glimepiride, metformin)', 'moderate', 'Damiana has documented blood-sugar-lowering activity that can add to glucose-lowering drugs and disturb glycemic control.', 'Monitor blood glucose and adjust medication under supervision; stop damiana about two weeks before scheduled surgery.', 'Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic herbs); Medscape and RxList damiana interaction monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1034', 'H225', 'condition', 'Diabetes and hypoglycemia', 'moderate', 'Glucose-lowering activity can push susceptible people, especially those already on glucose-lowering therapy, toward hypoglycemia.', 'Use only with blood-sugar monitoring; watch for signs of low blood sugar.', 'Brinker, Herbal Contraindications and Drug Interactions; RxList/Medscape damiana monographs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1035', 'H225', 'other', 'Large or prolonged high-dose concentrated extract (cyanogenic glycoside and arbutin content)', 'moderate', 'The leaf contains a cyanogenic glycoside and arbutin (a hydroquinone precursor); rare case reports describe convulsions and strychnine-like paroxysms after roughly 200 grams (about 8 ounces) of concentrated extract, attributed to cyanide release.', 'Keep to ordinary tea and tincture doses; do not exceed recommended amounts or use concentrated extracts at high dose or for prolonged periods.', 'Drugs.com and RxList damiana clinical monographs (overdose case report); Szewczyk and Zidorn, genus Turnera review, Journal of Ethnopharmacology (2014) (cyanogenic and arbutin constituents).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1036', 'H225', 'condition', 'Hot, feverish, acutely inflamed, agitated, or insomniac states', 'moderate', 'A warming, drying, stimulating aromatic aggravates heat, excitation, and sleeplessness.', 'Avoid in hot, over-stimulated, or insomniac presentations; take earlier in the day and pair with cooling, moistening herbs where needed.', 'Mills and Bone, The Essential Guide to Herbal Safety; traditional energetic sources (King''s American Dispensatory, 1898; Ellingwood, 1919).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H225', 'EP01', 'avoid', 0, 3, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Damiana (Turnera diffusa / Turnera aphrodisiaca), which records it as a mild purgative, diuretic, and tonic with a longstanding reputation as an aphrodisiac in sexual debility. Also Ell", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions (hypoglycemic and tannin herbs); Szewczyk and Zidorn, Ethnob", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
