INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'D03', 'Secondary', 'Kapha: warm, dry, and dispersing, it clears damp, congested Kapha in the allergic airway.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
