INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'TCM13', 'Primary', 'Wind-Cold: warm and acrid, it releases and disperses Wind-Cold in the airways (clear, watery, sneezing allergic rhinitis). Energetic mapping.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'TCM08', 'Secondary', 'Qi Stagnation: its antispasmodic, unbinding action moves constrained Liver Qi expressed as spasm, migraine, and colic. Energetic mapping.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'TCM10', 'Secondary', 'Dampness/Phlegm: warm and drying, it transforms thin damp-phlegm of the congested airway. Energetic mapping.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'TCM11', 'Primary', 'Heat/Fire: a warm herb aggravates true heat and yang-type inflammation. Energetic mapping.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H226', 'TCM07', 'Secondary', 'Yin Deficiency: a warm, drying, acrid disperser further injures depleted fluids and empty-heat. Energetic mapping.', '{"title": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "locator": "Grieve, M., A Modern Herbal (1931): Butterbur (Petasites vulgaris). Public domain (botanical.com).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "locator": "Culpeper, N., The English Physician / Complete Herbal (1652): Butterbur (the plague-flower). NCCIH, Butterbur: Usefulness and Safety (nccih.nih.gov/health/butterbur). NIH LiverTox: Butterbur (NBK547997). Holland S, Silberstein SD, et al., E", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1037', 'H226', 'pregnancy', 'Pregnancy (all internal use)', 'absolute', 'Butterbur contains hepatotoxic, mutagenic, and carcinogenic unsaturated pyrrolizidine alkaloids that can cross the placenta and cause hepatic veno-occlusive disease and possible fetal harm. PA-containing butterbur is contraindicated in pregnancy, and the safety of even PA-free standardized extract in pregnancy is not established. A traditional emmenagogue and diaphoretic reputation adds a further theoretical concern.', 'Do not use in pregnancy in any form. There is no established safe dose; avoid both PA-containing and PA-free products.', 'NCCIH, Butterbur: Usefulness and Safety (products with PAs should not be used during pregnancy; little is known about PA-free products in pregnancy); AHPA cautionary labeling for PA-containing botanicals; Brinker, Herbal Contraindications and Drug Interactions (PA-containing herbs contraindicated in pregnancy).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1038', 'H226', 'breastfeeding', 'Breastfeeding', 'absolute', 'Pyrrolizidine alkaloids are excreted into breast milk and are hepatotoxic to the nursing infant; the safety of PA-free extract during lactation is unknown.', 'Avoid all internal use while breastfeeding.', 'NCCIH, Butterbur: Usefulness and Safety; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1039', 'H226', 'condition', 'Liver disease / hepatic impairment', 'absolute', 'Butterbur''s pyrrolizidine alkaloids are hepatotoxic and have caused clinically apparent liver injury, including with some products labeled PA-free; pre-existing liver disease compounds this risk.', 'Do not use with existing or suspected liver disease. Discontinue and evaluate liver function at any sign of hepatotoxicity (jaundice, dark urine, right-upper-quadrant pain, nausea, fatigue).', 'NIH LiverTox: Butterbur (NBK547997); NCCIH, Butterbur: Usefulness and Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1040', 'H226', 'drug_interaction', 'Hepatotoxic drugs and herbs and alcohol (e.g., acetaminophen, methotrexate, isoniazid, comfrey/other PA herbs, ethanol)', 'moderate', 'Additive hepatotoxic burden combining butterbur''s own PA content with other agents that stress the liver, increasing the risk of liver injury.', 'Avoid concurrent use with hepatotoxic medications, PA-containing herbs, and alcohol during a course of butterbur.', 'NIH LiverTox: Butterbur; NCCIH, Butterbur: Usefulness and Safety; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1041', 'H226', 'drug_interaction', 'CYP3A4 inducers (mechanistic/theoretical)', 'low', 'Pyrrolizidine alkaloids are bioactivated to toxic pyrroles by hepatic CYP3A4, so CYP3A4 induction could theoretically increase PA bioactivation and hepatotoxicity. This is mechanistic, not clinically documented, and applies chiefly to non-certified (PA-containing) material.', 'Prefer certified PA-free extract; use added caution when strong CYP3A4 inducers are co-administered with any butterbur product.', 'Mills & Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions (PA bioactivation pharmacology).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1042', 'H226', 'other', 'Asteraceae (ragweed, marigold, daisy, chrysanthemum) sensitivity', 'moderate', 'As a member of the Asteraceae, butterbur may provoke cross-reactive allergic responses in individuals sensitized to other daisy-family plants.', 'Use cautiously, and avoid, in those with known Asteraceae/ragweed allergy; watch for allergic reactions.', 'Butterbur, StatPearls (NCBI Bookshelf, NBK537160); AHPA Botanical Safety Handbook.');
