INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H227', 'TCM11', 'Secondary', 'Heat/Fire: added warmth aggravates frank heat and fire patterns.', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty) - Yin Yang Huo (Epimedium), where it is recorded as an acrid, warming tonic for impotence and for aching, cold sinews and bones.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty) - Yin Yang Huo (Epimedium), where it is recorded as an acrid, warming tonic for impotence and for aching, cold sinews and bones.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Yin Yang Huo (Herba Epimedii): acrid, sweet, warm; tonifies Kidney yang, strengthens sinew and bone, dispels wind-damp; classic caution in yin deficiency with fi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Yin Yang Huo (Herba Epimedii): acrid, sweet, warm; tonifies Kidney yang, strengthens sinew and bone, dispels wind-damp; classic caution in yin deficiency with fi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1043', 'H227', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient reliable human safety data, combined with documented estrogenic/hormonal (icariin) activity; no established obstetric use.', 'Avoid in pregnancy. Any pregnancy-related sexual, urinary, or musculoskeletal concern should be assessed by a clinician rather than self-treated.', 'Natural Medicines Comprehensive Database / WebMD Horny Goat Weed monograph; Drugs.com Horny Goat Weed (natural products) monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1044', 'H227', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable data on transfer into milk or on effects in the nursing infant, in a hormonally active herb.', 'Avoid while breastfeeding unless directed by a qualified practitioner.', 'Natural Medicines Comprehensive Database / WebMD Horny Goat Weed monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1045', 'H227', 'drug_interaction', 'Nitrates and PDE5 inhibitors / erectile-dysfunction drugs', 'moderate', 'Icariin is a weak PDE5 inhibitor and vasodilator; combined with nitrates or PDE5 drugs the effect can be additive, risking marked hypotension.', 'Do not combine with nitrates (nitroglycerin, isosorbide), sildenafil-class PDE5 inhibitors, or other ED drugs; monitor blood pressure.', 'Medscape Epimedium (Herba Epimedii) drug monograph; WebMD / Natural Medicines Comprehensive Database Horny Goat Weed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1046', 'H227', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Epimedium has mild antiplatelet/anticoagulant activity that may be additive and increase bleeding risk.', 'Use cautiously with anticoagulants/antiplatelets, monitor for bleeding, and stop before surgery.', 'Ge et al., herb-warfarin interaction review (PMC3976951); WebMD / Natural Medicines Comprehensive Database Horny Goat Weed; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1047', 'H227', 'drug_interaction', 'CYP3A4-metabolized medications', 'moderate', 'Herba Epimedii modulates cytochrome P450 3A4, altering plasma levels of drugs metabolized by that enzyme.', 'Use caution with narrow-therapeutic-index CYP3A4 substrates; monitor for altered drug effect.', 'Medscape Epimedium (Herba Epimedii) drug monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1048', 'H227', 'drug_interaction', 'Antihypertensive medication', 'moderate', 'Vasodilatory action may add to blood-pressure lowering, though tachyarrhythmia and hypertensive events have also been reported at high doses.', 'Monitor blood pressure if combined; introduce cautiously and avoid high doses.', 'Medscape Epimedium (Herba Epimedii) drug monograph; WebMD / Natural Medicines Comprehensive Database Horny Goat Weed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1049', 'H227', 'condition', 'Hormone-sensitive conditions (ER-positive breast cancer, uterine/ovarian cancer, endometriosis, uterine fibroids)', 'moderate', 'Icariin has estrogenic activity that may worsen estrogen-sensitive conditions.', 'Avoid in hormone-sensitive cancers and conditions.', 'WebMD / Natural Medicines Comprehensive Database Horny Goat Weed monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1050', 'H227', 'condition', 'Cardiac arrhythmia and cardiovascular disease', 'moderate', 'Tachyarrhythmia, hypotension, and rarely severe muscle spasm with elevated CK/creatinine have been reported, chiefly at high doses.', 'Avoid high or prolonged dosing; use cautiously (or avoid) in known arrhythmia or significant heart disease and refer palpitations or chest pain.', 'Herba Epimedium toxicity case report (PMC12182873); WebMD / Natural Medicines Comprehensive Database Horny Goat Weed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1051', 'H227', 'condition', 'Yin deficiency with heat / Fire patterns (TCM)', 'moderate', 'A warming, drying, yang-raising herb further injures yin fluids and stokes deficiency fire.', 'Do not use in yin deficiency with effulgent fire or in marked heat patterns; the classic TCM contraindication.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Yin Yang Huo.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H227', 'EP01', 'avoid', 0, 3, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty) - Yin Yang Huo (Epimedium), where it is recorded as an acrid, warming tonic for impotence and for aching, cold sinews and bones.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Han dynasty) - Yin Yang Huo (Epimedium), where it is recorded as an acrid, warming tonic for impotence and for aching, cold sinews and bones.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Yin Yang Huo (Herba Epimedii): acrid, sweet, warm; tonifies Kidney yang, strengthens sinew and bone, dispels wind-damp; classic caution in yin deficiency with fi", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.) - Yin Yang Huo (Herba Epimedii): acrid, sweet, warm; tonifies Kidney yang, strengthens sinew and bone, dispels wind-damp; classic caution in yin deficiency with fi", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, true);
