INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1052', 'H228', 'pregnancy', 'Pregnancy', 'moderate', 'Safety in pregnancy not established; no reproductive-toxicity data. Contains isoquinoline alkaloids (protopine and relatives).', 'Not recommended in pregnancy; avoid. Use only if a qualified practitioner judges benefit to outweigh the unknown risk.', 'EMA/HMPC EU herbal monograph on Fumaria officinalis L., herba (EMA/HMPC/367011/2021, 2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1053', 'H228', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety during lactation not established; unknown whether alkaloids pass into breast milk.', 'Not recommended while nursing; avoid without professional guidance.', 'EMA/HMPC EU herbal monograph on Fumaria officinalis L., herba (2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1054', 'H228', 'condition', 'Biliary obstruction, cholangitis, gallstones, liver disease and other biliary disease', 'moderate', 'Fumitory stimulates bile secretion, which can aggravate an obstructed or diseased biliary tract and provoke colic.', 'Avoid in bile-duct obstruction, cholangitis, gallstones, liver disease and any other biliary disease; effectively contraindicated where the duct is obstructed. Rule out these conditions before use.', 'EMA/HMPC EU herbal monograph on Fumaria officinalis L., herba (2023); German Commission E, Fumariae herba.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1055', 'H228', 'condition', 'Children and adolescents under 18 years (under 12 for the tea)', 'moderate', 'Use not established for lack of adequate safety and efficacy data in the young.', 'Do not use the powder, extracts, tincture or juice under 18 years, or the tea under 12 years, without qualified pediatric guidance.', 'EMA/HMPC EU herbal monograph on Fumaria officinalis L., herba (2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1056', 'H228', 'drug_interaction', 'Antihypertensive and antiarrhythmic medications', 'low', 'The chief alkaloid protopine shows hypotensive, antiarrhythmic, calcium-channel-antagonist and smooth-muscle-relaxant activity in pharmacological studies; a theoretical additive effect at higher intakes.', 'Theoretical only, no case reports; keep to recommended doses and monitor if combined with cardiovascular drugs. EMA records no interactions at recommended doses.', 'EMA/HMPC EU herbal monograph (2023, none reported); phytochemical/pharmacological reviews of Fumaria/protopine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1057', 'H228', 'other', 'Hypersensitivity to fumitory', 'moderate', 'Idiosyncratic hypersensitivity to the herb.', 'Do not use in those with known hypersensitivity to Fumaria; discontinue if allergic symptoms occur.', 'EMA/HMPC EU herbal monograph on Fumaria officinalis L., herba (2023).');
