INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H228', 'EP08', 'avoid', 1, 2, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve M, A Modern Herbal (1931), ''Fumitory'' (Fumaria officinalis), recording its traditional use as a slightly diaphoretic, diuretic, aperient and tonic bitter, ''valuable in all visceral obstructions, particularly those of the liver,'' and ", "locator": "Grieve M, A Modern Herbal (1931), ''Fumitory'' (Fumaria officinalis), recording its traditional use as a slightly diaphoretic, diuretic, aperient and tonic bitter, ''valuable in all visceral obstructions, particularly those of the liver,'' and ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "European Medicines Agency, Committee on Herbal Medicinal Products (HMPC), EU herbal monograph on Fumaria officinalis L., herba (EMA/HMPC/367011/2021, final Revision 1, 2023) and its Assessment Report; German Commission E monograph, Fumariae", "locator": "European Medicines Agency, Committee on Herbal Medicinal Products (HMPC), EU herbal monograph on Fumaria officinalis L., herba (EMA/HMPC/367011/2021, final Revision 1, 2023) and its Assessment Report; German Commission E monograph, Fumariae", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H229', 'Lovage', 'Levisticum officinale', 'Apiaceae (Umbelliferae), the carrot and celery family. Sometimes given the botanical synonym Levisticum officinale W.D.J. Koch; older literature also uses Ligusticum levisticum and Angelica levisticum.', 'Root and rhizome above all (the officinal drug of Commission E and the European Pharmacopoeia), secondarily the seed (fruit) and the aromatic leaf, the last chiefly culinary. Root is dug in autumn of the second or third year, split, and dried.', 'Pungent (warm, aromatic, celery-like and savory), Salty (the distinctive savory, mineral, ''Maggi'' note), Bitter (a mild bitterness), with a faint underlying sweetness.', 'Warm', 'Dry', 'Cold, damp, and boggy tissue with atony and torpor of the digestive and urinary terrain: the sluggish, waterlogged, still-water phenotype in whom fluids pool and gather (fluid retention, dropsy, a heavy and mucoid, congested gut) and in whom a cold, atonic digestion no longer kindles or moves its contents, so that gas, damp, and undigested food collect. Torpor and laxity of the tissues with poor fluid metabolism and weak peripheral circulation, met by a warm, drying, aromatic stimulant that rouses a torpid digestion, warms the cold, and drains the boggy, waterlogged excess. Damp, phlegmy congestion of the chest and sinuses in a cold, relaxed constitution. In every case the tissue is cold, under-toned, and waterlogged, and it is the warming, kindling, fluid-draining action of an aromatic stimulant that draws it back toward warmth, tone, and movement.', 'Heat and dryness. Its warming, pungent, drying, aromatic-oil character aggravates hot, dry, and irritated states: yin-deficient dryness, frank excess heat and fever from a hot terrain, and the thin, dry, already-depleted constitution, in whom a dispersing, drying stimulant deepens dryness and depletion. Acute inflammation of the kidneys and urinary tract, where the irritating volatile oils can worsen an already inflamed, hot, irritated parenchyma (a firm contraindication, see cautions). States of nervous excitation and heat, where a warming aromatic adds to the excess. Where there is no cold, damp, or atonic congestion to move, a warming diuretic stimulant has little to work on and may simply overheat and over-dry.', 'Digestive above all: a warming aromatic carminative and bitter-savory digestive stimulant for a cold, sluggish, flatulent gut. Urinary, as a strong aquaretic diuretic for the lower urinary tract, approved by Commission E for irrigation (flushing) therapy and the prevention of kidney gravel. Respiratory, as a mild warming expectorant and diaphoretic for damp, cold, phlegmy congestion. Reproductive (female), as a traditional emmenagogue and antispasmodic for delayed and painful menses. Musculoskeletal, as an eliminative, mildly anti-inflammatory herb long used to move metabolic waste in rheumatic and gouty states.', 'Sluggish, cold, flatulent digestion with bloating, wind, and colicky griping (its central carminative use). Water retention, edema, and the old use for dropsy, and the urinary flushing indications approved by Commission E: prevention of kidney gravel and supportive flushing of the lower urinary tract in mild inflammatory conditions. Rheumatic and gouty complaints, where its diuretic, eliminative action helps move metabolic waste. Delayed, scanty, or painful menstruation (emmenagogue and uterine antispasmodic). Damp, cold, phlegmy chest and sinus congestion (mild expectorant and diaphoretic). It is a warming digestive and urinary stimulant, not a remedy for hot, inflamed, or acutely obstructed conditions.', 'Cold-Damp-Relaxed, the boggy, waterlogged still-water terrain: the phlegmatic, damp, cool person with a sluggish, atonic digestion, poor fluid metabolism, a tendency to fluid retention and puffiness, and heavy, damp, phlegmy congestion, all met by a warming, drying, aromatic stimulant that kindles digestion and drains excess water. It is least suited to the hot, dry, robust (Pitta-like/choleric) constitution, in whom its warmth and pungency add heat, and it should be tempered in the thin, cold, dry, depleted (Vata-like) person, whose dryness its dispersing, drying character can deepen despite its welcome warmth.', 'Kapha', 'Pitta, Vata', 'Lovage is a European rather than a classical Chinese herb, but by its warm, acrid, aromatic nature it reads in TCM terms as an agent that warms and transforms Damp and moves a cold, stagnant middle. It suits Dampness and Phlegm-Damp accumulation with a cold, boggy terrain (its drying, aromatic, diuretic action drains and transforms damp), a cold and deficient Spleen that fails to transform food and fluid (warming the middle and rousing a torpid digestion), Qi stagnation of the middle burner with distension and flatulence (an acrid, aromatic carminative that moves Qi), and Wind-Cold on the exterior (a warm, acrid, diaphoretic herb). Its warming, draining, downward-and-outward movement fits cold-damp, not hot, patterns.', 'Heat and Fire patterns, and Damp-Heat, where a warming, acrid, drying herb adds heat to an already hot terrain. Yin deficiency with dryness and heat-from-emptiness, which its drying, dispersing nature worsens. Wind-Heat exterior patterns, for which a warm acrid diaphoretic is the wrong direction. In general, wherever there is heat, dryness, or a depleted Yin, a warm-dry aromatic stimulant is contraindicated.', 'Lovage is a widely eaten culinary herb with a good record of safety at food levels, but its concentrated medicinal preparations carry real cautions. The root''s volatile oils are irritating to inflamed kidney tissue, so it must not be used in acute kidney inflammation or impaired kidney function, nor as a flushing/irrigation therapy where edema arises from impaired heart or kidney function (Commission E; EMA HMPC). The root and essential oil contain phototoxic furanocoumarins: skin contact with the fresh plant or the oil, followed by sun or UV exposure, can cause phototoxic dermatitis, blistering, and lingering hyperpigmentation, so handle the fresh plant and oil with care and keep sun off exposed skin. It is a traditional emmenagogue and should be avoided in pregnancy. Ensure a generous fluid intake when using it as a urinary flushing therapy, and do not use it that way in known renal disease without medical supervision.', 'Acute inflammatory disease of the kidneys or urinary tract and impaired renal function (irritating volatile oils). Edema or dropsy due to impaired cardiac or renal function, for which flushing therapy is contraindicated (Commission E). Pregnancy (emmenagogue and uterine-stimulant action, with a reputed abortifacient history) and lactation without qualified guidance (insufficient data). Known hypersensitivity to lovage or to other Apiaceae/Umbelliferae (celery, fennel, carrot) and phototoxic reactivity to furanocoumarins. Caution with concurrent diuretics, lithium, anticoagulants, and photosensitizing drugs (see drug interactions).', 'Avoid in pregnancy. Lovage root is a traditional emmenagogue and uterine stimulant with an old reputation for bringing on delayed menses, and modern authorities place it among the herbs to avoid in pregnancy on that basis. The European Medicines Agency HMPC assessment of Levisticum officinale radix states that safety in pregnancy has not been established and that use during pregnancy is not recommended; the German Commission E and Brinker likewise caution against its use in pregnancy for its emmenagogue and reputed abortifacient action, and the root''s phototoxic furanocoumarins add further reason for caution. The consumer-safe course is to avoid medicinal doses of lovage root, seed, and essential oil throughout pregnancy. Ordinary culinary use of the leaf as a flavoring is a food-level exposure of far lower concern, but concentrated preparations should be avoided.', 'Insufficient data; avoid medicinal doses during lactation without professional guidance. The EMA HMPC assessment notes that safety during breastfeeding has not been established and does not recommend use for want of adequate data, and Herbal Reality advises avoiding lovage in lactation and using it only under the guidance of a medical herbalist. Culinary use of the leaf as a flavoring is a food-level exposure of low concern; concentrated root, seed, and essential-oil preparations should await better data or qualified supervision.', 'No established pediatric use; avoid medicinal doses in children. The EMA HMPC assessment did not establish safety or dosing in those under 18 years and did not recommend the medicinal product in that group for want of data. Culinary use of the leaf as a food flavoring is of low concern, but the concentrated root, seed, and essential-oil preparations, and especially the phototoxic essential oil, should be kept from young children and used in older children only under qualified guidance.', 'Documented human interaction data are limited; the well-reasoned cautions are mechanistic and follow from the herb''s strong diuretic action and its coumarin/furanocoumarin content. Diuretic (aquaretic) medications: as a potent plant diuretic, lovage can add to the fluid and electrolyte loss of pharmaceutical diuretics, so combined use should be monitored for dehydration, dizziness, and low blood pressure (Herbal Reality; Commission E flushing-therapy caution). Lithium: by the same diuretic action, lovage could theoretically reduce renal clearance of lithium and raise serum lithium toward toxic levels, the recognized caution for diuretic agents combined with lithium, so lithium levels should be monitored if the two are combined (mechanistic, by analogy to diuretic-lithium interactions). Anticoagulant and antiplatelet drugs (for example warfarin): lovage root contains coumarins and furanocoumarins, and spoiled or molded root can form the anticoagulant dicoumarol, giving a theoretical additive bleeding risk, so monitor for bleeding and check INR if combined (theoretical; drugs.com, Herbal Reality). Photosensitizing drugs: the root''s furanocoumarins (psoralens) are phototoxic and could add to the photosensitizing effect of drugs such as certain antibiotics, thiazide diuretics, and retinoids, increasing sunburn risk. Beyond these, no well-documented pharmacokinetic drug interactions are established (limited data).', 'Decoction of the dried root, the classic medicinal form (the tough root is simmered to draw out the aromatic oils and diuretic principles). Infusion (tea) of the root or bruised seed for digestive and carminative use. Tincture of the root. Culinary use of the fresh or dried leaf and stem as a savory pot-herb, and the seed as a spice, a gentle food-level form. Powdered root. Essential oil, used in flavoring and, with care, externally, noting its phototoxicity.', 'Dried root: about 4 to 8 g per day (German Commission E), taken as a decoction or divided infusions; roughly 2 to 3 g of root in 150 ml water, two to three times daily, up to some 4 to 9 g of dried root daily (Herbal Reality). Tincture (1:3, 45 percent): 1 to 3 ml, three times daily. Fluid extract (1:1, 45 percent): 0.5 to 2 ml, up to three times daily. When used as a urinary flushing therapy, take with a generous (roughly 2 liter) daily fluid intake. Not for continuous long-term use at medicinal doses without review.', 'Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The English Physitian (1653), ''Lovage.''', 'Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Reality, ''Lovage (Levisticum officinale)''; AHPA Botanical Safety Handbook, 2nd ed. (Levisticum officinale); ESCOP and modern phytochemical reviews of lovage phthalides and coumarins (LC-MS profiling of Levisticum root coumarins, PubMed-indexed).', 'Lovage is a tall, robust, celery-scented perennial of the carrot family (Apiaceae/Umbelliferae), native to the eastern Mediterranean and southwest Asia and long cultivated across Europe as a pot-herb and medicine; the whole plant carries a warm, savory, celery-and-yeast aroma that made it a favorite kitchen and ''Maggi'' herb. The medicinal root (and, secondarily, the seed and leaf) is rich in essential oil dominated by alkylphthalides, chiefly (Z)-ligustilide and 3-butylphthalide, with senkyunolide and butylidenephthalide, which give the characteristic odor and much of the antispasmodic and carminative action; alongside these are furanocoumarins (bergapten, psoralen and relatives), simple coumarins, polyacetylenes, phenolic acids, and beta-sitosterol. Pharmacologically it is a warming aromatic carminative and a strong aquaretic diuretic, with antispasmodic, mild expectorant, diaphoretic, emmenagogue, and antimicrobial activity; the phthalides account for the smooth-muscle relaxant effect and the furanocoumarins for the phototoxicity. Commission E approved lovage root for irrigation (flushing) therapy of the lower urinary tract and for the prevention of kidney gravel, and European tradition long used it for sluggish digestion, flatulent colic, water retention, and delayed menses. It is a food-grade herb whose bounding cautions are renal irritation, phototoxicity, and pregnancy.', 'Not found in the canonical biblical texts. Lovage is a herb of the ancient Mediterranean rather than of Scripture: it is generally identified with the ligystikon of Dioscorides (De Materia Medica, 1st century AD) and the ligusticum of Pliny the Elder (Natural History, 1st century AD), who linked its name to the region of Liguria on the Italian coast where it grew, and from that Late Latin ligusticum/levisticum the English ''lovage'' descends. It passed into the monastery and cottage gardens of medieval Europe, appearing in Charlemagne''s Capitulare de villis and the plan of the St. Gall garden, and is described in the early modern herbals of Gerard, Parkinson, and Culpeper (1653). Cited honestly as a herb of Greco-Roman and European tradition, not of the biblical canon.', 'Levisticum officinale is a hardy, vigorous garden perennial, widely cultivated and in no way at risk; it is not listed by United Plant Savers. A single plant is long-lived and easily propagated by seed or root division and self-sows freely, so home-grown and cultivated root is abundant and sustainable. Because it is so readily grown, wildcrafting pressure is negligible: the most sustainable source is simply a plant in the garden, harvesting root from mature (2 to 3 year) plants and leaving divisions to regrow.', 'Warm and drying: a pungent, savory, aromatic stimulant that warms and rouses a cold, torpid digestion and drains the boggy, waterlogged fluids of the still-water terrain.', 'Refer urinary red flags for prompt evaluation rather than self-treating with a diuretic herb: blood in the urine, fever with flank or loin pain (suggesting kidney infection), severe or colicky pain from a suspected obstructing stone, or a known or suspected kidney stone too large to pass. Do not use lovage as a flushing therapy in known kidney disease, impaired renal function, or edema arising from heart or kidney failure without medical supervision, and refer any unexplained or persistent edema for evaluation of its cardiac or renal cause. Refer persistent, severe, or worsening digestive pain, and any possible pregnancy, before use.', 'Lovage: LUV-ij. Levisticum officinale: leh-VISS-tih-kum oh-fiss-ih-NAH-lee.', 'free', 'Approved', '{"title": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "locator": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "locator": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
