INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS17', 'Primary', 'Cold: a warming aromatic stimulant for cold, chilled digestion and a cold terrain.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS07', 'Primary', 'Dampness: a drying, aromatic, aquaretic diuretic drains boggy, waterlogged accumulation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS19', 'Primary', 'Torpor: rouses a torpid, sluggish digestion and sluggish fluid metabolism.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS09', 'Secondary', 'Laxity/atony: warms and tones an atonic, under-toned gut and urinary terrain.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS08', 'Secondary', 'Stagnation: an acrid, aromatic carminative moves stagnant gas, fluid, and delayed menses.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS23', 'Minor', 'Phlegm: mild warming expectorant for damp, cold, phlegmy chest and sinus congestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS03', 'Primary', 'Dryness: a warming, dispersing, drying herb deepens dryness and fluid depletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS05', 'Primary', 'Excess heat: warmth and pungency aggravate a hot, feverish terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS06', 'Secondary', 'Acute inflammation: irritant volatile oils worsen acute kidney/urinary inflammation (firm contraindication).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H229', 'TS10', 'Minor', 'Excitation: a warming aromatic can add to states of heat and nervous excitation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H229', 'SY08', 'Primary', 'Digestive: warming aromatic carminative and savory digestive stimulant for a cold, flatulent gut.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H229', 'SY09', 'Primary', 'Urinary: strong aquaretic diuretic; Commission E flushing therapy and gravel prevention.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H229', 'SY07', 'Secondary', 'Respiratory: mild warming expectorant and diaphoretic for damp, cold congestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H229', 'SY03', 'Secondary', 'Reproductive (female): emmenagogue and uterine antispasmodic for delayed, painful menses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H229', 'SY04', 'Minor', 'Musculoskeletal: eliminative, mildly anti-inflammatory action in rheumatic and gouty states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A17', 'Primary', 'Carminative: relieves flatulence, bloating, and colicky griping (the central use).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A08', 'Primary', 'Diuretic (aquaretic): promotes urine flow; Commission E flushing therapy and gravel prevention.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A10', 'Secondary', 'Antispasmodic: phthalides (ligustilide, butylphthalide) relax gut and uterine smooth muscle.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A18', 'Secondary', 'Diaphoretic: a warm acrid herb that promotes sweating in cold, chilled states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A12', 'Secondary', 'Expectorant: mild warming expectorant for damp, cold, phlegmy congestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A19', 'Secondary', 'Emmenagogue: traditional promoter of delayed or scanty menses (basis of the pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A09', 'Secondary', 'Anti-inflammatory: leaf/root phenolics show anti-inflammatory activity; eliminative in rheumatic states.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A28', 'Minor', 'Antimicrobial: essential oil and phthalides show antibacterial activity in vitro.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A16', 'Minor', 'Bitter tonic: mild bitter-savory stimulation of digestive secretion and appetite.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A14', 'Minor', 'Alterative: diuretic, eliminative clearance of metabolic waste in gout and rheumatism.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H229', 'A25', 'Minor', 'Antioxidant: leaf phenolics show antioxidant activity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP54', 'Primary', 'Bloating/flatulence: the central carminative use for wind, bloating, and colicky griping.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP58', 'Primary', 'Dyspepsia/low digestive fire: warms and rouses a cold, sluggish, atonic digestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP66', 'Primary', 'Fluid retention: aquaretic diuretic for water retention and the old use for dropsy.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP63', 'Secondary', 'UTI (uncomplicated): Commission E flushing therapy for mild lower-urinary inflammation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP64', 'Secondary', 'Urinary stones: Commission E prevention of kidney gravel; traditional stone-flushing use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP12', 'Secondary', 'Digestive upset: general warming aromatic digestive for cold, damp indigestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP14', 'Secondary', 'Joint pain: eliminative diuretic for rheumatic and gouty joint complaints.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP29', 'Secondary', 'Dysmenorrhea: uterine antispasmodic (phthalides) eases cramping, painful menses.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP30', 'Secondary', 'Amenorrhea: traditional emmenagogue for delayed or scanty menses.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP20', 'Minor', 'Menstrual irregularity: emmenagogue action in delayed, irregular cycles.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP41', 'Minor', 'Cold/flu onset: warm diaphoretic at the onset of a cold, chilled infection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP49', 'Minor', 'Productive cough: mild warming expectorant for damp, cold, phlegmy cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H229', 'CP51', 'Minor', 'Bronchial congestion: warms and helps clear damp, cold chest and sinus congestion.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P04', 'Primary', 'Decoction of the dried root, the classic medicinal form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P05', 'Primary', 'Infusion (tea) of root or bruised seed for digestive/carminative use.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P01', 'Secondary', 'Tincture of the root (1:3, 45 percent).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P12', 'Secondary', 'Added to soups/food: fresh or dried leaf and stem as a savory pot-herb, seed as spice.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P03', 'Minor', 'Powdered root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H229', 'P13', 'Minor', 'Essential oil, in flavoring and, with care, externally, noting phototoxicity.');
