INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H229', 'TCM07', 'Secondary', 'Yin deficiency with dryness: its drying, dispersing nature worsens fluid depletion and heat-from-emptiness.', '{"title": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "locator": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "locator": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H229', 'TCM12', 'Minor', 'Wind-Heat: a warm acrid diaphoretic is the wrong direction for wind-heat.', '{"title": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "locator": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "locator": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1058', 'H229', 'pregnancy', 'Pregnancy (medicinal doses of root, seed, essential oil)', 'absolute', 'Traditional emmenagogue and uterine stimulant with a reputed abortifacient history; phototoxic furanocoumarins add further concern.', 'Avoid medicinal doses of lovage root, seed, and essential oil throughout pregnancy; culinary use of the leaf as a flavoring is a food-level exposure of far lower concern.', 'EMA HMPC, Assessment report on Levisticum officinale radix; German Commission E (Blumenthal, 1998); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1059', 'H229', 'breastfeeding', 'Breastfeeding (medicinal doses)', 'moderate', 'Safety during lactation has not been established; no adequate human data.', 'Avoid medicinal doses while nursing without professional guidance; culinary use of the leaf is lower concern.', 'EMA HMPC, Assessment report on Levisticum officinale radix; Herbal Reality, Lovage monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1060', 'H229', 'condition', 'Acute kidney/urinary inflammation and impaired renal function', 'absolute', 'Irritating volatile oils can aggravate an already inflamed renal parenchyma and worsen kidney function.', 'Do not use in acute inflammatory kidney or urinary-tract disease or in impaired renal function; use flushing therapy only in the absence of these.', 'German Commission E (Blumenthal, 1998), Lovage root; EMA HMPC, Levisticum officinale radix.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1061', 'H229', 'condition', 'Edema from impaired cardiac or renal function', 'absolute', 'Flushing (irrigation) therapy is contraindicated where edema arises from impaired heart or kidney function.', 'Do not use lovage as a urinary flushing therapy when edema is due to cardiac or renal impairment; seek medical care.', 'German Commission E (Blumenthal, 1998), Lovage root; EMA HMPC, Levisticum officinale radix.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1062', 'H229', 'drug_interaction', 'Diuretic medications (loop, thiazide, aquaretic)', 'moderate', 'As a potent plant diuretic, lovage can add to pharmaceutical diuretics'' fluid and electrolyte loss.', 'Monitor for dehydration, dizziness, and hypotension if combined; ensure adequate fluid intake.', 'Herbal Reality, Lovage monograph; German Commission E flushing-therapy caution (mechanistic).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1063', 'H229', 'drug_interaction', 'Lithium', 'moderate', 'A diuretic effect can reduce renal clearance of lithium and raise serum lithium toward toxic levels (recognized diuretic-lithium interaction).', 'Monitor serum lithium and adjust the dose with the prescriber if a lithium user takes lovage; theoretical, by analogy to diuretic-lithium interactions.', 'Mechanistic, by analogy to established diuretic-lithium interactions; flag for reviewer weighting.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1064', 'H229', 'drug_interaction', 'Anticoagulant/antiplatelet drugs (e.g. warfarin)', 'low', 'Coumarin and furanocoumarin content, with dicoumarol formation possible in spoiled/molded root, gives a theoretical additive bleeding risk.', 'Monitor for bleeding and check INR if combined; use fresh, properly dried root; theoretical interaction.', 'drugs.com, Lovage; Herbal Reality, Lovage monograph (theoretical).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1065', 'H229', 'drug_interaction', 'Photosensitizing drugs and topical exposure', 'moderate', 'Furanocoumarins (psoralens) in root and essential oil are phototoxic; skin contact plus UV causes phototoxic dermatitis, and they can add to photosensitizing drugs.', 'Handle fresh plant and oil with care, keep sun/UV off exposed skin, and be cautious combining with photosensitizing medicines (some antibiotics, thiazides, retinoids).', 'Herbal Reality, Lovage monograph; phototoxicity/furanocoumarin literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1066', 'H229', 'other', 'Apiaceae/Umbelliferae allergy', 'moderate', 'Cross-reactive hypersensitivity is possible in those allergic to celery, fennel, carrot, and related umbellifers.', 'Avoid in those with known Apiaceae allergy; discontinue if allergic symptoms occur.', 'Herbal Reality, Lovage monograph; general Apiaceae cross-reactivity.');
