INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H229', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "locator": "Grieve, M. A Modern Herbal (1931), ''Lovage'' (public-domain; the warming aromatic digestive and diuretic use and the European tradition). Supported by Felter & Lloyd, King''s American Dispensatory (1898), ''Levisticum,'' and Culpeper, The Engli", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "locator": "Blumenthal et al., The Complete German Commission E Monographs (1998), ''Lovage root''; European Medicines Agency HMPC, Assessment report on Levisticum officinale Koch, radix; Brinker, Herb Contraindications and Drug Interactions; Herbal Real", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H230', 'Fig', 'Ficus carica', 'Moraceae', 'Fruit (fresh and dried syconium); milky latex and leaf used topically', 'Sweet (ripe fruit); the fresh latex is acrid and pungent', 'Neutral', 'Moist', 'Dryness: dry, hard, constricted stool and a dry, tickling cough or parched throat. Tension and constriction of the lower bowel, eased by softening and moistening.', 'Dampness and phlegm: the sweet, cloying, moist fruit deepens boggy, mucus-laden states. Relaxed, lax bowels and active diarrhea, where a laxative is the wrong direction.', 'Digestive (bowel); Respiratory (throat and airways); Integumentary (skin), with broad nutritive support to the depleted constitution.', 'Constipation of the dry, sluggish bowel; dry, unproductive cough and sore, parched throat; boils, abscesses, and gum boils as a drawing poultice; nutritive support in debility and convalescence.', 'Dry-Depleted-Constricted; the thin, dry, undernourished, costive type. Suits the Melancholic and the dry Vata-like constitution.', 'Vata, Pitta', 'Kapha', 'Intestinal and Lung dryness with fluid insufficiency, and Spleen and Stomach weakness with poor appetite. Fig (Wu Hua Guo) is classed sweet and neutral, moistening the Lung and Large Intestine and harmonizing the Stomach.', 'Dampness and Phlegm accumulation, and loose stools from Spleen damp. The sweet, moist, cloying fruit burdens damp-phlegm patterns.', 'Rich in fermentable sugars and fiber; large amounts are strongly laxative and can cause loose stools, gas, and bloating. Dried figs are high in sugar, relevant in diabetes. The fresh latex and leaf are irritating and phototoxic: the furocoumarins (psoralen, bergapten) can cause severe phytophotodermatitis on sun-exposed skin. Fig is a recognized food allergen.', 'Known fig or weeping-fig (Ficus benjamina) allergy, and caution in those with multiple protease-fruit allergies (kiwi, papaya, pineapple, banana, avocado). Do not apply fresh latex or leaf to skin that will be exposed to sunlight. Avoid the laxative fruit in active diarrhea.', 'Fig fruit is a food and is regarded as safe in normal dietary amounts in pregnancy; dried figs are a traditional gentle remedy for the constipation of pregnancy. Concentrated fig-leaf and raw-latex medicinal preparations are not established as safe (the leaf has documented blood-glucose-lowering activity and the latex is a proteolytic irritant with a folk emmenagogue reputation), so therapeutic leaf and latex use should be avoided. Food form: safe; medicinal leaf/latex: insufficient data, avoid. No dedicated NCCIH or AHPA monograph establishes therapeutic-dose safety.', 'Fig fruit as food is compatible with breastfeeding in normal dietary amounts. No lactation data exist for medicinal fig-leaf or latex preparations, so therapeutic doses are best avoided while nursing (insufficient data). Fig is a recognized food allergen. Source: no LactMed or NCCIH monograph; food-safety by long common use.', 'Fig fruit and fig syrup are gentle and have long been given to children as a mild laxative and a demulcent for dry cough and sore throat; use ordinary food amounts. Keep the raw latex and leaf off children''s skin (phototoxic and irritant) and avoid concentrated leaf decoctions (marked glucose-lowering effect). Source: traditional pediatric use (Grieve 1931); fig phytophotodermatitis case reports.', 'Antidiabetic drugs (insulin, sulfonylureas, metformin): fig-leaf decoction has clinically documented hypoglycemic activity (about a 12 percent reduction in insulin requirement in type 1 diabetes, and a confirmed glucose-lowering effect in a type 2 double-blind trial), so combining it with glucose-lowering therapy can produce additive hypoglycemia and may require dose adjustment and monitoring. Antihypertensive drugs: fig-leaf preparations may add modestly to blood-pressure lowering (limited data). Photosensitizing agents (other psoralens): additive phototoxicity with topical fig latex or leaf. The fruit eaten as food has no well-documented interactions. Sources: Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22; Jundishapur J Nat Pharm Prod, fig-leaf type 2 diabetes double-blind trial; fig phytophotodermatitis, Cutis 2024 (PMID 38820103).', 'Fresh or dried fruit eaten whole; fig syrup and fig decoction (the base of the once-official Syrup of Figs, a gentle laxative); a split, warmed fruit poultice applied to boils, abscesses, and gum boils; fig-leaf decoction (folk antidiabetic, use cautiously); fresh latex dabbed on warts (proteolytic, irritant, not for sun-exposed skin).', 'Laxative: 2 to 4 fresh or dried figs, or 1 to 2 teaspoons of fig syrup, once or twice daily. Decoction: simmer 3 to 4 chopped figs in water, taken as needed for cough or constipation. Poultice: a split, warmed fig applied over a boil and changed several times daily. Fig-leaf decoction (traditional antidiabetic): about 1 leaf per cup once daily, only under medical supervision because of its glucose-lowering effect.', 'Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.', 'Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 38820103); Bensky et al., Chinese Herbal Medicine: Materia Medica (Wu Hua Guo).', 'Ripe figs are rich in sugars (glucose, fructose), soluble fiber and pectin, minerals (potassium, calcium, magnesium, iron), and organic acids; the milky latex carries the proteolytic enzyme ficin and furocoumarins (psoralen, bergapten). Traditional Western use is as a gentle bulk-and-osmotic laxative and demulcent (the base of the old Syrup of Figs), a nutritive food in convalescence, and a warm split-fruit poultice to ripen and draw boils and gum abscesses. The fresh latex is a folk wart remedy and the leaf a folk antidiabetic. Chief bounding cautions: phototoxic latex and leaf (phytophotodermatitis), fig-fruit allergy (Ficus-fruit syndrome, ficin), and additive hypoglycemia from leaf preparations.', 'Prominent throughout Scripture: the fig leaf covering (Genesis 3:7); the fig as emblem of peace and plenty, every man under his vine and fig tree (1 Kings 4:25; Micah 4:4); the cake of figs laid on King Hezekiah''s boil, a direct materia-medica reference (2 Kings 20:7; Isaiah 38:21); the barren fig tree (Matthew 21:19; Mark 11:13) and the parable of the fig tree (Luke 13:6-9). Also documented as food and medicine by Dioscorides and Pliny.', 'Ficus carica is a widely cultivated, non-threatened orchard and dooryard tree with no conservation concern. Prefer organically grown, unsulphured dried figs; harvest leaves and latex with gloves and sun protection because of the phototoxic sap.', 'A sweet, moist, temperate demulcent: it softens dryness and constriction, moistening the dry bowel and parched throat while gently nourishing the depleted.', 'Refer for constipation with severe abdominal pain, vomiting, blood in the stool, or a sudden change in bowel habit; for a cough lasting more than three weeks or with blood, fever, or breathlessness; for a boil or abscess with spreading redness, fever, or facial or dental involvement; and for any systemic allergic reaction to figs (throat swelling, wheeze), which is a medical emergency.', 'Fig (FIG); Ficus carica (FY-kus KAIR-ih-kuh)', 'free', 'Approved', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H230', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H230', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS03', 'Primary', 'Dryness: moistens the dry, hard, constricted bowel and the parched, dry throat and airway.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS12', 'Secondary', 'Constriction: softens and opens the costive, constricted lower bowel.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS18', 'Secondary', 'Tension: relieves griping bowel tension by softening and lubricating.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS07', 'Primary', 'Dampness: the sweet, moist, cloying fruit worsens boggy, damp states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS23', 'Secondary', 'Phlegm: cloying sweetness increases mucus and phlegm burden.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H230', 'TS09', 'Secondary', 'Laxity: a laxative is wrong for an already lax, loose bowel and diarrhea.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H230', 'SY08', 'Primary', 'Digestive: the headline use, a gentle demulcent laxative for the dry, sluggish bowel.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H230', 'SY07', 'Secondary', 'Respiratory: demulcent syrup and decoction soothe dry cough and sore throat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H230', 'SY10', 'Secondary', 'Integumentary: split-fruit poultice draws and ripens boils and abscesses; latex on warts.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A38', 'Primary', 'Laxative: a gentle bulk-and-osmotic laxative, the base of the old Syrup of Figs.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A11', 'Primary', 'Demulcent: soothing mucilage and pectin coat and moisten the bowel and throat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A34', 'Secondary', 'Emollient: softens and soothes skin and mucous surfaces topically.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A39', 'Secondary', 'Nutritive: sugar-, fiber-, and mineral-rich nourishment in debility and convalescence.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A24', 'Secondary', 'Vulnerary: warm split-fruit poultice ripens and draws boils, abscesses, and gum boils.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A33', 'Minor', 'Antitussive: demulcent action calms dry, tickling, unproductive cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A36', 'Minor', 'Hypoglycemic: the leaf lowers blood glucose (clinically documented); source of a folk antidiabetic and a drug-interaction caution.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H230', 'A32', 'Minor', 'Anthelmintic/vermifuge: the proteolytic latex (ficin) is a folk remedy for intestinal worms.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP55', 'Primary', 'Constipation: dry, sluggish bowel, the headline indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP50', 'Secondary', 'Dry, unproductive cough: demulcent fig syrup and decoction.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP52', 'Secondary', 'Sore throat: soothing, moistening demulcent for a parched, raw throat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP70', 'Secondary', 'Boils and abscesses: classic warm split-fig drawing poultice (as in Hezekiah''s boil).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP03', 'Minor', 'Debility: nutritive nourishment in convalescence and undernourishment.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP62', 'Minor', 'Dysbiosis/parasites: latex (ficin) as a folk vermifuge for intestinal worms.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H230', 'CP27', 'Minor', 'Blood sugar dysregulation: fig leaf as a traditional, evidence-supported antidiabetic (use with caution).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H230', 'P09', 'Primary', 'Syrup: Syrup of Figs, the classic gentle laxative preparation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H230', 'P08', 'Secondary', 'Poultice: warm split fruit applied to boils, abscesses, and gum boils.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H230', 'P04', 'Secondary', 'Decoction: figs simmered for cough, throat, and bowel; fig-leaf decoction (antidiabetic, cautious use).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H230', 'P12', 'Secondary', 'Added to food: eaten fresh or dried as a nutritive, mildly laxative food.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H230', 'P05', 'Minor', 'Infusion (leaf tea): folk antidiabetic leaf tea, used cautiously.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H230', 'C05', 'Indicated', 'Primary', 'Thin/Cold/Depleted (Vata-like): the dry, thin, costive, undernourished type.', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H230', 'C03', 'Indicated', 'Secondary', 'Melancholic: the dry, constricted, costive melancholic constitution.', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
