INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H230', 'TCM07', 'Primary', 'Yin/fluid deficiency dryness: moistens the Lung and Large Intestine for dry cough, dry throat, and dry constipation.', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H230', 'TCM03', 'Secondary', 'Spleen Qi deficiency: harmonizes the Stomach and benefits appetite as a gentle nourishing food.', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H230', 'TCM10', 'Primary', 'Dampness/Phlegm: the sweet, moist, cloying fruit burdens damp-phlegm accumulation and loose, damp stools.', '{"title": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "locator": "Grieve, A Modern Herbal (1931), Fig; Culpeper, The English Physician / Complete Herbal (1653), Fig Tree.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "locator": "Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22 (fig-leaf hypoglycemia); Focke et al., Clin Exp Allergy 2003;33:971-977 (Ficus-fruit cross-reactivity); Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 388", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1067', 'H230', 'pregnancy', 'Pregnancy (medicinal fig-leaf and raw-latex preparations)', 'moderate', 'Fig leaf has documented pharmacologic, blood-glucose-lowering activity and the raw latex is a proteolytic irritant with a folk emmenagogue reputation; therapeutic-dose safety of leaf and latex in pregnancy is not established.', 'Fig fruit as food is safe in normal dietary amounts and is a traditional gentle remedy for the constipation of pregnancy. Avoid concentrated fig-leaf decoctions and raw-latex applications during pregnancy.', 'No dedicated NCCIH or AHPA monograph establishes therapeutic-dose safety in pregnancy; fig-leaf pharmacologic (glucose-lowering) activity per Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1068', 'H230', 'breastfeeding', 'Breastfeeding (medicinal fig-leaf and latex preparations)', 'moderate', 'No lactation safety data exist for medicinal fig-leaf or latex preparations; fig is also a recognized food allergen.', 'Fig fruit as food is compatible with breastfeeding in ordinary amounts. Avoid therapeutic leaf and latex preparations while nursing.', 'No LactMed or NCCIH monograph for medicinal Ficus carica; food-safety by long common use.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1069', 'H230', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Fig-leaf decoction lowers blood glucose (about a 12 percent reduction in insulin requirement in type 1 diabetes and a confirmed hypoglycemic effect in a type 2 double-blind trial), adding to the effect of glucose-lowering therapy.', 'If fig-leaf preparations are used with antidiabetic drugs, monitor blood glucose and be prepared to reduce medication doses. Fig fruit eaten as food is not a concern beyond its sugar content.', 'Serraclara et al., Diabetes Res Clin Pract 1998;39:19-22; fig-leaf type 2 diabetes double-blind decoction trial, Jundishapur J Nat Pharm Prod.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1070', 'H230', 'other', 'Fig and weeping-fig (Ficus benjamina) allergy; protease-fruit cross-reactivity', 'moderate', 'Fig allergens, notably the cysteine protease ficin, cause IgE-mediated reactions including anaphylaxis, with cross-reactivity to Ficus benjamina latex and to kiwi, papaya, pineapple, banana, and avocado (the Ficus-fruit syndrome, a distinct entity from natural rubber latex allergy).', 'Avoid figs entirely in known fig or weeping-fig allergy; use caution in those with multiple protease-fruit allergies. A systemic reaction with throat swelling or wheeze is a medical emergency.', 'Focke et al., Clin Exp Allergy 2003;33:971-977; Hemmer et al., the Ficus-fruit syndrome, J Allergy Clin Immunol 2004.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1071', 'H230', 'other', 'Fresh fig latex and leaf on sun-exposed skin', 'moderate', 'The latex and leaf contain linear furocoumarins (psoralen, bergapten); skin contact followed by ultraviolet exposure causes phytophotodermatitis, a blistering, burn-like reaction.', 'Handle sap and leaves with gloves and skin protection; do not apply fig latex or leaf to skin that will be exposed to sunlight, and keep them off children''s skin.', 'Botanical Briefs: Fig Phytophotodermatitis (Ficus carica), Cutis 2024 (PMID 38820103); fig-tree phytophotodermatitis case report, PMC10423627.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1072', 'H230', 'condition', 'Active diarrhea, IBS-diarrhea flare, and loose-bowel states', 'low', 'As a bulk-and-osmotic laxative, figs worsen already loose or hyperactive bowels.', 'Avoid the laxative fruit during active diarrhea or IBS-diarrhea flares; the demulcent action offers no offsetting benefit here.', 'Grieve, A Modern Herbal (1931), Fig (laxative action); standard laxative pharmacology.');
