INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H231', 'TCM07', 'Secondary', 'Yin deficiency with heat and dryness worsened by a warm herb.', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), San Qi (Panax notoginseng).", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), San Qi (Panax notoginseng).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., San Qi (Notoginseng); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Memorial Slo", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., San Qi (Notoginseng); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Memorial Slo", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1073', 'H231', 'pregnancy', 'Pregnancy', 'moderate', 'Blood-invigorating herb that dispels blood stasis; traditionally contraindicated in pregnancy, with an added theoretical bleeding concern from documented antiplatelet saponin activity. Human pregnancy safety data are lacking.', 'Avoid throughout pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), Panax notoginseng; classical TCM pregnancy contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1074', 'H231', 'drug_interaction', 'Warfarin', 'moderate', 'Notoginseng raises the peak concentration, half-life, and AUC of warfarin in animal studies and its saponins independently inhibit platelet aggregation, so the combination can alter anticoagulation and increase bleeding. Evidence is complex and partly conflicting: some observational cohorts associate notoginseng regimens with fewer major bleeds, and its dencichine is hemostatic.', 'Do not self-combine. Use with warfarin only under medical supervision with INR and bleeding monitoring; discontinue about one to two weeks before surgery.', 'Herb-drug interaction reviews (Ge et al., J Ethnopharmacol 2023; Frontiers in Pharmacology 2021); Natural Medicines / WebMD monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1075', 'H231', 'drug_interaction', 'Antiplatelet, anticoagulant, and thrombolytic drugs (aspirin, clopidogrel, heparin, DOACs) and NSAIDs', 'moderate', 'Notoginseng saponins inhibit platelet aggregation and prolong bleeding time (shown in vitro and in rat models), giving additive bleeding risk with blood-thinning drugs.', 'Avoid, or use only under close medical supervision with bleeding monitoring; discontinue before surgery.', 'Natural Medicines / WebMD monograph; herb-drug interaction reviews; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1076', 'H231', 'condition', 'Bleeding disorders and the perioperative period', 'moderate', 'Despite its hemostatic reputation, the saponin fraction is antiplatelet and can prolong bleeding time, raising hemorrhage risk in bleeding disorders and around surgery.', 'Use cautiously in hemorrhagic disorders; discontinue about one to two weeks before surgery or dental extraction.', 'Natural Medicines / WebMD monograph; Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1077', 'H231', 'drug_interaction', 'Drugs metabolized by hepatic cytochrome P450 enzymes', 'low', 'Notoginseng saponins may modulate CYP450 activity and alter the metabolism and levels of co-administered drugs.', 'Use caution and monitor when combined with narrow-therapeutic-index CYP substrates.', 'Herb-drug interaction reviews (Ge et al., J Ethnopharmacol 2023); Natural Medicines monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1078', 'H231', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on transfer of notoginseng saponins or dencichine into breast milk or on infant effects; antiplatelet activity of unknown relevance to the infant.', 'Avoid during lactation for want of safety data.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013).');
