INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H232', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H232', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H232', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS06', 'Primary', 'Acute inflammation: soothes and cools the acutely inflamed, hot, red urinary mucosa of cystitis, urethritis, and nephritis.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS05', 'Primary', 'Excess heat: refrigerant, cooling the hot, burning, scalding heat of the irritated urinary tract and inflamed tissue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS03', 'Secondary', 'Dryness: the mucilaginous demulcent moistens and soothes dry, chafed, irritated mucosa and a dry, tickling cough.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS07', 'Secondary', 'Dampness: the watery diuresis drains dropsical fluid retention and the damp-heat gravelly terrain of stone.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS10', 'Minor', 'Excitation: relaxes and calms the tense, spasming, over-excited, irritable bladder.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS17', 'Primary', 'Cold: a cooling refrigerant diuretic chills the frankly cold, atonic urinary tract with pale, copious urine.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS01', 'Secondary', 'Deficiency: a flushing diuretic that drains fluid and minerals depletes the already deficient.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H232', 'TS04', 'Minor', 'Exhaustion: draining and cooling is wrong for the depleted, emptied, exhausted reserve.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H232', 'SY09', 'Primary', 'Urinary: the defining seat; kidney to bladder, for stone, gravel, cystitis, nephritis, and fluid retention.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H232', 'SY07', 'Secondary', 'Respiratory: demulcent soothing of a dry, tickling, irritable cough and bronchial dryness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H232', 'SY10', 'Secondary', 'Integumentary: the bruised fresh-herb poultice for burns, scalds, wounds, and hot swellings.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H232', 'SY08', 'Minor', 'Digestive: a gentle laxative action on a sluggish, dry bowel.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H232', 'SY04', 'Minor', 'Musculoskeletal: traditional flushing use in gouty and rheumatic complaints.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A11', 'Primary', 'Demulcent: soft mucilage soothes and rehydrates the irritated, inflamed urinary and bronchial mucosa; the defining virtue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A08', 'Primary', 'Diuretic: a genuine, saline, stone-clearing diuretic for gravel, suppressed urine, and dropsy.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A24', 'Secondary', 'Vulnerary: the bruised fresh herb heals and cools burns, scalds, wounds, and inflamed skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A09', 'Secondary', 'Anti-inflammatory: cools and settles the hot, inflamed urinary tract and hot skin (refrigerant action).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A34', 'Minor', 'Emollient: softens and soothes inflamed skin applied externally.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A38', 'Minor', 'Laxative: a mild laxative action on a sluggish, dry bowel (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A33', 'Minor', 'Antitussive: demulcent easing of a dry, tickling, unproductive cough (traditionally as a syrup).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H232', 'A15', 'Minor', 'Astringent: a faint astringency toning the relaxed, irritated mucosa.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP64', 'Primary', 'Urinary stones / gravel: the headline demulcent, stone-clearing diuretic use, easing the passage of calculi.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP63', 'Primary', 'UTI / cystitis: burning, scalding, frequent, or scanty painful urination of an inflamed bladder and urethra.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP65', 'Secondary', 'Urinary irritation / interstitial: the irritable, inflamed, over-excited bladder and nephritis/pyelitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP66', 'Secondary', 'Fluid retention: dropsy and suppressed or scanty urine relieved by its watery diuresis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP50', 'Minor', 'Cough dry/unproductive: demulcent soothing of a dry, tickling cough (traditionally as a syrup).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP55', 'Minor', 'Constipation: a mild laxative action on a sluggish, dry bowel.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP18', 'Minor', 'Skin conditions: hot, inflamed skin and swellings cooled by the external poultice.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H232', 'CP08', 'Minor', 'Poor wound healing: burns, scalds, and wounds dressed with the bruised fresh-herb vulnerary poultice.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H232', 'P05', 'Primary', 'Infusion (tea) of the dried or fresh herb, the standard form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H232', 'P01', 'Secondary', 'Tincture / fluid extract of the herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H232', 'P08', 'Secondary', 'Bruised fresh-herb poultice for burns, scalds, wounds, and hot swellings.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H232', 'P09', 'Minor', 'Syrup, traditionally for a dry, irritable cough.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H232', 'P04', 'Minor', 'Short decoction, used historically; fresh material preferred.');
