INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H232', 'TCM03', 'Secondary', 'Spleen Qi deficiency: a watery, cooling diuretic further weakens a depleted digestion and drains qi and fluids.', '{"title": "Grieve, A Modern Herbal (1931) - Pellitory of the Wall (Parietaria officinalis). Classed diuretic, demulcent, refrigerant, and slightly laxative; a valued remedy for suppression of urine, stone and gravel, dropsy, and other urinary and blad", "locator": "Grieve, A Modern Herbal (1931) - Pellitory of the Wall (Parietaria officinalis). Classed diuretic, demulcent, refrigerant, and slightly laxative; a valued remedy for suppression of urine, stone and gravel, dropsy, and other urinary and blad", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The English Physician / Complete Herbal (1653) - Pellitory of the Wall (cooling, cleansing, for the stone, gravel, and hot urinary complaints, and as a poultice). Bartram, Encyclopedia of Herbal Medicine (Parietaria officinalis, u", "locator": "Culpeper, The English Physician / Complete Herbal (1653) - Pellitory of the Wall (cooling, cleansing, for the stone, gravel, and hot urinary complaints, and as a poultice). Bartram, Encyclopedia of Herbal Medicine (Parietaria officinalis, u", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1079', 'H232', 'other', 'Hay fever, pollen allergy, and Urticaceae (nettle family) allergy', 'moderate', 'Parietaria pollen is one of the most significant airborne allergens of the Mediterranean, a leading cause of allergic rhinitis and a trigger of asthma, with cross-reactive allergen proteins. Pollen-sensitized or nettle-family-allergic people can react to the herb.', 'Avoid in anyone with hay fever, pollen allergy, asthma, or known sensitivity to the Urticaceae family; approach any allergic or atopic patient with caution and avoid on any sign of reaction.', 'Herbal Reality Pellitory-of-the-Wall monograph (contraindicated in hay fever / Urticaceae allergy); ''Parietaria Allergy: An Intriguing Challenge for the Allergist'' (Medicina 2018, PMC6306946).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1080', 'H232', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient modern human safety data for a stimulating diuretic herb; no controlled pregnancy studies.', 'Avoid medicinal doses in pregnancy as a precaution; urinary complaints in pregnancy should be assessed by a clinician rather than self-treated.', 'Herbal Reality Pellitory-of-the-Wall monograph (avoid, insufficient data); RxList/NMCD Pellitory-of-the-Wall monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1081', 'H232', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable modern data on transfer into milk or on effects in the nursing infant.', 'Avoid medicinal doses while breastfeeding unless directed by a qualified practitioner.', 'Herbal Reality Pellitory-of-the-Wall monograph (avoid, insufficient data); RxList/NMCD monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1082', 'H232', 'drug_interaction', 'Diuretic drugs and lithium', 'low', 'As a genuine diuretic, its action may be additive with pharmaceutical diuretics (increasing fluid and electrolyte loss) and, as a general diuretic-class effect, could alter renal lithium clearance and serum lithium levels. Theoretical, not documented; no CYP450 or documented pharmaceutical interactions are on record.', 'Use cautiously with diuretics and maintain hydration; where lithium is co-prescribed, monitor serum lithium.', 'Herbal Reality monograph (no documented interactions); Brinker, Herbal Contraindications and Drug Interactions (diuretic class effects); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1083', 'H232', 'condition', 'Edema due to impaired heart or kidney function', 'moderate', 'Standard irrigation-therapy precaution: fluid retention arising from cardiac or renal insufficiency should not be managed by diuretic flushing without medical oversight, and a cooling, draining diuretic can burden compromised kidneys or mask worsening disease.', 'Do not self-treat edema from heart or kidney disease with pellitory; refer for medical assessment. Ensure adequate fluid intake when the herb is used as a diuretic.', 'Mills and Bone, Principles and Practice of Phytotherapy (diuretic / irrigation-therapy principle); general phytotherapy practice.');
