INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H232', 'EP08', 'avoid', 0, 3, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931) - Pellitory of the Wall (Parietaria officinalis). Classed diuretic, demulcent, refrigerant, and slightly laxative; a valued remedy for suppression of urine, stone and gravel, dropsy, and other urinary and blad", "locator": "Grieve, A Modern Herbal (1931) - Pellitory of the Wall (Parietaria officinalis). Classed diuretic, demulcent, refrigerant, and slightly laxative; a valued remedy for suppression of urine, stone and gravel, dropsy, and other urinary and blad", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The English Physician / Complete Herbal (1653) - Pellitory of the Wall (cooling, cleansing, for the stone, gravel, and hot urinary complaints, and as a poultice). Bartram, Encyclopedia of Herbal Medicine (Parietaria officinalis, u", "locator": "Culpeper, The English Physician / Complete Herbal (1653) - Pellitory of the Wall (cooling, cleansing, for the stone, gravel, and hot urinary complaints, and as a poultice). Bartram, Encyclopedia of Herbal Medicine (Parietaria officinalis, u", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H233', 'Southernwood (Lad''s Love, Old Man)', 'Artemisia abrotanum', 'Asteraceae (Compositae), the daisy and aster family', 'Aerial parts, chiefly the young leafy flowering shoots and leaves (the herb). The finely divided, feathery, lemon-and-camphor-scented foliage carries the bitter principle and aromatic volatile oil that define it; historically the dried tops, and a distilled oil, were used.', 'Bitter (the defining tonic, worm-expelling bitterness), Pungent and aromatic (the warm, camphoraceous, lemon-scented volatile oil), and a light Astringency (the tannins behind its old use to stanch small wounds).', 'Warm', 'Dry', 'Cold, torpid, atonic states of the digestion and liver: the sluggish, underactive, torpid stomach with poor appetite and weak digestive fire, and a slack, atonic gut whose want of tone (laxity) a warming aromatic bitter rouses and firms. Its worm-expelling reach suits the boggy, cold, damp-harboring intestinal terrain in which threadworms and roundworms take hold, especially in children. Through its deobstruent, bile-moving action it answers a congested, sluggish, torpid liver and biliary flow, and through its emmenagogue action the cold, held-back, sluggish uterus of scanty or absent menses. In every case the picture is cold, damp, sluggish, and lacking in tone and activity rather than hot, dry, or over-tense, and what it needs is warming, drying, bitter stimulation to wake and tone the part.', 'A warming, drying, aromatic bitter is wrong for tissue that is already hot, dry, or over-stimulated. Dry, depleted, fluid-poor states that its bitterness and dryness only parch further. Hot, acutely inflamed, feverish-irritable conditions, where the warm, pungent, thujone-bearing oil can aggravate the heat and the irritation. Nervous over-excitation and a lowered seizure threshold, since the thujone in the volatile oil is a central stimulant that can worsen an already excited, twitchy, or convulsion-prone state.', 'Digestive above all: a warm aromatic bitter that rouses a cold, torpid, atonic stomach, sharpens appetite and digestion, and expels intestinal worms. Hepatic, through its deobstruent, cholagogue action on a congested, sluggish liver and torpid bile. Reproductive, through its emmenagogue, uterus-stimulating action on scanty, delayed, or suppressed menses. Nervous, through the aromatic, mildly nervine volatile oil, traditionally used to rouse from drowsiness and lassitude (and the seat of the thujone caution). Integumentary, applied externally to small wounds, to skin complaints, and as a hair and scalp wash. Immune, through a mild antiseptic, antimicrobial action.', 'Intestinal worms, the headline folk use: threadworms and roundworms, classically given to children as a bitter tea or sweetened powder to expel them. Scanty, delayed, or suppressed menstruation, its principal use as an emmenagogue that provokes a held-back, sluggish menstrual flow. Atonic, cold indigestion with poor appetite, weak digestive fire, and a torpid stomach that a bitter aromatic tonic wakes. A congested, sluggish liver and torpid bile, addressed by its deobstruent, cholagogue action. Fevers, which it was used to reduce through a warm, diaphoretic action. Externally: small bleeding wounds (a styptic wash or poultice), skin complaints, dandruff, and thinning hair (an aromatic scalp and hair wash), and drowsiness or faintness (the fresh, pungent herb sniffed or carried, whence garden names like Lad''s Love and, in France, garde-robe for repelling moths).', 'Cold-Damp-Torpid, the sluggish, phlegmatic type whose cold, underactive, atonic digestion and congested liver breed poor appetite, torpid bile, and a boggy, worm-harboring gut, and whose cold, held-back uterus gives scanty or absent menses. A warming, drying, bitter stimulant, it wakes and tones this cold, slow terrain. It is wrong for the hot, dry, tense, bilious (choleric, Pitta-like) constitution, whose heat and dryness its warm, pungent, thujone-bearing nature only aggravates, and it can further deplete the thin, dry, depleted (Vata-like) person despite its warmth.', 'Kapha', 'Vata, Pitta', 'Southernwood is a European, not a classical Chinese, herb (its Artemisia cousins qing hao and ai ye belong to that tradition, but abrotanum does not); the following is an energetic mapping from its warm, bitter, drying, moving nature. Its clearest correspondence is cold Dampness with worms and food stagnation: the boggy, damp, torpid digestive terrain, sluggish appetite, and intestinal parasites that its warm, bitter, drying, worm-expelling action drains and clears. It also answers Liver Qi Stagnation, the congested, held-back liver, bile, and menstrual flow that its deobstruent, cholagogue, emmenagogue action moves, and a mild Wind-Cold exterior with fever, which its warm diaphoresis releases.', 'Yin deficiency with dryness and heat, since a warm, drying, bitter, dispersing herb further injures the yin and fluids of a dry, depleted patient. Heat and Fire patterns, where its warm, pungent, aromatic nature aggravates the heat rather than clearing it. Blood deficiency, where an emmenagogue that moves and disperses blood and menses is the wrong direction in an already blood-depleted, weak patient.', 'Southernwood is a thujone-bearing Artemisia, and its cautions turn on that volatile oil. Depending on chemotype the essential oil can be high in thujone (a central-nervous stimulant and, in excess, a neurotoxin and convulsant), so the herb should be used in ordinary culinary-to-medicinal amounts, not in large or prolonged doses, and the concentrated essential oil should not be taken internally. Avoid in epilepsy and other seizure disorders. As an Asteraceae member it can provoke contact dermatitis and allergic reactions in sensitive people, especially those allergic to ragweed, chamomile, or other daisies. Its bitterness and dryness can aggravate dry, depleted, or overheated constitutions. Because its emmenagogue, uterus-stimulating reputation is strong and long-standing, it is firmly contraindicated in pregnancy (see safety fields). Modern clinical safety and dosing data are limited, so keep to conservative doses and short courses.', 'Pregnancy, absolutely, on its emmenagogue, uterus-stimulating, reputedly abortifacient action (see safety fields). Lactation, on insufficient data and thujone content. Epilepsy and other seizure disorders, given the proconvulsant thujone in the volatile oil. Known allergy to ragweed or other Asteraceae (risk of cross-sensitivity and dermatitis). Concurrent heavy alcohol use, which can amplify thujone neurotoxicity. Do not take the concentrated essential oil internally. Any unexplained amenorrhea should be evaluated, and pregnancy excluded, before an emmenagogue is used.', 'Contraindicated in pregnancy. Southernwood''s long and consistent traditional use is as an emmenagogue and uterine stimulant to bring on suppressed menses, and it carries a reputed abortifacient action; on that basis modern botanical-safety references place it among the herbs to avoid in pregnancy. It also contains thujone, a compound restricted in pregnancy. No controlled human safety data overturn this precaution, so it should not be used in any medicinal amount during pregnancy. Sources: AHPA Botanical Safety Handbook (2nd ed.), which contraindicates emmenagogue and uterine-stimulant Artemisia species in pregnancy; Brinker, Herbal Contraindications and Drug Interactions (emmenagogues contraindicated in pregnancy); Mills and Bone, The Essential Guide to Herbal Safety.', 'Avoid during breastfeeding. There are no reliable modern data on the transfer of southernwood''s constituents into breast milk or on effects in the nursing infant, and the thujone content argues for caution; standard references discourage medicinal use of thujone-bearing Artemisia species while nursing. Use no medicinal amount during lactation unless directed by a qualified practitioner. Sources: AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, The Essential Guide to Herbal Safety.', 'Traditionally southernwood was given to children in small sweetened doses to expel threadworms, one of its oldest uses; nonetheless, because the herb contains thujone and modern pediatric safety and dosing data are lacking, it should be used in children only under qualified supervision, at reduced, short-course doses of the dilute herb (tea or low-dose tincture), never the essential oil. Sources: AHPA Botanical Safety Handbook (2nd ed.); traditional use per Grieve, A Modern Herbal (1931); Bown, RHS Encyclopedia of Herbs and Their Uses.', 'There are no well-documented clinical drug interactions for southernwood; the following are constituent-based cautions, and direct human interaction data are limited. Its thujone content is proconvulsant (a GABA-A antagonist), so it can theoretically lower the seizure threshold and oppose anticonvulsant medication; avoid it in people taking antiepileptic drugs. Thujone''s central-nervous effects may be additive with, or amplified by, alcohol and other CNS-active agents. As a bitter cholagogue it stimulates bile flow, a theoretical caution alongside drugs affecting the biliary tract. No effects on CYP450 drug-metabolizing enzymes are established. Modern references: Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, The Essential Guide to Herbal Safety; AHPA Botanical Safety Handbook (2nd ed.).', 'Infusion (bitter tea) of the dried leafy tops, the common internal form. Tincture of the dried or fresh herb. Powdered dried herb, historically given to children for worms mixed into honey, syrup, or molasses to mask the bitterness. Externally: a poultice or fomentation of the herb, a wash or bath for skin complaints and small wounds, and an infused-oil or vinegar hair and scalp rinse. The distilled essential oil is used externally and as an aromatic only, not internally.', 'Infusion: about 1 teaspoon (1 to 2 g) dried herb per cup of water, up to three times daily, as a short course. Tincture (1:5, 45 percent): 1 to 2 mL up to three times daily. Powder: historically small pinch-to-teaspoon doses in honey for worms, given briefly. Keep to conservative doses and short courses because of the thujone content; avoid large or prolonged dosing, and do not take the essential oil internally.', 'Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and the plant used as an aromatic and moth-repellent (Lad''s Love, Old Man, garde-robe).', 'Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in antiquity). Bown, RHS Encyclopedia of Herbs and Their Uses. Modern chemistry and safety: Wolski et al., review of Artemisia abrotanum chemistry, biological activity, and traditional use (PMC8123286); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, The Essential Guide to Herbal Safety; AHPA Botanical Safety Handbook (2nd ed.).', 'Family Asteraceae (Compositae). A hardy, semi-woody perennial subshrub of southern European and probably western Asian origin, long grown in European gardens and widely naturalized, with finely divided, feathery, grey-green, lemon-and-camphor-scented foliage and (rarely, in cool climates) small yellowish flower heads. Its many folk names, Lad''s Love, Old Man, Southern Wormwood, and the French garde-robe, record its use as a courting-posy, a scented men''s sprig, a wormwood-kin bitter, and a moth-repellent laid among clothes. The chemistry is chemotype-dependent: the volatile oil may be dominated by thujone, by 1,8-cineole, or (in many samples) by borneol, alongside davanone-type sesquiterpenoids, and the herb also carries coumarins, phenolic acids, flavonoids, tannins, and the traditional alkaloid abrotanine. Its clinical identity is a warm, bitter, aromatic stimulant: a vermifuge for children''s worms, an emmenagogue for suppressed menses, a bitter tonic and cholagogue for cold, torpid digestion and a sluggish liver, with external use on skin, wounds, and hair. Best regarded as a low-dose, short-course specialist bitter rather than a daily tonic, given its thujone content and strong emmenagogue reputation.', 'Not a plant of the biblical Near East and not named in canonical Scripture. Southernwood belongs to the Old World Mediterranean and European tradition: it appears in the Greek and Roman materia medica as abrotonon in Dioscorides and Pliny, used in antiquity against intestinal worms and to provoke menstruation, and it passed through the medieval monastic and English cottage-garden traditions as Lad''s Love and Old Man. Included here as a cross-traditional Mediterranean-European entry, honestly sourced to that origin rather than to Scripture.', 'Not a species of conservation concern. Southernwood is a cultivated garden perennial, easily propagated from softwood or semi-ripe cuttings and rarely setting seed in cool climates, and is not wild-harvested at any scale; it carries no United Plant Savers at-risk listing. Prefer organically grown, cultivated garden material; because it spreads readily from cuttings, home or small-farm propagation is both easy and sustainable.', 'Warm, dry, and bitter-aromatic: a worm-expelling, menses-provoking, bile-moving bitter stimulant that wakes and tones a cold, damp, torpid, atonic digestion and a sluggish liver.', 'Refer suspected worm infestation that does not clear, or heavy infestation in a young child, for diagnosis and appropriate antiparasitic treatment. Refer any unexplained absence of menses for evaluation and, first of all, to exclude pregnancy before an emmenagogue is even considered. Refer known or suspected pregnancy (do not use), epilepsy or any seizure disorder, jaundice or suspected liver or gallbladder disease, and persistent digestive complaints, weight loss, or abdominal pain that need medical assessment rather than a bitter tonic.', 'Southernwood: SUTH-ern-wood. Artemisia abrotanum: ar-teh-MEE-zee-uh ab-roh-TAY-num.', 'seed', 'Approved', '{"title": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "locator": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "locator": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H233', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H233', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H233', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS19', 'Primary', 'Torpor: wakes a cold, sluggish, underactive, torpid stomach and liver; the keynote.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS09', 'Secondary', 'Laxity: a bitter tonic firming the slack, atonic tone of a weak digestion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS08', 'Secondary', 'Stagnation: deobstruent and cholagogue action on congested liver, bile, and held-back menses.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS17', 'Secondary', 'Cold: a warming aromatic for cold digestion and a cold, held-back uterus.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS07', 'Minor', 'Dampness: dries the boggy, damp, worm-harboring intestinal terrain.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS05', 'Primary', 'Excess heat: a warm, pungent aromatic aggravates hot, flushed, feverish states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS03', 'Primary', 'Dryness: a drying bitter parches dry, fluid-poor, depleted tissue further.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS06', 'Secondary', 'Acute inflammation: wrong for hot, acutely inflamed, irritated conditions.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H233', 'TS10', 'Minor', 'Excitation: the thujone-bearing oil is a stimulant that worsens over-excited, convulsion-prone states.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY08', 'Primary', 'Digestive: rouses a cold, torpid, atonic stomach; bitter tonic and vermifuge.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY12', 'Primary', 'Hepatic: deobstruent, cholagogue action on a congested, sluggish liver and torpid bile.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY03', 'Secondary', 'Reproductive: emmenagogue, uterus-stimulating action on scanty or suppressed menses.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY01', 'Minor', 'Nervous: aromatic, mildly nervine oil used to rouse from drowsiness; seat of the thujone caution.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY10', 'Minor', 'Integumentary: external use on wounds, skin complaints, dandruff, and hair.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H233', 'SY05', 'Minor', 'Immune: mild antiseptic, antimicrobial action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A32', 'Primary', 'Anthelmintic/vermifuge: the classic folk use to expel threadworms and roundworms, especially in children.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A19', 'Primary', 'Emmenagogue: provokes a held-back, scanty, or suppressed menstrual flow; basis of the pregnancy contraindication.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A16', 'Primary', 'Bitter tonic: a warm aromatic bitter that wakes appetite and cold, torpid digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A43', 'Secondary', 'Cholagogue: moves a torpid, sluggish bile flow.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A14', 'Secondary', 'Alterative: the deobstruent, terrain-clearing action of the old herbals.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A17', 'Secondary', 'Carminative: the aromatic oil eases a cold, sluggish, flatulent digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A23', 'Secondary', 'Tonic: a general stimulant tonic to a cold, slow constitution (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A28', 'Secondary', 'Antimicrobial/antiseptic: external antiseptic use on wounds and skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A18', 'Minor', 'Diaphoretic: a warm diaphoresis used to reduce fevers.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A49', 'Minor', 'Febrifuge: reduces fever, in the wormwood-kin manner.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A24', 'Minor', 'Vulnerary: external application to small wounds.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A50', 'Minor', 'Styptic: an astringent wash to stanch small bleeding wounds.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H233', 'A02', 'Minor', 'Nervine tonic: a mild nervine principle in the aromatic herb (Grieve).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP62', 'Primary', 'Dysbiosis/parasites: threadworms and roundworms, the headline vermifuge use, classically in children.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP30', 'Primary', 'Amenorrhea: suppressed or absent menses, the principal emmenagogue use (exclude pregnancy first).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP20', 'Secondary', 'Menstrual irregularity: scanty, delayed, held-back menstrual flow.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP58', 'Secondary', 'Dyspepsia/low digestive fire: cold, atonic indigestion with poor appetite.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP72', 'Secondary', 'Sluggish liver/bile stagnation: deobstruent, cholagogue action on a torpid liver.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP76', 'Minor', 'Fever management: a warm diaphoretic traditionally used to reduce fevers.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP08', 'Minor', 'Poor wound healing: external styptic and antiseptic wash for small wounds.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H233', 'CP18', 'Minor', 'Skin conditions: external poultice and wash for skin complaints, dandruff, and scalp.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P05', 'Primary', 'Infusion (bitter tea) of the dried leafy tops, the common internal form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P01', 'Primary', 'Tincture of the dried or fresh herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P03', 'Secondary', 'Powdered herb, historically given to children for worms in honey or syrup.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P08', 'Minor', 'Poultice of the herb for skin and small wounds.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P11', 'Minor', 'Fomentation, wash, or bath for skin, wounds, and as a hair and scalp rinse.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H233', 'P13', 'Minor', 'Essential oil, external and aromatic use only, never internal (thujone).');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H233', 'C04', 'Indicated', 'Primary', 'Phlegmatic (cold-damp-torpid): wakes and tones the cold, sluggish, atonic, worm-prone digestive and hepatic type.', '{"title": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "locator": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "locator": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
