INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H233', 'D03', 'Primary', 'Kapha: warm, dry, bitter, pungent, decongesting; drains cold, damp, torpid Kapha and its worms and sluggish digestion.', '{"title": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "locator": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "locator": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
