INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H233', 'TCM06', 'Secondary', 'Blood deficiency: a blood- and menses-moving emmenagogue is wrong in a blood-depleted patient.', '{"title": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "locator": "Grieve, A Modern Herbal (1931) - Southernwood (Artemisia abrotanum): tonic, emmenagogue, anthelmintic, antiseptic, deobstruent, and stimulant; the powdered herb given to children to expel worms, an infusion used to promote menstruation, and", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "locator": "Culpeper, The Complete Herbal (1653) - Southernwood (a hot, dry herb of Mercury; kills worms, provokes the terms/menses, resists poison). Dioscorides, De Materia Medica (1st c. AD) - abrotonon (used against worms and to provoke menses in an", "source_id": "S08", "author": "Culpeper \u2014 Complete Herbal", "year": "1653", "url": "https://www.gutenberg.org/ebooks/49513", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1084', 'H233', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Long-standing, consistent use as an emmenagogue and uterine stimulant to bring on suppressed menses, with a reputed abortifacient action; the herb also contains thujone, a compound restricted in pregnancy.', 'Do not use in any medicinal amount during pregnancy. Evaluate and exclude pregnancy before an emmenagogue is considered for absent menses.', 'AHPA Botanical Safety Handbook (2nd ed.), emmenagogue/uterine-stimulant Artemisia contraindicated in pregnancy; Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1085', 'H233', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable data on transfer of constituents into breast milk or on infant effects; thujone content argues for caution.', 'Avoid medicinal use while breastfeeding unless directed by a qualified practitioner.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1086', 'H233', 'condition', 'Epilepsy and other seizure disorders', 'moderate', 'Thujone in the volatile oil is a GABA-A antagonist and proconvulsant that can lower the seizure threshold.', 'Avoid in epilepsy or any seizure disorder; keep to low, short-course doses of the dilute herb and never the essential oil.', 'AHPA Botanical Safety Handbook (2nd ed.); EMA public statement on thujone; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1087', 'H233', 'drug_interaction', 'Antiepileptic drugs, alcohol, and other CNS-active agents', 'moderate', 'Proconvulsant thujone may oppose anticonvulsant control, and its central-nervous effects may be additive with or amplified by alcohol and other CNS-active drugs.', 'Avoid with antiepileptic medication; avoid concurrent heavy alcohol use; use cautiously with sedatives or other CNS-active agents.', 'Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, The Essential Guide to Herbal Safety; EMA public statement on thujone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1088', 'H233', 'condition', 'Allergy to ragweed and other Asteraceae', 'moderate', 'As an Asteraceae member it can provoke contact dermatitis and cross-sensitivity in people allergic to ragweed, chamomile, or other daisies.', 'Avoid or patch-test in those with known Asteraceae/ragweed allergy, especially for topical use.', 'AHPA Botanical Safety Handbook (2nd ed.); Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1089', 'H233', 'other', 'Concentrated essential oil and high-dose or prolonged use', 'moderate', 'Thujone is a neurotoxin and convulsant in excess; the concentrated oil and large or prolonged doses carry the greatest risk.', 'Do not take the essential oil internally; keep to ordinary medicinal amounts and short courses.', 'AHPA Botanical Safety Handbook (2nd ed.); EMA public statement on thujone.');
