INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H234', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS17', 'Primary', 'Cold: warms a cold, sluggish, gas-bound digestion and a cold, damp chest.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS09', 'Primary', 'Laxity: an aromatic astringent that tightens a loose, boggy, over-relaxed bowel (simple diarrhea).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS07', 'Secondary', 'Dampness: a warming, drying aromatic that dries damp digestion and cold, damp catarrh.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS08', 'Secondary', 'Stagnation: disperses trapped wind, flatulence, and gas-bound distension.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS18', 'Secondary', 'Tension: eases the colicky, cramping spasm of flatulent colic.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS23', 'Minor', 'Phlegm: a warm aromatic expectorant loosening cold, damp phlegm in the chest.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS05', 'Primary', 'Excess heat: a warm, pungent aromatic stimulant aggravates hot, irritated states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS03', 'Primary', 'Dryness: a warming, drying, astringent herb deepens frank dryness and fluid deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H234', 'TS06', 'Secondary', 'Acute inflammation: a carvacrol-rich aromatic can irritate hot, inflamed mucosa, especially as the oil.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H234', 'SY08', 'Primary', 'Digestive: warming carminative and aromatic digestive for a cold, gas-bound, atonic gut; gentle astringent for a loose bowel.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H234', 'SY07', 'Secondary', 'Respiratory: warming aromatic expectorant and diaphoretic for cold, damp coughs, catarrh, and cold onset.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H234', 'SY03', 'Secondary', 'Reproductive: traditional emmenagogue and folk aphrodisiac.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H234', 'SY10', 'Minor', 'Integumentary: topical antimicrobial wash and sting rub.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A17', 'Primary', 'Carminative: the defining action; disperses flatulent colic, trapped wind, and gas.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A10', 'Primary', 'Antispasmodic: eases colicky intestinal cramping and spasm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A15', 'Secondary', 'Astringent: tightens a loose, lax bowel; the traditional remedy for simple diarrhea.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A12', 'Secondary', 'Expectorant: a warming aromatic loosening cold, damp phlegm from the chest.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A28', 'Secondary', 'Antimicrobial: carvacrol and thymol give real antibacterial and antifungal activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A18', 'Minor', 'Diaphoretic: a hot infusion promotes a mild sweat at the onset of a cold.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A16', 'Minor', 'Aromatic digestive tonic: kindles appetite and digestive fire in cold, torpid digestion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A19', 'Minor', 'Emmenagogue: a traditional menses-promoting use (grounds the pregnancy caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H234', 'A25', 'Minor', 'Antioxidant: rosmarinic and caffeic acids and the phenolic oil are antioxidant.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP54', 'Primary', 'Bloating and flatulence: flatulent colic and trapped wind, the headline carminative use.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP12', 'Primary', 'Digestive upset: cold, sluggish, gassy, atonic digestion after heavy meals.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP56', 'Secondary', 'Diarrhea: simple, non-inflammatory loose bowel (aromatic astringent).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP58', 'Secondary', 'Dyspepsia/low digestive fire: poor appetite and torpid, fermentative digestion.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP39', 'Secondary', 'Muscular tension/spasm: colicky intestinal cramping and spasm.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP41', 'Minor', 'Cold/flu onset: a hot infusion warms and promotes a mild sweat at the first chill.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP51', 'Minor', 'Bronchial congestion: cold, damp cough and catarrh (warming expectorant).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP52', 'Minor', 'Sore throat: warm aromatic gargle and antimicrobial rinse.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H234', 'CP05', 'Minor', 'Low libido: the classical folk-aphrodisiac reputation of the satyr herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P05', 'Primary', 'Infusion (tea) of the dried herb, hot for colds and warm for flatulent colic.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P12', 'Primary', 'Added to soups, beans, and rich dishes as a culinary carminative (the bean herb).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P01', 'Secondary', 'Tincture of the herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P03', 'Secondary', 'Powdered dried herb blended into food.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P10', 'Minor', 'Warm infusion as a gargle and mouth rinse for sore throat.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H234', 'P13', 'Minor', 'Essential oil, well diluted, for topical antimicrobial use only.');
