INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H234', 'TCM11', 'Secondary', 'Heat/Fire: its warmth aggravates heat, fire, and Damp-Heat.', '{"title": "Grieve, A Modern Herbal (1931), Savory (Summer), Satureja hortensis. Supported by Culpeper''s Complete Herbal (1653), Savory, for the classical hot-and-dry energetics and the carminative, expectorant, and aphrodisiac tradition.", "locator": "Grieve, A Modern Herbal (1931), Savory (Summer), Satureja hortensis. Supported by Culpeper''s Complete Herbal (1653), Savory, for the classical hot-and-dry energetics and the carminative, expectorant, and aphrodisiac tradition.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Review of Natural Products (drugs.com), Savory monograph; WebMD and RxList Summer Savory monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, ", "locator": "Review of Natural Products (drugs.com), Savory monograph; WebMD and RxList Summer Savory monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, ", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1090', 'H234', 'pregnancy', 'Pregnancy', 'moderate', 'Longstanding traditional use as an emmenagogue (menses-promoting) herb, with insufficient modern data to establish safety of medicinal or essential-oil doses in pregnancy.', 'Avoid therapeutic and essential-oil doses throughout pregnancy. Ordinary culinary seasoning use is regarded as safe.', 'WebMD and RxList summer savory monographs (Natural Medicines Comprehensive Database): not enough reliable information, avoid use. Review of Natural Products (drugs.com) Savory: traditional emmenagogue use.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1091', 'H234', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable data on the safety of medicinal summer savory during breastfeeding.', 'Avoid therapeutic and essential-oil doses while nursing; ordinary culinary use is a much smaller, accepted exposure.', 'WebMD and RxList summer savory monographs (Natural Medicines Comprehensive Database): not enough reliable information, avoid use.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1092', 'H234', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Summer savory may slow blood clotting, adding to the bleeding and bruising risk of these agents.', 'Use medicinal and essential-oil doses cautiously with these drugs; monitor for bruising or bleeding, and stop summer savory at least two weeks before scheduled surgery.', 'WebMD and RxList summer savory monographs (Natural Medicines Comprehensive Database), Moderate interaction with anticoagulant/antiplatelet drugs; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1093', 'H234', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Extracts inhibit alpha-glucosidase and lower blood glucose in laboratory studies, giving a theoretical additive hypoglycemic effect.', 'Monitor blood glucose if medicinal doses are used with antidiabetic therapy; adjust as needed with the prescriber.', 'Phytochemistry and bioactivity review of Satureja hortensis and Satureja montana, PMC12435695 (2024): alpha-glucosidase inhibition and glucose-lowering activity.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1094', 'H234', 'condition', 'Bleeding disorders and scheduled surgery', 'moderate', 'Antiplatelet, clotting-slowing activity aggravates a bleeding tendency and adds perioperative bleeding risk.', 'Avoid medicinal and essential-oil doses in active bleeding disorders; discontinue at least two weeks before surgery.', 'WebMD and RxList summer savory precautions; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1095', 'H234', 'other', 'Undiluted essential oil', 'moderate', 'The concentrated carvacrol-thymol essential oil is a strong skin and mucous-membrane irritant.', 'Never use the undiluted oil on skin or mucosa or internally; dilute well (about one percent) for topical antimicrobial use only.', 'WebMD and RxList summer savory monographs: undiluted oil is very irritating and should not be used.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H234', 'EP01', 'neutral', 1, 1, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb damp rebalances the pattern''s dry', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Savory (Summer), Satureja hortensis. Supported by Culpeper''s Complete Herbal (1653), Savory, for the classical hot-and-dry energetics and the carminative, expectorant, and aphrodisiac tradition.", "locator": "Grieve, A Modern Herbal (1931), Savory (Summer), Satureja hortensis. Supported by Culpeper''s Complete Herbal (1653), Savory, for the classical hot-and-dry energetics and the carminative, expectorant, and aphrodisiac tradition.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Review of Natural Products (drugs.com), Savory monograph; WebMD and RxList Summer Savory monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, ", "locator": "Review of Natural Products (drugs.com), Savory monograph; WebMD and RxList Summer Savory monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, ", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, true);
