INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H235', 'TCM11', 'Secondary', 'Heat/Fire: its warmth aggravates heat, fire, and Damp-Heat.', '{"title": "Grieve, A Modern Herbal (1931), Marjoram (Sweet), Origanum majorana (Majorana hortensis). Supported by Culpeper''s Complete Herbal (1653), Sweet Marjoram, for the hot-and-dry Mercurial energetics and the nervine, carminative, emmenagogue, he", "locator": "Grieve, A Modern Herbal (1931), Marjoram (Sweet), Origanum majorana (Majorana hortensis). Supported by Culpeper''s Complete Herbal (1653), Sweet Marjoram, for the hot-and-dry Mercurial energetics and the nervine, carminative, emmenagogue, he", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, for the antiplatelet and diuretic-lithium cautions; Mills and B", "locator": "WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database) for modern safety and interaction data; Brinker, Herbal Contraindications and Drug Interactions, for the antiplatelet and diuretic-lithium cautions; Mills and B", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1096', 'H235', 'pregnancy', 'Pregnancy', 'moderate', 'Longstanding emmenagogue (menses-promoting) reputation; rated possibly unsafe in medicinal amounts because it might stimulate menstruation and threaten the pregnancy.', 'Avoid therapeutic and essential-oil doses throughout pregnancy. Ordinary culinary seasoning use is regarded as safe.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database): possibly unsafe in medicinal amounts, may start menstruation.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1097', 'H235', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient reliable data on the safety of medicinal marjoram during breastfeeding.', 'Avoid therapeutic and essential-oil doses while nursing; keep to ordinary culinary amounts.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database): not enough reliable information, stick to food amounts.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1098', 'H235', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, NSAIDs)', 'moderate', 'Marjoram may slow blood clotting, adding to the bleeding and bruising risk of these agents.', 'Use medicinal and essential-oil doses cautiously with these drugs; monitor for bruising or bleeding, and stop marjoram at least two weeks before scheduled surgery.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database), Moderate interaction; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1099', 'H235', 'drug_interaction', 'Antidiabetes drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Marjoram may lower blood sugar, so combined with these drugs it could push blood glucose too low.', 'Monitor blood glucose if medicinal doses are used with antidiabetic therapy; adjust with the prescriber as needed.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database), Moderate interaction: blood sugar may go too low.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1100', 'H235', 'drug_interaction', 'Lithium', 'moderate', 'Marjoram can act as a mild diuretic and may reduce lithium clearance, raising lithium levels toward toxicity.', 'Use medicinal doses only with prescriber oversight and lithium-level monitoring.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database): diuretic effect may increase lithium levels.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1101', 'H235', 'drug_interaction', 'Anticholinergic and cholinergic drugs', 'moderate', 'Marjoram has cholinergic, acetylcholinesterase-inhibiting activity and may blunt the effect of anticholinergic (drying) drugs while adding to the effects of cholinergic ones.', 'Use cautiously with anticholinergic or cholinergic medications and watch for altered response.', 'WebMD and RxList Marjoram monographs (Natural Medicines Comprehensive Database): Moderate interactions with anticholinergic and cholinergic drugs.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1102', 'H235', 'condition', 'Bleeding disorders and scheduled surgery', 'moderate', 'Clotting-slowing activity aggravates a bleeding tendency and adds perioperative bleeding risk.', 'Avoid medicinal and essential-oil doses in active bleeding disorders; discontinue at least two weeks before surgery.', 'WebMD and RxList Marjoram precautions (Natural Medicines Comprehensive Database); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1103', 'H235', 'other', 'Undiluted essential oil and fresh herb (eyes and sensitive skin)', 'moderate', 'The concentrated essential oil and the fresh herb can irritate the eyes and mucous membranes and cause contact dermatitis on sensitive skin.', 'Never use the undiluted oil internally or neat on skin or mucosa; dilute well for topical use and keep it away from the eyes.', 'WebMD and RxList Marjoram monographs: applying fresh marjoram or the concentrated oil may cause eye or skin irritation.');
