INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H236', 'TCM01', 'Minor', 'Kidney Yang deficiency: cooling and draining, wrong for a cold, yang-depleted constitution.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Aletris (Aletris farinosa). The entry classes it as a simple bitter tonic and stomachic for flatulence, colic, borborygmi, and dyspepsia, and explicitly warns that the commercial drug s", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Aletris (Aletris farinosa). The entry classes it as a simple bitter tonic and stomachic for flatulence, colic, borborygmi, and dyspepsia, and explicitly warns that the commercial drug s", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (Aletris farinosa), for the uterine-tonic and debility uses and the note that large doses are narcotic, emetic, and cathartic; Grieve, A Modern Herbal (1931), Unicorn-root,", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (Aletris farinosa), for the uterine-tonic and debility uses and the note that large doses are narcotic, emetic, and cathartic; Grieve, A Modern Herbal (1931), Unicorn-root,", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1104', 'H236', 'pregnancy', 'Pregnancy', 'absolute', 'Estrogen-like activity that may affect the pregnancy, plus a traditional uterine-stimulant reputation; constituents poorly characterized.', 'Avoid throughout pregnancy. The historical Eclectic use in threatened miscarriage rests on uncontrolled reports and on confusion with false unicorn (Chamaelirium) and is not supported by modern safety data.', 'WebMD/RxList Aletris monograph (possibly unsafe in pregnancy); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1105', 'H236', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient safety data in lactation combined with demonstrated estrogen-like activity.', 'Avoid while breastfeeding.', 'WebMD/RxList Aletris monograph (best to avoid if breast-feeding); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1106', 'H236', 'condition', 'Hormone-sensitive conditions (breast, uterine, or ovarian cancer, endometriosis, uterine fibroids)', 'moderate', 'Estrogen-like activity may stimulate estrogen-sensitive tissue.', 'Avoid in estrogen-dependent conditions.', 'WebMD/RxList Aletris monograph; Natural Medicines/Drugs.com Aletris monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1107', 'H236', 'drug_interaction', 'Estrogens and hormonal therapy (HRT, hormonal contraceptives)', 'moderate', 'Estrogen-like effects of Aletris may add to or interfere with estrogen therapy.', 'Avoid combining; use caution and monitor in any hormone-sensitive context.', 'WebMD/RxList Aletris interactions (moderate); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1108', 'H236', 'drug_interaction', 'Acid-reducing drugs (antacids, H2-blockers, proton-pump inhibitors)', 'low', 'As a bitter stomachic Aletris may increase gastric acid secretion and could blunt acid-suppressing therapy.', 'Separate dosing and monitor for reduced antacid effect or dyspepsia.', 'WebMD/RxList Aletris interactions (minor).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1109', 'H236', 'other', 'Fresh or undried root, and large doses', 'moderate', 'The fresh root and large doses are narcotic, emetic, and cathartic (acrid principle), causing vertigo, vomiting, purging, and hypogastric colic.', 'Use only the properly dried root in small, tonic doses.', 'Ellingwood, American Materia Medica; Grieve, A Modern Herbal (1931).');
