INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H237', 'TCM11', 'Secondary', 'Heat/Fire: warming, pressor, cardioactive nature aggravates full heat and ascendant yang.', '{"title": "Felter HW, Lloyd JU, King''s American Dispensatory (1898), Scoparius (broom tops): diuretic and cathartic, used in all chronic forms of dropsy, said almost never to fail in increasing the flow of urine, and especially useful in dropsy of the", "locator": "Felter HW, Lloyd JU, King''s American Dispensatory (1898), Scoparius (broom tops): diuretic and cathartic, used in all chronic forms of dropsy, said almost never to fail in increasing the flow of urine, and especially useful in dropsy of the", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "German Commission E Monograph, Broom flower (Cytisus scoparius), approved for functional heart and circulatory disorders; AHPA Botanical Safety Handbook (2nd ed., Gardner & McGuffin, 2013); Brinker F, Herbal Contraindications and Drug Inter", "locator": "German Commission E Monograph, Broom flower (Cytisus scoparius), approved for functional heart and circulatory disorders; AHPA Botanical Safety Handbook (2nd ed., Gardner & McGuffin, 2013); Brinker F, Herbal Contraindications and Drug Inter", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1110', 'H237', 'pregnancy', 'Pregnancy', 'absolute', 'Sparteine is a potent oxytocic/uterine stimulant (a former labor-inducing drug) and is regarded as an abortifacient.', 'Do not use in any form during pregnancy.', 'AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker, Herbal Contraindications and Drug Interactions (2010); German Commission E.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1111', 'H237', 'breastfeeding', 'Breastfeeding', 'moderate', 'Active alkaloids (sparteine) and pressor amines (tyramine) with no reliable human safety data in lactation.', 'Avoid therapeutic use while breastfeeding.', 'Brinker, Herbal Contraindications and Drug Interactions (2010); AHPA Botanical Safety Handbook (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1112', 'H237', 'drug_interaction', 'MAO inhibitors (isocarboxazid, phenelzine, tranylcypromine)', 'absolute', 'Broom''s tyramine content can precipitate a hypertensive crisis with monoamine oxidase inhibition.', 'Do not combine broom with any MAOI; observe the standard MAOI/tyramine washout.', 'Brinker, Herbal Contraindications and Drug Interactions (2010); drugs.com Natural Products Database (Broom).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1113', 'H237', 'drug_interaction', 'Cardiac/antiarrhythmic drugs (digoxin, beta-blockers, calcium channel blockers, antiarrhythmics)', 'absolute', 'Sparteine alters cardiac conduction in a quinidine-like (class 1A) manner, giving additive, potentially hazardous effects on heart rate and rhythm.', 'Avoid combining broom with rhythm- or rate-altering cardiac drugs except under strict medical supervision.', 'drugs.com Natural Products Database (Broom); Brinker (2010).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1114', 'H237', 'condition', 'Hypertension / abnormal blood pressure', 'absolute', 'Tyramine and the alkaloids can raise blood pressure; broom is contraindicated in hypertension.', 'Do not use in hypertensive patients or those on antihypertensive therapy.', 'German Commission E; Brinker, Herbal Contraindications and Drug Interactions (2010).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1115', 'H237', 'condition', 'Cardiac conduction disorders / AV block / serious arrhythmia', 'moderate', 'Sparteine''s class 1A-like action on cardiac conduction can worsen block or provoke arrhythmia.', 'Avoid in conduction disease and use cardioactive dosing only under specialist cardiac supervision.', 'German Commission E; drugs.com Natural Products Database (Broom).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1116', 'H237', 'drug_interaction', 'CYP2D6 inhibitors / CYP2D6 poor metabolizers', 'moderate', 'Sparteine is a classic CYP2D6 probe substrate; impaired CYP2D6 metabolism raises sparteine exposure and toxicity risk.', 'Use extra caution (or avoid) in CYP2D6 poor metabolizers and with CYP2D6-inhibiting drugs.', 'drugs.com Natural Products Database (Broom); clinical pharmacology of sparteine (CYP2D6 probe).');
