INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H238', 'C06', 'Indicated', 'Primary', 'Calms the robust, hot, irritable, agitated (Pitta-like) type.', '{"title": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "locator": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "locator": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H238', 'C05', 'Indicated', 'Secondary', 'Grounds, nourishes, and rebuilds the thin, dry, depleted, nervous (Vata-like) mind.', '{"title": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "locator": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "locator": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
