INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1117', 'H238', 'drug_interaction', 'Thyroid-hormone therapy (levothyroxine) and hypothyroidism', 'moderate', 'Convolvulus pluricaulis inhibits peripheral T4-to-T3 conversion (hepatic 5''-deiodinase) and lowers serum T3, so it can antagonize levothyroxine, blunt thyroid function, and worsen hypothyroidism.', 'Avoid in hypothyroidism and alongside thyroid-hormone therapy unless supervised; monitor thyroid labs (TSH, free T3/T4) with prolonged use.', 'Panda and Kar, Hormone and Metabolic Research 2001 (PubMed 11280709); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1118', 'H238', 'drug_interaction', 'CNS depressants (benzodiazepines, barbiturates, opioids, sedating antihistamines, sedative herbs, alcohol)', 'moderate', 'Additive central nervous system depression; C. pluricaulis has documented CNS-depressant activity and potentiates barbiturate hypnosis.', 'Avoid combining or use only under supervision; warn about drowsiness and impaired alertness for driving.', 'CNS-depressant and anti-anxiety study, PubMed 36825716; Brinker; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1119', 'H238', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Additive blood-pressure lowering; the leaves and flowers have documented hypotensive activity.', 'Use cautiously with antihypertensives and in those already hypotensive; monitor blood pressure.', 'Frontiers in Pharmacology review 2020 (PMC7063970); Brinker; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1120', 'H238', 'pregnancy', 'Pregnancy', 'moderate', 'No modern reproductive-toxicology or human pregnancy data; documented antithyroid, hypotensive, and CNS-depressant activities are theoretical concerns.', 'Avoid in pregnancy unless supervised; prefer better-studied options if a calming or nootropic herb is needed.', 'NCCIH (insufficient-data principle); AHPA Botanical Safety Handbook 2nd ed. (not individually rated).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1121', 'H238', 'breastfeeding', 'Breastfeeding', 'moderate', 'No human lactation data and no NIH LactMed monograph; sedative and antithyroid constituents could in theory reach the infant.', 'Avoid or use only under professional supervision; safety not established.', 'NIH LactMed (no monograph on record); NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1122', 'H238', 'pediatric', 'Children (prolonged or unsupervised use)', 'moderate', 'Traditionally used as a children''s memory tonic and generally gentle, but modern pediatric safety is unestablished and the antithyroid action counsels caution with long-term use.', 'Use age-appropriate low doses under a qualified practitioner; avoid unsupervised long-term use.', 'NCCIH (insufficient-data principle).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1123', 'H238', 'other', 'Major surgery / general anesthesia', 'moderate', 'Additive CNS-depressant and hypotensive effects with anesthetic agents.', 'Discontinue at least one to two weeks before scheduled surgery.', 'Brinker; Mills and Bone (general sedative-botanical peri-operative principle).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1124', 'H238', 'other', 'Adulteration and substitution under the name Shankhpushpi', 'moderate', 'At least four unrelated plants (Convolvulus pluricaulis, Evolvulus alsinoides, Clitoria ternatea, Canscora decussata) are traded as Shankhpushpi, so an unauthenticated product may not be this species.', 'Source correctly identified, authenticated material of known botanical origin.', 'Frontiers in Pharmacology review 2020 (PMC7063970); Sethiya et al. (PubMed 25182446).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H238', 'EP01', 'match', 3, 0, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "locator": "Charaka Samhita (c. 1st to 2nd century CE), where Shankhpushpi is named among (and, by the classical maxim medhyanam Shankhapushpi shreshtha, foremost of) the medhya rasayana brain-and-intellect tonics; corroborated in the Ayurvedic Pharmac", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "locator": "Sethiya et al., An update on Shankhpushpi, a cognition-boosting Ayurvedic medicine (PubMed 25182446); Balkrishna et al., Phytochemical Profile, Pharmacological Attributes and Medicinal Properties of Convolvulus prostratus, Frontiers in Phar", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null, "kind": "pubmed"}'::jsonb, true);
