INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H239', 'TCM03', 'Minor', 'Spleen Qi deficiency (without damp-heat): heavy or prolonged use of a cold bitter can weaken the digestive fire.', '{"title": "Grieve, M., A Modern Herbal (1931), ''Artichoke, Globe'' (Cynara scolymus), recording its traditional use as a bitter, diuretic, and liver-supporting plant of the Mediterranean.", "locator": "Grieve, M., A Modern Herbal (1931), ''Artichoke, Globe'' (Cynara scolymus), recording its traditional use as a bitter, diuretic, and liver-supporting plant of the Mediterranean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "European Medicines Agency (EMA/HMPC), European Union herbal monograph on Cynara cardunculus L. (syn. C. scolymus L.), folium (artichoke leaf), traditional use for dyspeptic complaints; ESCOP Monographs, Cynarae folium; German Commission E, ", "locator": "European Medicines Agency (EMA/HMPC), European Union herbal monograph on Cynara cardunculus L. (syn. C. scolymus L.), folium (artichoke leaf), traditional use for dyspeptic complaints; ESCOP Monographs, Cynarae folium; German Commission E, ", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1125', 'H239', 'condition', 'Bile-duct obstruction, gallstones lodged in the duct, cholangitis, or other biliary disorders', 'absolute', 'Artichoke''s choleretic and cholagogue action increases bile production and flow; forcing bile against an obstruction can provoke biliary colic and harm.', 'Do not use therapeutically with bile-duct obstruction or biliary disease; where gallstones are present, use only on medical advice. Refer any jaundice, severe right-upper-quadrant pain, or fever with abdominal pain.', 'EMA/HMPC European Union herbal monograph, Cynarae folium; ESCOP Monographs, Cynarae folium; Drugs.com/Natural Medicines, Artichoke; PeaceHealth, Artichoke.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1126', 'H239', 'other', 'Asteraceae/Compositae allergy (ragweed, daisies, chrysanthemums, marigolds)', 'absolute', 'Sesquiterpene lactones such as cynaropicrin cross-react in Compositae-sensitive individuals, causing itching, rash, contact dermatitis, and rarely more serious reactions.', 'Avoid in known allergy to artichoke or other Asteraceae plants; discontinue at any sign of allergic reaction and seek care for severe reactions.', 'WebMD, Artichoke; EMA/HMPC Cynarae folium; AHPA Botanical Safety Handbook (Cynara).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1127', 'H239', 'pregnancy', 'Pregnancy (therapeutic leaf-extract doses)', 'moderate', 'No adequate controlled human safety data for concentrated artichoke leaf extract in pregnancy.', 'Avoid therapeutic leaf-extract doses in pregnancy unless supervised by a qualified practitioner; culinary amounts of the vegetable are considered food-safe.', 'Drugs.com/Natural Medicines, Artichoke; PeaceHealth, Artichoke.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1128', 'H239', 'breastfeeding', 'Breastfeeding (therapeutic leaf-extract doses)', 'moderate', 'No reliable safety data for concentrated artichoke leaf extract during lactation.', 'Avoid concentrated extracts while nursing without professional guidance; culinary artichoke is rated low risk as a food.', 'Drugs.com/Natural Medicines, Artichoke; e-lactation.com, Artichoke.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1129', 'H239', 'drug_interaction', 'Antidiabetic and lipid-lowering drugs; anticoagulant/antiplatelet drugs (theoretical)', 'low', 'Additive glucose- and cholesterol-lowering with antidiabetics and statins; a weakly evidenced theoretical additive bleeding risk with anticoagulants.', 'Monitor blood sugar and lipids if combining; note the theoretical caution with anticoagulants. Interaction data are limited and mostly theoretical.', 'WebMD, Artichoke; Drugs.com/Natural Medicines, Artichoke.');
