INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H240', 'TCM11', 'Secondary', 'Heat/Fire: its warmth aggravates heat, fire, and acute inflammation.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "locator": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1130', 'H240', 'pregnancy', 'Pregnancy', 'absolute', 'Traditional emmenagogue and uterine stimulant; ethanolic Ferula assa-foetida extract prevented implantation in animal studies, and its blood-moving action adds theoretical risk. Modern consumer-safety references cite a miscarriage concern.', 'Avoid medicinal doses and deliberate therapeutic use throughout pregnancy. Ordinary trace culinary hing in cooked food is a much smaller exposure but is best minimized.', 'WebMD/RxList asafoetida monograph (likely unsafe, miscarriage risk); AHPA Botanical Safety Handbook, 2nd ed. (Ferula assa-foetida); anti-implantation data in Mahendra and Bisht, Pharmacognosy Reviews 2012.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1131', 'H240', 'breastfeeding', 'Breastfeeding', 'moderate', 'Constituents may pass into breast milk; the sulphur compounds can cause blood disorders (methemoglobinemia) in a susceptible nursing infant.', 'Avoid medicinal doses while nursing; occasional trace culinary hing in the mother''s cooked food is a far smaller, traditionally accepted exposure.', 'WebMD/RxList asafoetida monograph (unsafe while breastfeeding); infant methemoglobinemia case, Al-Qahtani et al., PMC6945318.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1132', 'H240', 'other', 'Infants and young children', 'absolute', 'Sulphur constituents are potent oxidants; infants under about four months have reduced methemoglobin-reductase activity and easily-oxidized fetal hemoglobin. Documented severe methemoglobinemia (66.9 percent) in a three-month-old given the gum-resin for colic.', 'Never give asafoetida to infants, and do not use it for infantile colic. In older children avoid concentrated medicinal doses; only diluted culinary amounts.', 'Al-Qahtani et al., severe methemoglobinemia secondary to Ferula asafoetida ingestion in an infant, PMC6945318; WebMD/RxList (unsafe in infants).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1133', 'H240', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel, DOACs)', 'moderate', 'Coumarin and ferulic-acid constituents can slow blood clotting, adding to the bleeding risk of these agents.', 'Use cautiously and monitor for bruising or bleeding; stop asafoetida at least two weeks before scheduled surgery.', 'Brinker, Herbal Contraindications and Drug Interactions; WebMD/RxList asafoetida interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1134', 'H240', 'drug_interaction', 'Antihypertensive drugs (ACE inhibitors, ARBs, calcium-channel blockers, diuretics)', 'moderate', 'Asafoetida lowers blood pressure and can produce additive hypotension when combined with blood-pressure-lowering medication.', 'Monitor blood pressure; avoid combined use if prone to hypotension or lightheadedness.', 'WebMD/RxList asafoetida interactions; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1135', 'H240', 'condition', 'Bleeding disorders, hypotension, G6PD deficiency, and scheduled surgery', 'moderate', 'Antiplatelet and hypotensive activity aggravate bleeding tendency and low blood pressure; oxidant sulphur constituents raise hemolysis and methemoglobinemia risk in G6PD deficiency.', 'Avoid in active bleeding disorders, marked hypotension, and known G6PD deficiency; discontinue at least two weeks before surgery.', 'WebMD/RxList asafoetida precautions; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1136', 'H240', 'condition', 'Active gastritis, peptic ulcer, GERD, and acute inflammatory gut conditions', 'moderate', 'An acrid, heating gastric irritant; King''s American Dispensatory notes it is improper in inflammatory conditions of the system.', 'Avoid in active reflux, gastritis, and ulceration; take with food and in capsule to blunt gastric acridity when used.', 'King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (improper in inflammatory conditions); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H240', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "locator": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H240', 'EP02', 'avoid', 0, 3, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "locator": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
