INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H240', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Asafoetida (from Ferula foetida). Supported by Potter''s Compendium (Asafoetida) and Ellingwood''s American Materia Medica for the Eclectic clinical detail; the Chinese materia medica ent", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "locator": "Grieve, A Modern Herbal (1931), Asafetida; Mahendra and Bisht, Ferula asafoetida: traditional uses and pharmacological activity (Pharmacognosy Reviews, 2012); Iranmehr et al./Mills and Bone, Principles and Practice of Phytotherapy for the m", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H241', 'Cacao (Cocoa)', 'Theobroma cacao', 'Malvaceae (the mallow family; the genus Theobroma was historically placed in Sterculiaceae, now folded into a broadly circumscribed Malvaceae under the APG system)', 'Seed (the fermented, dried, and roasted bean, source of cocoa mass, cocoa powder, and cocoa butter). The surrounding fruit pulp is also traditionally eaten and juiced, but the medicinal and nutritive material is the seed.', 'Bitter and astringent, with a rich, roasted, faintly aromatic depth. The bitterness comes from the methylxanthines theobromine and caffeine and from polyphenols; the drawing, drying astringency comes from the flavanol tannins (procyanidins). Pure roasted cacao is markedly bitter; the sweetness of chocolate is added sugar, not the bean itself.', 'Warm. A bitter, stimulating seed whose methylxanthines rouse the circulation, heart, and nervous system and lift a cold, heavy, torpid state; the classical and Ayurvedic reading of chocolate is heating and stimulating. The warmth is kindling and dispersing rather than deeply nourishing, and it readily overheats an already hot or fiery person.', 'Dry. Despite the richness of its fat (cocoa butter), the medicinal action of the seed is drying: the astringent flavanol tannins tighten and dry the tissues, and theobromine is a genuine diuretic that promotes fluid loss. It is a warming, drying, bitter stimulant, not a moistening demulcent.', 'Torpor: the headline use, a warming bitter stimulant that rouses a cold, sluggish, heavy, low-energy torpor of body and mind. Depression (as a tissue state of low, flat, stuck vitality): a mood-elevating stimulant whose theobromine, phenylethylamine, and flavanols lift a heavy, downcast, stagnant mood. Stagnation of the peripheral and cerebral circulation, which the nitric-oxide-mediated vasodilation of cocoa flavanols helps to open. Exhaustion of a cold, depleted, mineral-poor kind, where cacao acts as a mineral-rich (magnesium, iron) nutritive stimulant, used sparingly rather than as a deep restorative.', 'Excitation: the central caution. A methylxanthine stimulant aggravates a wired, over-stimulated, anxious, restless, insomniac, or palpitation-prone state. Excess heat, which a warm stimulant fans into reflux, irritability, flushing, and migraine. Tension: it worsens a clenched, tense, headache-prone, agitated picture. Acute inflammation of an irritable gut or nervous system, where a bitter xanthine stimulant can inflame reflux and trigger migraine rather than soothe.', 'Cardiovascular first: the flavanol-rich circulatory herb, improving endothelial function, opening peripheral and cerebral blood flow, and gently lowering blood pressure, while theobromine mildly stimulates the heart. Nervous: a cerebral stimulant and mood-elevator that sharpens alertness and lifts low mood, and the same system that bears the over-stimulation caution. Digestive: a bitter that stimulates digestion, with theobromine giving a mild laxative and reflux-provoking tendency. Urinary: theobromine is a classic diuretic, once used for cardiac and renal edema. Respiratory: theobromine is a bronchodilator and cough-suppressant, related in action to theophylline.', 'Low, heavy, flat, stagnant mood and cold torpor of body and mind: the mood-lifting, rousing use. Functional hypertension and poor cardiovascular tone, where cocoa flavanols modestly lower blood pressure and improve endothelial function. Poor peripheral and cerebral circulation. Mental fog and cognitive dullness, helped by improved cerebral blood flow. Cold, sluggish fatigue (used sparingly, and wrong for wired or anxious exhaustion). Historically, a diuretic for fluid retention and a bronchodilator and cough remedy. It is a comfort and cardiovascular-support herb, not a treatment for the anxious, insomniac, reflux-prone, or migraine-prone, in whom it is the wrong remedy.', 'Cold-Damp-Relaxed and heavy: the cold, sluggish, torpid, low-spirited phlegmatic phenotype who runs heavy, foggy, and downcast and is roused by a warming bitter stimulant. It is the wrong remedy for the hot, dry, driven, irritable choleric and for the thin, wired, nervous, insomniac type, in whom a xanthine stimulant adds heat, dryness, and over-excitation.', 'Kapha', 'Pitta, Vata', 'Not a classical Chinese materia medica herb, but functionally a warm, bitter, aromatic stimulant that moves stagnant Qi and Blood, opens the circulation, and lifts a stuck, heavy, low mood (a Qi Stagnation picture with dampish torpor). Read through a TCM lens it warms, moves, and disperses rather than tonifies deeply, and as a stimulant it stirs the Shen.', 'Heat or Fire patterns, where a warm methylxanthine stimulant aggravates agitation, insomnia, flushing, and disturbed Shen. Yin deficiency with empty heat, where a drying stimulant deepens restlessness, night waking, and dryness. Any hot, hyper, or Shen-disturbed picture.', 'Cacao is a methylxanthine stimulant (theobromine, with smaller amounts of caffeine) and can cause insomnia, restlessness, anxiety, jitteriness, rapid or irregular heartbeat, and reflux, especially in sensitive people, children, and with large or late-day intake. It is a recognized migraine trigger for some people. Cocoa and cocoa powder, particularly dark chocolate and some raw cacao, can carry notable lead and cadmium, a concern with heavy or long-term use and in children. Its oxalate content is relevant to calcium-oxalate kidney-stone formers, and its methylxanthines can irritate the bladder in interstitial cystitis. Sweetened chocolate is high in sugar and fat. Theobromine is toxic to dogs and other pets, so keep it out of their reach.', 'Pregnancy and breastfeeding at large or concentrated doses (caffeine, theobromine, and heavy metals; keep total caffeine modest). Children in large amounts of dark or high-cocoa products (heavy metals and stimulant sleep disturbance). Anxiety, insomnia, cardiac arrhythmia or palpitations, uncontrolled hypertension, and gastroesophageal reflux, all of which a stimulant can worsen. Migraine-prone individuals for whom cacao is a trigger. Calcium-oxalate kidney stones and interstitial cystitis. Concurrent MAOI antidepressants (tyramine content), other stimulants, theophylline, and pharmacologic cardiac stress testing with adenosine or dipyridamole.', 'Possibly safe in moderate, food amounts; large or concentrated amounts are best avoided. Cocoa in the amounts commonly found in foods is regarded as possibly safe in pregnancy, but large amounts are possibly unsafe because of the caffeine and the lead and cadmium cocoa can contain. Total caffeine should be kept modest: ACOG advises less than 200 mg of caffeine per day in pregnancy, and cocoa (roughly 12 mg caffeine per tablespoon of powder, plus theobromine) counts toward that total. Concentrated cocoa-flavanol supplements in pregnancy are not well studied and are best avoided. (WebMD Cocoa monograph drawing on the Natural Medicines Comprehensive Database; ACOG guidance on moderate caffeine intake in pregnancy.)', 'Possibly safe in moderate, food amounts. Cocoa in ordinary food amounts is considered possibly safe while breastfeeding. Very large maternal intake is the concern: LactMed documents case reports in which mothers consuming very large quantities of chocolate or cocoa (on the order of 250 g of cocoa, or about 16 oz of chocolate, daily) had infants who became irritable, jittery, and had frequent stools from the caffeine and theobromine, resolving when intake was reduced. Keep to moderate amounts and watch the infant. (Drugs and Lactation Database (LactMed), Chocolate monograph; WebMD Cocoa monograph, Natural Medicines Comprehensive Database.)', 'Ordinary food amounts are generally tolerated, but dark chocolate and other high-cocoa products are possibly unsafe for children in quantity because they can contain high levels of lead and cadmium, and the methylxanthine stimulant can disturb sleep and cause jitteriness, rapid heartbeat, and reflux. Favor small food amounts, avoid concentrated cacao and dark-chocolate loads and late-day intake, and choose brands tested low in heavy metals. (WebMD Cocoa monograph, Natural Medicines Comprehensive Database, on heavy-metal content in children; independent heavy-metal testing of dark chocolate, Consumer Reports, 2022 to 2023; NCCIH general caution on concentrated botanicals in children.)', 'MAOI antidepressants (phenelzine, tranylcypromine, isocarboxazid): cacao contains tyramine, and in large amounts with an MAOI this can raise blood pressure, so keep intake modest (a Moderate-rated caution). Adenosine and dipyridamole used in pharmacologic cardiac stress testing: cocoa methylxanthines block adenosine receptors and can blunt the test, so cocoa and other caffeine sources are withheld before such testing (Moderate). Stimulant drugs (ephedrine, pseudoephedrine, amphetamines and ADHD stimulants): additive stimulation with raised heart rate and blood pressure (Moderate). Theophylline and other methylxanthines: additive xanthine effects and toxicity (Moderate). Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel): cocoa flavanols have a mild antiplatelet effect that may add to bleeding risk at high intake (Minor to Moderate). Lithium: the caffeine in cocoa has a diuretic action that can change lithium levels, so a marked change in intake warrants monitoring (Moderate). Antihypertensive and antidiabetic drugs: possible additive effects warranting monitoring (Minor). (WebMD Cocoa monograph, Natural Medicines Comprehensive Database; Brinker, Herbal Contraindications and Drug Interactions, for the methylxanthine and tyramine cautions.)', 'Traditional drinking chocolate, a decoction or hot beverage of the ground roasted bean or cocoa mass (the Mesoamerican preparation). Cocoa or cacao powder stirred into foods and drinks and used in savory dishes such as mole. Standardized cocoa-flavanol capsules or extracts for cardiovascular support. Powdered roasted nibs eaten as food. Tincture is uncommon and secondary. Choose minimally alkalized (non-Dutched) cocoa and dark, low-sugar chocolate to preserve the flavanols.', 'Culinary and nutritive: about 1 to 2 tablespoons (roughly 5 to 10 g) of natural cocoa or cacao powder daily, or a moderate square of dark chocolate. Cardiovascular flavanol studies have used cocoa providing on the order of 200 to 500 mg of cocoa flavanols per day; follow the label of a standardized product. Keep the stimulant load modest and avoid late-day dosing in the sensitive. There is no standardized medicinal dose, so favor the food and beverage forms, and prefer minimally processed, heavy-metal-tested cocoa.', 'Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.', 'Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine for the beneficial effects of cocoa consumption, Frontiers in Pharmacology (2015, PMC4335269); WebMD Cocoa monograph (Natural Medicines Comprehensive Database) and the Drugs and Lactation Database (LactMed) Chocolate monograph for modern safety and interactions; Brinker, Herbal Contraindications and Drug Interactions.', 'Family Malvaceae (the genus Theobroma was long placed in Sterculiaceae, now merged into a broadly defined Malvaceae). Cacao is a small evergreen tropical tree native to the Amazon basin and cultivated across Mesoamerica in antiquity. Linnaeus named the genus Theobroma, food of the gods (Greek theos, god, and broma, food), in 1753, echoing its sacred and ceremonial use among the Maya and Aztec, who drank it and used the beans as currency. Its chief actives are the methylxanthine theobromine (about 1 to 2 percent) with smaller caffeine; the flavanols epicatechin, catechin, and procyanidins (potent antioxidants and vasodilators); phenylethylamine and trace anandamide (mood effects); tyramine; the minerals magnesium, iron, and copper; and roughly half its weight as cocoa butter (mainly stearic, oleic, and palmitic fats). Cocoa flavanols are best evidenced for a modest lowering of blood pressure and improved endothelial and cognitive function. Raw and minimally processed cacao is highest in flavanols; Dutched (alkalized) cocoa and heavily sweetened chocolate contain far less. Note the heavy-metal (lead, cadmium) caution and that theobromine is toxic to dogs.', 'Not named in the canonical biblical texts. Cacao is a New World plant, unknown to the ancient Mediterranean and biblical world; it is native to tropical Central and South America and was a sacred and ceremonial plant of the Maya and Aztec, for whom it was a ritual beverage, a medicine, and a currency. Its botanical name Theobroma, food of the gods, coined by Linnaeus in 1753, preserves that Mesoamerican reverence rather than any scriptural reference.', 'Theobroma cacao is a widely cultivated tropical crop and is not a wild-at-risk species (not listed by United Plant Savers). The real stewardship concerns are ethical and ecological: cocoa production drives tropical deforestation, especially in West Africa, and is linked to child and forced labor, while heirloom criollo genetics are dwindling. Choose Fair Trade, Rainforest Alliance, or equivalently certified, shade-grown, and where possible organic cacao, and favor origins and brands that test low for cadmium and lead.', 'Warm and dry, bitter and stimulating: a flavanol-rich circulatory and cerebral stimulant that rouses a cold, heavy, torpid low mood, opens stagnant peripheral and cerebral blood flow, and gently lowers blood pressure, while over-stimulating anyone already hot, tense, or wired.', 'Refer for chest pain, palpitations, or an irregular or racing heartbeat; fainting; uncontrolled or severe high blood pressure; a severe, sudden, or persistent headache or migraine with neurological signs; severe anxiety, agitation, or insomnia; and any sign of methylxanthine or caffeine toxicity such as vomiting, tremor, marked tachycardia, or seizures (especially in a child or after a pet ingests chocolate). Persistent low mood or depression with hopelessness or suicidal thoughts needs professional care; cacao is a comfort and cardiovascular-support food, not a treatment for these conditions.', 'Cacao: kuh-KOW (also kuh-KAY-oh). Theobroma cacao: thee-oh-BROH-muh kuh-KOW.', 'free', 'Approved', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H241', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H241', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS19', 'Primary', 'Torpor: a warming bitter stimulant rousing cold, heavy, sluggish, low-energy dullness of body and mind.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS11', 'Primary', 'Depression: theobromine, phenylethylamine, and flavanols lift a flat, heavy, downcast, stagnant mood.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS08', 'Secondary', 'Stagnation: cocoa flavanols open stagnant peripheral and cerebral circulation via nitric-oxide vasodilation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS04', 'Minor', 'Exhaustion: a mineral-rich (magnesium, iron) nutritive stimulant for cold, depleted states, used sparingly.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS10', 'Primary', 'Excitation: a methylxanthine stimulant aggravates wired, anxious, restless, insomniac, palpitation-prone states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS05', 'Secondary', 'Excess heat: a warm stimulant fans reflux, flushing, irritability, and migraine.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS18', 'Secondary', 'Tension: worsens a clenched, tense, agitated, headache-prone picture.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H241', 'TS06', 'Minor', 'Acute inflammation: can inflame an irritable gut (reflux) or trigger migraine rather than soothe.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H241', 'SY06', 'Primary', 'Cardiovascular: flavanols improve endothelial function, open circulation, and lower blood pressure; theobromine stimulates the heart.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H241', 'SY01', 'Primary', 'Nervous: cerebral stimulant and mood-elevator, and the seat of the over-stimulation caution.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H241', 'SY08', 'Secondary', 'Digestive: a bitter that stimulates digestion, with a mild laxative and reflux-provoking tendency.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H241', 'SY09', 'Minor', 'Urinary: theobromine is a classic diuretic, historically used for cardiac and renal edema.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H241', 'SY07', 'Minor', 'Respiratory: theobromine is a bronchodilator and cough-suppressant, akin in action to theophylline.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A25', 'Primary', 'Antioxidant: cocoa flavanols (epicatechin, catechin, procyanidins) are potent antioxidants.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A37', 'Primary', 'Hypotensive: cocoa flavanols modestly lower blood pressure via nitric-oxide-mediated vasodilation (Cochrane).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A48', 'Secondary', 'Nootropic/Cerebral Tonic: improves cerebral blood flow, alertness, and cognition.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A08', 'Secondary', 'Diuretic: theobromine is a classic methylxanthine diuretic.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A16', 'Secondary', 'Bitter Tonic: bitter, stimulating to digestion and appetite in cold torpor.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A15', 'Secondary', 'Astringent: flavanol tannins (procyanidins) tighten and dry the tissues.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H241', 'A33', 'Minor', 'Antitussive: theobromine suppresses cough and dilates the bronchi.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP11', 'Primary', 'Depression: mood-lifting stimulant for a heavy, flat, downcast, stagnant mood.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP44', 'Primary', 'Hypertension (functional): cocoa flavanols modestly lower blood pressure and improve endothelial function.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP47', 'Secondary', 'Poor peripheral circulation: flavanol vasodilation opens stagnant peripheral and cerebral blood flow.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP24', 'Secondary', 'Mental fog/cognitive dullness: improved cerebral blood flow sharpens alertness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP07', 'Secondary', 'Fatigue: a stimulant and mineral-rich nutritive for cold, sluggish tiredness (wrong for wired exhaustion).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP50', 'Minor', 'Cough dry/unproductive: theobromine has documented antitussive and bronchodilator activity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H241', 'CP66', 'Minor', 'Fluid retention: theobromine is a traditional diuretic.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H241', 'P04', 'Primary', 'Decoction: traditional drinking chocolate of the ground roasted bean or cocoa mass.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H241', 'P12', 'Primary', 'Added to food and drink (cocoa powder, savory mole), the everyday culinary and nutritive form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H241', 'P03', 'Secondary', 'Powder: natural (non-Dutched) cocoa or cacao powder, higher in flavanols.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H241', 'P02', 'Secondary', 'Capsule: standardized cocoa-flavanol extract for cardiovascular support.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H241', 'P01', 'Minor', 'Tincture: uncommon and secondary for this seed.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H241', 'C04', 'Indicated', 'Primary', 'Phlegmatic: the cold, heavy, damp, torpid, low-spirited type roused by a warming bitter stimulant.', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H241', 'C02', 'Aggravates', 'Primary', 'Choleric: a warm stimulant overheats the hot, dry, driven, irritable type (reflux, migraine, insomnia).', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H241', 'C06', 'Aggravates', 'Secondary', 'Robust/Hot (Pitta-like): adds heat and irritation to the fiery constitution.', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H241', 'C05', 'Aggravates', 'Secondary', 'Thin/Cold/Depleted (Vata-like): a xanthine stimulant over-excites and dries the wired, nervous, insomniac type.', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H241', 'D03', 'Primary', 'Kapha: a warm, bitter, drying stimulant that clears cold Kapha torpor, heaviness, and low mood.', '{"title": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "locator": "Grieve, A Modern Herbal (1931), Cocoa (Theobroma cacao), for the traditional Western account of theobromine, the diuretic and stimulant use, and the nutritive value of the bean.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "locator": "Ried et al., Cochrane Database of Systematic Reviews, Effect of cocoa on blood pressure (2017), for the modest blood-pressure-lowering effect of cocoa flavanols; Franco, Onatibia-Astibia and Martinez-Pinilla, The relevance of theobromine fo", "source_id": "S17", "author": "Brinker \u2014 Herbal Contraindications and Drug Interactions", "year": "2010", "url": null}'::jsonb, 'authored_v2', true);
