INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1137', 'H241', 'pregnancy', 'Pregnancy', 'moderate', 'Caffeine and theobromine cross the placenta and high caffeine intake is linked to premature delivery, low birth weight, and miscarriage; cocoa can also carry lead and cadmium.', 'Moderate, food amounts are possibly safe; keep total caffeine under 200 mg/day (ACOG) and avoid large or concentrated cocoa-flavanol doses.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database); ACOG guidance on caffeine in pregnancy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1138', 'H241', 'breastfeeding', 'Breastfeeding', 'moderate', 'Caffeine and theobromine pass into breast milk; very large maternal intake has caused infant irritability, jitteriness, and frequent stools.', 'Moderate food amounts are fine; avoid very large daily intakes and watch the infant for restlessness.', 'Drugs and Lactation Database (LactMed), Chocolate monograph; WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1139', 'H241', 'other', 'Children (dark/high-cocoa products in quantity)', 'moderate', 'Dark chocolate and high-cocoa products can contain high lead and cadmium; the methylxanthine stimulant disturbs sleep and can cause jitteriness and tachycardia.', 'Limit to small food amounts, avoid concentrated cacao and late-day intake, and choose heavy-metal-tested brands.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database); independent dark-chocolate heavy-metal testing (Consumer Reports, 2022 to 2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1140', 'H241', 'drug_interaction', 'MAOI antidepressants (phenelzine, tranylcypromine, isocarboxazid)', 'moderate', 'Cacao contains tyramine; with an MAOI, large amounts can precipitate a rise in blood pressure.', 'Keep cacao and chocolate intake modest with MAOIs and avoid large boluses.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1141', 'H241', 'drug_interaction', 'Adenosine and dipyridamole (pharmacologic cardiac stress testing)', 'moderate', 'Cocoa methylxanthines antagonize adenosine receptors and can blunt the vasodilator stress test.', 'Withhold cocoa and other caffeine sources before pharmacologic stress testing, per the testing protocol.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1142', 'H241', 'drug_interaction', 'Stimulant drugs (ephedrine, pseudoephedrine, amphetamines, ADHD stimulants)', 'moderate', 'Additive central and cardiovascular stimulation raising heart rate and blood pressure.', 'Use cautiously and limit intake with stimulant medications.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1143', 'H241', 'drug_interaction', 'Theophylline and other methylxanthines', 'moderate', 'Additive methylxanthine effects and toxicity (tachycardia, nervousness).', 'Limit cocoa with theophylline and monitor for xanthine excess.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1144', 'H241', 'drug_interaction', 'Lithium', 'moderate', 'The caffeine in cocoa has a diuretic effect that can alter lithium levels; a marked change in intake shifts lithium concentration.', 'Keep cocoa intake steady and monitor lithium levels if intake changes.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1145', 'H241', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'Cocoa flavanols have a mild antiplatelet effect that may add to bleeding risk at high intake.', 'Watch for additive effect with high cocoa-flavanol intake alongside blood thinners.', 'Brinker, Herbal Contraindications and Drug Interactions; WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1146', 'H241', 'condition', 'Anxiety, insomnia, cardiac arrhythmia/palpitations, GERD/reflux, migraine', 'moderate', 'The methylxanthine stimulant aggravates over-excitation, disturbed sleep, irregular heartbeat, reflux, and is a migraine trigger for some.', 'Avoid or minimize in these conditions, and avoid late-day and large-dose intake.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1147', 'H241', 'condition', 'Calcium-oxalate kidney stones and interstitial cystitis', 'moderate', 'Cocoa is an oxalate source relevant to stone formers, and its methylxanthines irritate the bladder in interstitial cystitis.', 'Limit cocoa in oxalate stone formers and in interstitial cystitis.', 'WebMD Cocoa monograph (Natural Medicines Comprehensive Database).');
