INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H242', 'TCM01', 'Secondary', 'Kidney Yang deficiency / interior cold: its cold, draining nature burdens failing yang.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "locator": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H242', 'TCM07', 'Minor', 'Yin deficiency with dryness: a bitter, drying herb can injure fluids in the dry, depleted phase.', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "locator": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1148', 'H242', 'pregnancy', 'Pregnancy (all medicinal doses, juice, seeds, extracts)', 'absolute', 'Documented abortifacient and weak uterine-stimulant activity; seed/fruit proteins alpha- and beta-momorcharin terminate early pregnancy in animals, and fruit water extracts induce abortion in rodents and primates.', 'Avoid all medicinal use in pregnancy. Occasional culinary use of the cooked green fruit is a lower food-level exposure, but juice, seeds, and concentrated doses must not be taken.', 'Review of Natural Products (Bitter Melon); AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker, Herbal Contraindications and Drug Interactions (4th ed., 2010); Enwerem et al., Int J Studies in Nursing (2018).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1149', 'H242', 'breastfeeding', 'Breastfeeding (medicinal doses, juice, seeds, extracts)', 'moderate', 'No reliable human safety data during lactation; the same cytotoxic, abortifacient seed proteins counsel caution.', 'Avoid medicinal juice, seeds, and extracts while nursing without professional guidance; culinary use of the cooked fruit is lower concern.', 'Review of Natural Products (Bitter Melon); Enwerem et al., Int J Studies in Nursing (2018).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1150', 'H242', 'drug_interaction', 'Antidiabetic medications (insulin, sulfonylureas, metformin, other hypoglycemics)', 'moderate', 'Additive pharmacodynamic hypoglycemia: bitter melon lowers blood glucose (charantin, insulin-like polypeptide-p, momordicosides), which can compound antidiabetic drugs and cause blood sugar to fall too low.', 'Use only with blood-glucose monitoring and prescriber oversight; antidiabetic doses may need downward adjustment. Stop before surgery. Do not replace prescribed therapy.', 'NCCIH; Review of Natural Products (Bitter Melon); Natural Medicines.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1151', 'H242', 'condition', 'G6PD (glucose-6-phosphate dehydrogenase) deficiency', 'moderate', 'The seed constituent vicine can precipitate favism, an acute hemolytic anemia, in G6PD-deficient individuals.', 'G6PD-deficient people should avoid bitter melon preparations, especially any containing seeds; seek urgent care for dark urine, pallor, or jaundice.', 'Review of Natural Products (Bitter Melon).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1152', 'H242', 'condition', 'Children (seeds and red seed-aril; medicinal doses)', 'moderate', 'The red aril around the ripe seeds is toxic to children (a reported fatality), and bitter melon tea has caused hypoglycemic coma and convulsions in children; intense glucose-lowering is hazardous in small bodies.', 'Never give seeds or the red aril to children; reserve any medicinal use for qualified professional supervision. Culinary cooked fruit only in family cooking.', 'Review of Natural Products (Bitter Melon).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1153', 'H242', 'condition', 'Spleen/stomach deficiency-cold and frank debility (TCM)', 'low', 'A markedly cold, bitter, draining fruit chills and weakens a cold, deficient, or exhausted terrain.', 'Avoid or combine with warming, building herbs in deficiency-cold digestion and debility; not a herb for want and cold.', 'Traditional TCM/energetic principle (Ku Gua, bitter and cold); Bensky et al., Chinese Herbal Medicine (energetic classification).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H242', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Karavellaka (Momordica charantia), the government pharmacopeial monograph codifying the classical Ayurvedic use of the bitter fruit (tikta rasa, cooling, drying) for prameha (the wasting and uri", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "locator": "Review of Natural Products (Facts and Comparisons / Wolters Kluwer), Bitter Melon monograph; NCCIH and Natural Medicines database entries on bitter melon; AHPA Botanical Safety Handbook (2nd ed., 2013); Brinker F, Herbal Contraindications a", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
