INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS14', 'Secondary', 'Chronic infection: supports host defense against smoldering, lingering infection.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS04', 'Secondary', 'Exhaustion: for convalescence and debility after illness or chemotherapy.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS05', 'Secondary', 'Excess heat: clears damp-heat and resolves toxicity in the warmer, boggy terrain.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS24', 'Minor', 'Scrofulous/lymphatic congestion: immune, toxin-resolving action on a boggy lymphatic terrain.');
