INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS17', 'Secondary', 'Cold: cool-leaning, heat-clearing, draining nature burdens true cold from yang deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H243', 'TS02', 'Minor', 'Atrophy: wasting from want of moisture is not helped by a drying agent.');
