INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A06', 'Primary', 'Immune tonic: builds and restores defensive (wei qi) function; the defining use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A25', 'Secondary', 'Antioxidant: polysaccharides and phenolics scavenge free radicals.');
