INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A30', 'Secondary', 'Antiviral: studied in HPV-related lesions and chronic viral infection (immune-mediated).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A23', 'Secondary', 'Tonic: a building, spleen- and vitality-strengthening fungus.');
