INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A21', 'Minor', 'Lymphagogue: supports a boggy, congested lymphatic terrain.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A36', 'Minor', 'Hypoglycemic: mild glucose-lowering tendency (basis of the antidiabetic caution).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H243', 'A28', 'Minor', 'Antimicrobial: broad antimicrobial activity reported in vitro.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H243', 'CP16', 'Primary', 'Immune weakness: the central indication, building and regulating defensive immunity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H243', 'CP06', 'Primary', 'Frequent illness: recurrent colds, flu, and infections from weak wei qi.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H243', 'CP09', 'Secondary', 'Chronic infection: supports host defense in smoldering, lingering infection (incl. HPV-related lesions).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H243', 'CP41', 'Secondary', 'Cold/flu: immune support at and around acute respiratory infection.');
