INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P04', 'Primary', 'Decoction: traditional long simmer of the dried fruiting body, often as broth/soup.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P02', 'Primary', 'Capsule of standardized hot-water/dual polysaccharide (beta-glucan) extract, the modern form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P01', 'Secondary', 'Tincture, best as a dual (water-and-alcohol) extract to capture water-soluble polysaccharides.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P03', 'Secondary', 'Powder of standardized extract.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P12', 'Secondary', 'Added to soups/bone broth as a food-level immune support.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H243', 'P05', 'Minor', 'Long infusion/tea.');
