INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1154', 'H243', 'pregnancy', 'Pregnancy (therapeutic/extract doses)', 'moderate', 'No reliable human safety data for Turkey tail or its concentrated PSK/PSP extracts in pregnancy.', 'Avoid concentrated medicinal doses in pregnancy unless supervised by a qualified practitioner; occasional culinary use of the whole mushroom is a food-level exposure.', 'Memorial Sloan Kettering, About Herbs ''Coriolus versicolor''; Herbal Reality, Turkey Tail monograph; WebMD, Turkey Tail Mushroom.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1155', 'H243', 'breastfeeding', 'Breastfeeding (therapeutic/extract doses)', 'moderate', 'Unknown whether constituents pass into breast milk; no reliable human safety data during lactation.', 'Avoid concentrated extracts while nursing without professional guidance; culinary mushroom broth is lower concern.', 'Memorial Sloan Kettering, About Herbs ''Coriolus versicolor''; WebMD, Turkey Tail Mushroom.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1156', 'H243', 'drug_interaction', 'Immunosuppressant medications (transplant drugs, e.g. cyclosporine, tacrolimus; autoimmune immunosuppressants)', 'moderate', 'As an immunostimulating, immunomodulating fungus it could theoretically oppose the intended action of immunosuppressive therapy.', 'Use only under medical supervision in transplant recipients and others on immunosuppressants; start low and monitor.', 'Herbal Reality, Turkey Tail monograph; mechanistic (immunostimulant); MSKCC About Herbs (immune-stimulating action).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1157', 'H243', 'drug_interaction', 'Antidiabetic medications (insulin, oral hypoglycemics)', 'low', 'Turkey tail may have a mild glucose-lowering tendency, giving a theoretical additive risk of hypoglycemia.', 'Monitor blood glucose if combining; adjust antidiabetic therapy with the prescriber as needed.', 'Herbal Reality, Turkey Tail monograph (theoretical).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1158', 'H243', 'condition', 'Active autoimmune disease (e.g. RA, lupus, MS) in flare', 'moderate', 'Immune-stimulating action may add fuel during an active autoimmune flare.', 'Use cautiously and under practitioner guidance in autoimmune disease; work at low initial doses with immune-marker monitoring.', 'Herbal Reality, Turkey Tail monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1159', 'H243', 'condition', 'Cancer (self-treatment in place of conventional care)', 'moderate', 'Turkey tail (and PSK/PSP) is an adjuvant terrain agent, not a curative therapy; used alone it can delay effective treatment.', 'Use only as an adjunct coordinated with the oncology team, never as a substitute for evaluation or conventional cancer treatment.', 'Memorial Sloan Kettering, About Herbs ''Coriolus versicolor''; meta-analyses of PSK as an adjuvant.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1160', 'H243', 'other', 'Mushroom/fungal allergy', 'moderate', 'As a fungus it can provoke hypersensitivity, including rare serious allergic reactions (breathing problems, swelling, hives).', 'Avoid in those with known mushroom allergy; discontinue if allergic symptoms occur.', 'WebMD, Turkey Tail Mushroom.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1161', 'H243', 'condition', 'Yin-deficient dryness / true interior cold', 'low', 'The drying, damp-draining, cool-leaning character can deepen dryness or burden failing yang where there is no damp-heat.', 'Avoid or combine with moistening, warming, yin-building herbs in markedly dry or cold-deficient constitutions.', 'Traditional TCM/energetic principle (Yun Zhi drains damp, clears heat).');
