INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1162', 'H244', 'pregnancy', 'Pregnancy', 'absolute', 'Reputed emmenagogue and uterine-stimulant action that may affect the menstrual cycle or provoke uterine contraction and miscarriage, compounded by irritant calcium-oxalate content.', 'Do not use in pregnancy in any form or dose.', 'WebMD, ''Skunk Cabbage,'' citing Brinker, Herb Contraindications and Drug Interactions (2nd ed., 1998) and AHPA Botanical Safety Handbook (1997).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1163', 'H244', 'breastfeeding', 'Breastfeeding', 'moderate', 'Rated possibly unsafe; no reliable human data on transfer of acrid calcium-oxalate constituents into breast milk.', 'Avoid therapeutic use while nursing.', 'WebMD, ''Skunk Cabbage'' (per Brinker 1998 and AHPA Botanical Safety Handbook 1997).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1164', 'H244', 'other', 'Raw or fresh plant (ingestion of any quantity)', 'absolute', 'Needle-like calcium-oxalate raphides in the fresh plant cause intense oropharyngeal burning and swelling that can threaten the airway; the fresh sap can burn and blister skin.', 'Never ingest the raw or fresh plant; use only correctly prepared, dried and dosed material.', 'WebMD, ''Skunk Cabbage''; AHPA Botanical Safety Handbook (calcium-oxalate raphides of Araceae).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1165', 'H244', 'condition', 'Oxalate kidney stones / oxalate nephropathy', 'moderate', 'Calcium-oxalate content can irritate the kidneys and raise the risk of oxalate stones.', 'Avoid in those with a history of oxalate kidney stones or oxalate nephropathy.', 'WebMD, ''Skunk Cabbage'' (AHPA Botanical Safety Handbook).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1166', 'H244', 'condition', 'Peptic ulcer, ulcerative colitis, Crohn''s disease', 'moderate', 'Acrid calcium-oxalate raphides irritate the gastrointestinal mucosa and can worsen ulceration and inflammatory bowel disease.', 'Avoid in active peptic ulcer or inflammatory bowel disease.', 'WebMD, ''Skunk Cabbage.''');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1167', 'H244', 'drug_interaction', 'Nephrotoxic or oxalate-raising agents', 'low', 'Theoretical additive renal and oxalate burden; no documented pharmacologic interactions exist for skunk cabbage.', 'Use cautiously alongside nephrotoxic drugs or high oxalate loads; monitor renal status. Precautionary, not documented.', 'Mechanistic (calcium-oxalate content); WebMD lists no documented interactions (limited data).');
