INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H245', 'TCM07', 'Secondary', 'Yin deficiency with dryness: a drying, draining alterative worsens fluid depletion.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H245', 'TCM02', 'Secondary', 'Qi deficiency: further draining depletes an already deficient qi.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1168', 'H245', 'pregnancy', 'Pregnancy', 'moderate', 'A stimulating cholagogue and cathartic with emetic potential and a traditional emmenagogue reputation; insufficient reliable human safety data.', 'Avoid in pregnancy; do not use even low specific-medication doses without qualified supervision.', 'WebMD/RxList (Blue Flag, unsafe in pregnancy); PeaceHealth; Herbal Reality (Iris); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1169', 'H245', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion of the acrid, irritant constituents into breast milk; emetic-cathartic nature and insufficient lactation data.', 'Avoid while nursing without professional guidance.', 'Herbal Reality (Iris, not recommended in breastfeeding); WebMD/RxList.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1170', 'H245', 'drug_interaction', 'Cardiac glycosides (digoxin, digitoxin)', 'moderate', 'Emetic and cathartic gastrointestinal action can deplete fluids and potassium, heightening cardiac-glycoside toxicity; the herb has a narrow dosing margin.', 'Avoid concurrent use with digoxin or other cardiac glycosides; involve the prescriber and monitor potassium if unavoidable.', 'Herbal Reality (Iris, avoid with digoxin/cardiac glycosides); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1171', 'H245', 'condition', 'Acute gastrointestinal inflammation or ulceration (gastritis, IBD, IBS)', 'moderate', 'The acrid, irritant rhizome inflames an already inflamed or ulcerated gut and provokes nausea, cramping, and purging.', 'Avoid in acute GI inflammation, ulceration, and irritable or inflammatory bowel disease.', 'Herbal Reality (Iris, avoid in gastrointestinal inflammation); Southern Cross University Medicinal Plant Monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1172', 'H245', 'condition', 'Fresh rhizome internal use / overdose', 'moderate', 'The fresh acrid rhizome and high doses cause nausea, violent vomiting, purging, colic, salivation, and headache; the acrid oleoresin (irisin/iridin) is the toxic principle.', 'Use only the dried rhizome in low, measured doses; never take the fresh rhizome internally; discontinue if nausea or purging occurs.', 'WebMD/RxList (fresh root irritant/emetic); Southern Cross University Medicinal Plant Monograph; King''s American Dispensatory 1898 (overdose picture).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1173', 'H245', 'condition', 'Children (self-directed use)', 'moderate', 'No established pediatric dosing; a gastrointestinal irritant that is emetic and cathartic, with a real overdose picture.', 'Do not give to children for self-directed use; reserve any pediatric use to a qualified practitioner and refer for evaluation.', 'WebMD/RxList (do not give to children); Herbal Reality (Iris, not suitable for children).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1174', 'H245', 'other', 'Contact irritation (fresh plant, juice, root dust)', 'low', 'The fresh plant and its juice and dust can irritate the skin, eyes, and mucous membranes in sensitive handlers.', 'Handle the fresh plant and root dust with care; avoid in those with known Iris sensitivity.', 'WebMD/RxList; Southern Cross University Medicinal Plant Monograph.');
