INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H245', 'EP08', 'neutral', 1, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898), Iris (Iris versicolor, the rhizome), which describes Blue Flag as a stimulating alterative, cholagogue, and mild cathartic for chronic hepatic, glandular, and skin disease, gives the sm", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), Iris versicolor; Cook, The Physiomedical Dispensatory (1869), Iris; Grieve, A Modern Herbal (1931), Iris (Blue Flag); Holmes, The Energetics of Western Herbs (energ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H246', 'Longan', 'Dimocarpus longan', 'Sapindaceae (the soapberry family; the same family as lychee, Litchi chinensis, and rambutan). Botanical synonyms Euphoria longana Lam. and Euphoria longan (Lour.) Steud.', 'The arillus, the translucent, sweet, fleshy aril that surrounds the single dark seed, dried until it is amber-brown and leathery. Dried longan aril is the Chinese medicinal Long Yan Rou (dragon-eye flesh, so named because the seed shows through the peeled flesh like a dark pupil).', 'Sweet (a rich, honeyed, faintly cloying sweetness, the building and nourishing taste of a blood tonic).', 'Warm', 'Moist', 'Deficiency and depletion of the blood and of the vital energy, above all Heart-Blood and Spleen-Qi deficiency: the pale, worn-down, overworked, or convalescent person whose blood no longer nourishes the heart and whose spleen no longer builds it, so the spirit is left unsettled. In that emptiness arise palpitations, a fluttering or pounding heart, insomnia and dream-disturbed sleep, forgetfulness and a foggy, unfocused mind, dizziness, and a tired pallor. There is genuine exhaustion here, the used-up state that follows long illness, blood loss, overthinking, or overwork, and it is met by a sweet, warm, nourishing tonic that rebuilds the blood, tonifies the spleen, and quiets a spirit made restless by want rather than by heat. Marked cold and depletion of the middle also draw on its gentle warmth. The restlessness it settles is the restlessness of an under-nourished, deficient terrain, not of an overheated or over-full one.', 'Excess heat and fire: a warm, sweet, cloying tonic adds fuel to any heat pattern, so it is wrong in feverish, red, inflamed, or heat-from-emptiness states. Dampness and phlegm: its rich sweetness readily generates damp and phlegm, so it burdens the person with a heavy, greasy, boggy middle, abdominal fullness, a thick tongue coat, or phlegm-fire. Food stagnation and a congested, over-full digestion, where another sweet, building food only clogs. In short, longan is for the empty and the cold-depleted, never for the full, the hot, or the damp.', 'Cardiovascular and the Heart above all, in the Chinese sense of the Heart that houses the spirit (Shen): longan nourishes Heart-Blood and settles a heart made anxious and palpitant by deficiency. Nervous system, closely tied to it: a nourishing, calming trophorestorative for deficiency insomnia, anxiety, poor memory, and mental fatigue from overthinking. Digestive and the Spleen, its second home organ: it tonifies Spleen-Qi, supports appetite and the building of blood from food, and eases the fatigue and poor digestion of a weak spleen. Secondarily Reproductive, meeting the blood-building needs of women depleted by menstruation, childbirth, or blood loss, for whom it is a gentle postpartum and blood-deficiency tonic.', 'Palpitations, anxiety, insomnia, and dream-disturbed sleep arising from Heart-Blood and Spleen-Qi deficiency, its central use, embodied in the classic formula Gui Pi Tang (Restore the Spleen Decoction). Forgetfulness, poor concentration, mental fatigue, and dizziness in the overworked, overthinking, or blood-deficient person. General fatigue, debility, pallor, and convalescence after illness, blood loss, or childbirth, where qi and blood must be rebuilt. Poor appetite and weak digestion from spleen deficiency. It is a gentle, food-grade building tonic, best in deficiency patterns and combined in formula, not a remedy for acute or excess-heat conditions.', 'Thin, cold, depleted, and blood-poor: the nervous, worn-down, Vata-like person who lies awake with a racing mind, startles easily, forgets, tires quickly, and runs pale and slightly cold, all rebuilt by a sweet, warm, nourishing blood tonic. It equally suits the deficient, pale phenotype convalescing from illness, blood loss, or childbirth, and the cold-dry melancholic whose depletion its warm moisture nourishes. Because it is warm, sweet, and damp-generating, it is poorly suited to the robust, hot (Pitta-like) constitution, in whom it stokes heat, and to the damp, boggy phlegmatic, in whom its cloying sweetness deepens dampness and congestion.', 'Vata', 'Pitta, Kapha', 'Long Yan Rou is a classic herb of the Chinese materia medica, recorded from the Shen Nong Ben Cao Jing and made central by Yan Yonghe''s Gui Pi Tang (1253). Sweet and warm, entering the Heart and Spleen, it tonifies the Heart and Spleen, nourishes the Blood, and quiets the Spirit. Its pattern is Heart-Blood and Spleen-Qi deficiency with an unsettled Shen: palpitations, insomnia, poor memory, anxiety, dizziness, fatigue, and pallor, together with the qi-and-blood deficiency that follows chronic illness, overwork, or blood loss.', 'It is contraindicated where there is Heat or Fire, including Yin-deficient heat and Phlegm-Fire harassing the Heart, because its warm sweetness adds heat. It is likewise wrong in Dampness and Phlegm accumulation and in food stagnation, since its rich, cloying nature readily generates damp and phlegm and clogs a congested middle. Use it only in genuine deficiency, never in excess or damp-heat patterns.', 'Longan is a widely eaten subtropical fruit and a food-grade tonic with a long record of safe use; its cautions are largely those of a sweet, warm, sugar-rich food. Eaten in excess it can cause indigestion and, in TCM terms, internal heat with symptoms such as sore throat, mouth ulcers, or acne, and it can generate dampness and bloating in those already damp or phlegmatic. Its high natural sugar content means it should be used sparingly by people with diabetes or blood-sugar dysregulation. Because it is warm and sweet, avoid it in acute heat, fever, and damp-heat conditions. Traditional Chinese sources advise caution or avoidance of concentrated medicinal amounts in pregnancy.', 'Heat and Fire patterns, fever, and acute inflammation, which its warm sweetness aggravates. Dampness, phlegm, and food stagnation, which its cloying richness worsens. Diabetes and other blood-sugar dysregulation, given its high sugar content (use sparingly and monitor). Known allergy to longan or related Sapindaceae fruits (lychee, rambutan). Therapeutic or medicinal doses in pregnancy without professional guidance, per traditional caution and the absence of modern safety data; culinary amounts of the fruit are a food-level exposure.', 'Culinary amounts of the fruit are a food-level exposure and are generally regarded as safe; the American Herbal Products Association Botanical Safety Handbook rates longan fruit as a Class 1 herb (one that can be safely consumed when used appropriately). Therapeutic or concentrated medicinal amounts of the dried aril, however, are traditionally cautioned in pregnancy: classical and modern Chinese-medicine sources hold that its sweet, warm nature can generate internal heat and dampness that may disturb a pregnancy, and several advise pregnant women, especially in the first trimester, to avoid concentrated longan. Reliable modern human safety data for medicinal doses in pregnancy are lacking. Prudent, consumer-safe course: the fruit in normal food amounts is of low concern, but avoid concentrated therapeutic doses in pregnancy unless supervised by a qualified practitioner.', 'As a food fruit, culinary longan is a food-level exposure of low concern during lactation, and dried longan appears in some traditional postpartum tonic soups. There are no specific modern human safety data for concentrated therapeutic doses of the dried aril during breastfeeding, so reserve medicinal amounts for use under professional guidance. AHPA rates the fruit Class 1, with no restriction identified for appropriate use.', 'The fresh or dried fruit is commonly and safely eaten by children in moderation and is a food-level exposure (AHPA Class 1). Its high sugar content argues for moderation for dental and blood-sugar reasons. There is no established pediatric dosing for concentrated medicinal preparations of the dried aril; reserve therapeutic tonic doses for use under a qualified practitioner, and treat longan for children mainly as a gentle food in soups and congee.', 'No well-documented pharmacokinetic drug interactions are established for longan (limited data). The most practical caution is with antidiabetic therapy: the dried aril is rich in natural sugars and, eaten in quantity, can raise blood glucose, so people on insulin or oral hypoglycemics should account for its sugar load and monitor blood glucose (isolated longan seed and leaf extracts have shown hypoglycemic activity in animal studies, but that is a different preparation from the sugar-rich edible aril). Popular sources also mention theoretical additive effects with blood-pressure-lowering or anticoagulant drugs, but these are not well documented. Overall, treat longan as a food with no established clinically significant drug interactions, and monitor blood glucose in diabetics.', 'Decoction of the dried aril, the classical medicinal form, almost always combined in formula (as in Gui Pi Tang). Added to soups, congee, and tonic broths as a food-grade blood and spleen tonic, its most everyday use. Steeped as a simple tea or added to herbal tea blends. Soaked in rice wine or spirits as a warming tonic elixir. Longan syrup and honeyed pastes. Eaten simply as the fresh or dried fruit.', 'Decoction of dried aril: 6 to 15 g per day, simmered, usually within a formula (the classical Long Yan Rou range; roughly 9 to 10 g as a gentle Heart-Spleen tonic, up to 12 to 15 g for marked Heart-Blood deficiency with palpitations and insomnia). As food: a small handful of dried longan, about 10 to 30 g, added to soup, congee, or tea. Use sparingly in those watching blood sugar. Prolonged medicinal use is best guided by a practitioner and balanced with damp-draining or qi-moving herbs to offset its cloying nature.', 'Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Long Yan, describing the dried aril as a sweet, warm tonic that nourishes the blood, benefits the Heart and Spleen, and quiets the spirit.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoction), in which longan is a principal herb; AHPA Botanical Safety Handbook (longan fruit, Class 1); modern phytochemical work on longan polyphenols and the longan genome (Lin et al., GigaScience, 2017, PMC5467034).', 'Longan (Dimocarpus longan, family Sapindaceae) is a subtropical evergreen tree of southern China and Southeast Asia, closely related to lychee and rambutan; its name dragon-eye (long yan) comes from the peeled fruit, whose translucent flesh around a single dark seed resembles an eyeball. The medicinal part is the dried aril, Long Yan Rou. Its constituents include abundant simple sugars (glucose, sucrose), which underlie both its nourishing, blood-building action and its cautions, along with a notable load of polyphenols and antioxidants (gallic and ellagic acids, corilagin, flavonoids), polysaccharides, and small amounts of adenine and choline. Traditionally it is a sweet, warm tonic for Heart-Blood and Spleen-Qi deficiency, the defining herb of Gui Pi Tang, valued for palpitations, insomnia, forgetfulness, anxiety, and post-illness or postpartum depletion. It is gentle and food-grade but cloying: overused it generates heat and damp, so it is classically combined with qi-moving, damp-draining, or spleen-strengthening herbs. In this materia medica it serves as a food-safe blood and heart tonic in place of the toxic cardioactive Canadian Hemp.', 'Not found in the canonical biblical texts nor in the classical Greco-Roman herbals; longan is a fruit of southern China and Southeast Asia, not of the ancient Mediterranean world. Its medicinal use belongs to the Chinese tradition, recorded from the Shen Nong Ben Cao Jing (c. 200 CE) and elaborated in Li Shizhen''s Ben Cao Gang Mu (1596), and it became a signature herb of Yan Yonghe''s Gui Pi Tang (1253). Cited honestly as a herb of Chinese medical tradition rather than of Scripture.', 'Longan is a widely cultivated commercial fruit crop grown across China, Thailand, Vietnam, India, Australia, and subtropical parts of the Americas; it is in no way threatened and is not listed by United Plant Savers. The dried aril used in medicine is a byproduct of ordinary orchard fruit production, so it is abundant and sustainably sourced. Favor fruit from growers using sound orchard practices; the sugar-rich dried fruit is essentially a food commodity.', 'Warm and moistening: a sweet, honeyed blood and spleen tonic that rebuilds Heart-Blood, nourishes the depleted, and quiets a spirit made restless by deficiency.', 'Palpitations, chest pain, breathlessness, fainting, or a persistently irregular or racing heartbeat need medical evaluation for cardiac causes, not self-treatment with a food tonic. Refer severe, chronic, or worsening insomnia, anxiety, or memory loss for proper assessment. Unexplained fatigue, pallor, or dizziness may signal anemia or other serious illness and should be investigated. People with diabetes should coordinate any regular use with their clinician given the sugar content. Longan is a gentle adjunct for deficiency patterns, not a treatment for acute, severe, or excess-heat disease.', 'Longan: LONG-gun (also LONG-gahn). Dimocarpus longan: dy-moh-KAR-pus LONG-gan. Long Yan Rou: long yen roh.', 'free', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "locator": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H246', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS01', 'Primary', 'Deficiency: the core state, qi and blood (Heart-Blood, Spleen-Qi) deficiency of the depleted, convalescent, or overworked.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS21', 'Primary', 'Blood deficiency: nourishes and rebuilds the blood, settling a heart and spirit starved by emptiness.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS04', 'Secondary', 'Exhaustion: the used-up state after long illness, blood loss, overthinking, or overwork.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS17', 'Minor', 'Cold: its gentle warmth serves a cold, depleted middle.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS05', 'Primary', 'Excess heat: warm, sweet tonic adds fuel to feverish, red, inflamed, or heat-from-emptiness states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS07', 'Primary', 'Dampness: cloying sweetness generates damp and burdens a boggy, heavy middle.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS23', 'Secondary', 'Phlegm: worsens phlegm accumulation and phlegm-fire.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS08', 'Secondary', 'Stagnation: rich, building sweetness clogs a congested, food-stagnant digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS16', 'Minor', 'Excess conditions: a building tonic is wrong where the pattern is full, not empty.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H246', 'TS06', 'Minor', 'Acute inflammation: warm and sweet, it aggravates active heat and inflammation.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H246', 'SY06', 'Primary', 'Cardiovascular: nourishes Heart-Blood, settles palpitations, calms the Heart-housed spirit.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H246', 'SY01', 'Primary', 'Nervous: nourishing trophorestorative for deficiency insomnia, anxiety, poor memory, mental fatigue.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H246', 'SY08', 'Secondary', 'Digestive: tonifies the spleen, supports appetite and the building of blood from food.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H246', 'SY13', 'Secondary', 'Spleen (TCM): tonifies Spleen-Qi, the root of blood production.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H246', 'SY03', 'Minor', 'Reproductive: gentle blood tonic for depletion from menstruation, childbirth, or blood loss.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A23', 'Primary', 'Tonic: a building blood and qi tonic for genuine deficiency.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A39', 'Primary', 'Nutritive: a sweet, food-grade nourisher that rebuilds the blood.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A02', 'Primary', 'Nervine tonic: nourishes and restores a depleted nervous system, calming a spirit unsettled by want.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A22', 'Secondary', 'Sedative: settles deficiency insomnia and a restless heart through nourishment, not suppression.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A26', 'Secondary', 'Anxiolytic: eases anxiety and restlessness of Heart-Blood deficiency.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A40', 'Secondary', 'Trophorestorative: restores the depleted Heart and Spleen over time.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A05', 'Minor', 'Anabolic: a building, flesh-and-blood-nourishing tonic.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A25', 'Minor', 'Antioxidant: rich in polyphenols (gallic and ellagic acids, corilagin, flavonoids).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H246', 'A48', 'Minor', 'Nootropic/cerebral tonic: for forgetfulness and mental dullness of blood deficiency (the classical benefit-the-mind reputation).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP46', 'Primary', 'Palpitations: a fluttering or pounding heart of Heart-Blood deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP04', 'Primary', 'Insomnia: deficiency insomnia and dream-disturbed sleep with an unsettled spirit.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP10', 'Primary', 'Anxiety: restlessness and worry of an under-nourished heart and spirit.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP07', 'Secondary', 'Fatigue: qi-and-blood-deficiency tiredness of the worn-down, spleen-weak person.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP03', 'Secondary', 'Debility: convalescence and rebuilding after illness, blood loss, or childbirth.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP24', 'Secondary', 'Mental fog/cognitive dullness: forgetfulness, poor concentration, and dizziness of blood deficiency.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H246', 'CP21', 'Secondary', 'Nervous exhaustion: depletion from overthinking and overwork.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H246', 'P04', 'Primary', 'Decoction of the dried aril, the classical form, usually combined in formula (Gui Pi Tang).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H246', 'P12', 'Primary', 'Added to soups, congee, and tonic broths as a food-grade blood and spleen tonic.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H246', 'P05', 'Secondary', 'Infusion/tea, alone or in blends.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H246', 'P14', 'Secondary', 'Elixir: soaked in rice wine or spirits as a warming tonic.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H246', 'P09', 'Minor', 'Syrup or honeyed paste.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H246', 'C05', 'Indicated', 'Primary', 'Thin/Cold/Depleted (Vata-like): the nervous, blood-poor, sleepless, forgetful, pale, slightly cold person.', '{"title": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "locator": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
