INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1175', 'H246', 'pregnancy', 'Pregnancy (therapeutic/medicinal doses of the dried aril)', 'moderate', 'Sweet, warm nature is traditionally held to generate internal heat and dampness that may disturb a pregnancy; no reliable modern human safety data for medicinal doses.', 'Avoid concentrated therapeutic doses in pregnancy unless supervised by a qualified practitioner; culinary amounts of the fruit are a food-level exposure.', 'Traditional TCM caution (multiple Chinese materia medica sources); AHPA Botanical Safety Handbook (fruit, Class 1); modern pregnancy-specific data lacking.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1176', 'H246', 'drug_interaction', 'Antidiabetic medications (insulin, oral hypoglycemics) and diabetes', 'moderate', 'The dried aril is high in natural sugars and, eaten in quantity, can raise blood glucose and complicate glycemic control.', 'Use sparingly and monitor blood glucose if diabetic or on glucose-lowering drugs; coordinate regular use with the prescriber.', 'Nutrition/consumer-health references on longan sugar content; mechanistic; AHPA note that excess causes indigestion.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1177', 'H246', 'condition', 'Heat, Fire, Damp-Heat, and Phlegm patterns', 'moderate', 'A warm, sweet, cloying tonic adds heat and generates damp and phlegm.', 'Avoid in acute heat, fever, damp-heat, and phlegm-fire; use only in genuine deficiency.', 'Traditional TCM principle (Bensky, Chinese Herbal Medicine: Materia Medica; classical contraindications for Long Yan Rou).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1178', 'H246', 'other', 'Allergy to longan or related Sapindaceae fruits (lychee, rambutan)', 'moderate', 'Possible cross-reactive fruit allergy within the Sapindaceae.', 'Avoid with known longan, lychee, or rambutan allergy; discontinue if allergic symptoms occur.', 'General allergen/botanical-family principle.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H246', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "locator": "Shen Nong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE), which records longan (Long Yan) among the materia medica as a sweet tonic fruit that benefits the vital energy and the mind; and Li Shizhen, Ben Cao Gang Mu (Compendium", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Long Yan Rou); Chen & Chen, Chinese Medical Herbology and Pharmacology (Longan Arillus); Yan Yonghe, Ji Sheng Fang (1253), the source of Gui Pi Tang (Restore the Spleen Decoc", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
