INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H247', 'TCM07', 'Primary', 'Yin Deficiency: a warming, drying, draining herb worsens yin-deficient dryness.', '{"title": "Maud Grieve, A Modern Herbal (1931), ''Celery'' (Apium graveolens), which records its diuretic, carminative, and antirheumatic use, the medicinal use of the seed, and the caution that the seed and its essential oil are more active than the pl", "locator": "Maud Grieve, A Modern Herbal (1931), ''Celery'' (Apium graveolens), which records its diuretic, carminative, and antirheumatic use, the medicinal use of the seed, and the caution that the seed and its essential oil are more active than the pl", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy, and Bone, A Clinical Guide to Blending Liquid Herbs (celery seed for gout, rheumatism, and uric-acid conditions); AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin), Apium", "locator": "Mills and Bone, Principles and Practice of Phytotherapy, and Bone, A Clinical Guide to Blending Liquid Herbs (celery seed for gout, rheumatism, and uric-acid conditions); AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin), Apium", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H247', 'TCM11', 'Secondary', 'Heat/Fire: warm, pungent nature aggravates heat and fire patterns.', '{"title": "Maud Grieve, A Modern Herbal (1931), ''Celery'' (Apium graveolens), which records its diuretic, carminative, and antirheumatic use, the medicinal use of the seed, and the caution that the seed and its essential oil are more active than the pl", "locator": "Maud Grieve, A Modern Herbal (1931), ''Celery'' (Apium graveolens), which records its diuretic, carminative, and antirheumatic use, the medicinal use of the seed, and the caution that the seed and its essential oil are more active than the pl", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy, and Bone, A Clinical Guide to Blending Liquid Herbs (celery seed for gout, rheumatism, and uric-acid conditions); AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin), Apium", "locator": "Mills and Bone, Principles and Practice of Phytotherapy, and Bone, A Clinical Guide to Blending Liquid Herbs (celery seed for gout, rheumatism, and uric-acid conditions); AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin), Apium", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1179', 'H247', 'pregnancy', 'Pregnancy (medicinal doses of seed, extract, and essential oil)', 'absolute', 'Traditional uterine-stimulant and emmenagogue reputation; the essential oil is uterotonic and reproductive-toxicity concern applies at concentrated doses.', 'Avoid medicinal celery seed, seed extract, and celery seed essential oil throughout pregnancy. Culinary celery stalk as food is acceptable.', 'AHPA Botanical Safety Handbook, 2nd ed. (Apium graveolens); Brinker, Herb Contraindications and Drug Interactions; Tisserand and Young, Essential Oil Safety, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1180', 'H247', 'condition', 'Acute kidney inflammation (acute nephritis) and significant renal disease', 'absolute', 'An irritant volatile oil plus active diuresis increases the load on inflamed, actively secreting, or impaired kidney tissue.', 'Do not use medicinal doses of celery seed in acute nephritis or serious kidney disease; refer for evaluation.', 'German Commission E (celery seed); Grieve, A Modern Herbal (1931); NMCD/WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1181', 'H247', 'other', 'Celery / Apiaceae and birch-mugwort pollen allergy', 'absolute', 'IgE cross-reactivity (celery-mugwort-spice and celery-carrot-mugwort syndromes); reactions range from oral allergy and urticaria to anaphylaxis; celery is a major EU labeled allergen.', 'Avoid in anyone allergic to celery, related Apiaceae (carrot, fennel, caraway, anise, coriander), or birch or mugwort pollen. Stop at once for lip, tongue, or throat swelling or breathing difficulty.', 'AHPA Botanical Safety Handbook, 2nd ed.; EU Regulation 1169/2011 major allergen listing; NMCD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1182', 'H247', 'drug_interaction', 'Lithium', 'moderate', 'Diuretic action can reduce renal lithium clearance, raising serum lithium toward toxic levels.', 'Avoid medicinal doses or use only with close monitoring of lithium levels.', 'Natural Medicines Comprehensive Database; WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1183', 'H247', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Coumarin content may add to anticoagulant effect and bleeding risk.', 'Use caution and monitor for bleeding / INR if combined.', 'Brinker, Herb Contraindications and Drug Interactions; Mills and Bone; NMCD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1184', 'H247', 'drug_interaction', 'Levothyroxine (thyroid hormone)', 'moderate', 'Published case reports describe loss of levothyroxine effect and recurrence of hypothyroid symptoms when celery seed tablets were added, resolving on discontinuation.', 'Separate dosing, monitor TSH, and stop celery seed if thyroid control worsens.', 'G. Moses, ''Thyroxine interacts with celery seed tablets?'' (case report); NMCD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1185', 'H247', 'drug_interaction', 'Diuretic and antihypertensive drugs', 'moderate', 'Additive diuresis (fluid/electrolyte disturbance) and additive blood-pressure lowering.', 'Use caution and monitor blood pressure, fluid balance, and electrolytes when combined.', 'NMCD; WebMD; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1186', 'H247', 'other', 'Furanocoumarins (bergapten/psoralens) with UV or photosensitizing drugs', 'moderate', 'Psoralen furanocoumarins in the seed and oil cause photosensitivity and phototoxic skin reactions, especially with the concentrated oil and sun exposure.', 'Avoid large intakes of the concentrated oil with UV exposure or photosensitizing medication.', 'Tisserand and Young, Essential Oil Safety, 2nd ed.; AHPA Botanical Safety Handbook.');
