INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1187', 'H248', 'pregnancy', 'Pregnancy', 'moderate', 'No adequate human data; chirata is traditionally classed among the bitter emmenagogues with a theoretical uterine-stimulant action.', 'Avoid in pregnancy.', 'Natural Medicines Comprehensive Database (via RxList and WebMD, Chirata); traditional emmenagogue classification.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1188', 'H248', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable lactation data and no NIH LactMed monograph; the intense bitterness may pass into the milk.', 'Avoid during breastfeeding.', 'Natural Medicines Comprehensive Database (via RxList and WebMD); NIH LactMed (no entry).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1189', 'H248', 'drug_interaction', 'Antidiabetic and hypoglycemic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Documented blood-sugar-lowering activity may add to their effect and cause hypoglycemia.', 'Monitor blood glucose and adjust medication under professional guidance.', 'Natural Medicines Comprehensive Database (via RxList and WebMD, Chirata).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1190', 'H248', 'condition', 'Active peptic or intestinal ulcer and acute gastritis', 'moderate', 'The sharp bitter can aggravate ulceration and raw, irritated gut lining.', 'Avoid in active ulcer disease.', 'Natural Medicines Comprehensive Database (via RxList and WebMD).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1191', 'H248', 'condition', 'Diabetes and hypoglycemia-prone individuals', 'moderate', 'May lower blood sugar, with a risk of hypoglycemia especially alongside glucose-lowering therapy.', 'Monitor blood glucose; use only with professional oversight.', 'Kumar and Van Staden, Frontiers in Pharmacology 6:308 (2015); Natural Medicines Comprehensive Database.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1192', 'H248', 'other', 'Scheduled surgery', 'moderate', 'Blood-sugar-lowering effect may interfere with glycemic control during and after surgery.', 'Stop use at least two weeks before scheduled surgery.', 'Natural Medicines Comprehensive Database (via RxList and WebMD).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1193', 'H248', 'pediatric', 'Young children', 'moderate', 'No pediatric safety data; extreme bitterness is poorly tolerated and hypoglycemia is a concern.', 'Avoid in young children; use in older children only in low, short-term doses under supervision.', 'Natural Medicines Comprehensive Database; NCCIH (insufficient data).');
