INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H249', 'C06', 'Aggravates', 'Secondary', 'Robust/Hot (Pitta-like): its warmth and richness aggravate real heat and plethora.', '{"title": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "locator": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "source_id": "S30", "author": "NCCIH Herbs at a Glance", "year": "current", "url": "https://www.nccih.nih.gov/health/herbsataglance"}'::jsonb, 'authored_v2', true);
