INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H249', 'TCM11', 'Primary', 'Heat/Fire: a warming, building tonic is contraindicated in excess heat and fire.', '{"title": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "locator": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "source_id": "S30", "author": "NCCIH Herbs at a Glance", "year": "current", "url": "https://www.nccih.nih.gov/health/herbsataglance"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H249', 'TCM12', 'Secondary', 'Wind-Heat: withhold during acute febrile exterior illness; can retain the pathogen.', '{"title": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "locator": "Wu Yiluo, Ben Cao Cong Xin (New Compilation of Materia Medica, 1757), Dong Chong Xia Cao (winter-worm summer-grass), the first detailed materia medica description of the caterpillar fungus, with an earlier brief mention in Wang Ang, Ben Cao", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao); Memorial Sloan Kettering Cancer Center, About Herbs, Cordyceps (mskcc.org); RxList / Natural Medicines, Cordyceps; Drugs.com, Cordyceps monograph; NCCIH ", "source_id": "S30", "author": "NCCIH Herbs at a Glance", "year": "current", "url": "https://www.nccih.nih.gov/health/herbsataglance"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1194', 'H249', 'pregnancy', 'Pregnancy (therapeutic/extract doses)', 'moderate', 'No reliable human safety data in pregnancy; animal studies show cordyceps alters plasma testosterone and reproductive hormones, a theoretical fetal concern.', 'Avoid therapeutic doses and concentrated extracts in pregnancy unless supervised by a qualified practitioner; occasional food-level use of the whole fungus in broth is a dietary exposure.', 'Memorial Sloan Kettering, About Herbs ''Cordyceps''; RxList / Natural Medicines, Cordyceps.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1195', 'H249', 'breastfeeding', 'Breastfeeding (therapeutic/extract doses)', 'moderate', 'Unknown whether constituents pass into breast milk; no reliable human safety data during lactation.', 'Avoid concentrated extracts while nursing without professional guidance; culinary use of the whole fungus in soup is lower concern.', 'Memorial Sloan Kettering, About Herbs ''Cordyceps''; RxList / Natural Medicines, Cordyceps.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1196', 'H249', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin)', 'moderate', 'Cordyceps inhibits platelet aggregation and may add to the effect of blood thinners; a case report documents excessive bleeding after a dental extraction in a daily user.', 'Use only under medical supervision with these drugs; monitor for bleeding and discontinue before surgery or dental procedures.', 'Memorial Sloan Kettering, About Herbs ''Cordyceps'' (case report of excessive bleeding).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1197', 'H249', 'drug_interaction', 'Antidiabetic drugs and insulin', 'low', 'Cordyceps may have additive glucose-lowering (hypoglycemic) effects, though clinical relevance is not yet established.', 'Monitor blood glucose if combining; adjust antidiabetic therapy with the prescriber as needed.', 'Memorial Sloan Kettering, About Herbs ''Cordyceps''.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1198', 'H249', 'drug_interaction', 'Immunosuppressants (cyclosporine, tacrolimus, corticosteroids) and transplant regimens', 'moderate', 'As an immunomodulating fungus it could theoretically oppose immunosuppression; however evidence is bidirectional, with kidney-transplant studies showing reduced rejection and nephrotoxicity when combined, so the interaction is complex.', 'Use only under the transplant or specialist team''s supervision, never self-directed; do not start or stop around active immunosuppressive therapy without oversight.', 'RxList / Natural Medicines, Cordyceps; NCCIH / PMC review of Cordyceps immunomodulation (PMC7898063).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1199', 'H249', 'condition', 'Myelogenous-type cancers (leukemias)', 'moderate', 'Animal studies show cordyceps stimulates red blood cell proliferation, which could be undesirable in myelogenous malignancies.', 'Avoid in people with myelogenous-type cancers; any use in oncology only under the treating team.', 'Memorial Sloan Kettering, About Herbs ''Cordyceps''.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1200', 'H249', 'condition', 'Acute infection / febrile exterior illness with excess heat', 'moderate', 'A warming, rich yang-and-essence tonic can retain a pathogen and worsen acute heat or exterior illness (traditional contraindication).', 'Withhold during acute infection and high fever; resume only once the acute stage has resolved.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Dong Chong Xia Cao).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1201', 'H249', 'other', 'Mushroom / fungal allergy', 'low', 'As a fungus it can provoke hypersensitivity in mushroom-sensitive individuals.', 'Avoid in those with known mushroom allergy; discontinue if allergic symptoms occur.', 'RxList / Natural Medicines, Cordyceps.');
