INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H250', 'TCM01', 'Minor', 'Kidney Yang deficiency / interior cold: cool nature burdens failing yang without damp congestion; pair with warming yang tonics.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Chamaelirium (Helonias)'', which records the root as a bitter uterine tonic for atony, threatened abortion, amenorrhea, dysmenorrhea with pelvic congestion, leucorrhea, and the dyspepsia ", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Chamaelirium (Helonias)'', which records the root as a bitter uterine tonic for atony, threatened abortion, amenorrhea, dysmenorrhea with pelvic congestion, leucorrhea, and the dyspepsia ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Herbal Reality, ''False Unicorn (Chamaelirium luteum)'' (energetics, constituents, dosage, and pregnancy or lactation guidance); WebMD, ''False Unicorn'' (modern pregnancy, breastfeeding, and drug-interaction data, including lithium, CYP2D6, an", "locator": "Herbal Reality, ''False Unicorn (Chamaelirium luteum)'' (energetics, constituents, dosage, and pregnancy or lactation guidance); WebMD, ''False Unicorn'' (modern pregnancy, breastfeeding, and drug-interaction data, including lithium, CYP2D6, an", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1202', 'H250', 'pregnancy', 'Pregnancy (self-care / unsupervised use)', 'moderate', 'Uterine-active emmenagogue; modern references state it may cause uterine contractions and threaten the pregnancy, and it is emetic and cardiotoxic (chamaelirin) in overdose. Traditional use for threatened miscarriage is practitioner-administered only.', 'Avoid in pregnancy for self-care. Any use in pregnancy (including the historical threatened-miscarriage indication) is reserved for a qualified practitioner; do not self-dose.', 'WebMD, False Unicorn (''UNSAFE... might cause uterine contractions and threaten the pregnancy''); Herbal Reality, False Unicorn (''only... under the supervision of a medical herbalist''); AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1203', 'H250', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient modern safety data; transfer of steroidal saponins into breast milk is not characterized.', 'Avoid while nursing unless directed and supervised by a qualified practitioner.', 'WebMD, False Unicorn (''not enough is known... avoid use''); Herbal Reality, False Unicorn.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1204', 'H250', 'drug_interaction', 'Lithium', 'moderate', 'A mild diuretic action may reduce lithium excretion, raising serum lithium toward toxic levels.', 'Avoid the combination or use only with prescriber-directed monitoring of lithium levels.', 'WebMD, False Unicorn (moderate interaction).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1205', 'H250', 'drug_interaction', 'Drugs metabolized by CYP2D6 (e.g. some antidepressants, opioid analgesics)', 'moderate', 'May slow CYP2D6 metabolism, increasing levels, effects, and side effects of substrate drugs.', 'Monitor for increased drug effects; adjust with the prescriber as needed.', 'WebMD, False Unicorn (moderate interaction).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1206', 'H250', 'drug_interaction', 'Drugs metabolized by CYP3A4 (e.g. certain statins, antifungals)', 'moderate', 'May alter CYP3A4 metabolism, changing levels of substrate drugs.', 'Monitor for altered drug effects; coordinate with the prescriber.', 'WebMD, False Unicorn (moderate interaction).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1207', 'H250', 'condition', 'Overdose / large-dose toxicity', 'moderate', 'Large doses are emetic and sialagogue (nausea, vomiting), and the principal saponin chamaelirin is described as cardiotoxic (a heart poison) in excess.', 'Use low doses only; never exceed recommended amounts. Refer urgently for persistent vomiting, palpitations, or cardiac symptoms.', 'King''s American Dispensatory (Felter & Lloyd, 1898), Chamaelirium; WebMD, False Unicorn (large doses cause nausea and vomiting).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1208', 'H250', 'condition', 'Estrogen-sensitive conditions / concurrent hormone therapy', 'low', 'Diosgenin-based steroidal saponins carry hormone-like (estrogen-modulating) activity; theoretical, mechanism-based concern.', 'Use cautiously and under professional guidance in estrogen-sensitive conditions or alongside hormonal therapy.', 'Herbal Reality, False Unicorn (diosgenin hormone-like activity); mechanistic (theoretical).');
