INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H250', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Chamaelirium (Helonias)'', which records the root as a bitter uterine tonic for atony, threatened abortion, amenorrhea, dysmenorrhea with pelvic congestion, leucorrhea, and the dyspepsia ", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Chamaelirium (Helonias)'', which records the root as a bitter uterine tonic for atony, threatened abortion, amenorrhea, dysmenorrhea with pelvic congestion, leucorrhea, and the dyspepsia ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Herbal Reality, ''False Unicorn (Chamaelirium luteum)'' (energetics, constituents, dosage, and pregnancy or lactation guidance); WebMD, ''False Unicorn'' (modern pregnancy, breastfeeding, and drug-interaction data, including lithium, CYP2D6, an", "locator": "Herbal Reality, ''False Unicorn (Chamaelirium luteum)'' (energetics, constituents, dosage, and pregnancy or lactation guidance); WebMD, ''False Unicorn'' (modern pregnancy, breastfeeding, and drug-interaction data, including lithium, CYP2D6, an", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H251', 'Great Burnet', 'Sanguisorba officinalis', 'Rosaceae (the rose family). Great Burnet is the type species of the genus Sanguisorba; the culinary Salad (Lesser) Burnet is the related Sanguisorba minor, syn. Poterium sanguisorba, a distinct plant.', 'Root and rhizome (Radix Sanguisorbae, the TCM Di Yu, the primary medicinal part, frequently dry-fried to charring as Di Yu Tan to heighten its hemostatic action), and secondarily the aerial herb and leaves, which are astringent and styptic and were used in European practice for hemorrhage and wounds.', 'Bitter, Sour, Astringent (a hard, drying, tannic, faintly sour taste).', 'Cold', 'Dry', 'Laxity of the tissues that leak and bleed: the over-relaxed, over-open capillaries and mucous membranes that pour out blood (bloody stool, bleeding hemorrhoids, flooding uterine bleeding, blood in vomit, urine, or sputum), which a tannin-rich astringent tightens and seals. Excess heat in the blood, the reckless hot blood that overflows its vessels as bright, hot bleeding, cooled and settled by a cold, bitter, blood-cooling root. Acute inflammation and heat of the lower bowel and the skin: burning, inflamed, bleeding hemorrhoids and damp-heat dysentery, hot swollen burns and scalds, and weeping, inflamed eczema. Ulceration of gut and skin, the raw, weeping, poorly healing surface (peptic ulceration, burns, sores) that its astringent, vulnerary action draws together. Dampness with heat, the boggy, hot, weeping discharge of bowel and skin, dried and drained. In every case the tissue is hot, lax, weeping, and bleeding, and it is the cooling, astringing, sealing action of the herb that draws it back toward tone.', 'Cold: a cold, bitter herb is wrong for bleeding, diarrhea, and discharge that arise from cold and yang deficiency rather than heat, where it further chills a failing digestive fire. Dryness: a strongly drying, tannic astringent deepens dryness, atrophy, and fluid depletion. Deficiency: bleeding from qi or yang deficiency (rather than blood heat) is not corrected by astringency and cold alone and may be worsened. Stagnation: in the early acute stage of damp-heat dysentery, before the pathogenic damp-heat has been expelled, premature astringency can trap and retain the pathogen; and it is not a herb for bleeding due to blood stasis, where staunching without moving blood is counterproductive.', 'Digestive above all, and especially the lower bowel: the classic herb for bloody stool, bleeding and inflamed hemorrhoids, damp-heat (bacillary) dysentery, chronic diarrhea, and bleeding peptic ulceration. Integumentary (skin): a leading topical remedy for burns and scalds, wounds and sores, and weeping, inflamed eczema, applied as powder, ointment, or wash. Reproductive: for heavy menstrual bleeding and uterine hemorrhage of the heat type. Cardiovascular in the sense of the blood itself, as a general hemostatic that cools and staunches reckless hot bleeding from many sites (hematemesis, epistaxis, hematuria). Hepatic (liver), which its channel-entry and blood-cooling action reach, with modern research reporting hepatoprotective and antioxidant constituents. Secondary Urinary affinity (a mild diuretic and remedy for blood in the urine per European tradition).', 'Hot-type bleeding from the lower body above all: bloody stool and bleeding, inflamed hemorrhoids, damp-heat (bacillary) dysentery and chronic bloody diarrhea, and heavy or flooding uterine bleeding. General hemostasis for hot, reckless bleeding, including vomiting of blood, nosebleed, and blood in the urine. Burns and scalds, a signature external use, and wounds, sores, and non-healing ulcers dressed with the root. Weeping, inflamed, hot eczema and dermatitis, applied topically. Bleeding peptic ulceration. It is a symptomatic astringent hemostatic and heat-clearing herb for the acute leaking of hot blood and the raw, weeping surface, not a deep tonic; significant or unexplained bleeding requires medical evaluation alongside its use.', 'Hot-Damp-Lax, the plethoric, hot-blooded terrain that leaks and bleeds: the robust, ruddy, full-blooded choleric or sanguine person whose reckless hot blood overflows its vessels as bright bleeding, whose damp-heat pools in the lower bowel as burning, bloody dysentery and inflamed hemorrhoids, and whose skin weeps, burns, and ulcerates with heat. A cold, sour, astringent root meets this by cooling the blood, draining damp-heat, and tightening the lax, leaking tissue. It is least suited to the thin, cold, dry, depleted (Vata-like) constitution and the cold, damp phlegmatic, in whom its cold, drying astringency deepens cold, dryness, and depletion.', 'Pitta, Kapha', 'Vata', 'Di Yu (Sanguisorbae Radix) is a genuine herb of the Chinese materia medica, classed among the herbs that cool the blood and stop bleeding. It is bitter, sour, and cold and enters the Liver, Stomach, and Large Intestine. It cools the blood and stops bleeding in patterns of blood heat, where heat drives the blood recklessly out of its vessels (bloody stool, bleeding hemorrhoids, blood in the urine, and uterine bleeding, most classically bleeding of the lower body). It clears heat and resolves fire toxicity and, applied externally, heals burns, scalds, and sores. Through its heavy, cold, astringent nature it also drains and dries damp-heat lodged in the lower burner (damp-heat dysentery). Its charred form (Di Yu Tan) is favored to enhance the hemostatic action.', 'Deficiency-cold patterns: bleeding, diarrhea, and discharge from Spleen and Kidney yang deficiency and interior cold, where a bitter, cold herb injures the yang and the digestive fire. Bleeding without heat (from qi deficiency failing to hold the blood, or from blood stasis), which calls for tonifying or blood-moving rather than cold astringing. The early acute stage of damp-heat dysentery before the pathogenic damp-heat has been expelled, when premature astringency can retain the pathogen.', 'Great Burnet root taken internally at ordinary doses has a long record of safe use and low toxicity, and modern studies of the root report no significant toxicity. The main cautions are three. First, timing in dysentery: because it is strongly astringent, it should not be given in the very early stage of damp-heat dysentery, when the pathogenic damp-heat still needs to be expelled, lest the astringency trap the pathogen. Second, and most important, extensive topical use on burns: although the powdered or ointment root is a classic dressing for burns and scalds, it must not be applied over large burn surfaces (roughly a third of the body or more), because its high tannin content can be absorbed through the damaged skin and cause toxic hepatitis. Third, constitutional fit: as a cold, drying astringent it is wrong for bleeding and diarrhea of the cold, deficient type and can chill and dry an already cold, depleted, or dry person. Being very tannin-rich, large internal doses may cause digestive upset or nausea and can hinder the absorption of iron and other nutrients and drugs taken at the same time.', 'Bleeding or diarrhea of the deficiency-cold type (Spleen or Kidney yang deficiency, interior cold), in which a cold, bitter astringent is inappropriate. The early acute stage of damp-heat dysentery, before the damp-heat is cleared. Extensive burns: do not apply topically over large areas of the body (approximately 30 percent body surface or more) because of systemic tannin absorption and hepatotoxic risk; reserve topical use for localized burns. Marked dryness, atrophy, or fluid depletion, which its drying astringency worsens. Pregnancy and lactation at therapeutic doses without professional supervision (insufficient safety data). Known hypersensitivity to the herb.', 'Avoid therapeutic (especially internal) doses in pregnancy unless supervised by a qualified practitioner. There is no reliable human safety data for Great Burnet in pregnancy: the WebMD ingredient monograph for Greater Burnet advises that there is not enough reliable information to know if it is safe and to stay on the safe side and avoid use, and standard Chinese materia medica practice treats blood-cooling, astringent hemostatics cautiously in pregnancy. It is not a documented abortifacient, but its cold, astringent nature and the absence of established safety data make avoidance of medicinal doses the prudent, consumer-safe course. Confirm the exact AHPA Botanical Safety Handbook class at merge.', 'Insufficient data; avoid therapeutic doses during lactation without professional guidance. It is not known whether Great Burnet''s tannins and saponins pass into breast milk or affect a nursing infant, and the WebMD Greater Burnet monograph advises avoiding use for lack of reliable safety information. Incidental culinary or topical exposure to a small area is of low concern, but concentrated internal doses should await better data or qualified supervision. (Source: WebMD, Greater Burnet; Chen & Chen, Chinese Medical Herbology and Pharmacology, Di Yu.)', 'Localized topical use of the root for minor burns, sores, and weeping skin is traditional and generally gentle, but internal therapeutic dosing in children should be undertaken only under professional guidance, with no established pediatric self-dosing range. The large-burn caution applies with particular force to small children: never dress an extensive burn with tannin-rich burnet preparations, since a burn covers a proportionally larger share of a child''s body surface and systemic tannin absorption raises the risk of toxic hepatitis. Any significant burn or bleeding in a child is a matter for medical care, not self-treatment. (Source: Chen & Chen, Chinese Medical Herbology and Pharmacology, Di Yu.)', 'Documented clinical interactions are limited; the well-grounded cautions are pharmacologic. Because the root is very rich in tannins (around 17 percent), it can bind and reduce the absorption of iron and other mineral supplements, alkaloidal drugs, and other medicines taken at the same time; separate oral dosing by at least two hours. Anticoagulant and antiplatelet drugs (for example warfarin, aspirin, clopidogrel): the interaction is uncertain and may be bidirectional, because the herb is used clinically as a hemostatic (which could theoretically oppose anticoagulation) yet also contains, in vitro, anticoagulant polysaccharide-polyphenol conjugates acting through heparin cofactor II; if the herb and these drugs are combined, monitor coagulation and bleeding. Beyond these, no well-documented pharmacokinetic drug interactions are established (limited data). (Sources: Zhao et al., A Comprehensive Review of Genus Sanguisorba, 2021, PMC8488092; Chen & Chen, Chinese Medical Herbology and Pharmacology, Di Yu; general tannin pharmacology.)', 'Decoction of the dried root (the standard internal TCM form), often using the charred root (Di Yu Tan) when the aim is to stop bleeding. Powder of the dried or charred root, taken internally or dusted onto wounds, burns, and bleeding surfaces. Ointment or salve and lotion or wash of the root for burns, scalds, wounds, hemorrhoids, and weeping eczema (localized areas only). Poultice and compress of the fresh or reconstituted root or the fresh leaves for bleeding and inflamed skin. Tincture of the root. Infusion (tea) of the astringent leaves, used in European tradition for hemorrhage and diarrhea.', 'Decoction: 9 to 15 g dried root per day (up to 30 g in acute bleeding), the charred root preferred when stopping hemorrhage. Powder: 1.5 to 3 g taken internally, or applied topically to the affected area. Tincture (1:5): 2 to 4 mL up to three times daily. Topical: apply the powder, ointment, or wash to localized burns, wounds, or weeping skin; do not apply over extensive burn surfaces (roughly 30 percent of the body or more) because of tannin absorption and hepatotoxic risk. Significant internal bleeding calls for professional care alongside any herbal use.', 'Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. TCM anchor: the Shennong Ben Cao Jing tradition and later Chinese materia medica, ''Di Yu'' (Sanguisorbae Radix), for cooling the blood and stopping bleeding.', 'Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu; Zhao, Z. et al., ''A Comprehensive Review of Genus Sanguisorba: Traditional Uses, Chemical Constituents and Medical Applications,'' 2021 (Molecules / PMC8488092); WebMD, ''Greater Burnet''; TCM Wiki and Me & Qi, Di Yu (Sanguisorba root).', 'Sanguisorba officinalis is a rhizomatous herbaceous perennial of the Rosaceae, native across temperate Europe and Asia, with deep maroon oblong flower-heads on tall stems; the genus name, from Latin sanguis (blood) and sorbere (to soak up or staunch), records its ancient European reputation as a styptic wound herb, and its English and Chinese uses converge on stopping bleeding. It should be distinguished from the culinary Salad (Lesser) Burnet, Sanguisorba minor (syn. Poterium sanguisorba). The root''s defining constituents are hydrolyzable tannins (around 17 percent, including sanguiin H-6 and gallotannins), triterpenoid saponins (ziyuglycoside I and II), and gallic and ellagic acids, with flavonoids; these underlie its documented hemostatic, astringent, antibacterial (notably against dysentery organisms), anti-inflammatory, antioxidant, and wound- and burn-healing effects, with active research interest in antiviral, antitumor, and hepatoprotective actions. In TCM the charred root (Di Yu Tan) is the classic hemostatic form. Two bounding cautions define safe use: it is withheld in the early acute stage of damp-heat dysentery, and it is never applied over extensive burn surfaces because absorbed tannin can cause toxic hepatitis.', 'Not named in the canonical biblical texts nor in the classical Greco-Roman herbals under this identity; Great Burnet is a plant of temperate European and Asian tradition, not of the ancient Holy Land flora. Its European standing as a wound and hemorrhage herb is preserved in the genus name Sanguisorba (Latin sanguis, blood, and sorbere, to staunch). In East Asia the root, Di Yu, is a long-established herb of the Chinese materia medica for cooling the blood and stopping bleeding, within the tradition reaching back to the Shennong Ben Cao Jing. Cited honestly as a herb of European folk medicine and Chinese medical tradition rather than of Scripture.', 'Sanguisorba officinalis is widespread across temperate Eurasia and is not listed as at-risk by United Plant Savers; it is also widely grown as a hardy garden ornamental, so cultivated root is readily and sustainably obtained and should be preferred for medicine. Note that in parts of its native range wild Great Burnet is a locally declining wet-meadow plant and the obligate host of rare large blue (Phengaris) butterflies, so wild stands carry real ecological value: favor cultivated material and do not dig wild roots from sensitive or protected meadow habitats.', 'Cold and drying: a bitter, sour, astringent root that cools reckless hot blood, staunches bleeding, and tightens lax, weeping, ulcerated tissue in the hot, damp-heat lower bowel and skin.', 'Significant or unexplained bleeding is a medical matter, not a self-care one: refer at once for vomiting or coughing of blood, black tarry or bloody stools, heavy or prolonged uterine bleeding, blood in the urine, and any signs of internal hemorrhage such as dizziness, pallor, fainting, or a rapid pulse. Refer any burn that is more than small and superficial, and all facial, hand, genital, blistering (partial thickness), deep, or large-area burns, to emergency care. Refer bloody diarrhea or dysentery accompanied by high fever, severe abdominal pain, or dehydration, and any non-healing ulcer or sore. Great Burnet may support these situations only alongside, never in place of, proper evaluation.', 'Great Burnet: GRAYT BUR-nit. Sanguisorba officinalis: sang-gwih-SOR-buh oh-fiss-ih-NAY-liss. Di Yu: dee yoo.', 'free', 'Approved', '{"title": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "locator": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "locator": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H251', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H251', 'T06');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H251', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS09', 'Primary', 'Laxity: tightens over-relaxed, leaking capillaries and mucous membranes that pour out blood (the defining astringent-hemostatic action; drives the tonic tone).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS05', 'Primary', 'Excess heat: cools the reckless hot blood that overflows its vessels as bright, hot bleeding.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS25', 'Secondary', 'Ulceration: draws together raw, weeping, poorly healing surfaces of gut and skin (peptic ulcer, burns, sores).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS06', 'Secondary', 'Acute inflammation: hot, swollen, inflamed hemorrhoids, dysentery, burns, and weeping eczema.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS07', 'Secondary', 'Dampness (damp-heat): drains and dries the boggy, hot, weeping discharge of the lower bowel and skin.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS15', 'Minor', 'Acute infection: antibacterial action in bacillary dysentery and infected burns and wounds.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS17', 'Primary', 'Cold: a cold, bitter herb worsens bleeding, diarrhea, and discharge that arise from cold and yang deficiency.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS03', 'Primary', 'Dryness: a strongly drying, tannic astringent deepens dryness and fluid depletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS01', 'Secondary', 'Deficiency: bleeding from qi or yang deficiency (not heat) is not corrected by cold astringency alone and may worsen.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H251', 'TS08', 'Secondary', 'Stagnation: premature astringency in early damp-heat dysentery can trap the pathogen; not for bleeding due to blood stasis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY08', 'Primary', 'Digestive, esp. lower bowel: bloody stool, bleeding hemorrhoids, damp-heat dysentery, bloody diarrhea, bleeding peptic ulcer.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY10', 'Primary', 'Integumentary: leading topical remedy for burns, scalds, wounds, sores, and weeping eczema.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY03', 'Secondary', 'Reproductive: heavy menstrual bleeding and uterine hemorrhage of the heat type.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY06', 'Secondary', 'Cardiovascular / the blood: general hemostatic that cools and staunches reckless hot bleeding (hematemesis, epistaxis, hematuria).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY12', 'Secondary', 'Hepatic: enters the Liver channel and cools the blood; modern research reports hepatoprotective, antioxidant constituents.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H251', 'SY09', 'Minor', 'Urinary: mild diuretic and traditional remedy for blood in the urine.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A15', 'Primary', 'Astringent: tannin-rich root that tightens lax, leaking tissue (the defining action).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A50', 'Primary', 'Styptic/hemostatic: cools and stops hot bleeding from many sites; charred Di Yu Tan the classic form.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A09', 'Secondary', 'Anti-inflammatory: settles inflamed, swollen, bleeding hemorrhoids, dysentery, burns, and eczema.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A24', 'Secondary', 'Vulnerary: heals wounds, sores, ulcers, and burns applied topically.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A49', 'Secondary', 'Febrifuge/antipyretic: refrigerant, clears heat, used in fevers (Grieve).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A28', 'Secondary', 'Antimicrobial: broad antimicrobial activity, incl. against burn and wound organisms.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A29', 'Secondary', 'Antibacterial: notably active against dysentery-causing bacteria.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A25', 'Minor', 'Antioxidant: gallic/ellagic acids and tannins scavenge free radicals.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A08', 'Minor', 'Diuretic: the root is mildly diuretic (European tradition).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H251', 'A14', 'Minor', 'Alterative: clears heat and resolves fire toxicity for toxic-heat sores and inflamed skin.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP56', 'Primary', 'Diarrhea: bloody, damp-heat diarrhea and dysentery, staunched and cooled.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP61', 'Primary', 'Hemorrhoids: bleeding, inflamed hemorrhoids (a classic use, internal and topical).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP31', 'Primary', 'Menorrhagia: heavy menstrual and uterine bleeding of the heat type.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP08', 'Secondary', 'Poor wound healing: vulnerary root that draws together wounds, sores, ulcers, and burns.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP67', 'Secondary', 'Eczema/dermatitis: weeping, inflamed, hot eczema, applied topically.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP62', 'Minor', 'Dysbiosis/intestinal infection: antibacterial action in bacillary dysentery and chronic intestinal infection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP13', 'Minor', 'Inflammation: anti-inflammatory action on inflamed, bleeding tissue.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H251', 'CP76', 'Minor', 'Fever management: refrigerant, febrifuge use in fevers (Grieve).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P04', 'Primary', 'Decoction of the dried (often charred) root, the standard internal form for bleeding and dysentery.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P08', 'Primary', 'Poultice of the root or fresh leaves for bleeding, inflamed, and burned skin (localized).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P07', 'Primary', 'Salve/ointment (and lotion/wash) for burns, scalds, wounds, hemorrhoids, and weeping eczema; localized areas only.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P01', 'Secondary', 'Tincture of the root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P03', 'Secondary', 'Powder of the dried or charred root, internal or dusted onto bleeding surfaces.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P05', 'Secondary', 'Infusion (tea) of the astringent leaves for hemorrhage and diarrhea (European tradition).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H251', 'P10', 'Minor', 'Compress/wash of the decoction for weeping, bleeding skin.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H251', 'C06', 'Indicated', 'Primary', 'Robust/Hot (Pitta-like): the ruddy, hot-blooded, plethoric person with reckless hot bleeding and damp-heat.', '{"title": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "locator": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "locator": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
