INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1209', 'H251', 'pregnancy', 'Pregnancy (therapeutic/internal doses)', 'moderate', 'No reliable human safety data; a cold, astringent, blood-cooling herb of uncertain safety in pregnancy.', 'Avoid therapeutic internal doses in pregnancy unless supervised by a qualified practitioner; confirm AHPA class at merge.', 'WebMD, Greater Burnet ingredient monograph; Chen & Chen, Chinese Medical Herbology and Pharmacology (Di Yu); AHPA Botanical Safety Handbook (class to confirm).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1210', 'H251', 'breastfeeding', 'Breastfeeding (therapeutic/internal doses)', 'moderate', 'Unknown whether tannins/saponins pass into breast milk; no reliable human safety data during lactation.', 'Avoid concentrated internal doses while nursing without professional guidance; incidental topical use of a small area is lower concern.', 'WebMD, Greater Burnet ingredient monograph; Chen & Chen, Chinese Medical Herbology and Pharmacology (Di Yu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1211', 'H251', 'condition', 'Extensive burns (roughly 30% body surface or more), topical use', 'moderate', 'High tannin content absorbed through damaged skin over a large area can cause systemic tannin toxicity and toxic hepatitis.', 'Do not apply the root (powder/ointment) over large burn surfaces; reserve topical use for small, localized burns and refer extensive burns to emergency care.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology (Di Yu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1212', 'H251', 'condition', 'Early acute stage of damp-heat dysentery', 'moderate', 'Strong astringency applied before the pathogenic damp-heat is expelled can trap and retain the pathogen.', 'Do not use in the very early stage; introduce only after the damp-heat has begun to clear, or combine with damp-heat-clearing herbs under professional guidance.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica; Chen & Chen (Di Yu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1213', 'H251', 'condition', 'Deficiency-cold bleeding and diarrhea (no heat sign)', 'moderate', 'A bitter, cold herb can injure Spleen and Kidney yang and worsens bleeding or diarrhea arising from cold and deficiency rather than blood heat.', 'Avoid, or combine with warming, qi-tonifying herbs, when the pattern is cold and deficient rather than hot.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica; Chen & Chen (Di Yu).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1214', 'H251', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (e.g. warfarin, aspirin, clopidogrel)', 'moderate', 'Uncertain, possibly bidirectional effect on coagulation: clinical hemostatic use could oppose anticoagulation, while in-vitro anticoagulant polysaccharide-polyphenol conjugates (via heparin cofactor II) could add to it.', 'If combined with anticoagulant or antiplatelet therapy, monitor coagulation and for bleeding, and involve the prescriber.', 'Zhao et al., A Comprehensive Review of Genus Sanguisorba (2021), PMC8488092; mechanistic.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1215', 'H251', 'drug_interaction', 'Oral iron and mineral supplements, alkaloidal drugs, and other oral medicines', 'low', 'The very high tannin content binds minerals, alkaloids, and other constituents in the gut and can reduce their absorption.', 'Separate oral dosing of Great Burnet from iron, mineral supplements, and medicines by at least two hours.', 'Zhao et al., A Comprehensive Review of Genus Sanguisorba (2021), PMC8488092; general tannin pharmacology.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H251', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "locator": "Grieve, A Modern Herbal (1931), ''Burnet, Great'' (Sanguisorba officinalis), recording the root as astringent, styptic, haemostatic, tonic, and vulnerary for hemorrhage, dysentery, diarrhea, menorrhagia, bloody stool, hemorrhoids, and burns. ", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "locator": "Chen, J.K. & Chen, T.T., Chinese Medical Herbology and Pharmacology (2004), Di Yu (dosing, the early-dysentery and large-burn/tannin-hepatotoxicity cautions); Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Di Yu;", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, true);
