INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H252', 'TCM07', 'Secondary', 'Yin deficiency with dryness: a drying, draining root worsens fluid depletion.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Hydrangea'' (Hydrangea arborescens, the root), which details its use as a solvent and eliminative remedy for calculous and gravelly deposits of the bladder, its relief of vesical and uret", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), ''Hydrangea'' (Hydrangea arborescens, the root), which details its use as a solvent and eliminative remedy for calculous and gravelly deposits of the bladder, its relief of vesical and uret", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), ''Hydrangea''; Grieve, A Modern Herbal (1931), ''Hydrangea''; Southern Cross University Medicinal Plant Monograph, ''Hydrangea arborescens'' (constituents, cautions, preg", "locator": "Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919), ''Hydrangea''; Grieve, A Modern Herbal (1931), ''Hydrangea''; Southern Cross University Medicinal Plant Monograph, ''Hydrangea arborescens'' (constituents, cautions, preg", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1216', 'H252', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient pharmacological and toxicity data; the root carries a cyanogenic glycoside (hydrangin) and emetic quinazoline alkaloids (febrifugine, isofebrifugine).', 'Avoid during pregnancy; do not use even the specific-medication doses without qualified supervision.', 'Southern Cross University Medicinal Plant Monograph (Hydrangea arborescens); Healthline, Hydrangea Root.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1217', 'H252', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion of constituents into breast milk; same cyanogenic-glycoside and emetic-alkaloid concerns; insufficient safety data.', 'Avoid while nursing without professional guidance.', 'Southern Cross University Medicinal Plant Monograph (Hydrangea arborescens); Healthline, Hydrangea Root.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1218', 'H252', 'drug_interaction', 'Diuretics, lithium, and cardiac glycosides (digoxin)', 'low', 'As a diuretic it adds to diuresis and can deplete electrolytes, notably potassium; theoretically it may raise serum lithium by reducing renal clearance and heighten cardiac-glycoside sensitivity through potassium loss. Theoretical/mechanistic, not documented case reports.', 'Monitor blood pressure and electrolytes with other diuretics; use caution with lithium and digoxin and involve the prescriber; avoid prolonged high-dose use.', 'Brinker, Herb Contraindications and Drug Interactions (diuretic-class caution); 7Song, Wild Hydrangea monograph (electrolyte and blood-pressure caution).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1219', 'H252', 'condition', 'Overdose / higher-than-specified doses', 'moderate', 'Overdose produces dizziness and a sense of chest oppression or constriction, with gastroenteritis, nausea, vomiting, and central-nervous-system disturbance; the cyanogenic glycoside and emetic alkaloids underlie this narrow margin.', 'Keep strictly to low, measured doses (specific hydrangea 5 to 30 drops); do not exceed or take long-term unsupervised; discontinue if dizziness or chest tightness occurs.', 'King''s American Dispensatory 1898 (Hydrangea, overdose symptoms); Southern Cross University Medicinal Plant Monograph; Healthline, Hydrangea Root.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1220', 'H252', 'condition', 'Large or obstructing urinary stones, urinary obstruction/retention, significant kidney disease', 'moderate', 'Hydrangea eases passage and discourages deposit but does not dissolve large, established stones; an obstructing stone or retention is a surgical/urological emergency, and diuresis against obstruction can worsen it.', 'Do not self-treat; refer large or obstructing stones, obstruction, retention, or significant renal disease for urological evaluation.', 'Southern Cross University Medicinal Plant Monograph; King''s American Dispensatory 1898 (eliminative, not dissolving, action).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1221', 'H252', 'other', 'Contact dermatitis / hydrangenol sensitivity', 'low', 'The stilbenoid hydrangenol in the fresh plant and dust is a contact allergen and can cause dermatitis in sensitive handlers.', 'Handle the fresh plant and root dust with care; avoid in those with known Hydrangea sensitivity.', 'Southern Cross University Medicinal Plant Monograph; Healthline, Hydrangea Root.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1222', 'H252', 'condition', 'Children (self-directed use)', 'moderate', 'No established pediatric dosing; cyanogenic glycoside, emetic alkaloids, and overdose potential make casual use in children inappropriate.', 'Reserve any pediatric use to a qualified practitioner; refer children with stones, obstruction, or urinary infection for medical care.', 'Healthline, Hydrangea Root; Southern Cross University Medicinal Plant Monograph.');
