INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H253', 'TCM11', 'Secondary', 'Heat / Fire: clears damp-heat from the lower burner, skin, joints, and the purulent abscess picture.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H253', 'TCM07', 'Primary', 'Yin deficiency: draining and urine-promoting action injures fluids in yin- and fluid-deficient dryness.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H253', 'TCM06', 'Secondary', 'Blood deficiency: a reducing, draining herb is wrong for blood- and fluid-poor, dry states.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica / Classic of the Materia Medica, Han dynasty, public domain) - Yi Yi Ren (Coicis Semen), listed among the superior (upper-class) medicines: sweet and slightly cold, used to drain dam", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed) - Yi Yi Ren / Coicis Semen (energetics, channels, functions, dosage 9 to 30 g, and the pregnancy contraindication). Modern pharmacology and phytochemistry reviews: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1223', 'H253', 'pregnancy', 'Pregnancy', 'absolute', 'Classically contraindicated in pregnancy in the Chinese materia medica; modern animal studies show aqueous and oil extracts of coix seed stimulate uterine contraction and exert embryotoxic, abortifacient effects in pregnant rodents.', 'Avoid medicinal and therapeutic doses (decoctions, powders, extracts, and the Kanglaite oil preparation) throughout pregnancy; even culinary use of the grain is traditionally avoided as a precaution, and regular or concentrated use should not be taken.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (pregnancy contraindication for Coicis Semen); peer-reviewed animal uterine-stimulant and embryotoxicity studies of coix seed extracts; AHPA Botanical Safety Handbook framework.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1224', 'H253', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin and others)', 'moderate', 'Coix polysaccharides have documented blood-sugar-lowering activity that may be additive with glucose-lowering drugs, risking hypoglycemia.', 'Monitor blood glucose; adjust antidiabetic therapy only with the prescriber; introduce cautiously.', 'Reviews of Coix lacryma-jobi hypoglycemic polysaccharide activity; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1225', 'H253', 'condition', 'Yin, blood, and body-fluid deficiency; dryness; spleen deficiency without dampness', 'moderate', 'Its cool, draining, urine-promoting action depletes fluids and can aggravate dryness, constipation, and depletion where there is no dampness to drain.', 'Avoid or minimize in dry, fluid-depleted, or frankly deficient states and in spleen deficiency without dampness; if used, pair with moistening, tonifying correctives and keep courses short.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (classical contraindication); traditional energetics.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1226', 'H253', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable data on transfer of coix constituents into breast milk or on effects in the nursing infant, and none for concentrated extracts such as Kanglaite; food-grade grain is generally regarded as acceptable.', 'Culinary amounts are reasonable; avoid concentrated therapeutic doses and extracts while breastfeeding unless directed by a qualified practitioner.', 'Precautionary; AHPA Botanical Safety Handbook / Mills and Bone / Brinker framework; no NCCIH lactation entry.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1227', 'H253', 'drug_interaction', 'Pharmaceutical diuretics (loop, thiazide)', 'low', 'As a diuretic damp-draining herb, coix may add to the fluid- and electrolyte-shifting effect of pharmaceutical diuretics.', 'Use cautiously with prescription diuretics; monitor hydration and electrolytes in those at risk.', 'Pharmacodynamic inference; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1228', 'H253', 'condition', 'Undiagnosed severe edema, suspected lung abscess, or acute abdomen', 'moderate', 'Severe or worsening edema may signal cardiac, renal, or hepatic failure; purulent or bloody cough may signal lung abscess; acute localized abdominal pain may be appendicitis or intestinal abscess, conditions that self-treatment can dangerously delay.', 'Do not self-treat severe or worsening edema, suspected lung abscess, or acute severe abdominal pain; refer for medical or surgical evaluation.', 'General clinical safety (refer threshold); standard herbal practice.');
