INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H254', 'TCM11', 'Primary', 'Heat / Fire: a warm, stimulating herb adds heat and can cause burning.', '{"title": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "locator": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "locator": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H254', 'TCM07', 'Secondary', 'Yin deficiency: its hot potency worsens empty heat and dryness.', '{"title": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "locator": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "locator": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H254', 'TCM10', 'Secondary', 'Dampness / Phlegm: its heavy, cloying, unctuous quality clogs and aggravates damp-phlegm accumulation.', '{"title": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "locator": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "locator": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1229', 'H254', 'drug_interaction', 'MAO inhibitors (phenelzine, tranylcypromine, isocarboxazid, linezolid)', 'absolute', 'The seed''s levodopa combined with a non-selective MAO inhibitor can precipitate a hypertensive crisis, a documented and potentially life-threatening event, and risks serotonergic toxicity.', 'Do not combine. Avoid Mucuna in anyone taking an MAO inhibitor and for at least two weeks after stopping one.', 'Levodopa clinical pharmacology (StatPearls; drug-interaction references); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1230', 'H254', 'pregnancy', 'Pregnancy', 'absolute', 'Mucuna is a concentrated levodopa source; L-dopa crosses the placenta and is hormonally active (suppresses prolactin), and an animal study reported increased fetal malformation in rats given the herb.', 'Avoid medicinal seed-powder and extract preparations in pregnancy. Even culinary velvet bean should be limited and thoroughly processed.', 'Reproductive-toxicity animal data; AHPA Botanical Safety Handbook / general levodopa pregnancy caution; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1231', 'H254', 'breastfeeding', 'Breastfeeding', 'moderate', 'The L-dopa in Mucuna suppresses prolactin, the hormone that maintains milk production, so it can reduce milk supply, and levodopa metabolites may reach the infant through milk.', 'Avoid medicinal preparations while breastfeeding. If galactagogue support is needed, this herb is counterproductive.', 'Levodopa / prolactin clinical pharmacology; general lactation-safety practice; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1232', 'H254', 'drug_interaction', 'Levodopa/carbidopa and other dopaminergic anti-Parkinson drugs (MAO-B and COMT inhibitors, dopamine agonists)', 'moderate', 'Additive dopaminergic effect can overshoot the intended dose, causing nausea, orthostatic hypotension, and dyskinesia; conversely, self-substitution can destabilise Parkinson''s control.', 'Do not add to or substitute for prescribed anti-Parkinson therapy except under a neurologist''s supervision with dose titration and monitoring.', 'Katzenschlager et al., J Neurol Neurosurg Psychiatry 2004; Brinker, Herbal Contraindications and Drug Interactions; levodopa clinical pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1233', 'H254', 'drug_interaction', 'Dopamine antagonists: antipsychotics (haloperidol, risperidone) and antiemetics (metoclopramide, prochlorperazine)', 'moderate', 'Mutual pharmacological antagonism, each drug and the herb blunting the other''s effect, with risk of worsening movement or psychiatric symptoms.', 'Avoid concurrent use unless supervised; watch for loss of drug efficacy and for movement or psychiatric changes.', 'Levodopa clinical pharmacology (drug-interaction references); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1234', 'H254', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Levodopa can cause orthostatic hypotension that is additive with blood-pressure-lowering medication.', 'Monitor blood pressure and for postural dizziness; introduce cautiously and adjust antihypertensives only with the prescriber.', 'Levodopa clinical pharmacology; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1235', 'H254', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin and others)', 'low', 'Documented hypoglycaemic activity of Mucuna may be additive with glucose-lowering drugs.', 'Monitor blood glucose; adjust antidiabetic therapy only with the prescriber.', 'Reviews of Mucuna pruriens hypoglycaemic activity; Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1236', 'H254', 'condition', 'Major psychiatric illness (psychosis, schizophrenia, mania)', 'moderate', 'Added dopaminergic load can exacerbate psychosis and manic or dopamine-dysregulation symptoms.', 'Avoid in active psychotic or manic illness; use in psychiatric patients only under specialist supervision.', 'Levodopa disease-interaction references; standard clinical practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1237', 'H254', 'condition', 'Malignant melanoma or undiagnosed suspicious pigmented skin lesions', 'moderate', 'Levodopa is a precursor of melanin and is cautioned in melanoma, where it may theoretically activate malignant cells.', 'Avoid in known melanoma; evaluate suspicious pigmented lesions before use.', 'Levodopa disease-interaction references (melanoma caution).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1238', 'H254', 'condition', 'Cardiovascular disease (arrhythmia, ischaemic heart disease), narrow-angle glaucoma, active peptic ulcer', 'moderate', 'These mirror the standard cautions for levodopa, whose dopaminergic and cardiovascular effects can aggravate arrhythmia, ischaemia, raised intraocular pressure, and ulceration.', 'Use only with medical oversight in these conditions; avoid where the risk outweighs benefit.', 'Levodopa disease-interaction references (Sinemet / carbidopa-levodopa).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1239', 'H254', 'other', 'Raw pod hairs (trichomes)', 'moderate', 'The pod trichomes bear the protease mucunain and are an intense mechanical and proteolytic irritant, causing severe itching and contact dermatitis.', 'Use only properly processed, dehaired seed material; avoid skin, eye, and airway contact with raw pods and hairs.', 'Grieve, A Modern Herbal (1931), Cowhage; dermatology / toxicology of Mucuna trichomes.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H254', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "locator": "Grieve, A Modern Herbal (1931), Cowhage / Cowage (Mucuna pruriens; Dolichos pruriens): the seed hairs used as a mechanical anthelmintic and the seed and root in traditional tonic use. The Ayurvedic Pharmacopoeia of India (Government of Indi", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "locator": "Classical Ayurvedic tradition: Charaka and Sushruta Samhitas (Atmagupta / Kapikacchu as a vajikarana aphrodisiac and Vata nervine, and its use in kampavata). Modern clinical and pharmacological evidence: Katzenschlager R, et al., ''Mucuna pr", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, true);
