INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H255', 'TCM07', 'Secondary', 'Yin Deficiency: a warm, drying herb worsens dryness and heat-from-emptiness.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 18th ed, 1898), ''Cypripedium'' (Lady''s Slipper, Nerve Root, American Valerian), which recognizes Cypripedium pubescens and Cypripedium parviflorum as official, classes the dried rhizome and roo", "locator": "King''s American Dispensatory (Felter and Lloyd, 18th ed, 1898), ''Cypripedium'' (Lady''s Slipper, Nerve Root, American Valerian), which recognizes Cypripedium pubescens and Cypripedium parviflorum as official, classes the dried rhizome and roo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physio-Medical Dispensatory (1869), ''Cypripedium''; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919); Hoffmann, Medical Herbalism (2003), which places lady''s slipper among the nervine tonics and trophorest", "locator": "Cook, The Physio-Medical Dispensatory (1869), ''Cypripedium''; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919); Hoffmann, Medical Herbalism (2003), which places lady''s slipper among the nervine tonics and trophorest", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H255', 'TCM11', 'Minor', 'Heat/Fire: warmth and stimulant, diaphoretic character add to heat rather than clear it.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 18th ed, 1898), ''Cypripedium'' (Lady''s Slipper, Nerve Root, American Valerian), which recognizes Cypripedium pubescens and Cypripedium parviflorum as official, classes the dried rhizome and roo", "locator": "King''s American Dispensatory (Felter and Lloyd, 18th ed, 1898), ''Cypripedium'' (Lady''s Slipper, Nerve Root, American Valerian), which recognizes Cypripedium pubescens and Cypripedium parviflorum as official, classes the dried rhizome and roo", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physio-Medical Dispensatory (1869), ''Cypripedium''; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919); Hoffmann, Medical Herbalism (2003), which places lady''s slipper among the nervine tonics and trophorest", "locator": "Cook, The Physio-Medical Dispensatory (1869), ''Cypripedium''; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919); Hoffmann, Medical Herbalism (2003), which places lady''s slipper among the nervine tonics and trophorest", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1240', 'H255', 'pregnancy', 'Pregnancy', 'moderate', 'No reliable modern human safety data for Cypripedium in pregnancy; off the legitimate market on conservation grounds and unclassified in the AHPA Botanical Safety Handbook; aromatic, stimulant warmth is a theoretical concern.', 'Avoid in pregnancy; choose a better-studied, sustainable nervine if a calming herb is needed.', 'Mills & Bone, Essential Guide to Herbal Safety (2005); AHPA Botanical Safety Handbook (2013, no assigned class); precautionary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1241', 'H255', 'breastfeeding', 'Breastfeeding', 'moderate', 'Unknown whether constituents or glandular quinones pass into breast milk; no modern lactation safety data; unclassified in the AHPA Botanical Safety Handbook.', 'Avoid therapeutic use while nursing; prefer a well-documented, sustainable nervine such as lemon balm.', 'Mills & Bone, Essential Guide to Herbal Safety (2005); AHPA Botanical Safety Handbook (2013, no assigned class); precautionary.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1242', 'H255', 'drug_interaction', 'CNS depressants and sedatives (benzodiazepines, barbiturates, hypnotics, opioids, alcohol)', 'moderate', 'As a sedative, antispasmodic nervine it may add to central nervous system depression and drowsiness (theoretical, additive).', 'Combine only with care and professional oversight; watch for excess sedation; the same caution applies with other calming botanicals (valerian, hops, kava).', 'Brinker, Herbal Contraindications and Drug Interactions (2010), sedative-herb class caution; mechanistic.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1243', 'H255', 'other', 'Contact with the fresh plant / known hypersensitivity', 'moderate', 'Glandular hairs of the plant contain phenanthrenequinones that can provoke an allergic contact dermatitis on handling.', 'Avoid handling the fresh plant if prone to dermatitis; do not use in known hypersensitivity to lady''s slipper.', 'Natural Standard/compiled modern monograph (contact dermatitis); botanical dermatology literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1244', 'H255', 'other', 'Products substituted with Veratrum (American false hellebore) or unverified Cypripedium', 'moderate', 'Scarcity of genuine root drives frequent adulteration and substitution; Veratrum viride is cardiotoxic and cholinergic and has historically been confused with and substituted for lady''s slipper.', 'Use only botanically authenticated, cultivated Cypripedium from reputable suppliers; reject any product whose identity and sourcing cannot be verified.', 'United Plant Savers Cypripedium profile; AHPA trade guidance on wildcrafted lady''s slipper; historical adulteration literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1245', 'H255', 'condition', 'Hot, feverish, acutely inflamed, or markedly dry yin-deficient states', 'low', 'Warm, dry, stimulant, diaphoretic character aggravates heat and dryness.', 'Avoid or combine with cooling, moistening herbs in the hot, inflamed, or dry-depleted constitution.', 'Traditional Western/TCM energetic principle (warm, dry, stimulant nervine).');
