INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H256', 'TCM02', 'Minor', 'Qi Deficiency: contraindicated where there is no qi or blood stagnation; a disperser used alone in frank deficiency scatters rather than builds.', '{"title": "Shen Nong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry He Huan, which records the bark as comforting the five zang, harmonizing the mind and will, and making one joyful and free of worry.", "locator": "Shen Nong Ben Cao Jing (The Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry He Huan, which records the bark as comforting the five zang, harmonizing the mind and will, and making one joyful and free of worry.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (He Huan Pi / He Huan Hua); Herbal Reality, ''Albizia (Albizia julibrissin)''; American Dragon (Dr Joel Penner), He Huan Pi monograph; WebMD, ''Albizia julibrissin''; Liu et al., ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (He Huan Pi / He Huan Hua); Herbal Reality, ''Albizia (Albizia julibrissin)''; American Dragon (Dr Joel Penner), He Huan Pi monograph; WebMD, ''Albizia julibrissin''; Liu et al., ", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1246', 'H256', 'pregnancy', 'Pregnancy', 'moderate', 'He Huan Pi invigorates the blood (huo xue); blood-moving herbs are classically contraindicated in pregnancy, and reliable human safety data are lacking.', 'Avoid therapeutic doses of the bark and flower in pregnancy unless supervised by a qualified practitioner.', 'Herbal Reality, Albizia monograph (''caution should be taken when pregnant as it invigorates blood''); American Dragon / Bensky He Huan Pi (''Use caution during pregnancy'').');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1247', 'H256', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human safety data during lactation; passage of constituents into breast milk is unstudied, and the herb has sedative and serotonergic activity.', 'Avoid concentrated medicinal doses while nursing without professional guidance.', 'Herbal Reality, Albizia monograph (consult a medical herbalist before use in pregnancy or lactation).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1248', 'H256', 'drug_interaction', 'Sedatives / CNS depressants (benzodiazepines, barbiturates, z-drugs such as zolpidem, alcohol)', 'moderate', 'Albizia can cause drowsiness and may add to the sedative effect of CNS depressants.', 'Use cautiously; avoid combining without medical advice, and take care with activities needing alertness.', 'WebMD, Albizia julibrissin (interaction with sedative/CNS-depressant medications rated moderate).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1249', 'H256', 'drug_interaction', 'Antidepressant and serotonergic drugs (SSRIs, SNRIs, MAOIs)', 'moderate', 'Albizia lignan glycosides noncompetitively inhibit the serotonin transporter and the herb acts at 5-HT1A receptors, giving a theoretical additive serotonergic effect (including serotonin syndrome).', 'Combine only under medical oversight; watch for serotonergic excess (agitation, tremor, sweating, hyperthermia).', 'Liu et al., ''Two Lignan Glycosides from Albizia julibrissin Durazz. Noncompetitively Inhibit Serotonin Transporter,'' Pharmaceuticals 2022 (PMC8954383); mechanistic.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1250', 'H256', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'The bark''s blood-invigorating action gives a theoretical additive bleeding risk.', 'Monitor if combining; watch for easy bruising or bleeding.', 'Mechanistic (huo xue / blood-invigorating action; Bensky He Huan Pi); no documented case reports.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1251', 'H256', 'condition', 'Active bleeding or bleeding disorder', 'moderate', 'Invigorating the blood is inappropriate where blood should be held rather than moved.', 'Avoid in active hemorrhage or a marked bleeding tendency.', 'Traditional TCM principle (contraindicated without qi/blood stagnation; invigorates blood); American Dragon / Bensky He Huan Pi.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1252', 'H256', 'condition', 'Children (therapeutic doses)', 'moderate', 'No established pediatric safety or dosing data; sedative and serotonergic actions warrant caution.', 'Use in children only under qualified practitioner oversight, not for self-directed treatment of mood, sleep, or behavior.', 'Absence of pediatric safety data (Herbal Reality; WebMD).');
