INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1253', 'H257', 'pregnancy', 'Pregnancy (concentrated/therapeutic doses and essential oil)', 'moderate', 'No reliable modern human safety data for concentrated or high-dose perilla preparations in pregnancy; the essential oil contains lung-toxic perilla ketone.', 'Culinary leaf and mild tea are a food-level exposure and are traditionally used for morning sickness and to calm the fetus; reserve concentrated extracts and high therapeutic doses for professional guidance and avoid internal essential oil.', 'WebMD, Perilla (pregnancy effect unknown); Drugs.com natural-products monograph; Bensky Materia Medica (traditional pregnancy use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1254', 'H257', 'breastfeeding', 'Breastfeeding (concentrated/therapeutic doses)', 'moderate', 'Unknown whether perilla constituents pass into breast milk; no reliable human data on concentrated medicinal doses during lactation.', 'Ordinary culinary and mild-tea use is low concern; avoid concentrated extracts, high doses, and the essential oil while nursing without professional guidance.', 'WebMD, Perilla (unknown if passes into breast milk); Drugs.com natural-products monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1255', 'H257', 'drug_interaction', 'Anticoagulant and antiplatelet medications (warfarin, heparin, aspirin, clopidogrel, ticagrelor)', 'moderate', 'Perilla, chiefly the alpha-linolenic-acid-rich seed oil (leaf to a lesser degree), can carry a mild antiplatelet, blood-thinning tendency, giving a theoretical additive bleeding risk.', 'Use extra care with bleeding disorders, on blood thinners, and around surgery; monitor and clear medicinal-dose use with the prescriber.', 'WebMD, Perilla (bleeding-risk caution); Mills & Bone principles for omega-3/antiplatelet additivity.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1256', 'H257', 'other', 'Perilla or mint-family (Lamiaceae) allergy', 'moderate', 'As an aromatic mint-family plant it can provoke hypersensitivity, including occupational allergic contact dermatitis and asthma in perilla farm/processing workers.', 'Avoid in anyone allergic to perilla or to mint-family plants; discontinue if allergic symptoms occur.', 'WebMD, Perilla; occupational-allergy case literature.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1257', 'H257', 'drug_interaction', 'Perilla essential oil, internal use (high perilla-ketone material)', 'moderate', 'Perilla ketone is a potent pulmonary toxin, documented to cause acute lung edema and emphysema in grazing livestock (perilla mint poisoning); concentrated essential oil concentrates it.', 'Do not take concentrated perilla essential oil internally; keep it away from infants and young children; seek prompt care for respiratory distress after concentrated-oil exposure.', 'WebMD, Perilla (lung-damage warning); veterinary toxicology literature on perilla ketone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1258', 'H257', 'condition', 'Wind-heat / heat-type fevers, internal heat, and yin-deficient dryness', 'low', 'A warm, acrid, sweat-promoting diaphoretic drives heat higher and scatters fluid, the wrong direction for heat and dryness patterns.', 'Avoid in wind-heat colds, high or heat-type fevers, and marked yin/fluid deficiency; if used, combine with cooling, moistening, or yin-building herbs.', 'Traditional TCM/energetic principle (Zi Su Ye is a warm exterior-releaser); Bensky Materia Medica.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H257', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, true);
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H257', 'EP02', 'avoid', 0, 3, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, true);
