INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H257', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), Su / Zi Su (Perilla), which describes the warm, acrid leaf that releases the exterior, disperses cold, moves qi and harmonizes the middle, calms the fetus, and resolves fish ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Zi Su Ye / Folium Perillae); WebMD, Perilla; Drugs.com natural-products monograph, Perilla; the Japanese Kampo tradition (perilla / soyo in Hange-koboku-to and Koso-", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H258', 'Pinkroot (also Indian Pink, Maryland Pinkroot, Wormgrass, Carolina Pink)', 'Spigelia marilandica', 'Loganiaceae (the Logania or strychnine family). The genus Spigelia, occasionally segregated into its own family Spigeliaceae, belongs among the alkaloid-rich Loganiaceae alongside its poisonous relatives Strychnos (strychnine) and Gelsemium.', 'Dried root and rhizome, gathered in autumn. The fresh root is more acrid and is considered unsafe; drying reduces but does not remove the toxic alkaloid, so even the dried root must be dosed precisely.', 'Bitter (a pronounced, lasting bitterness), Pungent (an acrid, nauseous quality from the narcotic alkaloid), Sweet (a faint initial sweetness of the root).', 'Cool', 'Dry', 'Dampness and damp-stagnation of the digestive tract: the boggy, mucus-laden, sluggish bowel that harbors intestinal worms (chiefly the large roundworm, less reliably tapeworm), where fermenting damp accumulation gives parasites their foothold. Stagnation and morbid accumulation in the intestines, which a bitter, acrid, downward-draining, purgative-assisted herb moves, expels, and clears. The picture is one of damp, stagnant excess in the digestive terrain rather than dryness or want of tone, and it is the worm-expelling, eliminating action that resolves it.', 'Dryness and fluid depletion, which a bitter, acrid, drying, cathartic-paired herb deepens. Deficiency, atrophy, and exhaustion: the frail, wasted, or convalescent patient, in whom a toxic anthelmintic and its obligatory purge further drain an already low vitality, so the classical rule is to worm only those strong enough to bear it. Atony and laxity of the bowel with a tendency to loose stool or diarrhea, worsened by the accompanying cathartic. Acute inflammation or irritation of the gut, which the acrid root aggravates.', 'Digestive above all, and specifically the intestines: pinkroot is a near-specific anthelmintic (vermifuge) of the small bowel, its whole reputation resting on the expulsion of roundworm (Ascaris lumbricoides) and, secondarily, tapeworm. Through its toxic alkaloid it also reaches the Nervous and Cardiovascular systems, not therapeutically but as the seat of its poisoning (cerebral disturbance, disturbed vision, dilated pupils, cardiac excitation, convulsions), which is why the worming dose and the toxic dose lie so close together.', 'Intestinal worms above all, especially the large roundworm (Ascaris lumbricoides) and, less reliably, tapeworm, and most famously in children. It was given for the restlessness, disturbed sleep, irritability, and so-called worm fever attributed to infestation. It is a specific remedy for a specific problem, not a general digestive or constitutional tonic.', 'Not a constitutional herb in the tonic sense; it is a specific vermifuge chosen for the condition rather than the temperament. Where any lean applies, it suits the damp, boggy, phlegmatic digestive terrain in which parasites lodge, in a patient robust enough to bear a toxic, purging remedy. It is contraindicated in the thin, cold, dry, depleted (Vata-like) constitution and in the frail, wasted, or convalescent, whom its toxicity and obligatory catharsis would only deplete.', 'Kapha', 'Vata', 'Chinese medicine treats intestinal parasites with a distinct category of expel-parasites (qu chong) herbs, and pinkroot, though a Western botanical, fills that role: it addresses worm accumulation in the intestines against a background of Dampness and Damp-Heat that harbors them. Its bitter, draining, downward-moving, toxin-bearing nature clears damp accumulation and expels parasites. In classical terms it is used only when the upright qi is strong enough to withstand a toxic, draining herb.', 'Spleen Qi deficiency and general Qi deficiency: a toxic, draining, parasite-expelling herb paired with a purgative injures the Spleen and the upright qi, so it is withheld from the weak, the depleted, and the frail. Yin deficiency with dryness, which its bitter, drying, purging character deepens. Pregnancy. The rule is to attack the parasites only in a body strong enough to bear the attack.', 'Pinkroot is a narrow-margin, potentially poisonous herb whose therapeutic and toxic doses lie close together. Its alkaloid spigeline, likened to coniine and nicotine, is a nerve and heart poison: overdose or accumulation produces increased and disturbed cardiac action, vertigo and dizziness, dimness and disturbance of vision, dilated pupils, twitching of the eyelids and face, muscular spasms, general convulsions, stupor, and in severe poisoning death. Toxicity is more likely when the root is given alone without the customary cathartic, allowing the alkaloid to be absorbed rather than swept out, and when doses are repeated. The fresh root is more acrid and hazardous than the dried. For these reasons pinkroot is a practitioner''s remedy, dosed precisely, always followed by a saline or senna cathartic, never taken casually or self-dosed, and kept out of the reach of children except in carefully calculated therapeutic use.', 'Pregnancy (a toxic alkaloid plus the obligatory strong laxative). Cardiac disease and any tendency to arrhythmia (the alkaloid excites and disturbs the heart). Seizure disorders (it is convulsant in overdose). Concurrent cardiac-glycoside therapy without supervision (see interactions). Inflammatory or ulcerative bowel disease, irritated by the acrid root. Marked debility, wasting, and deficiency, in which neither the toxin nor the purge can be safely borne. Any use of the fresh root. Infancy and frailty except in carefully calculated, supervised dosing.', 'UNSAFE in pregnancy; avoid entirely. Modern consumer-safety references (Natural Medicines Comprehensive Database, as reported by WebMD and RxList) state plainly that it is unsafe to use pink root, even the dried preparation, during pregnancy: to be effective it must be given with a strong laxative, and strong stimulant or saline laxatives can be harmful in pregnancy, while the root''s own alkaloid is a toxic, convulsant, cardioactive agent.', 'Avoid. Natural Medicines / WebMD note there is not enough information to know whether pink root is safe while breastfeeding and advise avoiding it. Given a toxic alkaloid that may pass into milk and the accompanying strong laxative, the prudent course during lactation is to avoid it.', 'Use only under qualified supervision, never as a home remedy. Pinkroot was historically the classic children''s vermifuge and children were among its principal patients, but it is a narrow-margin poison: overdose or repeated dosing has produced the toxic syndrome (disturbed vision, dilated pupils, facial twitching, cardiac excitation, convulsions) in children, and modern references give no established pediatric dose (Natural Medicines / WebMD: insufficient information to set a dose). Any pediatric use must be practitioner-directed, weight-calculated, single-course, and always followed by a cathartic to prevent absorption; safer modern anthelmintics are the first choice.', 'Documented human pharmacokinetic interaction data are lacking (modern monographs list no formal interactions), so the cautions are mechanistic. Cardiac glycosides (digoxin): the strong stimulant or saline laxative that pinkroot is always paired with can deplete potassium, and hypokalemia potentiates cardiac-glycoside toxicity, a concern compounded by the alkaloid''s own cardiac excitation; combine only under supervision. Antiarrhythmics and other cardioactive or QT-affecting drugs: additive disturbance of cardiac rhythm is plausible given spigeline''s cardiac action. Drugs that lower the seizure threshold: the alkaloid is convulsant in excess. Other stimulant laxatives and potassium-depleting diuretics: additive potassium loss and bowel irritation. Nicotinic agents: spigeline resembles nicotine and coniine and may act on nicotinic pathways, a theoretical additive concern. These are precautionary rather than documented case reports; a practitioner should review all cardiac and neurologic medication before use. Sources: Natural Medicines Comprehensive Database (WebMD/RxList); mechanistic pharmacology.', 'Decoction or infusion of the dried root, the traditional forms, taken fasting for several mornings and each course followed by a saline aperient or senna cathartic to sweep out worms and root together (the classic Eclectic pinkroot-and-senna). Fluid extract and tincture of the dried root. Powdered dried root. A syrup was sometimes made for children. The compound Spigelia and Senna fluid extract was the standard officinal form. The fresh root is not used.', 'A practitioner-administered, weight-calculated remedy, not for casual self-dosing. Historical Eclectic dosing (King''s American Dispensatory, 1898): dried root as an infusion, roughly 1 to 2 drachms (about 4 to 8 g) to the cup, morning and evening for several days, each course followed by a cathartic; fluid extract of Spigelia, 1 to 2 fluid drachms (about 4 to 8 mL); the compound Spigelia and Senna fluid extract in similar amounts, with children dosed proportionally lower. Modern references set no standardized dose (Natural Medicines / WebMD). Never exceed the calculated dose or repeat without the cathartic, and stop at once for any sign of visual disturbance, facial twitching, or palpitations.', 'King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.', 'Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pinkroot; Millspaugh, American Medicinal Plants, Spigelia.', 'Pinkroot is a shade-loving perennial of rich, moist woods of the southeastern and midwestern United States, its scarlet-and-yellow tubular flowers making it a prized native garden plant (the source of its modern nursery revival). Its medicinal use was learned from Southeastern Native peoples (Cherokee and Creek/Muscogee) and became one of the most trusted anthelmintics of nineteenth-century American Eclectic and regular practice, official in the U.S. Pharmacopoeia into the early twentieth century. The active and toxic principle is the volatile alkaloid spigeline (chemically likened to coniine and nicotine), concentrated in the root, with a volatile oil, resin, tannin, and a bitter body; the plant''s place in the Loganiaceae sets it among alkaloid-rich, poisonous relatives such as Strychnos and Gelsemium. Its safe use always depended on precise dosing and an accompanying cathartic, and it fell from general use as its toxicity, and the arrival of safer synthetic anthelmintics, made the risk no longer worthwhile. It is retained here as a documented historical specific, not a recommendation for self-treatment.', 'Not in the canonical biblical texts nor in the classical Greco-Roman herbals; Spigelia marilandica is a North American native unknown to the ancient Mediterranean world. Its medicinal tradition is Native American, notably Cherokee and Creek/Muscogee use as a wormer, from whom it passed into colonial and Eclectic American medicine. Cited honestly as a herb of Southeastern Native American and American Eclectic tradition rather than of Scripture.', 'Pinkroot appears on United Plant Savers'' Species-At-Risk list (at-risk score around 35) and is listed as Endangered in Indiana. It is a slow, shade-demanding woodland perennial, easily crowded out by invasive species and historically over-collected for the drug trade. Encouragingly, wild-harvest pressure is easing as the plant''s popularity as a nursery-grown, hummingbird-attracting garden perennial rises. Source only nursery-propagated or responsibly cultivated root, never wild-dug from native woodland populations.', 'Cool and drying: a bitter, acrid, narrow-margin vermifuge that drains a damp, stagnant, worm-burdened gut and expels intestinal parasites, always swept out afterward by a cathartic.', 'Refer, and do not self-treat, any case that is not a straightforward, practitioner-confirmed worm infestation; seek medical evaluation for suspected parasitic disease and use safer modern anthelmintics first. Treat as an emergency any sign of pinkroot poisoning: disturbed or dimmed vision, dilated pupils, twitching of the eyelids or face, palpitations or irregular heartbeat, dizziness, muscle spasms, drowsiness or stupor, or convulsions. Refer red flags of serious bowel disease: blood in the stool, persistent abdominal pain, unexplained weight loss, or fever. Never use in pregnancy, in cardiac or seizure disease, or in the very frail.', 'Pinkroot: PINK-root. Spigelia marilandica: spy-JEE-lee-uh mair-ih-LAN-dih-kuh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "locator": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLU