INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H258', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H258', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H258', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS07', 'Primary', 'Dampness: drains the boggy, mucus-laden, sluggish bowel in which worms breed.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS08', 'Primary', 'Stagnation: moves and expels morbid accumulation and parasites from the intestines.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS16', 'Secondary', 'Excess conditions: a draining, eliminating remedy for a damp, stagnant excess of the gut, not a deficiency state.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS03', 'Primary', 'Dryness: a bitter, acrid, drying, cathartic-paired herb deepens fluid depletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS01', 'Primary', 'Deficiency: the toxin and its obligatory purge further drain an already low vitality.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS04', 'Secondary', 'Exhaustion: withheld from the frail and convalescent who cannot bear a toxic, purging remedy.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS06', 'Secondary', 'Acute inflammation: the acrid root irritates an inflamed or ulcerated gut.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H258', 'TS09', 'Minor', 'Laxity: loose, atonic bowel with diarrhea is worsened by the accompanying cathartic.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H258', 'SY08', 'Primary', 'Digestive: a near-specific anthelmintic of the small intestine (roundworm, secondarily tapeworm).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H258', 'SY01', 'Secondary', 'Nervous: the seat of its toxicity (cerebral disturbance, disturbed vision, dilated pupils, convulsions).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H258', 'SY06', 'Secondary', 'Cardiovascular: the seat of its toxicity (increased, disturbed cardiac action from spigeline).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H258', 'A32', 'Primary', 'Anthelmintic/vermifuge: the defining action, expelling roundworm and, less reliably, tapeworm.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H258', 'A16', 'Minor', 'Bitter tonic: a pronounced bitter principle stimulates the digestion, though this is not its therapeutic aim.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H258', 'A38', 'Minor', 'Laxative: only mildly purgative in large doses; classically paired with a stronger cathartic (senna) to carry out worms and root.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H258', 'CP62', 'Primary', 'Dysbiosis/parasites: intestinal worms, chiefly roundworm and, less reliably, tapeworm (the herb''s single defining use).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H258', 'CP12', 'Minor', 'Digestive upset: the restlessness, irritability, and worm fever attributed to infestation.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H258', 'P04', 'Primary', 'Decoction of the dried root, taken fasting, each course followed by a cathartic.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H258', 'P05', 'Primary', 'Infusion (tea) of the dried root, the common domestic form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H258', 'P01', 'Secondary', 'Tincture / fluid extract of the dried root; the compound Spigelia and Senna was officinal.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H258', 'P03', 'Secondary', 'Powdered dried root.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H258', 'P09', 'Minor', 'Syrup, sometimes made to dose children.');
