INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H258', 'C07', 'Aggravates', 'Secondary', 'Deficient/Pale: the frail cannot safely bear the toxin or the obligatory catharsis.', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "locator": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
