INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1259', 'H258', 'pregnancy', 'Pregnancy', 'absolute', 'A toxic, convulsant, cardioactive alkaloid (spigeline) combined with the obligatory strong laxative, which is itself harmful in pregnancy.', 'Do not use in any form during pregnancy.', 'Natural Medicines Comprehensive Database, as reported by WebMD and RxList (Pink Root: UNSAFE in pregnancy).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1260', 'H258', 'breastfeeding', 'Breastfeeding', 'moderate', 'A toxic alkaloid that may pass into milk, plus the accompanying strong laxative; safety not established.', 'Avoid while breastfeeding; there is not enough information to consider it safe.', 'Natural Medicines Comprehensive Database, as reported by WebMD and RxList (Pink Root: insufficient data, avoid).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1261', 'H258', 'population', 'Infants and children (unsupervised use)', 'moderate', 'Narrow margin between the worming dose and the toxic dose; overdose has caused the poisoning syndrome (disturbed vision, dilated pupils, facial twitching, cardiac excitation, convulsions) in children.', 'Pediatric use only if practitioner-directed, weight-calculated, single-course, and followed by a cathartic; prefer safer modern anthelmintics.', 'Natural Medicines / WebMD (no established pediatric dose); King''s American Dispensatory (Felter & Lloyd, 1898), toxicity of Spigelia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1262', 'H258', 'drug_interaction', 'Cardiac glycosides (digoxin, digitoxin)', 'moderate', 'The strong stimulant or saline laxative given with pinkroot can deplete potassium, and hypokalemia potentiates cardiac-glycoside toxicity; spigeline''s own cardiac excitation compounds the risk.', 'Avoid the combination or use only under close medical supervision with electrolyte monitoring.', 'Natural Medicines Comprehensive Database (laxative and potassium-affecting interactions); mechanistic pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1263', 'H258', 'condition', 'Cardiac disease and arrhythmia', 'moderate', 'Spigeline increases and disturbs cardiac action, which can precipitate or worsen arrhythmia.', 'Avoid in heart disease or any arrhythmic tendency.', 'King''s American Dispensatory (Felter & Lloyd, 1898), toxicity of Spigelia; modern pharmacology of the alkaloid.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1264', 'H258', 'condition', 'Seizure disorders', 'moderate', 'The alkaloid is convulsant in overdose and may lower the seizure threshold.', 'Avoid in epilepsy or any seizure-prone condition.', 'King''s American Dispensatory (Felter & Lloyd, 1898), toxicity of Spigelia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1265', 'H258', 'other', 'Fresh root, overdose, or use without an accompanying cathartic', 'absolute', 'The fresh root is more acrid and hazardous; without the cathartic the alkaloid is absorbed rather than expelled, producing cardiac excitation, visual disturbance, facial twitching, convulsions, stupor, and, in severe poisoning, death.', 'Use only the dried root, precisely dosed, always followed by a saline or senna cathartic; never use the fresh root and never exceed the calculated dose.', 'Natural Medicines / WebMD (fresh root unsafe; dried root only short-term with a strong laxative); King''s American Dispensatory (Felter & Lloyd, 1898).');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H258', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Spigelia.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "locator": "Natural Medicines Comprehensive Database, as reported by WebMD and RxList, Pink Root; United Plant Savers, Species-At-Risk, Pinkroot (Spigelia marilandica); Harding (ed.), The Eclectic Materia Medica, Spigelia; Grieve, A Modern Herbal, Pink", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, true);
