INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H259', 'C06', 'Indicated', 'Secondary', 'Robust / Hot (Pitta-like): cools the hot, plethoric type with acutely inflamed, swollen glands.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "locator": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H259', 'C02', 'Indicated', 'Secondary', 'Choleric: its cool, dispersing quality checks the heat and glandular inflammation of the choleric.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "locator": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H259', 'C05', 'Aggravates', 'Primary', 'Thin / Cold / Depleted (Vata-like): cool, dry, reducing, and toxic; aggravates dryness, cold, and depletion.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "locator": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
