INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H259', 'TCM07', 'Minor', 'Yin deficiency: its drying action can injure fluids in yin-deficient dryness.', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "locator": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1266', 'H259', 'pregnancy', 'Pregnancy', 'absolute', 'Systemic toxicity from irritant triterpenoid saponins and mitogenic lectins, plus a traditional reputation as a uterine stimulant and emmenagogue affecting the menstrual cycle. No safe therapeutic data exist in pregnancy.', 'Do not use in any form during pregnancy.', 'AHPA Botanical Safety Handbook (Phytolacca americana); Brinker, Herbal Contraindications and Drug Interactions; Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1267', 'H259', 'breastfeeding', 'Breastfeeding', 'absolute', 'Toxic saponins and lectins may be transferred to the nursing infant, and there are no data establishing safety in lactation; even topical breast use risks infant exposure.', 'Avoid internal use while breastfeeding, and avoid topical application to the nipple or broken breast skin.', 'AHPA Botanical Safety Handbook; Mills and Bone, The Essential Guide to Herbal Safety; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1268', 'H259', 'condition', 'Children', 'absolute', 'High toxicity and a low toxic margin; poke berries and root are a leading cause of pediatric plant poisoning in North America, with severe gastroenteritis and occasional fatalities.', 'Do not give to children; treat any ingestion of berries or root as a poisoning and seek emergency care.', 'AHPA Botanical Safety Handbook; clinical toxicology and poison-control literature; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1269', 'H259', 'drug_interaction', 'Immunosuppressant and immunomodulatory drugs (ciclosporin, tacrolimus, corticosteroids, azathioprine, methotrexate, biologics)', 'moderate', 'Pokeweed mitogen is a potent lymphocyte stimulant, so poke may oppose immunosuppressive therapy or unpredictably alter immune activity.', 'Avoid in patients on immunosuppressant or immunomodulatory drugs; this is a theoretical pharmacodynamic caution, so err on the side of avoidance.', 'Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1270', 'H259', 'condition', 'Lymphocytic leukaemia and autoimmune / immunosuppressed states', 'moderate', 'Its potent lymphocyte-mitogenic lectin makes stimulation of a proliferative or autoimmune process a theoretical concern.', 'Avoid in lymphocytic leukaemia and use only with specialist oversight, if at all, in autoimmune or immunosuppressed patients.', 'Mills and Bone, The Essential Guide to Herbal Safety; Bartram, Encyclopedia of Herbal Medicine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1271', 'H259', 'condition', 'Gastrointestinal inflammation (gastritis, peptic ulcer, inflammatory bowel disease)', 'moderate', 'Poke is a powerful gastrointestinal irritant (saponins / phytolaccatoxin) that can cause burning, cramping, vomiting, and haemorrhagic gastritis.', 'Avoid internal use where the GI mucosa is inflamed or ulcerated.', 'King''s American Dispensatory (1898); clinical toxicology literature; Mills and Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1272', 'H259', 'condition', 'General toxicity / self-dosing / overdose', 'absolute', 'Narrow toxic margin: excess causes burning throat, profuse vomiting, bloody diarrhoea, hypotension, respiratory depression, convulsions, and rarely death.', 'Use only in low, practitioner-administered or practitioner-supervised drop doses for short courses; never self-dose casually and never use raw.', 'AHPA Botanical Safety Handbook; Brinker; clinical toxicology and poison-control reports.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1273', 'H259', 'condition', 'Kidney disease', 'moderate', 'Listed as a contraindication in the modern Western clinical tradition; potential renal stress from a toxic, irritant botanical.', 'Avoid in significant renal impairment.', 'Bartram, Encyclopedia of Herbal Medicine; Mills and Bone, The Essential Guide to Herbal Safety.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H259', 'EP01', 'avoid', 1, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "locator": "King''s American Dispensatory (Felter and Lloyd, 1898) - Phytolacca (Phytolaccae Radix, poke root, and Phytolaccae Bacca, poke berry). Described as alterative, deobstruent to glandular tissue, and emetic/cathartic in larger dose, indicated f", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "locator": "Mills and Bone, Principles and Practice of Phytotherapy and The Essential Guide to Herbal Safety (2005); Bartram, Encyclopedia of Herbal Medicine (poke root actions, dosing, and Schedule 20 restriction); Matthew Wood, The Earthwise Herbal: ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
