INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1279', 'H261', 'condition', 'Thyroid disease / concurrent thyroid medication', 'moderate', 'Kanchnara is thyroid-modulating (used for goitre; animal studies show it alters thyroid hormone and TSH), so it may shift thyroid status and thyroid-function tests.', 'Use only under professional supervision with periodic thyroid-function monitoring; do not self-treat thyroid disease, and evaluate any goitre or thyroid swelling medically first.', 'Peer-reviewed thyroid pharmacology (Singha, Sarma & Lahakar, J Drug Delivery & Therapeutics 2019: Bauhinia variegata + Commiphora mukul lowering raised TSH in methimazole-induced hypothyroid rats; congener B. purpurea antithyroid data); general clinical practice.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1280', 'H261', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin and others)', 'moderate', 'Documented hypoglycaemic activity of the bark/flower may be additive with glucose-lowering drugs, risking hypoglycaemia.', 'Monitor blood glucose; adjust antidiabetic therapy only with the prescriber; introduce cautiously.', 'Reviews of Bauhinia variegata antidiabetic activity; Mills and Bone, Principles and Practice of Phytotherapy; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1281', 'H261', 'drug_interaction', 'Thyroid medications (levothyroxine, antithyroid drugs)', 'moderate', 'Its thyroid-modulating action may add to or interfere with thyroid replacement or antithyroid therapy and shift thyroid-function tests.', 'Combine only under supervision with thyroid-function monitoring; separate oral dosing from levothyroxine and watch for dose changes.', 'Peer-reviewed thyroid pharmacology (as above); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1282', 'H261', 'drug_interaction', 'Iron and mineral supplements; alkaloidal / protein-based drugs', 'low', 'High tannin content can bind and reduce the absorption of iron and other minerals and of some drugs taken at the same time.', 'Separate Kanchnara from iron, mineral supplements, and susceptible medications by at least two hours; use cautiously in iron-deficiency anaemia.', 'Brinker, Herbal Contraindications and Drug Interactions (tannin interactions); Mills and Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1283', 'H261', 'pregnancy', 'Pregnancy', 'moderate', 'Insufficient modern human safety data and lacking reproductive-toxicity studies; thyroid-modulating and cold, astringent actions add specific concern during pregnancy.', 'Avoid medicinal bark preparations and Kanchnara Guggulu in pregnancy unless supervised by a qualified practitioner; keep even culinary bud use moderate.', 'Precautionary; AHPA Botanical Safety Handbook / Mills and Bone / Brinker safety framework; peer-reviewed thyroid pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1284', 'H261', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable data on transfer into milk or effects on the nursing infant; thyroid-modulating activity is a specific reason for care.', 'Avoid therapeutic bark and guggulu preparations while breastfeeding unless directed by a qualified practitioner.', 'Precautionary; AHPA / Mills and Bone / Brinker safety framework.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1285', 'H261', 'condition', 'Cold, dry, depleted (Vata) constitutions and states of debility, dryness, or constipation', 'moderate', 'Its cold, drying, astringent, reducing action aggravates dryness, cold, constipation, and depletion in an already empty or dry terrain (aggravates Vata).', 'Avoid or minimise in frank debility, dryness, and constipation; if used, pair with warming, moistening, carminative correctives and keep doses low.', 'Ayurvedic Pharmacopoeia of India (karma Kaphahara / Pittahara, Vata-aggravating cold-dry qualities); traditional energetics.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1286', 'H261', 'condition', 'Undiagnosed glandular / neck mass or lymphadenopathy', 'moderate', 'A hard, fixed, or rapidly growing neck mass or persistent lymphadenopathy may signal serious disease (lymphoma, tuberculosis, thyroid cancer) that self-treatment can delay.', 'Do not self-treat an undiagnosed, hard, fixed, or rapidly enlarging mass or lymphadenopathy with red-flag features; refer for medical evaluation.', 'General clinical safety (refer threshold); standard herbal practice.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H261', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH) - Kanchnara (Bauhinia variegata Linn.), stem bark. Rasa: Kasaya (astringent); Guna: Laghu, Ruksa (light, dry); Virya: Sita (cold); Vipaka: Katu (pungent); Karma: ", "locator": "The Ayurvedic Pharmacopoeia of India (Government of India, Ministry of AYUSH) - Kanchnara (Bauhinia variegata Linn.), stem bark. Rasa: Kasaya (astringent); Guna: Laghu, Ruksa (light, dry); Virya: Sita (cold); Vipaka: Katu (pungent); Karma: ", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "Classical Ayurvedic tradition: Sushruta Samhita (galaganda / goitre and granthi / glandular swellings) and the Kanchnara Guggulu formula of the Sharangadhara Samhita (the standard compound for gandamala, apaci, and galaganda). Modern review", "locator": "Classical Ayurvedic tradition: Sushruta Samhita (galaganda / goitre and granthi / glandular swellings) and the Kanchnara Guggulu formula of the Sharangadhara Samhita (the standard compound for gandamala, apaci, and galaganda). Modern review", "source_id": "S28", "author": "Sushruta Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, true);
