INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'C06', 'Aggravates', 'Secondary', 'Robust / Hot (Pitta-like): a warming stimulant aggravates the hot, raw, inflamed dry cough.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'D03', 'Primary', 'Kapha: warm, dry, acrid, decongesting; disperses cold, boggy kapha phlegm from the chest.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_doshas_aggravates (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'D01', 'Primary', 'Vata: warm but drying and acrid; aggravates Vata dryness and the dry, unproductive cough.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
