INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'TCM13', 'Secondary', 'Wind-Cold: warm, acrid dispersal of a cold, boggy chest with phlegm, with relaxation of the tight airway.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'TCM07', 'Primary', 'Yin deficiency: a warm, drying, acrid herb injures fluids and worsens a Lung-yin-deficient dry cough.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H262', 'TCM11', 'Secondary', 'Heat / Fire: wrong for a hot, raw, inflamed Lung-heat dry cough that needs cooling and moistening.', '{"title": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "locator": "Grieve, A Modern Herbal (1931) - Ivy, Common (Hedera helix), which records the leaves'' traditional internal use in whooping cough and bronchitic, catarrhal conditions and their external use, and notes the acrid, saponin-bearing nature of th", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "locator": "EMA/HMPC European Union herbal monograph on Hedera helix L., folium, and the accompanying Assessment report (well-established-use expectorant for productive cough; posology, pregnancy, lactation, pediatric, and interaction statements). ESCO", "source_id": "S12", "author": "ESCOP Monographs", "year": "2003", "url": "https://escop.com/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1287', 'H262', 'other', 'Children under 2 years', 'absolute', 'Cough medicines in children under 2 can worsen respiratory symptoms, and the irritant saponins can provoke vomiting; ivy-leaf preparations are not established as safe in this age group.', 'Do not give ivy-leaf preparations to children under 2 years. Use only in adults, adolescents, and children from age 2, at age-appropriate label doses.', 'EMA/HMPC European Union herbal monograph on Hedera helix L., folium (use from age 2; not for children under 2).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1288', 'H262', 'pregnancy', 'Pregnancy', 'moderate', 'Safety in pregnancy is not established and reproductive-toxicity data are insufficient; a 2021 retrospective cohort found no clear increased risk but does not overturn the precautionary position.', 'Not recommended in pregnancy; avoid medicinal ivy-leaf preparations unless a qualified practitioner judges benefit to outweigh the uncertainty.', 'EMA/HMPC European Union herbal monograph on Hedera helix L., folium; retrospective cohort study (PubMed 34482524, 2021).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1289', 'H262', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety during lactation is not established; no data on transfer of ivy-leaf saponins into milk or effects on the nursing infant.', 'Not recommended while breastfeeding; avoid medicinal preparations unless directed by a qualified practitioner.', 'EMA/HMPC European Union herbal monograph on Hedera helix L., folium.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1290', 'H262', 'other', 'Ivy or Araliaceae allergy; allergic contact dermatitis to the plant', 'moderate', 'The polyacetylenes falcarinol and didehydrofalcarinol are well-documented contact allergens; oral use can rarely provoke hives, rash, and breathlessness in sensitized people.', 'Avoid in known ivy or Araliaceae allergy. Stop at any sign of allergic reaction. Handlers of the fresh plant should wear gloves to prevent contact dermatitis.', 'Hausen et al., Contact Dermatitis (1987), falcarinol and didehydrofalcarinol; EMA/HMPC monograph (allergic reactions listed as side effects).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1291', 'H262', 'other', 'Ingestion of ivy berries or the raw whole plant', 'absolute', 'The black berries and raw plant contain high concentrations of irritant saponins that cause vomiting, diarrhoea, and, in quantity, more serious poisoning; they are not a medicine.', 'Do not ingest the berries or raw plant. Use only standardized, correctly dosed leaf preparations, and keep berries away from children. Treat suspected ingestion as a poisoning and seek medical care.', 'AHPA Botanical Safety Handbook (2nd ed, 2013); EMA/HMPC assessment report; poison-control toxicology literature on Hedera helix.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1292', 'H262', 'drug_interaction', 'Cough-suppressant (antitussive) drugs (e.g., codeine, dextromethorphan)', 'low', 'Ivy leaf is a secretolytic expectorant that loosens and mobilizes phlegm; suppressing the cough reflex at the same time is counterproductive and can promote mucus retention.', 'Do not combine an expectorant with a cough suppressant; choose one strategy. This is a pharmacodynamic rationale, not a documented adverse interaction.', 'EMA/HMPC assessment report on Hedera helix L., folium; Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1293', 'H262', 'condition', 'Gastritis, peptic ulcer, or a sensitive, easily irritated stomach', 'low', 'The saponins are gastrointestinal irritants and can cause nausea, burning, and vomiting, more likely in an already sensitive or inflamed stomach.', 'Use cautiously and with food in those prone to gastric irritation; reduce dose or stop if nausea or gastric upset occurs.', 'EMA/HMPC monograph (gastrointestinal side effects); Mills and Bone, Principles and Practice of Phytotherapy.');
