INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H263', 'TCM01', 'Minor', 'Cold, draining action aggravates Kidney Yang deficiency.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty) and Ge Hong, Zhou Hou Bei Ji Fang (Handbook of Prescriptions for Emergencies, c. 340 CE) - Qing Hao.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty) and Ge Hong, Zhou Hou Bei Ji Fang (Handbook of Prescriptions for Emergencies, c. 340 CE) - Qing Hao.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qing Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; WHO Guidelines for Malaria; Tu Youyou, Artemisinin and ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qing Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; WHO Guidelines for Malaria; Tu Youyou, Artemisinin and ", "source_id": "S13", "author": "WHO Monographs on Selected Medicinal Plants", "year": "1999-2009", "url": "https://www.who.int/publications/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1294', 'H263', 'pregnancy', 'Pregnancy (especially first trimester)', 'absolute', 'Artemisinin and its derivatives are embryotoxic in animal studies, causing embryolethality and cardiovascular and skeletal malformations within a narrow early-gestation window by impairing early erythropoiesis and vasculogenesis; the traditional materia medica also cautions the herb in pregnancy.', 'Do not self-treat with the herb in pregnancy; malaria in pregnancy must be managed by a clinician.', 'WHO Guidelines for Malaria (malaria in pregnancy); Safety of Artemisinin Derivatives in the First Trimester of Pregnancy (Molecules 2020, PMC7435965); AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1295', 'H263', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data for the whole herb; excretion of artemisinin into milk is poorly characterized.', 'Avoid without medical supervision while breastfeeding.', 'AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1296', 'H263', 'drug_interaction', 'CYP3A4 and CYP2B6 substrates (e.g., some antiretrovirals, immunosuppressants, statins, hormonal contraceptives)', 'moderate', 'Artemisinin induces CYP2B6 and CYP3A4 via PXR and CAR activation, potentially lowering plasma levels and efficacy of drugs cleared by these enzymes (and of artemisinin itself).', 'Coordinate with a pharmacist or physician before combining with narrow-therapeutic-index CYP3A4 or CYP2B6 medicines.', 'Simonsson et al., Artemisinin autoinduction is caused by involvement of CYP2B6 (Clin Pharmacol Ther, 2003); herb-drug interaction review (Molecules 2017, 22:2049).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1297', 'H263', 'drug_interaction', 'Antimalarial monotherapy / artemisinin resistance', 'moderate', 'Using Artemisia annua tea or the whole herb as sole malaria treatment delivers sub-therapeutic, variable artemisinin and promotes resistance.', 'Never use the herb as stand-alone malaria treatment; confirmed malaria requires properly dosed artemisinin-based combination therapy under medical care.', 'WHO Guidelines for Malaria; WHO position on non-pharmaceutical Artemisia annua for malaria.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1298', 'H263', 'condition', 'Spleen and Stomach Qi deficiency with cold and chronic loose stools', 'moderate', 'The bitter, cold, draining nature chills and weakens an already cold, feeble digestion.', 'Avoid in cold, weak digestion, or combine with warming, digestion-protecting herbs and use only for genuine heat.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qing Hao.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1299', 'H263', 'other', 'Hypersensitivity to Asteraceae (ragweed, chamomile, marigold, feverfew)', 'moderate', 'Cross-reactivity within the Asteraceae family can provoke allergic reactions.', 'Avoid with known Asteraceae allergy; discontinue if rash, itching, or swelling appears.', 'AHPA Botanical Safety Handbook (2nd ed.).');
