INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H263', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty) and Ge Hong, Zhou Hou Bei Ji Fang (Handbook of Prescriptions for Emergencies, c. 340 CE) - Qing Hao.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty) and Ge Hong, Zhou Hou Bei Ji Fang (Handbook of Prescriptions for Emergencies, c. 340 CE) - Qing Hao.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qing Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; WHO Guidelines for Malaria; Tu Youyou, Artemisinin and ", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Qing Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; WHO Guidelines for Malaria; Tu Youyou, Artemisinin and ", "source_id": "S13", "author": "WHO Monographs on Selected Medicinal Plants", "year": "1999-2009", "url": "https://www.who.int/publications/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H264', 'White Mulberry Leaf (Sang Ye)', 'Morus alba', 'Moraceae (the mulberry and fig family)', 'Leaf (Sang Ye; the dried leaf, traditionally gathered after the first autumn frost)', 'Sweet, Bitter', 'Cool', 'Neutral', 'Excess Heat (the wind-heat and internal heat it clears: feverishness, a hot flushed head, hot sore throat, and the heat behind red, hot eyes and a hot dry cough); Wind (surface wind-heat: the early, feverish head-cold or flu with headache, sore throat, and cough that a mild acrid-cool disperser releases); Acute Inflammation (red, sore, gritty, inflamed eyes and an inflamed throat); Dryness (the hot, dry, tickly, unproductive cough of Lung heat and autumn dryness, eased by clearing the heat that parches the tissue). In modern use it also answers the post-meal blood-sugar surge of dysregulated glucose metabolism.', 'Cold: the cool, dispersing leaf is the wrong direction for cold patterns, a cold, wet, copious clear-phlegm cough, wind-cold chills without thirst, and a cold, weak Spleen and Stomach, where it can deepen the chill. Deficiency: as a light, cooling, surface-releasing herb it does not tonify and can further thin an already Qi- or Yang-deficient, cold, depleted terrain if leaned on.', 'Respiratory and Lungs (primary: the wind-heat surface, hot dry cough, sore throat, bronchial heat); Hepatic and Liver (clears Liver heat and, through the Liver, the eyes: red, dry, sore, or blurry hot eyes); Endocrine and metabolic (modern: blunts postprandial blood glucose via alpha-glucosidase inhibition); Immune (mild support in early febrile wind-heat).', 'Hot, dry, tickly, unproductive cough (the signature indication); the early, feverish stage of a wind-heat cold or flu with headache, sore throat, and mild fever; red, hot, dry, gritty, or sore eyes from Liver or Lung heat; wind-heat headache and hot, rising Liver-yang headache. In modern practice, dysregulated post-meal blood sugar and metabolic support, where standardized leaf extract lowers the postprandial glucose spike. Secondarily, allergic wind-heat reactivity (itchy hot eyes and throat) and oxidative-stress support from its flavonoids.', 'The hot, dry, over-heated phenotype: a flushed, feverish, dry-coughing, red-eyed heat pattern. Best for the Choleric (hot, bilious) and the robust hot (Pitta-like) constitution, whose heat it clears. The cool, dispersing, non-nourishing leaf aggravates the cold, thin, depleted (Vata-like) and the cold-damp Phlegmatic constitution, chilling and further thinning what is already cold and weak.', 'Pitta, Kapha', 'Vata', 'Wind-Heat invading the exterior and the Lung: fever, sore throat, headache, and a hot, dry cough at the onset of an acute febrile illness, released by this acrid, sweet, cold, light surface-relieving leaf. Also Lung heat with a hot dry cough, and Liver heat or ascendant Liver yang rising to the eyes and head (red, sore, dry eyes; hot headache; dizziness). Sang Ye enters the Lung and Liver channels; charred (Sang Ye tan) it also cools the blood to stem minor heat-driven bleeding.', 'Wind-Cold patterns (chills, clear nasal discharge, no thirst, a cold, wet cough), where the cool, heat-clearing leaf is the wrong direction and can worsen the chill. Spleen and Stomach cold or Yang deficiency with a cold, weak, loose digestion, which the cold herb can further injure. A cold, deficient, copious clear-phlegm cough is not its pattern.', 'Generally gentle and well tolerated as a tea or in food, with a long record of ordinary consumption (mulberry leaf tea; silkworm-fodder crop). The most common adverse effect, seen mainly with concentrated blood-sugar extracts, is digestive: bloating, gas, loose stools, or mild constipation, an extension of its alpha-glucosidase-inhibiting action in the gut. Because it measurably lowers post-meal blood glucose, watch for hypoglycemia when it is combined with glucose-lowering drugs or used by people prone to low blood sugar. Its cool, dispersing nature can aggravate cold, deficient, cold-cough, or cold-digestion patterns. Do not use concentrated eye or systemic preparations to self-treat serious eye disease. Distinguish white mulberry (Morus alba) leaf from black mulberry (Morus nigra) and from the unrelated trees rendered ''mulberry'' in some English Bibles.', 'No absolute contraindications at food and tea amounts. Use concentrated, blood-sugar-standardized (DNJ-enriched) extracts cautiously and with glucose monitoring in anyone on antidiabetic medication or prone to hypoglycemia, and coordinate around surgery given the glucose-lowering effect. Avoid concentrated therapeutic extracts in pregnancy and lactation, where safety data are lacking. Use cautiously in cold, Yang-deficient, or cold-phlegm cough and cold, weak digestion. Reserve concentrated extracts in children for qualified supervision.', 'Little reliable human safety data. NCCIH states plainly that little is known about whether white mulberry leaf is safe to use during pregnancy. Mulberry leaf tea and culinary leaf have a long history of ordinary consumption, and classical TCM does not list Sang Ye among the pregnancy-contraindicated herbs, but concentrated, blood-sugar-standardized extracts have not been evaluated in pregnancy and carry a hypoglycemia risk. Prefer, at most, modest tea amounts; avoid concentrated therapeutic or DNJ-enriched extracts in pregnancy. Source: NCCIH, White Mulberry Leaf: Usefulness and Safety; AHPA Botanical Safety Handbook, 2nd ed.', 'Little reliable data. NCCIH states that little is known about whether white mulberry leaf is safe while breastfeeding; there are no lactation-specific studies. Ordinary tea amounts are unlikely to be a concern, but concentrated extracts are not established as safe. Prefer tea amounts, monitor the infant, and avoid standardized high-DNJ extracts without professional guidance. Source: NCCIH, White Mulberry Leaf: Usefulness and Safety.', 'No pediatric safety data from modern trials. Sang Ye appears in traditional Chinese pediatric wind-heat formulas as a gentle herb, and a mild leaf tea is generally well tolerated. Reserve concentrated blood-sugar (DNJ-enriched) extracts for adults or qualified pediatric supervision because of the hypoglycemia risk and the associated GI effects. Source: NCCIH, White Mulberry Leaf; traditional TCM pediatric use (Bensky, Chinese Herbal Medicine: Materia Medica).', 'Antidiabetic and glucose-lowering drugs (insulin, sulfonylureas, metformin, and especially alpha-glucosidase inhibitors such as acarbose and miglitol): mulberry leaf 1-deoxynojirimycin (DNJ) is itself an alpha-glucosidase inhibitor and measurably lowers postprandial glucose, so it can add to both the glucose-lowering and the gut (gas, bloating, loose stool) effects of these agents, with a real risk of hypoglycemia. NCCIH: there is a potential risk for low blood sugar when taken with diabetes medications. Monitor blood glucose and coordinate dosing with the prescriber. A theoretical additive effect is possible with antihypertensive agents given mild blood-pressure lowering reported in some studies. Otherwise no well-documented interactions (limited data). Sources: NCCIH, White Mulberry Leaf; Mudra M et al., Diabetes Care 2007;30(5):1272-1274; Kimura T et al., J Agric Food Chem 2007;55(14):5869-5874.', 'Hot-water infusion or tea of the dried leaf (the traditional mulberry leaf tea, kuwacha), often taken before meals for glycemic support; decoction of the dried leaf within TCM formulas for wind-heat and hot dry cough; standardized leaf extract in capsule or powder (often DNJ-enriched) for postprandial blood-sugar control; tincture of the leaf; a cooled, well-strained leaf decoction as an eye wash or compress for hot, red, tired eyes; the tender leaf eaten as a cooked green or added to food.', 'Dried-leaf decoction (TCM): 4.5-9 g daily, up to 15 g in acute wind-heat, decocted. Leaf tea: 1-2 teaspoons (about 2-4 g) of cut leaf per cup, 1-3x daily, taken before carbohydrate meals for glycemic support. Standardized or DNJ-enriched leaf extract: taken just before meals per product labeling; DNJ doses of roughly 6-12 mg before a meal have lowered postprandial glucose in trials. Tincture (1:5, 40 percent): 2-4 mL, up to 3x daily. Eye wash: a well-strained, cooled decoction used externally only.', 'Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).', 'Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulberry leaf extract on the blood glucose and breath hydrogen response to ingestion of 75 g sucrose by type 2 diabetic and control subjects. Diabetes Care 2007;30(5):1272-1274. Kimura T et al. Food-grade mulberry powder enriched with 1-deoxynojirimycin suppresses the elevation of postprandial blood glucose in humans. J Agric Food Chem 2007;55(14):5869-5874. AHPA Botanical Safety Handbook, 2nd ed.', 'Moraceae. Sang Ye is the leaf of Morus alba. Key constituents: flavonoids (rutin, quercetin, isoquercitrin, astragalin, and kaempferol glycosides); the iminosugar alkaloid 1-deoxynojirimycin (DNJ) with related polyhydroxylated alkaloids (fagomine); phenolic acids (chlorogenic acid); gamma-aminobutyric acid; phytosterols; and benzofurans such as moracin. DNJ is a potent alpha-glucosidase inhibitor and the basis of the well-documented postprandial glucose-lowering effect. In TCM the leaf is sweet-bitter and cold, entering the Lung and Liver channels: it disperses wind-heat, clears and gently relieves dryness in the Lung for a hot dry cough, calms Liver yang and clears the eyes, and (charred, Sang Ye tan) cools the blood to stop minor bleeding. Native to China; the foundational leaf of sericulture (silkworm fodder), now naturalized worldwide and invasive in parts of North America. Distinguish from black mulberry (Morus nigra) and red mulberry (Morus rubra). The fruit (Sang Shen) and root bark (Sang Bai Pi) are separate medicinals with different actions.', 'White Mulberry (Morus alba) is native to China and is not a plant of the biblical Near East; it reached the Mediterranean world later with the silk trade. The ''mulberry trees'' of the King James Version in 2 Samuel 5:23-24 and 1 Chronicles 14:14-15 render the Hebrew beka''im, now generally identified as the balsam or poplar (Populus euphratica), not a true Morus. The one plausible biblical mulberry is the ''sycamine tree'' (Greek sykaminos) of Luke 17:6, traditionally identified as the black mulberry (Morus nigra), a different species. The definitive traditional source for the leaf as medicine is the Chinese Shennong Ben Cao Jing (Han era), under Sang.', 'Morus alba is one of the most widely cultivated trees on earth (silk industry, ornamental, animal fodder) and is abundant; it is not at risk and not on the United Plant Savers list. It is, in fact, naturalized and invasive across much of North America, where it hybridizes with and threatens the native red mulberry (Morus rubra). No conservation concern for the plant itself; prefer cultivated, organically grown leaf to limit pesticide load, and favor cultivated over any wild collection near the imperiled native species.', 'Cool, light, and acrid-sweet: a gentle surface-reliever that scatters wind-heat, quiets a hot dry cough, cools red irritated eyes, and, in modern use, softens the post-meal blood-sugar spike.', 'Refer a cough that lasts beyond about three weeks, brings up blood, or comes with high fever, breathlessness, chest pain, night sweats, or unexplained weight loss (rule out pneumonia, tuberculosis, or malignancy). Refer eye symptoms with pain, light sensitivity, discharge, vision change, or trauma to an eye specialist rather than self-treating. For blood sugar: anyone with diabetes must be physician-supervised, must not stop prescribed medication in order to use the herb, and should seek care for symptoms of very high or very low glucose.', 'White Mulberry = MUL-ber-ee; Sang Ye = sahng YEH; Morus alba = MOR-us AL-buh', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H264', 'T02');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H264', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS05', 'Primary', 'Excess Heat: clears wind-heat and internal Lung and Liver heat (hot cough, hot red eyes, sore throat, feverishness).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS20', 'Secondary', 'Wind: mild acrid-cool disperser of surface wind-heat at the early, feverish stage of a cold or flu.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS06', 'Secondary', 'Acute Inflammation: red, sore, gritty, inflamed eyes and inflamed throat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS03', 'Secondary', 'Dryness: eases the hot, dry, unproductive cough of Lung heat and autumn dryness by clearing the parching heat.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS17', 'Primary', 'Cold: the cool, dispersing leaf aggravates cold patterns, wind-cold, cold wet cough, and cold, weak digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H264', 'TS01', 'Secondary', 'Deficiency: does not tonify; a cooling disperser can further thin a Qi- or Yang-deficient, depleted terrain.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H264', 'SY07', 'Primary', 'Respiratory: the wind-heat surface, hot dry cough, sore throat, and bronchial heat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H264', 'SY14', 'Primary', 'Lungs: clears and gently relieves dryness in the Lung for a hot dry cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H264', 'SY12', 'Secondary', 'Hepatic and Liver: clears Liver heat and, through the Liver, the eyes (red, dry, sore eyes; hot Liver-yang headache).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H264', 'SY02', 'Secondary', 'Endocrine and metabolic: DNJ alpha-glucosidase inhibition blunts postprandial blood glucose.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A33', 'Primary', 'Antitussive: quiets the hot, dry, tickly, unproductive cough of Lung heat and dryness.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A36', 'Primary', 'Hypoglycemic: leaf DNJ inhibits intestinal alpha-glucosidase, lowering the post-meal glucose spike (human RCTs).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A18', 'Secondary', 'Diaphoretic (mild): acrid-cool surface release of exterior wind-heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A49', 'Secondary', 'Febrifuge and antipyretic: clears heat and eases the mild fever of wind-heat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A25', 'Secondary', 'Antioxidant: rich in flavonoids (rutin, quercetin, isoquercitrin) and phenolic acids.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A09', 'Secondary', 'Anti-inflammatory: eases inflamed, red eyes and throat; documented in vitro and in vivo.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A28', 'Minor', 'Antimicrobial: moderate activity of leaf phenolics and benzofurans.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A46', 'Minor', 'Anti-allergic and antihistaminic: eases itchy, hot wind-heat reactivity of eyes and throat.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A37', 'Minor', 'Hypotensive: mild blood-pressure lowering reported in some studies.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H264', 'A50', 'Minor', 'Styptic and hemostatic: charred Sang Ye tan cools the blood to stem minor heat-driven bleeding.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP50', 'Primary', 'Cough dry or unproductive: the signature hot, dry, tickly cough of Lung heat and dryness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP27', 'Primary', 'Blood sugar dysregulation: standardized leaf extract lowers the postprandial glucose spike (DNJ).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP41', 'Secondary', 'Cold and flu onset: early, feverish wind-heat stage with headache, sore throat, cough.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP52', 'Secondary', 'Sore throat: hot, inflamed wind-heat throat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP76', 'Secondary', 'Fever management: clears the mild heat and fever of wind-heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP19', 'Minor', 'Headaches: wind-heat headache and hot, rising Liver-yang headache.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP42', 'Minor', 'Allergic reactivity: itchy, hot wind-heat eyes and throat (allergic rhinitis pattern).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H264', 'CP75', 'Minor', 'Oxidative stress: flavonoid and phenolic antioxidant support.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P05', 'Primary', 'Infusion or tea of the dried leaf (mulberry leaf tea, kuwacha), often before meals for glycemic support.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P04', 'Primary', 'Decoction of the dried leaf within TCM formulas for wind-heat and hot dry cough.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P02', 'Secondary', 'Capsule of standardized or DNJ-enriched leaf extract for postprandial blood-sugar control.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P03', 'Secondary', 'Powdered leaf or extract, taken before carbohydrate meals.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P01', 'Secondary', 'Tincture of the leaf.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P10', 'Minor', 'Compress or eye wash: a cooled, well-strained decoction used externally for hot, red, tired eyes.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H264', 'P12', 'Minor', 'Added to food; the tender leaf eaten as a cooked green.');
