INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H264', 'TCM11', 'Secondary', 'Heat and Fire: clears Lung heat (hot dry cough) and Liver heat or ascendant Liver yang (red sore eyes, hot headache).', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
