INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H264', 'TCM03', 'Secondary', 'Spleen Qi deficiency with cold: the cold herb can further injure a cold, weak, loose digestion.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 CE), Sang (the mulberry, Morus alba; the leaf, Sang Ye).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye. Grieve M, A Modern Herbal (1931), Mulberry. NCCIH, White Mulberry Leaf: Usefulness and Safety (nccih.nih.gov). Mudra M et al. Influence of mulbe", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1300', 'H264', 'pregnancy', 'Pregnancy (concentrated and DNJ-standardized extracts)', 'moderate', 'Human safety data are lacking (NCCIH: little is known about use in pregnancy); concentrated blood-sugar extracts additionally carry a hypoglycemia risk not evaluated in pregnancy. Ordinary tea and food amounts have wide traditional use.', 'Limit to, at most, modest tea amounts; avoid concentrated therapeutic or DNJ-enriched extracts during pregnancy.', 'NCCIH, White Mulberry Leaf: Usefulness and Safety; AHPA Botanical Safety Handbook, 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1301', 'H264', 'breastfeeding', 'Breastfeeding (concentrated extracts)', 'moderate', 'No lactation-specific data (NCCIH: little is known about use while breastfeeding). Ordinary tea amounts are unlikely to be a concern; concentrated extracts are unstudied.', 'Prefer tea amounts and monitor the infant; avoid standardized high-DNJ extracts without professional guidance.', 'NCCIH, White Mulberry Leaf: Usefulness and Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1302', 'H264', 'drug_interaction', 'Antidiabetic drugs, especially alpha-glucosidase inhibitors (acarbose, miglitol), plus insulin, sulfonylureas, metformin', 'moderate', 'Leaf DNJ is an alpha-glucosidase inhibitor that lowers postprandial glucose; effect is additive with glucose-lowering drugs (and with acarbose or miglitol, which share the mechanism), risking hypoglycemia and additive GI upset (gas, bloating, loose stool).', 'Monitor blood glucose, watch for hypoglycemia and GI symptoms, and coordinate dosing and any medication changes with the prescriber.', 'NCCIH, White Mulberry Leaf; Mudra M et al., Diabetes Care 2007;30(5):1272-1274; Kimura T et al., J Agric Food Chem 2007;55(14):5869-5874.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1303', 'H264', 'condition', 'Diabetes or a tendency to hypoglycemia; perioperative period', 'moderate', 'The measurable glucose-lowering effect can drive blood sugar too low in people prone to hypoglycemia and can complicate perioperative glucose control.', 'Diabetics must use it only under physician supervision, must not stop prescribed medication to use it, and should pause concentrated extracts around scheduled surgery.', 'NCCIH, White Mulberry Leaf: Usefulness and Safety.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1304', 'H264', 'other', 'Infants and children (concentrated or DNJ-enriched extracts)', 'moderate', 'Concentrated blood-sugar extracts carry a hypoglycemia and GI risk and are unstudied in children; only mild leaf tea has a traditional pediatric record.', 'Use only mild leaf tea for children if at all; reserve concentrated extracts for qualified pediatric supervision.', 'NCCIH, White Mulberry Leaf; traditional TCM pediatric use (Bensky, Chinese Herbal Medicine: Materia Medica).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1305', 'H264', 'other', 'Wind-Cold and cold, Yang-deficient patterns (cold wet cough, cold weak digestion)', 'moderate', 'As a cool, heat-clearing, surface-dispersing leaf it opposes and can worsen cold patterns and cold, weak Spleen and Stomach.', 'Avoid or combine with warming, tonifying herbs in wind-cold, cold-phlegm cough, and cold, deficient digestion.', 'Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Sang Ye.');
