INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H265', 'Amomum / Grains-of-Paradise (Sha Ren)', 'Amomum villosum', 'Zingiberaceae', 'Ripe fruit and seed', 'Pungent (acrid, aromatic)', 'Warm', 'Dry', 'Cold, Dampness, Torpor (atonic, sluggish, cold digestion), Stagnation, Qi Stagnation; cold-damp diarrhea', 'Excess Heat, Dryness, Blood Deficiency with dryness, Acute Inflammation (hot, red, irritated mucosa)', 'Digestive (primary); Spleen and Stomach; Reproductive (morning sickness, restless fetus, via the Spleen and Kidney channels of TCM)', 'Bloating and flatulence, nausea and vomiting (including morning sickness of pregnancy), cold and atonic dyspepsia with poor appetite, cold-damp diarrhea, epigastric distension and fullness; traditionally used to calm a restless fetus (a refer-level obstetric context)', 'Cold-Damp-Relaxed and Cold-Depleted (Vata-like) phenotypes: the sluggish, gassy, cold, boggy digestion with a thick, wet tongue coat. Aggravates hot, dry, choleric (Pitta) constitutions.', 'Vata, Kapha', 'Pitta (heating and drying)', 'Damp obstructing the Spleen and Stomach (middle jiao), Spleen and Stomach Qi stagnation with damp-cold, cold-damp diarrhea, rebellious Stomach Qi (nausea, vomiting); traditionally calms a restless fetus and eases morning sickness', 'Yin Deficiency with heat (night sweats, dry mouth, red tongue with scant coat), blood dryness, Heat and Fire patterns, dry cough of Lung heat', 'Warm, drying aromatic: can consume fluids and worsen heat signs in yin-deficient or dry constitutions. In TCM the fruit is added only in the final 5 minutes of a decoction, since the volatile oil (the active fraction) is driven off by prolonged boiling. Concentrated essential oil is for dilute aromatic or topical use, not high-dose internal use.', 'Yin deficiency with heat, and dry or blood-deficient heat patterns (the warm aromatic nature aggravates them). No absolute contraindication at culinary or standard supervised decoction amounts.', 'Sha Ren is one of the classic pregnancy-supportive herbs of Chinese medicine: it is used to calm a restless fetus and to relieve morning sickness (nausea and vomiting), and it is not a documented abortifacient. Food and standard supervised decoction amounts have a long traditional record of use in pregnancy. Modern controlled safety data are limited, so concentrated extracts and internal essential oil are not established; keep medicinal use to appropriate doses under qualified practitioner guidance. (Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Natural Medicines / Drugs.com NPP: safety data in pregnancy lacking.)', 'Traditionally used and food amounts considered acceptable. Specific modern controlled data during lactation are lacking; keep to food and standard tea or decoction amounts and reserve concentrated extracts for supervised use. (Natural Medicines / Drugs.com NPP: lactation data lacking; Bensky & Gamble.)', 'Culinary and mild aromatic amounts are gentle and traditionally given in TCM for infantile poor appetite and damp-cold diarrhea in reduced, weight-appropriate doses. Reserve concentrated extracts and essential oil for older children under professional guidance. (Chen & Chen, Chinese Medical Herbology and Pharmacology.)', 'No well-documented clinically significant interactions (limited data; AHPA-style Interaction Class A expected for a culinary aromatic). Theoretical only: mild antiplatelet potential of the volatile oil, so a possible additive effect with anticoagulant or antiplatelet drugs at high therapeutic doses; clinical relevance unproven. Culinary and standard decoction use is unproblematic. (Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP.)', 'Decoction (TCM standard; crush the fruit and add in the final 5 minutes to preserve the volatile oil), powdered seed, added to soups and food, tincture, brief infusion of freshly crushed seed. Essential oil for dilute aromatic use only.', 'Decoction: 3-6 g crushed fruit, added in the last 5 minutes (up to 10 g short-term under supervision). Powder: 1.5-3 g. Tincture (1:5): 2-4 mL up to 3x daily. Crush just before use; the aromatic volatile oil is the active fraction and is lost with heat and storage.', 'Stuart, Chinese Materia Medica: Vegetable Kingdom (1911): Amomum (Sha Ren); Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica (traditional Sha Ren / Fructus Amomi entry)', 'Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren); Amomum villosum Lour. ethnopharmacological, phytochemical and pharmacological review (J. Ethnopharmacology, 2024, ScienceDirect S0378874124009140)', 'Sha Ren (Fructus Amomi), ''sand seed'', is the ripe fruit and seed of Amomum villosum Lour. (ginger family, Zingiberaceae; now placed in the genus Wurfbainia as Wurfbainia villosa; A. villosum var. xanthioides and A. longiligulare are accepted substitute sources). It is a leading aromatic damp-transforming, qi-moving herb of Chinese medicine, entering the Spleen, Stomach and Kidney channels. The active fraction is the volatile oil (bornyl acetate, camphor, limonene and related terpenes). It shares the warm carminative, damp-transforming action of true cardamom (Elettaria cardamomum) and black cardamom, but is a distinct species with a specific TCM use to calm a restless fetus and settle morning sickness. Note the common-name caveat: strictly, ''Grains of Paradise'' is Aframomum melegueta, a different West African species; the label is used loosely in the trade (also ''Chinese cardamom'', ''bastard cardamom'') for Amomum villosum, which is the correct binomial for Sha Ren.', 'Not named in the canonical biblical texts. A classical Chinese materia medica herb (Sha Ren), first described among the Tang and Song herbals and standard in later works such as Stuart''s Chinese Materia Medica (1911). The Greco-Roman aromatic ''amomum'' of Dioscorides and Pliny was an Eastern spice-route import that lent its name to the genus but was not identified with this species; Amomum villosum is native to South China and Southeast Asia.', 'Cultivated at scale in Yunnan, Guangdong and across Southeast Asia; the Yang Chun (Guangdong) source is the prized grade. Wild Wurfbainia villosa is pollinator-limited (dependent on specific bee pollination), so commercial supply relies on cultivation and hand-pollination; not listed as globally at-risk, though local wild stands benefit from habitat-conscious sourcing. Prefer cultivated, single-origin Yang Chun Sha for potency and traceability.', 'Warm, dry, acrid-aromatic seed: the middle-warming carminative that transforms cold damp, frees stuck qi, settles nausea and a restless fetus, and rekindles a cold, bloated, sluggish digestion.', 'T1 to T2. Seek obstetric care, do not self-treat, for: threatened miscarriage, vaginal bleeding, or persistent or severe vomiting in pregnancy (rule out hyperemesis). Refer also for: blood in vomit or stool, persistent diarrhea with dehydration, unexplained weight loss, difficulty swallowing, or dyspepsia lasting more than 2 weeks (rule out ulcer or malignancy).', 'shah-RUN (Sha Ren); ah-MOH-mum vih-LOH-sum', 'seed', 'Approved', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (1911): Amomum (Sha Ren); Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica (traditional Sha Ren / Fructus Amomi entry)", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (1911): Amomum (Sha Ren); Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica (traditional Sha Ren / Fructus Amomi entry)", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren); Amomum", "locator": "Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren); Amomum", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
