INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1306', 'H265', 'pregnancy', 'Pregnancy (concentrated or high medicinal doses)', 'moderate', 'Sha Ren is traditionally used IN pregnancy to calm a restless fetus and ease morning sickness and is not a documented abortifacient; however, modern controlled safety data are limited, and the warm, drying aromatic can consume fluids at high doses.', 'Food and standard supervised decoction amounts have a long traditional record in pregnancy. Reserve concentrated extracts and internal essential oil, and any dose above the standard 3-6 g, for use under a qualified practitioner. Any threatened miscarriage or persistent or severe pregnancy vomiting is a refer-to-obstetrics situation, not self-care.', 'Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Natural Medicines / Drugs.com NPP (Sha Ren): pregnancy safety data lacking');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1307', 'H265', 'condition', 'Yin deficiency with heat, and blood-dry or heat and fire patterns', 'moderate', 'The warm, acrid, drying aromatic nature can further consume yin fluids and aggravate heat signs (night sweats, dry mouth, red tongue with scant coating) and dry cough of Lung heat.', 'Avoid or combine with fluid-nourishing, cooling herbs in yin-deficient, dry, or heat-pattern individuals.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology; Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1308', 'H265', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (e.g. warfarin, aspirin, clopidogrel)', 'low', 'Theoretical: the volatile oil has shown mild antiplatelet potential in preliminary study, giving a possible additive bleeding effect at high therapeutic doses. Not confirmed clinically.', 'Culinary and standard decoction use is unproblematic. Monitor only if concentrated preparations are combined with anticoagulant or antiplatelet therapy.', 'Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H265', 'EP01', 'avoid', 0, 2, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry', 'computed_energetics', '{"title": "Stuart, Chinese Materia Medica: Vegetable Kingdom (1911): Amomum (Sha Ren); Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica (traditional Sha Ren / Fructus Amomi entry)", "locator": "Stuart, Chinese Materia Medica: Vegetable Kingdom (1911): Amomum (Sha Ren); Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica (traditional Sha Ren / Fructus Amomi entry)", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren); Amomum", "locator": "Bensky, Gamble & Kaptchuk, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Mills & Bone, Principles and Practice of Phytotherapy; Natural Medicines / Drugs.com NPP (Sha Ren); Amomum", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb, true);
