INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H266', 'Anemarrhena (Zhi Mu)', 'Anemarrhena asphodeloides', 'Asparagaceae (subfamily Agavoideae; formerly placed in Liliaceae, and sometimes given its own family Anemarrhenaceae)', 'Rhizome (dried; Rhizoma Anemarrhenae, Zhi Mu)', 'Bitter, Sweet', 'Cold', 'Moist', 'Excess heat and fire, especially yang-bright (Stomach and Lung) heat with high fever, drenching sweat, intense thirst, and a flooding pulse; dryness and fluid depletion with thirst, dry cough, and wasting-thirst (the classic xiao ke, diabetes-like picture); yin deficiency with rising deficient fire, night sweats, tidal fever, steaming-bone heat, and five-palm heat; heat vexation, irritability, and restlessness (excitation) from fire harassing the interior.', 'Cold and dampness of the middle burner: spleen and stomach deficiency cold with poor appetite, loose stools, or chronic diarrhea, which its cold, moist, sinking nature worsens; general yang deficiency and interior cold; torpid, boggy, cold-damp digestion, where a cold, enriching herb deepens the stagnation.', 'Respiratory and Lungs (clears Lung heat, moistens dry and hot cough); Digestive and Stomach (drains Stomach fire, quells febrile heat and thirst); Urinary and Endocrine by way of the Kidney (nourishes Kidney yin, clears deficient fire, steaming-bone heat, and wasting-thirst, and lowers blood sugar); Immune and febrile (antipyretic in heat disease).', 'High fever with profuse sweating, intense thirst, and irritability in acute febrile (warm) disease (the White Tiger Decoction picture); dry, hot cough with thick, scanty phlegm from Lung heat and dryness; yin-deficient heat with night sweats, tidal fever, a steaming-bone sensation, and five-palm heat; wasting-thirst with excessive thirst, hunger, and urination (the classic xiao ke, diabetes-type pattern); restlessness and insomnia from deficient heat; constipation from heat and dryness.', 'The overheated, dried-out, yin-depleted type: flushed, thirsty, and restless, with night sweats and afternoon fever, whose fluids and cooling reserve have burned down. A cold, moistening herb for the hot and dry, not for the cold, damp, or weak-digestion constitution.', 'Pitta', 'Kapha, Vata', 'Excess heat and fire, especially yang-bright (Yangming) Stomach and Lung heat: high fever, profuse sweating, great thirst, irritability, and a big, flooding pulse (the Bai Hu Tang, White Tiger, pattern). Lung and Stomach yin deficiency with heat and dryness: dry cough, thick sputum, thirst, and wasting-thirst (xiao ke). Kidney yin deficiency with deficient fire blazing: steaming-bone tidal fever, night sweats, five-palm heat, and restlessness (the Zhi Bai Di Huang Wan pattern). Enters the Lung, Stomach, and Kidney channels; it both drains excess fire and, unusually, nourishes yin and moistens dryness.', 'Spleen and Stomach deficiency cold with loose stools or diarrhea, and yang deficiency with interior cold: its cold, moist, sinking nature injures digestive fire and loosens the stool. Not for cold patterns or for cold-damp accumulation in the middle burner.', 'Cold and cloying: because it is cold and moistening it readily weakens digestion and can cause loose stools, poor appetite, and abdominal fullness in anyone with weak or cold digestion, so it is avoided in that setting or paired with warming, spleen-supporting herbs. It has documented blood-sugar-lowering activity, so people on antidiabetic medication should watch for additive hypoglycemia. The acute high-fever and steaming-bone patterns it is reached for can signal serious infection or systemic disease, so it belongs within a full diagnosis rather than being used for undiagnosed fever. Salt-processed material (yan zhi mu) is preferred for guiding the herb to the Kidney to clear deficient fire; raw material is preferred for draining excess Stomach and Lung fire.', 'Spleen and Stomach deficiency cold with chronic loose stools or diarrhea; yang deficiency and interior cold; known hypersensitivity. Use caution with antidiabetic drugs (additive glucose lowering). Reliable human data are lacking in pregnancy and lactation, so avoid or use only under professional supervision. Undiagnosed high or persistent fever is a matter for medical diagnosis, not self-treatment.', 'Insufficient reliable human data; avoid unless directed by a qualified practitioner. Anemarrhena is a cold, fire-draining herb, traditionally used with caution in pregnancy, and controlled human pregnancy safety and reproductive-toxicity data are lacking; given the absence of data the prudent course is to avoid. Source: AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Anemarrhena asphodeloides; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; NCCIH (limited data).', 'Insufficient reliable data; avoid unless professionally supervised. No reliable data describe transfer of timosaponins or mangiferin into breast milk or effects on the nursing infant. Source: AHPA Botanical Safety Handbook, 2nd ed. (2013); NCCIH (no data).', 'Not established for self-care; use only under professional supervision. Anemarrhena appears in pediatric TCM formulas prescribed by trained practitioners but is not a casual home remedy, and modern pediatric safety and dosing data are lacking, especially given its cold nature and tendency to loosen the stool. Source: AHPA Botanical Safety Handbook, 2nd ed. (2013); Bensky, Clavey and Stoger, Materia Medica, 3rd ed.; NCCIH (insufficient data).', 'Antidiabetic drugs (insulin, sulfonylureas, metformin, and others): Anemarrhena and its constituents mangiferin and the timosaponins have documented blood-glucose-lowering activity in animal and cell studies, so the herb may add to the effect of glucose-lowering medication and theoretically increase the risk of hypoglycemia; monitor blood glucose and watch for additive effects. Its documented sedative activity in animal models raises a theoretical additive effect with central nervous system depressants (sedatives and hypnotics). Otherwise no well-documented clinical herb-drug interactions have been reported, and human interaction data are limited. Sources: Miura et al., antidiabetic activity of Anemarrhenae Rhizoma and mangiferin, Biol. Pharm. Bull. 24(9):1009-1011, 2001; drugs.com Natural Products (Zhi Mu) monograph; Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Brinker, Herb Contraindications and Drug Interactions.', 'Water decoction of the sliced dried rhizome (the standard form, usually combined in formula such as Bai Hu Tang with gypsum); salt-processed decoction (yan zhi mu) to direct the herb to the Kidney for deficient fire and steaming-bone heat; powder; tincture; granule or standardized extract. Traditionally combined rather than used alone: with gypsum (Shi Gao) for yang-bright heat, with Phellodendron (Huang Bai) and Rehmannia for yin-deficient fire, and with Fritillaria for a hot, dry cough.', 'Decoction: 6-12 g dried rhizome daily, in formula. Powder: 1.5-3 g. Tincture (1:5): per product labeling, commonly 2-4 mL up to three times daily. Salt-processed (yan zhi mu) is preferred for Kidney deficient-fire patterns; raw (unprocessed) rhizome is preferred for draining excess Stomach and Lung fire. Best used within a formula prescribed by a trained practitioner.', 'Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miura et al., Biol. Pharm. Bull. 24(9):1009-1011, 2001 (antidiabetic activity, mangiferin); drugs.com Natural Products (Zhi Mu) monograph; Plants of the World Online (Kew) for taxonomy; Brinker, Herb Contraindications and Drug Interactions; NCCIH.', 'Sole species of the genus Anemarrhena; botanical author Anemarrhena asphodeloides Bunge. Family placement is unsettled: Plants of the World Online (Kew) places it in Asparagaceae (subfamily Agavoideae); older references and many TCM texts list Liliaceae, and some botanists give it its own family, Anemarrhenaceae. The rhizome is rich in steroidal saponins (timosaponins A-III, A-I, B-II, and anemarsaponins), the xanthone C-glycoside mangiferin (and isomangiferin), the norlignan nyasol (cis-hinokiresinol), and polysaccharides (anemarans). Documented pharmacology includes antipyretic, hypoglycemic (mangiferin and timosaponins), anti-inflammatory, antimicrobial, sedative, and antineoplastic (timosaponin A-III) activity. In TCM it is the chief herb of White Tiger Decoction (Bai Hu Tang) with gypsum, and a key herb of Zhi Bai Di Huang Wan (with Phellodendron and Rehmannia) for yin-deficient fire. Salt-processing (yan zhi mu) guides it to the Kidney.', 'Not in canonical biblical texts and unknown to the ancient Mediterranean world. Native to northern China, Korea, and Mongolia; first recorded in the Shennong Ben Cao Jing (Han dynasty, c. 200 CE), where Zhi Mu is listed among the cooling, fluid-generating herbs, and used continuously in Chinese medicine for roughly two millennia as a chief herb for febrile heat and yin-deficient fire.', 'Anemarrhena asphodeloides is widely cultivated for the herb trade across northern China and is not considered globally threatened; it is an East Asian species and is not on the United Plant Savers at-risk list, which covers North American plants. The main sourcing concerns are botanical authenticity and freedom from pesticide and heavy-metal residues; buy cultivated rhizome from suppliers who provide identity and contaminant testing.', 'Cold and moistening: a bitter, sweet rhizome that drains fierce Stomach and Lung fire while nourishing yin and generating fluids, cooling the steaming-bone heat of burnt-down reserves.', 'Refer for high or persistent fever, fever with confusion, stiff neck, or rash; for night sweats, unexplained weight loss, or tidal fevers that could signal tuberculosis, chronic infection, or malignancy; for excessive thirst, hunger, and urination that may indicate diabetes; and for any severe or worsening cough. Anyone on antidiabetic medication should have blood glucose monitored. These are diagnoses for a clinician, not for herbal self-treatment.', 'Anemarrhena (Zhi Mu): an-em-uh-REE-nuh; jr-MOO (Mandarin, roughly ''jer-moo''). Anemarrhena asphodeloides: an-em-uh-REE-nuh ass-foh-del-OY-deez.', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H266', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H266', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS05', 'Primary', 'Excess heat and fire: drains fierce yang-bright Stomach and Lung fire, high fever, and febrile heat (the White Tiger picture).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS03', 'Primary', 'Dryness and fluid depletion: nourishes yin, generates fluids, and relieves thirst, dry cough, and wasting-thirst.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS10', 'Secondary', 'Excitation: heat vexation, irritability, and restlessness from fire harassing the interior.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS01', 'Secondary', 'Yin deficiency with deficient fire: steaming-bone tidal fever, night sweats, and five-palm heat.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS14', 'Minor', 'The consumptive, steaming-bone deficient-heat picture historically linked to chronic wasting infection.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS17', 'Primary', 'Cold: its cold nature injures yang and is wrong for interior-cold patterns.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS07', 'Secondary', 'Dampness: cold and cloying, it burdens a damp, boggy middle burner and loosens the stool.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H266', 'TS19', 'Minor', 'Torpor: worsens torpid, cold-damp, weak digestion.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H266', 'SY08', 'Primary', 'Digestive and Stomach: drains Stomach fire, quells febrile heat and great thirst.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H266', 'SY07', 'Primary', 'Respiratory and Lungs: clears Lung heat and moistens a dry, hot cough.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H266', 'SY09', 'Secondary', 'Urinary and Kidney channel: clears deficient fire, steaming-bone heat, and wasting-thirst.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H266', 'SY02', 'Secondary', 'Endocrine: nourishes Kidney yin and lowers blood sugar (wasting-thirst, xiao ke).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H266', 'SY05', 'Minor', 'Immune and febrile: antipyretic in acute heat disease.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A49', 'Primary', 'Febrifuge/antipyretic: drains fire and clears high febrile heat (chief herb of White Tiger Decoction).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A09', 'Primary', 'Anti-inflammatory: clears heat and inflammation (saponins, mangiferin).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A11', 'Secondary', 'Demulcent: moistens dryness, generates fluids, and relieves thirst and dry cough.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A36', 'Secondary', 'Hypoglycemic: documented blood-sugar-lowering activity (mangiferin, timosaponins); the wasting-thirst use.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A22', 'Secondary', 'Sedative: calms heat vexation and restlessness (documented sedative activity).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A28', 'Minor', 'Antimicrobial: documented antibacterial and antifungal activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A33', 'Minor', 'Antitussive: eases a dry, hot cough by moistening the Lung.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H266', 'A25', 'Minor', 'Antioxidant: mangiferin and related constituents.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP76', 'Primary', 'Fever management: high fever with sweating and thirst in acute febrile disease; also tidal fever of deficient heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP50', 'Secondary', 'Dry, unproductive, hot cough from Lung heat and dryness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP27', 'Secondary', 'Blood sugar dysregulation: wasting-thirst (xiao ke) and documented hypoglycemic activity.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP13', 'Secondary', 'Systemic inflammation: clears heat and inflammatory fire.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP33', 'Secondary', 'Menopausal vasomotor symptoms: yin-deficient hot flushes and night sweats.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP04', 'Minor', 'Insomnia from deficient heat and restlessness.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H266', 'CP10', 'Minor', 'Anxiety, heat vexation, and irritability from fire harassing the interior.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H266', 'P04', 'Primary', 'Decoction of the sliced rhizome, the standard form, usually within a formula.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H266', 'P03', 'Secondary', 'Powder (including salt-processed yan zhi mu for Kidney deficient fire).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H266', 'P01', 'Secondary', 'Tincture.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H266', 'P02', 'Minor', 'Capsule or standardized granule extract.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H266', 'C06', 'Indicated', 'Primary', 'Robust, hot (Pitta-like) type with excess fire, high fever, and great thirst.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H266', 'C02', 'Indicated', 'Secondary', 'Choleric, fiery, overheated constitution with irritability and heat.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
