INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H266', 'TCM03', 'Primary', 'Spleen Qi deficiency: cold, moist herb injures the spleen and causes loose stools and diarrhea.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H266', 'TCM01', 'Secondary', 'Kidney Yang deficiency and interior cold, worsened by a cold herb.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H266', 'TCM10', 'Minor', 'Cold-damp accumulation in the middle burner, where a cloying cold herb adds to the dampness.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Zhi Mu (Anemarrhena).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu (Anemarrhenae Rhizoma); Chen and Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013); Miu", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1309', 'H266', 'pregnancy', 'Pregnancy', 'moderate', 'Cold, fire-draining herb traditionally used with caution in pregnancy; controlled human pregnancy safety and reproductive-toxicity data are lacking.', 'Avoid in pregnancy unless directed and supervised by a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner and McGuffin, 2013), Anemarrhena asphodeloides; Bensky, Clavey and Stoger, Materia Medica, 3rd ed.; NCCIH (limited data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1310', 'H266', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data describe transfer of timosaponins or mangiferin into breast milk or effects on the nursing infant.', 'Avoid during lactation for want of safety data.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); NCCIH (no data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1311', 'H266', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin, and other hypoglycemics)', 'moderate', 'Anemarrhena and its constituents mangiferin and the timosaponins lower blood glucose in animal and cell studies, giving an additive glucose-lowering effect and a theoretical risk of hypoglycemia.', 'Use with medical oversight; monitor blood glucose and watch for additive hypoglycemia, adjusting medication as needed.', 'Miura et al., Biol. Pharm. Bull. 24(9):1009-1011, 2001; drugs.com Natural Products (Zhi Mu) monograph; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1312', 'H266', 'condition', 'Spleen and Stomach deficiency cold with diarrhea or loose stools', 'moderate', 'The cold, moist, sinking nature of the rhizome injures digestive fire and loosens the stool, worsening cold, weak digestion.', 'Avoid in this setting, or combine with warming, spleen-supporting herbs under practitioner guidance.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed., Zhi Mu; AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1313', 'H266', 'condition', 'Yang deficiency and interior cold', 'moderate', 'A cold herb further suppresses yang and deepens interior cold in constitutionally cold patients.', 'Avoid in yang-deficient, interior-cold patterns.', 'Bensky, Clavey and Stoger, Materia Medica, 3rd ed., Zhi Mu.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1314', 'H266', 'drug_interaction', 'Central nervous system depressants (sedatives, hypnotics)', 'low', 'Documented sedative activity in animal models raises a theoretical additive sedative effect.', 'Use caution when combined with sedative or hypnotic drugs; human data are lacking.', 'drugs.com Natural Products (Zhi Mu) monograph; Brinker, Herb Contraindications and Drug Interactions.');
