INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H267', 'Capillaris Wormwood (Yin Chen, Yin Chen Hao)', 'Artemisia capillaris', 'Asteraceae (Compositae, the daisy and sunflower family)', 'Dried young aerial parts, the tender spring shoots harvested before the plant matures (Herba Artemisiae Scopariae, ''Yin Chen Hao''; the fine early-spring growth is graded ''Mian Yin Chen''). The co-official Chinese Pharmacopoeia source is Artemisia scoparia; only the young shoot is potent, so older summer growth is not used.', 'Bitter, Pungent (acrid, slightly aromatic).', 'Cool (slightly cold).', 'Dry', 'Damp-heat smoldering in the liver and gallbladder: the classic hot, yellow (yang) jaundice with bile stagnation, dark scanty urine, a bitter mouth, and a heavy, oppressed right-sided fullness. Damp-heat pouring downward with hot, scanty, dark urination, and damp-heat weeping, itching skin. Bile and damp stagnation obstructing the free flow of the gallbladder. A cooling, bitter, aromatic drainer for genuinely hot, damp, stagnant, repletion tissue where damp-heat needs to be opened downward and outward through the bile and urine.', 'Cold, weak, deficient digestion, since bitter-cold quenches an already low digestive fire and brings loose stools and poor appetite. Jaundice that is NOT damp-heat: the dull, cold, smoky (yin) jaundice of cold-damp or the sallow pallor of blood and qi deficiency, where a cooling drainer is wrong and can deepen the depletion. Frank dryness and yin or blood deficiency, which a drying bitter worsens. Constitutional cold, exhaustion, and yang deficiency without a true damp-heat excess to clear.', 'Hepatic (Liver and gallbladder) above all, the seat of its damp-heat-draining, bile-opening, jaundice-resolving action. Digestive (Spleen and Stomach, the middle-burner source of damp-heat). Urinary (promotes urination, draining damp-heat downward). Integumentary/skin (damp-heat weeping, itching eruptions). Secondary Immune and hepatic-infective sphere (supportive in viral hepatitis). Channels entered: Spleen, Stomach, Liver, and Gallbladder.', 'Damp-heat (yang) jaundice with bile stagnation, dark urine, and yellowing of the skin and eyes, the defining indication and the emperor herb of Yin Chen Hao Tang. Sluggish liver and gallbladder with bile stagnation, right-sided fullness, and a bitter mouth. Supportive care in damp-heat hepatitis and gallbladder inflammation. Hot, scanty, dark urination of lower-burner damp-heat. Damp-heat skin conditions with weeping, itching, and eczema. Damp-heat fever with a heavy, oppressed quality.', 'Hot-Damp-Excess: the sallow-to-sanguine, bilious, congested, damp-heat phenotype who runs hot and stagnant in the liver and gallbladder, with a greasy, yellow-coated tongue, a bitter mouth, dark urine, and a tendency to itchy, weeping, damp-heat eruptions. Not for the pale, cold, loose-bowelled, depleted (Vata- or yang-deficient) constitution, whom its bitter cold only chills and dries.', 'Pitta, Kapha', 'Vata', 'Damp-Heat above all, the premier herb to clear damp-heat and resolve jaundice: as the emperor herb of Yin Chen Hao Tang it joins Zhi Zi (Gardenia) and Da Huang (rhubarb) for yang jaundice, and pairs with warming herbs for the cold-damp yin-jaundice variant only when reconfigured. It drains damp-heat from the Liver and Gallbladder, opens bile flow, and leads damp-heat out through the urine. Heat and Fire of the liver-gallbladder sphere secondarily, and damp-heat skin patterns. It also clears the damp-heat behind hot, scanty urination.', 'Jaundice from Blood deficiency or qi deficiency (non-damp-heat, deficiency-type sallowness), where a draining bitter-cold is wrong. Cold-damp (yin) jaundice from Spleen and Kidney yang deficiency, which needs warming, not cooling and draining, unless Yin Chen is rebalanced within a warm formula. Spleen and Stomach deficiency-cold with poor appetite and loose stools, which bitter-cold worsens. It is a draining herb for genuine damp-heat repletion, not for cold or deficiency patterns.', 'Bitter, cool, and drying, so even short courses can chill and slow a weak digestion, bringing loose stools and poor appetite; it is best reserved for genuine damp-heat and combined with digestive-protective herbs in cold-prone people. Doses of 15 g or more have been associated in consumer reports with numbness, tremor, irregular heartbeat, dizziness, and fainting, so keep to customary amounts. As an Asteraceae (Compositae) herb it can provoke allergic dermatitis or cross-reactivity in ragweed-sensitive individuals. Most important, its coumarin constituent 6,7-dimethylesculetin (scoparone) activates the nuclear receptor CAR and induces hepatic drug-metabolizing enzymes (CYP3A, CYP2B, CYP2C19, UGT1A1), so it can accelerate the clearance and lower the blood levels of many co-administered medicines (see Drug Interactions). Jaundice must be medically diagnosed before any self-treatment.', 'Non-damp-heat jaundice (cold-damp yin jaundice, or deficiency-type sallowness from blood or qi deficiency). Spleen and Stomach deficiency-cold and Kidney yang deficiency (TCM). Frank yin or blood deficiency with dryness. Pregnancy and lactation except under qualified professional supervision (see safety fields). Concurrent use of narrow-therapeutic-index medications metabolized by CYP3A4, CYP2C19, CYP2B6, or UGT1A1 without professional oversight, given the enzyme-induction interactions. Known Asteraceae/Compositae allergy.', 'Insufficient reliable modern human data; avoid in pregnancy for self-care and use only under qualified professional supervision for a genuine damp-heat pattern. Yin Chen Hao is a bitter, cool, draining herb, and consumer and clinical references advise against use in pregnancy and nursing given the absence of adequate safety data. It is a distinct species from the thujone-rich abortifacient wormwood (Artemisia absinthium) and mugwort (Artemisia vulgaris) and is not a recognized emmenagogue, but its scoparone and chromone constituents strongly induce hepatic drug-metabolizing enzymes (CAR-mediated CYP and UGT induction), which is an additional reason to avoid casual use in pregnancy. Modern references (Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen and Chen, Chinese Medical Herbology and Pharmacology) restrict bitter-cold damp-heat drainers in pregnancy to short-course, practitioner-prescribed use. AHPA Botanical Safety Handbook interaction/pregnancy class to be confirmed at merge.', 'Caution; limited data. There is little modern data on the transfer of Yin Chen constituents into breast milk, and its cool, draining nature could disturb an infant''s digestion, so prolonged or high-dose maternal use should be avoided during lactation. Its enzyme-inducing coumarins (CAR-mediated CYP/UGT induction) are a theoretical concern for an exposed infant''s drug and bilirubin metabolism. Short low-dose courses within a balanced formula under professional supervision are the outer limit of prudent use; prefer better-studied, gentler alternatives while nursing (Chen and Chen; Bensky, Clavey and Stoger).', 'Only under qualified supervision. Notably, the closely related classical preparation Yin Zhi Huang (a decoction built on Artemisia capillaris) is used clinically in East Asia for neonatal jaundice, and its mechanism is documented: 6,7-dimethylesculetin activates the nuclear receptor CAR and induces bilirubin glucuronyl transferase (UGT1A1), accelerating bilirubin clearance (Huang et al., J Clin Invest 2004). This is a supervised medical use, not a license for casual pediatric dosing. Neonatal and infant jaundice must be medically managed, never self-treated. The bitter-cool nature readily chills a child''s digestion, and the same enzyme induction alters the metabolism of any co-administered pediatric medication (Chen and Chen; Bensky, Clavey and Stoger; Huang et al. 2004).', 'The principal, well-characterized concern is enzyme induction. The coumarin 6,7-dimethylesculetin (scoparone) in Artemisia capillaris activates the constitutive androstane receptor (CAR), inducing hepatic CYP2B, CYP3A, and UGT1A1 and accelerating both bilirubin and drug glucuronidation (Huang et al., A traditional herbal medicine enhances bilirubin clearance by activating the nuclear receptor CAR, J Clin Invest 2004;113:137-143). The related Yin Zhi Huang preparation induces CYP3A4-mediated and CYP2C19-dependent metabolism of omeprazole (Xu et al., Acta Pharmacologica Sinica 2008), demonstrating enhanced clearance of a CYP3A4/CYP2C19 substrate. By this mechanism Yin Chen can lower the plasma levels and reduce the efficacy of narrow-therapeutic-index drugs metabolized through these pathways, including warfarin, cyclosporine, tacrolimus and other immunosuppressants, oral contraceptives, many statins, calcium-channel blockers, certain antiretrovirals, and clopidogrel (a CYP2C19-activated prodrug). Separately, its constituent scoparone has documented anticoagulant, antiplatelet, vasorelaxant, and hypolipidemic activity, giving a theoretical additive effect with anticoagulant, antiplatelet, and antihypertensive drugs. Evidence is mechanistic and preclinical to pharmacokinetic; there are no large controlled human interaction trials. Avoid concurrent use with critical-dose medications without professional supervision, separate dosing, and monitor (Huang et al. 2004; Xu et al. 2008; Brinker, Herbal Contraindications and Drug Interactions).', 'Decoction of the dried young shoots is the standard and most effective form, typically decocted briefly to preserve the volatile constituents and given at higher doses for jaundice. Infusion (tea) of the light aerial parts. Powder and capsules of the dried herb. Tincture. Externally, a strong decoction is used as a wash or compress over damp-heat, itching, weeping skin. Classically it anchors the formula Yin Chen Hao Tang with Gardenia and rhubarb for yang jaundice.', 'Decoction: 6 to 15 g dried herb daily in divided doses; higher amounts, commonly up to about 30 g, are used for acute damp-heat jaundice only under professional supervision. Tincture (1:5): 2 to 4 mL up to three times daily. Powder or capsules: about 2 to 4 g daily. External: strong decoction as a wash or compress. Doses of 15 g or more can provoke adverse effects (numbness, tremor, palpitations, faintness) and should be kept to short, supervised courses. A draining herb for genuine damp-heat, not for long-term tonic use.', 'Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications and Drug Interactions; Huang, Zhang, Chua et al., A traditional herbal medicine enhances bilirubin clearance by activating the nuclear receptor CAR, J Clin Invest 2004;113:137-143 (PMC300765); Xu et al., Yin Zhi Huang induces CYP3A4-mediated sulfoxidation and CYP2C19-dependent hydroxylation of omeprazole, Acta Pharmacologica Sinica 2008; Jang, Kim, Kim et al., A Survey of Therapeutic Effects of Artemisia capillaris in Liver Diseases, Evid Based Complement Alternat Med 2015 (PMC4558445); Hsueh et al., The Pharmacological Effects and Pharmacokinetics of Active Compounds of Artemisia capillaris, Biomedicines 2021;9:1412 (PMC8533588); NCCIH.', 'Family Asteraceae. Yin Chen Hao is the dried young spring aerial parts of Artemisia capillaris Thunb. (or the co-official Artemisia scoparia). Key constituents: the coumarins scoparone (6,7-dimethoxycoumarin, also called 6,7-dimethylesculetin) and scopoletin; the chromone capillarisin (and 6-demethoxycapillarisin); the polyyne capillin (antifungal) and the volatile capillene; phenolic acids (chlorogenic and caffeic acid); and flavonoids (arcapillin, cirsimaritin, rhamnocitrin). Pharmacology: choleretic and cholagogue (scoparone, capillarisin, and germacrene D increase bile secretion and biliary excretion of bilirubin and cholesterol), hepatoprotective (lowers transaminases, promotes hepatocyte regeneration; studied in hepatitis B, non-alcoholic fatty liver, cirrhosis, and hepatocellular carcinoma), plus anti-inflammatory, antioxidant, antipyretic, diuretic, hypolipidemic, and antifungal activity. Crucially, 6,7-dimethylesculetin activates the nuclear receptor CAR, inducing CYP2B and CYP3A and UGT1A1 and accelerating bilirubin glucuronidation and clearance, which is both the molecular basis of the traditional Yin Zhi Huang treatment for neonatal jaundice and the source of its enzyme-induction drug interactions. Classically Yin Chen is the emperor herb of Yin Chen Hao Tang (with Zhi Zi and Da Huang) for yang, damp-heat jaundice. A folk harvest rule holds that only the tender third-month shoots are medicinal Yin Chen while the older fourth-month plant is merely hao (common mugwort, fit only for kindling), underscoring that potency lives in the young growth.', 'Not in canonical biblical texts and unknown to the ancient Mediterranean world; native to East Asia (China, Korea, Japan, and the Russian Far East). Its documented tradition is Chinese: the young shoot entered the materia medica in the Han-era Shen Nong Ben Cao Jing as Yin Chen Hao and runs through every later Chinese pharmacopoeia as the premier herb to clear damp-heat and resolve jaundice. It is distinct from the biblical ''wormwood'' (la''anah) of Scripture, which refers to bitter Near Eastern Artemisia such as Artemisia herba-alba or Artemisia judaica, not this East Asian species.', 'Not at risk. Artemisia capillaris is an abundant, weedy, fast-colonizing perennial widely distributed and commercially cultivated and wild-collected across East Asia, and the medicinal portion is only the renewable spring shoot, so it is a low-pressure, sustainable resource. Prefer cultivated or responsibly wild-harvested young shoots. Not listed by United Plant Savers (a North American native-plant registry; this is an Asian species).', 'Cool and drying: a bitter, aromatic spring shoot that drains damp-heat from the liver and gallbladder, opens bile flow, and resolves the yellow of damp-heat (yang) jaundice.', 'Refer for jaundice or any yellowing of the skin or eyes, which requires medical diagnosis and can signal hepatitis, biliary obstruction, or hemolysis rather than a self-treatable complaint; dark urine with pale stools; right-upper-abdominal pain, fever, or known gallstones or biliary disease; suspected or diagnosed hepatitis or any liver disease; persistent nausea or vomiting; and neonatal or infant jaundice, which must be medically managed and never self-treated. Refer anyone who is pregnant or breastfeeding, or who takes a narrow-therapeutic-index medication (warfarin, cyclosporine, tacrolimus, oral contraceptives, antiretrovirals, immunosuppressants, or other CYP3A4/CYP2C19/UGT1A1 substrates) before use, given the enzyme-induction interactions.', 'Capillaris Wormwood: kap-ih-LAIR-iss WURM-wood. Artemisia capillaris: ar-teh-MEE-zhee-uh kap-ih-LAIR-iss. Yin Chen Hao: yin chun how.', 'seed', 'Approved', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H267', 'T01');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H267', 'T03');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS07', 'Primary', 'Dampness: the core action, draining damp-heat from the liver, gallbladder, and lower burner.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS05', 'Primary', 'Excess heat: clears the heat component of damp-heat jaundice and damp-heat fever.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS08', 'Primary', 'Stagnation: opens bile and damp stagnation obstructing the gallbladder (relaxant/draining action).');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS16', 'Secondary', 'Excess conditions: a draining, clearing herb for genuine damp-heat repletion.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS06', 'Secondary', 'Acute inflammation: cools hot, inflamed hepatobiliary and damp-heat skin tissue.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS15', 'Minor', 'Acute infection: supportive in acute damp-heat hepatitis and gallbladder inflammation.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS14', 'Minor', 'Chronic infection: supportive in chronic viral hepatitis (hepatoprotective).');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS17', 'Primary', 'Cold: bitter-cool quenches cold, weak digestion and is wrong for cold-damp (yin) jaundice.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS01', 'Primary', 'Deficiency: a draining cool bitter is wrong for blood- or qi-deficiency sallowness and depletion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS03', 'Secondary', 'Dryness: a drying bitter worsens yin- or fluid-deficient dryness.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H267', 'TS04', 'Minor', 'Exhaustion: draining cold further depletes the truly spent.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY12', 'Primary', 'Hepatic: damp-heat jaundice, bile stagnation, hepatitis, gallbladder heat.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY08', 'Secondary', 'Digestive (Spleen/Stomach): the middle-burner source of damp-heat, bitter mouth, poor appetite.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY09', 'Secondary', 'Urinary: promotes urination, leading damp-heat downward (hot, scanty, dark urine).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY10', 'Secondary', 'Skin: damp-heat weeping, itching eruptions and eczema (internal and external wash).');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY13', 'Minor', 'Spleen: clears damp accumulation of the spleen sphere.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H267', 'SY05', 'Minor', 'Immune: supportive antiviral/hepatoprotective role in viral hepatitis.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A43', 'Primary', 'Cholagogue: promotes bile flow and relieves bile stagnation in jaundice.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A44', 'Primary', 'Choleretic: scoparone and capillarisin increase bile secretion and biliary bilirubin/cholesterol excretion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A13', 'Primary', 'Hepatoprotective: lowers transaminases, protects and regenerates hepatocytes (hepatitis, NAFLD, cirrhosis).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A08', 'Secondary', 'Diuretic: promotes urination, draining damp-heat downward.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A09', 'Secondary', 'Anti-inflammatory: cools hepatobiliary and damp-heat skin inflammation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A49', 'Secondary', 'Febrifuge/antipyretic: clears damp-heat fever.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A16', 'Secondary', 'Bitter tonic: bitter stimulates bile and digestive secretion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A25', 'Minor', 'Antioxidant: chlorogenic acid, scoparone, and flavonoid free-radical scavenging.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A14', 'Minor', 'Alterative: clears damp-heat from the blood and skin.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A31', 'Minor', 'Antifungal: the polyyne capillin has documented antifungal activity.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A28', 'Minor', 'Antimicrobial: broad activity of the volatile oil and coumarins.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H267', 'A37', 'Minor', 'Hypotensive: scoparone is vasorelaxant and mildly hypotensive/hypolipidemic.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP72', 'Primary', 'Sluggish liver/bile stagnation: the defining damp-heat liver-gallbladder indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP74', 'Primary', 'Cholestasis: damp-heat (yang) jaundice with bile stagnation and yellowing.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP13', 'Secondary', 'Systemic/hepatic inflammation: damp-heat hepatitis and gallbladder inflammation.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP66', 'Secondary', 'Fluid retention: diuretic draining of damp-heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP18', 'Secondary', 'Damp-heat skin conditions with itching and weeping (general).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP67', 'Secondary', 'Eczema/atopic dermatitis of a damp-heat, weeping character (internal and external wash).');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP65', 'Minor', 'Urinary irritation: hot, scanty, dark urination of lower-burner damp-heat.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP09', 'Minor', 'Chronic infection: supportive in chronic viral hepatitis.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP75', 'Minor', 'Oxidative stress: antioxidant hepatoprotection.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H267', 'CP76', 'Minor', 'Fever management: damp-heat fever with a heavy, oppressed quality.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P04', 'Primary', 'Decoction of the dried young shoots, the standard form (brief decoction; higher dose for jaundice).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P05', 'Secondary', 'Infusion (tea) of the light aerial parts.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P03', 'Secondary', 'Powdered dried herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P01', 'Secondary', 'Tincture.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P02', 'Minor', 'Capsules of the dried herb.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H267', 'P10', 'Minor', 'Compress or wash of strong decoction over damp-heat, itching, weeping skin.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H267', 'C06', 'Indicated', 'Primary', 'Robust/Hot (Pitta-like): damp-heat repletion of the liver-gallbladder sphere.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H267', 'C02', 'Indicated', 'Secondary', 'Choleric: bilious, congested, hot liver-gallbladder heat with a bitter mouth.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H267', 'C05', 'Aggravates', 'Primary', 'Thin/Cold/Depleted (Vata-like): bitter cool chills and dries.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
