INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H267', 'TCM01', 'Secondary', 'Kidney Yang deficiency: cold-damp (yin) jaundice needs warming, not cooling and draining.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H267', 'TCM03', 'Secondary', 'Spleen Qi deficiency-cold: bitter-cool damages weak digestion and loosens the stool.', '{"title": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "locator": "Shen Nong Ben Cao Jing (The Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Yin Chen Hao (Artemisia capillaris), listed among the herbs to clear heat, dispel damp, and resolve jaundice.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Yin Chen Hao; Chen and Chen, Chinese Medical Herbology and Pharmacology, Yin Chen Hao; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herbal Contraindications", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1315', 'H267', 'pregnancy', 'Pregnancy', 'moderate', 'Bitter, cool, draining herb with insufficient human safety data; its scoparone and chromone constituents strongly induce hepatic drug-metabolizing enzymes (CAR-mediated CYP and UGT induction), and consumer and clinical references advise against use in pregnancy.', 'Avoid for self-care. Use only short-course, low-dose within a practitioner-prescribed formula for a genuine damp-heat pattern; avoid routine or prolonged use.', 'WebMD/RxList consumer safety monograph (Yin Chen); Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology. AHPA class to confirm at merge.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1316', 'H267', 'breastfeeding', 'Breastfeeding', 'moderate', 'Limited data on transfer of Yin Chen constituents into breast milk; its cool, draining nature may disturb an infant''s digestion, and its enzyme-inducing coumarins could theoretically alter an exposed infant''s drug and bilirubin metabolism.', 'Avoid prolonged or high-dose use while nursing; only short low-dose courses under professional supervision. Prefer gentler, better-studied alternatives.', 'Chen and Chen, Chinese Medical Herbology and Pharmacology; Bensky, Clavey and Stoger, Materia Medica (3rd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1317', 'H267', 'drug_interaction', 'CYP3A4, CYP2C19, CYP2B6, and UGT1A1 substrates (warfarin, cyclosporine, tacrolimus, oral contraceptives, statins, calcium-channel blockers, clopidogrel, antiretrovirals, omeprazole)', 'moderate', '6,7-dimethylesculetin (scoparone) activates the nuclear receptor CAR, inducing hepatic CYP2B, CYP3A, and UGT1A1 and accelerating drug and bilirubin glucuronidation; the related Yin Zhi Huang preparation induces CYP3A4-mediated and CYP2C19-dependent metabolism of omeprazole. This can lower the plasma levels and reduce the efficacy of narrow-therapeutic-index drugs cleared by these pathways.', 'Avoid concurrent use with critical-dose medications without professional supervision; separate dosing and monitor drug levels/clinical response (e.g., INR for warfarin, immunosuppressant levels).', 'Huang et al., A traditional herbal medicine enhances bilirubin clearance by activating the nuclear receptor CAR, J Clin Invest 2004;113:137-143 (PMC300765); Xu et al., Acta Pharmacologica Sinica 2008 (Yin Zhi Huang and omeprazole); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1318', 'H267', 'drug_interaction', 'Anticoagulant, antiplatelet, and antihypertensive drugs (warfarin, aspirin, clopidogrel, antihypertensives)', 'moderate', 'The constituent scoparone has documented anticoagulant, antiplatelet, vasorelaxant, and hypolipidemic activity, giving a theoretical additive effect with these drug classes. Evidence is preclinical/mechanistic.', 'Use caution and monitor (coagulation, blood pressure); avoid concurrent therapeutic use without professional supervision.', 'Scoparone pharmacology (anticoagulant, vasorelaxant, hypolipidemic); Brinker, Herbal Contraindications and Drug Interactions (theoretical additivity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1319', 'H267', 'condition', 'Non-damp-heat jaundice (cold-damp yin jaundice; blood- or qi-deficiency sallowness) and Spleen/Stomach deficiency-cold (TCM)', 'moderate', 'Yin Chen is a cooling, draining herb specific to damp-heat (yang) jaundice; in cold-damp or deficiency-type jaundice, or in cold, weak digestion, its bitter-cool drainage worsens the cold and depletion, causing poor appetite and loose stools.', 'Reserve for genuine damp-heat patterns; in cold or deficiency patterns avoid, or use only reconfigured within a warming, tonifying formula under professional guidance.', 'Bensky, Clavey and Stoger, Materia Medica (3rd ed.); Chen and Chen, Chinese Medical Herbology and Pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1320', 'H267', 'condition', 'High-dose use (15 g or more) and Asteraceae/Compositae allergy', 'moderate', 'Doses of about 15 g or more have been associated in consumer reports with numbness, tremor, irregular heartbeat, dizziness, and fainting; as an Asteraceae herb it can cause allergic dermatitis or cross-reactivity in ragweed-sensitive individuals.', 'Keep to customary doses in short courses; avoid in known Compositae allergy; discontinue if neurological or cardiac symptoms or rash occur.', 'WebMD/RxList consumer safety monograph (Yin Chen); AHPA Botanical Safety Handbook (Asteraceae allergy class, to confirm at merge).');
