INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H268', 'Chinese Senega / Polygala (Yuan Zhi)', 'Polygala tenuifolia Willd.', 'Polygalaceae, the milkwort family. Polygala tenuifolia Willd. is Yuan Zhi (Chinese senega or Chinese polygala); the Chinese Pharmacopoeia also accepts the closely related Polygala sibirica L. as an official source of the drug Radix Polygalae.', 'Dried root, classically the cored root bark (Radix Polygalae, Yuan Zhi). The woody central core is removed and the saponin-rich root bark used; the root is usually honey-fried (zhi yuan zhi) to temper its harshness on the stomach.', 'Pungent (acrid) and Bitter. The acrid quality opens and disperses (moving phlegm and opening the orifices), and the bitter quality drains and dries phlegm-damp.', 'Warm', 'Dry', 'Phlegm-damp stagnation, the herb''s core terrain: thick, sticky phlegm that clogs the Lungs (copious, hard-to-raise cough) and, in the classical image, veils the orifices of the Heart to fog the mind, blur memory, cloud consciousness, and, when it stirs, provoke seizures. This is a boggy, congested, sluggish, phlegm-laden picture (dampness and phlegm organized into stagnation) that the herb dries, dissolves, and moves. Alongside it, an excited, restless, unsettled shen: insomnia, palpitations, anxiety, and agitation in which the spirit will not settle, which the herb calms; and where phlegm binds the spirit into a heavy, withdrawn, low mood, it opens and lifts that too. The tissue is damp, congested, and stuck, or the spirit over-stirred, rather than dry, hot, or depleted, and what it needs is warm, acrid, drying, dispersing, spirit-settling action to break up the phlegm, open the orifices, and quiet the heart.', 'A warm, acrid, drying, dispersing herb is wrong for hot, dry, and depleted tissue. Yin deficiency with heat and empty fire, and frank internal heat, which its warmth and acridity aggravate. Dryness and fluid-poor states, which its drying quality parches further. And, as a practical matter, an inflamed or ulcerated stomach: the irritant saponins inflame gastritis and peptic ulceration and provoke nausea and vomiting, so acute GI mucosal inflammation and ulceration are a clear contraindication. It is a herb for cold, damp, phlegm-congested, over-stirred terrain, not for heat, dryness, depletion, or a raw, inflamed gut.', 'Nervous and mental: the Heart-shen and cognition above all, for insomnia, anxiety, restlessness, poor memory, disorientation, and phlegm-clouded consciousness (the classical benefiting of the will and intelligence). Respiratory (Lungs): phlegm-damp cough with copious sputum, which it expels. Cardiovascular (Heart): palpitations and anxious restlessness of a disturbed Heart-shen. It works along the Heart-Kidney (Shao Yin) axis, reconnecting the two to steady sleep, memory, and will. Secondary reach to the skin and flesh in its topical and internal use for abscesses, sores, and swollen, painful breasts. Channels entered: Heart, Kidney, Lung.', 'Insomnia and disturbed sleep, especially with a restless, anxious, palpitating heart and Heart-Kidney disharmony. Poor memory, forgetfulness, mental fogginess, and disorientation (its headline classical and modern use, benefiting the intelligence). Anxiety, restlessness, agitation, and palpitations. Phlegm-damp cough with copious or difficult-to-expectorate phlegm, and bronchial congestion. Phlegm-type seizures, clouded consciousness, and disordered behavior from phlegm veiling the orifices. Abscesses, boils, sores, and swollen, painful breasts (topically and internally). Low, constrained, phlegm-bound mood as a secondary use.', 'Cold-Damp-Phlegmatic, the boggy, phlegm-congested type whose sluggish, foggy mentation, poor memory, heavy dull head, and copious phlegm sit on a cold, damp terrain that this warm, drying, phlegm-dispersing opener suits best (phlegmatic). It is wrong for the hot, dry, or depleted constitutions: the robust, hot (Pitta-like) and choleric types, whose heat its warmth and acridity aggravate, and the thin, cold, dry, depleted (Vata-like) and dry melancholic types, whose dryness and depletion its drying, dispersing action deepens.', 'Kapha', 'Pitta, Vata', 'Phlegm obstructing the Heart orifices and misting the mind, the signature pattern: disorientation, muddled or clouded consciousness, poor memory, seizures, and manic or withdrawn behavior arising when phlegm veils the sensory orifices, which Yuan Zhi opens and clears. Heart and Kidney failing to communicate (Shao Yin disharmony) with a restless shen: insomnia, palpitations, anxiety, restlessness, and forgetfulness, for which it calms the spirit and is said to restore the Heart-Kidney connection. Phlegm-damp in the Lungs: cough with copious or difficult-to-expectorate phlegm, which it resolves and expels. It also disperses toxic swelling in abscesses, sores, and swollen, painful breasts. Its nature is bitter, acrid, and warm, entering Heart, Kidney, and Lung.', 'Yin deficiency with heat, empty fire, or vigorous internal fire, where a warm, acrid, drying herb injures fluids and stokes heat. Heat and Fire patterns generally. It is likewise unsuited to those with peptic ulcer, gastritis, or a delicate stomach, in whom its irritant saponins provoke nausea and vomiting (a functional rather than strictly pattern-based contraindication). Best avoided in the frankly heat-dry or yin-depleted terrain.', 'The chief practical caution is gastrointestinal: the triterpenoid saponins are mucosal irritants and are emetic in quantity, so raw Yuan Zhi and higher doses can cause nausea, vomiting, stomach upset, and loose stools. It is therefore contraindicated in active peptic ulcer disease and gastritis, and the honey-fried (zhi yuan zhi) form, or taking it with food and in modest doses, is preferred to buffer the stomach. Being warm, acrid, and drying, it is inappropriate in yin deficiency with heat signs or vigorous internal fire, which it aggravates. Its sedative, shen-calming action can add to other sedatives, hypnotics, and alcohol. Avoid in pregnancy. As with any herb used for insomnia, cognitive decline, seizures, or a persistent cough, it should support rather than replace proper diagnosis of the underlying cause.', 'Active peptic ulcer, gastritis, or GI mucosal inflammation, where the irritant saponins aggravate the condition. Yin deficiency with heat or vigorous internal fire, which its warm, acrid, drying nature worsens. Pregnancy (emmenagogue and uterine-stimulant caution) and, on precautionary grounds, lactation and young children. Concurrent use of strong sedatives, hypnotics, or CNS depressants and alcohol without supervision, given additive sedation. Known hypersensitivity to Polygala. Undiagnosed seizures, acute confusion or psychiatric change, chest pain, or a persistent or bloody cough call for medical evaluation rather than self-treatment (see refer threshold).', 'Avoid in pregnancy. Yuan Zhi is treated in modern Chinese materia medica (Bensky, Clavey and Stoger, 3rd ed 2004; Chen and Chen, 2004) as an emmenagogue and uterine stimulant and is contraindicated during pregnancy; the saponins are also gastric irritants and emetic in higher doses. There are no controlled human pregnancy safety data and no adequate reproductive-toxicity studies, so the prudent course is to avoid it entirely in pregnancy. NCCIH has no monograph, and a species-specific AHPA Botanical Safety Handbook class was not confirmed at authoring (see flags).', 'Insufficient data; avoid during breastfeeding. There are no data on transfer of Polygala tenuifolia constituents into breast milk or on effects in the nursing infant, and the same emmenagogue and gastric-irritant cautions that bar it in pregnancy carry over. In the absence of safety data the prudent course is to avoid therapeutic doses while nursing unless directed by a qualified practitioner.', 'No established pediatric dosing and little modern safety data; use in children only under qualified TCM supervision, if at all. The irritant saponins commonly cause nausea, vomiting, and stomach upset, a particular concern in the young, and no controlled pediatric safety data exist. Classical use in children (for example within shen-calming or phlegm-resolving formulas) is always in small, practitioner-adjusted doses and preferably the honey-fried (zhi yuan zhi) form; self-treatment of children is not advised.', 'There are no large controlled clinical interaction studies for Polygala tenuifolia; the following are pharmacodynamic and preclinical cautions. CNS depressants and sedatives: its shen-calming, sedative, sleep-promoting action (documented for the saponins and oligosaccharide esters) may add to benzodiazepines, barbiturates, Z-drugs, sedating antihistamines, opioids, other sedative herbs, and alcohol, increasing drowsiness and CNS depression; monitor and reduce dose. Anticoagulant and antiplatelet drugs: some Polygala constituents show antiplatelet or anticoagulant activity in preclinical work, so a theoretical additive bleeding risk exists with warfarin, heparins, direct oral anticoagulants, aspirin, and clopidogrel (limited human data; use caution and monitor). CYP enzymes: in-vitro inhibition of CYP2E1 has been reported, of uncertain clinical significance for co-administered CYP2E1 substrates. Gastric irritants: the irritant saponins may compound the GI effects of NSAIDs, aspirin, and alcohol. References: Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Brinker, Herbal Contraindications and Drug Interactions (2010); Mills and Bone, Principles and Practice of Phytotherapy (2013); preclinical pharmacology cited under secondary sources. NCCIH has no monograph.', 'Decoction (tang), the classical form: the dried, cored root or root bark simmered, typically honey-fried (zhi yuan zhi) to temper its harshness and protect the stomach, and often combined with shen-calming and phlegm-resolving herbs (for example suan zao ren, fu shen, shi chang pu, and long gu). Powder (san) and honey pills (wan). Tincture, and modern capsule or concentrated extract (the common Western nootropic form). Cough syrup for phlegm-damp cough. Topically, a powder or paste and poultice of the root has been applied to sores, abscesses, and swollen, painful breasts. The bitter, acrid woody core is traditionally removed and the richer root bark used.', 'Decoction: 3 to 9 g of dried root per day (commonly 3 to 6 g), honey-fried, in divided doses. Powder: 1 to 3 g per day. Tincture (1:5): about 2 to 4 mL up to three times daily. Modern standardized root extract or capsule: follow product labeling (often a few hundred mg once or twice daily). Begin at the low end, take with food, and use the honey-fried form to minimize gastric upset; reduce or stop if nausea, vomiting, or loose stools occur. Higher doses are emetic.', 'Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening the Heart orifices, and sharpening the senses. Li Shizhen, Bencao Gangmu (Compendium of Materia Medica, 1596, public domain) - Yuan Zhi.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of metabolites, pharmacological activities and toxicology (Frontiers in Pharmacology, 2024) and Pharmacology of Polygala tenuifolia and its significance in traditional Chinese medicine (2023). Safety framework: AHPA Botanical Safety Handbook (2nd ed, 2013), Brinker, Herbal Contraindications and Drug Interactions (2010), and Mills and Bone (2013); a species-specific AHPA class for Polygala tenuifolia was not confirmed at authoring (see flags). NCCIH has no Herbs at a Glance entry.', 'Radix Polygalae (Yuan Zhi) is the dried root, classically the cored root bark, of Polygala tenuifolia Willd. (the Chinese Pharmacopoeia also admits the closely related Polygala sibirica L.) in the milkwort family, Polygalaceae. The name Chinese Senega is an analogy to the American Seneca snakeroot, Polygala senega, a congeneric saponin-rich expectorant; both share the family''s phlegm-moving character, but the correct binomial for Yuan Zhi is Polygala tenuifolia. Documented constituents include triterpenoid (oleanane) saponins (the onjisaponins A, B, E, F, and G and their aglycones tenuifolin and senegenin/polygalacic acid derivatives), oligosaccharide esters (tenuifolisides and sibiricoses), xanthones (polygalaxanthone and related), and the sugar-alcohol polygalitol, to which its expectorant, sedative, neuroprotective, memory-enhancing, and mucosa-irritant (emetic) effects are attributed. Its clinical identity is that of a warm, acrid, drying opener: it resolves and moves phlegm (from both the Lungs and the orifices of the Heart and mind), calms a restless shen, and is said to reconnect Heart and Kidney (the Shao Yin axis), so it is used for insomnia, palpitations with anxiety, disorientation, poor memory and mental fogginess, phlegm-type seizures, phlegm-damp cough, and, topically or internally, for abscesses and swollen breasts. Modern interest centers on its saponins and oligosaccharide esters as nootropic, anti-amnesic, and antidepressant candidates. Channels entered: Heart, Kidney, Lung. Classical karma: calms the spirit, benefits the will and intelligence, opens the orifices, expels phlegm, and reduces abscesses.', 'Not a plant of the biblical Near East and not named in canonical Scripture. Polygala tenuifolia is native to northern and northeastern China, Mongolia, and Korea and belongs to the Chinese materia medica rather than the Mediterranean-biblical tradition. It is one of the oldest recorded Chinese herbs, listed among the upper-grade (superior) medicines of the Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE) for calming the spirit and benefiting the will and intelligence, and detailed later in Li Shizhen''s Bencao Gangmu (1596). Included here as an honestly sourced cross-traditional entry from the Chinese canon; the common name Chinese Senega is by analogy to the North American Polygala senega, not a biblical reference.', 'Polygala tenuifolia is extensively cultivated for the herb trade in China (notably Shanxi and Shaanxi), so commercial material is generally cultivated rather than wild. It is not on the United Plant Savers list, which covers North American species, but it is a root crop, and root harvest kills the plant, and wild stands in parts of its range have experienced collection pressure. Prefer cultivated, sustainably grown root from suppliers who can name their source, and favor the abundant cultivated supply over wild-collected material.', 'Warm, dry, and acrid: a phlegm-dissolving, orifice-opening shen-calmer that clears phlegm from the Lungs and the mind, quiets a restless, anxious heart, and reconnects Heart and Kidney to restore sleep, memory, and calm.', 'Refer new, worsening, or unexplained seizures, fainting, acute confusion, or a marked change in mental state or behavior for medical evaluation rather than self-treatment. Refer chest pain, or palpitations with breathlessness, syncope, or an irregular pulse. Refer a cough lasting more than three weeks, or any cough with blood, fever, night sweats, or weight loss (to exclude tuberculosis, pneumonia, and malignancy). Refer severe, persistent, or worsening insomnia, anxiety, or low mood, and any suicidal ideation. Refer significant epigastric pain, vomiting, or signs of GI bleeding. Pregnant or breastfeeding people and young children should not self-treat with this herb.', 'Yuan Zhi: ywen jr (roughly yoo-EN JUR). Polygala tenuifolia: puh-LIG-uh-luh ten-yoo-ih-FOH-lee-uh.', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H268', 'T03');
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H268', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS08', 'Primary', 'Stagnation: phlegm-damp organized into thick, stuck congestion in the Lungs and clouding the orifices; broken up and moved.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS23', 'Primary', 'Phlegm: sticky phlegm veiling the Heart orifices and clogging the Lungs; dissolved and expelled.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS07', 'Secondary', 'Dampness: boggy, phlegm-damp, sluggish terrain with foggy mentation and copious sputum; dried and decongested.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS10', 'Secondary', 'Excitation: a restless, over-stirred, unsettled shen with insomnia, anxiety, and palpitations; calmed and settled.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS11', 'Minor', 'Depression: a heavy, withdrawn, phlegm-bound low spirit; opened and lifted as the phlegm clears.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS05', 'Primary', 'Excess heat: warm and acrid, it aggravates yin-deficient heat, empty fire, and internal heat.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS06', 'Primary', 'Acute inflammation: the irritant saponins inflame gastritis and an inflamed GI mucosa; contraindicated.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS03', 'Secondary', 'Dryness: a warm, drying herb parches dry, fluid-poor, yin-deficient tissue further.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H268', 'TS25', 'Secondary', 'Ulceration: contraindicated in peptic ulceration, which its emetic, irritant saponins worsen.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H268', 'SY01', 'Primary', 'Nervous: Heart-shen and cognition; insomnia, anxiety, poor memory, disorientation, phlegm-clouded consciousness.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H268', 'SY07', 'Primary', 'Respiratory: phlegm-damp cough with copious sputum; expectorant, opens the Lung.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H268', 'SY06', 'Secondary', 'Cardiovascular: palpitations and anxious restlessness of a disturbed Heart-shen; the Heart-Kidney axis.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H268', 'SY14', 'Secondary', 'Lungs: the TCM Lung organ and channel; resolves and expels phlegm.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H268', 'SY10', 'Minor', 'Integumentary (skin/flesh): topical and internal use for abscesses, sores, and swollen, painful breasts.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A12', 'Primary', 'Expectorant: expels phlegm from the Lungs and disperses phlegm-damp; a defining action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A03', 'Primary', 'Nervine relaxant: calms and settles a restless, over-stirred shen; classical spirit-calming (an shen).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A48', 'Primary', 'Nootropic / cerebral tonic: benefits the will and intelligence, sharpens memory, opens the Heart orifices.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A22', 'Secondary', 'Sedative: eases insomnia, restlessness, and palpitations of a disturbed Heart-shen.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A33', 'Secondary', 'Antitussive: relieves phlegm-damp cough alongside its expectorant action.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A26', 'Secondary', 'Anxiolytic: quiets anxiety, agitation, and an unsettled spirit.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A47', 'Secondary', 'Hypnotic: promotes sleep onset in restless, Heart-Kidney-disharmony insomnia.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A10', 'Minor', 'Antispasmodic: used for phlegm-type seizures and convulsive, clouded-consciousness presentations.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A28', 'Minor', 'Antimicrobial: antibacterial activity reported for root extracts and saponins.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A31', 'Minor', 'Antifungal: documented antifungal activity of the saponin fraction.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A09', 'Minor', 'Anti-inflammatory: modern data on saponins and xanthones suppressing pro-inflammatory signaling.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A24', 'Minor', 'Vulnerary: topical root powder or paste for sores and abscesses; disperses toxic swelling.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H268', 'A02', 'Minor', 'Nervine tonic: a trophorestorative edge to the Heart-shen and memory over time.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP04', 'Primary', 'Insomnia: restless, anxious, palpitating sleeplessness of Heart-Kidney disharmony; calmed and settled.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP24', 'Primary', 'Mental fog / cognitive dullness: forgetfulness, poor memory, disorientation; the headline use, benefiting the intelligence.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP10', 'Primary', 'Anxiety: restlessness, agitation, and an unsettled spirit; the classical shen-calming indication.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP49', 'Primary', 'Cough productive: phlegm-damp cough with copious or difficult-to-raise sputum; resolved and expelled.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP46', 'Secondary', 'Palpitations: anxious palpitations of a disturbed Heart-shen.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP51', 'Secondary', 'Bronchial congestion: phlegm-damp congestion of the Lungs; decongested.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP70', 'Secondary', 'Boils / abscess: abscesses, sores, and swollen, painful breasts; dispersed topically and internally.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP21', 'Minor', 'Nervous exhaustion: a trophorestorative, memory-supporting effect on a depleted, over-taxed Heart-shen.');
INSERT INTO public.herbs_complaints (herb_id, complaint_id, strength_of_indication, notes) VALUES ('H268', 'CP11', 'Minor', 'Depression: a heavy, withdrawn, phlegm-bound low mood; opened as phlegm clears.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P04', 'Primary', 'Decoction (tang) of the honey-fried, cored root, the classical internal form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P01', 'Secondary', 'Tincture, a convenient Western form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P03', 'Secondary', 'Powder (san) and honey pills (wan).');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P02', 'Secondary', 'Capsule / concentrated extract, the common modern nootropic form.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P09', 'Minor', 'Cough syrup for phlegm-damp cough.');
INSERT INTO public.herbs_preparations (herb_id, prep_id, strength_of_indication, notes) VALUES ('H268', 'P08', 'Minor', 'Poultice or paste of root powder topically for sores, abscesses, and swollen breasts.');
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'C04', 'Indicated', 'Primary', 'Phlegmatic: the cold, damp, phlegm-congested type with foggy, sluggish mind, poor memory, and copious phlegm.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'C06', 'Aggravates', 'Primary', 'Robust / Hot (Pitta-like): warm and acrid, it aggravates the hot, plethoric, fiery constitution.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'C02', 'Aggravates', 'Secondary', 'Choleric: its warmth and acridity stoke the heat of the choleric type.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'C05', 'Aggravates', 'Secondary', 'Thin / Cold / Depleted (Vata-like): drying, dispersing, and acrid; deepens dryness and depletion (aggravates Vata).', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
