INSERT INTO public.herbs_doshas_match (herb_id, dosha_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'D03', 'Primary', 'Kapha: warm, dry, and acrid; dissolves kapha phlegm-damp and clears a heavy, foggy, dull mind.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
