INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'TCM07', 'Primary', 'Yin deficiency: warm, acrid, and drying, it injures fluids and worsens yin-deficient dryness and empty fire.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H268', 'TCM11', 'Secondary', 'Heat / Fire: aggravates internal heat and vigorous fire.', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1321', 'H268', 'pregnancy', 'Pregnancy', 'absolute', 'Treated in modern Chinese materia medica as an emmenagogue and uterine stimulant and traditionally contraindicated in pregnancy; the irritant saponins are also emetic. No controlled human pregnancy data or adequate reproductive-toxicity studies exist.', 'Avoid Yuan Zhi entirely during pregnancy. Do not self-treat; a qualified practitioner should be involved in any use of Chinese herbs in pregnancy.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004); Brinker, Herbal Contraindications and Drug Interactions (2010).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1322', 'H268', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on transfer into breast milk or effects on the nursing infant; the emmenagogue and gastric-irritant cautions of pregnancy carry over.', 'Avoid therapeutic doses while breastfeeding unless directed by a qualified practitioner.', 'Precautionary; Bensky (2004); Mills and Bone, Principles and Practice of Phytotherapy (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1323', 'H268', 'condition', 'Peptic ulcer disease, gastritis, or an inflamed / delicate stomach', 'moderate', 'The triterpenoid saponins irritate the GI mucosa and are emetic, provoking nausea, vomiting, and stomach upset, and aggravating ulceration and gastritis.', 'Contraindicated in active ulcer or gastritis. Otherwise use the honey-fried (zhi yuan zhi) form, take with food, keep doses modest, and stop if nausea or loose stools occur.', 'Bensky (2004); Chen and Chen, Chinese Medical Herbology and Pharmacology (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1324', 'H268', 'condition', 'Yin deficiency with heat / vigorous internal fire', 'moderate', 'Its warm, acrid, drying nature injures fluids and stokes heat, worsening yin-deficient heat and empty or vigorous fire.', 'Avoid in yin-deficient heat and internal fire patterns; if phlegm-heat is present, pair with cooling, yin-protecting herbs under supervision.', 'Bensky (2004); Chen and Chen (2004); traditional TCM energetics.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1325', 'H268', 'drug_interaction', 'CNS depressants (benzodiazepines, barbiturates, Z-drugs, sedating antihistamines, opioids), other sedative herbs, and alcohol', 'moderate', 'Its documented sedative, shen-calming, sleep-promoting action may be additive with other CNS depressants, increasing drowsiness and sedation.', 'Use cautiously with sedatives and alcohol; monitor for excessive drowsiness and reduce dose or avoid combining without supervision.', 'Chen and Chen (2004); Brinker, Herbal Contraindications and Drug Interactions (2010); preclinical sedative pharmacology.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1326', 'H268', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparins, DOACs, aspirin, clopidogrel)', 'low', 'Some Polygala constituents show antiplatelet or anticoagulant activity in preclinical studies, giving a theoretical additive bleeding risk. Human data are lacking.', 'Use caution and monitor for bruising or bleeding if combined with anticoagulant or antiplatelet therapy; discuss with the prescriber (limited evidence).', 'Preclinical Polygala pharmacology (see secondary sources); Brinker, Herbal Contraindications and Drug Interactions (2010) as safety framework. Flagged as low-certainty (see flags).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1327', 'H268', 'condition', 'Children', 'moderate', 'The irritant, emetic saponins commonly cause nausea and vomiting, a particular concern in the young, and no controlled pediatric safety or dosing data exist.', 'Use in children only under qualified supervision at small, weight-appropriate doses of the honey-fried form; do not self-treat children.', 'Precautionary; Bensky (2004); Chen and Chen (2004).');
