INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H268', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, c. 200 CE, public domain) - Yuan Zhi (Radix Polygalae), listed among the upper-grade (superior) medicines for calming the spirit, benefiting the will and intelligence, opening th", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004) - Yuan Zhi (Radix Polygalae). Chen and Chen, Chinese Medical Herbology and Pharmacology (2004) - Yuan Zhi. Modern pharmacology: Polygalae Radix: review of met", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H269', 'Chinese Yam (Shan Yao)', 'Dioscorea polystachya', 'Dioscoreaceae', 'Rhizome (dried; dry-fried ''chao'' Shan Yao favored for Spleen and diarrhea, raw favored for Lung and Kidney yin)', 'Sweet', 'Neutral', 'Moist', 'Deficiency (qi and yin depletion of the Spleen, Lung, and Kidney), atrophy and wasting of chronic illness and convalescence, dryness (deficient fluids, dry cough, thirst), exhaustion, and laxity with leakage (chronic loose stool, spontaneous sweating, spermatorrhea, leukorrhea, frequent or nocturnal urination).', 'Dampness and damp-heat, frank excess conditions, and stagnation (food stagnation, abdominal fullness and distension, heavy phlegm accumulation).', 'Digestive (Spleen and Stomach), Respiratory (Lungs), Urinary and Reproductive (Kidney and essence), with supporting endocrine (blood sugar) and immune (polysaccharide) action.', 'Spleen and Stomach qi deficiency with poor appetite, fatigue, and chronic loose stool; Lung qi and yin deficiency with chronic cough and wheeze; Kidney deficiency with spermatorrhea, leukorrhea, and frequent or nocturnal urination; wasting-thirsting disorder (xiao ke) and blood sugar dysregulation; convalescence and debility in the young and the old.', 'The depleted, dry-yet-lax phenotype: frail, thin, easily tired people with weak digestion, chronic loose stool, and quiet leaking (sweat, urine, essence). A building food-tonic for the run-down, not for the damp, congested, boggy phlegmatic with abdominal fullness.', 'Vata, Pitta', 'Kapha', 'Simultaneously tonifies the qi and yin of Spleen, Lung, and Kidney and astringes leakage of essence. Spleen and Stomach qi deficiency (poor appetite, fatigue, chronic loose stool, spontaneous sweat); Lung qi and yin deficiency (chronic cough, wheeze, shortness of breath); Kidney deficiency (spermatorrhea, leukorrhea, frequent or nocturnal urination); and wasting-thirsting disorder (xiao ke).', 'Excess patterns, damp-heat or damp-stagnation with abdominal fullness and distension, food stagnation, and constipation. Its sweet, moistening, astringent, and somewhat cloying nature can deepen dampness and obstruct qi movement, so it is paired with qi-moving and damp-draining herbs rather than used alone in these cases.', 'The sweet, moistening, astringent, and cloying nature can obstruct qi or add to dampness. Avoid using alone where there is abdominal fullness, food stagnation, or heavy phlegm-damp. May lower blood glucose. Rare Dioscorea hypersensitivity.', 'Excess patterns with damp-heat, marked abdominal distension, food stagnation, or constipation. Known allergy to yam (Dioscorea) species.', 'Long culinary and tonic tradition in pregnancy (Chinese yam congee is a classic nourishing pregnancy food) with no established teratogenicity; regarded as safe in food and standard decoction amounts. It is not an emmenagogue or uterine stimulant. Concentrated or standardized extracts are less studied and show mild estrogenic activity, so reserve high-dose extracts for practitioner supervision.', 'Traditionally eaten as a nourishing food during lactation with no documented adverse effects; considered compatible in food and standard decoction amounts. Data on concentrated extracts are lacking, so favor culinary and standard-dose use.', 'A classic pediatric tonic food; Chinese yam congee is traditionally given to children for weak digestion, poor appetite, and chronic loose stool. Gentle and well tolerated in food and age-appropriate decoction amounts.', 'May potentiate blood-glucose-lowering drugs and insulin; monitor glucose and adjust doses under clinical supervision, as Shan Yao and Shan Yao-containing formulas show additive hypoglycemic benefit. Mild estrogen-receptor-modulating constituents (adenosine and arbutin, acting via ERalpha, ERbeta, and GPR30) mean concentrated extracts warrant theoretical caution alongside hormone therapy or in estrogen-dependent conditions. No other well-documented pharmacokinetic interactions in the limited data available.', 'Decoction (dried slices, alone or in formula), added to soups and congee as a food therapy, powder, and tincture. Dry-frying (chao) is preferred to strengthen the Spleen and check diarrhea; the raw root is preferred to nourish Lung and Kidney yin and generate fluids.', 'Decoction 15-30 g/day dried; up to 60-250 g/day as a single-herb decoction for severe deficiency or wasting-thirsting under practitioner supervision. Powder 6-10 g. Tincture 2-4 mL (1:5) up to three times daily. Fresh root freely as food.', 'Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Shu Yu / Shan Yao (Dioscorea), listed as a superior (upper-grade) herb.', 'Li Shizhen, Bencao Gangmu (1596), Shan Yao; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Zhang et al. (Shanyao and diabetes), Evid Based Complement Alternat Med, PMC7685178; Chen et al. (estrogenic effects of Dioscorea opposita), PMC6017084; Mills & Bone, Principles and Practice of Phytotherapy.', 'Accepted name Dioscorea polystachya; principal synonyms D. opposita and D. batatas. Rhizome constituents include mucilage and polysaccharides (mannan), the steroidal saponin diosgenin, allantoin, dopamine, batatasins, choline, arbutin, adenosine, amino acids, and abundant starch. Note that dietary diosgenin does not convert into human steroid hormones in the body. Shan Yao is the rare tonic that builds qi and yin of three organs at once (Spleen, Lung, Kidney) while securing essence, gentle enough to be a food for children and elders yet clinically load-bearing as the moistening, harmonizing assistant in classic formulas such as Liu Wei Di Huang Wan, Shen Qi Wan (Jin Gui), You Gui Wan, Zuo Gui Wan, Wan Dai Tang (for leukorrhea), and Yu Ye Tang (for wasting-thirsting). It is a distinct food-grade species from Wild Yam (D. villosa), which is a warming antispasmodic used differently and not a food. Bounding caution: sweet, moistening, and astringent, so it can aggravate dampness, food stagnation, and abdominal fullness and should not be used alone in those settings.', 'Not in canonical biblical texts; native to East Asia (China). First recorded in the Shennong Ben Cao Jing (Han dynasty) as shu yu, later shan yao, a superior herb said to reinforce physical strength and, with long use, to brighten the eyes and improve hearing.', 'Widely cultivated as a staple food and medicinal crop across East Asia; not at risk and not on any conservation watch list. Source cultivated rhizome. Be aware that D. polystachya has naturalized and become invasive in parts of the eastern United States (spread by aerial bulbils, the ''cinnamon vine'' or ''air potato''), so do not plant or wild-spread it outside cultivation.', 'Neutral and moistening, sweetly building: a gentle food-tonic that fills deficiency, generates fluids, and astringes leakage across Spleen, Lung, and Kidney without heating or cloying the way richer tonics can.', 'Refer for medical evaluation with unexplained weight loss, persistent thirst with excessive urination (evaluate for diabetes), cough lasting more than three weeks or any coughing of blood, blood in the stool or diarrhea with dehydration, or worsening edema and abdominal distension.', 'Common: SHAHN yow (Shan Yao). Latin: dy-oh-SKOR-ee-uh pol-ee-STAK-ee-uh.', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Shu Yu / Shan Yao (Dioscorea), listed as a superior (upper-grade) herb.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Classic of Materia Medica, Han dynasty, c. 200 BCE to 200 CE), Shu Yu / Shan Yao (Dioscorea), listed as a superior (upper-grade) herb.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Li Shizhen, Bencao Gangmu (1596), Shan Yao; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Zhang et al. (Shanyao and diabetes), Evid Based Complement Alter", "locator": "Li Shizhen, Bencao Gangmu (1596), Shan Yao; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.; Chen & Chen, Chinese Medical Herbology and Pharmacology; Zhang et al. (Shanyao and diabetes), Evid Based Complement Alter", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
