INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1328', 'H269', 'condition', 'Excess dampness, damp-heat, or food stagnation', 'moderate', 'Sweet, moistening, astringent, and cloying nature can deepen dampness and obstruct qi movement, aggravating abdominal fullness and stagnation.', 'Do not use alone in these patterns; combine with qi-moving and damp-draining herbs, or defer until the excess clears.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Shan Yao).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1329', 'H269', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Additive blood-glucose-lowering effect; Shan Yao and Shan Yao-containing formulas show documented hypoglycemic activity.', 'Monitor blood glucose and coordinate any dose adjustments with the prescribing clinician.', 'Zhang et al., Evid Based Complement Alternat Med (Shanyao for diabetes), PMC7685178; Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1330', 'H269', 'drug_interaction', 'Hormone therapy and estrogen-sensitive conditions', 'moderate', 'Constituents adenosine and arbutin show mild estrogen-receptor-modulating (SERM-like) activity via ERalpha, ERbeta, and GPR30.', 'Food and standard decoction amounts are low risk; use caution with concentrated or standardized extracts in estrogen-dependent cancers or alongside hormonal therapy.', 'Chen et al., Estrogenic Effects of the Extracts from Chinese Yam (Dioscorea opposita), PMC6017084.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1331', 'H269', 'pregnancy', 'Pregnancy', 'low', 'No established teratogenicity and long use as a pregnancy tonic food; not an emmenagogue or uterine stimulant. Concentrated extracts are under-studied and show mild estrogenic activity.', 'Food and standard decoction amounts regarded as safe; reserve high-dose or standardized extracts for practitioner supervision.', 'Bensky, Clavey & Stoger, Materia Medica, 3rd ed.; estrogenic data PMC6017084.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1332', 'H269', 'breastfeeding', 'Breastfeeding', 'low', 'Nourishing food traditionally used during lactation with no documented adverse effects; concentrated-extract data are limited.', 'Compatible in food and standard decoction amounts; favor culinary use over concentrated extracts.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1333', 'H269', 'other', 'Known Dioscorea (yam) allergy', 'moderate', 'Hypersensitivity to yam species.', 'Avoid in anyone with a known Dioscorea allergy.', 'General clinical caution (Dioscorea hypersensitivity).');
