INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1334', 'H270', 'pregnancy', 'Pregnancy', 'moderate', 'No formal safety studies and no AHPA/NCCIH monograph; consumer sources conflict. Traditionally used only within practitioner-prescribed Kidney-tonifying formulas and not a documented abortifacient.', 'Avoid self-prescription in pregnancy; use only under a qualified practitioner.', 'AHPA Botanical Safety Handbook 2nd ed. (no monograph); Bensky et al., Chinese Herbal Medicine: Materia Medica 3rd ed. (2004); vendor safety labels');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1335', 'H270', 'condition', 'Damp-heat of the lower jiao / painful or difficult urination from heat', 'moderate', 'The sour, astringent, warming nature aggravates damp-heat and can lock heat into the bladder, worsening dysuria.', 'Do not use in acute UTI, dysuria from heat, or damp-heat patterns; clear the heat first.', 'Bensky et al., Chinese Herbal Medicine: Materia Medica 3rd ed. (2004); Me & Qi / classical TCM materia medica');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1336', 'H270', 'condition', 'Unresolved exterior or excess pathogen (acute infection with fever)', 'moderate', 'As an astringent it consolidates and can trap an active pathogen internally before it is released.', 'Withhold until the exterior or excess pathogen is cleared and residual deficiency is the dominant pattern.', 'Bensky et al., Chinese Herbal Medicine: Materia Medica 3rd ed. (2004)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1337', 'H270', 'condition', 'Ministerial (Ming Men) fire with priapism or frequent erections', 'moderate', 'Warming and securing action can intensify constrained heat manifesting as priapism.', 'Avoid in blazing ministerial fire patterns.', 'American Dragon / Bensky-derived TCM materia medica');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1338', 'H270', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'Tannins and iridoid glycosides carry mild antiplatelet potential; theoretical additive bleeding risk at therapeutic doses only.', 'Monitor if combining concentrated preparations with anticoagulants; food amounts unproblematic.', 'Corni Fructus pharmacology reviews (PMC6020197, 2018); vendor safety labels');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1339', 'H270', 'drug_interaction', 'Insulin and oral hypoglycemic drugs', 'low', 'Alpha-glucosidase inhibition and glucose-lowering activity in modern studies; theoretical additive hypoglycemia.', 'Monitor blood glucose if combining medicinal doses with antidiabetic medication.', 'Corni Fructus pharmacology reviews (PMC6020197, 2018; PMC8072387, 2021)');
