INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1340', 'H271', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Blood-invigorating and menstrual-moving herb that may stimulate uterine activity; potent centrally acting alkaloids with no controlled human pregnancy data.', 'Do not use during pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), class 2b; traditional TCM contraindication (Bensky et al., 2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1341', 'H271', 'breastfeeding', 'Breastfeeding', 'moderate', 'Isoquinoline alkaloids including tetrahydropalmatine may pass into breast milk; infant effects unstudied.', 'Avoid while breastfeeding unless directed and monitored by a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), class 2c.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1342', 'H271', 'drug_interaction', 'CNS depressants and sedatives (benzodiazepines, opioids, barbiturates, alcohol)', 'moderate', 'Tetrahydropalmatine is sedative; effects on the central nervous system may be additive, risking excessive drowsiness or respiratory depression.', 'Avoid combined use; caution with driving or operating machinery.', 'Natural Medicines / WebMD Corydalis monograph; Bensky et al. (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1343', 'H271', 'drug_interaction', 'Anticoagulants and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Blood-invigorating action plus berberine content may theoretically slow platelet aggregation and clotting, increasing bleeding risk.', 'Use caution and monitor; discontinue before surgery.', 'Natural Medicines Corydalis monograph; Chen & Chen (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1344', 'H271', 'drug_interaction', 'Narrow-therapeutic-index drugs metabolized by CYP3A4, CYP2C19, or CYP2C9', 'moderate', 'Corydalis alkaloids (corydaline, tetrahydropalmatine) inhibit or induce these hepatic enzymes in laboratory and animal studies, potentially altering drug levels.', 'Use caution with agents such as certain anticonvulsants, immunosuppressants, and anticoagulants; monitor for altered effect.', 'PMID 25134417 (CYP2E1/3A up-regulation, rat); PMC6264278 (corydaline CYP2C19/2C9 inhibition, human microsomes).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1345', 'H271', 'drug_interaction', 'Dopamine agonists, antipsychotics, and Parkinson medication', 'moderate', 'Tetrahydropalmatine is a dopamine D2 receptor antagonist and may oppose dopaminergic therapy or add to extrapyramidal effects.', 'Avoid in patients on dopaminergic or antipsychotic therapy without professional oversight.', 'Natural Medicines Corydalis monograph; pharmacology reviews of tetrahydropalmatine.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1346', 'H271', 'condition', 'Hepatic impairment / concurrent hepatotoxic drugs', 'moderate', 'Rare hepatotoxicity has been reported, predominantly with multi-ingredient corydalis-containing supplements.', 'Avoid in active liver disease and do not combine with known hepatotoxic medications; discontinue if signs of liver injury appear.', 'Systematic review of corydalis hepatotoxicity case reports (PMC8739176); Natural Medicines monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1347', 'H271', 'population', 'Infants and young children', 'moderate', 'Potent centrally acting alkaloids with no pediatric safety data.', 'Avoid in young children; use in older children only under qualified supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); absence of pediatric data.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H271', 'EP01', 'neutral', 1, 1, 'temperature: herb hot reinforces the pattern''s hot; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica), 1596 - Yan Hu Suo (\u5ef6\u80e1\u7d22, Rhizoma Corydalis). The herb was first recorded earlier by Chen Cangqi in the Ben Cao Shi Yi (Supplement to the Materia Medica), Tang dynasty, c. 720 CE.", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica), 1596 - Yan Hu Suo (\u5ef6\u80e1\u7d22, Rhizoma Corydalis). The herb was first recorded earlier by Chen Cangqi in the Ben Cao Shi Yi (Supplement to the Materia Medica), Tang dynasty, c. 720 CE.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Gardner & McGuffin (eds.), AHPA Botanical Safety Handbook, 2nd ed. (2013); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Natural Medicines /", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Gardner & McGuffin (eds.), AHPA Botanical Safety Handbook, 2nd ed. (2013); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Natural Medicines /", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
