INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H272', 'TCM07', 'Secondary', 'yin deficiency with effulgent fire', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Du Zhong (Eucommia), listed in the superior/upper class as non-toxic and suitable for long-term use.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Du Zhong (Eucommia), listed in the superior/upper class as non-toxic and suitable for long-term use.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Du Zhong; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); He et al., ''Traditional application and modern pharmacological research of Eucommia ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Du Zhong; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); He et al., ''Traditional application and modern pharmacological research of Eucommia ", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1348', 'H272', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional ''calm-the-fetus'' herb (chief herb of Shou Tai Wan) used to prevent threatened/habitual miscarriage, but it is a warming yang tonic and modern human safety/efficacy data in pregnancy are lacking.', 'Use in pregnancy only under a qualified herbalist or physician; not for self-directed use. Bleeding or cramping in pregnancy is an obstetric emergency requiring immediate referral.', 'Natural Medicines / drugs.com Du Zhong monograph; AHPA Botanical Safety Handbook, 2nd ed. (2013) (insufficient human data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1349', 'H272', 'breastfeeding', 'Breastfeeding', 'moderate', 'No modern lactation safety data; traditional texts are silent on nursing.', 'Avoid self-directed use while breastfeeding; use only under professional guidance.', 'Natural Medicines / drugs.com Du Zhong monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1350', 'H272', 'drug_interaction', 'Antihypertensive medications (ACE inhibitors, ARBs, calcium-channel blockers, diuretics)', 'moderate', 'Additive blood-pressure-lowering effect (pinoresinol diglucoside, renin-angiotensin-system modulation, vasorelaxation).', 'Monitor blood pressure; watch for hypotension or orthostatic symptoms when combined.', 'Natural Medicines / drugs.com; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1351', 'H272', 'drug_interaction', 'Reserpine and similar antihypertensive/sympatholytic agents', 'low', 'Reported additive hypotension and orthostatic effects in Chinese clinical literature.', 'Avoid concurrent use or monitor blood pressure closely.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); drugs.com Du Zhong.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1352', 'H272', 'drug_interaction', 'Sedative-hypnotics / CNS depressants', 'low', 'Theoretical additive sedation reported in Chinese pharmacology literature.', 'Use caution and monitor for excess sedation; limited data.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Natural Medicines.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1353', 'H272', 'condition', 'Yin-deficient heat / damp-heat / acute febrile illness', 'moderate', 'Warming yang tonic aggravates empty-heat and damp-heat patterns.', 'Avoid, or combine with yin-nourishing and heat-clearing herbs, in patients with night sweats, five-palm heat, red dry tongue, or active fever.', 'Bensky, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen & Chen (2004).');
