INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1354', 'H273', 'pregnancy', 'Pregnancy (self-use)', 'moderate', 'Insufficient modern safety data. Classical Chinese medicine uses Gou Teng for eclampsia and pre-eclampsia only within practitioner-prescribed formulas; it is not a documented abortifacient but its potent hypotensive and CNS-active alkaloids are not appropriate for unsupervised use.', 'Do not self-administer in pregnancy. Use only under qualified professional supervision; hypertensive or eclamptic symptoms in pregnancy require obstetric care.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); Bensky, Clavey & Stoger (2004)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1355', 'H273', 'breastfeeding', 'Breastfeeding', 'moderate', 'No safety data during lactation; the alkaloids'' transfer into milk and effect on the infant are unstudied.', 'Avoid during breastfeeding or use only under professional supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1356', 'H273', 'drug_interaction', 'Antihypertensives and calcium-channel blockers', 'moderate', 'Rhynchophylline is a non-selective calcium-channel antagonist with documented blood-pressure-lowering activity; additive with antihypertensive drugs.', 'Monitor blood pressure closely and adjust medication under supervision if combined; watch for hypotension, dizziness, and syncope.', 'Brinker, Herbal Contraindications and Drug Interactions, 4th ed. (2010); Mills & Bone (2013); gou-teng vasorelaxation study (PMID 8208063)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1357', 'H273', 'drug_interaction', 'CNS depressants and sedative-hypnotics (benzodiazepines, barbiturates)', 'moderate', 'Gou Teng has sedative and anticonvulsant CNS activity; theoretical additive sedation and CNS depression.', 'Use cautiously with sedatives; watch for excess drowsiness. Do not substitute for prescribed anticonvulsant therapy.', 'Brinker, Herbal Contraindications and Drug Interactions, 4th ed. (2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1358', 'H273', 'drug_interaction', 'CYP3A4-metabolized drugs (statins such as simvastatin, cyclosporine and tacrolimus, some calcium-channel blockers, oral contraceptives)', 'moderate', 'Gou Teng extract and its alkaloids (rhynchophylline, isorhynchophylline, corynoxeine, isocorynoxeine) activate the pregnane X receptor (PXR) and induce CYP3A4, accelerating metabolism and potentially lowering plasma concentrations and efficacy of CYP3A4-cleared drugs.', 'Avoid concurrent use with narrow-therapeutic-index CYP3A4 substrates (e.g., immunosuppressants) unless monitored; anticipate possible loss of drug effect and monitor levels where feasible.', 'Lei et al., ''Identification of PXR Activators from Uncaria rhynchophylla (Gou Teng),'' Drug Metabolism and Disposition 51(5):629 (2023, PMC10158501)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1359', 'H273', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, heparin, aspirin, clopidogrel)', 'low', 'Theoretical additive antiplatelet/bleeding potential attributed to Uncaria constituents; limited direct evidence.', 'Monitor for bruising or bleeding if combined with anticoagulant or antiplatelet therapy.', 'Brinker, Herbal Contraindications and Drug Interactions, 4th ed. (2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1360', 'H273', 'condition', 'Hypotension', 'moderate', 'Its vasodilatory, blood-pressure-lowering action can worsen low blood pressure.', 'Avoid in hypotension; discontinue if dizziness or faintness develops.', 'Bensky, Clavey & Stoger (2004); Mills & Bone (2013)');
