INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H273', 'EP08', 'avoid', 0, 2, 'temperature: herb cold reinforces the pattern''s cold; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Stuart GA. Chinese Materia Medica: Vegetable Kingdom (1911): genus Uncaria / Ourouparia (syn. Nauclea), the drug kou-teng (''hook vine''), stems with hooks prescribed for convulsions of children. Public domain (Internet Archive item b31350033", "locator": "Stuart GA. Chinese Materia Medica: Vegetable Kingdom (1911): genus Uncaria / Ourouparia (syn. Nauclea), the drug kou-teng (''hook vine''), stems with hooks prescribed for convulsions of children. Public domain (Internet Archive item b31350033", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Gou Teng entry; Pharmacopoeia of the People''s Republic of China, Ramulus Uncariae cum Uncis; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013)", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Gou Teng entry; Pharmacopoeia of the People''s Republic of China, Ramulus Uncariae cum Uncis; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013)", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H274', 'Gastrodia (Tian Ma)', 'Gastrodia elata', 'Orchidaceae', 'Dried rhizome / tuber (typically steamed then dried)', 'Sweet', 'Neutral', 'Neutral', 'Wind (internal Liver wind with tremor, spasm, and convulsion); Tension and constriction (muscular spasm, convulsive tightening); Excitation (ascendant Liver yang, agitation, throbbing vertigo). Also wind-phlegm turbidity rising to the head.', 'Blood deficiency and yin deficiency, per Ben Jing Feng Yuan: ''if there is blood deficiency without wind it must not be used recklessly.'' Dryness and deficiency-heat states, since the dispersing rhizome can further consume fluids in an already depleted person.', 'Nervous system, Hepatic (Liver), Cardiovascular, Musculoskeletal', 'Headache and migraine, dizziness and vertigo, tremor and convulsion, seizures, hypertension from Liver yang rising, limb numbness and wind-damp joint pain.', 'Hot-Tense-Rising; the choleric, Liver-driven phenotype in whom heat and wind ascend, flushed and taut, with pounding headache, spinning vertigo, and tremor. Poorly suited to the pale, cold, blood-deficient phenotype.', 'Vata, Pitta', 'Kapha (mildly, and only with prolonged use of the sweet rhizome; the herb is temperature-neutral and largely dosha-gentle).', 'Liver Wind stirring internally (tremor, spasm, convulsion, childhood and febrile seizures) and Liver Yang rising (headache, dizziness, hypertension). Also wind-phlegm ascending (the Ban Xia Bai Zhu Tian Ma Tang pattern of phlegm-turbid dizziness) and wind-damp obstructing the collaterals (numbness, bi-pain).', 'Wind generated by blood or yin deficiency without concurrent tonification; deficiency-heat flaring upward; and external wind-cold headache, since Tian Ma settles internal, not external, wind.', 'Doses beyond the therapeutic range (traditionally cautioned near 40 g) may provoke chest tightness, dizziness, nausea, and skin eruptions. Allergic skin rash has been reported. Gastrodin is heat-sensitive, so add the rhizome in the last 10 to 15 minutes of decoction. Not a standalone remedy when wind arises from an underlying blood or yin deficiency; pair with tonics that address the root.', 'Known allergy or hypersensitivity to Gastrodia. Wind or tremor arising from blood-deficiency or yin-deficiency without concurrent tonification. External wind-cold headache and common cold.', 'NEEDS REVIEW: no pregnancy-specific human safety studies located. Gastrodia carries an overall AHPA Botanical Safety Handbook Class 1 rating (safe when used appropriately) and classical Chinese sources do not list it as an emmenagogue or abortifacient, but pregnancy-specific controlled data are absent. Use in pregnancy only under a qualified practitioner. (AHPA Botanical Safety Handbook, 2nd ed.; data otherwise limited.)', 'NEEDS REVIEW: no lactation-specific data located. Overall AHPA Class 1, but excretion in breast milk and effects on the nursing infant are unstudied. Avoid during lactation unless directed by a qualified practitioner. (AHPA Botanical Safety Handbook, 2nd ed.; Mills & Bone.)', 'Traditionally used within TCM formulas for childhood convulsions and febrile seizures under professional supervision (a use recorded from the Mingyi Bielu onward). No modern pediatric safety trials exist. Pediatric use only under a qualified practitioner, never for self-treatment of a seizing child.', 'No well-documented clinical interactions are established, and several references state none are known (AHPA Class 1). The following are theoretical, from pharmacology and limited data: (1) Sedatives and CNS depressants (benzodiazepines, barbiturates, alcohol) may show additive sedation, as gastrodin has sedative-hypnotic and GABA-enhancing activity; (2) Antihypertensives may show additive hypotension, as Gastrodia lowers blood pressure through vasodilation; (3) Anticoagulants and antiplatelet drugs (warfarin, aspirin, clopidogrel) carry a theoretical additive bleeding risk, as extracts inhibit platelet aggregation and are antithrombotic; (4) Anticonvulsants, additive and uncertain. Monitor accordingly. (Gastrodin CNS reviews, Frontiers in Pharmacology 2018; Kim et al., Medicina 2021, platelet aggregation; Brinker; Mills & Bone.)', 'Traditionally decocted with the rhizome added late, powdered, or stewed in medicinal soups (classically with fish head or chicken). Also taken as tincture or standardized capsule/extract.', 'Decoction: 3 to 10 g dried rhizome (up to 15 g under supervision), added in the final 10 to 15 minutes to protect heat-sensitive gastrodin. Powder: 1 to 1.5 g, 2 to 3 times daily. Do not exceed roughly 40 g (toxicity threshold). Tincture and standardized capsules per manufacturer labeling.', 'Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Eastern Han compilation, c. 200 CE) - Tian Ma / Chi Jian, listed among the superior (top-grade) medicinals.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); American Herbal Products Association Botanical Safety Handbook (2nd ed., 2013); Wu et al., ''Gastrodia elata Bl.: A Comprehensive Review of Its Traditional Use, Botany, Phytochemistry, Pharmacology, and Pharmacokinetics,'' Evid Based Complement Alternat Med (2023); Zhang et al., ''A Review on Central Nervous System Effects of Gastrodin,'' Frontiers in Pharmacology (2018).', 'The chief constituents are gastrodin (p-hydroxymethylphenyl-beta-D-glucopyranoside) and its aglycone gastrodigenin (p-hydroxybenzyl alcohol), plus parishins, vanillyl alcohol, 4-hydroxybenzaldehyde, and polysaccharides. Gastrodia elata is a fully mycoheterotrophic orchid: it has no chlorophyll and lives symbiotically on the fungus Armillaria mellea, so cultivation requires co-culturing that fungus. The herb is steamed and dried before use to temper harshness. It is the foremost TCM herb for internal wind, but because it disperses rather than tonifies it is classically paired: with Gou Teng in Tian Ma Gou Teng Yin for Liver yang rising, and with Ban Xia and Bai Zhu for wind-phlegm dizziness. Neurological presentations (new seizures, stroke signs, thunderclap headache) require medical work-up before any herbal management.', 'Not in canonical biblical texts. Native to East Asia (China, Korea, Japan, and the Himalayas); first recorded in the Han-era Shennong Ben Cao Jing as a superior-grade herb, under the names Chi Jian and Tian Ma, and expanded in the Mingyi Bielu for wind disorders and childhood convulsions.', 'Gastrodia elata is a chlorophyll-free orchid wholly dependent on its Armillaria fungal symbiont; all Orchidaceae are listed under CITES Appendix II. Wild stands were heavily depleted by overharvest, but the herb is now extensively cultivated in Yunnan, Guizhou, and Sichuan. Choose cultivated, not wild-collected, rhizome. Not tracked by United Plant Savers, which covers North American species.', 'Neutral and settling: a sweet, wind-extinguishing anchor that quiets tremor and draws rising Liver yang back down to earth.', 'New or thunderclap headache, sudden severe vertigo, a first-time or unremitting seizure, stroke signs (facial droop, one-sided weakness, speech change), uncontrolled hypertension, or any progressive neurological deficit require urgent medical evaluation, not self-treatment.', 'Gastrodia (gas-TROH-dee-uh); Gastrodia elata (gas-TROH-dee-uh ell-AH-tuh); Tian Ma (tyen-MAH).', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Eastern Han compilation, c. 200 CE) - Tian Ma / Chi Jian, listed among the superior (top-grade) medicinals.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Eastern Han compilation, c. 200 CE) - Tian Ma / Chi Jian, listed among the superior (top-grade) medicinals.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); American Herbal Products Association Botanical Safety Handbook (2nd ed., 2013); Wu et al., ''Ga", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); American Herbal Products Association Botanical Safety Handbook (2nd ed., 2013); Wu et al., ''Ga", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
