INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H274', 'TCM13', 'Minor', 'External wind-cold headache; Tian Ma settles internal wind only.', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Eastern Han compilation, c. 200 CE) - Tian Ma / Chi Jian, listed among the superior (top-grade) medicinals.", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of the Materia Medica, Eastern Han compilation, c. 200 CE) - Tian Ma / Chi Jian, listed among the superior (top-grade) medicinals.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); American Herbal Products Association Botanical Safety Handbook (2nd ed., 2013); Wu et al., ''Ga", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); American Herbal Products Association Botanical Safety Handbook (2nd ed., 2013); Wu et al., ''Ga", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1361', 'H274', 'pregnancy', 'Pregnancy', 'moderate', 'No pregnancy-specific human safety data. Overall AHPA Class 1 and not classically an emmenagogue/abortifacient, but controlled data are absent.', 'Avoid unless directed and monitored by a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); pregnancy-specific data limited.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1362', 'H274', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation data; excretion in milk and infant effects unstudied.', 'Avoid during lactation unless directed by a qualified practitioner.', 'AHPA Botanical Safety Handbook, 2nd ed.; Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1363', 'H274', 'drug_interaction', 'Sedatives / CNS depressants (benzodiazepines, barbiturates, alcohol)', 'moderate', 'Gastrodin has sedative-hypnotic and GABA-enhancing activity; additive CNS depression is theoretically possible.', 'Monitor for excess sedation; caution when combining.', 'Zhang et al., ''CNS Effects of Gastrodin,'' Frontiers in Pharmacology (2018); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1364', 'H274', 'drug_interaction', 'Antihypertensive drugs', 'moderate', 'Gastrodia lowers blood pressure via vasodilation; additive hypotension is theoretically possible.', 'Monitor blood pressure when combined with antihypertensives.', 'Pharmacology reviews (Wu et al., 2023); Brinker.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1365', 'H274', 'drug_interaction', 'Anticoagulant / antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Extracts inhibit platelet aggregation and are antithrombotic; theoretical additive bleeding risk.', 'Monitor for bleeding; consider discontinuing before surgery.', 'Kim et al., Medicina (2021), platelet aggregation/thrombosis; herb-drug interaction reviews.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1366', 'H274', 'condition', 'Blood-deficiency or yin-deficiency wind (TCM)', 'moderate', 'The rhizome disperses without tonifying and can worsen wind that arises from an underlying deficiency.', 'Use only in combination with blood/yin tonics; not as a standalone.', 'Bensky, Clavey & Stoger, Materia Medica (3rd ed.); Ben Jing Feng Yuan.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1367', 'H274', 'other', 'Gastrodia hypersensitivity; high-dose use (over ~40 g)', 'absolute', 'Allergic skin rash has been reported; excessive dosing can cause chest tightness, dizziness, nausea, and skin eruptions.', 'Contraindicated in known allergy; discontinue if rash develops; do not exceed the therapeutic dose.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Acupuncture Today materia medica.');
