INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H275', 'C06', 'Indicated', 'Primary', 'Cools and moistens the hot, dry deficiency-heat (Pitta-like) picture: night sweats, dry eyes.', '{"title": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE) - Nu Zhen Shi (\u5973\u8c9e\u5be6, privet fruit), listed in the superior/upper class of longevity tonics.", "locator": "Shennong Ben Cao Jing (Divine Farmer''s Materia Medica, c. 200 CE) - Nu Zhen Shi (\u5973\u8c9e\u5be6, privet fruit), listed in the superior/upper class of longevity tonics.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Nu Zhen Zi / Ligustri Fructus); Chen & Chen, Chinese Medical Herbology and Pharmacology; Memorial Sloan Kettering ''About Herbs: Ligustrum lucidum''; Pang et al. (2015", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Nu Zhen Zi / Ligustri Fructus); Chen & Chen, Chinese Medical Herbology and Pharmacology; Memorial Sloan Kettering ''About Herbs: Ligustrum lucidum''; Pang et al. (2015", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
