INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1368', 'H275', 'pregnancy', 'Pregnancy', 'moderate', 'No abortifacient or blood-moving action in tradition, but modern reproductive-toxicity data are insufficient and safety is not established.', 'Use only under qualified practitioner supervision; avoid self-prescription. Some manufacturers precautionarily label it avoid in pregnancy.', 'AHPA Botanical Safety Handbook (specific rating not verifiable); NCCIH (no monograph).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1369', 'H275', 'breastfeeding', 'Breastfeeding', 'moderate', 'No lactation-specific safety or milk-transfer data available.', 'Avoid unless supervised by a qualified practitioner.', 'No modern lactation data located (AHPA/NCCIH silent).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1370', 'H275', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Documented hypoglycemic activity may additively lower blood glucose.', 'Monitor blood glucose; watch for hypoglycemia and adjust medication only with the prescriber.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology; American Dragon (J. Penner) Nu Zhen Zi monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1371', 'H275', 'condition', 'Spleen-deficiency cold / chronic diarrhea; yang deficiency', 'moderate', 'Cool, moistening, enriching nature burdens a weak, cold digestion and can provoke or worsen loose stools.', 'Avoid, or combine with warming, qi-tonifying, digestion-supporting herbs; reduce dose if stools loosen.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1372', 'H275', 'drug_interaction', 'Immunosuppressants (e.g., cyclosporine, transplant regimens)', 'moderate', 'Immunostimulatory/immunomodulatory action may theoretically oppose immunosuppressive therapy.', 'Avoid in transplant recipients or during immunosuppressive treatment without specialist oversight.', 'Memorial Sloan Kettering ''About Herbs: Ligustrum lucidum'' (immunomodulation); theoretical.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1373', 'H275', 'other', 'Privet (Ligustrum) hypersensitivity', 'low', 'Privet pollen and plant material are recognized aeroallergens; hypersensitivity reactions reported.', 'Avoid with known privet allergy.', 'Zhang et al. (2024) review, PMC11199554; Memorial Sloan Kettering ''About Herbs'' (hypersensitivity).');
