INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1374', 'H276', 'pregnancy', 'Pregnancy', 'moderate', 'Aromatic, warming, drying, mildly diaphoretic rhizome; theoretical fluid-depleting and dispersing effects with no controlled human pregnancy data.', 'Avoid unless prescribed and monitored by a qualified practitioner. Prefer Bai Zhu, the traditional Spleen-tonic used to secure pregnancy.', 'AHPA Botanical Safety Handbook, 2nd ed. (A. lancea); Bensky, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1375', 'H276', 'breastfeeding', 'Breastfeeding', 'moderate', 'No human lactation data; drying and aromatic constituents excreted status unknown.', 'Avoid during breastfeeding except under professional supervision.', 'AHPA Botanical Safety Handbook, 2nd ed.; practitioner references.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1376', 'H276', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Aqueous extract lowers fasting blood glucose and improves insulin sensitivity in animal models; additive hypoglycemia possible.', 'Monitor blood glucose; watch for hypoglycemia and adjust antidiabetic dosing with clinician oversight.', 'Atractylodes lancea metabolic-syndrome pharmacology studies (ScienceDirect review; PMC12482687).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1377', 'H276', 'drug_interaction', 'CYP3A4 and CYP1A2 substrates (narrow therapeutic index)', 'low', 'Chronic dosing of atractylodin and beta-eudesmol downregulates CYP3A4 and CYP1A2 expression/activity; acute in-vitro inhibition is weak.', 'Single-dose risk is low; use caution with prolonged concurrent use of NTI CYP3A4 substrates and monitor.', 'Modulatory effects of atractylodin and beta-eudesmol on human CYP450 enzymes (PMC10095747, 2023).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1378', 'H276', 'condition', 'Yin deficiency, interior heat, or dehydration', 'moderate', 'Acrid, warm, drying action injures body fluids and Yin, worsening dryness and empty heat.', 'Avoid, or use short-term at reduced dose combined with moistening/blood-nourishing herbs.', 'Bensky, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1379', 'H276', 'condition', 'Qi-deficient spontaneous sweating (Wei Qi weakness)', 'moderate', 'Diaphoretic action can aggravate fluid loss and sweating in exterior/qi deficiency.', 'Use Bai Zhu (sweat-arresting) instead of Cang Zhu in these patterns.', 'Bensky, Chinese Herbal Medicine: Materia Medica, 3rd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1380', 'H276', 'other', 'Asteraceae/Compositae allergy (ragweed, daisy, marigold, chrysanthemum)', 'moderate', 'Potential cross-reactive hypersensitivity within the Asteraceae family.', 'Avoid in patients with known Asteraceae-family allergy.', 'WebMD/RxList Atractylodes monograph (allergen cross-reactivity).');
