INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H277', 'Lily Bulb (Bai He)', 'Lilium lancifolium', 'Liliaceae', 'Bulb (dried fleshy bulb scales)', 'Sweet, Bitter', 'Cool', 'Moist', 'Dryness of the Lung and mucosa, Deficiency (Heart and Lung yin and fluid depletion), Atrophy (consumptive wasting with dry membranes), Excess Heat (deficiency-fire, lingering low-grade heat after febrile illness)', 'Cold (Spleen and Stomach deficiency-cold), Dampness (phlegm-damp accumulation), Phlegm (cold-phlegm or wind-cold cough), Torpor (weak, atonic digestion with loose stools)', 'Respiratory and Lungs (primary), Nervous (calms the spirit), Cardiovascular and Heart (clears Heart heat, settles palpitations), Digestive (nourishes Stomach yin)', 'Dry consumptive cough with scanty or blood-streaked sputum, chronic dry throat and hoarseness; lingering low-grade fever and night sweats after a febrile illness; restlessness, insomnia, anxiety, and emotional lability of Lily Bulb syndrome (Bai He Bing); grief and low mood in a depleted, over-heated nervous system; palpitations from Heart yin deficiency with heat', 'Hot-Dry-Depleted: the wrung-out, over-heated, yin-deficient phenotype. The thin, restless, grief-worn person who runs hot and dry after long stress or illness, with a dry unproductive cough and a mind that will not settle at night. Aggravates cold, damp, boggy, phlegmatic constitutions.', 'Pitta, Vata', 'Kapha', 'Lung yin deficiency with dry cough; combined Lung and Heart yin deficiency with deficiency-heat (the classic Bai He Bing picture of restlessness, insomnia, and disorientation lingering after a febrile disease); Heart heat disturbing the shen; Stomach yin deficiency', 'Wind-Cold cough with thin white phlegm; Dampness and cold-Phlegm patterns; Spleen and Stomach deficiency-cold with diarrhea or loose stools', 'Cool and cloying: can burden a weak, cold, damp digestion and provoke loose stools. Do not use to suppress an acute wind-cold or phlegm-damp cough, where the moistening, cooling action can trap the pathogen. Mildly sedative, so it can add to drowsiness. Culinary amounts of the food-grade bulb are broadly safe.', 'Spleen and Stomach deficiency-cold with diarrhea or loose stools; acute wind-cold or cold-phlegm cough; damp-phlegm accumulation. Discontinue if it causes loose stools or chilliness.', 'The bulb has a long history of dietary use and culinary and food amounts are generally considered acceptable. Some secondary TCM safety sources note a possible teratogenic effect at high doses in animal studies, so concentrated high-dose medicinal preparations should be avoided in pregnancy; keep to food amounts. Not documented as a classical abortifacient or emmenagogue. (Traditional food-use record; TCM materia medica and Me&Qi safety database. AHPA-specific rating not confirmed: see flags.)', 'No documented concerns; considered safe at food and standard supportive doses given the bulb''s food-grade status. Formal lactation data are limited, so favor culinary and standard decoction amounts. (Traditional food-use record; TCM materia medica.)', 'Food-grade and commonly eaten (fresh or dried bulb in congee and soups). Considered safe for children at culinary and standard supportive doses; a gentle moistening herb used in TCM pediatric practice for dry, heat-type cough.', 'Documented pharmacological potentiation of central nervous system depressants: Bai He prolongs the sleeping time induced by barbiturates, benzodiazepines, antihistamines, and narcotic (opioid) analgesics, an additive sedative effect. Monitor for excess drowsiness and caution when driving or operating machinery if combined with sedative-hypnotics or other CNS depressants. Immunomodulating Lilium polysaccharides give a theoretical caution alongside immunosuppressant therapy. No other well-documented interactions at food or standard doses; overall data are limited. (Chinese pharmacological studies via American Dragon; Sacred Lotus TCM database; Lilium pharmacology reviews.)', 'Decoction of dried bulb scales (classic), added to congee and soups as food therapy, syrup for dry cough, tincture, powder. Fresh or dried fleshy bulb scales are used.', 'Decoction: 9-30 g per day (commonly 10-15 g), up to 30 g. Tincture (1:5): 2-5 mL up to 3x daily. Food therapy: 15-30 g fresh bulb simmered in congee or soup. Use the higher range for consumptive dry cough and Bai He Bing restlessness.', 'Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang Tang', 'Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baihe/Lilii Bulbus (PMID 31872612); Sacred Lotus, American Dragon, and Me&Qi TCM databases (safety and interactions)', 'Bai He means hundred meetings or hundred united, a reference to the many fleshy scales pressed together in the bulb. The Chinese Pharmacopoeia recognizes several official species as source of Bai He: Lilium lancifolium (= L. tigrinum), Lilium brownii var. viridulum, and Lilium pumilum; recent textual research (PMID 31872612) argues L. brownii var. viridulum is the historically authentic medicinal lily. Constituents include steroidal saponins, Lilium polysaccharides (immunomodulating, sedative, anti-inflammatory), flavonoids, phenylpropanoid glycerides (regalosides, linked to antidepressant and sedative activity), and steroidal alkaloids. A 2026 LC-MS screen of five Lilium species found no colchicine or its precursors, dispelling an older concern that lily bulbs contain colchicine. Signature formulas: Bai He Gu Jin Tang (moistens Lung, nourishes yin) and Zhang Zhongjing''s Bai He Di Huang Tang for Lily Bulb syndrome.', 'The lily is named in Scripture (Song of Solomon 2:1-2, ''the lily of the valleys'' and ''as the lily among thorns''; Matthew 6:28 and Luke 12:27, ''consider the lilies of the field''), but the biblical lily (Hebrew shoshannah) is a Mediterranean flower, not this East Asian medicinal species. Medicinal Bai He is a Chinese herb first recorded in the Shennong Ben Cao Jing (c. 200 CE); it belongs to the Chinese, not the biblical, materia medica.', 'Widely cultivated across China (notably Hunan, Gansu, and Jiangsu) as both a food crop and a medicinal; not listed as at-risk. Prefer cultivated, food-grade bulbs. Important pet-safety warning: Lilium species are acutely nephrotoxic to cats, and even small ingestion of any plant part is a veterinary emergency, so keep bulbs and plants well away from cats.', 'Cool, moist, sweet yin tonic: the quiet moistener that soothes a dry, heat-frayed Lung and settles a grieving, restless spirit back into stillness.', 'T1 to T2. Refer if: cough brings up significant blood (hemoptysis); persistent fever, drenching night sweats, and weight loss (rule out tuberculosis or malignancy); cough lasting more than 2 to 3 weeks; severe or worsening breathlessness; persistent insomnia, agitation, or depression that does not settle, or any suicidal ideation accompanying the grief and low mood.', 'LIL-ee bulb (bye-HUH); LIL-ee-um lan-sih-FOH-lee-um', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
