INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H277', 'TCM03', 'Secondary', 'Cold and cloying aggravates Spleen qi deficiency with diarrhea', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1381', 'H277', 'condition', 'Spleen and Stomach deficiency-cold with diarrhea or loose stools', 'moderate', 'Bai He is cool, moist, and cloying; it burdens a weak, cold, damp digestion and can provoke or worsen loose stools.', 'Avoid in deficiency-cold digestion with diarrhea, or combine with warming, drying, digestive herbs and keep doses low.', 'Bensky, Chinese Herbal Medicine: Materia Medica (3rd ed, 2004); Sacred Lotus and Me&Qi TCM databases');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1382', 'H277', 'condition', 'Acute wind-cold or cold-phlegm cough', 'moderate', 'The cool, moistening action is inappropriate for an external cold pattern and can trap the pathogen and thicken retained phlegm.', 'Reserve for dry, heat-type, or yin-deficiency cough; do not use to suppress an acute wind-cold or damp-phlegm cough.', 'Bensky, Chinese Herbal Medicine: Materia Medica (3rd ed, 2004); American Dragon TCM database');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1383', 'H277', 'drug_interaction', 'CNS depressants and sedative-hypnotics (barbiturates, benzodiazepines, antihistamines, opioid analgesics)', 'moderate', 'Bai He prolongs drug-induced sleeping time, an additive sedative effect on the central nervous system.', 'Monitor for excess drowsiness and sedation; caution with driving or operating machinery when combined with sedative-hypnotics or other CNS depressants.', 'Chinese pharmacological studies via American Dragon TCM database; Sacred Lotus TCM database');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1384', 'H277', 'pregnancy', 'Pregnancy (concentrated high-dose medicinal use)', 'moderate', 'Food amounts have a long safe-use record, but a secondary safety source reports a possible teratogenic effect at high doses in animal studies, and concentrated dosing is not well studied.', 'Limit to culinary and food amounts during pregnancy; avoid concentrated high-dose extracts and decoctions.', 'Me&Qi TCM safety database; traditional food-use record');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1385', 'H277', 'drug_interaction', 'Immunosuppressant therapy', 'low', 'Immunomodulating Lilium polysaccharides enhance T-cell function and could theoretically oppose immunosuppression.', 'Use concentrated preparations only under practitioner guidance in patients on immunosuppressant drugs.', 'Lilium spp. pharmacology reviews (Frontiers in Pharmacology 2025, PMC12682905; PMC11434738)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H277', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Bai He (Bulbus Lilii); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 220 CE): the Bai He Bing (Lily Bulb syndrome) chapter and Bai He Di Huang", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica (3rd ed, 2004): Bai He; systematic pharmacology reviews of Lilium spp. (Frontiers in Pharmacology 2025, PMC12682905; Ph 2024 PMC11434738); herbal textual research on Baih", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null, "kind": "pubmed"}'::jsonb, true);
