INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H278', 'TCM11', 'Secondary', 'Warming; avoid in Heat and Fire', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Hou Po (Magnolia bark)", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Hou Po (Magnolia bark)", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004): Hou Po; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013): Magnolia officinalis (safety class 2b); Memorial Sloan Kettering Cancer Center", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004): Hou Po; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013): Magnolia officinalis (safety class 2b); Memorial Sloan Kettering Cancer Center", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1386', 'H278', 'pregnancy', 'Pregnancy', 'absolute', 'Strong qi-moving and downward-directing action; AHPA safety class 2b (not to be used during pregnancy). Traditional Chinese sources counsel caution or prohibition.', 'Avoid during pregnancy. Use only under specialist supervision if ever, which is not recommended.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013), class 2b; Bensky et al., Chinese Herbal Medicine: Materia Medica');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1387', 'H278', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data; CNS-active neolignans (honokiol, magnolol) distribute widely.', 'Avoid while breastfeeding; if used at all, only under practitioner supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1388', 'H278', 'drug_interaction', 'Sedatives and CNS depressants (benzodiazepines, barbiturates, sleep and anxiety medications, alcohol)', 'moderate', 'Honokiol and magnolol are positive allosteric modulators of GABA-A receptors, producing additive sedation, ataxia, and muscle relaxation.', 'Do not combine with sedative or hypnotic drugs or alcohol without supervision; caution with driving or machinery.', 'Memorial Sloan Kettering Integrative Medicine, Magnolia officinalis; magnolol/honokiol GABA-A modulation study (Neuropharmacology, 2012); WebMD/RxList');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1389', 'H278', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Magnolol and honokiol inhibit platelet aggregation via thromboxane formation and intracellular calcium mobilization, adding to bleeding risk.', 'Avoid concentrated extracts with anticoagulant or antiplatelet therapy; monitor for bruising or bleeding and stop before surgery.', '''Two antiplatelet agents from Magnolia officinalis'' (Thrombosis Research, 1988; PMID 3413728); Memorial Sloan Kettering Integrative Medicine');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1390', 'H278', 'drug_interaction', 'CYP450, UGT1A9, and P-glycoprotein substrates', 'moderate', 'Honokiol inhibits CYP1A2, 2C8, 2C9, and 2C19 and UGT1A9 in vitro and modulates P-glycoprotein, potentially raising or altering levels of co-administered drugs, including narrow-therapeutic-index agents.', 'Avoid concentrated extracts with sensitive substrates (for example warfarin, phenytoin, certain statins) unless monitored by a clinician.', 'Memorial Sloan Kettering Integrative Medicine, Magnolia officinalis');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1391', 'H278', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'low', 'Magnolol and honokiol lower blood glucose (PTP1B inhibition, enhanced insulin signaling), risking additive hypoglycemia at therapeutic extract doses.', 'Monitor blood glucose if combining magnolia extract with glucose-lowering medication.', 'Memorial Sloan Kettering Integrative Medicine, Magnolia officinalis');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1392', 'H278', 'drug_interaction', 'Neuromuscular blockers and general anesthesia', 'moderate', 'The bark contains the curariform isoquinoline alkaloid magnocurarine plus centrally muscle-relaxant neolignans; theoretical additive neuromuscular blockade and prolonged sedation.', 'Discontinue 1 to 2 weeks before scheduled surgery; disclose use to the anesthesiologist.', 'Constituent pharmacology (magnocurarine curariform alkaloid; magnolol/honokiol muscle relaxation); Memorial Sloan Kettering Integrative Medicine');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1393', 'H278', 'condition', 'Qi- and Yin-deficiency, debility, and dryness patterns', 'moderate', 'The bark is warm, drying, and strongly dispersing; it moves and consumes qi, so overuse can further deplete weak, dry, or deficient patients.', 'Use only with balancing tonic herbs in deficient constitutions, or avoid; not for prolonged solo use.', 'Bensky et al., Chinese Herbal Medicine: Materia Medica; traditional TCM caution');
