INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H278', 'EP08', 'match', 2, 1, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Hou Po (Magnolia bark)", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Hou Po (Magnolia bark)", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004): Hou Po; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013): Magnolia officinalis (safety class 2b); Memorial Sloan Kettering Cancer Center", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004): Hou Po; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013): Magnolia officinalis (safety class 2b); Memorial Sloan Kettering Cancer Center", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H279', 'Sweet Basil', 'Ocimum basilicum', 'Lamiaceae (Labiatae; the mint and dead-nettle family)', 'Leaf and flowering tops (the leafy tops, fresh or dried, gathered as the plant comes into flower in summer)', 'Pungent, Sweet', 'Warm', 'Dry', 'Tension and constriction of a nervous, spasmodic gut: the griping, gas, and cramping of wind-bound or nervous digestion, where a warm aromatic relaxant unknots the smooth muscle and lets trapped gas pass. Stagnation and cold torpor of a sluggish, chilly stomach with poor appetite and bloating after meals, which the carminative kindles and moves. A damp, boggy, cold-stomached terrain with belching and nausea. Also mild nervous tension surfacing as tension headache and a wound-up, windy constitution. A warming, dispersing aromatic for the cold, tense, gassy picture.', 'Excess heat and acute inflammation: hot, red, irritated, or ulcerated mucosa, burning reflux, or any frankly hot, feverish gut, which a warm pungent aromatic aggravates. Frank dryness and fluid depletion, since a warm, drying, dispersing aromatic used heavily can further parch a dry terrain. Wrong for the hot, dry, overstimulated picture; this is a remedy for cold tension, not for heat.', 'Digestive (primary): the carminative, antispasmodic, and stomach-settling action on gas, colic, nausea, and sluggish appetite. Nervous (secondary): a gentle aromatic nervine for nervous tension, nervous headache, and the mind-gut overlap of nervous dyspepsia. Respiratory (minor): a warm aromatic for head colds and catarrh, historically taken as a snuff. Reproductive (minor): a traditional galactagogue and, in concentrated essential-oil form, an emmenagogue (see cautions).', 'Flatulence, bloating, and griping wind; nausea and vomiting (an infusion of the fresh herb was the classic remedy that arrests vomiting and allays nausea); atonic, cold, and nervous dyspepsia with poor appetite; spasmodic, IBS-pattern gut cramping. Secondarily nervous tension and nervous (tension) headache, for which the dried leaf was taken as a snuff, and the early stages of a head cold.', 'Cold-Damp-Relaxed and Cold-Depleted (Vata-like) phenotypes: the chilly, gassy, nervous, easily-bloated digestion and the wound-up, windy, tension-prone nervous system. A warming, relaxing carminative for the cold, tense terrain. Aggravates hot, dry, robust choleric (Pitta-like) constitutions, in whom the warm pungency adds heat.', 'Vata, Kapha', 'Pitta (heating and pungent; and in excess its dryness and lightness can also unsettle Vata)', 'Known in Chinese medicine as Luo Le, a warm, acrid, aromatic herb that releases the exterior and disperses Wind-Cold (early head colds and chills), warms and moves the middle to relieve Qi stagnation with distension and pain, and aromatically transforms Damp while harmonizing the Stomach to settle nausea and poor appetite. Acrid, sweet, and warm, entering the Lung, Spleen, Stomach, and Large Intestine channels.', 'Heat and Fire patterns, Yin deficiency with heat, and dryness: the warm, drying, acrid nature is wrong for any hot or fluid-depleted picture and aggravates a red, inflamed, or parched terrain.', 'The dried leaf, tea, and culinary herb are gentle and broadly safe. The concern is the concentrated ESSENTIAL OIL: many basil oils, especially the exotic (tropical / Reunion) chemotype, are rich in estragole (methylchavicol), a compound that is genotoxic and carcinogenic in rodents at high doses. Reserve the essential oil for dilute external aromatic use, prefer a low-estragole (European / linalool-type) oil, and do not take it internally. Emmenagogue and abortifacient effects have been reported for the essential oil. Culinary and normal tea amounts do not carry these concerns.', 'No absolute contraindications at culinary and normal tea amounts (AHPA safety Class 1). Avoid concentrated medicinal doses and the internal essential oil in pregnancy and lactation (estragole; see safety fields). Caution with the estragole-rich exotic essential oil in anyone, and with internal essential-oil use generally.', 'Culinary and food amounts are considered safe (basil is GRAS as a food; the AHPA Botanical Safety Handbook classes the herb as safety Class 1). Avoid concentrated medicinal doses and the essential oil during pregnancy: basil oil is frequently high in estragole (methylchavicol), a genotoxic rodent carcinogen, and reproductive-toxicity, uterine-stimulant, emmenagogue, and abortifacient effects have been reported for the essential oil; Tisserand and Young advise avoiding basil oil (estragole chemotype) throughout pregnancy. Keep to food and normal tea amounts. Sources: Tisserand & Young, Essential Oil Safety (2nd ed., 2014); AHPA Botanical Safety Handbook (2nd ed., 2013); Natural Medicines / Drugs.com (Sweet Basil).', 'Culinary and food amounts are considered safe and are traditionally used (basil has a folk reputation as a galactagogue). Avoid concentrated medicinal doses and the essential oil while nursing, as standard guidance restricts medicinal basil during lactation because of its estragole content. Keep to food and tea amounts. Sources: LactMed-aligned guidance (medicinal doses cautioned for estragole); AHPA Botanical Safety Handbook (2nd ed., 2013); Tisserand & Young, Essential Oil Safety (2nd ed.).', 'Culinary and tea amounts are safe and commonly enjoyed. Do not use the essential oil internally in children, and avoid it near the face of infants and toddlers (estragole content and general aromatic-oil caution). Reserve concentrated preparations for older children under guidance. Sources: AHPA Botanical Safety Handbook (2nd ed.); Tisserand & Young, Essential Oil Safety (2nd ed.).', 'No well-documented, clinically significant interactions at culinary or normal tea amounts (limited human data). Theoretical additive effects apply only to concentrated medicinal or essential-oil doses: mild blood-sugar lowering (additive with insulin and oral hypoglycemics), mild blood-pressure lowering (additive with antihypertensives), and possible antiplatelet activity (additive with anticoagulant or antiplatelet drugs). In vitro, Ocimum basilicum extract has inhibited CYP2B6 and CYP3A4, a theoretical basis for interaction with drugs cleared by those enzymes if high hepatic concentrations were reached, though clinical relevance at dietary intake is unproven. Culinary use is unproblematic. Sources: Natural Medicines / Drugs.com (Sweet Basil); in vitro CYP2B6/CYP3A4 study (PMC7204527, 2020); Mills & Bone, Principles and Practice of Phytotherapy.', 'Infusion (tea) of the fresh or dried leaf; the fresh herb and leaf as a culinary seasoning (pesto, salads, sauces, soups); tincture of the leaf; dried powdered leaf (historically taken as a snuff for nervous headache and head colds); poultice of bruised fresh leaf or seed (traditional, on insect stings). Essential oil for dilute external aromatic use only, not internal, preferring a low-estragole chemotype.', 'Dried leaf infusion: 1 to 2 teaspoons (about 2 to 4 g) per cup, steeped covered, up to 3x daily. Tincture (1:5, 40 percent): about 2 to 4 mL up to 3x daily. Fresh culinary herb: to taste, ad libitum. Essential oil: external and well diluted only (a low-estragole basil oil kept to roughly 1.5 percent or less in a carrier), never internal, and avoid the estragole-rich exotic (tropical / Reunion) oil. Steep the tea covered to retain the volatile aromatic oil that carries the action.', 'Grieve''s A Modern Herbal (1931) - Basil (Sweet and Bush); Culpeper, The Complete Herbal / English Physician (1653) - Basil.', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013; Ocimum basilicum reclassified to safety Class 1); Tisserand & Young, Essential Oil Safety, 2nd ed. (2014); Natural Medicines / Drugs.com (Sweet Basil monograph); Mills & Bone, Principles and Practice of Phytotherapy; Ocimum basilicum review (PMC10748370, 2023); in vitro CYP2B6/CYP3A4 interaction study (PMC7204527, 2020).', 'Family Lamiaceae. Sweet basil''s activity rides on its volatile oil, whose composition varies by chemotype: European culinary types are linalool-rich (with 1,8-cineole and eugenol), while exotic / tropical (Reunion) types are dominated by estragole (methylchavicol), the constituent behind the essential-oil safety caution; methyl-cinnamate and eugenol chemotypes also exist. This is CULINARY sweet basil, not Holy Basil / Tulsi (Ocimum tenuiflorum, syn. O. sanctum): the two are distinct species with different profiles, and the adaptogenic, blood-sugar, and sacred-Hindu associations belong properly to Tulsi. Grieve''s own entry blends the two traditions. Sweet basil''s documented pharmacology (antispasmodic, carminative, antimicrobial, antioxidant, mild hypoglycemic) supports its long culinary-medicinal use as a warm digestive aromatic and gentle nervine.', 'Not named in the canonical biblical texts. The common name descends from the Greek basilikon (from basileus, king), the royal or kingly herb. In Eastern Orthodox Christian tradition basil is linked to the finding of the True Cross by St. Helena and is used to sprinkle holy water at the Feast of the Exaltation of the Cross. Native to tropical Asia and Africa and long naturalized around the Mediterranean. The sacred Hindu basil cherished in temple courtyards is properly Tulsi (Holy Basil, Ocimum tenuiflorum), a different species, though older herbals such as Grieve''s conflate the two.', 'A fast-growing, easily cultivated annual and one of the most widely grown culinary herbs worldwide, so it is not at risk and does not appear on the United Plant Savers at-risk or to-watch lists. Home-grown or organically cultivated leaf is preferable for potency and to avoid pesticide residue on a herb usually eaten fresh.', 'Warm, dry, sweet-pungent aromatic: the kitchen carminative and gentle nervine that unknots a tense, gassy, cold-stomached gut, settles nausea, and eases nervous tension.', 'T1 Self-Care for culinary and tea use. Refer if: persistent or projectile vomiting, blood in vomit or stool, severe or unremitting abdominal pain, difficulty swallowing, unexplained weight loss, or dyspepsia lasting more than 2 weeks (rule out ulcer or malignancy); severe or worsening headache with neurological signs; and any pregnancy, where concentrated or essential-oil basil should be avoided and questions directed to the prenatal provider.', 'Sweet Basil: BAY-zuhl (also BAZ-uhl). Ocimum basilicum: OSS-ih-mum bah-ZIL-ih-kum.', 'free', 'Approved', '{"title": "Grieve''s A Modern Herbal (1931) - Basil (Sweet and Bush); Culpeper, The Complete Herbal / English Physician (1653) - Basil.", "locator": "Grieve''s A Modern Herbal (1931) - Basil (Sweet and Bush); Culpeper, The Complete Herbal / English Physician (1653) - Basil.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013; Ocimum basilicum reclassified to safety Class 1); Tisserand & Young, Essential Oil Safety, 2nd ed. (2014); Natural Medicines / Drugs.com (Sweet Basil monograph); Mills & Bon", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013; Ocimum basilicum reclassified to safety Class 1); Tisserand & Young, Essential Oil Safety, 2nd ed. (2014); Natural Medicines / Drugs.com (Sweet Basil monograph); Mills & Bon", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
