INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H279', 'C04', 'Indicated', 'Primary', 'Cold-damp phlegmatic digestion; gassy, sluggish, chilly stomach.', '{"title": "Grieve''s A Modern Herbal (1931) - Basil (Sweet and Bush); Culpeper, The Complete Herbal / English Physician (1653) - Basil.", "locator": "Grieve''s A Modern Herbal (1931) - Basil (Sweet and Bush); Culpeper, The Complete Herbal / English Physician (1653) - Basil.", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013; Ocimum basilicum reclassified to safety Class 1); Tisserand & Young, Essential Oil Safety, 2nd ed. (2014); Natural Medicines / Drugs.com (Sweet Basil monograph); Mills & Bon", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013; Ocimum basilicum reclassified to safety Class 1); Tisserand & Young, Essential Oil Safety, 2nd ed. (2014); Natural Medicines / Drugs.com (Sweet Basil monograph); Mills & Bon", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
