INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1394', 'H279', 'pregnancy', 'Pregnancy (essential oil and concentrated medicinal doses)', 'moderate', 'Basil essential oil is frequently high in estragole (methylchavicol), a genotoxic rodent carcinogen; reproductive-toxicity, uterine-stimulant, emmenagogue, and abortifacient effects have been reported for the oil. Culinary and food amounts have a long record of safe use (GRAS; AHPA Class 1).', 'Limit to culinary and normal tea amounts during pregnancy; avoid the essential oil and concentrated extracts.', 'Tisserand & Young, Essential Oil Safety (2nd ed., 2014); AHPA Botanical Safety Handbook (2nd ed., 2013); Natural Medicines / Drugs.com (Sweet Basil).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1395', 'H279', 'breastfeeding', 'Breastfeeding (essential oil and concentrated medicinal doses)', 'moderate', 'Standard guidance restricts medicinal-dose basil during lactation because of its estragole content; culinary amounts are considered compatible and are traditionally used.', 'Keep to food and tea amounts while nursing; avoid the essential oil and concentrated extracts.', 'LactMed-aligned guidance (medicinal doses cautioned for estragole); AHPA Botanical Safety Handbook (2nd ed., 2013); Tisserand & Young, Essential Oil Safety (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1396', 'H279', 'drug_interaction', 'Antidiabetic / hypoglycemic drugs (insulin, sulfonylureas, metformin)', 'low', 'Basil has shown mild blood-sugar-lowering activity in vitro and in animal studies; theoretical additive hypoglycemic effect at concentrated medicinal doses only.', 'Culinary use is unproblematic; monitor blood glucose if taking medicinal-dose basil preparations with antidiabetic drugs.', 'Natural Medicines / Drugs.com (Sweet Basil); Ocimum basilicum antidiabetic studies.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1397', 'H279', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'Possible antiplatelet activity reported for Ocimum species; theoretical additive bleeding risk at concentrated medicinal doses only.', 'Culinary use is unproblematic; monitor if combining concentrated basil preparations with anticoagulant or antiplatelet drugs.', 'Natural Medicines / Drugs.com (Sweet Basil); Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1398', 'H279', 'drug_interaction', 'CYP3A4 and CYP2B6 substrates (narrow-therapeutic-index drugs)', 'low', 'Ocimum basilicum extract inhibited CYP2B6 and CYP3A4 in vitro, a theoretical basis for altered clearance of drugs metabolized by these enzymes if high hepatic concentrations were reached; clinical relevance at dietary intake is unproven.', 'No action needed at culinary intake; consider theoretical interaction only with concentrated extracts and narrow-therapeutic-index medicines.', 'In vitro CYP2B6/CYP3A4 interaction study (PMC7204527, 2020).');
