INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H280', 'TCM07', 'Primary', 'Yin deficiency with dry cough, deficiency fire, or hemoptysis', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, Han dynasty, c. 200 CE): Jie Geng (Platycodon), recorded as a middle-grade herb for chest and rib pain, abdominal fullness, and cough.", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, Han dynasty, c. 200 CE): Jie Geng (Platycodon), recorded as a middle-grade herb for chest and rib pain, abdominal fullness, and cough.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Eastland Press, 2004): Jie Geng. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013). Zhao et al., ''The Pharmacological Effects and Health Benefits of", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Eastland Press, 2004): Jie Geng. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013). Zhao et al., ''The Pharmacological Effects and Health Benefits of", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1399', 'H280', 'other', 'Yin-deficient dry cough or hemoptysis (coughing/spitting blood)', 'moderate', 'The dispersing, drying, upward-diffusing action aggravates dryness and can worsen bleeding in yin-deficient (deficiency-fire) patterns.', 'Avoid in dry unproductive cough and in coughing or spitting of blood. If used in yin-deficient presentations, combine with yin-nourishing herbs.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Eastland Press, 2004); classical TCM contraindication.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1400', 'H280', 'other', 'High oral doses', 'moderate', 'Triterpenoid saponins irritate the gastric mucosa and trigger a vagal reflex, producing nausea and vomiting.', 'Keep to 3-10 g/day decoction (or equivalent). Overdose is emetic; reduce dose if nausea occurs.', 'Chen & Chen, Chinese Medical Herbology and Pharmacology; AHPA Botanical Safety Handbook, 2nd ed. (2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1401', 'H280', 'other', 'Parenteral / intravenous use', 'absolute', 'Platycodin saponins (notably platycodin D) are hemolytic when introduced into the bloodstream.', 'Oral use only. Never inject or use parenterally.', 'Pharmacology reviews of platycodin D hemolytic activity (Front. Pharmacol. 2023, PMC10117678).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1402', 'H280', 'pregnancy', 'Pregnancy (concentrated/high therapeutic doses)', 'moderate', 'No dedicated human safety data; not an emmenagogue/abortifacient. Food-homology use suggests low risk at dietary levels.', 'Culinary amounts acceptable; avoid concentrated extracts and high therapeutic doses without practitioner supervision.', 'AHPA Botanical Safety Handbook, 2nd ed. (2013); limited data.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1403', 'H280', 'breastfeeding', 'Breastfeeding (concentrated preparations)', 'low', 'No lactation-specific data; traditional food use during and after pregnancy in Korea.', 'Culinary use appears low-risk; use caution with concentrated extracts.', 'Limited data; food-homology traditional use.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1404', 'H280', 'drug_interaction', 'Antihypertensive and hypoglycemic/lipid-lowering drugs', 'low', 'Platycodin saponins show mild blood-pressure lowering and glucose/triglyceride lowering; theoretical additive effect.', 'Monitor blood pressure and blood glucose/lipids if combined with these medications.', 'Pharmacology reviews (Foods 2020, PMC7073691); theoretical/limited clinical data.');
