INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H280', 'EP08', 'neutral', 1, 1, 'moisture: herb dry rebalances the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, Han dynasty, c. 200 CE): Jie Geng (Platycodon), recorded as a middle-grade herb for chest and rib pain, abdominal fullness, and cough.", "locator": "Shennong Ben Cao Jing (Shen Nong''s Classic of Materia Medica, Han dynasty, c. 200 CE): Jie Geng (Platycodon), recorded as a middle-grade herb for chest and rib pain, abdominal fullness, and cough.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Eastland Press, 2004): Jie Geng. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013). Zhao et al., ''The Pharmacological Effects and Health Benefits of", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (Eastland Press, 2004): Jie Geng. AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013). Zhao et al., ''The Pharmacological Effects and Health Benefits of", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H281', 'Siler / Saposhnikovia (Fang Feng)', 'Saposhnikovia divaricata', 'Apiaceae (Umbelliferae)', 'Root (dried; Radix Saposhnikoviae)', 'Pungent, Sweet', 'Warm', 'Neutral', 'Wind (external and internal), Cold (wind-cold at the surface), Dampness (wind-damp painful obstruction), Tension and Constriction (spasm, tetany, tremor), Stagnation (obstructed channels); minor Wei Qi Weakness (leaky, wind-susceptible exterior).', 'Dryness and fluid depletion, Excess Heat and yin-deficient heat, Deficiency (blood- or yin-deficiency generating internal wind); exhaustion states where further dispersal drains reserves.', 'Respiratory and Immune (exterior release, defensive qi, allergy), Musculoskeletal (wind-damp bi, spasm), Integumentary/Skin (wind rash, itch), Nervous (antispasmodic, tremor), Digestive/Spleen (Liver-Spleen harmonizing, painful diarrhea). TCM channels: Urinary Bladder, Liver, Spleen (also Lung).', 'Wind-cold and wind-heat common cold with headache and body aches; wind-damp painful obstruction (migratory, achy joint and muscle pain, arthritis); wind on the skin (urticaria, eczema, itching, allergic rash); allergic rhinitis and hay fever; spasm, tremor and tetany; Liver-overacting-on-Spleen painful diarrhea and IBS; recurrent colds with weak defensive qi (Jade Windscreen).', 'Cold-Damp and wind-invaded phenotypes: the person who takes wind and damp into the surface and channels, with migratory achy joints, wind-rash and itch, or a weak, leaky exterior that catches every cold. Also suits the wind-driven, spasmodic, tremulous picture. Aggravates hot, dry, yin-deficient (choleric/Pitta) constitutions and internal wind that arises from blood or yin deficiency rather than from an external pathogen.', 'Kapha, Vata', 'Pitta (warm, acrid; in heat or excess)', 'Wind-Cold (and, in combination, Wind-Heat) invading the exterior; Wind-Damp painful obstruction (bi); wind on the skin with itch; internal wind with spasm and tremor; Liver overacting on the Spleen (painful diarrhea, Tong Xie Yao Fang); weak defensive (wei) qi with spontaneous sweating and recurrent colds (Yu Ping Feng San, Jade Windscreen).', 'Yin deficiency with heat (night sweats, hot flushes); blood deficiency generating internal wind; Liver-yang rising and true interior wind (wind-stroke, convulsions) not from an external pathogen; headache or diarrhea not due to wind, cold or damp.', 'A practitioner-directed herb, not a self-care staple. Its warm, acrid, dispersing nature can deplete fluids: use with care in dryness, heat, and yin or blood deficiency. Contains photosensitising furanocoumarins (psoralen, bergapten); theoretical caution with strong sun/UV exposure or phototherapy at high or prolonged doses. Distinguish exterior and wind-damp patterns (where it helps) from deficiency wind (where it is contraindicated).', 'Blood-deficiency spasm or convulsion and yin-deficiency heat; interior wind (wind-stroke, seizures) not from an external pathogen; headache or diarrhea unrelated to wind, cold or damp. Known allergy to the carrot/celery family (Apiaceae).', 'No modern human safety studies establish a clear verdict, and published sources disagree (some contraindicate in pregnancy, others consider standard doses acceptable). Classical Chinese texts caution against Fang Feng in blood-deficiency and postpartum wind rather than in ordinary pregnancy, and animal toxicology of the water extract shows very low toxicity with no clear reproductive signal (rat NOAEL 5,000 mg/kg/day). Prudent guidance: avoid unsupervised use; take only within a practitioner-formulated prescription and avoid high or prolonged dosing. (Bensky et al. 2004; Saposhnikoviae Radix toxicology, PMC6791657, 2019.) NEEDS REVIEW: sources conflict on a blanket pregnancy prohibition; confirm against AHPA Botanical Safety Handbook 2nd ed.', 'Modern lactation safety data are lacking. The water extract is of very low toxicity in animal studies, and the herb is not a documented galactagogue or lactifuge. Insufficient evidence for routine use; if used, keep to short, practitioner-guided courses. (Saposhnikoviae Radix toxicology, PMC6791657, 2019.) NEEDS REVIEW: no dedicated lactation reference located.', 'Traditionally included in age-reduced doses within professionally formulated decoctions; the water extract shows very low toxicity in animal studies (rat NOAEL 5,000 mg/kg/day). Not for unsupervised pediatric self-care; use only under a qualified practitioner. (Bensky et al. 2004; Saposhnikoviae Radix toxicology, PMC6791657.)', 'No well-documented clinical drug interactions (limited human data). Mechanistic cautions only: the root''s coumarins (imperatorin) and furanocoumarins (psoralen, bergapten) show anticoagulant/antiplatelet and CYP-modulating activity in vitro, giving a theoretical additive bleeding risk with warfarin and antiplatelet drugs, a theoretical interaction with CYP3A4-metabolised narrow-therapeutic-index drugs, and possible additive photosensitivity with photosensitising medication or UV therapy. Clinical relevance at normal decoction doses is unestablished. (Chinese Journal of Integrative Medicine phytochemistry/pharmacology reviews 2020, 2023; natural-coumarin review PMC8440074, 2021; oral-anticoagulant and medicinal-plant review, Pharmacy/MDPI 2025.)', 'Decoction of the dried root (standard TCM method, usually within a formula); powder for pill and powder formulas (San); Western tincture; occasionally dry-fried (chao, favouring the diarrhea-stopping action) or charred (to stop bleeding). Classic formulas: Yu Ping Feng San (Jade Windscreen), Tong Xie Yao Fang, Chuan Xiong Cha Tiao San, Xiao Feng San.', 'Decoction: 4.5-9 g dried root daily (up to 10 g; 15-30 g for acute wind-damp under practitioner supervision). Tincture (1:5): 2-4 mL up to 3x daily. Usually combined in formula rather than used alone; short courses for acute exterior and wind patterns.', 'Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Fang Feng (防风), listed among the superior-class herbs for wind, headache, dizziness, wind-damp and joint pain.', 'Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed (2004): Fang Feng; Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2019); Saposhnikovia divaricata ethnopharmacology, phytochemistry and pharmacology reviews, Chinese Journal of Integrative Medicine (2020, 2023).', 'Fang Feng (防风, ''guard against wind''), the dried root of Saposhnikovia divaricata (Turcz.) Schischk., family Apiaceae, formerly placed in the genus Ledebouriella (L. seseloides / L. divaricata). A foundational exterior-releasing herb of Chinese medicine, prized as the ''moistening agent among the wind herbs'' for expelling wind without harshly drying. Active constituents include chromones (prim-O-glucosylcimifugin, cimifugin, 4''-O-beta-D-glucosyl-5-O-methylvisamminol), coumarins and furanocoumarins (imperatorin, psoralen, bergapten, phellopterin, anomalin, nodakenin), polyacetylenes (falcarindiol/panaxynol), polysaccharides and volatile oil. Modern pharmacology documents antipyretic, analgesic, anti-inflammatory, antihistaminic/anti-allergic, antioxidant and immunomodulatory activity, with very low toxicity. Signature formulas: Yu Ping Feng San (with Huang Qi and Bai Zhu) to stabilise the exterior in recurrent colds and allergy; Tong Xie Yao Fang (with Bai Zhu, Bai Shao, Chen Pi) for Liver-Spleen painful diarrhea/IBS; Chuan Xiong Cha Tiao San for wind headache; Xiao Feng San for wind rash and itch.', 'Not named in the canonical biblical texts and not a Mediterranean plant. Native to northern China, Mongolia, Korea and eastern Siberia; a foundational herb of classical Chinese medicine, first recorded in the Shennong Ben Cao Jing (c. 200 CE) as Fang Feng, ''guard against wind.'' Formerly classified in the genus Ledebouriella.', 'Wild Saposhnikovia divaricata has been heavily wild-harvested across its native northern-Asian range, and demand has thinned wild stands in parts of China and Mongolia; roots are now widely cultivated (dug at 3-4 years). Not a North American United Plant Savers listing, but prefer cultivated or verified-sustainable root over wild-dug material to relieve pressure on wild populations.', 'Warm, dispersing and notably non-drying: the gentle ''guard against wind'' that opens the surface, drives out wind-cold and wind-damp, calms spasm and tremor, and quiets wind-borne itch without parching the fluids.', 'T3 Practitioner. Refer urgently for: high fever with stiff neck or photophobia (meningitis); true seizures, stroke signs or progressive neurological deficit; a hot, red, swollen joint with fever (septic or acute inflammatory arthritis); rapidly spreading hives with lip or tongue swelling, wheeze or throat tightness (anaphylaxis, call emergency services); rash with fever, blistering or skin peeling. Not for self-directed use in pregnancy or in yin/blood-deficiency patterns.', 'Fang Feng: fahng fung; Siler: SY-ler; Saposhnikovia divaricata: sap-osh-nih-KOH-vee-uh dih-var-ih-KAH-tuh.', 'seed', 'Approved', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Fang Feng (\u9632\u98ce), listed among the superior-class herbs for wind, headache, dizziness, wind-damp and joint pain.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Fang Feng (\u9632\u98ce), listed among the superior-class herbs for wind, headache, dizziness, wind-damp and joint pain.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed (2004): Fang Feng; Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed (2004): Fang Feng; Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
