INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H281', 'TCM11', 'Secondary', 'Avoid in Heat/Fire patterns', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Fang Feng (\u9632\u98ce), listed among the superior-class herbs for wind, headache, dizziness, wind-damp and joint pain.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Fang Feng (\u9632\u98ce), listed among the superior-class herbs for wind, headache, dizziness, wind-damp and joint pain.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed (2004): Fang Feng; Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2", "locator": "Bensky D, Clavey S, Stoger E. Chinese Herbal Medicine: Materia Medica, 3rd ed (2004): Fang Feng; Chen JK, Chen TT. Chinese Medical Herbology and Pharmacology (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1405', 'H281', 'condition', 'Yin-deficiency heat and blood-deficiency internal wind', 'moderate', 'The warm, acrid, dispersing action depletes fluids and can aggravate internal wind arising from yin or blood deficiency rather than from an external pathogen.', 'Avoid in night sweats, hot flushes and tremor of deficiency; reserve for genuine exterior or wind-damp patterns.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1406', 'H281', 'condition', 'Interior wind not from an external pathogen (Liver-yang rising, wind-stroke, convulsions)', 'moderate', 'Fang Feng targets external and wind-damp wind; it does not address true interior wind and may be inappropriate or delay proper care.', 'Differentiate the pattern before use; refer neurological presentations for evaluation.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1407', 'H281', 'pregnancy', 'Pregnancy', 'moderate', 'No modern human safety data; classical sources caution in blood-deficiency and postpartum wind. Animal toxicology of the water extract shows very low toxicity with no clear reproductive signal.', 'Use only within a qualified practitioner''s prescription; avoid high or prolonged dosing and unsupervised self-use.', 'Bensky et al. (2004); Saposhnikoviae Radix water-extract toxicological evaluation (PMC6791657, 2019).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1408', 'H281', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'Coumarin and furanocoumarin constituents (imperatorin, psoralen, bergapten) show anticoagulant/antiplatelet activity in vitro; theoretical additive bleeding risk.', 'Use caution with concentrated preparations in anticoagulated patients and monitor; short decoction courses are likely low risk.', 'Chinese Journal of Integrative Medicine phytochemistry/pharmacology reviews (2020, 2023); oral-anticoagulant and medicinal-plant review, Pharmacy/MDPI (2025).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1409', 'H281', 'drug_interaction', 'Photosensitising drugs, UV/PUVA phototherapy, and CYP3A4 substrates', 'low', 'Furanocoumarins (psoralen, bergapten) are photosensitisers and known CYP modulators; theoretical additive photosensitivity and altered metabolism of CYP3A4 narrow-therapeutic-index drugs at high or prolonged doses.', 'Advise sun protection with high-dose or prolonged use; use caution alongside photosensitising medication and critical CYP3A4 substrates.', 'Natural coumarins pharmacology review (PMC8440074, 2021).');
