INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H282', 'Tree Peony Bark / Moutan (Mu Dan Pi)', 'Paeonia suffruticosa Andr.', 'Paeoniaceae', 'Root bark (Cortex Moutan / Mu Dan Pi), the dried bark of the root; pharmacopeial grade ''Feng Dan'' is farm-grown in Anhui.', 'Bitter, Pungent (acrid)', 'Cool', 'Neutral', 'Excess heat at the blood level, blood stasis and stagnation, heat-driven inflammation and abscess, and excitation of the blood (reckless bleeding, restlessness, night fever).', 'Cold and yang/qi deficiency with loose stools, blood deficiency without stasis, and yin deficiency with profuse spontaneous sweating (the acrid, dispersing quality worsens the sweat).', 'Cardiovascular (blood, Heart channel), Hepatic/Liver (Liver fire, Liver channel), Reproductive (gynecological blood stasis), Integumentary (blood-heat rashes and sores), with Kidney-channel action that clears deficiency heat.', 'Blood-heat fevers and warm-disease eruptions (maculae, papules), reckless bleeding from heat (epistaxis, hematemesis), yin-deficient steaming-bone and night fevers without sweat, blood-stasis dysmenorrhea and amenorrhea, abdominal masses and trauma, Liver-fire headache and red eyes, and early intestinal abscess.', 'Hot, robust, blood-congested: the choleric / Pitta-like phenotype with heat pressed into the blood, red rashes, night fevers, and stagnant painful menses. Wrong for the cold, pale, depleted, or loose-bowelled.', 'Pitta, Kapha', 'Vata', 'Heat entering the blood / nutritive (ying-xue) level in warm-febrile disease (fever worse at night, maculopapular rash, epistaxis, hematemesis); blood stasis (amenorrhea, dysmenorrhea, abdominal masses, trauma); yin-deficient heat with steaming bones and night fever without sweating; ascendant Liver fire (headache, red eyes); and early intestinal abscess (chang yong).', 'Cold-deficient Spleen/Stomach with diarrhea, blood deficiency without stasis, yin deficiency with copious spontaneous sweating, non-heat bleeding, and pregnancy.', 'Cold digestion and loose stools, blood deficiency without stasis, and heavy menstrual flow that is not due to blood heat or blood stasis. The antiplatelet action warrants caution around surgery and with blood-thinning drugs.', 'Pregnancy (blood-moving, emmenagogue). Yin deficiency with profuse sweating. Cold-deficiency diarrhea. Active bleeding disorders and the perioperative window (antiplatelet effect).', 'Contraindicated. TCM references uniformly forbid Mu Dan Pi in pregnancy because its blood-invigorating, stasis-dispelling action can stimulate the uterus and threaten the pregnancy. Avoid throughout gestation. (Bensky, Clavey & Stoger 2004; Chen & Chen 2004.)', 'NEEDS REVIEW: No human lactation data located (no LactMed entry). The recommendation is precautionary. Traditionally avoided during nursing given the blood-moving nature; use only under a qualified practitioner''s direction.', 'Used in classical pediatric formulas for blood-heat rashes and fevers at reduced, weight-adjusted doses under practitioner supervision. Not intended for unsupervised home use in infants or young children.', 'Theoretical additive bleeding risk with anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, direct oral anticoagulants): paeonol and paeoniflorin inhibit platelet aggregation and coagulation. Possible additive hypotension with antihypertensives (paeonol is mildly hypotensive and vasodilatory). No well-documented CYP-mediated interactions; data are limited. Discontinue 1 to 2 weeks before surgery.', 'Water decoction (standard TCM), tincture, powder, or capsule. Prepared raw to maximize blood-cooling, dry-fried (chao) to strengthen the blood-invigorating action, or charred (tan) to stop bleeding.', 'Decoction: 6 to 12 g dried root bark per day (up to 15 g in acute heat, practitioner-supervised). Tincture (1:5): 2 to 4 mL up to three times daily. Add near the end of the decoction to preserve the volatile paeonol.', 'Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Mu Dan (Moutan), listed among the middle-grade herbs; flavor acrid, qi cold; used for fevers, convulsions, and stagnant blood.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Mu Dan Pi; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Wang et al., ''Origins, Phytochemistry, Pharmacology, Analytical Methods and Safety of Cortex Moutan,'' Molecules 2017 (PMC6152737); Koo et al., ''Antithrombotic Effects of Paeoniflorin from Paeonia suffruticosa,'' Int J Mol Sci 2019 (PMC6834133).', 'The root bark of the tree peony, distinct from the herbaceous peony roots Bai Shao (white, Paeonia lactiflora) and Chi Shao (red). Among the peony family Mu Dan Pi is the strongest at cooling the blood and, uniquely, at clearing deficiency (yin-vacuity) heat, the ''steaming bone'' fever without sweat. Its signature is dual and balanced: it cools blood without congealing it and moves blood without provoking bleeding. Key constituents include the characteristic phenol paeonol, the monoterpene glycoside paeoniflorin, gallotannins, and trace benzoic acid (some 119 compounds catalogued). Paeonol drives anti-inflammatory (iNOS and COX-2 inhibition), antioxidant (Nrf2 activation), antipyretic, analgesic, and mild antiplatelet effects; paeoniflorin adds antithrombotic and anti-inflammatory action. Cornerstone of Liu Wei Di Huang Wan and Zhi Bai Di Huang Wan (yin-deficient heat), Gui Zhi Fu Ling Wan (blood stasis), and Dan Zhi Xiao Yao San (Liver heat). Classical teaching: do not combine with garlic.', 'Not in canonical biblical or Mediterranean texts. This is the Chinese tree peony, first recorded in the Shennong Ben Cao Jing (c. 200 CE) as Mu Dan among the middle-grade herbs. The peony of the classical Greco-Roman world (Paeonia officinalis, named for the healer Paion in Homer, and described by Dioscorides and Pliny) is a distinct European species and a different medicine from this Chinese root bark.', 'Paeonia suffruticosa is very widely cultivated across China as both an ornamental and a medicinal crop; medicinal ''Feng Dan'' is farm-grown, chiefly in Anhui. It is not a wild-at-risk species and does not appear on the United Plant Savers list (which tracks North American natives). Prefer cultivated, pharmacopeial-grade bark tested for heavy-metal (lead, cadmium) and pesticide residues.', 'Cool, dispersing, blood-clearing: it cools the blood that heat has scorched and breaks the stasis heat leaves behind, moving without provoking bleeding.', 'Refer urgently for heavy or uncontrolled bleeding (hematemesis, hemoptysis, large-volume epistaxis), high fever with a purpuric rash or altered consciousness (possible sepsis or meningococcemia), suspected pregnancy, or an acute abdomen (possible appendicitis or peritonitis). These are not self-treatment situations.', 'Mu Dan Pi (moo dahn pee); Tree Peony Bark. Latin Paeonia suffruticosa (pay-OH-nee-uh suf-roo-tih-KOH-suh).', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Mu Dan (Moutan), listed among the middle-grade herbs; flavor acrid, qi cold; used for fevers, convulsions, and stagnant blood.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Mu Dan (Moutan), listed among the middle-grade herbs; flavor acrid, qi cold; used for fevers, convulsions, and stagnant blood.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Mu Dan Pi; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Wang et al., ''Origins, Phytochemistry, Pharmacology, Analytical Methods and Safety ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Mu Dan Pi; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Wang et al., ''Origins, Phytochemistry, Pharmacology, Analytical Methods and Safety ", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
