INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H282', 'TCM01', 'Secondary', 'Kidney yang deficiency and cold patterns.', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Mu Dan (Moutan), listed among the middle-grade herbs; flavor acrid, qi cold; used for fevers, convulsions, and stagnant blood.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, Han dynasty, c. 200 CE), Mu Dan (Moutan), listed among the middle-grade herbs; flavor acrid, qi cold; used for fevers, convulsions, and stagnant blood.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Mu Dan Pi; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Wang et al., ''Origins, Phytochemistry, Pharmacology, Analytical Methods and Safety ", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004), Mu Dan Pi; Chen & Chen, Chinese Medical Herbology and Pharmacology (2004); Wang et al., ''Origins, Phytochemistry, Pharmacology, Analytical Methods and Safety ", "source_id": "S04", "author": "Bensky et al. \u2014 Chinese Herbal Medicine: Materia Medica", "year": "2004", "url": null}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1410', 'H282', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Blood-invigorating, stasis-dispelling (emmenagogue) action can stimulate the uterus and threaten the pregnancy.', 'Do not use during pregnancy.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Chen & Chen, Chinese Medical Herbology and Pharmacology (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1411', 'H282', 'breastfeeding', 'Breastfeeding', 'moderate', 'No human lactation data; excretion of paeonol/paeoniflorin into milk unknown, and the herb is blood-moving.', 'Avoid during nursing unless directed by a qualified practitioner.', 'Bensky et al. (2004); no LactMed monograph available.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1412', 'H282', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, heparin, direct oral anticoagulants)', 'moderate', 'Paeonol and paeoniflorin inhibit platelet aggregation and blood coagulation; additive antithrombotic effect increases bleeding risk.', 'Avoid or use only with medical supervision and INR/bleeding monitoring; discontinue 1 to 2 weeks before surgery.', 'Wang et al., Molecules 2017 (PMC6152737); Koo et al., Int J Mol Sci 2019 (PMC6834133).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1413', 'H282', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Paeonol has mild hypotensive/vasodilatory activity; theoretical additive blood-pressure lowering.', 'Monitor blood pressure when combined.', 'Wang et al., Molecules 2017 (PMC6152737).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1414', 'H282', 'condition', 'Cold-deficient Spleen/Stomach with chronic diarrhea', 'moderate', 'Cool, bitter, dispersing nature can worsen cold-type digestive weakness and loose stools.', 'Avoid, or combine with warming, Spleen-tonifying herbs under practitioner guidance.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1415', 'H282', 'condition', 'Yin deficiency with profuse spontaneous sweating; bleeding without heat signs', 'moderate', 'The acrid, dispersing quality can aggravate spontaneous sweating; the herb is inappropriate for bleeding not driven by heat.', 'Avoid in these patterns.', 'Bensky et al. (2004); Chen & Chen (2004).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1416', 'H282', 'other', 'Bleeding disorders and the perioperative period', 'moderate', 'Antiplatelet/anticoagulant constituents increase bleeding risk.', 'Discontinue 1 to 2 weeks before surgery; avoid with thrombocytopenia or coagulopathy.', 'Wang et al., Molecules 2017 (PMC6152737).');
