INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1417', 'H283', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'The plant is a documented abortifacient; root-derived trichosanthin acts on placental trophoblast cells, and the cold, slippery fruit/seed are traditionally abortive and reported as potentially harmful to the fetus.', 'Do not use in any form during pregnancy.', 'WebMD Chinese Cucumber monograph; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1418', 'H283', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human safety data for fruit, seed, or root during lactation.', 'Avoid while breastfeeding unless directed by a qualified practitioner.', 'WebMD Chinese Cucumber monograph');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1419', 'H283', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, other hypoglycemics)', 'moderate', 'Trichosanthes has documented hypoglycemic activity; additive effect may lower blood glucose excessively.', 'Monitor blood glucose and adjust medication with clinician oversight if combined.', 'WebMD Chinese Cucumber monograph; hypoglycemic study PMC5242006');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1420', 'H283', 'other', 'Aconite (Aconitum spp.; Fu Zi, Wu Tou)', 'moderate', 'Classical Eighteen Antagonisms (Shi Ba Fan) incompatibility pairing; traditionally treated as an absolute do-not-combine in TCM practice.', 'Do not combine Gua Lou with aconite-family herbs in the same formula.', 'Bensky, Clavey & Stoger, Materia Medica; classical Shi Ba Fan (Eighteen Antagonisms)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1421', 'H283', 'condition', 'Spleen/Stomach yang or qi deficiency with loose stools or diarrhea', 'moderate', 'Cold, slippery, and mildly laxative; aggravates cold-deficient digestion and diarrhea.', 'Avoid or use only when balanced by warming, digestive-supporting herbs.', 'Bensky, Clavey & Stoger, Materia Medica');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1422', 'H283', 'condition', 'Suspected cardiac chest pain (angina/myocardial infarction)', 'absolute', 'Traditional chest painful obstruction (xiong bi) overlaps clinically with acute coronary syndrome; self-treating conceals a medical emergency.', 'Refer immediately for emergency cardiac evaluation; do not substitute herbal therapy for cardiac care.', 'Clinical safety principle (Refer Threshold)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H283', 'EP01', 'match', 3, 0, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb damp rebalances the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry Gua Lou (\u681d\u6a13 / Trichosanthes).", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry Gua Lou (\u681d\u6a13 / Trichosanthes).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 200 CE), Gua Lou Xie Bai Bai Jiu Tang; Li Shi Zhen, Ben Cao Gang Mu (1596); WebMD and", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 200 CE), Gua Lou Xie Bai Bai Jiu Tang; Li Shi Zhen, Ben Cao Gang Mu (1596); WebMD and", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, true);
