INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H283', 'EP08', 'avoid', 0, 3, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb damp reinforces the pattern''s damp; tone: herb relaxed reinforces the pattern''s relaxed', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry Gua Lou (\u681d\u6a13 / Trichosanthes).", "locator": "Shennong Ben Cao Jing (Divine Husbandman''s Classic of Materia Medica, Han dynasty, c. 200 CE), entry Gua Lou (\u681d\u6a13 / Trichosanthes).", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 200 CE), Gua Lou Xie Bai Bai Jiu Tang; Li Shi Zhen, Ben Cao Gang Mu (1596); WebMD and", "locator": "Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004); Zhang Zhongjing, Jin Gui Yao Lue (Essentials from the Golden Cabinet, c. 200 CE), Gua Lou Xie Bai Bai Jiu Tang; Li Shi Zhen, Ben Cao Gang Mu (1596); WebMD and", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H284', 'Water Plantain (Ze Xie)', 'Alisma orientale', 'Alismataceae', 'Dried tuber (corm) / rhizome (Rhizoma Alismatis)', 'Sweet, Bland (dàn)', 'Cold', 'Dry', 'Dampness, Excess Heat (damp-heat in the lower burner), fluid Stagnation (water accumulation, edema), Phlegm / thin-fluid (tan-yin) accumulation, Excess Conditions', 'Dryness, Deficiency (Kidney yang deficiency; cold, deficient spermatorrhea or leukorrhea), Cold, fluid Exhaustion / depletion. Do not use to drain a dry, fluid-depleted, or yin-deficient patient who has no genuine dampness.', 'Urinary (primary; Kidney and Bladder channels), Digestive (damp diarrhea), Reproductive (drains Kidney ministerial fire), Cardiovascular / metabolic (modern antihyperlipidemic and antihypertensive activity)', 'Edema and fluid retention, scanty or difficult urination, damp-heat painful urinary dribbling (lin) and urinary irritation, damp diarrhea, phlegm-fluid dizziness and vertigo, damp-heat spermatorrhea and nocturnal emission; modern: hyperlipidemia and mild functional hypertension', 'The boggy, water-logged, damp-heat phenotype: the phlegmatic who holds fluid and the robust, hot-damp type with lower-burner heat. Aggravates the thin, cold, dry, depleted (Vata-like) and the deficient, pale, fluid-poor constitution, in whom its cold, drying diuresis worsens depletion.', 'Kapha, Pitta', 'Vata (cold, drying, diuretic; depletes and disperses)', 'Dampness and damp-heat pouring into the lower burner (edema, painful urinary dribbling, damp-heat diarrhea and leukorrhea); phlegm-fluid (tan-yin) with dizziness and vertigo; Kidney and Bladder damp-heat stirring the ministerial fire (damp-heat spermatorrhea). Classically paired within yin-tonifying formulas (e.g. Liu Wei Di Huang Wan) to drain turbid damp and settle deficiency fire.', 'Kidney yang deficiency with cold (cold, deficient spermatorrhea or vaginal discharge); Yin deficiency or fluid dryness without dampness; Spleen qi deficiency with sinking / sunken middle qi (use with caution).', 'A strong, draining, cold diuretic; use only where genuine damp or damp-heat is present. Not for spermatorrhea or leukorrhea arising from Kidney yang deficiency or damp-cold. Use caution with sunken middle-burner qi (Spleen qi deficiency, prolapse). Overdose or prolonged high-dose use can cause nausea, vomiting, diarrhea, abdominal pain, hematuria, and potassium/electrolyte depletion; modern toxicology reports dose- and duration-dependent hepatotoxicity and nephrotoxicity (attributed to emodin and to high-dose alisols). Keep to therapeutic doses; avoid megadoses and open-ended long-term use, and use cautiously in pre-existing liver or kidney disease.', 'Kidney yang deficiency with cold; yin deficiency / fluid dryness without true dampness; sinking Spleen qi (caution). Pregnancy and lactation: avoid absent practitioner supervision. Avoid stacking with pharmaceutical diuretics without monitoring.', 'Insufficient modern safety data. Classical Chinese medicine used Ze Xie cautiously within formulas for pregnancy edema, but it is a strong diuretic that depletes fluid and electrolytes, and modern consumer references advise avoidance. Avoid in pregnancy except under qualified practitioner supervision. (Natural Medicines / WebMD, Asian Water Plantain; AHPA Botanical Safety Handbook, 2nd ed., 2013.)', 'Insufficient data. Diuretics can reduce maternal fluid status and theoretically milk volume. Avoid during lactation without practitioner guidance. (Natural Medicines / WebMD, Asian Water Plantain.)', 'No established pediatric safety data and not a routine Western pediatric herb. Reserve for practitioner-guided use in children, at weight-adjusted decoction doses, and not for prolonged courses. (No modern pediatric data; AHPA Botanical Safety Handbook, 2nd ed., 2013.)', 'Additive with pharmaceutical diuretics (furosemide, thiazides): increased diuresis with risk of potassium and electrolyte depletion. Additive hypotensive effect with antihypertensive drugs. Theoretical potentiation of lithium toxicity (diuretic-induced reduction in lithium clearance) and of digoxin toxicity (via diuretic-induced hypokalemia). May add to the effect of blood-glucose-lowering and lipid-lowering drugs (documented modern hypoglycemic and hypolipidemic activity). (Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology; Brinker, Herbal Contraindications and Drug Interactions, 4th ed.; Acupuncture Today herb-drug interaction review.)', 'Decoction of the sliced dried tuber (standard). Also powder, tincture, and capsule/granule extract. Often processed before use: salt-fried (yán zhì, to direct action to the Kidney and drain deficiency fire) or bran-fried (to temper the cold, draining quality and protect the Spleen). Added to soups as part of a formula.', 'Decoction: 5-10 g dried tuber per day (Pharmacopoeia of the PRC range 6-10 g); up to 15-30 g short-term for marked edema. Tincture: 2-4 mL. Powder: 1-3 g. Rarely used alone; typically formula-based. Short to medium courses; avoid indefinite high-dose use.', 'Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.', 'Bensky D, Clavey S, Stöger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA Botanical Safety Handbook (2nd ed., 2013); Natural Medicines / WebMD (Asian Water Plantain); Tian et al., traditional uses, phytochemistry, pharmacology and toxicology review of Rhizoma Alismatis / Alisma orientale (J Ethnopharmacol 2014; Frontiers in Pharmacology 2022, 2025).', 'Ze Xie (泽泻) is the dried tuber of Alisma orientale (Sam.) Juzep., family Alismataceae (water-plantain family), also treated as A. plantago-aquatica subsp. orientale. A foundational Chinese diuretic and one of the five ingredients of Wu Ling San, of Zhu Ling Tang and Ze Xie Tang, and the draining ''minus'' herb of Liu Wei Di Huang Wan, where it leaches turbid damp so the rich yin tonics do not become cloying and settles Kidney deficiency fire. Characteristic constituents are protostane-type triterpenoids (alisols), notably alisol A, alisol B and their acetates (alisol A 24-acetate, alisol B 23-acetate) and alisol C, plus sesquiterpenes; the anthraquinone emodin is the marker most implicated in high-dose toxicity. Modern pharmacology documents diuretic, antihyperlipidemic, antihypertensive, hypoglycemic, hepatoprotective (fatty-liver, anti-lipoapoptotic) and antioxidant activity. Distinguish from Che Qian Zi (Plantago seed), which shares the diuretic role but is a different plant, and from the European Water Plantain, Alisma plantago-aquatica, which belongs to a separate Western folk tradition.', 'Not named in the canonical biblical texts; native to eastern Asia (China, Japan, Korea, eastern Russia). A foundational Chinese materia medica herb first recorded in the Shennong Ben Cao Jing (c. 200 CE) as a superior-grade drug said, in the Daoist idiom, to sharpen the senses, lighten the body, and prolong life with long use. Its European congener Alisma plantago-aquatica (''Water Plantain'') carries a separate Western folk tradition (Culpeper, Grieve) and should not be conflated with the Chinese drug.', 'Not at-risk. Ze Xie is a cultivated aquatic (paddy) crop, grown at scale in Fujian (Jian Ze Xie) and Sichuan (Chuan Ze Xie); not listed by United Plant Savers or CITES. The sourcing concern is quality and processing rather than conservation: prefer lab-tested material free of excess sulfur-dioxide residue (a common processing and preservation problem for this root) and screened for heavy metals and agrochemical residues.', 'Cold, dry, sweet-and-bland draining diuretic: opens the water pathways to leach damp-heat and stagnant fluid downward and out through the urine, cooling the boggy, water-logged lower burner.', 'T2/T3. Edema is a red-flag symptom: refer before self-treating any undiagnosed swelling. Refer urgently for edema with shortness of breath or chest pain, sudden or one-sided leg swelling, facial or periorbital edema, markedly reduced urine output, blood in the urine, or fever with flank pain, and for any edema, headache, or visual change in pregnancy (to rule out cardiac, renal, or hepatic failure, DVT, nephrotic syndrome, pyelonephritis, or pre-eclampsia).', 'Water Plantain / Ze Xie (dzuh SHYEH); Alisma orientale (ah-LIZ-muh or-ee-en-TAH-lee)', 'free', 'Approved', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "locator": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H284', 'T02');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS07', 'Primary', 'Chief action: drains dampness and promotes urination');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS05', 'Primary', 'Clears damp-heat and drains Kidney/ministerial fire');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS08', 'Secondary', 'Moves stagnant water and fluid accumulation (edema)');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS23', 'Secondary', 'Resolves phlegm-fluid (tan-yin) causing dizziness and vertigo');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS16', 'Secondary', 'For genuine excess damp, not deficiency');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS03', 'Primary', 'Cold and drying; avoid in dryness or yin-deficient fluid loss');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H284', 'TS01', 'Primary', 'Avoid in Kidney yang deficiency and cold, deficient spermatorrhea/leukorrhea');
