INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H284', 'TCM03', 'Secondary', 'Use caution in Spleen qi deficiency with sinking / sunken middle qi', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "locator": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1423', 'H284', 'pregnancy', 'Pregnancy', 'moderate', 'Strong cold diuretic that depletes fluid and electrolytes; modern safety data are insufficient. Classical use for pregnancy edema was cautious and formula-based.', 'Avoid in pregnancy except under qualified practitioner supervision; do not self-treat pregnancy swelling (rule out pre-eclampsia).', 'Natural Medicines / WebMD (Asian Water Plantain); AHPA Botanical Safety Handbook, 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1424', 'H284', 'breastfeeding', 'Breastfeeding', 'moderate', 'Insufficient data; diuretic action can reduce maternal fluid status and theoretically milk volume.', 'Avoid during lactation without practitioner guidance.', 'Natural Medicines / WebMD (Asian Water Plantain)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1425', 'H284', 'drug_interaction', 'Pharmaceutical diuretics (furosemide, thiazides)', 'moderate', 'Additive diuresis; increased risk of dehydration and potassium/electrolyte depletion.', 'Avoid combined use or monitor fluid status and serum electrolytes if co-administered.', 'Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology; Brinker, Herbal Contraindications and Drug Interactions, 4th ed. (2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1426', 'H284', 'drug_interaction', 'Antihypertensive drugs', 'low', 'Documented modest blood-pressure-lowering activity; theoretical additive hypotension.', 'Monitor blood pressure if combined with antihypertensive medication.', 'Acupuncture Today herb-drug interaction review; Chen & Chen, Chinese Medical Herbology and Pharmacology');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1427', 'H284', 'drug_interaction', 'Lithium and digoxin', 'moderate', 'Theoretical, via the diuretic mechanism: reduced lithium clearance can raise lithium levels; diuretic-induced hypokalemia can potentiate digoxin toxicity.', 'Avoid or use only with drug-level and electrolyte monitoring in patients on lithium or digoxin.', 'Brinker, Herbal Contraindications and Drug Interactions, 4th ed. (2010); standard diuretic-herb interaction reasoning (Natural Medicines)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1428', 'H284', 'condition', 'Overdose / prolonged high-dose use (esp. pre-existing liver or kidney disease)', 'moderate', 'Dose- and duration-dependent hepatotoxicity and nephrotoxicity reported in modern toxicology (attributed to emodin and high-dose alisols); overdose can cause GI upset, hematuria, and electrolyte imbalance.', 'Keep to therapeutic doses and limited courses; avoid megadoses and open-ended long-term use; use cautiously and monitor in pre-existing hepatic or renal impairment.', 'Tian et al., Rhizoma Alismatis / Alisma orientale toxicology reviews (J Ethnopharmacol 2014; Frontiers in Pharmacology 2022, 2025)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1429', 'H284', 'other', 'Kidney yang deficiency with cold; yin deficiency without dampness; sinking Spleen qi', 'moderate', 'Cold, draining, drying herb; it depletes yang, fluids, and qi when no true dampness is present and can worsen sinking of the middle burner.', 'Use only where genuine damp or damp-heat is present; avoid in cold-deficient spermatorrhea/leukorrhea and in dry, yin-deficient patients; use cautiously with prolapse or sunken qi.', 'Bensky, Clavey & Stöger, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H284', 'EP01', 'match', 2, 1, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb relaxed rebalances the pattern''s tense', 'computed_energetics', '{"title": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "locator": "Shennong Ben Cao Jing (The Divine Farmer''s Materia Medica, c. 200 CE): Ze Xie, listed among the superior (upper-grade / shang pin) herbs.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "locator": "Bensky D, Clavey S, St\u00f6ger E, Chinese Herbal Medicine: Materia Medica (3rd ed., 2004): Ze Xie; Chen JK & Chen TT, Chinese Medical Herbology and Pharmacology (2004); Pharmacopoeia of the People''s Republic of China (Rhizoma Alismatis); AHPA B", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
