INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1430', 'H285', 'condition', 'Renal insufficiency / chronic kidney disease / history of calcium-oxalate kidney stones / gout', 'absolute', 'Chaga is high in oxalate; high-dose or prolonged use has caused oxalate nephropathy, nephrotic syndrome, and end-stage renal disease in human case reports. Impaired kidneys, prior oxalate stones, and gout cannot safely handle the added oxalate load.', 'Do not use in anyone with reduced kidney function, CKD, prior calcium-oxalate stones, or gout. In others, keep courses short, hydrate well, and monitor renal function.', 'MSKCC About Herbs (Chaga Mushroom); Chaga-induced oxalate nephropathy, Medicine 2022;101(11):e28983 (PMC8913114); ESRD after long-term chaga ingestion (2020)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1431', 'H285', 'drug_interaction', 'High-dose vitamin C (ascorbic acid) supplements', 'moderate', 'Vitamin C is metabolized in part to oxalate; combined with chaga''s own oxalate it compounds the renal oxalate burden. Concurrent high-dose vitamin C was a co-factor in a reported chaga oxalate-nephropathy case.', 'Do not combine medicinal chaga with high-dose vitamin C; keep total oxalate and ascorbate intake modest and stay well hydrated.', 'Chaga-induced oxalate nephropathy manifesting as nephrotic syndrome, Medicine 2022;101(11):e28983 (PMC8913114)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1432', 'H285', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel, DOACs)', 'moderate', 'Chaga extract inhibits platelet aggregation in animal models, giving a theoretical additive bleeding risk.', 'Avoid or use only with medical supervision and monitoring in patients on anticoagulants or antiplatelets; discontinue before surgery.', 'MSKCC About Herbs (Chaga Mushroom)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1433', 'H285', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Chaga shows additive blood-glucose-lowering activity in vitro and animal models; combined with hypoglycemic drugs it may cause hypoglycemia.', 'Monitor blood glucose if combined with antidiabetic therapy; adjust medication under clinician guidance.', 'MSKCC About Herbs (Chaga Mushroom)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1434', 'H285', 'drug_interaction', 'Immunosuppressant drugs (ciclosporin, tacrolimus, transplant and autoimmune regimens)', 'moderate', 'Chaga stimulates immune activity and may oppose the intended action of immunosuppressive therapy.', 'Avoid in organ-transplant recipients and others on immunosuppressants unless directed by the prescribing clinician.', 'MSKCC About Herbs (Chaga Mushroom)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1435', 'H285', 'condition', 'Autoimmune disease (e.g. rheumatoid arthritis, lupus, multiple sclerosis)', 'moderate', 'Immunostimulant activity may theoretically aggravate autoimmune conditions or interfere with immunomodulating treatment.', 'Use only under practitioner supervision in autoimmune disease; discontinue if disease activity increases.', 'MSKCC About Herbs (Chaga Mushroom); AHPA Botanical Safety Handbook 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1436', 'H285', 'pregnancy', 'Pregnancy (medicinal use)', 'moderate', 'No adequate human safety data; the oxalate load and immunostimulant activity add theoretical concern.', 'Avoid medicinal chaga in pregnancy; insufficient data to establish safety.', 'MSKCC About Herbs (Chaga Mushroom); AHPA Botanical Safety Handbook 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1437', 'H285', 'breastfeeding', 'Breastfeeding (medicinal use)', 'moderate', 'No lactation safety data; milk transfer and infant effects are unstudied.', 'Avoid medicinal chaga while breastfeeding; insufficient data to establish safety.', 'MSKCC About Herbs (Chaga Mushroom); AHPA Botanical Safety Handbook 2nd ed. (2013)');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H285', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Russian and Siberian ethnobotanical tradition (birch-fungus / chaga folk medicine, documented since at least the 16th century): decoction for chronic gastritis, gastric and duodenal ulcers, and gastrointestinal cancers; standardized by the ", "locator": "Russian and Siberian ethnobotanical tradition (birch-fungus / chaga folk medicine, documented since at least the 16th century): decoction for chronic gastritis, gastric and duodenal ulcers, and gastrointestinal cancers; standardized by the ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Memorial Sloan Kettering Cancer Center, About Herbs, Chaga Mushroom (integrative-oncology monograph); AHPA Botanical Safety Handbook (2nd ed., 2013); chaga oxalate-nephropathy case reports (Medicine 2022;101(11):e28983, PMC8913114; end-stag", "locator": "Memorial Sloan Kettering Cancer Center, About Herbs, Chaga Mushroom (integrative-oncology monograph); AHPA Botanical Safety Handbook (2nd ed., 2013); chaga oxalate-nephropathy case reports (Medicine 2022;101(11):e28983, PMC8913114; end-stag", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
