INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1438', 'H286', 'condition', 'G6PD (glucose-6-phosphate dehydrogenase) deficiency, especially neonates and infants', 'absolute', 'Lawsone is an ortho-substituted 1,4-naphthoquinone that induces oxidative injury to red blood cells. In G6PD-deficient individuals this triggers hemolysis; even topical application to neonates and infants has caused severe hemolytic anemia, hyperbilirubinemia, kernicterus, and death.', 'Do not apply henna to the skin of neonates or infants. Avoid henna entirely (topical or oral) in anyone known or suspected to be G6PD-deficient. Screen before any pediatric use.', 'G6PD hemolysis case literature (Raupp et al., PubMed 8985525; PMC9985141, 2023); AHPA Botanical Safety Handbook 2nd ed.; WebMD/Natural Medicines');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1439', 'H286', 'pregnancy', 'Pregnancy (internal use; and near-term/large-area topical use)', 'absolute', 'Oral henna is rated Unsafe (hemolysis; the fruit carries a traditional emmenagogue reputation, Grieve 1931). Near term, hemolysis risk extends to a potentially G6PD-deficient fetus or neonate.', 'Do not use henna internally in pregnancy. Limit topical natural henna to small skin areas; avoid large-area or near-term application and avoid ''black henna'' (PPD) entirely.', 'WebMD/Natural Medicines; Grieve''s A Modern Herbal (1931); AHPA Botanical Safety Handbook 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1440', 'H286', 'breastfeeding', 'Breastfeeding (internal use)', 'moderate', 'Oral henna is rated Unsafe during lactation. Topical natural henna has low systemic absorption but stained skin can transfer to a nursing infant.', 'Do not take henna internally while breastfeeding. If using topically, avoid the breast and nipple and prevent infant contact with stained skin.', 'WebMD/Natural Medicines; AHPA Botanical Safety Handbook 2nd ed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1441', 'H286', 'drug_interaction', 'Lithium', 'moderate', 'Henna may decrease lithium elimination, raising serum lithium toward toxic levels.', 'Avoid concurrent internal use of henna with lithium; if unavoidable, monitor serum lithium closely under medical supervision.', 'WebMD/Natural Medicines (Henna-lithium interaction)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1442', 'H286', 'drug_interaction', 'Oxidant drugs in G6PD-deficient patients (dapsone, primaquine, sulfonamides, nitrofurantoin, methylene blue)', 'moderate', 'Additive oxidative stress on red blood cells increases the risk of hemolysis in G6PD-deficient individuals.', 'Avoid henna in G6PD-deficient patients, particularly those taking oxidant medications.', 'G6PD hemolysis literature; WebMD/Natural Medicines');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1443', 'H286', 'condition', '''Black henna'' (para-phenylenediamine, PPD) and henna/naphthoquinone allergy', 'absolute', '''Black henna'' is natural henna adulterated with PPD, a potent contact allergen that causes severe allergic contact dermatitis, chemical burns, permanent scarring, and lifelong sensitization. True natural henna stains reddish-brown, never black.', 'Never use ''black henna.'' Use only pure, body-art-quality natural henna, and avoid all henna in anyone with a known henna or naphthoquinone-dye allergy.', 'WebMD/Natural Medicines; dermatology contact-allergy literature');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H286', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve''s A Modern Herbal (1931): Henna (Lawsonia alba / Lawsonia inermis)", "locator": "Grieve''s A Modern Herbal (1931): Henna (Lawsonia alba / Lawsonia inermis)", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb, '{"title": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); WebMD/Natural Medicines Henna monograph; NCCIH; lawsone phytochemistry and pharmacology reviews (PMC11288359; ACS Molecule of the Week: Lawsone); G6PD hemolysis case literat", "locator": "AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 2013); WebMD/Natural Medicines Henna monograph; NCCIH; lawsone phytochemistry and pharmacology reviews (PMC11288359; ACS Molecule of the Week: Lawsone); G6PD hemolysis case literat", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/", "kind": "pubmed"}'::jsonb, true);
