INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H287', 'Bogbean (Buckbean)', 'Menyanthes trifoliata', 'Menyanthaceae (historically classified in Gentianaceae)', 'Leaf (dried trifoliate leaf); traditionally the rhizome also', 'Bitter', 'Cold', 'Dry', 'Atonic torpor and laxity of the digestive and hepatic tissues, with deficiency and debility of assimilation. Secondarily, damp lymphatic and rheumatic congestion in a cold, boggy, under-fired terrain.', 'Dryness and cold: the cold, drying bitterness aggravates dry, cold, or exhausted states. Acute gastrointestinal inflammation and ulceration (peptic ulcer, dysentery, colitis) are aggravated by its irritant, purgative potential.', 'Digestive (stomach, appetite, gastric and biliary secretion) and hepatic primarily; secondarily musculoskeletal (rheumatism, gout), integumentary (skin and scrofulous eruptions), and lymphatic/glandular; historically also urinary, as a diuretic in dropsy.', 'Atonic dyspepsia with poor appetite and sluggish digestion; general debility and convalescent weakness with impaired assimilation; sluggish liver and bile stagnation; chronic rheumatism and gout; scrofulous and cutaneous complaints with glandular swelling; historically intermittent fevers (ague) and intestinal worms.', 'Cold-Damp, atonic and phlegmatic: the sluggish, boggy, under-fired digestion with poor appetite and slow assimilation, and the congested melancholic liver. Best suited to the damp, torpid, relaxed constitution that needs stimulation and tone, not to the thin, dry, cold-depleted frame, which its cooling, drying bitterness can further deplete.', 'Kapha, Pitta', 'Vata', 'By energetic analogy (not a classical Chinese herb): a bitter, cold, draining leaf that clears and dries Damp-Heat and Damp-stagnation of the Stomach/Spleen and Liver/Gallbladder, promotes bile and gentle downward movement, and clears heat expressed in the skin and joints.', 'Spleen and Stomach Qi and Yang deficiency with cold and loose stools (bitter-cold injures the middle burner); Kidney Yang deficiency; and Yin or fluid deficiency with dryness, where its drying, cooling nature aggravates.', 'Intensely bitter; doses above the tonic range are purgative and emetic, causing nausea, vomiting, griping, and diarrhea. Cold and drying: unsuitable for cold-deficient digestion with loose stools and for the frail, dry, or depleted. Contraindicated in active peptic (gastric or duodenal) ulcer and in diarrhea, dysentery, or inflammatory bowel disease. Keep to small bitter-tonic doses, taken shortly before meals for appetite and digestion.', 'Active gastric or duodenal ulcer (EMA/HMPC contraindication); acute diarrhea, dysentery, or inflammatory bowel disease; known hypersensitivity to the herb. Avoid in pregnancy and lactation (no safety data). Not for use above traditional tonic doses.', 'Avoid. No safety data in pregnancy; EMA/HMPC advises a precautionary approach and non-use, and consumer references (Natural Medicines/WebMD) rate medicinal amounts possibly unsafe owing to gastrointestinal irritation and diarrhea risk. Trace culinary or flavoring amounts are not the concern, but therapeutic bitter doses should be avoided.', 'Insufficient data; avoid. EMA/HMPC reports no lactation data, and excretion into milk and effects on the infant are unstudied. Precautionary avoidance recommended.', 'No pediatric dosing established. Bitter tonics are generally reserved for adults; the intense bitterness and purgative potential at higher doses make bogbean unsuitable for young children. If used in older children for poor appetite, only under professional guidance at a reduced dose. No modern pediatric safety data.', 'No well-documented pharmacokinetic drug interactions (limited data); EMA/HMPC and AHPA note none of significance. Theoretical additive gastrointestinal irritation with NSAIDs, salicylates, or other mucosal irritants, and additive effect with stimulant laxatives at higher doses. As a bitter that stimulates gastric secretion, use cautiously alongside drugs whose tolerance or absorption is affected by increased gastric acidity.', 'Cold or hot water infusion (tea) of the dried leaf; tincture; powdered leaf; often combined with other bitters and aromatics (wormwood, centaury, or sage, per Grieve) for dyspepsia. Externally, a compress or wash of the infusion was applied traditionally to glandular (scrofulous) swellings.', 'Dried-leaf infusion: 1.5-3 g in about 150 mL boiling water, up to 3 times daily (EMA/HMPC), taken before meals; traditional strong infusion 1 oz dried leaf to 1 pint water in wineglassful doses (Grieve). Powdered leaf: 0.6-1.6 g (10-25 grains) as a tonic (King''s). Tincture (1:5, 45%): about 1-2 mL up to 3x daily. Fluid extract: 10-40 drops (Grieve). Do not exceed tonic doses; larger amounts are cathartic and emetic.', 'Grieve, M., A Modern Herbal (1931) - Bogbean/Buckbean (Menyanthes trifoliata); King''s American Dispensatory (Felter & Lloyd, 1898) - Menyanthes.', 'EMA/HMPC Assessment Report on Menyanthes trifoliata L., folium (2009); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Mills, S. & Bone, K., Principles and Practice of Phytotherapy (bitters/cholagogues); WebMD/Natural Medicines - Bogbean; Plants For A Future (PFAF) - Menyanthes trifoliata.', 'Chief constituents are intensely bitter secoiridoid glycosides - dihydrofoliamenthin, foliamenthin, menthiafolin, loganin, and sweroside, historically summarized as the bitter principle ''menyanthin'' - together with flavonoids (rutoside/rutin, hyperoside, quercetin, kaempferol and isorhamnetin glycosides, and the C-glycosides vitexin/isovitexin), phenolic and coumaric acids, and a small volatile oil. The high bitterness value drives a reflex stomachic action: bitter receptors trigger increased salivary and gastric secretion, bile flow, and appetite, which is the basis of its classical use as a bitter tonic in atonic dyspepsia and debility. It is a close energetic relative of gentian (both share the secoiridoid-bitter niche; Menyanthes was long placed in Gentianaceae before segregation into Menyanthaceae). Eclectic tradition (King''s) valued it as a tonic ''where digestion and blood making are impaired,'' and in chronic rheumatism, hepatalgia, dropsy, worms, scrofula, and cutaneous disease; Grieve records tonic, cathartic, deobstruent, and febrifuge actions and its historical use as a hop substitute for bittering ale. Bounding caution: the same bitterness that is therapeutic becomes purgative and emetic at higher doses, and the leaf is contraindicated in peptic ulceration and active diarrheal or inflammatory bowel states.', 'Not in canonical biblical texts. Menyanthes trifoliata is a circumboreal wetland species of Europe, northern Asia, and North America belonging to Western and Northern European folk and American Eclectic traditions rather than the Mediterranean biblical materia medica. Documented by Grieve (A Modern Herbal, 1931) and the American Eclectics (King''s, 1898); historically used in Scotland, Scandinavia, and northern Europe as a spring bitter, an antiscorbutic, and a hop substitute in brewing.', 'Bogbean is an obligate wetland plant of peat bogs, fens, marshes, and shallow pond margins, habitats that are declining and legally protected in parts of its range (Grieve already noted it as scarce in southern England). It is not listed by United Plant Savers (a Eurasian-centered species), but its bog and fen habitats are fragile, slow to recover, and ecologically valuable. Source from cultivated stock or responsibly managed wetlands; do not wild-harvest from sensitive or protected peatlands.', 'Cold, dry, and intensely bitter: a bog-born bitter tonic that kindles a torpid, atonic digestion, moves a sluggish liver, and cools rheumatic and cutaneous heat.', 'Refer for unexplained weight loss, persistent vomiting or diarrhea, blood in stool or black/tarry stools, jaundice, severe or progressive abdominal pain, a known or suspected peptic ulcer, or joint disease with progressive deformity or systemic features. Digestive symptoms that persist beyond two weeks of tonic use warrant medical evaluation.', 'Bogbean: BOG-been (Buckbean: BUK-been). Menyanthes trifoliata: men-ee-AN-theez try-foh-lee-AY-tuh.', 'seed', 'Approved', '{"title": "Grieve, M., A Modern Herbal (1931) - Bogbean/Buckbean (Menyanthes trifoliata); King''s American Dispensatory (Felter & Lloyd, 1898) - Menyanthes.", "locator": "Grieve, M., A Modern Herbal (1931) - Bogbean/Buckbean (Menyanthes trifoliata); King''s American Dispensatory (Felter & Lloyd, 1898) - Menyanthes.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC Assessment Report on Menyanthes trifoliata L., folium (2009); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Mills, S. & Bone, K., Principles and Practice of Phytotherapy (bitters/cholagogues); WebMD/Natural Me", "locator": "EMA/HMPC Assessment Report on Menyanthes trifoliata L., folium (2009); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Mills, S. & Bone, K., Principles and Practice of Phytotherapy (bitters/cholagogues); WebMD/Natural Me", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H287', 'T01');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS19', 'Primary', 'Atonic torpor of digestion and liver; the core bitter-tonic indication for atonic dyspepsia');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS01', 'Secondary', 'Debility and impaired assimilation (''digestion and blood making impaired'', King''s)');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS09', 'Secondary', 'Laxity and under-tone of the atonic digestive tract');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS08', 'Secondary', 'Deobstruent action on hepatic and lymphatic congestion');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS24', 'Secondary', 'Scrofulous/glandular swellings; alterative use in scrofula (King''s, Grieve)');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS07', 'Minor', 'Damp, boggy terrain; historic diuretic use in dropsy');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS03', 'Primary', 'Cold, drying bitter aggravates dry tissue states');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS17', 'Primary', 'Cold herb worsens frank cold, especially cold-deficient digestion with loose stools');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS06', 'Secondary', 'GI irritant; contraindicated in peptic ulcer, dysentery, colitis (EMA/HMPC, WebMD)');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H287', 'TS04', 'Secondary', 'Depleting in the truly exhausted or frail on overuse');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY08', 'Primary', 'Stomach, appetite, gastric secretion; bitter stomachic tonic');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY12', 'Primary', 'Cholagogue/deobstruent for torpid liver and bile stagnation');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY04', 'Secondary', 'Chronic rheumatism and gout');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY10', 'Secondary', 'Skin diseases and cutaneous eruptions (alterative)');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY11', 'Secondary', 'Scrofula and glandular swellings');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H287', 'SY05', 'Minor', 'Alterative/immune support in scrofulous states');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H287', 'A16', 'Primary', 'Intensely bitter reflex stomachic tonic; stimulates appetite and gastric secretion');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H287', 'A43', 'Secondary', 'Deobstruent/cholagogue for torpid liver (Grieve, King''s)');
