INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1444', 'H287', 'condition', 'Active gastric or duodenal (peptic) ulcer', 'absolute', 'Bitter secoiridoids stimulate gastric secretion and the leaf is a mucosal irritant, which can aggravate ulceration', 'Do not use in active peptic ulcer disease; formally contraindicated per EMA/HMPC labeling', 'EMA/HMPC Assessment Report on Menyanthes trifoliata folium (2009)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1445', 'H287', 'condition', 'Diarrhea, dysentery, or inflammatory bowel disease (colitis)', 'moderate', 'Gastrointestinal irritant with cathartic potential; may worsen loose stools and mucosal inflammation', 'Avoid during active diarrheal or inflammatory bowel conditions', 'WebMD/Natural Medicines - Bogbean; RxList');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1446', 'H287', 'pregnancy', 'Pregnancy', 'moderate', 'No safety data; bitter/cathartic potential at higher doses may cause GI irritation and diarrhea', 'Avoid therapeutic doses during pregnancy as a precaution', 'EMA/HMPC Assessment Report (2009); WebMD/Natural Medicines - Bogbean');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1447', 'H287', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on excretion into breast milk or effects on the nursing infant', 'Avoid during lactation as a precaution', 'EMA/HMPC Assessment Report (2009)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1448', 'H287', 'other', 'High doses (above tonic range)', 'moderate', 'Amounts above the bitter-tonic range are purgative and emetic, causing nausea, vomiting, griping, and diarrhea', 'Keep to tonic doses (1.5-3 g leaf up to 3x daily); do not exceed', 'Grieve, A Modern Herbal (1931); King''s American Dispensatory (1898); EMA/HMPC (2009)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1449', 'H287', 'drug_interaction', 'NSAIDs, salicylates, other gastric irritants, and stimulant laxatives', 'low', 'Theoretical additive GI mucosal irritation or additive laxative effect; no clinically documented pharmacokinetic interactions', 'Monitor for additive GI upset; separate dosing from mucosal-irritant drugs; limited-data caution', 'AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); EMA/HMPC (2009) - no significant interactions documented');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H287', 'EP01', 'avoid', 1, 2, 'temperature: herb cold rebalances the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "Grieve, M., A Modern Herbal (1931) - Bogbean/Buckbean (Menyanthes trifoliata); King''s American Dispensatory (Felter & Lloyd, 1898) - Menyanthes.", "locator": "Grieve, M., A Modern Herbal (1931) - Bogbean/Buckbean (Menyanthes trifoliata); King''s American Dispensatory (Felter & Lloyd, 1898) - Menyanthes.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "EMA/HMPC Assessment Report on Menyanthes trifoliata L., folium (2009); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Mills, S. & Bone, K., Principles and Practice of Phytotherapy (bitters/cholagogues); WebMD/Natural Me", "locator": "EMA/HMPC Assessment Report on Menyanthes trifoliata L., folium (2009); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013); Mills, S. & Bone, K., Principles and Practice of Phytotherapy (bitters/cholagogues); WebMD/Natural Me", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
