INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H288', 'TCM07', 'Secondary', 'Yin deficiency with dryness: further dries fluids', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. II ,  Daruharidra (Berberis aristata DC., root), Government of India, Ministry of Health & Family Welfare.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. II ,  Daruharidra (Berberis aristata DC., root), Government of India, Ministry of Health & Family Welfare.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Berberis (Berberis vulgaris, the Western congener), henriettes-herb.com; Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.; NCCIH; Brinker, He", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Berberis (Berberis vulgaris, the Western congener), henriettes-herb.com; Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.; NCCIH; Brinker, He", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1450', 'H288', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Berberine crosses the placenta and displaces bilirubin from albumin (neonatal kernicterus risk near term); it has also shown uterine-stimulant activity in animal models.', 'Avoid throughout pregnancy.', 'MotherToBaby/NCBI Berberine fact sheet (NBK600384); AHPA Botanical Safety Handbook 2nd ed. (berberine-containing Berberis); Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1451', 'H288', 'breastfeeding', 'Breastfeeding', 'absolute', 'Berberine is excreted into breast milk and can displace bilirubin in the nursing newborn, risking jaundice and, rarely, kernicterus.', 'Avoid while nursing, especially with a jaundiced or premature infant.', 'LactMed (berberine-containing goldenseal); MotherToBaby Berberine fact sheet (NBK600384).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1452', 'H288', 'other', 'Newborns, premature, and jaundiced infants', 'absolute', 'Bilirubin displacement can precipitate kernicterus; berberine can also cause hemolysis in G6PD-deficient infants.', 'Do not administer to neonates or young infants.', 'AHPA Botanical Safety Handbook 2nd ed.; MotherToBaby; LactMed.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1453', 'H288', 'drug_interaction', 'Cyclosporine and tacrolimus', 'moderate', 'Berberine inhibits CYP3A4 and P-glycoprotein, raising blood levels of these narrow-therapeutic-index immunosuppressants (a human study showed elevated cyclosporine concentrations).', 'Avoid combination or monitor drug levels closely under supervision.', 'Brinker, Herbal Contraindications and Drug Interactions; clinical pharmacokinetic study; Mills & Bone.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1454', 'H288', 'drug_interaction', 'Antidiabetic drugs (metformin, sulfonylureas, insulin)', 'moderate', 'Berberine lowers blood glucose; additive effect can cause hypoglycemia.', 'Monitor blood glucose and adjust medication with the prescriber.', 'NCCIH; Mills & Bone, Principles and Practice of Phytotherapy.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1455', 'H288', 'drug_interaction', 'CYP3A4 and P-glycoprotein substrates (digoxin, some statins, warfarin, calcium-channel blockers)', 'moderate', 'Inhibition of CYP3A4 and P-gp can raise substrate exposure; warfarin may be potentiated via protein-binding displacement.', 'Avoid with narrow-therapeutic-index drugs or monitor closely.', 'Brinker, Herbal Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1456', 'H288', 'condition', 'G6PD deficiency (infants)', 'moderate', 'Berberine can induce hemolysis in G6PD-deficient individuals, most concerning in infants.', 'Avoid in G6PD-deficient infants; caution in known G6PD deficiency.', 'MotherToBaby; AHPA Botanical Safety Handbook 2nd ed.');
