INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H288', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. II ,  Daruharidra (Berberis aristata DC., root), Government of India, Ministry of Health & Family Welfare.", "locator": "The Ayurvedic Pharmacopoeia of India, Part I, Vol. II ,  Daruharidra (Berberis aristata DC., root), Government of India, Ministry of Health & Family Welfare.", "source_id": "S10", "author": "Ayurvedic Pharmacopoeia of India", "year": "ongoing", "url": "https://www.ayush.gov.in/"}'::jsonb, '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898), Berberis (Berberis vulgaris, the Western congener), henriettes-herb.com; Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.; NCCIH; Brinker, He", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898), Berberis (Berberis vulgaris, the Western congener), henriettes-herb.com; Mills & Bone, Principles and Practice of Phytotherapy; AHPA Botanical Safety Handbook, 2nd ed.; NCCIH; Brinker, He", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H289', 'Kutki (Katuka)', 'Picrorhiza kurroa', 'Plantaginaceae (formerly Scrophulariaceae)', 'Rhizome (dried), with roots', 'Bitter (intense; tikta rasa) with a pungent post-digestive vipaka (katu)', 'Cold', 'Dry', 'Torpor and congestion of the liver and digestion (the sluggish, damp, bilious state), damp-heat, excess heat, and the heat of chronic and acute febrile infection. The intense cold bitterness stimulates a torpid hepatobiliary system while draining damp-heat.', 'Cold, dryness, deficiency, and exhaustion. Its cold, dry bitterness worsens cold-deficient digestion (spleen and stomach yang deficiency), Vata dryness, and depleted, wasted states.', 'Hepatic (liver and biliary), Digestive, Immune, Integumentary (skin), and Respiratory.', 'Jaundice and viral or cholestatic hepatitis, sluggish liver with bile stagnation, chronic and intermittent fevers, low digestive fire and dyspepsia, constipation (at higher, purgative doses), damp-heat skin conditions, and immune weakness with frequent infection.', 'Hot-Damp-Stagnant: the congested, bilious, plethoric liver phenotype (choleric and robust Pitta-like constitutions carrying damp-heat). It aggravates thin, cold, dry, depleted (Vata-like) and deficient, pale constitutions.', 'Pitta, Kapha', 'Vata', 'Damp-Heat (hepatobiliary and lower burner, e.g. jaundice and damp-heat dysentery), Heat and Fire excess, and Yin-deficient empty heat with steaming-bone fever and night sweats. As Hu Huang Lian it also clears the heat of childhood nutritional impairment (gan).', 'Spleen and Stomach deficiency cold, Kidney and Spleen Yang deficiency, and Qi deficiency without heat; the bitter-cold nature injures digestive fire.', 'Intensely bitter and cold. Overdose or prolonged use can cause nausea, vomiting, loose or purgative stools, abdominal cramping, appetite loss, rash, and itching. Its cold dryness aggravates Vata and, over time, injures digestive fire (spleen and stomach yang). Because it stimulates immune activity, use caution in autoimmune conditions. It can lower blood glucose, and higher doses act as a cathartic.', 'Avoid in cold-deficient digestion (spleen and stomach yang deficiency) and chronic cold-type diarrhea, in dehydration, and in known hypersensitivity to the Plantaginaceae. Avoid in autoimmune disease (immunostimulant). Use cautiously and with monitoring in diabetes (additive hypoglycemia). Avoid in pregnancy; avoid or use only under supervision in lactation and in young children. Discontinue at least two weeks before surgery.', 'Avoid. Reliable human safety data are lacking, and as a strong bitter with purgative action at higher doses it is advised against in pregnancy by modern references (Natural Medicines/NMCD, WebMD) and by classical TCM cautions for Hu Huang Lian. (Modern-sourced; insufficient data, avoid.)', 'Insufficient reliable data. Classical Ayurveda places Katuka among stanya-shodhana (milk-cleansing) herbs at low dose, but no modern lactation safety data exist and general references advise avoidance, so use only under qualified supervision, and preferably not in the early postpartum. See flags: guidance is conflicting.', 'Traditionally used in small, carefully measured doses for pediatric fevers and indigestion, and in TCM (Hu Huang Lian) for childhood nutritional impairment with heat. However it is a potent bitter purgative with no modern pediatric safety studies, so give only under qualified supervision at low doses; avoid in infants and avoid self-administration. (Modern data insufficient.)', 'Immunosuppressants (ciclosporin, tacrolimus, corticosteroids): Kutki is immunostimulant and may reduce their effectiveness, so avoid combining. Antidiabetic drugs (insulin, sulfonylureas, metformin): additive blood-sugar lowering, monitor glucose. Narrow-therapeutic-index drugs cleared by the liver: theoretical alteration via hepatic and possible CYP450 activity, monitor. Anticoagulant or antiplatelet drugs: theoretical additive effect, evidence limited. Discontinue at least two weeks before surgery. (Sources: Natural Medicines/NMCD, WebMD Picrorhiza monograph.)', 'Powdered rhizome (churna) taken with warm water or honey; decoction of the coarse rhizome; tincture; and standardized picroliv/kutkin extract in capsules. Because the taste is extreme, it is usually combined with other herbs (as in the classical Ayurvedic formula Arogyavardhini vati) or delivered in capsule or honey.', 'Powder (churna): 0.5 to 1 g up to twice daily as a hepatic bitter; 2 to 4 g as a single purgative dose. Decoction: 3 to 6 g dried rhizome. Tincture (1:5, 45 percent): 1 to 3 mL up to three times daily. Standardized picroliv/kutkin extract: 200 to 400 mg daily in divided doses. Take before meals to prime bile flow. Vitiligo research used 200 mg rhizome powder twice daily alongside topical methoxsalen.', 'The Ayurvedic Pharmacopoeia of India, Part I - Katuka (Picrorhiza kurroa Royle ex Benth., dried rhizome), Government of India, Ministry of AYUSH. Classical anchors: Bhavaprakasha Nighantu (Katuka/Katuki) and Charaka Samhita, where Katuka is placed in the Bhedaniya, Lekhaniya, Stanyashodhana, and Tikta-skandha groups.', 'Mills S & Bone K, Principles and Practice of Phytotherapy; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Hu Huang Lian, Picrorhiza scrophulariiflora); Williamson EM, Major Herbs of Ayurveda; Natural Medicines / WebMD Picrorhiza monograph (safety and interactions); Sultan et al., comprehensive pharmacological review, PMC9738980 (2022).', 'Key constituents: iridoid glycosides kutkin/kutkoside and picrosides I, II and III (together standardized as ''picroliv''), plus the phenolics apocynin and androsin, vanillic and caffeic acids, and cucurbitacin glycosides. Picroliv underlies the flagship hepatoprotective and choleretic activity; the herb is also antioxidant, anti-inflammatory, and immunomodulatory. Family reclassified from Scrophulariaceae to Plantaginaceae (APG). In Chinese medicine the source of Hu Huang Lian is the closely related, formerly conspecific Picrorhiza scrophulariiflora. Modern clinical signals: possibly effective for vitiligo combined with topical methoxsalen; early positive data for acute viral hepatitis; controlled asthma trials were negative. Bounding cautions: strongly purgative at higher doses, immunostimulant (avoid in autoimmune disease), hypoglycemic, and conservation-critical, so cultivated sourcing only.', 'Not found in canonical biblical texts. Kutki is native to the alpine Himalaya (Kashmir and Ladakh east to Sikkim, and Nepal, roughly 3000 to 4800 m). It is a classical tikta (bitter) of Ayurveda named in the Charaka Samhita and Bhavaprakasha Nighantu, and, as Hu Huang Lian (from the closely related Picrorhiza scrophulariiflora), a long-standing bitter-cold herb of Chinese medicine.', 'At-risk. Picrorhiza kurroa is IUCN-listed as endangered and is on CITES Appendix II, its wild Himalayan stands severely depleted by unregulated over-collection for the herb trade. Purchase only certified cultivated or verifiably sustainably propagated (farmed or tissue-cultured) rhizome, never wild-harvested, and consider substituting other bitters such as gentian or andrographis where clinically appropriate. (United Plant Savers is a North American registry and does not list this Asian species; the governing flags are IUCN, CITES Appendix II, and India''s National Medicinal Plants Board.)', 'Cold, dry, and fiercely bitter: the Himalayan liver-scouring bitter that drains damp-heat, opens the flow of bile, and cools chronic and febrile heat.', 'Refer promptly for deepening jaundice, dark urine with pale stools, right-upper-quadrant pain, high or persistent fever, easy bruising or bleeding, drowsiness or confusion (possible acute or fulminant hepatitis), suspected gallstone or biliary obstruction, or any liver disease in pregnancy. Kutki supports but does not replace medical evaluation and management of liver disease.', 'Kutki: KOOT-kee. Katuka: kah-TOO-kah. Picrorhiza kurroa: pik-roh-RYE-zuh KOO-roh-uh.', 'seed', 'Approved', '{"title": "The Ayurvedic Pharmacopoeia of India, Part I - Katuka (Picrorhiza kurroa Royle ex Benth., dried rhizome), Government of India, Ministry of AYUSH. Classical anchors: Bhavaprakasha Nighantu (Katuka/Katuki) and Charaka Samhita, where Katuka is", "locator": "The Ayurvedic Pharmacopoeia of India, Part I - Katuka (Picrorhiza kurroa Royle ex Benth., dried rhizome), Government of India, Ministry of AYUSH. Classical anchors: Bhavaprakasha Nighantu (Katuka/Katuki) and Charaka Samhita, where Katuka is", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Mills S & Bone K, Principles and Practice of Phytotherapy; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Hu Huang Lian, Picrorhiza scrophulariiflora); Williamson EM, Major Herbs of Ayurveda; Natural Medicines / WebMD Pic", "locator": "Mills S & Bone K, Principles and Practice of Phytotherapy; Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Hu Huang Lian, Picrorhiza scrophulariiflora); Williamson EM, Major Herbs of Ayurveda; Natural Medicines / WebMD Pic", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
