INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1457', 'H289', 'pregnancy', 'Pregnancy', 'moderate', 'Strong bitter with purgative/cathartic action at higher doses and no reliable human reproductive safety data; TCM cautions Hu Huang Lian in pregnancy.', 'Avoid throughout pregnancy.', 'Natural Medicines/NMCD; WebMD Picrorhiza monograph; Bensky & Gamble Materia Medica (Hu Huang Lian).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1458', 'H289', 'breastfeeding', 'Breastfeeding', 'moderate', 'No modern lactation safety data; potent bitter purgative. Classical Ayurveda cites low-dose stanya-shodhana use, but this is not validated for safety.', 'Avoid, or use only under qualified professional supervision; avoid in early postpartum.', 'Natural Medicines/NMCD; conflicting classical Ayurvedic guidance (see flags).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1459', 'H289', 'drug_interaction', 'Immunosuppressants (ciclosporin, tacrolimus, corticosteroids)', 'moderate', 'Immunostimulant activity may increase immune function and antagonize the drug effect.', 'Avoid concurrent use; monitor closely if unavoidable.', 'Natural Medicines/NMCD; WebMD Picrorhiza monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1460', 'H289', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin)', 'moderate', 'Additive hypoglycemic effect; may lower blood glucose excessively.', 'Monitor blood glucose and adjust medication with a clinician.', 'Natural Medicines/NMCD; WebMD Picrorhiza monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1461', 'H289', 'condition', 'Autoimmune disease (lupus, multiple sclerosis, rheumatoid arthritis)', 'moderate', 'May increase immune activity and worsen autoimmune symptoms.', 'Avoid unless supervised by a clinician.', 'WebMD/Natural Medicines Picrorhiza monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1462', 'H289', 'condition', 'Spleen/Stomach deficiency cold (chronic cold-type diarrhea)', 'moderate', 'Bitter, cold, drying nature injures digestive fire and can worsen cold-deficient digestion.', 'Avoid, or pair with warming carminatives/digestives and keep courses short.', 'Bensky, Clavey & Stoger, Chinese Herbal Medicine: Materia Medica (Hu Huang Lian).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1463', 'H289', 'other', 'Surgery', 'low', 'Hypoglycemic effect may interfere with perioperative blood-sugar control.', 'Discontinue at least two weeks before scheduled surgery.', 'WebMD/Natural Medicines Picrorhiza monograph.');
