INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H290', 'TCM02', 'Secondary', 'Qi deficiency: supports upright qi and vitality in depletion and convalescence.', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), within the classical Chinese materia medica tradition of tonic and ''zhi'' mushrooms; maitake (hui shu hua, ''grey tree flower'') is used as a spleen and stomach tonic said also ", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), within the classical Chinese materia medica tradition of tonic and ''zhi'' mushrooms; maitake (hui shu hua, ''grey tree flower'') is used as a spleen and stomach tonic said also ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Memorial Sloan Kettering Cancer Center, About Herbs, ''Maitake'' (mskcc.org); Ulbricht C et al., Maitake mushroom (Grifola frondosa): systematic review by the Natural Standard Research Collaboration (PMID 19476741; Drugs.com monograph); Herba", "locator": "Memorial Sloan Kettering Cancer Center, About Herbs, ''Maitake'' (mskcc.org); Ulbricht C et al., Maitake mushroom (Grifola frondosa): systematic review by the Natural Standard Research Collaboration (PMID 19476741; Drugs.com monograph); Herba", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
