INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H290', 'TCM13', 'Minor', 'Wind-Cold (acute exterior invasion): hold a rich, building tonic until the surface pattern is cleared.', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), within the classical Chinese materia medica tradition of tonic and ''zhi'' mushrooms; maitake (hui shu hua, ''grey tree flower'') is used as a spleen and stomach tonic said also ", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), within the classical Chinese materia medica tradition of tonic and ''zhi'' mushrooms; maitake (hui shu hua, ''grey tree flower'') is used as a spleen and stomach tonic said also ", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Memorial Sloan Kettering Cancer Center, About Herbs, ''Maitake'' (mskcc.org); Ulbricht C et al., Maitake mushroom (Grifola frondosa): systematic review by the Natural Standard Research Collaboration (PMID 19476741; Drugs.com monograph); Herba", "locator": "Memorial Sloan Kettering Cancer Center, About Herbs, ''Maitake'' (mskcc.org); Ulbricht C et al., Maitake mushroom (Grifola frondosa): systematic review by the Natural Standard Research Collaboration (PMID 19476741; Drugs.com monograph); Herba", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1464', 'H290', 'pregnancy', 'Pregnancy (therapeutic/extract doses)', 'moderate', 'No reliable human safety data for maitake or its D-fraction extracts in pregnancy; safety information is lacking.', 'Avoid concentrated medicinal and D-fraction doses in pregnancy unless supervised by a qualified practitioner; occasional culinary use of the whole mushroom is a food-level exposure.', 'MSKCC About Herbs (Maitake); Ulbricht et al., Natural Standard systematic review of Grifola frondosa (PMID 19476741; Drugs.com); RxList/WebMD.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1465', 'H290', 'breastfeeding', 'Breastfeeding (therapeutic/extract doses)', 'moderate', 'Unknown whether constituents pass into breast milk; no reliable human safety data during lactation.', 'Avoid concentrated extracts while nursing without professional guidance; culinary mushroom use is lower concern.', 'MSKCC About Herbs (Maitake); Natural Standard systematic review (Drugs.com, PMID 19476741).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1466', 'H290', 'drug_interaction', 'Warfarin and other anticoagulants/antiplatelets', 'moderate', 'A case report describes maitake raising the INR in a patient on warfarin, potentially increasing bleeding risk.', 'Monitor INR and bleeding signs if combined; coordinate dose changes with the prescriber.', 'Memorial Sloan Kettering About Herbs (Maitake).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1467', 'H290', 'drug_interaction', 'Antidiabetic drugs (insulin, sulfonylureas, metformin and other oral hypoglycemics)', 'moderate', 'Maitake lowers blood glucose and can add to the effect of hypoglycemic drugs, with additive risk of hypoglycemia (documented in type-2 diabetic patients).', 'Monitor blood glucose and adjust antidiabetic therapy with the prescriber; watch for hypoglycemia.', 'Memorial Sloan Kettering About Herbs (Maitake); Natural Standard systematic review (Drugs.com, PMID 19476741).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1468', 'H290', 'drug_interaction', 'Antihypertensive medications', 'low', 'Maitake can lower blood pressure, giving a theoretical additive risk of hypotension.', 'Monitor blood pressure if combining; adjust antihypertensive therapy with the prescriber as needed.', 'Mechanistic (blood-pressure-lowering action); MSKCC About Herbs (purported hypertension use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1469', 'H290', 'drug_interaction', 'Immunosuppressant medications (transplant drugs, e.g. cyclosporine, tacrolimus; autoimmune immunosuppressants)', 'moderate', 'As an immunostimulating, immunomodulating beta-glucan it could theoretically oppose the intended action of immunosuppressive therapy.', 'Use only under medical supervision in transplant recipients and others on immunosuppressants; start low and monitor.', 'Mechanistic (immunostimulant beta-glucan); MSKCC About Herbs (immune-activating action).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1470', 'H290', 'other', 'Mushroom/fungal allergy', 'moderate', 'As a fungus, maitake can provoke hypersensitivity reactions in the mushroom-sensitive.', 'Avoid in those with known mushroom allergy; discontinue if allergic symptoms occur.', 'MSKCC About Herbs (Maitake); AHPA Botanical Safety Handbook (2nd ed.).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1471', 'H290', 'condition', 'Active autoimmune disease in flare', 'moderate', 'Immune-activating action may add fuel during an active autoimmune flare.', 'Use cautiously and under practitioner guidance in autoimmune disease; work at low initial doses.', 'Mechanistic (immunostimulant); consistent with immunomodulating-mushroom safety practice.');
