INSERT INTO public.herbs_constitutions (herb_id, constitution_id, relationship, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H291', 'C02', 'Aggravates', 'Primary', 'Hot, choleric, Pitta-like type overheated and irritated by a warm pungent.', '{"title": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "locator": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "locator": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
