INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H291', 'TCM11', 'Primary', 'Warm, acrid nature aggravates Heat and Fire patterns.', '{"title": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "locator": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "locator": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H291', 'TCM07', 'Secondary', 'Drying, warming action injures fluids and worsens Yin deficiency with heat.', '{"title": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "locator": "Grieve M. A Modern Herbal (1931), Onion; and Felter HW, Lloyd JU. King''s American Dispensatory (18th ed., 1898), Allium Cepa (Onion).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "locator": "Blumenthal M et al. (eds), The Complete German Commission E Monographs (1998), Allii cepae bulbus; World Health Organization, WHO Monographs on Selected Medicinal Plants Vol. 1 (1999), Bulbus Allii Cepae; AHPA Botanical Safety Handbook (2nd", "source_id": "S11", "author": "Commission E Monographs", "year": "1998", "url": "https://www.herbalgram.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1472', 'H291', 'pregnancy', 'Pregnancy (concentrated medicinal or high-dose extracts)', 'low', 'Onion as a food has a long safe dietary record in pregnancy, but concentrated medicinal or supplemental doses are not well studied.', 'Culinary amounts are considered safe; avoid concentrated extracts or use only with professional guidance.', 'e-lactancia.org (Allium cepa); AHPA Botanical Safety Handbook (2nd ed., 2013); NCCIH.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1473', 'H291', 'breastfeeding', 'Breastfeeding', 'low', 'Compatible in dietary amounts; some constituents (e.g. quercetin) pass into milk, but food-level intake is low or no risk, and the belief that onion causes infant colic is not supported.', 'Eat freely as food; keep concentrated medicinal doses for professional guidance.', 'e-lactancia.org (Allium cepa, rated safe/preferred); AHPA Botanical Safety Handbook (2nd ed., 2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1474', 'H291', 'drug_interaction', 'Antiplatelet and anticoagulant drugs (warfarin, aspirin, clopidogrel)', 'moderate', 'Onion has a mild antiplatelet and fibrinolytic effect; concentrated or high-dose preparations may add to bleeding risk.', 'Ordinary food amounts are low risk; avoid concentrated extracts around surgery or alongside anticoagulation without clinician oversight.', 'Brinker, Herb Contraindications and Drug Interactions (4th ed., 2010); AHPA Botanical Safety Handbook (2nd ed., 2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1475', 'H291', 'drug_interaction', 'Antidiabetic drugs and insulin', 'moderate', 'Onion can lower blood glucose, giving a potential additive hypoglycemic effect with glucose-lowering medicines.', 'Monitor blood glucose if using concentrated onion preparations with antidiabetic medication.', 'Mills & Bone, Principles and Practice of Phytotherapy (2nd ed., 2013); Commission E, Allii cepae bulbus.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1476', 'H291', 'drug_interaction', 'Lithium', 'low', 'As a diuretic-acting food-herb, high intake could theoretically reduce lithium clearance and raise serum lithium.', 'Theoretical; keep to food amounts and monitor if on lithium.', 'Brinker, Herb Contraindications and Drug Interactions (4th ed., 2010).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1477', 'H291', 'condition', 'Gastroesophageal reflux, gastritis, hiatal hernia, peptic ulcer', 'moderate', 'Raw onion notoriously provokes heartburn, reflux, and gastric irritation; the fructan fraction adds gas and bloating.', 'Prefer cooked onion, reduce or avoid raw onion in reflux and irritable-bowel patterns.', 'King''s American Dispensatory (1898), Allium Cepa; AHPA Botanical Safety Handbook (2nd ed., 2013).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1478', 'H291', 'other', 'Allium and Amaryllidaceae allergy (onion, garlic, leek, chive); occupational contact dermatitis', 'moderate', 'Cross-reactive allergy within the Allium group can cause ingestion reactions; handling cut onion can cause contact dermatitis.', 'Avoid with known Allium allergy; discontinue topical use if rash, itching, or burning appears.', 'AHPA Botanical Safety Handbook (2nd ed., 2013).');
