INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1479', 'H292', 'pregnancy', 'Pregnancy (oral use)', 'absolute', 'Cytotoxic and emetic; documented reproductive toxicity in animal models. Rated likely unsafe taken by mouth.', 'Do not use internally during pregnancy.', 'RxList/WebMD - Quassia; Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1480', 'H292', 'breastfeeding', 'Breastfeeding (oral use)', 'absolute', 'Cytotoxic potential and insufficient safety data; rated likely unsafe orally.', 'Avoid internal use while breastfeeding.', 'RxList/WebMD - Quassia; Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1481', 'H292', 'drug_interaction', 'Digoxin / cardiac glycosides', 'moderate', 'Potential potassium depletion (stimulant-laxative effect) plus quassin cardiotoxicity, increasing glycoside toxicity risk.', 'Avoid concurrent use; if unavoidable, monitor potassium and glycoside levels under a physician.', 'RxList/WebMD - Quassia; Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1482', 'H292', 'drug_interaction', 'Potassium-depleting diuretics', 'moderate', 'Additive hypokalemia.', 'Avoid prolonged concurrent use; monitor potassium.', 'RxList/WebMD - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1483', 'H292', 'drug_interaction', 'Antacids, proton pump inhibitors, H2 blockers', 'low', 'Quassia increases gastric acid secretion and may oppose acid-suppressing therapy.', 'Separate dosing and monitor symptom control.', 'RxList/WebMD - Quassia; Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1484', 'H292', 'drug_interaction', 'Anticoagulant / antiarrhythmic regimens', 'moderate', 'Excessive use may interfere with existing cardiac and anticoagulant regimens.', 'Avoid prolonged or high dosing; consult the prescribing physician.', 'Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1485', 'H292', 'condition', 'Peptic ulcer disease / gastritis / GERD', 'moderate', 'Bitter raises gastric acid and is a mucosal irritant above bitter dose.', 'Avoid in active ulcer, gastritis, or reflux.', 'Drugs.com Natural Products - Quassia; RxList/WebMD - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1486', 'H292', 'condition', 'Cardiac arrhythmia', 'moderate', 'Quassin is cardiotoxic (arrhythmias) at large or parenteral doses.', 'Avoid medicinal doses in arrhythmia; keep to culinary bitter amounts only under guidance.', 'Drugs.com Natural Products - Quassia.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1487', 'H292', 'other', 'Male subfertility / men trying to conceive', 'moderate', 'Reversible antifertility: quassin inhibits Leydig-cell steroidogenesis and lowers testosterone, LH, FSH, and sperm counts in male animals (restored ~8 weeks after withdrawal).', 'Men actively seeking conception should avoid internal use.', 'Njar VCO et al., J Ethnopharmacol 1995 (PMID 7753928); reproductive-toxicity studies of Quassia amara in male rats (Reprod Toxicol).');
