INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H292', 'EP08', 'match', 2, 1, 'temperature: herb cold reinforces the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quassia (Picraena excelsa / Quassia amara).", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) - Quassia (Picraena excelsa / Quassia amara).", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931) - Quassia; Drugs.com Natural Products (Professional) - Quassia; RxList/WebMD - Quassia; Njar VCO et al., quassin inhibition of Leydig-cell steroidogenesis / antifertility (J Ethnopharmacol 1995, PMID 7753928);", "locator": "Grieve, A Modern Herbal (1931) - Quassia; Drugs.com Natural Products (Professional) - Quassia; RxList/WebMD - Quassia; Njar VCO et al., quassin inhibition of Leydig-cell steroidogenesis / antifertility (J Ethnopharmacol 1995, PMID 7753928);", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "pubmed"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H293', 'Rhatany', 'Krameria triandra', 'Krameriaceae (older texts place it in Polygalaceae/Polygaleae)', 'Root, especially the root bark', 'Astringent, Bitter', 'Cool', 'Dry', 'Laxity, dampness, and ulceration: relaxed, atonic, weeping or passively bleeding tissue. Spongy and bleeding gums, chronic damp diarrhea and dysentery, leucorrhea, prolapse, fissures, and passive hemorrhage.', 'Dryness, atrophy, and constriction: thin, wasted, dry or already-tightened mucosa where further astringency withers rather than tones.', 'Digestive tract and its mucous membranes, oral cavity and gums, skin and mucosal surfaces (integumentary), female reproductive tract, urinary tract, and the throat.', 'Chronic diarrhea and dysentery, passive hemorrhage (epistaxis, hematemesis, menorrhagia), spongy and bleeding gums, hemorrhoids and prolapsus ani, anal and nipple fissures, leucorrhea, and relaxed inflamed sore throat.', 'Cold-Damp-Relaxed; the boggy, weeping, still-water phenotype whose tissues have lost tone and leak fluid or blood. It aggravates the thin, cold, dry, depleted (Vata-like) and melancholic constitutions.', 'Kapha, Pitta', 'Vata', 'Damp leakage patterns (damp diarrhea, leucorrhea) and reckless heat-type bleeding with spongy inflamed gums; a restraining, blood-astringing, damp-drying herb.', 'Yin deficiency with dryness, where its drying nature further injures fluids, and unresolved exterior or acute infective patterns (Wind-Cold, early dysentery), where astringing too soon traps the pathogen.', 'Very high tannin content (roughly 10 to 20 percent, and up to about 40 percent in the root bark). Frequent or prolonged internal use can irritate the gastrointestinal lining and impair absorption of iron, minerals, and protein. It rarely causes allergic reactions of the mouth and throat lining. It astringes without any demulcency, so it is unsuited to dry, atrophic tissue. Limit internal use to short courses and topical or oral use to under two weeks.', 'Do not use to suppress acute infective diarrhea or dysentery before the cause is evaluated, since astringing may retain the pathogen and mask serious infection. Avoid in constipation and in dry, atrophic mucous membranes. Discontinue with any hypersensitivity reaction.', 'Insufficient reliable data; avoid internal medicinal doses in pregnancy. Occasional dilute oral-rinse use is likely low risk but is not well studied. Modern references note there is not enough information to establish safety, and high-tannin astringents are traditionally avoided.', 'Insufficient data; avoid internal medicinal use while breastfeeding. Tannins may bind minerals and reduce absorption. Topical and oral-rinse use is likely low risk.', 'No pediatric safety data for internal use; not recommended internally for children. If used as a supervised oral rinse or gargle, ensure it is not swallowed.', 'No well-documented herb-specific clinical interactions (limited data). Based on its very high tannin content, it may bind and reduce the absorption of iron and other mineral supplements, thiamine, and alkaloidal or protein-based drugs taken at the same time. Separate oral administration of rhatany from medications and supplements by at least two hours.', 'Cold or hot infusion of the powdered root (also used as a gargle, mouthwash, or wash), decoction, tincture, fluid extract, powder (in tooth powders and gum applications with myrrh, orris, or chalk), and topical compress.', 'Powdered root 10 to 30 grains (0.6 to 2 g) up to three times daily; tincture (1:5) 1 to 4 fluid drachms (about 2 to 4 mL) up to three times daily; infusion or decoction of 0.5 to 1 g dried root. As a gargle or mouthwash, use a diluted tincture or strong infusion. Limit topical and oral use to under two weeks.', 'King''s American Dispensatory (Felter & Lloyd, 1898) ,  Krameria.', 'Grieve, A Modern Herbal (1931) ,  Rhatany; Cook, The Physio-Medical Dispensatory (1869) ,  Krameria triandra; ESCOP Monographs ,  Ratanhiae radix; Natural Medicines / WebMD Rhatany monograph; Brinker, Herb Contraindications and Drug Interactions.', 'Key constituents are condensed (catechin-type) tannins historically called rhatania- or krameria-tannic acid, along with proanthocyanidins, the lignan-type ratanhiaphenols, and N-methyltyrosine (rhatanin, also called andirin); notably no gallic acid is present. A premier astringent of Eclectic and European practice, valued because cold water readily extracts its virtue. Because it astringes without soothing, it is a short-course corrective for laxity and passive bleeding rather than a daily tonic. Note that commercial Peruvian rhatany traded as K. triandra Ruiz & Pavon is now usually referred to the species Krameria lappacea.', 'Not in canonical biblical texts; native to the Andes of Peru and Bolivia and long used by Andean peoples. It entered European and American materia medica in the early 19th century and became a standard astringent of Eclectic medicine.', 'At risk. Rhatany is a slow-growing Andean hemiparasitic shrub, and the medicinal part is the root, so harvest typically kills the plant. The species in trade (Krameria lappacea, long sold as K. triandra) is considered overexploited and endangered in its Andean deserts, and sustainable wild harvest has rarely been achieved. Prefer cultivated or verified responsibly wild-crafted sources, and consider local astringent substitutes such as oak bark, tormentil, or cranesbill (geranium) to reduce pressure on wild stands.', 'Cool and drying: the master astringent that tightens boggy, weeping, and passively bleeding tissue back into tone.', 'Refer for diarrhea that is bloody, high-fever, severely dehydrating, or lasting beyond two days (especially in children or the elderly); for heavy, bright, or unexplained bleeding such as hematemesis, rectal bleeding, or soaking menorrhagia; and for persistent bleeding or spongy gums, which can signal periodontal disease, a bleeding disorder, scurvy, or blood dyscrasia. Unexplained or persistent bleeding needs medical evaluation, not self-astringing.', 'Rhatany: RAT-uh-nee. Krameria triandra: kruh-MEER-ee-uh try-AN-druh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) ,  Krameria.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) ,  Krameria.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931) ,  Rhatany; Cook, The Physio-Medical Dispensatory (1869) ,  Krameria triandra; ESCOP Monographs ,  Ratanhiae radix; Natural Medicines / WebMD Rhatany monograph; Brinker, Herb Contraindications and Drug Interac", "locator": "Grieve, A Modern Herbal (1931) ,  Rhatany; Cook, The Physio-Medical Dispensatory (1869) ,  Krameria triandra; ESCOP Monographs ,  Ratanhiae radix; Natural Medicines / WebMD Rhatany monograph; Brinker, Herb Contraindications and Drug Interac", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
