INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1488', 'H293', 'pregnancy', 'Internal medicinal use in pregnancy', 'moderate', 'Insufficient safety data; high-tannin astringents are traditionally avoided and tannins may reduce nutrient absorption.', 'Avoid internal medicinal doses in pregnancy. Occasional dilute oral-rinse use is likely low risk but is not well studied.', 'Natural Medicines / WebMD Rhatany monograph; general tannin caution per Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1489', 'H293', 'breastfeeding', 'Internal medicinal use while breastfeeding', 'moderate', 'Insufficient data; tannins may bind minerals and reduce absorption.', 'Avoid internal medicinal use while breastfeeding; topical and oral-rinse use is likely low risk.', 'Natural Medicines / WebMD Rhatany monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1490', 'H293', 'pediatric', 'Internal ingestion by children', 'moderate', 'No pediatric safety data; high tannin content may irritate GI mucosa and impair nutrition.', 'Not recommended internally for children; if used as an oral rinse, supervise to prevent swallowing.', 'Natural Medicines / WebMD Rhatany monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1491', 'H293', 'drug_interaction', 'Iron and mineral supplements, thiamine, alkaloidal or protein-based drugs', 'moderate', 'High tannin content binds and precipitates iron, minerals, and alkaloids, reducing their absorption when co-administered.', 'Separate oral administration of rhatany from medications and supplements by at least two hours.', 'Brinker, Herb Contraindications and Drug Interactions; Mills & Bone, Principles and Practice of Phytotherapy (tannin class effect).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1492', 'H293', 'condition', 'Acute infective diarrhea or dysentery', 'moderate', 'Astringing early may retain the pathogen and toxins and mask a serious infection.', 'Do not use to suppress acute infective diarrhea before evaluation; refer if bloody, febrile, or dehydrating.', 'Mills & Bone, Principles and Practice of Phytotherapy (principles of astringent use).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1493', 'H293', 'other', 'Oral and pharyngeal mucosa', 'low', 'Rare allergic reactions of the mouth and throat lining have been reported.', 'Discontinue at any sign of hypersensitivity; do not use if allergic to rhatany.', 'Natural Medicines / WebMD Rhatany monograph.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1494', 'H293', 'other', 'Prolonged or frequent internal or topical use', 'moderate', 'High tannin content can irritate and injure GI mucosa and impair nutrition with chronic use.', 'Limit internal use to short courses and topical or oral use to under two weeks.', 'Natural Medicines / WebMD Rhatany monograph.');
