INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H294', 'TCM11', 'Minor', 'Rich building tonic; limited use in acute Heat/Fire excess or exterior invasion with an unresolved pathogen', '{"title": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), entry Xiang Xun (\u9999\u8548) / Xiang Gu (shiitake): classical Chinese materia medica, public domain.", "locator": "Li Shizhen, Ben Cao Gang Mu (Compendium of Materia Medica, 1596), entry Xiang Xun (\u9999\u8548) / Xiang Gu (shiitake): classical Chinese materia medica, public domain.", "source_id": "S09", "author": "Shennong Ben Cao Jing", "year": "c. 200 CE", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey & St\u00f6ger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Christopher Hobbs, Medicinal Mushrooms: An Exploration of Tradition, Healing & Culture (1995); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 201", "locator": "Bensky, Clavey & St\u00f6ger, Chinese Herbal Medicine: Materia Medica, 3rd ed. (2004); Christopher Hobbs, Medicinal Mushrooms: An Exploration of Tradition, Healing & Culture (1995); AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin 201", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/", "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1495', 'H294', 'drug_interaction', 'Autoimmune disease and immunosuppressant therapy (organ transplant; cyclosporine, tacrolimus, mycophenolate, corticosteroids, biologic DMARDs)', 'moderate', 'Shiitake beta-glucan lentinan activates macrophages and NK cells and stimulates immune signaling; theoretically it may aggravate autoimmune activity and oppose the intended action of immunosuppressant drugs.', 'Cooked culinary amounts are generally tolerated. Avoid concentrated immune extracts and purified lentinan in autoimmune disease and in transplant or other immunosuppressed patients except under specialist supervision.', 'Natural Medicines / Drugs.com lentinan monograph; NCCIH; Rupa Health clinical review (2024)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1496', 'H294', 'other', 'Raw or undercooked shiitake, and high-dose raw shiitake powder', 'moderate', 'Lentinan is a thermolabile polysaccharide; ingested raw or lightly cooked it can trigger a direct (non-allergic) toxic reaction, causing shiitake flagellate dermatitis (pruritic, whip-like linear streaks appearing hours to about 5 days later) and GI upset. It is broken down by thorough cooking.', 'Always cook shiitake thoroughly before eating; do not consume raw shiitake or raw powder. The rash is self-limiting and resolves over 1-8 weeks; symptomatic antihistamine or topical steroid if needed.', 'DermNet NZ, shiitake flagellate dermatitis; Mayo Clinic Proceedings (2022); AHPA Botanical Safety Handbook 2nd ed. (2013)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1497', 'H294', 'drug_interaction', 'Anticoagulant and antiplatelet drugs (warfarin, aspirin, clopidogrel)', 'low', 'Shiitake may modestly reduce blood clotting, giving a theoretical additive bleeding risk at concentrated extract doses.', 'Culinary use is unproblematic. Monitor if combining concentrated shiitake extracts with anticoagulant or antiplatelet medication, especially around surgery.', 'Natural Medicines / Drugs.com; Rupa Health clinical review (2024)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1498', 'H294', 'pregnancy', 'Pregnancy and breastfeeding (concentrated extracts and purified lentinan)', 'moderate', 'Cooked food amounts have a long safe dietary history and no adverse effect in an animal reproductive study (PMID 33389872), but human safety data for concentrated extracts and lentinan in pregnancy and lactation are lacking.', 'Limit to thoroughly cooked culinary amounts during pregnancy and breastfeeding; avoid concentrated immune extracts and lentinan unless supervised.', 'AHPA Botanical Safety Handbook 2nd ed. (2013); Nagao et al., Int J Med Mushrooms (PMID 33389872); Natural Medicines');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1499', 'H294', 'other', 'Sustained high-dose extract use', 'low', 'Prolonged high-dose oral shiitake extract has been associated with eosinophilia and, rarely, allergy; occupational spore inhalation can cause respiratory hypersensitivity in growers.', 'Use standardized extracts at label doses; discontinue and reassess if rash, wheezing or blood-count changes occur.', 'Rupa Health clinical review (2024); AHPA Botanical Safety Handbook 2nd ed. (2013)');
