INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H295', 'TCM07', 'Minor', 'Caution in Yin deficiency where marked heat signs are present', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898): Aralia Racemosa (Spikenard), with Aralia Nudicaulis for shared constituents and action; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Aralia racemosa.", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898): Aralia Racemosa (Spikenard), with Aralia Nudicaulis for shared constituents and action; Ellingwood, American Materia Medica, Therapeutics and Pharmacognosy (1919): Aralia racemosa.", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Cook, The Physiomedical Dispensatory (1869): Aralia Racemosa; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013), Araliaceae; Natural Medicines / WebMD-RxList American Spikenard monograph (2024); United Plant Savers At-Risk ", "locator": "Cook, The Physiomedical Dispensatory (1869): Aralia Racemosa; AHPA Botanical Safety Handbook, 2nd ed. (Gardner & McGuffin, 2013), Araliaceae; Natural Medicines / WebMD-RxList American Spikenard monograph (2024); United Plant Savers At-Risk ", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1500', 'H295', 'pregnancy', 'Pregnancy', 'moderate', 'Traditional Eclectic use as an emmenagogue for suppressed menstruation and dysmenorrhea; modern consumer-safety references classify American spikenard as likely unsafe in pregnancy. Reliable human safety data are lacking.', 'Avoid throughout pregnancy.', 'Natural Medicines / WebMD-RxList American Spikenard (2024); Ellingwood, American Materia Medica (1919), documented emmenagogue use.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1501', 'H295', 'breastfeeding', 'Breastfeeding', 'moderate', 'No data on milk transfer or infant safety.', 'Avoid, or use only under professional guidance.', 'Natural Medicines / WebMD-RxList American Spikenard (2024).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1502', 'H295', 'condition', 'Acute hot, febrile pulmonary inflammation (acute bronchitis or pneumonia with high fever, Lung Heat)', 'moderate', 'Warming, stimulating diaphoretic can aggravate acute heat and inflammation; the herb is indicated for cold, atonic, chronic, and early-stage catarrhal states, not acute hot lung conditions.', 'Use in cold, atonic, chronic, and early-stage catarrhal presentations; avoid in acute high-fever hot lung disease.', 'King''s American Dispensatory (1898) energetics; Holmes, The Energetics of Western Herbs (1989).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1503', 'H295', 'other', 'Topical / skin application', 'low', 'The resinous root may irritate sensitive skin on direct application.', 'Patch-test topical preparations and dilute external washes.', 'Natural Medicines / WebMD-RxList American Spikenard (2024).');
