INSERT INTO public.herbs_tcm_indicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H296', 'TCM02', 'Minor', 'Helps the Kidney grasp the Qi; wheezing and dyspnea of Kidney qi that fails to receive the breath.', '{"title": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "locator": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H296', 'TCM07', 'Primary', 'Warm, drying, acrid nature aggravates Yin deficiency with heat and empty fire.', '{"title": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "locator": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H296', 'TCM11', 'Secondary', 'Wrong for interior Heat and Fire patterns and for dryness or constipation.', '{"title": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "locator": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1504', 'H296', 'pregnancy', 'Pregnancy (internal or topical use)', 'absolute', 'Furanocoumarin psoralens are phototoxic and, when activated by UV light, genotoxic and mutagenic; the seed is a documented hepatotoxin and Bakuchi carries a traditional emmenagogue reputation. No adequate human safety data in pregnancy.', 'Avoid entirely in pregnancy, internally and topically.', 'AHPA Botanical Safety Handbook (2nd ed., Psoralea corylifolia); LiverTox (NIH), Psoralen; Psoralea corylifolia toxicology review (PMC9830135).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1505', 'H296', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable human lactation data; excretion of photoactive and hepatotoxic constituents into breast milk is uncharacterized and there is no NIH LactMed clearance.', 'Avoid during breastfeeding without medical supervision.', 'AHPA Botanical Safety Handbook (2nd ed.); NCCIH; Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1506', 'H296', 'condition', 'Pre-existing liver disease or prior drug/herb-induced liver injury', 'absolute', 'The seed and its constituents (bakuchiol, psoralen, 8-methoxypsoralen, bavachin) cause dose- and duration-dependent cholestatic and hepatocellular liver injury, with documented acute and fatal liver failure.', 'Do not use in liver disease; on any internal use limit to short supervised courses, monitor liver function, and stop at once for any sign of hepatotoxicity.', 'Acute liver failure associated with Fructus Psoraleae (BMC Complementary Medicine and Therapies, 2019, PMC6458792); LiverTox (NIH), Psoralen; Five constituents contributed to Psoraleae Fructus hepatotoxicity (Front Pharmacol, 2021).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1507', 'H296', 'other', 'Ultraviolet or sun exposure and other photosensitizing agents', 'moderate', 'Psoralen furanocoumarins intercalate into and cross-link DNA on UV exposure, producing severe phototoxic burns and blistering; effect is additive with other photosensitizers and, misused chronically, raises skin-cancer risk.', 'Use only with graded, timed, shielded light exposure under supervision; never combine with unprotected sun, tanning, or other photosensitizing drugs; a severe reaction has been reported in a child.', 'Mehta et al., Severe phototoxic reaction to Psoralea corylifolia seeds in a child with vitiligo (Contact Dermatitis, 2024); LiverTox (NIH), Psoralen.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1508', 'H296', 'drug_interaction', 'CYP1A2 and CYP3A4 substrates (and hepatotoxic drugs/alcohol)', 'moderate', 'Constituents inhibit CYP1A1/CYP1A2 (bakuchicin) and interact with CYP3A4 (furanocoumarins, as grapefruit does); Psoralea corylifolia altered tofacitinib pharmacokinetics. Additive liver risk with other hepatotoxins and alcohol.', 'Coordinate with a physician or pharmacist before combining with narrow-therapeutic-index CYP1A2 or CYP3A4 substrates; avoid concurrent hepatotoxic drugs and heavy alcohol.', 'Bakuchicin CYP1A inhibition study (PMC4763008); Psoralea corylifolia tofacitinib pharmacokinetic study (PMC11033359); Brinker, Herb Contraindications and Drug Interactions.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1509', 'H296', 'condition', 'Yin-deficiency heat, interior heat/fire, dryness or constipation (TCM)', 'moderate', 'The warm, acrid, drying nature scorches depleted fluids and worsens heat, empty fire, and dry stools.', 'Avoid in yin-deficient heat and dryness; use only for genuinely cold, deficient patterns.', 'Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1510', 'H296', 'population', 'Children', 'moderate', 'Documented severe phototoxic reaction in a child, plus hepatotoxicity and dosing uncertainty.', 'No internal use in children; topical use for vitiligo only under specialist dermatologic supervision.', 'Mehta et al. (Contact Dermatitis, 2024); AHPA Botanical Safety Handbook (2nd ed.); NCCIH.');
INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H296', 'EP01', 'avoid', 0, 3, 'temperature: herb hot reinforces the pattern''s hot; moisture: herb dry reinforces the pattern''s dry; tone: herb tense reinforces the pattern''s tense', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "locator": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
