INSERT INTO public.herbs_eden_patterns (herb_id, pattern_id, relationship, rebalancing_axes, aggravating_axes, rationale, derivation, primary_citation, secondary_citation, surfaced) VALUES ('H296', 'EP08', 'match', 3, 0, 'temperature: herb hot rebalances the pattern''s cold; moisture: herb dry rebalances the pattern''s damp; tone: herb tense rebalances the pattern''s relaxed', 'computed_energetics', '{"title": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "locator": "The Ayurvedic Pharmacopoeia of India (Part I) - Bakuchi (dried ripe fruit of Psoralea corylifolia); classical Ayurvedic use in the Charaka Samhita and Sushruta Samhita for kushtha and shvitra (skin diseases and leukoderma).", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "locator": "Bensky, Clavey and Stoger, Chinese Herbal Medicine: Materia Medica (3rd ed.), Bu Gu Zhi; AHPA Botanical Safety Handbook (2nd ed.); Brinker, Herb Contraindications and Drug Interactions; LiverTox (NIH), Psoralen; Acute liver failure associat", "source_id": "S14", "author": "AHPA Botanical Safety Handbook", "year": "2013", "url": "https://www.ahpa.org/"}'::jsonb, true);
INSERT INTO public.herbs (herb_id, common_name, latin_name, plant_family, part_used, taste, temperature, moisture, tissue_states_indicated, tissue_states_contraindicated, system_affinity, chief_complaints, western_constitution_match, ayurvedic_dosha_match, ayurvedic_dosha_aggravates, tcm_pattern_match, tcm_contraindicated_patterns, cautions, contraindications_general, pregnancy_safety, breastfeeding_safety, children_safety, drug_interactions, preparation_methods, dosage_notes, primary_sources, secondary_sources, notes, biblical_traditional_reference, stewardship_note, energetics_summary, refer_threshold, pronunciation, tier_visibility, status, primary_text_citation, secondary_citation) VALUES ('H297', 'Balmony (Turtlehead)', 'Chelone glabra', 'Plantaginaceae (formerly Scrophulariaceae)', 'Herb (aerial parts), especially the leaves', 'Bitter (intensely); faintly astringent', 'Cool', 'Dry', 'Hepatic and digestive torpor; atonic dyspepsia with laxity of gut tone; biliary stagnation and damp-boggy sluggishness; debility with poor appetite.', 'Dryness and atrophy (a cooling, drying bitter depletes withered tissue); frank cold-deficiency states; severe exhaustion where a purging bitter would drain further.', 'Hepatic and biliary; digestive. Secondarily integumentary (skin, salt-rheum) and lymphatic.', 'Jaundice and sluggish, bile-stagnant liver; atonic dyspepsia; debility with anorexia; intestinal worms; constipation from hepatic torpor; convalescence from fever. Externally: inflamed and irritable ulcers, painful tumors, inflamed breasts, piles, and salt-rheum (eczema).', 'Cold-Damp, torpid, boggy: the sallow, sluggish-liver phenotype with heavy digestion and poor appetite. Phlegmatic with a melancholic, bilious cast.', 'Kapha, Pitta', 'Vata', 'Damp and damp-heat accumulation with Liver/Gallbladder Qi stagnation and bile stasis; the damp-heat jaundice picture.', 'Spleen Qi and Spleen/Kidney Yang deficiency (bitter-cold injures the middle burner); Yin and Blood deficiency with dryness.', 'Intensely bitter; large or repeated doses are purgative and can cause griping, nausea, or watery stools. Being cooling and drying it depletes thin, cold, dry, or exhausted constitutions. Not a first-line self-care herb: the jaundice and hepatic disease it was historically used for are referral conditions today.', 'Avoid in pregnancy and lactation (see safety fields). Contraindicated where bile flow is obstructed (obstructing gallstones, bile-duct stricture, acute cholangitis) because of its cholagogue and choleretic action, and in bowel obstruction or acute inflammatory bowel disease because of its stimulant-laxative action in larger doses.', 'Avoid. No reliable modern safety data (Natural Medicines/WebMD advises avoidance). The flowers were also used traditionally by the Abenaki as an anti-fertility/contraceptive agent, and the herb carries bitter stimulant-laxative and cholagogue actions; the precautionary standard is to avoid during pregnancy.', 'Avoid. No reliable safety data during lactation (Natural Medicines/WebMD advises avoidance); bitter iridoid principles may transfer into milk.', 'Insufficient data; not established for children. Anthelmintic or cathartic-strength dosing risks griping and fluid loss. If used at all, only a low-dose bitter (a few drops of dilute tincture) under a qualified practitioner.', 'No well-documented herb-drug interactions (limited data). Theoretical, class-based cautions: additive effect with stimulant laxatives; the cholagogue action is inappropriate alongside management of biliary obstruction; as a bitter it may alter gastric emptying and theoretically the absorption timing of co-administered oral drugs. Monitor if combined with other laxative or hepatically active agents.', 'Decoction or cold infusion of the dried leaves/herb; tincture of the fresh or recently dried herb; powdered herb; historically ''specific chelone.'' Externally as a poultice, fomentation, or ointment of the leaves for inflamed tumors, irritable ulcers, inflamed breasts, and piles.', 'Tincture (1:5): 2-4 mL up to three times daily, taken before meals as a bitter (historical: 1-2 fluid drachms). Specific chelone: 10-30 drops. Decoction: 1-2 fluid ounces. Dried herb: about 1-2 g as infusion three times daily (historical powder dose 1 drachm). Start low; larger doses are laxative.', 'King''s American Dispensatory (Felter & Lloyd, 1898) ,  Chelone', 'Grieve, A Modern Herbal (1931) ,  Balmony; Natural Medicines / WebMD ingredient monograph ,  Turtlehead (safety); Moerman, Native American Ethnobotany (Iroquois, Cherokee, and Abenaki uses).', 'Chelone glabra is an eastern-North-American wetland perennial, long placed in Scrophulariaceae but now reclassified to Plantaginaceae. Key constituents are the iridoid glycosides aucubin and catalpol, with resin, a bitter glucoside, and gallic acid, which underlie its bitter, hepatoprotective, and mildly anti-inflammatory character. In Eclectic and Physiomedical practice it was a stimulating bitter hepatic and cholagogue for jaundice, torpid liver, atonic dyspepsia, debility with anorexia, and worms, and a topical for irritable ulcers and salt-rheum (hence the folk name ''salt-rheum weed''). Native American use (Iroquois liver / ''too-much-gall'' aid; Cherokee vermifuge, febrifuge, and laxative; Abenaki flower as a contraceptive) frames both its indications and its pregnancy caution. Bounding cautions: intensely bitter and purgative in quantity; avoid in pregnancy and lactation, in biliary obstruction, and in cold-dry-depleted states.', 'Not a canonical biblical plant. Chelone glabra is native to eastern North America and enters herbal medicine through Native American (Iroquois, Cherokee, Abenaki) and 19th-century Eclectic/Physiomedical practice. Its folk name ''bitter herb'' only thematically echoes the bitter herbs (maror) of Passover (Exodus 12:8), with no botanical identity.', 'A native wetland and riparian perennial and a larval host plant for the Baltimore checkerspot butterfly. Not currently listed by United Plant Savers, but sensitive to wetland loss. Wildcraft sparingly and only from healthy stands; harvest aerial leaves rather than uprooting; prefer cultivated or garden-grown material.', 'Cool, dry, and intensely bitter: a hepatic bitter that rouses a torpid, bile-logged liver and rekindles a stalled appetite.', 'Jaundice (yellow skin or eyes), pale stools with dark urine, persistent right-upper-quadrant pain, fever with jaundice, unexplained weight loss, or suspected hepatitis or biliary obstruction require medical evaluation rather than self-treatment. Suspected worm infestation in a child, or persistent vomiting, also warrant referral.', 'Balmony: BAL-moh-nee. Chelone glabra: kee-LOH-nee GLAB-ruh.', 'seed', 'Approved', '{"title": "King''s American Dispensatory (Felter & Lloyd, 1898) ,  Chelone", "locator": "King''s American Dispensatory (Felter & Lloyd, 1898) ,  Chelone", "source_id": "S01", "author": "King''s American Dispensatory", "year": "1898", "url": "https://www.henriettes-herb.com/eclectic/kings/", "kind": "public_domain_text"}'::jsonb, '{"title": "Grieve, A Modern Herbal (1931) ,  Balmony; Natural Medicines / WebMD ingredient monograph ,  Turtlehead (safety); Moerman, Native American Ethnobotany (Iroquois, Cherokee, and Abenaki uses).", "locator": "Grieve, A Modern Herbal (1931) ,  Balmony; Natural Medicines / WebMD ingredient monograph ,  Turtlehead (safety); Moerman, Native American Ethnobotany (Iroquois, Cherokee, and Abenaki uses).", "source_id": "S07", "author": "Grieve \u2014 A Modern Herbal", "year": "1931", "url": "https://www.botanical.com/", "kind": "public_domain_text"}'::jsonb) ON CONFLICT (herb_id) DO UPDATE SET common_name=EXCLUDED.common_name, latin_name=EXCLUDED.latin_name, plant_family=EXCLUDED.plant_family, part_used=EXCLUDED.part_used, taste=EXCLUDED.taste, temperature=EXCLUDED.temperature, moisture=EXCLUDED.moisture, tissue_states_indicated=EXCLUDED.tissue_states_indicated, tissue_states_contraindicated=EXCLUDED.tissue_states_contraindicated, system_affinity=EXCLUDED.system_affinity, chief_complaints=EXCLUDED.chief_complaints, western_constitution_match=EXCLUDED.western_constitution_match, ayurvedic_dosha_match=EXCLUDED.ayurvedic_dosha_match, ayurvedic_dosha_aggravates=EXCLUDED.ayurvedic_dosha_aggravates, tcm_pattern_match=EXCLUDED.tcm_pattern_match, tcm_contraindicated_patterns=EXCLUDED.tcm_contraindicated_patterns, cautions=EXCLUDED.cautions, contraindications_general=EXCLUDED.contraindications_general, pregnancy_safety=EXCLUDED.pregnancy_safety, breastfeeding_safety=EXCLUDED.breastfeeding_safety, children_safety=EXCLUDED.children_safety, drug_interactions=EXCLUDED.drug_interactions, preparation_methods=EXCLUDED.preparation_methods, dosage_notes=EXCLUDED.dosage_notes, primary_sources=EXCLUDED.primary_sources, secondary_sources=EXCLUDED.secondary_sources, notes=EXCLUDED.notes, biblical_traditional_reference=EXCLUDED.biblical_traditional_reference, stewardship_note=EXCLUDED.stewardship_note, energetics_summary=EXCLUDED.energetics_summary, refer_threshold=EXCLUDED.refer_threshold, pronunciation=EXCLUDED.pronunciation, tier_visibility=EXCLUDED.tier_visibility, status=EXCLUDED.status, primary_text_citation=EXCLUDED.primary_text_citation, secondary_citation=EXCLUDED.secondary_citation;
