INSERT INTO public.herbs_tastes (herb_id, taste_id) VALUES ('H297', 'T04');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS19', 'Primary', 'Hepatic and digestive torpor; the atonic, sluggish, boggy liver and gut.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS08', 'Secondary', 'Biliary and portal stagnation; sluggish bile flow.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS09', 'Secondary', 'Laxity/atony of digestive tone; the bitter raises tone.');
INSERT INTO public.herbs_tissue_states_indicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS07', 'Secondary', 'Damp, boggy accumulation with heavy digestion.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS03', 'Primary', 'A cooling, drying bitter aggravates dry tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS02', 'Secondary', 'Depletes atrophied, withered tissue.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS17', 'Secondary', 'Cooling action aggravates frank cold states.');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H297', 'TS04', 'Minor', 'A purging bitter drains the deeply exhausted.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H297', 'SY12', 'Primary', 'Hepatic/biliary: the classic stimulating hepatic bitter and cholagogue.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H297', 'SY08', 'Primary', 'Digestive: atonic dyspepsia, poor appetite, worms.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H297', 'SY10', 'Minor', 'Skin: external use for salt-rheum, irritable ulcers, inflamed breasts.');
INSERT INTO public.herbs_systems (herb_id, system_id, strength_of_indication, notes) VALUES ('H297', 'SY11', 'Minor', 'Alterative/detergent action on sluggish tissue.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A16', 'Primary', 'Intensely bitter tonic; wakes appetite and digestive secretion.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A43', 'Primary', 'Cholagogue; promotes bile flow in jaundice and bilious torpor.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A32', 'Secondary', 'Anthelmintic/vermifuge; historic worm remedy (Cherokee, Eclectic).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A13', 'Secondary', 'Hepatoprotective; iridoid glycosides aucubin/catalpol (modern rationale).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A44', 'Secondary', 'Choleretic; stimulates bile production (antibilious).');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A38', 'Secondary', 'Aperient to cathartic in larger doses; relieves torpid constipation.');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H297', 'A14', 'Secondary', 'Alterative/detergent for salt-rheum and sluggish skin.');
