INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1511', 'H297', 'pregnancy', 'Pregnancy', 'moderate', 'Bitter stimulant-laxative and cholagogue action; documented ethnobotanical use of the flowers as an anti-fertility/contraceptive agent by the Abenaki; no modern safety data.', 'Avoid during pregnancy.', 'Natural Medicines/WebMD (Turtlehead) ,  avoid in pregnancy; Moerman, Native American Ethnobotany (Abenaki contraceptive use)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1512', 'H297', 'breastfeeding', 'Breastfeeding', 'moderate', 'No reliable safety data; bitter iridoid principles may pass into milk.', 'Avoid while breastfeeding.', 'Natural Medicines/WebMD (Turtlehead) ,  avoid while breastfeeding');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1513', 'H297', 'condition', 'Biliary obstruction / obstructing gallstones / acute cholangitis', 'moderate', 'Cholagogue and choleretic action stimulates bile flow, which is hazardous where a stone or stricture obstructs the bile duct.', 'Do not use with known bile-duct obstruction, obstructing gallstones, or acute cholangitis; refer.', 'Class-based clinical caution for cholagogues (Mills & Bone, Principles and Practice of Phytotherapy; Brinker general principle) ,  not Balmony-specific');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1514', 'H297', 'condition', 'Bowel obstruction / acute inflammatory bowel disease', 'moderate', 'Aperient-to-cathartic (stimulant-laxative) action in larger doses is contraindicated in bowel obstruction and acute inflammatory bowel states.', 'Avoid in bowel obstruction or active inflammatory bowel disease.', 'Class-based clinical caution for stimulant laxatives (AHPA Botanical Safety Handbook class principle; Mills & Bone) ,  not Balmony-specific');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1515', 'H297', 'other', 'Infants and young children', 'moderate', 'No pediatric safety data; anthelmintic/cathartic dosing risks griping, dehydration, and electrolyte loss.', 'Avoid concentrated or cathartic dosing in children; only low-dose bitter under a qualified practitioner.', 'Natural Medicines/WebMD (Turtlehead) ,  insufficient data, avoid');
