INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1516', 'H298', 'pregnancy', 'Pregnancy', 'moderate', 'Safety in pregnancy has not been established; no reproductive or developmental toxicity data exist, and resins carry a theoretical uterine-stimulant concern.', 'Avoid medicinal doses, especially internal high-dose use in the first trimester. Culinary and food-level amounts are unlikely to pose concern.', 'EMA/HMPC Assessment report on Pistacia lentiscus L., resina (mastic), EMA/HMPC/46756/2015 (2015)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1517', 'H298', 'breastfeeding', 'Breastfeeding', 'moderate', 'Safety during lactation has not been established; excretion into breast milk is unstudied.', 'Avoid medicinal use while breastfeeding.', 'EMA/HMPC 46756/2015 (2015)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1518', 'H298', 'other', 'Anacardiaceae hypersensitivity (pistachio, cashew, mango, Schinus, poison ivy/oak)', 'absolute', 'Cross-reactive plant-family allergens; allergic contact dermatitis to mastic-containing products has been reported.', 'Contraindicated in known Anacardiaceae or Pistacia/Schinus allergy. Discontinue at any sign of rash, itching, or swelling.', 'EMA/HMPC 46756/2015 (2015); Drugs.com Natural Products (Professional), ''Mastic''; RxList ''Mastic''');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1519', 'H298', 'pediatric', 'Children/adolescents (under 18 internal, under 12 topical)', 'moderate', 'Efficacy and safety of medicinal use in minors have not been established due to lack of data.', 'Avoid medicinal internal use under 18 and topical use under 12. Culinary/food amounts have a long history of use.', 'EMA/HMPC 46756/2015 (2015)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1520', 'H298', 'drug_interaction', 'Antidiabetic and lipid-lowering agents', 'low', 'Long-term mastic intake is associated with mild reductions in serum glucose, total cholesterol, LDL, and liver enzymes; a theoretical additive effect is possible.', 'No clinically documented interaction. Monitor blood glucose and lipids if used alongside these drugs, and separate the adsorptive resin from other oral medications by 2 or more hours.', 'EMA/HMPC 46756/2015 (2015); Drugs.com Natural Products (Professional), ''Mastic''');
