INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H299', 'TS03', 'Secondary', 'Drying and depleting with chronic use');
INSERT INTO public.herbs_tissue_states_contraindicated (herb_id, state_id, strength_of_indication, notes) VALUES ('H299', 'TS02', 'Minor', 'Avoid in wasting and debility');
