INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H299', 'A32', 'Secondary', 'Vermifuge / anthelmintic (King''s, Grieve)');
INSERT INTO public.herbs_actions (herb_id, action_id, strength_of_indication, notes) VALUES ('H299', 'A44', 'Minor', 'Choleretic tendency of the bitter principle');
