INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1521', 'H299', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Anthranoid stimulant laxative and traditional emmenagogue; strong colonic stimulation and pelvic congestion can provoke reflex uterine activity. Judged possibly unsafe orally in pregnancy.', 'Do not use. Choose bulk-forming or osmotic measures for constipation in pregnancy under supervision.', 'NCCIH ''Aloe Vera''; AHPA Botanical Safety Handbook 2nd ed. (2013), leaf-latex class 2b; King''s American Dispensatory (1898)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1522', 'H299', 'breastfeeding', 'Breastfeeding', 'moderate', 'Anthraquinone aglycones (aloe-emodin) are excreted into breast milk and may purge or gripe the infant.', 'Avoid oral aloe latex while nursing; if a stimulant laxative is unavoidable use the lowest effective dose short-term and monitor the infant for loose stools.', 'AHPA Botanical Safety Handbook 2nd ed. (2013); NCCIH; King''s American Dispensatory (1898)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1523', 'H299', 'other', 'Children under 12 years', 'absolute', 'Oral aloe latex causes cramping, diarrhea, and fluid/electrolyte loss; stimulant laxatives are inappropriate for pediatric constipation.', 'Do not give to children under 12. Refer pediatric constipation for age-appropriate management.', 'WebMD / Natural Medicines; NCCIH');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1524', 'H299', 'condition', 'Intestinal obstruction, acute inflammatory bowel disease, appendicitis, or undiagnosed abdominal pain', 'absolute', 'An irritant stimulant purgative aggravates an inflamed, obstructed, or acutely painful bowel and can precipitate serious harm.', 'Contraindicated. Rule out these conditions before use; refer acute abdominal pain.', 'German Commission E Monograph (Aloe); AHPA Botanical Safety Handbook 2nd ed.; King''s American Dispensatory (1898)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1525', 'H299', 'condition', 'Hemorrhoids and anal fissures', 'moderate', 'Aloes increases pelvic and rectal vascular congestion and is classically noted to induce or worsen piles.', 'Avoid in active hemorrhoids; use only minimal doses if unavoidable and combine with a carminative.', 'Grieve''s A Modern Herbal (1931); King''s American Dispensatory (1898)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1526', 'H299', 'drug_interaction', 'Digoxin and cardiac glycosides', 'moderate', 'Laxative-induced potassium loss increases myocardial sensitivity to cardiac glycosides, raising the risk of toxicity and arrhythmia.', 'Avoid concurrent use; if a laxative is needed, choose a non-stimulant option and monitor serum potassium.', 'NCCIH; German Commission E Monograph; Brinker, Herbal Contraindications and Drug Interactions 4th ed. (2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1527', 'H299', 'drug_interaction', 'Potassium-depleting drugs: thiazide and loop diuretics, corticosteroids, and licorice', 'moderate', 'Additive potassium depletion can produce hypokalemia, especially with chronic laxative use.', 'Avoid combined or prolonged use; monitor electrolytes if short-term use is necessary.', 'German Commission E Monograph; Brinker, Herbal Contraindications and Drug Interactions 4th ed. (2010)');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1528', 'H299', 'drug_interaction', 'Warfarin and other anticoagulants', 'low', 'Purgative diarrhea can enhance the anticoagulant effect and increase bleeding risk.', 'Avoid stimulant laxatives in anticoagulated patients; monitor INR if used.', 'WebMD / Natural Medicines');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1529', 'H299', 'condition', 'Chronic or habitual use', 'moderate', 'Prolonged anthranoid use causes laxative dependency, loss of colonic tone, hypokalemia, and melanosis coli; non-decolorized whole-leaf aloe is an IARC Group 2B possible carcinogen.', 'Limit to short courses (1 to 2 weeks). Prefer low-aloin, decolorized preparations. Do not use as a daily laxative.', 'German Commission E Monograph; IARC Monographs Vol. 108; NCCIH (FDA 2002 OTC removal)');
