INSERT INTO public.herbs_tcm_contraindicated (herb_id, pattern_id, strength_of_indication, notes, primary_citation, secondary_citation, provenance, surfaced) VALUES ('H300', 'TCM06', 'Secondary', 'Drying and blood-moving; unsafe in blood deficiency or bleeding', '{"title": "Ayurvedic Pharmacopoeia of India, Part I - Chitraka (Plumbago zeylanica, root). Classical: Charaka Samhita and Bhavaprakasha Nighantu (Haritakyadi varga), Chitraka.", "locator": "Ayurvedic Pharmacopoeia of India, Part I - Chitraka (Plumbago zeylanica, root). Classical: Charaka Samhita and Bhavaprakasha Nighantu (Haritakyadi varga), Chitraka.", "source_id": "S27", "author": "Charaka Samhita", "year": "classical", "url": null, "kind": "public_domain_text"}'::jsonb, '{"title": "IJPSR Phytopharmacological Review of Plumbago zeylanica (constituents, antimicrobial, antifertility, toxicity); Sci Rep 2016 (plumbagin CYP450 inhibition, PMC4916434); Asian Pac J Trop Med 2011 reproductive-toxicity study (PMID 22118035); I", "locator": "IJPSR Phytopharmacological Review of Plumbago zeylanica (constituents, antimicrobial, antifertility, toxicity); Sci Rep 2016 (plumbagin CYP450 inhibition, PMC4916434); Asian Pac J Trop Med 2011 reproductive-toxicity study (PMID 22118035); I", "source_id": "S15", "author": "Mills & Bone \u2014 Principles and Practice of Phytotherapy", "year": "2013", "url": null, "kind": "pubmed"}'::jsonb, 'authored_v2', true);
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1530', 'H300', 'pregnancy', 'Pregnancy (all trimesters)', 'absolute', 'Root is a uterine stimulant and abortifacient; plumbagin and root extracts show dose-dependent anti-implantation and abortifacient activity in animal models, and classical Ayurveda lists it as garbhapatana (abortive).', 'Do not use in any form during pregnancy or when pregnancy is possible. Historically used to induce abortion.', 'Edwin et al., Asian Pac J Trop Med 2011 (PMID 22118035); preimplantation-loss study PMID 1889824; Ayurvedic Pharmacopoeia of India, Part I - Chitraka.');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1531', 'H300', 'breastfeeding', 'Breastfeeding', 'absolute', 'Plumbagin is cytotoxic and an irritant; transfer into milk is uncharacterized and no human lactation data exist.', 'Avoid during breastfeeding.', 'Precautionary per Mills & Bone, Principles and Practice of Phytotherapy (no primary lactation data).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1532', 'H300', 'other', 'Infants and children', 'absolute', 'Caustic irritant constituent with a narrow therapeutic margin and no pediatric safety data.', 'Do not give to infants or young children.', 'Precautionary; IJPSR Phytopharmacological Review (toxicity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1533', 'H300', 'condition', 'Peptic/duodenal ulcer, gastritis, hyperacidity, GERD, IBD', 'absolute', 'Plumbagin is a mucosal irritant and vesicant that inflames and can erode already hot or ulcerated GI tissue and provoke bleeding.', 'Contraindicated in active or history of ulcer and in inflammatory or acid GI disease.', 'IJPSR Phytopharmacological Review; classical Ayurvedic contraindication (Pitta/amlapitta).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1534', 'H300', 'drug_interaction', 'Warfarin and other anticoagulant/antiplatelet drugs', 'moderate', 'Plumbagin inhibits CYP2C9 (raising warfarin levels) and alters the coagulation profile, risking additive bleeding.', 'Avoid concurrent use; if unavoidable, monitor INR and bleeding closely under supervision.', 'Sci Rep 2016 plumbagin CYP450 inhibition (PMC4916434); Plumbago coagulation-profile study (J Ethnopharmacol).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1535', 'H300', 'drug_interaction', 'CYP1A2/2B6/2C9/2D6/2E1/3A4 substrates, incl. narrow-therapeutic-index drugs', 'moderate', 'Plumbagin is a potent mixed inhibitor of these isozymes (Ki below about 2.2 microM), which can raise plasma levels of co-administered substrate drugs.', 'Avoid combining with narrow-index or CYP-dependent medications; separate or supervise.', 'Sci Rep 2016 (PMC4916434).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1536', 'H300', 'drug_interaction', 'Antidiabetic / hypoglycemic drugs', 'moderate', 'Plumbagin has independent hypoglycemic activity that may add to antidiabetic medication and cause hypoglycemia.', 'Monitor blood glucose; adjust medication under supervision.', 'IJPSR Phytopharmacological Review (antidiabetic activity).');
INSERT INTO public.contraindications (contraindication_id, herb_id, type, interacting_entity, severity, mechanism_rationale, clinical_guidance, source_citation) VALUES ('CI1537', 'H300', 'condition', 'Bleeding disorders and menorrhagia', 'moderate', 'Emmenagogue and blood-moving action, plus effects on coagulation, may worsen heavy menstrual or other bleeding.', 'Avoid in bleeding tendencies and heavy or irregular menstrual bleeding.', 'Classical Ayurvedic caution; coagulation-profile study.');
